_ASSET_VERSION = str(int(time.time()))   # cambia en cada arranque → rompe la caché de css/js


@app.context_processor
def inject_globals():
    def has_endpoint(name: str) -> bool:
        # permite: {% if has_endpoint('mi_vista') %} ...
        return name in app.view_functions

    def _artist_photo_src(photo_url=None):
        return photo_url or url_for("static", filename="img/logo.png")

    def artist_avatar(photo_url=None, name="", cls="artist-avatar-inline", artist_id=None):
        # Solo la foto del artista en círculo (sin nombre); para ponerla delante de un nombre ya escrito.
        # Si se pasa artist_id, se marca con data-artist-link para que al pincharla lleve a su ficha
        # (lo enlaza artist_links.js; no cambia el aspecto, solo añade el cursor de mano).
        link = (Markup(' data-artist-link="%s"') % str(artist_id)) if artist_id else Markup("")
        return Markup('<img class="%s"%s src="%s" alt="" title="%s" loading="lazy">') % (
            cls, link, _artist_photo_src(photo_url), (name or ""),
        )

    def artist_chip(name, photo_url=None, artist_id=None):
        # Foto en círculo + nombre en una cápsula (.artist-chip). Devuelve '' si no hay nombre.
        # Con artist_id, la cápsula entera enlaza a la ficha del artista (data-artist-link).
        name = (name or "").strip()
        if not name:
            return Markup("")
        link = (Markup(' data-artist-link="%s"') % str(artist_id)) if artist_id else Markup("")
        return Markup('<span class="artist-chip"%s><img src="%s" alt="" loading="lazy">%s</span>') % (
            link, _artist_photo_src(photo_url), name,
        )

    return dict(
        BRAND_PRIMARY=settings.BRAND_PRIMARY,
        BRAND_ACCENT=settings.BRAND_ACCENT,
        IS_ADMIN=bool(session.get("user_id")),
        has_endpoint=has_endpoint,
        # Versión de ESTÁTICOS (cambia en cada arranque/deploy): rompe la caché del navegador de
        # css/js — sin esto, Flask cachea 12 h y los usuarios no ven los cambios recién subidos.
        ASSET_V=_ASSET_VERSION,
        artist_chip=artist_chip,
        artist_avatar=artist_avatar,
        linked_mini=linked_mini,
        CONCERT_CONTACT_ROLES=CONCERT_CONTACT_ROLES,
        AGENDA_KIND_ORDER=AGENDA_KIND_ORDER,
        AGENDA_KIND_META=AGENDA_KIND_META,
        SIM_EXPENSE_CATEGORIES=SIM_EXPENSE_CATEGORIES,
        SIM_EXPENSE_CATEGORY_LABELS=SIM_EXPENSE_CATEGORY_LABELS,
        SIM_EXPENSE_CATEGORY_ICONS=SIM_EXPENSE_CATEGORY_ICONS,
        SIM_EXPENSE_QTY_CATEGORIES=SIM_EXPENSE_QTY_CATEGORIES,
        ROLE=current_role(),
        ROLE_LABEL=ROLE_LABELS.get(current_role(), str(current_role())),
        CAN_VIEW_ECON=can_view_economics(),
        CAN_EDIT_RADIO=can_edit_radio(),
        CAN_EDIT_SALES=can_edit_sales(),
        CAN_EDIT_CONCERTS=can_edit_concerts(),
        CAN_VIEW_CONCERT_CONTRACTS=can_view_concert_contracts(),
        CAN_EDIT_CATALOGS=can_edit_catalogs(),
        CAN_EDIT_SONGS_PROMOTERS=(can_edit_catalogs() or can_edit_discografica()),
        CAN_EDIT_DISCOGRAFICA=can_edit_discografica(),
        CAN_EDIT_ARTISTS_STATIONS=can_edit_artists_stations(),
        IS_MASTER=is_master()
    )

# ---------- health check ----------
@app.get("/healthz")
def healthz():
    # Health check para Render (Settings → Health Check Path = /healthz): responde AL INSTANTE y
    # SIN tocar la BD. Así el balanceador distingue «instancia viva» de «threads ocupados», reinicia
    # solo instancias realmente colgadas y valida los deploys contra algo fiable (no contra páginas
    # que dependen de la BD).
    #
    # ⚠️ Mientras se está APLICANDO EL ESQUEMA responde 503: Render entonces NO manda tráfico a esta
    # instancia y la gente sigue en la vieja, que funciona. Es lo que hace que subir algo no se note
    # (antes la instancia decía «estoy bien» a los 2 segundos y atendía a medio migrar).
    if not _schema_is_ready():
        return ("aplicando la actualizacion", 503,
                {"Content-Type": "text/plain", "Cache-Control": "no-store", "Retry-After": "10"})
    return ("ok", 200, {"Content-Type": "text/plain", "Cache-Control": "no-store"})


