@app.get("/home", endpoint="home")
def home():
    # Refresco diario automático de Chartmetric (sin configurar nada; no bloquea ni rompe la home).
    _chartmetric_maybe_daily_refresh()
    s = db()
    try:
        try:
            # Sin los espejos de EVENTO (no son artistas de verdad; el asistente los elige aparte).
            artists = s.query(Artist).filter(Artist.event_id.is_(None)).order_by(Artist.name.asc()).all()
        except Exception:
            artists = []
        # Contexto del asistente de concierto para abrirlo IN SITU desde el «+» de la agenda (sin
        # navegar a /conciertos). Best-effort: si falla, la home no se rompe y el «+» cae al redirect.
        try:
            wizard_ctx = _concert_wizard_context(s)
        except Exception:
            wizard_ctx = {}
        wizard_available = bool(wizard_ctx)
        wizard_ctx.pop("artists", None)   # la home ya pasa `artists` (misma lista); evita colisión de kwarg
        # Se renderiza DENTRO de la sesión abierta para que los objetos ORM del wizard sigan válidos.
        return render_template("home.html", artists=artists, wizard_available=wizard_available, **wizard_ctx)
    finally:
        s.close()

# ---------- ARTISTAS ----------
def _active_artist_ids(session_db) -> set:
    """IDs (str) de artistas «en activo»: con canción o álbum de los últimos 6 meses, con
    conciertos / acciones / promociones activos o próximos, o con una GIRA COMPRADA creada y
    aún no terminada (cuenta desde que se crea, aunque no tenga actividades concretas). Se usa
    para filtrar el listado de artistas (por defecto solo activos, con opción de ver inactivos)."""
    today = today_local()
    cutoff = today - timedelta(days=183)
    ids = set()
    try:
        for (aid,) in (
            session_db.query(SongArtist.artist_id)
            .join(Song, Song.id == SongArtist.song_id)
            .filter(or_(Song.release_date >= cutoff, Song.created_at >= cutoff))
            .distinct().all()
        ):
            if aid:
                ids.add(str(aid))
        for (aid,) in (
            session_db.query(Album.artist_id)
            .filter(or_(Album.release_date >= cutoff, Album.created_at >= cutoff))
            .distinct().all()
        ):
            if aid:
                ids.add(str(aid))
        # Conciertos próximos o en curso (artista principal + co-artistas del JSONB).
        for aid, aids in session_db.query(Concert.artist_id, Concert.artist_ids).filter(Concert.date >= today).all():
            if aid:
                ids.add(str(aid))
            for x in (aids or []):
                if x:
                    ids.add(str(x))
        # Acciones no archivadas, en curso/próximas (o aún sin fecha).
        for (aids,) in (
            session_db.query(CompanyAction.artist_ids)
            .filter(
                CompanyAction.archived_at.is_(None),
                or_(CompanyAction.end_date >= today, CompanyAction.start_date >= today, CompanyAction.start_date.is_(None)),
            ).all()
        ):
            for x in (aids or []):
                if x:
                    ids.add(str(x))
        # Promociones/marketing activas.
        for (aids,) in (
            session_db.query(Promotion.artist_ids)
            .filter(
                Promotion.archived_at.is_(None),
                func.upper(func.coalesce(Promotion.status, "")) == "ACTIVE",
                or_(Promotion.ends_on >= today, Promotion.ends_on.is_(None)),
            ).all()
        ):
            for x in (aids or []):
                if x:
                    ids.add(str(x))
        # GIRAS COMPRADAS: tener una gira creada ya cuenta como actividad (aunque aún no tenga
        # conciertos concretos) hasta que la gira TERMINA (fin pasado) o se archiva.
        for aid, aids in (
            session_db.query(PurchasedTour.artist_id, PurchasedTour.artist_ids)
            .filter(
                func.upper(func.coalesce(PurchasedTour.status, "ACTIVA")) == "ACTIVA",
                or_(PurchasedTour.end_date.is_(None), PurchasedTour.end_date >= today),
            ).all()
        ):
            if aid:
                ids.add(str(aid))
            for x in (aids or []):
                if x:
                    ids.add(str(x))
    except Exception:
        # Nunca romper el listado por un fallo al calcular actividad.
        pass
    return ids


@app.route("/artistas", methods=["GET", "POST"])
@admin_required
def artists_view():
    session_db = db()

    # filtros (solo para vista)
    f_artist_ids = request.args.getlist("artist") or []
    f_sale_types = request.args.getlist("type") or []
    f_statuses = request.args.getlist("status") or []

    f_artist_ids = [to_uuid(x) for x in f_artist_ids if (x or "").strip()]
    f_sale_types = [(x or "").strip().upper() for x in f_sale_types if (x or "").strip()]
    f_statuses = [(x or "").strip().upper() for x in f_statuses if (x or "").strip()]

    # sanitizar
    f_sale_types = [x for x in f_sale_types if x in CONCERT_SALE_TYPES_ALL_SET]
    f_statuses = [x for x in f_statuses if x in ("BORRADOR", "HABLADO", "RESERVADO", "CONFIRMADO")]

    if request.method == "POST":
        name = request.form.get("name", "").strip()
        photo = request.files.get("photo")
        try:
            photo_url = upload_png(photo, "artists") if photo else None
            artist = Artist(
                name=name, photo_url=photo_url,  # id lo genera la BD
                is_group=_truthy(request.form.get("is_group")),
                birth_date=parse_optional_date(request.form.get("birth_date")),
            )
            session_db.add(artist)
            session_db.commit()
            flash("Artista creado.", "success")
        except Exception as e:
            session_db.rollback()
            flash(f"Error creando artista: {e}", "danger")
        finally:
            session_db.close()
        return redirect(url_for("artists_view"))
    show_inactive = _truthy(request.args.get("show_inactive"))
    # Los artistas ESPEJO de un evento no son artistas: no salen en esta base de datos.
    all_artists = (session_db.query(Artist).filter(Artist.event_id.is_(None))
                   .order_by(Artist.name.asc()).all())
    active_ids = _active_artist_ids(session_db)
    active_count = sum(1 for a in all_artists if str(a.id) in active_ids)
    inactive_count = len(all_artists) - active_count
    artists = all_artists if show_inactive else [a for a in all_artists if str(a.id) in active_ids]
    session_db.close()
    return render_template(
        "artists.html",
        artists=artists,
        show_inactive=show_inactive,
        active_ids=active_ids,
        active_count=active_count,
        inactive_count=inactive_count,
    )


@app.get("/artistas/<artist_id>", endpoint="artist_detail_view")
@admin_required
def artist_detail_view(artist_id):
    """Ficha de artista (tabs: datos/contratos/conciertos/discográfica...)."""
    session_db = db()
    try:
        artist = session_db.get(Artist, to_uuid(artist_id))
        if not artist:
            flash("Artista no encontrado.", "warning")
            return redirect(url_for("artists_view"))

        tab = (request.args.get("tab") or "datos").strip().lower()
        allowed_tabs = {
            "datos",
            "contratos",
            "conciertos",
            "discografica",
            "agenda",
            "promocion",
            "marketing",
            "onesheet",
            "liquidaciones",
            "vinculaciones",
            "playlisting",
            "fotos",
            "plantilla-gastos",
            "plantillas",
            # Personas del artista: cada una es un TERCERO que forma parte de él, con sus datos
            # personales completos (DNI, pasaporte, carnet, tarjetas, viaje, cuenta bancaria…).
            "personas",
        }
        if tab not in allowed_tabs:
            tab = "datos"

        disc_tab = (request.args.get("disc") or "canciones").strip().lower()
        if disc_tab == "repertorio":
            disc_tab = "canciones"
        if disc_tab not in {"canciones", "albumes"}:
            disc_tab = "canciones"

        # Datos: personas asociadas
        people = (
            session_db.query(ArtistPerson)
            .filter(ArtistPerson.artist_id == artist.id)
            .order_by(ArtistPerson.created_at.asc())
            .all()
        )
        artist_email_addresses = (
            session_db.query(ArtistEmail)
            .filter(ArtistEmail.artist_id == artist.id)
            .order_by(ArtistEmail.created_at.asc(), ArtistEmail.concept.asc())
            .all()
        )

        # Contratos (nivel artista)
        contracts = (
            session_db.query(ArtistContract)
            .options(selectinload(ArtistContract.commitments))
            .filter(ArtistContract.artist_id == artist.id)
            .order_by(ArtistContract.created_at.desc())
            .all()
        )

        # Discográfica: repertorio (canciones y álbumes asociados)
        songs = (
            session_db.query(Song)
            .join(SongArtist, SongArtist.song_id == Song.id)
            .options(selectinload(Song.artists))
            .filter(SongArtist.artist_id == artist.id)
            .order_by(Song.release_date.desc(), Song.title.asc())
            .all()
        )
        _annotate_song_display_fields(session_db, songs, persist=True)
        albums = (
            session_db.query(Album)
            .filter(Album.artist_id == artist.id)
            .order_by(Album.release_date.desc(), Album.title.asc())
            .all()
        )

        contract_commitments_payload = []
        for contract in contracts:
            for commitment in getattr(contract, "commitments", []) or []:
                contract_commitments_payload.append({
                    "id": str(commitment.id),
                    "concept": getattr(commitment, "concept", "") or "",
                    "pct_artist": str(getattr(commitment, "pct_artist", 0) or 0),
                    "pct_office": str(getattr(commitment, "pct_office", 0) or 0),
                    "base": getattr(commitment, "base", None) or "GROSS",
                    "profit_scope": getattr(commitment, "profit_scope", None) or "CONCEPT_ONLY",
                    "material_scope": getattr(commitment, "material_scope", None) or "ALL_MATERIALS",
                })

        # Conciertos del artista (solo lectura) + filtros
        f_statuses_raw = request.args.getlist("status") or []
        f_when_raw = request.args.getlist("when") or []

        f_statuses = [(x or "").strip().upper() for x in f_statuses_raw if (x or "").strip()]
        allowed_statuses = {"BORRADOR", "HABLADO", "RESERVADO", "CONFIRMADO"}
        f_statuses = [x for x in f_statuses if x in allowed_statuses]

        f_when = {(x or "").strip().upper() for x in f_when_raw if (x or "").strip()}
        allowed_when = {"PAST", "FUTURE"}
        f_when = {x for x in f_when if x in allowed_when}
        # Por defecto, mostrar FUTUROS (igual que la pantalla de conciertos)
        if not f_when:
            f_when = {"FUTURE"}

        q = (
            session_db.query(Concert)
            .options(joinedload(Concert.venue))
            .filter(Concert.artist_id == artist.id)
        )

        if f_statuses:
            q = q.filter(Concert.status.in_(f_statuses))

        today = today_local()
        want_past = "PAST" in f_when
        want_future = "FUTURE" in f_when
        if want_past and not want_future:
            q = q.filter(Concert.date < today)
        elif want_future and not want_past:
            q = q.filter(Concert.date >= today)

        concerts = q.order_by(Concert.date.asc()).all()
        # Fuera de Contratación/dirección, las actividades en borrador/habladas NO aparecen en las
        # listas ricas de la ficha (sí en su pestaña Agenda, como «Reserva — consultar con
        # Contratación»); vuelven a verse al pasar a RESERVADO/CONFIRMADO.
        if not _user_sees_unconfirmed_activities():
            concerts = [c for c in concerts if (c.status or "").upper() not in _CONCERT_PRIVATE_STATUSES]

        concerts_sections = {k: [] for k in CONCERTS_SECTION_ORDER}
        for c in concerts:
            concerts_sections.setdefault(c.sale_type or "EMPRESA", []).append(c)
        for k in concerts_sections:
            concerts_sections[k].sort(key=lambda x: (x.date or date.max))

        promotion_requests_display = []
        promotion_entries_display = []
        promo_entity_rows = []
        promo_spend = {"rows": [], "total": 0}
        promotion_source_snapshot = _promotion_request_snapshot_from_source(session_db, "ARTIST", artist.id)
        if tab in {"promocion", "marketing"}:
            promotion_request_rows, promotion_rows = _promotion_rows_for_artist(session_db, artist.id)
            promotion_requests_display = [_promotion_display_request(row) for row in promotion_request_rows]
            promotion_entries_display = [_promotion_display_promotion(row) for row in promotion_rows]
            promo_entity_rows = _promo_rows_for_subject(session_db, "ARTIST", artist.id)
            promo_spend = _promo_spend_rows(session_db, artist_id=artist.id)

        social_links_display = _ordered_social_links(getattr(artist, "social_links", None))
        # Iconos de redes del hero: se toman de las URLs que trae Chartmetric (no manuales).
        _cm_link = session_db.get(ChartmetricArtist, artist.id)
        artist_social_icons = _artist_social_icon_groups(getattr(_cm_link, "social_urls", None))
        onesheet = _onesheet_context(session_db, artist=artist, public=False) if tab == "onesheet" else None
        if tab == "onesheet":
            session_db.commit()

        # Compatibilidad con una versión intermedia que pasaba variables de conciertos
        # a esta plantilla de artista. Se dejan vacías para evitar NameError.
        contracting_general_rows = []
        promoter_email_suggestions = []
        production_panel = {}

        # Agenda: calendario del artista. Carga ~6 meses hacia atrás y ~6 hacia delante para poder
        # navegar por meses (vista de 4 semanas), incluido el pasado, sin recargar; el JS pagina.
        agenda_data = None
        calendar_links = []
        caldav_server = ""
        if tab == "agenda":
            _ag_today = today_local()
            agenda_data = _agenda_build(session_db, [str(artist.id)], _ag_today - timedelta(weeks=26), _ag_today + timedelta(weeks=26), _ag_today,
                                        full_details=_user_sees_unconfirmed_activities())
            # Con el artist_id el JS puede pedir más ventanas (home_agenda_data) y navegar SIN límite.
            agenda_data["artist_id"] = str(artist.id)
            calendar_links = [
                {"id": str(l.id), "label": l.label or "Sin nombre",
                 "page_url": _external_url_for("public_artist_calendar_view", token=l.token),
                 "ics_url": _artist_calendar_subscribe_url(l.token),
                 "kinds_label": _agenda_kinds_label(l.kinds),
                 "kinds_all": not [k for k in (l.kinds or []) if k in AGENDA_KIND_ORDER],
                 "created_by": l.created_by_nick or ""}
                for l in _artist_calendar_links(session_db, artist.id, only_active=True)
            ]
            caldav_server = (os.getenv("EXTERNAL_BASE_URL") or request.url_root).rstrip("/").split("//")[-1]

        artist_fotos_groups = _build_artist_fotos_groups(session_db, artist.id) if tab == "fotos" else None

        # Contexto del asistente de concierto para abrirlo IN SITU desde el «+» de la agenda del
        # artista (sin navegar a /conciertos). Best-effort: si falla, el «+» cae al redirect.
        try:
            _wizctx = _concert_wizard_context(session_db)
        except Exception:
            _wizctx = {}

        return render_template(
            "artist_detail.html",
            artist=artist,
            tab=tab,
            wizard_available=bool(_wizctx),
            # Balance de inversión: solo se calcula en su pestaña (una consulta de más si no).
            artist_investment=(_artist_investment_rows(session_db, artist.id)
                               if tab == "contratos" and "_artist_investment_rows" in globals() else None),
            expense_templates=_expense_templates_for(session_db, "ARTIST", artist.id),
            repertoire_templates=_repertoire_templates_for(session_db, "ARTIST", artist.id),
            templates_owner_type="ARTIST",
            templates_owner_id=str(artist.id),
            # Plantillas de personal / rooming / hoja de ruta del artista (pestaña «Plantillas»).
            **_artist_templates_context(session_db, artist.id),
            agenda_data=agenda_data,
            calendar_links=calendar_links,
            caldav_server=caldav_server,
            artist_fotos_groups=artist_fotos_groups,
            disc_tab=disc_tab,
            people=people,
            # Pestaña «Personas»: cada persona con su ficha de tercero (documentos + viaje + banco).
            person_cards=(_artist_person_cards(session_db, artist, can_edit_artists_stations())
                          if tab == "personas" else []),
            loyalty_brands=PERSON_LOYALTY_BRANDS,
            artist_email_addresses=artist_email_addresses,
            contracts=contracts,
            songs=songs,
            albums=albums,
            default_concepts=ARTIST_CONTRACT_DEFAULT_CONCEPTS,
            contract_commitments_payload=contract_commitments_payload,
            concerts_sections=concerts_sections,
            concerts_order=CONCERTS_SECTION_ORDER,
            concerts_titles=CONCERTS_SECTION_TITLE,
            concerts_total=len(concerts),
            f_statuses=f_statuses,
            f_when=sorted(list(f_when)),
            promotion_requests_display=promotion_requests_display,
            promotion_entries_display=promotion_entries_display,
            promo_entity_rows=promo_entity_rows,
            promo_spend=promo_spend,
            promotion_source_type="ARTIST",
            promotion_source_id=str(artist.id),
            promotion_source_snapshot=promotion_source_snapshot,
            social_links_display=social_links_display,
            social_platforms=SOCIAL_PLATFORMS,
            artist_social_icons=artist_social_icons,
            onesheet=onesheet,
            contracting_general_rows=contracting_general_rows,
            promoter_email_suggestions=promoter_email_suggestions,
            production_panel=production_panel,
            entity_links=_entity_link_rows(session_db, 'artist', artist.id),
            entity_link_context={'type': 'artist', 'id': str(artist.id), 'label': artist.name or 'artista'},
            entity_link_types=APP33_ENTITY_LINK_TYPES,
            entity_links_can_edit=True,
            chartmetric_header=_chartmetric_header_metrics(session_db, artist),
            chartmetric_playlists=(_chartmetric_playlists_grouped(session_db, artist_id=artist.id) if tab == 'playlisting' else None),
            **_wizctx,
        )
    finally:
        session_db.close()

@app.post("/artistas/<artist_id>/update")
@admin_required
def artist_update(artist_id):
    session_db = db()
    a = session_db.get(Artist, to_uuid(artist_id))
    if not a:
        flash("Artista no encontrado.", "warning")
        session_db.close()
        return redirect(safe_next_or(url_for("artists_view")))
    a.name = request.form.get("name", a.name).strip()
    email = (request.form.get("email") or "").strip() or None
    a.email = email
    if "is_international" in request.form:
        a.is_international = _truthy(request.form.get("is_international"))
    if "is_group" in request.form:
        a.is_group = _truthy(request.form.get("is_group"))
    if "birth_date" in request.form:
        a.birth_date = parse_optional_date(request.form.get("birth_date"))
    photo = request.files.get("photo")
    try:
        if photo and photo.filename:
            a.photo_url = upload_png(photo, "artists")
        # Propaga el nuevo email a sus invitaciones aún no enviadas (envío al último dato).
        _invitation_sync_contact_for_entity(session_db, artist_id=a.id, email=a.email)
        session_db.commit()
        flash("Artista actualizado.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error actualizando: {e}", "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(url_for("artists_view")))

