def _resolve_or_create_promoter_for_contract(session_db, nick: str, tax_id: str = '', contact_email: str = '', contact_phone: str = '') -> Promoter:
    nickname = (nick or '').strip()
    promoter = None
    if nickname:
        promoter = (
            session_db.query(Promoter)
            .filter(func.lower(Promoter.nick) == nickname.lower())
            .first()
        )
    if not promoter:
        promoter = Promoter(nick=nickname or 'Beneficiario')
        session_db.add(promoter)
        session_db.flush()
    if nickname:
        promoter.nick = nickname
    if tax_id:
        promoter.tax_id = tax_id
    if contact_email:
        promoter.contact_email = contact_email
    if contact_phone:
        promoter.contact_phone = contact_phone
    session_db.add(promoter)
    return promoter


def _save_contract_royalty_rows(session_db, media_kind: str, item_id, rows_payload: list[dict]):
    media_kind = (media_kind or 'SONG').strip().upper()
    created = []
    for row in rows_payload or []:
        nick = (row.get('nick') or '').strip()
        if not nick:
            continue
        promoter = _resolve_or_create_promoter_for_contract(
            session_db,
            nick=nick,
            tax_id=(row.get('tax_id') or '').strip(),
            contact_email=(row.get('contact_email') or '').strip(),
            contact_phone=(row.get('contact_phone') or '').strip(),
        )
        pct = _parse_pct(row.get('pct'))
        base = _norm_contract_base(row.get('base'))
        profit_scope = _norm_profit_scope(row.get('profit_scope')) if base == 'PROFIT' else None
        if media_kind == 'ALBUM':
            rec = (
                session_db.query(AlbumRoyaltyBeneficiary)
                .filter(AlbumRoyaltyBeneficiary.album_id == item_id)
                .filter(AlbumRoyaltyBeneficiary.promoter_id == promoter.id)
                .first()
            )
            if not rec:
                rec = AlbumRoyaltyBeneficiary(album_id=item_id, promoter_id=promoter.id)
                session_db.add(rec)
        else:
            rec = (
                session_db.query(SongRoyaltyBeneficiary)
                .filter(SongRoyaltyBeneficiary.song_id == item_id)
                .filter(SongRoyaltyBeneficiary.promoter_id == promoter.id)
                .first()
            )
            if not rec:
                rec = SongRoyaltyBeneficiary(song_id=item_id, promoter_id=promoter.id)
                session_db.add(rec)
        rec.promoter_id = promoter.id
        rec.pct = pct
        rec.base = base
        rec.profit_scope = profit_scope
        rec.updated_at = datetime.now(TZ_MADRID)
        session_db.add(rec)
        created.append(rec)
    return created

def _song_material_slot_label(category: str | None, slot_key: str | None, display_name: str | None = None) -> str:
    cat = (category or "").strip().upper()
    slot = (slot_key or "DEFAULT").strip().upper()
    if cat == "COVER":
        if slot == "COVER_PROVISIONAL":
            return "Portada provisional"
        return "Portada"
    if cat == "MASTER":
        if slot == "MASTER_48":
            return "Master 48 bits"
        if slot == "MASTER_24":
            return "Master 24 bits"
        if slot == "MASTER_16":
            return "Master 16 bits"
        return (display_name or "").strip() or "Subproducto"
    if cat == "INSTRUMENTAL":
        if slot == "DEFAULT":
            return "Instrumental"
        return (display_name or "").strip() or "Subproducto"
    if cat == "TV_TRACK":
        if slot == "DEFAULT":
            return "TV Track"
        return (display_name or "").strip() or "Subproducto"
    if cat == "STEMS":
        return (display_name or "").strip() or "Stems"
    return (display_name or "").strip() or "Archivo"


def _download_remote_content(file_url: str, timeout: int = 30) -> tuple[bytes, str | None]:
    target_url = (file_url or "").strip()
    if not target_url:
        raise ValueError("No hay URL de archivo.")
    req = Request(target_url, headers={"User-Agent": "Mozilla/5.0"})
    with urlopen(req, timeout=timeout) as resp:
        data = resp.read()
        guessed = getattr(resp, "headers", {}).get_content_type() if getattr(resp, "headers", None) else None
    return data, guessed


def _safe_zip_member_name(name: str | None, existing: set[str], fallback: str) -> str:
    raw = (name or "").replace("\\", "/").lstrip("/")
    parts = [part for part in raw.split("/") if part not in ("", ".", "..")]
    candidate = "/".join(parts).strip() or fallback
    if candidate not in existing:
        existing.add(candidate)
        return candidate
    stem = Path(candidate).stem or Path(fallback).stem or "archivo"
    suffix = Path(candidate).suffix
    idx = 2
    while True:
        alt = f"{stem}_{idx}{suffix}"
        if alt not in existing:
            existing.add(alt)
            return alt
        idx += 1


def _convert_image_content(data: bytes, target_format: str) -> tuple[bytes, str, str]:
    fmt = (target_format or "").strip().lower()
    if fmt not in {"jpg", "jpeg", "png"}:
        raise ValueError("Formato de imagen no válido.")
    if not PILLOW_AVAILABLE:
        raise RuntimeError("Pillow no está disponible para convertir imágenes.")
    with PILImage.open(BytesIO(data)) as img:
        out = BytesIO()
        if fmt == "png":
            img.save(out, format="PNG")
            return out.getvalue(), "image/png", ".png"
        if img.mode not in ("RGB", "L"):
            if "A" in img.getbands():
                bg = PILImage.new("RGB", img.size, (255, 255, 255))
                bg.paste(img, mask=img.getchannel("A"))
                img = bg
            else:
                img = img.convert("RGB")
        elif img.mode == "L":
            img = img.convert("RGB")
        img.save(out, format="JPEG", quality=95)
        return out.getvalue(), "image/jpeg", ".jpg"


def _convert_audio_content_to_mp3(data: bytes, source_ext: str | None = None) -> tuple[bytes, str, str]:
    if not PYDUB_AVAILABLE:
        raise RuntimeError("pydub no está disponible para convertir audio.")
    fmt = (source_ext or "").lower().lstrip(".") or None
    seg = AudioSegment.from_file(BytesIO(data), format=fmt or None)
    out = BytesIO()
    seg.export(out, format="mp3", bitrate="320k")
    return out.getvalue(), "audio/mpeg", ".mp3"


def _song_material_completion_meta(song: Song, material_rows: list[SongMaterial]) -> dict:
    # Audios obligatorios para considerar la canción "completa":
    #  - MASTER: basta con UNO cualquiera de los formatos (48/24/16); los demás son opcionales.
    #  - INSTRUMENTAL, TV_TRACK y STEMS: obligatorios.
    # (La portada se controla aparte, en cover_principal.)
    basics = {
        "MASTER": False,
        "INSTRUMENTAL": False,
        "TV_TRACK": False,
        "STEMS": False,
    }
    any_non_cover = False
    has_pending = False   # algún material recibido por entrega aún sin validar
    last_cover_at = None
    last_material_at = None
    cover_principal = False   # portada PRINCIPAL (slot COVER); la provisional NO pone el icono en verde
    any_cover_material = False

    for row in material_rows or []:
        category = (getattr(row, "category", None) or "").strip().upper()
        slot = (getattr(row, "slot_key", None) or "DEFAULT").strip().upper()
        dt = getattr(row, "updated_at", None) or getattr(row, "created_at", None)
        if category == "COVER":
            any_cover_material = True
            if slot != "COVER_PROVISIONAL":
                cover_principal = True
            if dt and (last_cover_at is None or dt > last_cover_at):
                last_cover_at = dt
            continue
        any_non_cover = True
        if dt and (last_material_at is None or dt > last_material_at):
            last_material_at = dt
        vstatus = (getattr(row, "validation_status", None) or "VALIDATED").strip().upper()
        if vstatus == "PENDING":
            has_pending = True
            continue
        if category == "MASTER" and slot in ("MASTER_48", "MASTER_24", "MASTER_16"):
            basics["MASTER"] = True
        elif category == "INSTRUMENTAL" and slot == "DEFAULT":
            basics["INSTRUMENTAL"] = True
        elif category == "TV_TRACK" and slot == "DEFAULT":
            basics["TV_TRACK"] = True
        elif category == "STEMS":
            basics["STEMS"] = True

    # Legacy: cover_url sin material COVER asociado → se considera portada principal.
    if not any_cover_material and bool(getattr(song, "cover_url", None)):
        cover_principal = True

    completed_basics = sum(1 for value in basics.values() if value)
    # Mientras haya algún material pendiente de validar, el estado NO puede ser "completo" (queda amarillo).
    if completed_basics == len(basics) and not has_pending:
        state = "complete"
    elif completed_basics > 0 or any_non_cover or has_pending:
        state = "partial"
    else:
        state = "none"

    return {
        "cover_done": cover_principal,
        "last_cover_at": last_cover_at,
        "last_material_at": last_material_at,
        "completed_basics": completed_basics,
        "total_basics": len(basics),
        "state": state,
        "text_class": "text-success" if state == "complete" else ("text-warning" if state == "partial" else "text-danger"),
        "badge_class": "text-bg-success" if state == "complete" else ("text-bg-warning text-dark" if state == "partial" else "text-bg-danger"),
    }


def _ensure_song_cover_material_row(session_db, song: Song | None) -> None:
    if not song or not getattr(song, "id", None):
        return
    cover_url = (getattr(song, "cover_url", None) or "").strip()
    if not cover_url:
        return
    exists = (
        session_db.query(SongMaterial)
        .filter(SongMaterial.song_id == song.id)
        .filter(func.upper(SongMaterial.category) == "COVER")
        .first()
    )
    if exists:
        return
    mime_type = mimetypes.guess_type(cover_url.split("?", 1)[0])[0] or None
    session_db.add(
        SongMaterial(
            song_id=song.id,
            category="COVER",
            slot_key="COVER",
            display_name="Portada",
            file_name="portada",
            file_url=cover_url,
            mime_type=mime_type,
        )
    )
    session_db.flush()


def _resolve_song_cover_url(session_db, song: Song, material_rows: list[SongMaterial] | None = None) -> None:
    """Recalcula Song.cover_url: portada principal (slot COVER) si existe; si no, la provisional."""
    if not song or not getattr(song, "id", None):
        return
    if material_rows is None:
        material_rows = (
            session_db.query(SongMaterial)
            .filter(SongMaterial.song_id == song.id)
            .filter(func.upper(SongMaterial.category) == "COVER")
            .all()
        )
    principal = None
    provisional = None
    for row in material_rows or []:
        if (getattr(row, "category", None) or "").strip().upper() != "COVER":
            continue
        slot = (getattr(row, "slot_key", None) or "COVER").strip().upper()
        if slot == "COVER_PROVISIONAL":
            if provisional is None:
                provisional = row
        elif principal is None:
            principal = row
    chosen = principal or provisional
    if chosen is not None:
        song.cover_url = (getattr(chosen, "file_url", None) or "").strip() or None
    else:
        song.cover_url = None
    session_db.add(song)


def _refresh_song_material_status(session_db, song_or_id, material_rows: list[SongMaterial] | None = None, status_obj: SongStatus | None = None) -> dict:
    song = song_or_id if isinstance(song_or_id, Song) else session_db.get(Song, to_uuid(song_or_id))
    if not song:
        return {"state": "none", "text_class": "text-danger", "badge_class": "text-bg-danger"}
    if material_rows is None:
        material_rows = (
            session_db.query(SongMaterial)
            .filter(SongMaterial.song_id == song.id)
            .order_by(SongMaterial.created_at.asc())
            .all()
        )
    meta = _song_material_completion_meta(song, material_rows)
    st = status_obj or _ensure_song_status_row(session_db, song.id)
    now_dt = datetime.now(TZ_MADRID)
    st.cover_done = bool(meta["cover_done"])
    st.cover_updated_at = meta["last_cover_at"] or (st.cover_updated_at if meta["cover_done"] else None)
    st.materials_done = meta["state"] == "complete"
    st.materials_updated_at = meta["last_material_at"]
    st.updated_at = now_dt
    session_db.add(st)
    return meta


def _album_material_completion_meta(album: Album, material_rows: list[AlbumMaterial]) -> dict:
    required = {
        "DDP": False,
        "BODEGON": False,
    }
    if bool(getattr(album, "physical_cd", False)) or bool(getattr(album, "physical_vinyl", False)):
        required["PHYSICAL_DESIGN"] = False

    any_non_cover = False
    last_cover_at = None
    last_material_at = None
    cover_exists = bool((getattr(album, "cover_url", None) or "").strip())

    for row in material_rows or []:
        category = (getattr(row, "category", None) or "").strip().upper()
        dt = getattr(row, "created_at", None)
        if category == "COVER":
            cover_exists = True
            if dt and (last_cover_at is None or dt > last_cover_at):
                last_cover_at = dt
            continue
        any_non_cover = True
        if dt and (last_material_at is None or dt > last_material_at):
            last_material_at = dt
        if category in required:
            required[category] = True

    completed_required = sum(1 for value in required.values() if value)
    total_required = len(required)
    if total_required and completed_required == total_required:
        state = "complete"
    elif completed_required > 0 or any_non_cover:
        state = "partial"
    else:
        state = "none"

    return {
        "cover_done": cover_exists,
        "last_cover_at": last_cover_at,
        "last_material_at": last_material_at,
        "completed_required": completed_required,
        "total_required": total_required,
        "state": state,
        "text_class": "text-success" if state == "complete" else ("text-warning" if state == "partial" else "text-danger"),
        "badge_class": "text-bg-success" if state == "complete" else ("text-bg-warning text-dark" if state == "partial" else "text-bg-danger"),
    }


def _ensure_album_status_row(session_db, album_or_id) -> AlbumStatus:
    if isinstance(album_or_id, Album):
        album = album_or_id
        aid = album.id
    else:
        aid = album_or_id
        album = session_db.get(Album, aid) if aid else None

    st = session_db.get(AlbumStatus, aid) if aid else None
    if not st and aid:
        st = AlbumStatus(album_id=aid)
        if album is not None:
            st.cover_done = bool((getattr(album, "cover_url", None) or "").strip())
            if st.cover_done:
                st.cover_updated_at = datetime.now(TZ_MADRID)
        session_db.add(st)
        session_db.flush()
    return st


def _refresh_album_material_status(session_db, album_or_id, material_rows: list[AlbumMaterial] | None = None, status_obj: AlbumStatus | None = None) -> dict:
    album = album_or_id if isinstance(album_or_id, Album) else session_db.get(Album, to_uuid(album_or_id))
    if not album:
        return {"state": "none", "text_class": "text-danger", "badge_class": "text-bg-danger"}
    if material_rows is None:
        material_rows = (
            session_db.query(AlbumMaterial)
            .filter(AlbumMaterial.album_id == album.id)
            .order_by(AlbumMaterial.created_at.asc())
            .all()
        )
    meta = _album_material_completion_meta(album, material_rows)
    st = status_obj or _ensure_album_status_row(session_db, album.id)
    now_dt = datetime.now(TZ_MADRID)
    st.cover_done = bool(meta["cover_done"])
    st.cover_updated_at = meta["last_cover_at"] or (st.cover_updated_at if meta["cover_done"] else None)
    st.materials_done = meta["state"] == "complete"
    st.materials_updated_at = meta["last_material_at"]
    st.updated_at = now_dt
    session_db.add(st)
    return meta


def _mark_album_agedi_registered(session_db, album_id) -> AlbumStatus:
    aid = to_uuid(album_id) if not isinstance(album_id, UUID) else album_id
    st = _ensure_album_status_row(session_db, aid)
    st.agedi_done = True
    st.agedi_updated_at = datetime.now(TZ_MADRID)
    st.updated_at = datetime.now(TZ_MADRID)
    session_db.add(st)
    return st


def _build_song_material_context(session_db, song: Song, material_rows: list[SongMaterial] | None = None) -> dict:
    if material_rows is None:
        material_rows = (
            session_db.query(SongMaterial)
            .filter(SongMaterial.song_id == song.id)
            .order_by(SongMaterial.created_at.asc())
            .all()
        )

    def row_payload(row: SongMaterial) -> dict:
        category = (getattr(row, "category", None) or "").strip().upper()
        slot_key = (getattr(row, "slot_key", None) or "DEFAULT").strip().upper()
        display_name = (getattr(row, "display_name", None) or "").strip() or None
        raw_name = (getattr(row, "file_name", None) or display_name or "archivo").replace("\\", "/")
        base_name = Path(raw_name).name or "archivo"
        share_token = _make_public_song_share_token("MATERIAL", str(song.id), ref=str(row.id), fmt="original")
        share_url = _external_url_for("public_song_material_download") + f"?token={quote_plus(share_token)}"
        payload = {
            "id": str(row.id),
            "category": category,
            "slot_key": slot_key,
            "bundle_key": (getattr(row, "bundle_key", None) or "").strip(),
            "label": _song_material_slot_label(category, slot_key, display_name),
            "display_name": display_name,
            "file_name": raw_name,
            "base_name": base_name,
            "file_url": (getattr(row, "file_url", None) or "").strip(),
            "mime_type": (getattr(row, "mime_type", None) or "").strip(),
            "created_at": getattr(row, "created_at", None),
            "share_url": share_url,
            "download_original_url": url_for("discografica_song_material_download", song_id=song.id, material_id=row.id, format="original"),
            "download_jpg_url": url_for("discografica_song_material_download", song_id=song.id, material_id=row.id, format="jpg") if category == "COVER" else "",
            "download_png_url": url_for("discografica_song_material_download", song_id=song.id, material_id=row.id, format="png") if category == "COVER" else "",
            "download_wav_url": url_for("discografica_song_material_download", song_id=song.id, material_id=row.id, format="wav") if category in {"MASTER", "INSTRUMENTAL", "TV_TRACK"} else "",
            "download_mp3_url": url_for("discografica_song_material_download", song_id=song.id, material_id=row.id, format="mp3") if category in {"MASTER", "INSTRUMENTAL", "TV_TRACK"} else "",
            "is_audio": category in {"MASTER", "INSTRUMENTAL", "TV_TRACK", "STEMS"},
            "is_pending": (getattr(row, "validation_status", None) or "VALIDATED").strip().upper() == "PENDING",
        }
        return payload

    cover_principal = None
    cover_provisional = None
    masters_default = {"MASTER_48": None, "MASTER_24": None, "MASTER_16": None}
    master_subproducts = []
    instrumental_default = None
    instrumental_subproducts = []
    tv_track_default = None
    tv_track_subproducts = []
    stems_map: dict[str, dict] = {}

    for row in material_rows or []:
        category = (getattr(row, "category", None) or "").strip().upper()
        slot_key = (getattr(row, "slot_key", None) or "DEFAULT").strip().upper()
        payload = row_payload(row)
        if category == "COVER":
            if slot_key == "COVER_PROVISIONAL":
                if cover_provisional is None:
                    cover_provisional = payload
            elif cover_principal is None:
                cover_principal = payload
            continue
        if category == "MASTER":
            if slot_key in masters_default and masters_default[slot_key] is None:
                masters_default[slot_key] = payload
            else:
                master_subproducts.append(payload)
            continue
        if category == "INSTRUMENTAL":
            if slot_key == "DEFAULT" and instrumental_default is None:
                instrumental_default = payload
            else:
                instrumental_subproducts.append(payload)
            continue
        if category == "TV_TRACK":
            if slot_key == "DEFAULT" and tv_track_default is None:
                tv_track_default = payload
            else:
                tv_track_subproducts.append(payload)
            continue
        if category == "STEMS":
            bundle_key = payload["bundle_key"] or payload["id"]
            group = stems_map.setdefault(bundle_key, {
                "bundle_key": bundle_key,
                "label": payload["display_name"] or "Stems",
                "rows": [],
                "created_at": payload["created_at"],
            })
            group["rows"].append(payload)
            if payload["created_at"] and (group["created_at"] is None or payload["created_at"] > group["created_at"]):
                group["created_at"] = payload["created_at"]

    if cover_principal is None and (getattr(song, "cover_url", None) or "").strip():
        cover_principal = {
            "id": "",
            "category": "COVER",
            "slot_key": "COVER",
            "bundle_key": "",
            "label": "Portada",
            "display_name": "Portada",
            "file_name": "portada",
            "base_name": "portada",
            "file_url": (song.cover_url or "").strip(),
            "mime_type": mimetypes.guess_type((song.cover_url or "").split("?", 1)[0])[0] or "",
            "created_at": getattr(song, "created_at", None),
            "share_url": (song.cover_url or "").strip(),
            "download_original_url": "",
            "download_jpg_url": "",
            "download_png_url": "",
            "download_wav_url": "",
            "download_mp3_url": "",
        }

    stem_groups = []
    for bundle_key, group in stems_map.items():
        token = _make_public_song_share_token("STEMS_BUNDLE", str(song.id), ref=bundle_key)
        share_url = _external_url_for("public_song_material_bundle_download") + f"?token={quote_plus(token)}"
        group.update({
            "label": group["label"],
            "file_count": len(group["rows"]),
            "is_pending": any(r.get("is_pending") for r in group["rows"]),
            "share_url": share_url,
            "download_zip_url": url_for("discografica_song_stems_bundle_download", song_id=song.id, bundle_key=bundle_key),
        })
        stem_groups.append(group)
    stem_groups.sort(key=lambda item: item.get("created_at") or datetime.min.replace(tzinfo=TZ_MADRID), reverse=True)

    completion = _song_material_completion_meta(song, material_rows or [])
    return {
        "cover_item": cover_principal,
        "cover_principal": cover_principal,
        "cover_provisional": cover_provisional,
        "masters_default": masters_default,
        "master_subproducts": master_subproducts,
        "instrumental_default": instrumental_default,
        "instrumental_subproducts": instrumental_subproducts,
        "tv_track_default": tv_track_default,
        "tv_track_subproducts": tv_track_subproducts,
        "stem_groups": stem_groups,
        "completion": completion,
    }


def _bundle_song_material_rows_to_zip(rows: list[SongMaterial], archive_label: str | None = None) -> tuple[bytes, str]:
    buf = BytesIO()
    used = set()
    with zipfile.ZipFile(buf, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        for idx, row in enumerate(rows or [], start=1):
            content, _ctype = _download_remote_content(getattr(row, "file_url", None))
            fallback = f"archivo_{idx}"
            member_name = _safe_zip_member_name(getattr(row, "file_name", None), used, fallback)
            zf.writestr(member_name, content)
    filename_root = (archive_label or "stems").strip() or "stems"
    filename_root = filename_root.replace("/", "-").replace("\\", "-")
    return buf.getvalue(), f"{filename_root}.zip"


def _song_lyrics_meta(session_db, song: Song) -> dict:
    shares = (
        session_db.query(SongEditorialShare)
        .options(joinedload(SongEditorialShare.promoter))
        .filter(SongEditorialShare.song_id == song.id)
        .order_by(SongEditorialShare.created_at.asc())
        .all()
    )
    authors = []
    composers = []
    for sh in shares:
        promoter = getattr(sh, "promoter", None)
        full_name = " ".join([x for x in [
            (getattr(promoter, "first_name", None) or "").strip(),
            (getattr(promoter, "last_name", None) or "").strip(),
        ] if x]).strip()
        full_name = full_name or (getattr(promoter, "nick", None) or "").strip() or "—"
        role = (getattr(sh, "role", None) or "").strip().upper()
        if role == "AUTHOR":
            authors.append(full_name)
        elif role == "COMPOSER":
            composers.append(full_name)
        else:
            authors.append(full_name)
            composers.append(full_name)

    interpreters = [
        (getattr(row, "name", None) or "").strip()
        for row in (
            session_db.query(SongInterpreter)
            .filter(SongInterpreter.song_id == song.id)
            .order_by(SongInterpreter.is_main.desc(), SongInterpreter.created_at.asc())
            .all()
        )
        if (getattr(row, "name", None) or "").strip()
    ]
    if not interpreters:
        interpreters = [a.name for a in (getattr(song, "artists", []) or []) if getattr(a, "name", None)]

    combined = bool(authors) and bool(composers) and authors == composers
    return {
        "authors": authors,
        "composers": composers,
        "interpreters": interpreters,
        "combined": combined,
    }


def _build_song_lyrics_pdf_bytes(session_db, song_id, *, include_logo: bool = True) -> tuple[bytes, str]:
    song = session_db.get(Song, to_uuid(song_id))
    if not song or not (getattr(song, "lyrics_text", None) or "").strip():
        raise LookupError("La canción no tiene letra guardada.")

    from reportlab.lib.pagesizes import A4
    from reportlab.lib.units import cm

    meta = _song_lyrics_meta(session_db, song)
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle(
        "SongLyricsTitle",
        parent=styles["Heading1"],
        fontName="Helvetica-Bold",
        fontSize=18,
        leading=22,
        spaceAfter=12,
        textColor=colors.HexColor("#1f2937"),
    )
    meta_label_style = ParagraphStyle(
        "SongLyricsMetaLabel",
        parent=styles["BodyText"],
        fontName="Helvetica-Bold",
        fontSize=9.5,
        leading=12,
        textColor=colors.HexColor("#111827"),
        spaceAfter=3,
    )
    meta_text_style = ParagraphStyle(
        "SongLyricsMetaText",
        parent=styles["BodyText"],
        fontSize=10,
        leading=13,
        textColor=colors.HexColor("#374151"),
        spaceAfter=6,
    )
    lyrics_style = ParagraphStyle(
        "SongLyricsBody",
        parent=styles["BodyText"],
        fontSize=10.5,
        leading=16,
        alignment=TA_JUSTIFY,
        textColor=colors.HexColor("#111827"),
        spaceAfter=10,
    )

    buf = BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, leftMargin=2.1*cm, rightMargin=2.1*cm, topMargin=1.8*cm, bottomMargin=1.8*cm)
    story = []

    brand = _pies_brand_assets(session_db)
    logo = _rl_image_flowable_from_url(brand.get('logo_url'), 3.3, 1.05)
    if include_logo and logo:
        logo.hAlign = 'LEFT'
        story.append(logo)
        story.append(Spacer(1, 0.4*cm))

    story.append(Paragraph(f"Letra: {html.escape(song.title)}", title_style))

    if meta["combined"]:
        story.append(Paragraph("Autores y compositores", meta_label_style))
        story.append(Paragraph(html.escape(", ".join(meta["authors"]) or "—"), meta_text_style))
    else:
        story.append(Paragraph("Autores", meta_label_style))
        story.append(Paragraph(html.escape(", ".join(meta["authors"]) or "—"), meta_text_style))
        story.append(Paragraph("Compositores", meta_label_style))
        story.append(Paragraph(html.escape(", ".join(meta["composers"]) or "—"), meta_text_style))

    story.append(Paragraph("Intérpretes", meta_label_style))
    story.append(Paragraph(html.escape(", ".join(meta["interpreters"]) or "—"), meta_text_style))
    story.append(Spacer(1, 0.35*cm))

    lyrics_text = (song.lyrics_text or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    paragraphs = [chunk.strip() for chunk in lyrics_text.split("\n\n") if chunk.strip()] or [lyrics_text]
    for chunk in paragraphs:
        safe_chunk = html.escape(chunk).replace("\n", "<br/>")
        story.append(Paragraph(safe_chunk, lyrics_style))

    doc.build(story)
    filename = f"Letra - {song.title}".replace("/", "-").replace("\\", "-").strip() or "Letra"
    return buf.getvalue(), f"{filename}.pdf"




def _rl_image_flowable_from_url(file_url: str | None, width_cm: float, height_cm: float):
    if not file_url:
        return None
    try:
        from reportlab.lib.units import cm
        target = (file_url or "").strip()
        # ReportLab puede leer rutas locales directamente; esto evita depender
        # de que el servidor pueda descargarse a sí mismo los assets estáticos.
        if target.startswith("/static/") or target.startswith("static/"):
            rel = target.lstrip("/")
            local_path = Path(app.root_path) / rel
            if local_path.exists():
                return RLImage(str(local_path), width=width_cm * cm, height=height_cm * cm)
        if not re.match(r"^https?://", target, flags=re.I):
            local_path = Path(target)
            if not local_path.is_absolute():
                local_path = Path(app.root_path) / target
            if local_path.exists():
                return RLImage(str(local_path), width=width_cm * cm, height=height_cm * cm)
        data, _ = _download_remote_content(target)
        return RLImage(BytesIO(data), width=width_cm * cm, height=height_cm * cm)
    except Exception:
        return None


def _share_publisher(share):
    """Editorial efectiva de un registro de autoría.

    Devuelve el snapshot guardado en el propio registro (`SongEditorialShare`) y, si no lo
    tiene (registros antiguos), la editorial actual del tercero (compatibilidad hacia atrás).
    """
    pub = getattr(share, "publishing_company", None)
    if pub is not None:
        return pub
    promoter = getattr(share, "promoter", None)
    return getattr(promoter, "publishing_company", None) if promoter else None


def _song_label_copy_author_rows(session_db, song: Song) -> tuple[list[list[str]], float]:
    shares = (
        session_db.query(SongEditorialShare)
        .options(joinedload(SongEditorialShare.promoter).joinedload(Promoter.publishing_company))
        .filter(SongEditorialShare.song_id == song.id)
        .order_by(SongEditorialShare.created_at.asc())
        .all()
    )
    role_labels = {
        'AUTHOR': 'Autor',
        'COMPOSER': 'Compositor',
        'AUTHOR_COMPOSER': 'Autor y Compositor',
    }
    rows = []
    total_pct = 0.0
    for share in shares or []:
        promoter = share.promoter
        publisher = _share_publisher(share)
        pct = float(getattr(share, 'pct', 0) or 0)
        total_pct += pct
        rows.append([
            _promoter_display_name(promoter) or '—',
            role_labels.get((getattr(share, 'role', None) or '').strip().upper(), '—'),
            (getattr(publisher, 'name', None) or '').strip() or '—',
            f"{pct:.2f}%",
        ])
    return rows, round(total_pct, 2)


def _song_label_copy_isrc_lines(session_db, song: Song) -> list[str]:
    rows = (
        session_db.query(SongISRCCode)
        .filter(SongISRCCode.song_id == song.id)
        .order_by(SongISRCCode.kind.asc(), SongISRCCode.is_primary.desc(), SongISRCCode.created_at.asc())
        .all()
    )
    lines = []
    seen = set()
    for row in rows or []:
        code = _norm_isrc(getattr(row, 'code', None))
        if not code or code in seen:
            continue
        seen.add(code)
        kind = (getattr(row, 'kind', None) or '').strip().upper()
        lines.append(f"{'Vídeo' if kind == 'VIDEO' else 'Audio'}: {code}")
    main_isrc = _norm_isrc(getattr(song, 'isrc', None))
    if main_isrc and main_isrc not in seen:
        lines.insert(0, f"Audio: {main_isrc}")
    return lines


def _platform_links_for_item(item) -> list[dict]:
    specs = [
        ('spotify', 'Spotify', 'fa-brands fa-spotify', 'spotify_url', 'platform-spotify', 'img/platforms/spotify.png'),
        ('apple_music', 'Apple Music', 'fa-brands fa-apple', 'apple_music_url', 'platform-apple', 'img/platforms/apple_music.png'),
        ('amazon_music', 'Amazon Music', 'fa-brands fa-amazon', 'amazon_music_url', 'platform-amazon', 'img/platforms/amazon_music.png'),
        ('tiktok', 'TikTok', 'fa-brands fa-tiktok', 'tiktok_url', 'platform-tiktok', 'img/platforms/tiktok.png'),
        ('youtube', 'YouTube', 'fa-brands fa-youtube', 'youtube_url', 'platform-youtube', 'img/platforms/youtube.png'),
    ]
    out = []
    for key, label, icon, field, css_class, asset in specs:
        url = (getattr(item, field, None) or '').strip() if item is not None else ''
        if not url:
            continue
        if not url.startswith(('http://', 'https://')):
            url = 'https://' + url
        try:
            asset_url = url_for('static', filename=asset, _external=True)
            asset_path = str(Path(app.root_path) / 'static' / asset.replace('img/', 'img/'))
        except Exception:
            asset_url = ''
            asset_path = str(Path('static') / asset)
        out.append({
            'key': key,
            'label': label,
            'icon': icon,
            'class': css_class,
            'css_class': css_class,
            'asset': asset,
            'asset_url': asset_url,
            'asset_path': asset_path,
            'url': url,
        })
    return out


def _song_platform_links(song: Song | None) -> list[dict]:
    return _platform_links_for_item(song)


def _album_platform_links(album: Album | None) -> list[dict]:
    return _platform_links_for_item(album)


class _LinkedRLImage(RLImage if REPORTLAB_AVAILABLE else object):
    """Imagen clicable para PDFs ReportLab."""
    def __init__(self, filename, width=None, height=None, link_url=None, **kwargs):
        if not REPORTLAB_AVAILABLE:
            return
        super().__init__(filename, width=width, height=height, **kwargs)
        self.link_url = link_url

    def drawOn(self, canv, x, y, _sW=0):
        super().drawOn(canv, x, y, _sW)
        if getattr(self, 'link_url', None):
            try:
                canv.linkURL(self.link_url, (x, y, x + self.drawWidth, y + self.drawHeight), relative=0, thickness=0)
            except Exception:
                pass


def _platform_link_icon_flowable(link: dict, size_cm: float = 0.58):
    if not REPORTLAB_AVAILABLE:
        return None
    try:
        from reportlab.lib.units import cm
        asset_path = Path(link.get('asset_path') or '')
        if not asset_path.exists():
            asset = (link.get('asset') or '').lstrip('/')
            asset_path = Path(app.root_path) / 'static' / asset
        if not asset_path.exists():
            return None
        img = _LinkedRLImage(str(asset_path), width=size_cm * cm, height=size_cm * cm, link_url=link.get('url'))
        img.hAlign = 'LEFT'
        return img
    except Exception:
        return None


def _platform_links_pdf_table(item):
    if not REPORTLAB_AVAILABLE:
        return None
    try:
        from reportlab.lib.units import cm
        cells = []
        widths = []
        for link in _platform_links_for_item(item):
            icon = _platform_link_icon_flowable(link)
            if not icon:
                continue
            cells.append(icon)
            widths.append(0.74 * cm)
        if not cells:
            return None
        table = Table([cells], colWidths=widths, hAlign='LEFT')
        table.setStyle(TableStyle([
            ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
            ('LEFTPADDING', (0,0), (-1,-1), 0),
            ('RIGHTPADDING', (0,0), (-1,-1), 4),
            ('TOPPADDING', (0,0), (-1,-1), 2),
            ('BOTTOMPADDING', (0,0), (-1,-1), 2),
        ]))
        return table
    except Exception:
        return None


def _platform_links_pdf_html(item) -> str:
    """Compatibilidad para plantillas antiguas: HTML con iconos imagen clicables."""
    links = []
    for link in _platform_links_for_item(item):
        url = html.escape(link.get('url') or '', quote=True)
        src = html.escape(link.get('asset_url') or '', quote=True)
        label = html.escape(link.get('label') or 'Enlace')
        if src:
            links.append(f'<a href="{url}"><img src="{src}" alt="{label}" style="width:22px;height:22px;object-fit:contain;display:inline-block;margin-right:8px;"></a>')
    return ''.join(links)


def _song_platform_links_pdf_html(song: Song | None) -> str:
    return _platform_links_pdf_html(song)


def _album_platform_links_pdf_html(album: Album | None) -> str:
    return _platform_links_pdf_html(album)


def _song_label_copy_public_context(session_db, song: Song) -> dict:
    artist = _song_primary_artist(session_db, song)
    artist_name = (getattr(artist, 'name', None) or '').strip() or 'Artista'
    interpreters_label = _song_interpreters_label(session_db, song)
    isrc_lines = _song_label_copy_isrc_lines(session_db, song)
    author_rows, author_total = _song_label_copy_author_rows(session_db, song)
    musicians = []
    for row in (getattr(song, 'musicians', None) or []):
        instrument = (row.get('instrument') or '').strip() if isinstance(row, dict) else ''
        name = (row.get('name') or '').strip() if isinstance(row, dict) else ''
        if instrument or name:
            musicians.append((f"{instrument}: " if instrument else '') + name)

    info_rows = []
    def add_row(label, value):
        value = value if isinstance(value, str) else ('' if value is None else str(value))
        value = value.strip()
        if value:
            info_rows.append({'label': label, 'value': value})

    add_row('Título', song.title)
    add_row('Intérpretes', interpreters_label)
    add_row('Versión', song.version)
    add_row('Fecha de publicación', song.release_date.strftime('%d/%m/%Y') if song.release_date else '')
    add_row('Códigos ISRC', '\n'.join(isrc_lines))
    add_row('Duración (Timing)', _seconds_to_timecode(getattr(song, 'duration_seconds', None)))
    add_row('Inicio en Tik Tok', _seconds_to_timecode(getattr(song, 'tiktok_start_seconds', None)))
    add_row('BPM', str(song.bpm or ''))
    add_row('Género', song.genre)
    add_row('Copyright', song.copyright_text)
    add_row('Productor', ', '.join([x for x in (song.producers or []) if (x or '').strip()]))
    add_row('Ingeniero de grabación', song.recording_engineer)
    add_row('Estudio de grabación', song.studio)
    add_row('Fecha de grabación', song.recording_date.strftime('%d/%m/%Y') if song.recording_date else '')
    add_row('Ingeniero de mezcla', song.mixing_engineer)
    add_row('Ingeniero de mastering', song.mastering_engineer)
    add_row('Arreglista', ', '.join([x for x in (song.arrangers or []) if (x or '').strip()]))
    add_row('Músicos', '\n'.join(musicians))
    return {
        'song': song,
        'artist': artist,
        'artist_name': artist_name,
        'interpreters_label': interpreters_label,
        'brand': _pies_brand_assets(session_db),
        'cover_url': (getattr(song, 'cover_url', None) or '').strip(),
        'platform_links': _song_platform_links(song),
        'info_rows': info_rows,
        'author_rows': author_rows,
        'author_total': author_total,
    }


def _album_label_copy_public_context(session_db, album: Album) -> dict:
    artist = session_db.get(Artist, getattr(album, 'artist_id', None)) if getattr(album, 'artist_id', None) else None
