def _royalty_liquidation_snapshot(beneficiary: dict, sem_start: date, sem_end: date) -> dict:
    items = []
    for item in (beneficiary.get('items') or []):
        items.append({
            'item_id': item.get('item_id') or '',
            'item_kind': item.get('item_kind') or '',
            'item_type_label': item.get('item_type_label') or '',
            'title': item.get('title') or '',
            'subtitle': item.get('subtitle') or '',
            'code': item.get('code') or '',
            'code_label': item.get('code_label') or '',
            'release_date': item.get('release_date') or '',
            'income': float(item.get('income') or 0),
            'pct': float(item.get('pct') or 0),
            'amount': float(item.get('amount') or 0),
            # ⚠️ Los DESCUENTOS a terceros van en el congelado: el PDF los pinta bajo cada línea y
            # con `use_frozen=True` el congelado SUSTITUYE al beneficiario en vivo, así que si no
            # estuvieran aquí desaparecerían del PDF y de la pantalla (bug real: la liquidación se
            # veía «incompleta»). Las congeladas antes de esto no los traen y no se pueden
            # reconstruir: se pintan sin ellos, como hasta ahora.
            'amount_before_deductions': float(item.get('amount_before_deductions') or 0),
            'deduction_total': float(item.get('deduction_total') or 0),
            'deductions': [{
                'name': (d.get('name') or ''),
                'amount': float(d.get('amount') or 0),
                'pct': float(d.get('pct') or 0),
                'base': (d.get('base') or ''),
            } for d in (item.get('deductions') or []) if isinstance(d, dict)],
            'badges': list(item.get('badges') or []),
            'cover_url': (item.get('cover_url') or '').strip(),
            'fallback_cover_url': (item.get('fallback_cover_url') or '').strip(),
        })
    return {
        'kind': beneficiary.get('kind') or '',
        'id': beneficiary.get('id') or '',
        'name': beneficiary.get('name') or '',
        'kind_label': beneficiary.get('kind_label') or '',
        'photo_url': (beneficiary.get('photo_url') or '').strip(),
        'period_start': sem_start.isoformat(),
        'period_end': sem_end.isoformat(),
        'total_amount': float(beneficiary.get('total_amount') or 0),
        'total_income': float(beneficiary.get('total_income') or 0),
        'items': items,
    }



def _royalty_liquidation_snapshot_signature(snapshot: dict) -> str:
    raw = json.dumps(snapshot or {}, ensure_ascii=False, sort_keys=True, default=str).encode('utf-8')
    return hashlib.sha256(raw).hexdigest()



# ---------------------------------------------------------------------------
#  LA LIQUIDACIÓN GENERADA QUEDA CONGELADA
#  Al generar una liquidación se guarda el detalle tal cual (snapshot) con su firma y su PDF. Aunque
#  después cambien los ingresos, lo generado NO se toca: para actualizarla hay que generar una nueva
#  y antes se enseña la comparativa. Así nunca hay diferencia entre lo enviado y lo que registra el
#  sistema. Todo lo que le pasa a esa liquidación (generada, enviada, factura subida, pagada) queda
#  en su historial, que es lo que muestra el botón de Información.
# ---------------------------------------------------------------------------
ROYALTY_EVENT_LABELS = {
    "GENERATED": "Liquidación generada",
    "REGENERATED": "Liquidación regenerada",
    "SENT": "Enviada al beneficiario",
    "INVOICED": "Factura recibida",
    "PAID": "Pagada",
    "INVOICE_REJECTED": "Factura rechazada",
    "PAYMENT_REOPENED": "Vuelta a pendiente de pago",
    "CONSIGNED": "Datos consignados",
    "ACCOUNTED": "Contabilizada",
}


def _royalty_data_signature(beneficiary: dict) -> str:
    """Firma de los datos ECONÓMICOS del beneficiario: cambia si cambian los ingresos o el detalle."""
    if not isinstance(beneficiary, dict):
        return ""
    def _num(v):
        try:
            return float(_money_or_zero(v))
        except Exception:
            return 0.0
    filas = []
    for it in (beneficiary.get("items") or []):
        if not isinstance(it, dict):
            continue
        filas.append([str(it.get("id") or it.get("title") or ""), _num(it.get("income")),
                      _num(it.get("amount")), _num(it.get("pct"))])
    filas.sort(key=lambda x: x[0])
    # ⚠️ El importe del beneficiario es `total_amount`. `total` NO existe: se leía en varios sitios y
    # daba siempre 0, así que el aviso de «los ingresos han cambiado» no decía cuánto cambiaba y el
    # historial apuntaba la generación sin importe.
    base = {"total_income": _num(beneficiary.get("total_income")),
            "total_amount": _num(beneficiary.get("total_amount")), "items": filas}
    return hashlib.sha256(json.dumps(base, sort_keys=True, default=str).encode("utf-8")).hexdigest()


def _royalty_history_add(rec, kind: str, **extra) -> None:
    """Apunta un evento en la trazabilidad de la liquidación."""
    if rec is None:
        return
    estado = {}
    try:
        estado = _current_user_state() or {}
    except Exception:
        estado = {}
    evento = {"kind": (kind or "").upper(), "at": _now_madrid().isoformat(),
              "by": (estado.get("nick") or "").strip() or None}
    evento.update({k: v for k, v in (extra or {}).items() if v not in (None, "")})
    hist = list(getattr(rec, "history", None) or [])
    hist.append(evento)
    rec.history = hist[-60:]


def _royalty_freeze(session_db, rec, beneficiary: dict, pdf_url: str = "", regenerada: bool = False) -> None:
    """Congela en la liquidación los datos con los que se ha generado."""
    if rec is None or not isinstance(beneficiary, dict):
        return
    rec.snapshot = json.loads(json.dumps(beneficiary, default=str))
    rec.snapshot_signature = _royalty_data_signature(beneficiary)
    if pdf_url:
        rec.snapshot_pdf_url = pdf_url
    rec.generated_at = _now_madrid()
    rec.updated_at = rec.generated_at
    if (rec.status or "PENDING").upper() in ("", "PENDING"):
        rec.status = "GENERATED"
    _royalty_history_add(rec, "REGENERATED" if regenerada else "GENERATED",
                         total=(format_eur(_money_or_zero(beneficiary.get("total_amount")))
                                if beneficiary.get("total_amount") not in (None, "") else ""),
                         pdf_url=pdf_url or None)


def _royalty_frozen_beneficiary(rec):
    """Los datos CONGELADOS de la liquidación (o None si todavía no se ha generado).

    Se mira primero el congelado de la GENERACIÓN (`snapshot`) y, si no lo hay, el de lo que se
    ENVIÓ (`last_sent_snapshot`): una liquidación enviada antes de que se guardara el snapshot de la
    generación solo tiene ese, y aun así **es lo que se envió**, que es lo que manda. Sin esto esas
    liquidaciones caían a los datos de HOY y los importes «se actualizaban» (el fallo que había)."""
    if rec is None:
        return None
    for campo in ("snapshot", "last_sent_snapshot"):
        snap = getattr(rec, campo, None)
        # `{}` es «no hay nada congelado»; un congelado de verdad trae su importe (o sus líneas).
        if isinstance(snap, dict) and ("total_amount" in snap or snap.get("items")):
            return snap
    return None


def _royalty_effective_beneficiary(session_db, rec, kind: str, beneficiary_id, sem_year: int, sem_half: int):
    """LOS DATOS DE LA LIQUIDACIÓN: el congelado si ya se generó, y solo si no, los de ahora.

    Punto ÚNICO para que todas las pantallas (el enlace del beneficiario, la validación de su factura,
    pendiente de pago, el listado y el PDF) enseñen EXACTAMENTE lo que se envió. Si los ingresos
    cambian después, la liquidación no se altera: hay que generar una nueva."""
    congelada = _royalty_frozen_beneficiary(rec)
    if congelada:
        return congelada, True
    try:
        vivo, _s, _e, _b = _get_royalty_liquidation_beneficiary_data(
            session_db, kind, beneficiary_id, sem_year, sem_half, apply_frozen=False)
        return vivo, False
    except Exception:
        return None, False


def _royalty_invoice_totals(beneficiary: dict | None) -> dict:
    """Lo que hay que FACTURAR de una liquidación: su importe es la BASE y la factura va con IVA.

    Un solo cálculo para el enlace del beneficiario, la validación de la factura y el pago, para que
    la liquidación, la factura y lo que se paga digan el MISMO número."""
    return _invoice_request_amounts((beneficiary or {}).get("total_amount"), 0)


def _royalty_needs_regeneration(rec, live_beneficiary: dict) -> bool:
    """¿Los ingresos han cambiado desde que se generó? Entonces hay que volver a generarla."""
    if rec is None or not _royalty_frozen_beneficiary(rec):
        return False
    firma = (getattr(rec, "snapshot_signature", None) or "").strip()
    return bool(firma) and firma != _royalty_data_signature(live_beneficiary or {})


def _royalty_timeline(rec) -> list:
    """Historial legible de la liquidación para el botón de Información."""
    salida = []
    for ev in (getattr(rec, "history", None) or []):
        if not isinstance(ev, dict):
            continue
        cuando = ev.get("at")
        try:
            cuando_dt = datetime.fromisoformat(str(cuando)) if cuando else None
        except Exception:
            cuando_dt = None
        salida.append({
            "kind": (ev.get("kind") or "").upper(),
            "label": ROYALTY_EVENT_LABELS.get((ev.get("kind") or "").upper(), (ev.get("kind") or "").title()),
            "at_label": (_format_madrid_datetime_label(cuando_dt) if cuando_dt else (str(cuando or "")[:16].replace("T", " "))),
            "by": ev.get("by") or "",
            "pdf_url": ev.get("pdf_url") or "",
            "file_url": ev.get("file_url") or "",
            "note": ev.get("note") or "",
            "total": ev.get("total") or "",
            "to": ev.get("to") or "",
        })
    salida.reverse()          # lo más reciente arriba
    return salida


def _apply_royalty_liquidation_meta(bucket: dict, rec: RoyaltyLiquidation | None,
                                    apply_frozen: bool = True) -> None:
    if not bucket:
        return
    if not rec:
        bucket['has_sent_info'] = False
        bucket['last_sent_to'] = []
        bucket['last_sent_at_label'] = ''
        bucket['last_sent_pdf_url'] = ''
        bucket['last_sent_signature'] = ''
        # Sin fila de liquidación todavía NO está generada.
        bucket['is_generated'] = False
        bucket['is_sent'] = False
        bucket['needs_regeneration'] = False
        bucket['liquidation_status'] = 'PENDING'
        lbl, color = _royalty_status_meta('PENDING')
        bucket['liquidation_label'] = lbl
        bucket['liquidation_color'] = color
        return

    bucket['liquidation_status'] = getattr(rec, 'status', None)
    if bucket['liquidation_status']:
        lbl, color = _royalty_status_meta(bucket['liquidation_status'])
        bucket['liquidation_label'] = lbl
        bucket['liquidation_color'] = color

    sent_to = getattr(rec, 'last_sent_to', None) or []
    if not isinstance(sent_to, list):
        sent_to = []
    bucket['last_sent_to'] = [str(x).strip() for x in sent_to if str(x or '').strip()]
    bucket['last_sent_at'] = getattr(rec, 'last_sent_at', None)
    bucket['is_sent'] = bool(bucket['last_sent_at'])
    bucket['last_sent_at_label'] = _format_madrid_datetime_label(bucket['last_sent_at'])
    bucket['last_sent_pdf_url'] = (getattr(rec, 'last_sent_pdf_url', None) or '').strip()
    bucket['last_sent_signature'] = (getattr(rec, 'last_sent_signature', None) or '').strip()
    # La información se puede consultar SIEMPRE que exista la liquidación (no solo si se envió): ahí
    # está toda la trazabilidad (generada, enviada, factura, cobro).
    bucket['has_sent_info'] = True
    congelada = _royalty_frozen_beneficiary(rec)
    bucket['is_generated'] = bool(congelada)
    bucket['generated_at_label'] = _format_madrid_datetime_label(getattr(rec, 'generated_at', None))
    bucket['generated_pdf_url'] = (getattr(rec, 'snapshot_pdf_url', None) or '').strip()
    bucket['invoice_uploaded_at_label'] = _format_madrid_datetime_label(getattr(rec, 'invoice_uploaded_at', None))
    bucket['paid_at_label'] = _format_madrid_datetime_label(getattr(rec, 'paid_at', None))
    if congelada:
        # Los ingresos pueden haber cambiado; la liquidación NO se altera hasta generar una nueva.
        bucket['needs_regeneration'] = _royalty_needs_regeneration(rec, bucket)
        bucket['live_total'] = bucket.get('total_amount')
        bucket['live_total_income'] = bucket.get('total_income')
        # ⚠️ `apply_frozen=False` = el llamante quiere los datos EN VIVO (generar una liquidación
        # nueva, o comparar antes/ahora). Pegar aquí el congelado sin más hacía que GENERAR volviera a
        # congelar los importes VIEJOS: por eso «genero de nuevo y no se actualiza» (bug real).
        if apply_frozen:
            for campo in ('total_income', 'total_amount', 'items'):
                if campo in congelada:
                    bucket[campo] = congelada[campo]
        # Aviso de cambios: desde cuándo (la fecha en que se generó lo que hay) y CUÁNTO cambia.
        if bucket['needs_regeneration']:
            try:
                dif = _money_or_zero(bucket.get('live_total')) - _money_or_zero(congelada.get('total_amount'))
            except Exception:
                dif = Decimal('0')
            bucket['income_diff'] = dif
            bucket['income_diff_label'] = ('+' if dif > 0 else '') + format_eur(dif)
            bucket['changed_since_label'] = bucket['generated_at_label']
    else:
        bucket['needs_regeneration'] = False


# Estados de una liquidación de royalties, en orden de flujo. PENDING = todavía NO generada (no
# existe su fila); DOWNLOADED = ya generada y descargada (pero sin enviar).
ROYALTY_STATUS_FLOW = ["PENDING", "GENERATED", "DOWNLOADED", "SENT", "INVOICED", "PAID"]
# Estados en los que la liquidación aún NO se ha enviado al beneficiario.
ROYALTY_NOT_SENT_STATUSES = {"GENERATED", "DOWNLOADED"}


def _royalty_status_meta(status: str | None) -> tuple[str, str]:
    s = (status or "PENDING").upper()
    if s == "PENDING":
        return ("Sin generar", "light")
    if s == "DOWNLOADED":
        return ("Descargada", "info")
    if s == "SENT":
        return ("Enviada", "primary")
    if s == "INVOICED":
        return ("Facturada", "warning")
    if s == "PAID":
        return ("Pagado", "success")
    return ("Generada", "secondary")


def _semester_month_starts(sem_start: date) -> list[date]:
    month_starts: list[date] = []
    cursor = date(sem_start.year, sem_start.month, 1)
    for _ in range(6):
        month_starts.append(cursor)
        cursor = _add_months(cursor, 1)
    return month_starts


def _royalty_beneficiary_display_name(promoter: Promoter | None) -> str:
    if not promoter:
        return "Beneficiario"
    return (getattr(promoter, "nick", None) or (((getattr(promoter, "first_name", None) or "") + " " + (getattr(promoter, "last_name", None) or "")))).strip() or "Beneficiario"


def _build_distribution_deduction_maps(session_db, song_ids: list[UUID] | None, album_ids: list[UUID] | None, song_gross_map: dict | None, song_net_map: dict | None, album_gross_map: dict | None, album_net_map: dict | None) -> tuple[dict[str, list[dict]], dict[str, list[dict]]]:
    song_gross_map = song_gross_map or {}
    song_net_map = song_net_map or {}
    album_gross_map = album_gross_map or {}
    album_net_map = album_net_map or {}
    song_map: dict[str, list[dict]] = {}
    album_map: dict[str, list[dict]] = {}

    if song_ids:
        rows = (
            session_db.query(SongRoyaltyBeneficiary)
            .options(joinedload(SongRoyaltyBeneficiary.promoter))
            .filter(SongRoyaltyBeneficiary.song_id.in_(song_ids))
            .all()
        )
        for row in rows:
            sid = str(getattr(row, 'song_id', '') or '')
            if not sid:
                continue
            base = (getattr(row, 'base', 'GROSS') or 'GROSS').strip().upper()
            if base not in ('GROSS', 'NET', 'PROFIT'):
                base = 'GROSS'
            pct = float(getattr(row, 'pct', 0) or 0)
            income = float(song_net_map.get(getattr(row, 'song_id', None), 0) if base in ('NET', 'PROFIT') else song_gross_map.get(getattr(row, 'song_id', None), 0))
            amount = income * (pct / 100.0)
            song_map.setdefault(sid, []).append({
                'name': _royalty_beneficiary_display_name(getattr(row, 'promoter', None)),
                'amount': float(amount or 0),
                'pct': pct,
                'base': base,
            })

    if album_ids:
        rows = (
            session_db.query(AlbumRoyaltyBeneficiary)
            .options(joinedload(AlbumRoyaltyBeneficiary.promoter))
            .filter(AlbumRoyaltyBeneficiary.album_id.in_(album_ids))
            .all()
        )
        for row in rows:
            aid = str(getattr(row, 'album_id', '') or '')
            if not aid:
                continue
            base = (getattr(row, 'base', 'GROSS') or 'GROSS').strip().upper()
            if base not in ('GROSS', 'NET', 'PROFIT'):
                base = 'GROSS'
            pct = float(getattr(row, 'pct', 0) or 0)
            income = float(album_net_map.get(getattr(row, 'album_id', None), 0) if base in ('NET', 'PROFIT') else album_gross_map.get(getattr(row, 'album_id', None), 0))
            amount = income * (pct / 100.0)
            album_map.setdefault(aid, []).append({
                'name': _royalty_beneficiary_display_name(getattr(row, 'promoter', None)),
                'amount': float(amount or 0),
                'pct': pct,
                'base': base,
            })

    for mapping in (song_map, album_map):
        for key, rows in mapping.items():
            rows.sort(key=lambda item: ((item.get('name') or '').casefold(), float(item.get('amount') or 0)))
    return song_map, album_map


def _apply_distribution_deductions(item: dict, deductions: list[dict] | None) -> dict:
    item = dict(item or {})
    clean_deductions = []
    total = 0.0
    for row in deductions or []:
        amount = float((row or {}).get('amount') or 0)
        clean_row = {
            'name': ((row or {}).get('name') or 'Beneficiario').strip() or 'Beneficiario',
            'amount': amount,
            'pct': float((row or {}).get('pct') or 0),
            'base': (row or {}).get('base') or 'GROSS',
        }
        clean_deductions.append(clean_row)
        total += amount
    base_amount = float(item.get('amount') or 0)
    item['amount_before_deductions'] = base_amount
    item['deductions'] = clean_deductions
    item['deduction_total'] = total
    item['amount'] = base_amount - total
    return item


def _build_royalty_single_beneficiary(session_db, sem_start: date, sem_end: date, kind: str, beneficiary_id,
                                      apply_frozen: bool = True) -> dict | None:
    """Construye un único beneficiario sin recorrer todo el semestre.

    Esta ruta se usa para liquidaciones individuales (PDF/email) y evita el
    pico de RAM/CPU que provocaba montar todos los beneficiarios antes de
    filtrar uno solo.
    """

    kind = (kind or "").strip().upper()
    bid = to_uuid(beneficiary_id)
    if kind not in ("ARTIST", "PROMOTER") or not bid:
        return None

    month_starts = _semester_month_starts(sem_start)

    def _append_item(bucket: dict, item: dict):
        bucket["items"].append(item)
        bucket["total_income"] += float(item.get("income") or 0)
        bucket["total_amount"] += float(item.get("amount") or 0)

    def _load_song_income_maps(song_ids: list[UUID]) -> tuple[dict, dict]:
        gross_map: dict[UUID, float] = {}
        net_map: dict[UUID, float] = {}
        if not song_ids:
            return gross_map, net_map
        sem_rows = {
            sid: (Decimal(g or 0), Decimal(n or 0))
            for sid, g, n in (
                session_db.query(
                    SongRevenueEntry.song_id,
                    func.sum(SongRevenueEntry.gross),
                    func.sum(SongRevenueEntry.net),
                )
                .filter(SongRevenueEntry.song_id.in_(song_ids))
                .filter(func.upper(SongRevenueEntry.period_type) == "SEMESTER")
                .filter(SongRevenueEntry.period_start == sem_start)
                .group_by(SongRevenueEntry.song_id)
                .all()
            )
            if sid
        }
        month_rows = {
            sid: (Decimal(g or 0), Decimal(n or 0))
            for sid, g, n in (
                session_db.query(
                    SongRevenueEntry.song_id,
                    func.sum(SongRevenueEntry.gross),
                    func.sum(SongRevenueEntry.net),
                )
                .filter(SongRevenueEntry.song_id.in_(song_ids))
                .filter(func.upper(SongRevenueEntry.period_type) == "MONTH")
                .filter(SongRevenueEntry.period_start.in_(month_starts))
                .group_by(SongRevenueEntry.song_id)
                .all()
            )
            if sid
        }
        for sid in song_ids:
            g, n = sem_rows.get(sid, month_rows.get(sid, (Decimal(0), Decimal(0))))
            gross_map[sid] = float(g or 0)
            net_map[sid] = float(n or 0)
        return gross_map, net_map

    def _load_album_income_maps(album_ids: list[UUID]) -> tuple[dict, dict]:
        gross_map: dict[UUID, float] = {}
        net_map: dict[UUID, float] = {}
        if not album_ids:
            return gross_map, net_map
        sem_rows = {
            aid: (Decimal(g or 0), Decimal(n or 0))
            for aid, g, n in (
                session_db.query(
                    AlbumRevenueEntry.album_id,
                    func.sum(AlbumRevenueEntry.gross),
                    func.sum(AlbumRevenueEntry.net),
                )
                .filter(AlbumRevenueEntry.album_id.in_(album_ids))
                .filter(func.upper(AlbumRevenueEntry.period_type) == "SEMESTER")
                .filter(AlbumRevenueEntry.period_start == sem_start)
                .group_by(AlbumRevenueEntry.album_id)
                .all()
            )
            if aid
        }
        month_rows = {
            aid: (Decimal(g or 0), Decimal(n or 0))
            for aid, g, n in (
                session_db.query(
                    AlbumRevenueEntry.album_id,
                    func.sum(AlbumRevenueEntry.gross),
                    func.sum(AlbumRevenueEntry.net),
                )
                .filter(AlbumRevenueEntry.album_id.in_(album_ids))
                .filter(func.upper(AlbumRevenueEntry.period_type) == "MONTH")
                .filter(AlbumRevenueEntry.period_start.in_(month_starts))
                .group_by(AlbumRevenueEntry.album_id)
                .all()
            )
            if aid
        }
        for aid in album_ids:
            g, n = sem_rows.get(aid, month_rows.get(aid, (Decimal(0), Decimal(0))))
            gross_map[aid] = float(g or 0)
            net_map[aid] = float(n or 0)
        return gross_map, net_map

    if kind == "ARTIST":
        artist = session_db.get(Artist, bid)
        if not artist:
            return None
        delivery = _beneficiary_email_delivery_data(session_db, "ARTIST", bid)
        bucket = {
            "kind": "ARTIST",
            "id": str(bid),
            "name": artist.name,
            "photo_url": getattr(artist, "photo_url", None),
            "kind_label": "Artista",
            "items": [],
            "total_income": 0.0,
            "total_amount": 0.0,
            "liquidation_status": None,
            "liquidation_label": None,
            "liquidation_color": None,
            "contact_email": (delivery.get("primary_email") or _beneficiary_contact_email(session_db, "ARTIST", bid) or ""),
            "default_recipients": list(delivery.get("default_recipients") or []),
            "suggested_recipients": list(delivery.get("suggested_recipients") or []),
            "extra_email_rows": list(delivery.get("extra_rows") or []),
            "can_send_email": bool((delivery.get("default_recipients") or []) or (delivery.get("suggested_recipients") or [])),
        }

        song_ids = [
            sid
            for (sid,) in (
                session_db.query(SongRevenueEntry.song_id)
                .join(SongArtist, SongArtist.song_id == SongRevenueEntry.song_id)
                .filter(SongArtist.artist_id == bid)
                .filter(
                    or_(
                        and_(func.upper(SongRevenueEntry.period_type) == "SEMESTER", SongRevenueEntry.period_start == sem_start),
                        and_(func.upper(SongRevenueEntry.period_type) == "MONTH", SongRevenueEntry.period_start.in_(month_starts)),
                    )
                )
                .distinct()
                .all()
            )
            if sid
        ]
        album_ids = [
            aid
            for (aid,) in (
                session_db.query(AlbumRevenueEntry.album_id)
                .join(Album, Album.id == AlbumRevenueEntry.album_id)
                .filter(Album.artist_id == bid)
                .filter(
                    or_(
                        and_(func.upper(AlbumRevenueEntry.period_type) == "SEMESTER", AlbumRevenueEntry.period_start == sem_start),
                        and_(func.upper(AlbumRevenueEntry.period_type) == "MONTH", AlbumRevenueEntry.period_start.in_(month_starts)),
                    )
                )
                .distinct()
                .all()
            )
            if aid
        ]

        songs = []
        if song_ids:
            songs = (
                session_db.query(Song)
                .options(selectinload(Song.artists))
                .filter(Song.id.in_(song_ids))
                .order_by(Song.release_date.desc())
                .all()
            )

        albums = []
        if album_ids:
            albums = (
                session_db.query(Album)
                .options(joinedload(Album.artist))
                .filter(Album.id.in_(album_ids))
                .order_by(Album.release_date.desc())
                .all()
            )

        song_gross_map, song_net_map = _load_song_income_maps(song_ids)
        album_gross_map, album_net_map = _load_album_income_maps(album_ids)
        song_deduction_map, album_deduction_map = _build_distribution_deduction_maps(
            session_db,
            song_ids,
            album_ids,
            song_gross_map,
            song_net_map,
            album_gross_map,
            album_net_map,
        )

        interp_map = {sid: [] for sid in song_ids}
        if song_ids:
            rows = (
                session_db.query(SongInterpreter)
                .filter(SongInterpreter.song_id.in_(song_ids))
                .order_by(SongInterpreter.song_id.asc(), SongInterpreter.is_main.desc(), SongInterpreter.created_at.asc())
                .all()
            )
            for row in rows:
                if row.song_id in interp_map and row.name:
                    interp_map[row.song_id].append(row.name)
        interpreters_str = {sid: ", ".join(names) for sid, names in interp_map.items()}

        isrc_map = {}
        if song_ids:
            rows = (
                session_db.query(SongISRCCode.song_id, SongISRCCode.code)
                .filter(SongISRCCode.song_id.in_(song_ids))
                .filter(func.upper(SongISRCCode.kind) == "AUDIO")
                .filter(SongISRCCode.is_primary == True)
                .all()
            )
            for sid, code in rows:
                if sid and code and sid not in isrc_map:
                    isrc_map[sid] = _norm_isrc(code)

        album_code_map = _first_album_code_display_map(session_db, album_ids)

        commitment_rows = None

        def _pick_cached(concept_variants, material_date=None):
            nonlocal commitment_rows
            if commitment_rows is None:
                commitment_rows = (
                    session_db.query(ArtistContractCommitment, ArtistContract)
                    .join(ArtistContract, ArtistContractCommitment.contract_id == ArtistContract.id)
                    .filter(ArtistContract.artist_id == bid)
                    .all()
                )
            return _pick_artist_commitment_from_rows(commitment_rows, concept_variants, material_date=material_date, as_of_date=sem_end)

        for song in songs:
            primary_artist = song.artists[0] if getattr(song, "artists", None) else None
            if not primary_artist or getattr(primary_artist, "id", None) != bid:
                continue
            g = song_gross_map.get(song.id, 0.0)
            n = song_net_map.get(song.id, 0.0)
            if abs(float(g)) < 1e-9 and abs(float(n)) < 1e-9:
                continue
            commitment, _contract = _pick_cached(_royalty_concept_variants_for_material(song), material_date=getattr(song, "release_date", None))
            pct = float(getattr(commitment, "pct_artist", 0) or 0) if commitment else 0.0
            base = _norm_contract_base(getattr(commitment, "base", "GROSS") or "GROSS") if commitment else "GROSS"
            income = n if base in ("NET", "PROFIT") else g
            amount = float(income) * (pct / 100.0)
            badges = ["Canción"]
            ownership_label = _royalty_item_ownership_label(song)
            if ownership_label:
                badges.append(ownership_label)
            item_payload = {
                "item_kind": "SONG",
                "item_type_label": "Canción",
                "detail_url": url_for("discografica_song_detail", song_id=str(song.id), tab="royalties"),
                "cover_url": song.cover_url,
                "item_id": str(song.id),
                "title": song.title,
                "subtitle": (interpreters_str.get(song.id) or "").strip() or ", ".join([a.name for a in getattr(song, "artists", [])]) or "",
                "code": _norm_isrc(isrc_map.get(song.id) or song.isrc) or "—",
                "code_label": "ISRC",
                "release_date": song.release_date.strftime("%d/%m/%Y") if song.release_date else "",
                "income": float(income or 0),
                "pct": pct,
                "amount": amount,
                "badges": badges,
                "sort_title": (song.title or "").lower(),
            }
            if bool(getattr(song, 'is_distribution', False)):
                item_payload = _apply_distribution_deductions(item_payload, song_deduction_map.get(str(song.id)) or [])
            _append_item(bucket, item_payload)

        for album in albums:
            if getattr(album, "artist_id", None) != bid:
                continue
            g = album_gross_map.get(album.id, 0.0)
            n = album_net_map.get(album.id, 0.0)
            if abs(float(g)) < 1e-9 and abs(float(n)) < 1e-9:
                continue
            commitment, _contract = _pick_cached(_royalty_concept_variants_for_material(album), material_date=getattr(album, "release_date", None))
            pct = float(getattr(commitment, "pct_artist", 0) or 0) if commitment else 0.0
            base = _norm_contract_base(getattr(commitment, "base", "GROSS") or "GROSS") if commitment else "GROSS"
            income = n if base in ("NET", "PROFIT") else g
            amount = float(income) * (pct / 100.0)
            badges = ["Disco"]
            ownership_label = _royalty_item_ownership_label(album)
            if ownership_label:
                badges.append(ownership_label)
            code_display = album_code_map.get(str(album.id)) or ((_clean_csv_cell(getattr(album, "upc_code", None)) or "").strip()) or "—"
            subtitle_bits = [artist.name]
            kind_label = _album_kind_label(album)
            if kind_label:
                subtitle_bits.append(kind_label)
            item_payload = {
                "item_kind": "ALBUM",
                "item_type_label": "Disco",
                "detail_url": url_for("discografica_album_detail", album_id=str(album.id), tab="informacion"),
                "cover_url": album.cover_url,
                "item_id": str(album.id),
                "title": album.title,
                "subtitle": " · ".join([bit for bit in subtitle_bits if bit]),
                "code": code_display,
                "code_label": "Código",
                "release_date": album.release_date.strftime("%d/%m/%Y") if album.release_date else "",
                "income": float(income or 0),
                "pct": pct,
                "amount": amount,
                "badges": badges,
                "sort_title": (album.title or "").lower(),
            }
            if bool(getattr(album, 'is_distribution', False)):
                item_payload = _apply_distribution_deductions(item_payload, album_deduction_map.get(str(album.id)) or [])
            _append_item(bucket, item_payload)

    else:
        promoter = session_db.get(Promoter, bid)
        if not promoter:
            return None
        display_name = (promoter.nick or ((promoter.first_name or "") + " " + (promoter.last_name or ""))).strip() or "Beneficiario"
        delivery = _beneficiary_email_delivery_data(session_db, "PROMOTER", bid)
        bucket = {
            "kind": "PROMOTER",
            "id": str(bid),
            "name": display_name,
            "photo_url": getattr(promoter, "logo_url", None),
            "kind_label": "Beneficiario",
            "items": [],
            "total_income": 0.0,
            "total_amount": 0.0,
            "liquidation_status": None,
            "liquidation_label": None,
            "liquidation_color": None,
            "contact_email": (delivery.get("primary_email") or _beneficiary_contact_email(session_db, "PROMOTER", bid) or ""),
            "default_recipients": list(delivery.get("default_recipients") or []),
            "suggested_recipients": list(delivery.get("suggested_recipients") or []),
            "extra_email_rows": list(delivery.get("extra_rows") or []),
            "can_send_email": bool((delivery.get("default_recipients") or []) or (delivery.get("suggested_recipients") or [])),
        }

        song_ids = [
            sid
            for (sid,) in (
                session_db.query(SongRevenueEntry.song_id)
                .join(SongRoyaltyBeneficiary, SongRoyaltyBeneficiary.song_id == SongRevenueEntry.song_id)
                .filter(SongRoyaltyBeneficiary.promoter_id == bid)
                .filter(
                    or_(
                        and_(func.upper(SongRevenueEntry.period_type) == "SEMESTER", SongRevenueEntry.period_start == sem_start),
                        and_(func.upper(SongRevenueEntry.period_type) == "MONTH", SongRevenueEntry.period_start.in_(month_starts)),
                    )
                )
                .distinct()
                .all()
            )
            if sid
        ]
        album_ids = [
            aid
            for (aid,) in (
                session_db.query(AlbumRevenueEntry.album_id)
                .join(AlbumRoyaltyBeneficiary, AlbumRoyaltyBeneficiary.album_id == AlbumRevenueEntry.album_id)
                .filter(AlbumRoyaltyBeneficiary.promoter_id == bid)
                .filter(
                    or_(
                        and_(func.upper(AlbumRevenueEntry.period_type) == "SEMESTER", AlbumRevenueEntry.period_start == sem_start),
                        and_(func.upper(AlbumRevenueEntry.period_type) == "MONTH", AlbumRevenueEntry.period_start.in_(month_starts)),
                    )
                )
                .distinct()
                .all()
            )
            if aid
        ]

        songs = []
        if song_ids:
            songs = (
                session_db.query(Song)
                .options(selectinload(Song.artists))
                .filter(Song.id.in_(song_ids))
                .order_by(Song.release_date.desc())
                .all()
            )
        albums = []
        if album_ids:
            albums = (
                session_db.query(Album)
                .options(joinedload(Album.artist))
                .filter(Album.id.in_(album_ids))
                .order_by(Album.release_date.desc())
                .all()
            )

        song_lookup = {song.id: song for song in songs}
        album_lookup = {album.id: album for album in albums}
        song_gross_map, song_net_map = _load_song_income_maps(song_ids)
        album_gross_map, album_net_map = _load_album_income_maps(album_ids)

        interp_map = {sid: [] for sid in song_ids}
        if song_ids:
            rows = (
                session_db.query(SongInterpreter)
                .filter(SongInterpreter.song_id.in_(song_ids))
                .order_by(SongInterpreter.song_id.asc(), SongInterpreter.is_main.desc(), SongInterpreter.created_at.asc())
                .all()
            )
            for row in rows:
                if row.song_id in interp_map and row.name:
                    interp_map[row.song_id].append(row.name)
        interpreters_str = {sid: ", ".join(names) for sid, names in interp_map.items()}

        isrc_map = {}
        if song_ids:
            rows = (
                session_db.query(SongISRCCode.song_id, SongISRCCode.code)
                .filter(SongISRCCode.song_id.in_(song_ids))
                .filter(func.upper(SongISRCCode.kind) == "AUDIO")
                .filter(SongISRCCode.is_primary == True)
                .all()
            )
            for sid, code in rows:
                if sid and code and sid not in isrc_map:
                    isrc_map[sid] = _norm_isrc(code)

        album_code_map = _first_album_code_display_map(session_db, album_ids)

        extra_song_rows = []
        if song_ids:
            extra_song_rows = (
                session_db.query(SongRoyaltyBeneficiary)
                .filter(SongRoyaltyBeneficiary.promoter_id == bid)
                .filter(SongRoyaltyBeneficiary.song_id.in_(song_ids))
                .all()
            )
        extra_album_rows = []
        if album_ids:
            extra_album_rows = (
                session_db.query(AlbumRoyaltyBeneficiary)
                .filter(AlbumRoyaltyBeneficiary.promoter_id == bid)
                .filter(AlbumRoyaltyBeneficiary.album_id.in_(album_ids))
                .all()
            )

        for row in extra_song_rows:
            song = song_lookup.get(getattr(row, "song_id", None))
            if not song:
                continue
            g = song_gross_map.get(song.id, 0.0)
            n = song_net_map.get(song.id, 0.0)
            if abs(float(g)) < 1e-9 and abs(float(n)) < 1e-9:
                continue
            base = (getattr(row, "base", "GROSS") or "GROSS").strip().upper()
            if base not in ("GROSS", "NET", "PROFIT"):
                base = "GROSS"
            pct = float(getattr(row, "pct", 0) or 0)
            income = n if base in ("NET", "PROFIT") else g
            amount = float(income) * (pct / 100.0)
            badges = ["Canción"]
            ownership_label = _royalty_item_ownership_label(song)
            if ownership_label:
                badges.append(ownership_label)
            _append_item(
                bucket,
                {
                    "item_kind": "SONG",
                    "item_type_label": "Canción",
                    "detail_url": url_for("discografica_song_detail", song_id=str(song.id), tab="royalties"),
                    "cover_url": song.cover_url,
                "item_id": str(song.id),
                    "title": song.title,
                    "subtitle": (interpreters_str.get(song.id) or "").strip() or ", ".join([a.name for a in getattr(song, "artists", [])]) or "",
                    "code": _norm_isrc(isrc_map.get(song.id) or song.isrc) or "—",
                    "code_label": "ISRC",
                    "release_date": song.release_date.strftime("%d/%m/%Y") if song.release_date else "",
                    "income": float(income or 0),
                    "pct": pct,
                    "amount": amount,
                    "badges": badges,
                    "sort_title": (song.title or "").lower(),
                },
            )

        for row in extra_album_rows:
            album = album_lookup.get(getattr(row, "album_id", None))
            if not album:
                continue
            g = album_gross_map.get(album.id, 0.0)
            n = album_net_map.get(album.id, 0.0)
            if abs(float(g)) < 1e-9 and abs(float(n)) < 1e-9:
                continue
            base = (getattr(row, "base", "GROSS") or "GROSS").strip().upper()
            if base not in ("GROSS", "NET", "PROFIT"):
                base = "GROSS"
            pct = float(getattr(row, "pct", 0) or 0)
            income = n if base in ("NET", "PROFIT") else g
            amount = float(income) * (pct / 100.0)
            badges = ["Disco"]
            ownership_label = _royalty_item_ownership_label(album)
            if ownership_label:
                badges.append(ownership_label)
            code_display = album_code_map.get(str(album.id)) or ((_clean_csv_cell(getattr(album, "upc_code", None)) or "").strip()) or "—"
            album_artist = getattr(album, "artist", None)
            subtitle_bits = [getattr(album_artist, "name", None) or ""]
            kind_label = _album_kind_label(album)
            if kind_label:
                subtitle_bits.append(kind_label)
            _append_item(
                bucket,
                {
                    "item_kind": "ALBUM",
                    "item_type_label": "Disco",
                    "detail_url": url_for("discografica_album_detail", album_id=str(album.id), tab="informacion"),
                    "cover_url": album.cover_url,
                "item_id": str(album.id),
                    "title": album.title,
                    "subtitle": " · ".join([bit for bit in subtitle_bits if bit]),
                    "code": code_display,
                    "code_label": "Código",
                    "release_date": album.release_date.strftime("%d/%m/%Y") if album.release_date else "",
                    "income": float(income or 0),
                    "pct": pct,
                    "amount": amount,
                    "badges": badges,
                    "sort_title": (album.title or "").lower(),
                },
            )

    rec = (
        session_db.query(RoyaltyLiquidation)
        .filter(RoyaltyLiquidation.beneficiary_kind == kind)
        .filter(RoyaltyLiquidation.beneficiary_id == bid)
        .filter(RoyaltyLiquidation.period_start == sem_start)
        .first()
    )
    _apply_royalty_liquidation_meta(bucket, rec, apply_frozen=apply_frozen)

    bucket["items"].sort(key=lambda item: ((item.get("sort_title") or ""), item.get("release_date") or ""))
    return bucket if (bucket.get("items") or []) else None


def _build_royalty_beneficiaries(session_db, sem_start: date, sem_end: date, selected_artist_id=None,
                                 only_beneficiary: tuple[str, str] | None = None,
                                 apply_frozen: bool = True) -> dict:
    selected_artist_id_str = str(selected_artist_id) if selected_artist_id else None

    month_starts = []
    cursor = date(sem_start.year, sem_start.month, 1)
    for _ in range(6):
        month_starts.append(cursor)
        cursor = _add_months(cursor, 1)

    sem_song_ids = [
        sid
        for (sid,) in (
            session_db.query(SongRevenueEntry.song_id)
            .filter(func.upper(SongRevenueEntry.period_type) == "SEMESTER")
            .filter(SongRevenueEntry.period_start == sem_start)
            .distinct()
            .all()
        )
        if sid
    ]
    month_song_ids = [
        sid
        for (sid,) in (
            session_db.query(SongRevenueEntry.song_id)
            .filter(func.upper(SongRevenueEntry.period_type) == "MONTH")
            .filter(SongRevenueEntry.period_start.in_(month_starts))
            .distinct()
            .all()
        )
        if sid
    ]
    song_ids = sorted(set(sem_song_ids + month_song_ids), key=lambda x: str(x))

    sem_album_ids = [
        aid
        for (aid,) in (
            session_db.query(AlbumRevenueEntry.album_id)
            .filter(func.upper(AlbumRevenueEntry.period_type) == "SEMESTER")
            .filter(AlbumRevenueEntry.period_start == sem_start)
            .distinct()
            .all()
        )
        if aid
    ]
    month_album_ids = [
        aid
        for (aid,) in (
            session_db.query(AlbumRevenueEntry.album_id)
            .filter(func.upper(AlbumRevenueEntry.period_type) == "MONTH")
            .filter(AlbumRevenueEntry.period_start.in_(month_starts))
            .distinct()
            .all()
        )
        if aid
    ]
    album_ids = sorted(set(sem_album_ids + month_album_ids), key=lambda x: str(x))

    songs: list[Song] = []
    if song_ids:
        songs = (
            session_db.query(Song)
            .options(selectinload(Song.artists))
            .filter(Song.id.in_(song_ids))
            # Las colaboraciones externas SÍ entran: al artista le corresponde su % (según tipo)
            # sobre el ingreso que nos llega de la compañía (ver _royalty_external_collab_income),
            # y los terceros con % sobre sus ingresos discográficos participan en esa proporción.
            .order_by(Song.release_date.desc())
            .all()
        )

    albums: list[Album] = []
    if album_ids:
        albums = (
            session_db.query(Album)
            .options(joinedload(Album.artist))
            .filter(Album.id.in_(album_ids))
            .order_by(Album.release_date.desc())
            .all()
        )

    sem_song_totals = {
        sid: (Decimal(g or 0), Decimal(n or 0))
        for sid, g, n in (
            session_db.query(
                SongRevenueEntry.song_id,
                func.sum(SongRevenueEntry.gross),
                func.sum(SongRevenueEntry.net),
            )
            .filter(func.upper(SongRevenueEntry.period_type) == "SEMESTER")
            .filter(SongRevenueEntry.period_start == sem_start)
            .group_by(SongRevenueEntry.song_id)
            .all()
        )
        if sid
    }
    month_song_totals = {
        sid: (Decimal(g or 0), Decimal(n or 0))
        for sid, g, n in (
            session_db.query(
                SongRevenueEntry.song_id,
                func.sum(SongRevenueEntry.gross),
                func.sum(SongRevenueEntry.net),
            )
            .filter(func.upper(SongRevenueEntry.period_type) == "MONTH")
            .filter(SongRevenueEntry.period_start.in_(month_starts))
            .group_by(SongRevenueEntry.song_id)
            .all()
        )
        if sid
    }
    song_gross_map = {}
    song_net_map = {}
    for sid in song_ids:
        if sid in sem_song_totals:
            g, n = sem_song_totals[sid]
        else:
            g, n = month_song_totals.get(sid, (Decimal(0), Decimal(0)))
        song_gross_map[sid] = float(g or 0)
        song_net_map[sid] = float(n or 0)

    sem_album_totals = {
        aid: (Decimal(g or 0), Decimal(n or 0))
        for aid, g, n in (
            session_db.query(
                AlbumRevenueEntry.album_id,
                func.sum(AlbumRevenueEntry.gross),
                func.sum(AlbumRevenueEntry.net),
            )
            .filter(func.upper(AlbumRevenueEntry.period_type) == "SEMESTER")
            .filter(AlbumRevenueEntry.period_start == sem_start)
            .group_by(AlbumRevenueEntry.album_id)
            .all()
        )
        if aid
    }
    month_album_totals = {
        aid: (Decimal(g or 0), Decimal(n or 0))
        for aid, g, n in (
            session_db.query(
                AlbumRevenueEntry.album_id,
                func.sum(AlbumRevenueEntry.gross),
                func.sum(AlbumRevenueEntry.net),
            )
            .filter(func.upper(AlbumRevenueEntry.period_type) == "MONTH")
            .filter(AlbumRevenueEntry.period_start.in_(month_starts))
            .group_by(AlbumRevenueEntry.album_id)
            .all()
        )
        if aid
    }
    album_gross_map = {}
    album_net_map = {}
    for aid in album_ids:
        if aid in sem_album_totals:
            g, n = sem_album_totals[aid]
        else:
            g, n = month_album_totals.get(aid, (Decimal(0), Decimal(0)))
        album_gross_map[aid] = float(g or 0)
        album_net_map[aid] = float(n or 0)

    interp_map = {sid: [] for sid in song_ids}
    if song_ids:
        rows = (
            session_db.query(SongInterpreter)
            .filter(SongInterpreter.song_id.in_(song_ids))
            .order_by(SongInterpreter.song_id.asc(), SongInterpreter.is_main.desc(), SongInterpreter.created_at.asc())
            .all()
        )
        for row in rows:
            if row.song_id in interp_map and row.name:
                interp_map[row.song_id].append(row.name)
    interpreters_str = {sid: ", ".join(names) for sid, names in interp_map.items()}

    isrc_map = {}
    if song_ids:
        rows = (
            session_db.query(SongISRCCode.song_id, SongISRCCode.code)
            .filter(SongISRCCode.song_id.in_(song_ids))
            .filter(func.upper(SongISRCCode.kind) == "AUDIO")
            .filter(SongISRCCode.is_primary == True)  # noqa: E712
            .all()
        )
        for sid, code in rows:
            if sid and code and sid not in isrc_map:
                isrc_map[sid] = _norm_isrc(code)

    album_code_map = _first_album_code_display_map(session_db, album_ids)

    song_lookup = {song.id: song for song in songs}
    album_lookup = {album.id: album for album in albums}

    extra_song_rows = []
    if song_ids:
        extra_song_rows = (
            session_db.query(SongRoyaltyBeneficiary)
            .options(joinedload(SongRoyaltyBeneficiary.promoter))
            .filter(SongRoyaltyBeneficiary.song_id.in_(song_ids))
            .all()
        )

    extra_album_rows = []
    if album_ids:
        extra_album_rows = (
            session_db.query(AlbumRoyaltyBeneficiary)
            .options(joinedload(AlbumRoyaltyBeneficiary.promoter))
            .filter(AlbumRoyaltyBeneficiary.album_id.in_(album_ids))
            .all()
        )

    song_deduction_map, album_deduction_map = _build_distribution_deduction_maps(
        session_db,
        song_ids,
        album_ids,
        song_gross_map,
        song_net_map,
        album_gross_map,
        album_net_map,
    )

    liq_rows = (
        session_db.query(RoyaltyLiquidation)
        .filter(RoyaltyLiquidation.period_start == sem_start)
        .all()
    )
    liq_map = {(row.beneficiary_kind, str(row.beneficiary_id)): row for row in liq_rows if row}

    filter_artist_ids = set()
    for song in songs:
        for artist in getattr(song, "artists", []) or []:
            if getattr(artist, "id", None):
                filter_artist_ids.add(artist.id)

    ben_map: dict[tuple[str, str], dict] = {}

    def ensure_benef(kind: str, bid: str, name: str, photo_url: str | None, kind_label: str):
        key = (kind, bid)
        if only_beneficiary and key != only_beneficiary:
            return None
        if key not in ben_map:
            delivery = _beneficiary_email_delivery_data(session_db, kind, bid)
            ben_map[key] = {
                "kind": kind,
                "id": bid,
                "name": name,
                "photo_url": photo_url,
                "kind_label": kind_label,
                "items": [],
                "total_income": 0.0,
                "total_amount": 0.0,
                "liquidation_status": None,
                "liquidation_label": None,
                "liquidation_color": None,
                "contact_email": (delivery.get("primary_email") or _beneficiary_contact_email(session_db, kind, bid) or ""),
                "default_recipients": list(delivery.get("default_recipients") or []),
                "suggested_recipients": list(delivery.get("suggested_recipients") or []),
                "extra_email_rows": list(delivery.get("extra_rows") or []),
                "can_send_email": bool((delivery.get("default_recipients") or []) or (delivery.get("suggested_recipients") or [])),
            }
        return ben_map[key]

    def append_item(bucket: dict | None, item: dict):
        if not bucket:
            return
        bucket["items"].append(item)
        bucket["total_income"] += float(item.get("income") or 0)
        bucket["total_amount"] += float(item.get("amount") or 0)

    for song in songs:
        artist_ids = _royalty_item_artist_ids(song=song)
        if selected_artist_id_str and selected_artist_id_str not in artist_ids:
            continue

        primary_artist = song.artists[0] if getattr(song, "artists", None) else None
        if not primary_artist:
            continue

        g = song_gross_map.get(song.id, 0.0)
        n = song_net_map.get(song.id, 0.0)
        if abs(float(g)) < 1e-9 and abs(float(n)) < 1e-9:
            continue

        commitment, _contract = _pick_artist_commitment(
            session_db,
            primary_artist.id,
            _royalty_concept_variants_for_material(song),
            material_date=getattr(song, "release_date", None),
            as_of_date=sem_end,
        )
        pct = float(getattr(commitment, "pct_artist", 0) or 0) if commitment else 0.0
        base = _norm_contract_base(getattr(commitment, "base", "GROSS") or "GROSS") if commitment else "GROSS"
        income = n if base in ("NET", "PROFIT") else g
        _ext = _royalty_external_collab_income(song, g, n)
        if _ext is not None:
            income = _ext          # colaboración externa: se reparte SOLO lo que nos ingresa la compañía
        amount = float(income) * (pct / 100.0)

        badges = ["Canción"]
        ownership_label = _royalty_item_ownership_label(song)
        if ownership_label:
            badges.append(ownership_label)

        bucket = ensure_benef("ARTIST", str(primary_artist.id), primary_artist.name, getattr(primary_artist, "photo_url", None), "Artista")
        item_payload = {
            "item_kind": "SONG",
            "item_type_label": "Canción",
            "detail_url": url_for("discografica_song_detail", song_id=str(song.id), tab="royalties"),
            "cover_url": song.cover_url,
            "item_id": str(song.id),
            "title": song.title,
            "subtitle": (interpreters_str.get(song.id) or "").strip() or ", ".join([a.name for a in getattr(song, "artists", [])]) or "",
            "code": _norm_isrc(isrc_map.get(song.id) or song.isrc) or "—",
            "code_label": "ISRC",
            "release_date": song.release_date.strftime("%d/%m/%Y") if song.release_date else "",
            "income": float(income or 0),
            "pct": pct,
            "amount": amount,
            "badges": badges,
            "sort_title": (song.title or "").lower(),
        }
        if bool(getattr(song, 'is_distribution', False)):
            item_payload = _apply_distribution_deductions(item_payload, song_deduction_map.get(str(song.id)) or [])
        append_item(bucket, item_payload)

    for row in extra_song_rows:
        song = song_lookup.get(getattr(row, "song_id", None))
        promoter = getattr(row, "promoter", None)
        if not song or not promoter:
            continue

        artist_ids = _royalty_item_artist_ids(song=song)
        if selected_artist_id_str and selected_artist_id_str not in artist_ids:
            continue

        g = song_gross_map.get(song.id, 0.0)
        n = song_net_map.get(song.id, 0.0)
        if abs(float(g)) < 1e-9 and abs(float(n)) < 1e-9:
            continue

        base = (getattr(row, "base", "GROSS") or "GROSS").strip().upper()
        if base not in ("GROSS", "NET", "PROFIT"):
            base = "GROSS"
        pct = float(getattr(row, "pct", 0) or 0)
        income = n if base in ("NET", "PROFIT") else g
        _ext = _royalty_external_collab_income(song, g, n)
        if _ext is not None:
            income = _ext          # colaboración externa: el tercero participa de NUESTRO ingreso
        amount = float(income) * (pct / 100.0)

        badges = ["Canción"]
        ownership_label = _royalty_item_ownership_label(song)
        if ownership_label:
            badges.append(ownership_label)

        display_name = (promoter.nick or ((promoter.first_name or "") + " " + (promoter.last_name or ""))).strip() or "Beneficiario"
        bucket = ensure_benef("PROMOTER", str(promoter.id), display_name, getattr(promoter, "logo_url", None), "Beneficiario")
        append_item(
            bucket,
            {
                "item_kind": "SONG",
                "item_type_label": "Canción",
                "detail_url": url_for("discografica_song_detail", song_id=str(song.id), tab="royalties"),
                "cover_url": song.cover_url,
                "item_id": str(song.id),
                "title": song.title,
                "subtitle": (interpreters_str.get(song.id) or "").strip() or ", ".join([a.name for a in getattr(song, "artists", [])]) or "",
                "code": _norm_isrc(isrc_map.get(song.id) or song.isrc) or "—",
                "code_label": "ISRC",
                "release_date": song.release_date.strftime("%d/%m/%Y") if song.release_date else "",
                "income": float(income or 0),
                "pct": pct,
                "amount": amount,
                "badges": badges,
                "sort_title": (song.title or "").lower(),
            },
        )

    for album in albums:
        artist = getattr(album, "artist", None)
        if not artist:
            artist = session_db.get(Artist, getattr(album, "artist_id", None)) if getattr(album, "artist_id", None) else None
        if not artist:
            continue

        if selected_artist_id_str and str(artist.id) != selected_artist_id_str:
            continue

        g = album_gross_map.get(album.id, 0.0)
        n = album_net_map.get(album.id, 0.0)
        if abs(float(g)) < 1e-9 and abs(float(n)) < 1e-9:
            continue

        commitment, _contract = _pick_artist_commitment(
            session_db,
            artist.id,
            _royalty_concept_variants_for_material(album),
            material_date=getattr(album, "release_date", None),
            as_of_date=sem_end,
        )
        pct = float(getattr(commitment, "pct_artist", 0) or 0) if commitment else 0.0
        base = _norm_contract_base(getattr(commitment, "base", "GROSS") or "GROSS") if commitment else "GROSS"
        income = n if base in ("NET", "PROFIT") else g
        amount = float(income) * (pct / 100.0)

        badges = ["Disco"]
        ownership_label = _royalty_item_ownership_label(album)
        if ownership_label:
            badges.append(ownership_label)

        code_display = album_code_map.get(str(album.id)) or ((_clean_csv_cell(getattr(album, "upc_code", None)) or "").strip()) or "—"
        subtitle_bits = [artist.name]
        kind_label = _album_kind_label(album)
        if kind_label:
            subtitle_bits.append(kind_label)

        bucket = ensure_benef("ARTIST", str(artist.id), artist.name, getattr(artist, "photo_url", None), "Artista")
        item_payload = {
            "item_kind": "ALBUM",
            "item_type_label": "Disco",
            "detail_url": url_for("discografica_album_detail", album_id=str(album.id), tab="informacion"),
            "cover_url": album.cover_url,
            "item_id": str(album.id),
            "title": album.title,
            "subtitle": " · ".join([bit for bit in subtitle_bits if bit]),
            "code": code_display,
            "code_label": "Código",
            "release_date": album.release_date.strftime("%d/%m/%Y") if album.release_date else "",
            "income": float(income or 0),
            "pct": pct,
            "amount": amount,
            "badges": badges,
            "sort_title": (album.title or "").lower(),
        }
        if bool(getattr(album, 'is_distribution', False)):
            item_payload = _apply_distribution_deductions(item_payload, album_deduction_map.get(str(album.id)) or [])
        append_item(bucket, item_payload)

    for row in extra_album_rows:
        album = album_lookup.get(getattr(row, "album_id", None))
        promoter = getattr(row, "promoter", None)
        if not album or not promoter:
            continue

        album_artist = getattr(album, "artist", None)
        if not album_artist and getattr(album, "artist_id", None):
            album_artist = session_db.get(Artist, album.artist_id)
        if selected_artist_id_str and str(getattr(album, "artist_id", "")) != selected_artist_id_str:
            continue

        g = album_gross_map.get(album.id, 0.0)
        n = album_net_map.get(album.id, 0.0)
        if abs(float(g)) < 1e-9 and abs(float(n)) < 1e-9:
            continue

        base = (getattr(row, "base", "GROSS") or "GROSS").strip().upper()
        if base not in ("GROSS", "NET", "PROFIT"):
            base = "GROSS"
        pct = float(getattr(row, "pct", 0) or 0)
        income = n if base in ("NET", "PROFIT") else g
        amount = float(income) * (pct / 100.0)

        badges = ["Disco"]
        ownership_label = _royalty_item_ownership_label(album)
        if ownership_label:
            badges.append(ownership_label)

        code_display = album_code_map.get(str(album.id)) or ((_clean_csv_cell(getattr(album, "upc_code", None)) or "").strip()) or "—"
        subtitle_bits = [getattr(album_artist, "name", None) or ""]
        kind_label = _album_kind_label(album)
        if kind_label:
            subtitle_bits.append(kind_label)

        display_name = (promoter.nick or ((promoter.first_name or "") + " " + (promoter.last_name or ""))).strip() or "Beneficiario"
        bucket = ensure_benef("PROMOTER", str(promoter.id), display_name, getattr(promoter, "logo_url", None), "Beneficiario")
        append_item(
            bucket,
            {
                "item_kind": "ALBUM",
                "item_type_label": "Disco",
                "detail_url": url_for("discografica_album_detail", album_id=str(album.id), tab="informacion"),
                "cover_url": album.cover_url,
                "item_id": str(album.id),
                "title": album.title,
                "subtitle": " · ".join([bit for bit in subtitle_bits if bit]),
                "code": code_display,
                "code_label": "Código",
                "release_date": album.release_date.strftime("%d/%m/%Y") if album.release_date else "",
                "income": float(income or 0),
                "pct": pct,
                "amount": amount,
                "badges": badges,
                "sort_title": (album.title or "").lower(),
            },
        )

    for (kind, bid), bucket in ben_map.items():
        rec = liq_map.get((kind, bid))
        _apply_royalty_liquidation_meta(bucket, rec, apply_frozen=apply_frozen)
        bucket["items"].sort(key=lambda item: ((item.get("sort_title") or ""), item.get("release_date") or ""))

    artist_beneficiaries = [
        bucket for (kind, _bid), bucket in ben_map.items()
        if kind == "ARTIST" and (bucket.get("items") or [])
    ]
    other_beneficiaries = [
        bucket for (kind, _bid), bucket in ben_map.items()
        if kind == "PROMOTER" and (bucket.get("items") or [])
    ]
    artist_beneficiaries.sort(key=lambda item: (item.get("name") or "").lower())
    other_beneficiaries.sort(key=lambda item: (item.get("name") or "").lower())

    filter_artists = []
    if filter_artist_ids:
        filter_artists = (
            session_db.query(Artist)
            .filter(Artist.id.in_(list(filter_artist_ids)))
            .order_by(Artist.name.asc())
            .all()
        )

    return {
        "artists": artist_beneficiaries,
        "others": other_beneficiaries,
        "filter_artists": filter_artists,
        "selected_artist_id": selected_artist_id_str or "",
    }


# Estados de una liquidación A FAVOR, en orden, con su color (de azul a verde).
AFAVOR_STATUS_FLOW = [
    ("PENDING", "Pendiente", "afavor-st--pending", "fa-hourglass-half"),
    ("REQUESTED", "Solicitado", "afavor-st--requested", "fa-paper-plane"),
    ("PENDING_INVOICE", "Pendiente de facturación", "afavor-st--pendinv", "fa-file-invoice"),
    ("INVOICED", "Facturado", "afavor-st--invoiced", "fa-file-invoice-dollar"),
    ("COLLECTED", "Cobrado", "afavor-st--collected", "fa-circle-check"),
]
AFAVOR_STATUS_LABELS = {k: l for k, l, _c, _i in AFAVOR_STATUS_FLOW}
AFAVOR_STATUS_CLASSES = {k: c for k, _l, c, _i in AFAVOR_STATUS_FLOW}
AFAVOR_STATUS_ICONS = {k: i for k, _l, _c, i in AFAVOR_STATUS_FLOW}


def _afavor_status_meta(status: str | None) -> dict:
    st = (status or "PENDING").upper()
    if st not in AFAVOR_STATUS_LABELS:
        st = "PENDING"
    return {"key": st, "label": AFAVOR_STATUS_LABELS[st],
            "cls": AFAVOR_STATUS_CLASSES[st], "icon": AFAVOR_STATUS_ICONS[st]}


def _afavor_liquidation_row(session_db, company_id, sem_start: date, sem_end: date, create: bool = False):
    """Fila de estado de la liquidación a favor de una compañía en un semestre."""
    cid = to_uuid(str(company_id)) if company_id else None
    if not cid:
        return None
    rec = (session_db.query(AfavorLiquidation)
           .filter(AfavorLiquidation.company_id == cid,
                   AfavorLiquidation.period_start == sem_start)
           .first())
    if rec is None and create:
        rec = AfavorLiquidation(company_id=cid, period_start=sem_start, period_end=sem_end, status="PENDING")
        session_db.add(rec)
        session_db.flush()
    return rec


def _pies_group_company(session_db):
    """La empresa del grupo del SELLO (PIES). Es la que factura todo lo discográfico: las
    colaboraciones a favor y las liquidaciones de royalties (que se emiten a nombre de PIES, no de
    33 Producciones). Si no hay ninguna con «PIES» en el nombre, cae a la primera del grupo."""
    companies = session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
    for co in companies:
        if "PIES" in (co.name or "").upper():
            return co
    return companies[0] if companies else None


def _afavor_pies_company(session_db):
    """Empresa del grupo que factura las colaboraciones a favor: PIES (siempre la misma)."""
    return _pies_group_company(session_db)


def _build_afavor_groups(session_db, sem_start: date, selected_artist_id=None) -> dict:
    """Royalties «A FAVOR»: lo que nos tienen que liquidar las compañías externas por nuestras
    colaboraciones. Se agrupa por ARTISTA (como las liquidaciones normales) y, dentro, por
    COMPAÑÍA, que es a quien se le solicita la liquidación y quien lleva el estado.

    Los IMPORTES no se muestran aquí: se introducen en «Ingresos». Aquí van los datos de la
    colaboración (portada, artista y colaboradores, fecha de publicación, ISRC y % a favor nuestro).
    """
    sem_end = _semester_range(sem_start.year, 1 if sem_start.month <= 6 else 2)[1]
    songs = (
        session_db.query(Song)
        .options(selectinload(Song.artists))
        .filter(Song.is_external_collab.is_(True))
        .order_by(Song.release_date.desc())
        .all()
    )
    if not songs:
        return {"groups": [], "total": Decimal("0"), "companies": []}
    # Ingresos del semestre (para saber si YA hay importes cargados: de eso depende poder facturar).
    rev = {}
    for sid, gross, net, eid in (
        session_db.query(SongRevenueEntry.song_id, SongRevenueEntry.gross, SongRevenueEntry.net, SongRevenueEntry.id)
        .filter(SongRevenueEntry.song_id.in_([s.id for s in songs]))
        .filter(func.upper(SongRevenueEntry.period_type) == "SEMESTER")
        .filter(SongRevenueEntry.period_start == sem_start)
        .filter(SongRevenueEntry.is_base.is_(True))
        .all()
    ):
        rev[sid] = {"gross": gross or Decimal("0"), "net": net or Decimal("0"), "entry_id": str(eid)}
    comp_ids = {s.external_company_id for s in songs if s.external_company_id}
    comp_map = {}
    if comp_ids:
        for pr in session_db.query(Promoter).filter(Promoter.id.in_(comp_ids)).all():
            comp_map[pr.id] = pr
    # Estado por compañía en este semestre (una sola consulta).
    state_map = {}
    for rec in (session_db.query(AfavorLiquidation)
                .filter(AfavorLiquidation.period_start == sem_start).all()):
        state_map[str(rec.company_id)] = rec

    groups, order = {}, []
    grand = Decimal("0")
    companies_seen = {}
    sel = str(selected_artist_id) if selected_artist_id else None
    for s_row in songs:
        art = s_row.artists[0] if getattr(s_row, "artists", None) else None
        aid = str(art.id) if art else "sin"
        if sel and aid != sel:
            continue
        info = rev.get(s_row.id) or {"gross": Decimal("0"), "net": Decimal("0"), "entry_id": ""}
        base = (getattr(s_row, "our_pct_base", None) or "GROSS").upper()
        amount_base = info["net"] if base == "NET" else info["gross"]
        our_pct = Decimal(str(getattr(s_row, "our_pct", 0) or 0))
        our_amount = (amount_base * our_pct / Decimal("100"))
        grand += our_amount
        company = comp_map.get(s_row.external_company_id)
        company_id = str(company.id) if company is not None else ""
        rec = state_map.get(company_id)
        g = groups.get(aid)
        if g is None:
            g = {
                "artist_id": aid if art else "",
                "artist_name": (art.name if art else "Sin artista"),
                "artist_photo": ((getattr(art, "photo_url", "") or "") if art else ""),
                "companies": [],       # bloques por compañía (cada uno con su estado)
                "items": [],           # todas las canciones del artista (compat)
                "total": Decimal("0"),
            }
            groups[aid] = g
            order.append(aid)
        # Colaboradores: el resto de artistas de la canción + el campo libre.
        others = [a.name for a in (getattr(s_row, "artists", None) or [])[1:] if getattr(a, "name", None)]
        if (getattr(s_row, "collaborator", None) or "").strip():
            others.append(s_row.collaborator.strip())
        item = {
            "song_id": str(s_row.id),
            "title": s_row.title,
            "cover_url": (getattr(s_row, "cover_url", None) or ""),
            "artist_name": (art.name if art else ""),
            "collaborators": ", ".join(others),
            "release_date": (s_row.release_date.strftime("%d/%m/%Y") if getattr(s_row, "release_date", None) else ""),
            "isrc": (getattr(s_row, "isrc", None) or ""),
            "company": (_promoter_display_name(company) or company.nick or "") if company is not None else "",
            "company_id": company_id,
            "our_pct": our_pct,
            "base": base,
            "base_label": ("Neto" if base == "NET" else "Bruto"),
            "has_income": bool(info["entry_id"]) and (info["gross"] or info["net"]),
            "our_amount": our_amount,
        }
        g["items"].append(item)
        g["total"] += our_amount
        # Bloque de la compañía dentro del artista.
        block = next((c for c in g["companies"] if c["company_id"] == company_id), None)
        if block is None:
            block = {
                "company_id": company_id,
                "company_name": item["company"] or "Sin compañía",
                "company_logo": ((company.logo_url or "") if company is not None else ""),
                "status": _afavor_status_meta(getattr(rec, "status", None)),
                "liquidation_id": (str(rec.id) if rec is not None else ""),
                "invoice_url": (getattr(rec, "invoice_url", None) or "") if rec is not None else "",
                "invoice_sent_at": (getattr(rec, "invoice_sent_at", None) if rec is not None else None),
                "requested_at": (getattr(rec, "requested_at", None) if rec is not None else None),
                "songs": [],
                "has_income": False,
            }
            g["companies"].append(block)
        block["songs"].append(item)
        if item["has_income"]:
            block["has_income"] = True
        if company_id and company_id not in companies_seen:
            companies_seen[company_id] = {
                "company_id": company_id,
                "name": item["company"],
                "logo_url": ((company.logo_url or "") if company is not None else ""),
                "status": _afavor_status_meta(getattr(rec, "status", None)),
            }
    return {
        "groups": [groups[a] for a in order],
        "total": grand,
        "companies": list(companies_seen.values()),
        "period_start": sem_start,
        "period_end": sem_end,
    }


def _get_royalty_liquidation_beneficiary_data(session_db, kind: str, beneficiary_id, sem_year: int, sem_half: int,
                                             apply_frozen: bool = True) -> tuple[dict, date, date, UUID]:
    kind = (kind or "").strip().upper()
    if kind not in ("ARTIST", "PROMOTER"):
        raise ValueError("Beneficiario inválido")

    sem_start, sem_end = _semester_range(sem_year, sem_half)
    bid = to_uuid(beneficiary_id)
    if not bid:
        raise ValueError("Beneficiario inválido")

    beneficiary = _build_royalty_single_beneficiary(session_db, sem_start, sem_end, kind, bid,
                                                   apply_frozen=apply_frozen)
    if not beneficiary:
        payload = _build_royalty_beneficiaries(session_db, sem_start, sem_end, only_beneficiary=(kind, str(bid)),
                                               apply_frozen=apply_frozen)
        for row in (payload.get("artists") or []) + (payload.get("others") or []):
            if row.get("kind") == kind and row.get("id") == str(bid):
                beneficiary = row
                break
    if not beneficiary:
        raise LookupError("No hay datos de royalties para este beneficiario y semestre.")

    return beneficiary, sem_start, sem_end, bid


def _build_royalty_liquidation_pdf_bytes(session_db, kind: str, beneficiary_id, sem_year: int, sem_half: int,
                                         touch_liquidation: bool = True, use_frozen: bool = True) -> tuple[bytes, str, dict]:
    """PDF de la liquidación.

    ⚠️ `use_frozen=True` (lo normal en todo lo que NO es generar): se usa lo CONGELADO al generarla,
    para que el PDF que se ve, se envía o se descarga después sea exactamente el mismo aunque los
    ingresos hayan cambiado. Al GENERAR se llama con `use_frozen=False` (datos en vivo) y se congela.
    """
    kind = (kind or "").strip().upper()
    sem_start, sem_end = _semester_range(sem_year, sem_half)
    bid = to_uuid(beneficiary_id)
    if not bid:
        raise ValueError("Beneficiario inválido")

    # ⚠️ EL CONGELADO SE BUSCA PRIMERO. Antes se calculaba SIEMPRE la liquidación con los ingresos de
    # HOY y solo después se sustituía por el congelado: además de ser el cálculo más caro de la
    # aplicación, hacía que una liquidación ya generada NO se pudiera ver si esos ingresos habían
    # cambiado o desaparecido (saltaba «no hay datos») — y cualquier fallo en el reemplazo dejaba a la
    # vista los importes de hoy, que es justo lo que no puede pasar.
    beneficiary = None
    if use_frozen:
        _rec_prev = (session_db.query(RoyaltyLiquidation)
                     .filter(RoyaltyLiquidation.beneficiary_kind == kind,
                             RoyaltyLiquidation.beneficiary_id == bid,
                             RoyaltyLiquidation.period_start == sem_start).first())
        beneficiary = _royalty_frozen_beneficiary(_rec_prev)
    if beneficiary is None:
        # `apply_frozen=False`: aquí se quieren los datos DE AHORA. Si no, generar una liquidación
        # nueva volvía a congelar los importes viejos y nunca se actualizaba.
        beneficiary, sem_start, sem_end, bid = _get_royalty_liquidation_beneficiary_data(
            session_db,
            kind,
            beneficiary_id,
            sem_year,
            sem_half,
            apply_frozen=False,
        )

    if touch_liquidation:
        now_dt = datetime.now(TZ_MADRID)
        rec = (
            session_db.query(RoyaltyLiquidation)
            .filter(RoyaltyLiquidation.beneficiary_kind == kind)
            .filter(RoyaltyLiquidation.beneficiary_id == bid)
            .filter(RoyaltyLiquidation.period_start == sem_start)
            .first()
        )
        # ⚠️ LO GENERADO NO SE VUELVE A CONGELAR. Enviar la liquidación o descargar su PDF también
        # pasaban por aquí con `touch_liquidation=True`, así que a una liquidación YA generada se le
        # movía la fecha de generación y se le apuntaba un evento «regenerada» que no había ocurrido.
        # Congelar es solo del acto de GENERAR (`use_frozen=False`).
        if rec is not None and use_frozen and _royalty_frozen_beneficiary(rec):
            rec.period_end = sem_end
            rec.updated_at = now_dt
            session_db.commit()
            touch_liquidation = False
        regenerada = False
        if not touch_liquidation:
            pass
        elif rec:
            regenerada = bool(_royalty_frozen_beneficiary(rec))
            rec.period_end = sem_end
            rec.generated_at = now_dt
            rec.updated_at = now_dt
            if not getattr(rec, "status", None):
                rec.status = "GENERATED"
        else:
            rec = RoyaltyLiquidation(
                beneficiary_kind=kind,
                beneficiary_id=bid,
                period_start=sem_start,
                period_end=sem_end,
                status="GENERATED",
                generated_at=now_dt,
                updated_at=now_dt,
            )
            session_db.add(rec)
            session_db.flush()
        # Generar CONGELA los datos: a partir de aquí la liquidación no cambia aunque cambien los
        # ingresos (hasta que se genere una nueva).
        if touch_liquidation:
            _royalty_freeze(session_db, rec, beneficiary, regenerada=regenerada)
            session_db.commit()

    from reportlab.lib.pagesizes import A4
    from reportlab.lib.units import cm
    from reportlab.lib import colors
    from reportlab.lib.utils import ImageReader
    from reportlab.pdfbase.pdfmetrics import stringWidth
    from reportlab.pdfgen import canvas

    def _clean_filename(value: str) -> str:
        safe = (value or "").strip()
        allowed = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_ "
        safe = "".join(ch for ch in safe if ch in allowed)
        safe = "_".join([part for part in safe.split() if part])
        return safe or "beneficiario"

    def _eur(value) -> str:
        try:
            return f"{float(value):,.2f} EUR".replace(",", "X").replace(".", ",").replace("X", ".")
        except Exception:
            return "0,00 EUR"

    def _wrap_text(text_value: str, max_width: float, font_name: str, font_size: float, max_lines: int = 1) -> list[str]:
        txt = (text_value or "").strip()
        if not txt:
            return []
        words = txt.split()
        if not words:
            return []
        lines: list[str] = []
        current = words[0]
        used_count = 1
        for word in words[1:]:
            candidate = f"{current} {word}"
            if stringWidth(candidate, font_name, font_size) <= max_width:
                current = candidate
                used_count += 1
            else:
                lines.append(current)
                current = word
                used_count += 1
                if len(lines) >= max_lines:
                    break
        if len(lines) < max_lines and current:
            lines.append(current)
        if len(lines) > max_lines:
            lines = lines[:max_lines]
        full_joined = " ".join(words)
        current_joined = " ".join(lines)
        if len(lines) == max_lines and current_joined != full_joined:
            line = lines[-1]
            ellipsis = "..."
            while line and stringWidth(line + ellipsis, font_name, font_size) > max_width:
                line = line[:-1]
            lines[-1] = (line.rstrip() + ellipsis) if line else ellipsis
        return lines

    def _truncate(text_value: str, max_width: float, font_name: str, font_size: float) -> str:
        lines = _wrap_text(text_value, max_width, font_name, font_size, max_lines=1)
        return lines[0] if lines else ""

    def _cache_dir() -> str:
        cache_dir = os.path.join(tempfile.gettempdir(), "radio_spins_royalty_pdf_cache")
        os.makedirs(cache_dir, exist_ok=True)
        return cache_dir

    def _cleanup_cache(folder: str, max_age_seconds: int = 7 * 24 * 3600):
        try:
            now_ts = datetime.now().timestamp()
            for name in os.listdir(folder):
                if not name.lower().endswith('.pdf'):
                    continue
                fp = os.path.join(folder, name)
                try:
                    if (now_ts - os.path.getmtime(fp)) > max_age_seconds:
                        os.remove(fp)
                except Exception:
                    pass
        except Exception:
            pass

    def _payload_signature(pies_logo_url: str | None, pies_tax_info: str | None) -> str:
        payload = {
            "renderer": "royalty_pdf_v8",
            "kind": beneficiary.get("kind"),
            "id": beneficiary.get("id"),
            "name": beneficiary.get("name"),
            "period": [sem_start.isoformat(), sem_end.isoformat()],
            "logo": pies_logo_url or "",
            "tax": pies_tax_info or "",
            "total": round(float(beneficiary.get("total_amount") or 0), 4),
            "items": [
                {
                    "item_kind": item.get("item_kind"),
                    "cover_url": item.get("cover_url") or "",
                    "title": item.get("title") or "",
                    "subtitle": item.get("subtitle") or "",
                    "code": item.get("code") or "",
                    "release_date": item.get("release_date") or "",
                    "income": round(float(item.get("income") or 0), 4),
                    "pct": round(float(item.get("pct") or 0), 4),
                    "amount": round(float(item.get("amount") or 0), 4),
                    "amount_before_deductions": round(float(item.get("amount_before_deductions") or 0), 4),
                    "deduction_total": round(float(item.get("deduction_total") or 0), 4),
                    "deductions": [
                        {
                            "name": (row.get("name") or ""),
                            "amount": round(float(row.get("amount") or 0), 4),
                            "pct": round(float(row.get("pct") or 0), 4),
                            "base": (row.get("base") or ""),
                        }
                        for row in (item.get("deductions") or [])
                    ],
                    "badges": item.get("badges") or [],
                }
                for item in (beneficiary.get("items") or [])
            ],
        }
        raw = json.dumps(payload, ensure_ascii=False, sort_keys=True, default=str).encode("utf-8")
        return hashlib.sha256(raw).hexdigest()

    def _cache_path(signature: str) -> str:
        return os.path.join(_cache_dir(), f"{signature}.pdf")

    def _read_cached_pdf(signature: str) -> bytes | None:
        fp = _cache_path(signature)
        if not os.path.exists(fp):
            return None
        try:
            with open(fp, 'rb') as fh:
                return fh.read()
        except Exception:
            return None

    def _write_cached_pdf(signature: str, pdf_bytes: bytes):
        folder = _cache_dir()
        _cleanup_cache(folder)
        fp = _cache_path(signature)
        tmp = fp + '.tmp'
        try:
            with open(tmp, 'wb') as fh:
                fh.write(pdf_bytes)
            os.replace(tmp, fp)
        except Exception:
            try:
                if os.path.exists(tmp):
                    os.remove(tmp)
            except Exception:
                pass

    def _read_bytes_limited(url: str, max_bytes: int = 12 * 1024 * 1024) -> bytes | None:
        for timeout_sec, read_limit in ((4, max_bytes), (8, max(max_bytes, 18 * 1024 * 1024))):
            try:
                req = Request(url, headers={"User-Agent": "Mozilla/5.0", "Accept": "image/*,*/*;q=0.8"})
                with urlopen(req, timeout=timeout_sec) as resp:
                    content_length = None
                    try:
                        content_length = int(resp.headers.get('Content-Length') or 0) or None
                    except Exception:
                        content_length = None
                    if content_length and content_length > read_limit:
                        continue
                    chunks = []
                    total = 0
                    while True:
                        chunk = resp.read(262144)
                        if not chunk:
                            break
                        total += len(chunk)
                        if total > read_limit:
                            chunks = []
                            break
                        chunks.append(chunk)
                    if chunks:
                        return b"".join(chunks)
            except Exception:
                continue
        return None

    def _supabase_storage_ref_from_url(url: str | None) -> tuple[str, str] | None:
        if not url or not isinstance(url, str) or not url.startswith(("http://", "https://")):
            return None
        try:
            parsed = urlsplit(url)
            path = parsed.path or ''
            match = re.search(r"/storage/v1/object/(?:public|authenticated|sign)/([^/]+)/(.+)$", path)
            if not match:
                return None
            bucket = unquote((match.group(1) or '').strip())
            object_path = unquote((match.group(2) or '').strip())
            if not bucket or not object_path:
                return None
            return bucket, object_path
        except Exception:
            return None

    def _download_supabase_image(bucket: str, object_path: str, max_px: int, *, transformed: bool = True) -> bytes | None:
        try:
            client = supabase_client()
            options = {}
            if transformed:
                options = {
                    "transform": {
                        "width": int(max_px),
                        "height": int(max_px),
                        "resize": "contain",
                        "quality": 78,
                        "format": "origin",
                    }
                }
            data = client.storage.from_(bucket).download(object_path, options)
            if isinstance(data, (bytes, bytearray)):
                if len(data) > (24 * 1024 * 1024):
                    return None
                return bytes(data)
        except Exception:
            return None
        return None

    def _iter_image_sources(url: str | None, max_px: int):
        if not url:
            return
        seen: set[tuple] = set()
        ref = _supabase_storage_ref_from_url(url)
        if ref:
            bucket, object_path = ref
            for source in (
                ("supabase", bucket, object_path, max_px, True),
                ("supabase", bucket, object_path, max_px, False),
            ):
                if source not in seen:
                    seen.add(source)
                    yield source
            transformed_url = _maybe_apply_remote_thumb_params(url, max_px)
            if transformed_url and transformed_url != url:
                source = ("remote", transformed_url, min(4 * 1024 * 1024, max(2 * 1024 * 1024, max_px * max_px * 3)))
                if source not in seen:
                    seen.add(source)
                    yield source
        if isinstance(url, str) and url.startswith(("http://", "https://")):
            source = ("remote", url, 18 * 1024 * 1024)
            if source not in seen:
                seen.add(source)
                yield source
        else:
            source = ("local", url)
            if source not in seen:
                yield source

    def _maybe_apply_remote_thumb_params(url: str | None, max_px: int) -> str | None:
        if not url or not isinstance(url, str) or not url.startswith(("http://", "https://")):
            return None
        try:
            parsed = urlsplit(url)
            if '/storage/v1/object/' not in (parsed.path or ''):
                return None
            params = parse_qs(parsed.query, keep_blank_values=True)
            params.setdefault('width', [str(int(max_px))])
            params.setdefault('height', [str(int(max_px))])
            params.setdefault('resize', ['contain'])
            params.setdefault('quality', ['78'])
            new_query = urlencode(params, doseq=True)
            return urlunsplit((parsed.scheme, parsed.netloc, parsed.path, new_query, parsed.fragment))
        except Exception:
            return None

    image_asset_cache: dict[tuple[str, int], dict | None] = {}

    def _image_asset(url: str | None, max_px: int) -> dict | None:
        if not url:
            return None
        key = (url, max_px)
        if key in image_asset_cache:
            return image_asset_cache[key]
        try:
            raw = None
            for source in _iter_image_sources(url, max_px):
                source_type = source[0]
                if source_type == 'supabase':
                    _, bucket, object_path, px, transformed = source
                    raw = _download_supabase_image(bucket, object_path, px, transformed=transformed)
                elif source_type == 'remote':
                    _, remote_url, max_bytes = source
                    raw = _read_bytes_limited(remote_url, max_bytes=max_bytes)
                else:
                    _, local_path = source
                    with open(local_path, 'rb') as fh:
                        raw = fh.read()
                if raw:
                    break
            if not raw:
                image_asset_cache[key] = None
                return None

            if PILLOW_AVAILABLE and PILImage is not None:
                bio = BytesIO(raw)
                with PILImage.open(bio) as img:
                    try:
                        img.seek(0)
                    except Exception:
                        pass
                    img = ImageOps.exif_transpose(img) if ImageOps is not None else img
                    has_alpha = False
                    try:
                        has_alpha = ('A' in (img.getbands() or ())) or ('transparency' in (getattr(img, 'info', {}) or {}))
                    except Exception:
                        has_alpha = False
                    if has_alpha:
                        if img.mode != "RGBA":
                            img = img.convert("RGBA")
                    elif img.mode not in ("RGB", "L"):
                        img = img.convert("RGB")
                    resampling = getattr(getattr(PILImage, "Resampling", PILImage), "LANCZOS", getattr(PILImage, "LANCZOS", 1))
                    img.thumbnail((max_px, max_px), resampling)
                    out = BytesIO()
                    save_format = "PNG" if has_alpha or img.mode == "RGBA" else ("JPEG" if img.mode == "RGB" else "PNG")
                    save_kwargs = {"format": save_format, "optimize": True}
                    if save_format == "JPEG":
                        save_kwargs["quality"] = 76
                    img.save(out, **save_kwargs)
                    out.seek(0)
                    reader = ImageReader(out)
                    width, height = img.size
                    asset = {"reader": reader, "width": width, "height": height, "handle": out}
            else:
                bio = BytesIO(raw)
                reader = ImageReader(bio)
                width, height = reader.getSize()
                asset = {"reader": reader, "width": width, "height": height, "handle": bio}
            image_asset_cache[key] = asset
            return asset
        except Exception:
            image_asset_cache[key] = None
            return None

    def _draw_contained_image(asset: dict | None, x: float, y: float, box_w: float, box_h: float, pad: float = 0, draw_placeholder: bool = False):
        if draw_placeholder:
            pdf.setFillColor(colors.HexColor('#F4F4F4'))
            pdf.setStrokeColor(colors.HexColor('#DDDDDD'))
            pdf.roundRect(x, y, box_w, box_h, 3, fill=1, stroke=1)
        if not asset:
            return
        try:
            iw = float(asset.get('width') or box_w or 1)
            ih = float(asset.get('height') or box_h or 1)
            avail_w = max(1.0, float(box_w) - (pad * 2))
            avail_h = max(1.0, float(box_h) - (pad * 2))
            scale = min(avail_w / iw, avail_h / ih)
            draw_w = max(1.0, iw * scale)
            draw_h = max(1.0, ih * scale)
            dx = x + ((box_w - draw_w) / 2.0)
            dy = y + ((box_h - draw_h) / 2.0)
            pdf.drawImage(asset['reader'], dx, dy, width=draw_w, height=draw_h, preserveAspectRatio=True, mask='auto')
        except Exception:
            return

    def _song_cover_material_map(song_ids: list[UUID]) -> dict[str, str]:
        result: dict[str, str] = {}
        if not song_ids:
            return result
        rows = (
            session_db.query(SongMaterial.song_id, SongMaterial.file_url)
            .filter(SongMaterial.song_id.in_(song_ids))
            .filter(func.upper(SongMaterial.category) == "COVER")
            .order_by(SongMaterial.song_id.asc(), SongMaterial.updated_at.desc(), SongMaterial.created_at.desc())
            .all()
        )
        for sid, file_url in rows:
            key = str(sid)
            if key not in result and file_url:
                result[key] = (file_url or "").strip()
        return result

    def _song_album_cover_map(song_ids: list[UUID]) -> dict[str, str]:
        result: dict[str, str] = {}
        if not song_ids:
            return result
        rows = (
            session_db.query(AlbumTrack.song_id, Album.cover_url, AlbumMaterial.file_url)
            .join(Album, Album.id == AlbumTrack.album_id)
            .outerjoin(
                AlbumMaterial,
                and_(AlbumMaterial.album_id == Album.id, func.upper(AlbumMaterial.category) == "COVER"),
            )
            .filter(AlbumTrack.song_id.in_(song_ids))
            .order_by(AlbumTrack.song_id.asc(), Album.release_date.desc(), AlbumTrack.track_number.asc(), AlbumMaterial.created_at.desc())
            .all()
        )
        for sid, cover_url, material_url in rows:
            key = str(sid)
            if key in result:
                continue
            chosen = (cover_url or material_url or "").strip()
            if chosen:
                result[key] = chosen
        return result

    def _album_cover_material_map(album_ids: list[UUID]) -> dict[str, str]:
        result: dict[str, str] = {}
        if not album_ids:
            return result
        rows = (
            session_db.query(AlbumMaterial.album_id, AlbumMaterial.file_url)
            .filter(AlbumMaterial.album_id.in_(album_ids))
            .filter(func.upper(AlbumMaterial.category) == "COVER")
            .order_by(AlbumMaterial.album_id.asc(), AlbumMaterial.created_at.desc())
            .all()
        )
        for aid, file_url in rows:
            key = str(aid)
            if key not in result and file_url:
                result[key] = (file_url or "").strip()
        return result

    def _enrich_royalty_item_cover_urls(items: list[dict]):
        if not items:
            return
        song_ids: list[UUID] = []
        album_ids: list[UUID] = []
        for item in items:
            item_id = to_uuid(item.get("item_id"))
            if not item_id:
                continue
            if (item.get("item_kind") or "").upper() == "SONG":
                song_ids.append(item_id)
            elif (item.get("item_kind") or "").upper() == "ALBUM":
                album_ids.append(item_id)

        song_material_map = _song_cover_material_map(song_ids)
        song_album_map = _song_album_cover_map(song_ids)
        album_material_map = _album_cover_material_map(album_ids)

        for item in items:
            item_id_str = str(item.get("item_id") or "")
            primary = (item.get("cover_url") or "").strip()
            fallback = ""
            item_kind = (item.get("item_kind") or "").upper()
            if item_kind == "SONG":
                material_cover = (song_material_map.get(item_id_str) or "").strip()
                album_cover = (song_album_map.get(item_id_str) or "").strip()
                if not primary:
                    primary = material_cover or album_cover
                for candidate in (material_cover, album_cover):
                    if candidate and candidate != primary:
                        fallback = candidate
                        break
            elif item_kind == "ALBUM":
                material_cover = (album_material_map.get(item_id_str) or "").strip()
                if not primary:
                    primary = material_cover
                elif material_cover and material_cover != primary:
                    fallback = material_cover
            item["cover_url"] = primary
            item["fallback_cover_url"] = fallback

    pies_company = (
        session_db.query(GroupCompany)
        .filter(func.lower(GroupCompany.name).like('%pies%'))
        .order_by(GroupCompany.name.asc())
        .first()
    )
    pies_tax_info = (getattr(pies_company, 'tax_info', None) or 'poner los datos fiscales de la empresa del grupo PIES').strip()
    pies_logo_url = getattr(pies_company, 'logo_url', None) or None

    _enrich_royalty_item_cover_urls(beneficiary.get('items') or [])

    signature = _payload_signature(pies_logo_url, pies_tax_info)
    filename = f"{_clean_filename(beneficiary.get('name') or 'beneficiario')}_Liquidacion_Royalties_S{sem_half}_{sem_year}.pdf"
    cached_pdf = _read_cached_pdf(signature)
    if cached_pdf:
        return cached_pdf, filename, beneficiary

    buf = BytesIO()
    pdf = canvas.Canvas(buf, pagesize=A4)
    pdf.setPageCompression(1)
    pdf.setTitle(f"Liquidación Royalties {beneficiary.get('name') or ''}")

    page_width, page_height = A4
    left = 1.2 * cm
    right = page_width - (1.2 * cm)
    top = page_height - (1.0 * cm)
    bottom = 1.0 * cm
    footer_reserved = 22

    col_widths = [32, 172, 80, 52, 72, 34, 85]
    col_titles = ["", "Repertorio", "Código", "Fecha", "Ingreso", "%", "A facturar"]
    col_starts = [left]
    for width in col_widths[:-1]:
        col_starts.append(col_starts[-1] + width)

    row_h = 40
    table_header_h = 18
    logo_asset = _image_asset(pies_logo_url, 420)
    if not logo_asset:
        logo_path = os.path.join(app.root_path, 'static', 'img', 'logo.png')
        if os.path.exists(logo_path):
            logo_asset = _image_asset(logo_path, 420)
    beneficiary_asset = _image_asset(beneficiary.get('photo_url'), 160)
    period_str = f"{_semester_label(sem_year, sem_half)} ({sem_start.strftime('%d/%m/%Y')} - {sem_end.strftime('%d/%m/%Y')})"

    def _draw_page_footer(page_no: int):
        pdf.setStrokeColor(colors.HexColor('#DDDDDD'))
        pdf.line(left, bottom - 1, right, bottom - 1)
        pdf.setFillColor(colors.HexColor('#666666'))
        pdf.setFont('Helvetica', 8)
        pdf.drawRightString(right, bottom - 14, f"Página {page_no}")

    def _draw_page_header(page_no: int) -> float:
        y = top
        # Logo de la empresa del grupo (PIES) arriba a la DERECHA (estilo de casa)
        if logo_asset:
            if page_no == 1:
                _draw_contained_image(logo_asset, right - 110, y - 10, 110, 34)
            else:
                _draw_contained_image(logo_asset, right - 70, y - 6, 70, 22)
        # Título centrado (el periodo va en la cabecera del beneficiario, no aquí; sin línea
        # separadora bajo el título, por estética).
        pdf.setFont("Helvetica-Bold", 17 if page_no == 1 else 14)
        pdf.setFillColor(colors.black)
        pdf.drawCentredString(page_width / 2, y, "Liquidación de Royalties")
        y -= 22 if page_no == 1 else 18

        if page_no == 1:
            box_h = 52
            pdf.setFillColor(colors.HexColor('#F8F8F8'))
            pdf.setStrokeColor(colors.HexColor('#DDDDDD'))
            pdf.roundRect(left, y - box_h, right - left, box_h, 6, fill=1, stroke=1)
            _draw_contained_image(beneficiary_asset, left + 8, y - box_h + 7, 38, 38, pad=0, draw_placeholder=True)
            text_x = left + 56
            pdf.setFillColor(colors.black)
            pdf.setFont("Helvetica-Bold", 11)
            pdf.drawString(text_x, y - 18, _truncate((beneficiary.get('name') or 'Beneficiario').strip(), right - text_x - 12, 'Helvetica-Bold', 11))
            pdf.setFont("Helvetica", 9)
            pdf.setFillColor(colors.HexColor('#555555'))
            pdf.drawString(text_x, y - 31, _truncate((beneficiary.get('kind_label') or '').strip(), right - text_x - 12, 'Helvetica', 9))
            pdf.drawString(text_x, y - 42, _truncate(period_str, right - text_x - 12, 'Helvetica', 9))
            y -= box_h + 12

        pdf.setFillColor(colors.HexColor('#F1F1F1'))
        pdf.setStrokeColor(colors.HexColor('#DDDDDD'))
        pdf.rect(left, y - table_header_h + 2, right - left, table_header_h, fill=1, stroke=0)
        pdf.setFillColor(colors.black)
        pdf.setFont("Helvetica-Bold", 8)
        for idx, (x, title, width) in enumerate(zip(col_starts, col_titles, col_widths)):
            if idx == 5:
                pdf.drawCentredString(x + width / 2, y - 10, title)
            elif idx >= 4:
                pdf.drawRightString(x + width - 4, y - 10, title)
            else:
                pdf.drawString(x + 4, y - 10, title)
        pdf.setStrokeColor(colors.HexColor('#DDDDDD'))
        pdf.line(left, y - table_header_h + 1, right, y - table_header_h + 1)
        return y - table_header_h - 2

    def _draw_row(y: float, item: dict, row_index: int) -> float:
        deductions = list(item.get('deductions') or [])
        extra_lines = len(deductions)
        dynamic_row_h = row_h + (extra_lines * 10) + (8 if deductions else 0)
        if row_index % 2 == 0:
            pdf.setFillColor(colors.HexColor('#FAFAFA'))
            pdf.rect(left, y - dynamic_row_h + 2, right - left, dynamic_row_h, fill=1, stroke=0)
        pdf.setStrokeColor(colors.HexColor('#EFEFEF'))
        pdf.line(left, y - dynamic_row_h + 2, right, y - dynamic_row_h + 2)

        cover_asset = _image_asset(item.get('cover_url'), 160)
        if not cover_asset and item.get('fallback_cover_url'):
            cover_asset = _image_asset(item.get('fallback_cover_url'), 160)
        _draw_contained_image(cover_asset, col_starts[0] + 3, y - row_h + 6, 26, 26, pad=0, draw_placeholder=True)

        rep_x = col_starts[1] + 4
        rep_w = col_widths[1] - 8
        title = _truncate(item.get('title') or '', rep_w, 'Helvetica-Bold', 8.4)
        subtitle = _truncate(item.get('subtitle') or '', rep_w, 'Helvetica', 7.2)
        badges = _truncate(' · '.join(item.get('badges') or []), rep_w, 'Helvetica', 6.7)

        pdf.setFillColor(colors.black)
        pdf.setFont('Helvetica-Bold', 8.4)
        pdf.drawString(rep_x, y - 10, title or '—')
        pdf.setFont('Helvetica', 7.2)
        pdf.setFillColor(colors.HexColor('#555555'))
        if subtitle:
            pdf.drawString(rep_x, y - 21, subtitle)
        if badges:
            pdf.setFillColor(colors.HexColor('#777777'))
            pdf.setFont('Helvetica', 6.7)
            pdf.drawString(rep_x, y - 32, badges)

        code_txt = item.get('code') or '—'
        if item.get('item_kind') == 'SONG':
            code_txt = _norm_isrc(code_txt) or '—'
        pdf.setFillColor(colors.black)
        pdf.setFont('Helvetica', 7.6)
        baseline = y - 20
        pdf.drawString(col_starts[2] + 4, baseline, _truncate(code_txt, col_widths[2] - 8, 'Helvetica', 7.6) or '—')
        pdf.drawString(col_starts[3] + 4, baseline, _truncate(item.get('release_date') or '', col_widths[3] - 8, 'Helvetica', 7.6))
        pdf.drawRightString(col_starts[4] + col_widths[4] - 4, baseline, _eur(item.get('income') or 0))
        pdf.drawCentredString(col_starts[5] + col_widths[5] / 2, baseline, f"{float(item.get('pct') or 0):.2f}%")
        pdf.setFont('Helvetica-Bold', 7.8)
        pdf.drawRightString(col_starts[6] + col_widths[6] - 4, baseline, _eur(item.get('amount') or 0))

        if deductions:
            deduction_y = y - row_h - 2
            pdf.setFont('Helvetica', 6.6)
            pdf.setFillColor(colors.HexColor('#7A1F1F'))
            for deduction in deductions:
                ded_text = f"- {deduction.get('name') or 'Beneficiario'}: {_eur(deduction.get('amount') or 0)}"
                pdf.drawString(rep_x, deduction_y, _truncate(ded_text, (col_starts[6] + col_widths[6]) - rep_x - 8, 'Helvetica', 6.6))
                deduction_y -= 10
            pdf.setFont('Helvetica-Bold', 6.8)
            pdf.setFillColor(colors.HexColor('#444444'))
            total_text = f"Total descontado: {_eur(item.get('deduction_total') or 0)} | Total recaudado neto: {_eur(item.get('amount') or 0)}"
            pdf.drawString(rep_x, deduction_y, _truncate(total_text, (col_starts[6] + col_widths[6]) - rep_x - 8, 'Helvetica-Bold', 6.8))

        return y - dynamic_row_h

    y = _draw_page_header(1)
    page_no = 1
    items = beneficiary.get('items') or []

    if not items:
        pdf.setFillColor(colors.HexColor('#666666'))
        pdf.setFont('Helvetica', 10)
        pdf.drawString(left, y - 12, 'No hay líneas de liquidación para este periodo.')
        y -= 28
    else:
        for idx, item in enumerate(items):
            estimated_row_h = row_h + ((len(item.get('deductions') or [])) * 10) + (8 if (item.get('deductions') or []) else 0)
            if y - estimated_row_h < bottom + footer_reserved + 58:
                _draw_page_footer(page_no)
                pdf.showPage()
                page_no += 1
                y = _draw_page_header(page_no)
            y = _draw_row(y, item, idx)

    if y < bottom + footer_reserved + 72:
        _draw_page_footer(page_no)
        pdf.showPage()
        page_no += 1
        y = _draw_page_header(page_no)

    # El importe de la liquidación es la BASE y la factura va con IVA: se dan los tres números para
    # que la liquidación, la factura y el pago digan lo mismo.
    _tot = _royalty_invoice_totals(beneficiary)
    box_w = 230
    box_h = 46 if _tot["vat"] else 26
    pdf.setFillColor(colors.HexColor('#F8F8F8'))
    pdf.setStrokeColor(colors.HexColor('#DDDDDD'))
    pdf.roundRect(right - box_w, y - box_h, box_w, box_h, 6, fill=1, stroke=1)
    pdf.setFillColor(colors.black)
    if _tot["vat"]:
        pdf.setFont('Helvetica', 8.6)
        pdf.drawRightString(right - 8, y - 13, f"Base: {_eur(_tot['net'])}")
        pdf.drawRightString(right - 8, y - 24, f"IVA {float(_tot['vat_pct']):.0f}%: {_eur(_tot['vat'])}")
        pdf.setFont('Helvetica-Bold', 9.5)
        pdf.drawRightString(right - 8, y - 38, f"Total a facturar: {_eur(_tot['gross'])}")
    else:
        pdf.setFont('Helvetica-Bold', 9.5)
        pdf.drawRightString(right - 8, y - 16, f"Total a facturar: {_eur(_tot['gross'])}")
    y -= box_h + 12

    pdf.setFillColor(colors.HexColor('#555555'))
    pdf.setFont('Helvetica', 8.5)
    footer_lines = _wrap_text(f'Emitir factura a nombre de "{pies_tax_info or "poner los datos fiscales de la empresa del grupo PIES"}"', right - left, 'Helvetica', 8.5, max_lines=3)
    for line in footer_lines:
        pdf.drawString(left, y, line)
        y -= 10
    pdf.setFillColor(colors.HexColor('#0b5ed7'))
    pdf.setFont('Helvetica-Bold', 8.5)
    link_text = 'Subir factura'
    pdf.drawString(left, y, link_text)
    pdf.linkURL('https://www.piesrecords.com/facturacion', (left, y - 2, left + stringWidth(link_text, 'Helvetica-Bold', 8.5), y + 8), relative=0)

    _draw_page_footer(page_no)
    pdf.save()
    pdf_bytes = buf.getvalue()
    buf.close()
    _write_cached_pdf(signature, pdf_bytes)
    return pdf_bytes, filename, beneficiary


def _build_royalty_liquidation_email_body(beneficiary: dict, period_label: str, download_url: str, logo_url: str | None, beneficiary_photo_url: str | None, upload_url: str | None = None) -> tuple[str, str]:
    # `upload_url`: landing de la liquidación donde el beneficiario sube su factura.
    upload_url = (upload_url or download_url)
    def _eur(value) -> str:
        try:
            return f"{float(value):,.2f} EUR".replace(",", "X").replace(".", ",").replace("X", ".")
        except Exception:
            return "0,00 EUR"

    ben_name = html.escape(beneficiary.get('name') or 'Beneficiario')
    period_label_safe = html.escape(period_label)
    logo_html = ''
    if logo_url:
        logo_html = f'<img src="{html.escape(logo_url)}" alt="PIES" style="max-width:190px;height:auto;display:inline-block;">'
    photo_html = ''
    if beneficiary_photo_url:
        photo_html = f'<img src="{html.escape(beneficiary_photo_url)}" alt="{ben_name}" style="width:72px;height:72px;object-fit:cover;border-radius:14px;border:1px solid #e5e5e5;background:#fff;display:block;">'

    rows_html = []
    rows_text = []
    for item in beneficiary.get('items') or []:
        title = html.escape(item.get('title') or '—')
        subtitle = html.escape(item.get('subtitle') or '')
        badges = [html.escape(str(b)) for b in (item.get('badges') or []) if b]
        code = html.escape(item.get('code') or '—')
        release_date = html.escape(item.get('release_date') or '—')
        income = _eur(item.get('income') or 0)
        pct = f"{float(item.get('pct') or 0):.2f}%"
        amount = _eur(item.get('amount') or 0)
        cover_url = html.escape((item.get('cover_url') or item.get('fallback_cover_url') or ''))
        cover_html = ''
        if cover_url:
            cover_html = f'<img src="{cover_url}" alt="" style="width:52px;height:52px;object-fit:cover;border-radius:10px;border:1px solid #e5e7eb;background:#fff;display:block;">'
        subtitle_html = f'<div style="font-size:12px;color:#6b7280;margin-top:2px;">{subtitle}</div>' if subtitle else ''
        badges_html = ''
        if badges:
            badge_chunks = ''.join(
                f'<span style="display:inline-block;background:#f3f4f6;border:1px solid #e5e7eb;color:#374151;border-radius:999px;padding:2px 8px;font-size:11px;font-weight:600;margin:4px 6px 0 0;">{badge}</span>'
                for badge in badges
            )
            badges_html = f'<div style="margin-top:4px;">{badge_chunks}</div>'
        repertory_cell = f"""
          <table role="presentation" cellspacing="0" cellpadding="0" border="0" style="border-collapse:collapse;">
            <tr>
              <td style="padding:0 12px 0 0;vertical-align:top;width:56px;">{cover_html}</td>
              <td style="padding:0;vertical-align:top;">
                <div style="font-weight:700;color:#111827;">{title}</div>
                {subtitle_html}
                {badges_html}
              </td>
            </tr>
          </table>
        """
        deductions = list(item.get('deductions') or [])
        deduction_html = ''
        deduction_text = ''
        if deductions:
            deduction_rows = ''.join(
                f'<div style="margin-top:4px;font-size:11px;color:#7a1f1f;">- {html.escape(d.get("name") or "Beneficiario")}: {_eur(d.get("amount") or 0)}</div>'
                for d in deductions
            )
            deduction_html = (
                f'<div style="margin-top:6px;padding-top:6px;border-top:1px dashed #e5e7eb;">{deduction_rows}'
                f'<div style="margin-top:5px;font-size:11px;color:#374151;font-weight:700;">Total descontado: {_eur(item.get("deduction_total") or 0)} · Total recaudado neto: {_eur(item.get("amount") or 0)}</div></div>'
            )
            deduction_text = ' | Descuentos: ' + '; '.join([f'{(d.get("name") or "Beneficiario")}: {_eur(d.get("amount") or 0)}' for d in deductions]) + f' | Total descontado: {_eur(item.get("deduction_total") or 0)}'
        rows_html.append(
            f"""
            <tr>
              <td style="padding:12px;border-top:1px solid #e5e7eb;vertical-align:top;">{repertory_cell}{deduction_html}</td>
              <td style="padding:12px;border-top:1px solid #e5e7eb;vertical-align:top;color:#374151;white-space:nowrap;">{code}</td>
              <td style="padding:12px;border-top:1px solid #e5e7eb;vertical-align:top;color:#374151;white-space:nowrap;">{release_date}</td>
              <td style="padding:12px;border-top:1px solid #e5e7eb;vertical-align:top;color:#374151;text-align:right;white-space:nowrap;">{income}</td>
              <td style="padding:12px;border-top:1px solid #e5e7eb;vertical-align:top;color:#374151;text-align:right;white-space:nowrap;">{pct}</td>
              <td style="padding:12px;border-top:1px solid #e5e7eb;vertical-align:top;color:#111827;text-align:right;white-space:nowrap;font-weight:700;">{amount}</td>
            </tr>
            """
        )
        badge_text = f" [{' | '.join(item.get('badges') or [])}]" if (item.get('badges') or []) else ''
        subtitle_text = f" — {item.get('subtitle')}" if item.get('subtitle') else ''
        rows_text.append(
            f"- {item.get('title') or '—'}{subtitle_text}{badge_text} | Código: {item.get('code') or '—'} | Fecha: {item.get('release_date') or '—'} | Ingreso: {income} | %: {pct} | A facturar: {amount}{deduction_text}"
        )

    if not rows_html:
        rows_html.append('<tr><td colspan="6" style="padding:16px;border-top:1px solid #e5e7eb;color:#6b7280;">No hay líneas de liquidación para este periodo.</td></tr>')

    summary_table = f"""
      <div style="margin:22px 0 18px 0;border:1px solid #e5e7eb;border-radius:16px;overflow:hidden;background:#ffffff;">
        <div style="padding:14px 16px;font-size:16px;font-weight:700;background:#f9fafb;color:#111827;border-bottom:1px solid #e5e7eb;">Liquidación</div>
        <div style="overflow-x:auto;">
          <table role="presentation" cellspacing="0" cellpadding="0" border="0" style="width:100%;border-collapse:collapse;font-size:13px;">
            <thead>
              <tr style="background:#f3f4f6;color:#111827;">
                <th style="padding:12px 12px;text-align:left;font-size:12px;">Repertorio</th>
                <th style="padding:12px 12px;text-align:left;font-size:12px;">Código</th>
                <th style="padding:12px 12px;text-align:left;font-size:12px;">Fecha</th>
                <th style="padding:12px 12px;text-align:right;font-size:12px;">Ingreso</th>
                <th style="padding:12px 12px;text-align:right;font-size:12px;">%</th>
                <th style="padding:12px 12px;text-align:right;font-size:12px;">A facturar</th>
              </tr>
            </thead>
            <tbody>
              {''.join(rows_html)}
            </tbody>
          </table>
        </div>
      </div>
    """

    invoice_name = 'PIES Compañía Discográfica SL | B82165283 | Avenida de Castilla, 2, 28830 San Fernando de Henares'
    _tot_mail = _royalty_invoice_totals(beneficiary)
    total_amount = _eur(_tot_mail['gross'])
    total_desglose = (f"{_eur(_tot_mail['net'])} de base + {float(_tot_mail['vat_pct']):.0f}% de IVA"
                      if _tot_mail['vat'] else "")

    html_body = f"""
    <div style="font-family:Arial,Helvetica,sans-serif;color:#111827;max-width:900px;margin:0 auto;background:#f3f4f6;padding:24px;">
      <div style="text-align:right;margin-bottom:18px;">{logo_html}</div>
      <div style="border:1px solid #e5e7eb;border-radius:18px;padding:24px;background:#ffffff;">
        <div style="font-size:28px;line-height:1.1;font-weight:700;margin-bottom:18px;">Liquidación de royalties</div>
        <div style="display:flex;align-items:center;gap:16px;margin-bottom:18px;">
          <div>{photo_html}</div>
          <div>
            <div style="font-size:20px;font-weight:700;">{ben_name}</div>
            <div style="font-size:14px;color:#6b7280;">{html.escape(beneficiary.get('kind_label') or '')}</div>
          </div>
        </div>
        <div style="font-size:15px;color:#374151;margin-bottom:8px;"><strong>Periodo:</strong> {period_label_safe}</div>
        {summary_table}
        <div style="margin:0 0 18px 0;padding:14px 16px;border:1px solid #e5e7eb;border-radius:14px;background:#f9fafb;text-align:right;">
          <span style="font-size:14px;color:#374151;">Total a facturar:</span>
          <strong style="font-size:18px;color:#111827;margin-left:8px;">{total_amount}</strong>
          {f'<div style="font-size:12.5px;color:#6b7280;margin-top:4px;">{total_desglose}</div>' if total_desglose else ''}
        </div>
        <div style="margin:22px 0 18px 0;">
          <a href="{html.escape(download_url)}" style="display:inline-block;background:#111827;color:#ffffff;text-decoration:none;padding:12px 18px;border-radius:10px;font-weight:700;">Descargar PDF</a>
        </div>
        <div style="font-size:14px;color:#374151;margin-top:18px;">Emitir factura a nombre de &quot;{html.escape(invoice_name)}&quot;</div>
        <div style="margin:16px 0 8px 0;">
          <a href="{html.escape(upload_url)}" style="display:inline-block;background:#E33D48;color:#ffffff;text-decoration:none;padding:12px 18px;border-radius:10px;font-weight:700;">Subir factura</a>
        </div>
        <div style="font-size:14px;color:#374151;margin-top:16px;">Si tiene alguna duda contacte con <a href="mailto:music@piesrecords.com">music@piesrecords.com</a></div>
      </div>
    </div>
    """
    text_rows = "\n".join(rows_text) if rows_text else "- No hay líneas de liquidación para este periodo."
    text_body = (
        f"Liquidación de royalties\n\n"
        f"Beneficiario: {beneficiary.get('name') or 'Beneficiario'}\n"
        f"Periodo: {period_label}\n\n"
        f"Liquidación:\n{text_rows}\n\n"
        f"Total a facturar: {total_amount}" + (f" ({total_desglose})" if total_desglose else "") + "\n\n"
        f"Descargar PDF: {download_url}\n\n"
        f'Emitir factura a nombre de "{invoice_name}"\n'
        f"Subir factura: {upload_url}\n"
        "Si tiene alguna duda contacte con music@piesrecords.com"
    )
    return html_body, text_body


def _royalty_liquidation_record(session_db, kind: str, beneficiary_id, sem_start: date) -> RoyaltyLiquidation | None:
    kind = (kind or '').strip().upper()
    bid = to_uuid(beneficiary_id)
    if kind not in ('ARTIST', 'PROMOTER') or not bid or not sem_start:
        return None
    return (
        session_db.query(RoyaltyLiquidation)
        .filter(RoyaltyLiquidation.beneficiary_kind == kind)
        .filter(RoyaltyLiquidation.beneficiary_id == bid)
        .filter(RoyaltyLiquidation.period_start == sem_start)
        .first()
    )


def _royalty_liquidation_period_label_from_dates(period_start, period_end) -> str:
    start_value = period_start if isinstance(period_start, date) else parse_date(str(period_start or '').strip())
    end_value = period_end if isinstance(period_end, date) else parse_date(str(period_end or '').strip())
    if not start_value or not end_value:
        return ''
    half = 1 if start_value.month <= 6 else 2
    return f"{_semester_label(start_value.year, half)} ({start_value.strftime('%d/%m/%Y')} - {end_value.strftime('%d/%m/%Y')})"


def _royalty_liquidation_subject(sem_year: int, sem_half: int) -> str:
    return f"Liquidación Royalties Semestre {sem_half} {sem_year}"


def _royalty_liquidation_brand_assets(session_db, beneficiary: dict | None = None) -> tuple[str, str]:
    pies_company = (
        session_db.query(GroupCompany)
        .filter(func.lower(GroupCompany.name).like('%pies%'))
        .order_by(GroupCompany.name.asc())
        .first()
    )
    logo_url = (getattr(pies_company, 'logo_url', None) or '').strip() or _external_url_for('static', filename='img/logo.png')

    beneficiary = beneficiary or {}
    fallback_photo = 'img/default_promoter.png' if (beneficiary.get('kind') or '').strip().upper() == 'PROMOTER' else 'img/logo.png'
    photo_url = (beneficiary.get('photo_url') or '').strip() or _external_url_for('static', filename=fallback_photo)
    return logo_url, photo_url


def _wants_json_response() -> bool:
    if request.is_json:
        return True
    accept = (request.headers.get('Accept') or '').lower()
    return 'application/json' in accept


def _royalty_send_response(ok: bool, message: str, *, redirect_url: str, status_code: int = 200, category: str = 'success', extra: dict | None = None):
    payload = {'ok': bool(ok), 'message': message}
    if extra:
        payload.update(extra)
    if _wants_json_response():
        return jsonify(payload), status_code
    flash(message, category if ok else 'danger')
    return redirect(redirect_url)


def _ensure_snapshot_defaults(snapshot: dict | None, fallback: dict | None = None) -> dict:
    payload = dict(snapshot or {})
    fallback = fallback or {}
    for key in ('kind', 'id', 'name', 'kind_label', 'photo_url', 'total_amount', 'total_income'):
        if key not in payload or payload.get(key) in (None, ''):
            if fallback.get(key) not in (None, ''):
                payload[key] = fallback.get(key)
    payload['items'] = list(payload.get('items') or [])
    return payload


def _ensure_royalty_liquidation_row(session_db, kind: str, beneficiary_id, sem_start: date, sem_end: date) -> RoyaltyLiquidation:
    rec = _royalty_liquidation_record(session_db, kind, beneficiary_id, sem_start)
    now_dt = datetime.now(TZ_MADRID)
    if rec:
        rec.period_end = sem_end
        rec.updated_at = now_dt
        return rec
    rec = RoyaltyLiquidation(
        beneficiary_kind=kind,
        beneficiary_id=to_uuid(beneficiary_id),
        period_start=sem_start,
        period_end=sem_end,
        status='GENERATED',
        generated_at=now_dt,
        updated_at=now_dt,
    )
    session_db.add(rec)
    return rec


def _ensure_song_status_row(session_db, song_or_id) -> SongStatus:
    if isinstance(song_or_id, Song):
        song = song_or_id
        sid = song.id
    else:
        sid = song_or_id
        song = session_db.get(Song, sid) if sid else None

    st = session_db.get(SongStatus, sid) if sid else None
    if not st and sid:
        st = SongStatus(song_id=sid)
        if song is not None:
            st.cover_done = bool(getattr(song, "cover_url", None))
            if st.cover_done:
                st.cover_updated_at = datetime.now(TZ_MADRID)
        session_db.add(st)
        session_db.flush()
    return st


def _current_song_isrcs(session_db, song_id, include_song_field: bool = True) -> list[str]:
    sid = to_uuid(song_id) if not isinstance(song_id, UUID) else song_id
    rows = (
        session_db.query(SongISRCCode.code)
        .filter(SongISRCCode.song_id == sid)
        .order_by(SongISRCCode.is_primary.desc(), SongISRCCode.created_at.asc())
        .all()
    )
    codes = [code for (code,) in rows if code]
    if include_song_field:
        song = session_db.get(Song, sid)
        if song and getattr(song, "isrc", None):
            codes.append(song.isrc)
    return _norm_isrc_list(codes)


def _sync_song_agedi_state(session_db, song_id, status_obj: SongStatus | None = None) -> SongStatus:
    sid = to_uuid(song_id) if not isinstance(song_id, UUID) else song_id
    st = status_obj or _ensure_song_status_row(session_db, sid)
    current_codes = set(_current_song_isrcs(session_db, sid))
    registered_codes = set(_norm_isrc_list(getattr(st, "agedi_registered_isrcs", []) or []))

    prev_done = bool(getattr(st, "agedi_done", False))
    st.agedi_done = bool(current_codes) and bool(registered_codes) and current_codes.issubset(registered_codes)

    if prev_done != bool(st.agedi_done):
        st.updated_at = datetime.now(TZ_MADRID)
    session_db.add(st)
    return st


def _mark_song_agedi_registered(session_db, song_id) -> tuple[SongStatus, list[str]]:
    sid = to_uuid(song_id) if not isinstance(song_id, UUID) else song_id
    st = _ensure_song_status_row(session_db, sid)
    current_codes = _current_song_isrcs(session_db, sid)
    st.agedi_registered_isrcs = current_codes
    st.agedi_done = bool(current_codes)
    if current_codes:
        st.agedi_updated_at = datetime.now(TZ_MADRID)
    st.updated_at = datetime.now(TZ_MADRID)
    session_db.add(st)
    return st, current_codes


def _mark_song_sgae_pending_from_editorial_change(session_db, song_id) -> SongStatus:
    sid = to_uuid(song_id) if not isinstance(song_id, UUID) else song_id
    st = _ensure_song_status_row(session_db, sid)
    if bool(getattr(st, "sgae_done", False)):
        st.sgae_done = False
        st.sgae_modification_pending = True
        st.updated_at = datetime.now(TZ_MADRID)
        session_db.add(st)
    return st


def _mark_song_sgae_registered(session_db, song_id) -> SongStatus:
    sid = to_uuid(song_id) if not isinstance(song_id, UUID) else song_id
    st = _ensure_song_status_row(session_db, sid)
    st.sgae_done = True
    st.sgae_modification_pending = False
    st.sgae_updated_at = datetime.now(TZ_MADRID)
    st.updated_at = datetime.now(TZ_MADRID)
    session_db.add(st)
    return st


def _parse_money_decimal(val: str | None) -> Decimal:
    """Parse user/csv money-like strings to Decimal (robust for ES/EN formats)."""
    if val is None:
        return Decimal("0")
    s = str(val).strip()
    if not s:
        return Decimal("0")

    if s.lower() in ("nan", "none", "null", "na"):
        return Decimal("0")

    # remove currency symbols/spaces
    for ch in ("€", "$", "£"):
        s = s.replace(ch, "")
    s = s.replace(" ", "")

    # Detect thousands/decimal separators
    if "," in s and "." in s:
        # If dot appears before comma => ES (1.234,56)
        if s.find(".") < s.find(","):
            s = s.replace(".", "")
            s = s.replace(",", ".")
        else:
            # EN (1,234.56)
            s = s.replace(",", "")
    elif "," in s and "." not in s:
        # ES decimal comma
        s = s.replace(",", ".")

    # Any remaining thousands separators
    # (keep last dot as decimal)
    try:
        dec = Decimal(s)
        return dec if dec.is_finite() else Decimal("0")
    except Exception:
        # fallback: strip anything weird
        cleaned = "".join(ch for ch in s if ch.isdigit() or ch == "." or ch == "-")
        dec = Decimal(cleaned or "0")
        return dec if dec.is_finite() else Decimal("0")


def _money_norm(val) -> Decimal:
    try:
        dec = Decimal(val or 0)
    except Exception:
        dec = Decimal("0")
    if not dec.is_finite():
        return Decimal("0")
    try:
        return dec.quantize(Decimal("0.01"))
    except Exception:
        return dec


def _money_equal(a, b) -> bool:
    return _money_norm(a) == _money_norm(b)


def _clean_csv_cell(val) -> str:
    if val is None:
        return ""
    s = str(val).strip()
    if s.lower() in ("nan", "none", "null"):
        return ""
    return s


def _income_import_store_dir() -> Path:
    base = Path("/tmp/radio_spins_app_income_imports")
    try:
        base.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass

    # limpieza best-effort
    try:
        now_ts = datetime.utcnow().timestamp()
        for p in base.glob("*.json"):
            try:
                if (now_ts - p.stat().st_mtime) > (48 * 3600):
                    p.unlink(missing_ok=True)
            except Exception:
                continue
    except Exception:
        pass

    return base


def _save_income_import_payload(payload: dict, prefix: str = "income") -> str:
    token = f"{prefix}_{_uuid.uuid4().hex}"
    path = _income_import_store_dir() / f"{token}.json"
    with path.open("w", encoding="utf-8") as fh:
        json.dump(payload, fh, ensure_ascii=False, indent=2)
    return token


def _load_income_import_payload(token: str | None) -> dict | None:
    token = (token or "").strip()
    if not token:
        return None
    if not all(ch.isalnum() or ch in ("_", "-") for ch in token):
        return None

    path = _income_import_store_dir() / f"{token}.json"
    if not path.exists():
        return None

    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None


def _delete_income_import_payload(token: str | None) -> None:
    token = (token or "").strip()
    if not token:
        return
    if not all(ch.isalnum() or ch in ("_", "-") for ch in token):
        return
    try:
        (_income_import_store_dir() / f"{token}.json").unlink(missing_ok=True)
    except Exception:
        pass


def _update_url_query(url: str | None, updates: dict[str, object]) -> str:
    raw = (url or "").strip() or url_for("discografica_view", section="ingresos")
    parsed = urlsplit(raw)
    query = dict(parse_qsl(parsed.query, keep_blank_values=True))

    for key, value in (updates or {}).items():
        if value is None or value == "":
            query.pop(key, None)
        else:
            query[str(key)] = str(value)

    return urlunsplit((parsed.scheme, parsed.netloc, parsed.path, urlencode(query, doseq=True), parsed.fragment))


def _infer_income_period_from_url(next_url: str | None) -> tuple[str | None, date | None]:
    raw = (next_url or "").strip()
    if not raw:
        return None, None

    try:
        query = parse_qs(urlsplit(raw).query or "", keep_blank_values=True)
    except Exception:
        return None, None

    view = ((query.get("view") or ["month"])[0] or "month").strip().lower()
    if view == "semester":
        parsed_sem = _parse_semester_key(((query.get("s") or [""])[0] or "").strip())
        if parsed_sem:
            year, half = parsed_sem
            sem_start, _ = _semester_range(year, half)
            return "SEMESTER", sem_start

    month_start = _parse_month_key(((query.get("m") or [""])[0] or "").strip())
    if month_start:
        return "MONTH", month_start

    return None, None


def _serialize_income_song_meta(session_db, song_ids: list[str]) -> dict[str, dict]:
    if not song_ids:
        return {}

    uuids = []
    for sid in song_ids:
        try:
            uuids.append(uuid.UUID(str(sid)))
        except Exception:
            continue

    if not uuids:
        return {}

    meta: dict[str, dict] = {}
    song_rows = (
        session_db.query(Song.id, Song.title, Song.release_date, Song.isrc)
        .filter(Song.id.in_(uuids))
        .all()
    )
    for sid, title, release_date, legacy_isrc in song_rows:
        meta[str(sid)] = {
            "song_id": str(sid),
            "song_title": title or "",
            "release_date": release_date.isoformat() if release_date else "",
            "display_isrc": _norm_isrc(legacy_isrc),
            "artists": [],
            "artists_label": "",
            "all_isrcs": [],
        }

    artist_rows = (
        session_db.query(SongArtist.song_id, Artist.name)
        .join(Artist, Artist.id == SongArtist.artist_id)
        .filter(SongArtist.song_id.in_(uuids))
        .order_by(Artist.name.asc())
        .all()
    )
    for sid, artist_name in artist_rows:
        item = meta.get(str(sid))
        if item and artist_name:
            item.setdefault("artists", []).append(artist_name)

    code_rows = (
        session_db.query(SongISRCCode.song_id, SongISRCCode.code, SongISRCCode.is_primary)
        .filter(SongISRCCode.song_id.in_(uuids))
        .order_by(SongISRCCode.is_primary.desc(), SongISRCCode.code.asc())
        .all()
    )
    for sid, code, is_primary in code_rows:
        item = meta.get(str(sid))
        if not item:
            continue
        norm_code = _norm_isrc(code)
        if not norm_code:
            continue
        if norm_code not in item["all_isrcs"]:
            item["all_isrcs"].append(norm_code)
        if is_primary and not item.get("display_isrc"):
            item["display_isrc"] = norm_code

    for item in meta.values():
        if not item.get("display_isrc") and item.get("all_isrcs"):
            item["display_isrc"] = item["all_isrcs"][0]
        item["artists_label"] = ", ".join(item.get("artists") or [])

    return meta


def _serialize_income_album_meta(session_db, album_ids: list[str]) -> dict[str, dict]:
    if not album_ids:
        return {}

    uuids = []
    for aid in album_ids:
        try:
            uuids.append(uuid.UUID(str(aid)))
        except Exception:
            continue

    if not uuids:
        return {}

    meta: dict[str, dict] = {}
    album_rows = (
        session_db.query(Album.id, Album.title, Album.release_date, Album.upc_code, Album.artist_id)
        .filter(Album.id.in_(uuids))
        .all()
    )
    for aid, title, release_date, upc_code, artist_id in album_rows:
        meta[str(aid)] = {
            "album_id": str(aid),
            "album_title": title or "",
            "release_date": release_date.isoformat() if release_date else "",
            "display_code": (_clean_csv_cell(upc_code) or "").strip(),
            "artist_id": str(artist_id) if artist_id else "",
            "artists_label": "",
            "all_codes": [],
        }

    artist_rows = (
        session_db.query(Album.id, Artist.name)
        .join(Artist, Artist.id == Album.artist_id)
        .filter(Album.id.in_(uuids))
        .all()
    )
    for aid, artist_name in artist_rows:
        item = meta.get(str(aid))
        if item and artist_name:
            item["artists_label"] = artist_name

    code_rows = (
        session_db.query(AlbumProductCode.album_id, AlbumProductCode.code)
        .filter(AlbumProductCode.album_id.in_(uuids))
        .order_by(AlbumProductCode.created_at.asc())
        .all()
    )
    for aid, code in code_rows:
        item = meta.get(str(aid))
        if not item:
            continue
        raw_code = (_clean_csv_cell(code) or "").strip()
        if not raw_code:
            continue
        if raw_code not in item["all_codes"]:
            item["all_codes"].append(raw_code)
        if not item.get("display_code"):
            item["display_code"] = raw_code

    return meta


def _apply_album_income_import_items(session_db, items: list[dict], period_type: str, period_start: date, period_end: date, amount_kind: str, strategy: str = "replace") -> dict:
    result = {
        "created": 0,
        "updated": 0,
        "unchanged": 0,
        "kept": 0,
        "replaced": 0,
        "actions": [],
    }
    if not items:
        return result

    album_ids = []
    for item in items:
        try:
            album_ids.append(uuid.UUID(str(item.get("album_id") or "")))
        except Exception:
            continue

    if not album_ids:
        return result

    existing_rows = (
        session_db.query(AlbumRevenueEntry)
        .filter(AlbumRevenueEntry.album_id.in_(album_ids))
        .filter(AlbumRevenueEntry.period_type == period_type)
        .filter(AlbumRevenueEntry.period_start == period_start)
        .filter(AlbumRevenueEntry.is_base.is_(True))
        .all()
    )
    existing_by_album = {str(row.album_id): row for row in existing_rows}

    for item in items:
        aid = str(item.get("album_id") or "")
        amount = _money_norm(item.get("new_value") or item.get("amount") or 0)
        if not aid:
            continue

        entry = existing_by_album.get(aid)
        field_name = "gross" if amount_kind == "gross" else "net"
        existing_value = _money_norm(getattr(entry, field_name, 0) if entry else 0)
        action = None

        if entry and strategy == "keep" and not _money_equal(existing_value, amount):
            result["kept"] += 1
            action = "kept"
        else:
            if not entry:
                try:
                    album_uuid = uuid.UUID(aid)
                except Exception:
                    continue
                entry = AlbumRevenueEntry(
                    album_id=album_uuid,
                    period_type=period_type,
                    period_start=period_start,
                    period_end=period_end,
                    is_base=True,
                    name=None,
                    gross=Decimal("0"),
                    net=Decimal("0"),
                )
                session_db.add(entry)
                existing_by_album[aid] = entry
                result["created"] += 1
                action = "created"
            else:
                if strategy == "replace" and not _money_equal(existing_value, amount):
                    result["replaced"] += 1
                    action = "replaced"
                elif _money_equal(existing_value, amount):
                    result["unchanged"] += 1
                    action = "unchanged"
                else:
                    result["updated"] += 1
                    action = "updated"

            if strategy != "keep" or not _money_equal(existing_value, amount):
                setattr(entry, field_name, amount)
                entry.period_end = period_end
                entry.updated_at = func.now()
                if action not in ("created", "replaced", "unchanged"):
                    action = "updated"

        result["actions"].append(
            {
                **item,
                "existing_value": str(existing_value),
                "new_value": str(amount),
                "action": action or "updated",
            }
        )

    return result


def _apply_income_import_items(session_db, items: list[dict], period_type: str, period_start: date, period_end: date, amount_kind: str, strategy: str = "replace") -> dict:
    result = {
        "created": 0,
        "updated": 0,
        "unchanged": 0,
        "kept": 0,
        "replaced": 0,
        "actions": [],
    }
    if not items:
        return result

    song_ids = []
    for item in items:
        try:
            song_ids.append(uuid.UUID(str(item.get("song_id") or "")))
        except Exception:
            continue

    if not song_ids:
        return result

    existing_rows = (
        session_db.query(SongRevenueEntry)
        .filter(SongRevenueEntry.song_id.in_(song_ids))
        .filter(SongRevenueEntry.period_type == period_type)
        .filter(SongRevenueEntry.period_start == period_start)
        .filter(SongRevenueEntry.is_base.is_(True))
        .all()
    )
    existing_by_song = {str(row.song_id): row for row in existing_rows}

    for item in items:
        sid = str(item.get("song_id") or "")
        amount = _money_norm(item.get("new_value") or item.get("amount") or 0)
        if not sid:
            continue

        entry = existing_by_song.get(sid)
        field_name = "gross" if amount_kind == "gross" else "net"
        existing_value = _money_norm(getattr(entry, field_name, 0) if entry else 0)
        action = None

        if entry and strategy == "keep" and not _money_equal(existing_value, amount):
            result["kept"] += 1
            action = "kept"
        else:
            if not entry:
                try:
                    song_uuid = uuid.UUID(sid)
                except Exception:
                    continue
                entry = SongRevenueEntry(
                    song_id=song_uuid,
                    period_type=period_type,
                    period_start=period_start,
                    period_end=period_end,
                    is_base=True,
                    name=None,
                    gross=Decimal("0"),
                    net=Decimal("0"),
                )
                session_db.add(entry)
                existing_by_song[sid] = entry
                result["created"] += 1
                action = "created"
            else:
                if strategy == "replace" and not _money_equal(existing_value, amount):
                    result["replaced"] += 1
                    action = "replaced"
                elif _money_equal(existing_value, amount):
                    result["unchanged"] += 1
                    action = "unchanged"
                else:
                    result["updated"] += 1
                    action = "updated"

            if strategy != "keep" or not _money_equal(existing_value, amount):
                setattr(entry, field_name, amount)
                entry.period_end = period_end
                entry.updated_at = func.now()
                if action not in ("created", "replaced", "unchanged"):
                    action = "updated"

        result["actions"].append(
            {
                **item,
                "existing_value": str(existing_value),
                "new_value": str(amount),
                "action": action or "updated",
            }
        )

    return result

@app.get("/discografica")
@admin_required
def discografica_view():
    """Pestaña principal Discográfica.

    Agrupa (por ahora):
    - Canciones (Repertorio)
    - Royalties (próximamente)
    - Editorial (próximamente)
    - Ingresos
    """

    section = (request.args.get("section") or "lanzamientos").lower().strip()
    if section == "repertorio":
        section = "canciones"

    # Context (solo se usa cuando section == 'ingresos')
    income_view = request.args.get("view") or "month"  # 'month' | 'semester'
    if income_view not in ("month", "semester"):
        income_view = "month"

    income_period_label = ""
    income_period_type = "MONTH"
    income_period_key = ""
    income_period_start_iso = ""

    income_month_tabs: list[dict] = []
    income_month_prev_url: str | None = None
    income_month_next_url: str | None = None

    income_semester_tabs: list[dict] = []

    income_artist_blocks: list[tuple] = []
    repertorio_tab = (request.args.get("rep_tab") or "canciones").lower().strip()
    if repertorio_tab not in ("canciones", "albumes"):
        repertorio_tab = "canciones"
    editorial_pending_songs: list[Song] = []
    editorial_registered_songs: list[Song] = []
    editorial_filter_artists: list[Artist] = []
    isrc_pending_songs: list[dict] = []
    isrc_pending_filter_artists: list[Artist] = []
    isrc_config_subtab = (request.args.get("config_tab") or "isrc").lower().strip()
    if isrc_config_subtab not in ("isrc", "album_refs"):
        isrc_config_subtab = "isrc"

    registros_tab = (request.args.get("registros_tab") or "sgae").lower().strip()
    if registros_tab not in ("sgae", "agedi", "ritmonet"):
        registros_tab = "sgae"
    registros_upcoming_releases: list[dict] = []
    registros_sgae_pending_songs: list[Song] = []
    registros_agedi_items: list[dict] = []
    registros_ritmonet_songs: list[dict] = []
    registros_filter_artists: list[Artist] = []
    registros_filter_years: list[int] = []
    registros_selected_artist_id = ""
    registros_selected_year = ""

    launches_items: list[dict] = []
    launches_calendar_months: list[dict] = []

    # Context (solo se usa cuando section == 'royalties')
    royalty_period_label = ""
    royalty_semester_key = ""
    royalty_semester_tabs: list[dict] = []
    royalty_beneficiaries_artists: list[dict] = []
    royalty_beneficiaries_others: list[dict] = []
    royalty_filter_artists: list[Artist] = []
    royalty_selected_artist_id = ""
    royalty_selected_statuses: list[str] = []
    royalty_pending_generate = 0      # liquidaciones aún sin generar (botón «Generar todas»)
    royalty_pending_send = 0          # generadas/descargadas sin enviar («Descargar/Enviar todas»)
    royalty_tab = "liquidaciones"
    afavor_groups: list[dict] = []
    afavor_total = Decimal("0")
    royalty_semester_start_iso = ""

    # Para redirecciones tras POST
    income_next_url = _update_url_query(request.full_path.rstrip("?"), {"upload_report": None, "import_review": None})

    # Opciones para el modal del informe
    income_report_months: list[dict] = []
    income_report_semesters: list[dict] = []
    income_report_months_selected: list[str] = []
    income_report_semesters_selected: list[str] = []
    income_upload_report = None
    income_import_review = None

    if section not in ("lanzamientos", "canciones", "royalties", "editorial", "registros", "ingresos", "isrc", "adelantos"):
        section = "canciones"
    if section == "registros":
        legacy_tab = (request.args.get("registros_tab") or request.args.get("tab") or "pendiente").strip().lower()
        tab = "sgae" if legacy_tab == "sgae" else "pendiente"
        return redirect(url_for("registros_view", tab=tab))

    editorial_tab = (request.args.get("editorial_tab") or "repertorio").lower().strip()
    if editorial_tab == "pendientes":
        return redirect(url_for("discografica_view", section="registros", registros_tab="sgae"))
    if editorial_tab != "repertorio":
        editorial_tab = "repertorio"

    # subpestañas ISRC
    isrc_tab = (request.args.get("isrc_tab") or "repertorio").lower().strip()
    if isrc_tab == "pendientes":
        return redirect(url_for("discografica_view", section="registros", registros_tab="agedi"))
    if isrc_tab not in ("repertorio", "configurador"):
        isrc_tab = "repertorio"

    if section == "ingresos":
        income_upload_report = _load_income_import_payload(request.args.get("upload_report"))
        income_import_review = _load_income_import_payload(request.args.get("import_review"))

    session_db = db()
    artists = session_db.query(Artist).order_by(Artist.name.asc()).all()

    # Solo artistas con contrato Discográfico / Catálogo / Distribución (para alta de canciones)
    contract_artist_ids = _artist_ids_with_discography_contracts(session_db)
    contract_artists = [a for a in artists if a.id in contract_artist_ids]

    artist_blocks = []
    song_audio_isrc_map = {}
    isrc_artist_blocks = []
    isrc_years = []
    isrc_config = None
    isrc_artist_settings = {}
    isrc_contract_artists = []
    isrc_filter_artists = []
    isrc_current_filter_artists = []
    album_blocks = []
    product_code_config = None
    current_product_code_series = None
    product_code_series_rows = []

    if section == "canciones":
        if repertorio_tab == "canciones":
            for a in artists:
                songs = (
                    session_db.query(Song)
                    .join(SongArtist, Song.id == SongArtist.song_id)
                    .filter(SongArtist.artist_id == a.id)
                    .order_by(Song.release_date.desc())
                    .all()
                )
                for s in songs:
                    _ = s.artists
                if songs:
                    artist_blocks.append((a, songs))

            # Prefetch ISRC AUDIO principal por canción (song_isrc_codes),
            # para mostrarlo en el repertorio.
            all_song_ids = [s.id for _, ss in artist_blocks for s in (ss or [])]
            if all_song_ids:
                rows = (
                    session_db.query(SongISRCCode.song_id, SongISRCCode.code)
                    .filter(SongISRCCode.song_id.in_(all_song_ids))
                    .filter(func.upper(SongISRCCode.kind) == "AUDIO")
                    .filter(SongISRCCode.is_primary == True)  # noqa: E712
                    .all()
                )
                for sid, code in rows:
                    if sid and code:
                        song_audio_isrc_map[sid] = code
        else:
            for a in artists:
                albums = (
                    session_db.query(Album)
                    .filter(Album.artist_id == a.id)
                    .order_by(Album.release_date.desc(), Album.title.asc())
                    .all()
                )
                if albums:
                    album_blocks.append((a, albums))



    if section == "lanzamientos":
        today = today_local()
        launch_window_start = today - timedelta(days=7)
        launch_window_end = today + timedelta(days=180)

        launch_song_rows = []
        if contract_artist_ids:
            launch_song_rows = (
                session_db.query(Song)
                .join(SongArtist, Song.id == SongArtist.song_id)
                .filter(SongArtist.artist_id.in_(list(contract_artist_ids)))
                .filter(Song.release_date >= launch_window_start)
                .filter(Song.release_date <= launch_window_end)
                .distinct()
                .options(selectinload(Song.artists))
                .order_by(Song.release_date.asc(), Song.title.asc())
                .all()
            )
        _annotate_song_display_fields(session_db, launch_song_rows, persist=True)
        seen_launch_song_ids = set()
        for song in launch_song_rows:
            if not song or song.id in seen_launch_song_ids:
                continue
            seen_launch_song_ids.add(song.id)
            release_date = getattr(song, 'release_date', None)
            if not release_date:
                continue
            days_remaining = (release_date - today).days
            is_new = release_date <= today and release_date >= (today - timedelta(days=7))
            if days_remaining < 0 and not is_new:
                continue
            artist_label = ", ".join([a.name for a in (song.artists or []) if getattr(a, 'name', None)]) or "—"
            launches_items.append({
                'item_id': str(song.id),
                'kind': 'SONG',
                'kind_label': 'Canción',
                'title': getattr(song, 'title', None) or '—',
                'artist_label': artist_label,
                'collaborator': (getattr(song, 'display_collaborator', None) or getattr(song, 'collaborator', None) or '').strip(),
                'cover_url': (getattr(song, 'cover_url', None) or '').strip(),
                'release_date': release_date,
                'days_remaining': days_remaining,
                'is_new': is_new,
                'detail_url': url_for('discografica_song_detail', song_id=song.id, tab='informacion'),
            })

        launch_album_rows = []
        if contract_artist_ids:
            launch_album_rows = (
                session_db.query(Album)
                .options(joinedload(Album.artist))
                .filter(Album.artist_id.in_(list(contract_artist_ids)))
                .filter(Album.release_date >= launch_window_start)
                .filter(Album.release_date <= launch_window_end)
                .order_by(Album.release_date.asc(), Album.title.asc())
                .all()
            )
        for album in launch_album_rows:
            release_date = getattr(album, 'release_date', None)
            if not release_date:
                continue
            days_remaining = (release_date - today).days
            is_new = release_date <= today and release_date >= (today - timedelta(days=7))
            if days_remaining < 0 and not is_new:
                continue
            launches_items.append({
                'item_id': str(album.id),
                'kind': 'ALBUM',
                'kind_label': 'EP' if (getattr(album, 'album_type', None) or '').strip().upper() == 'EP' else 'Disco',
                'title': getattr(album, 'title', None) or '—',
                'artist_label': (getattr(getattr(album, 'artist', None), 'name', None) or '').strip() or '—',
                'collaborator': '',
                'cover_url': (getattr(album, 'cover_url', None) or '').strip(),
                'release_date': release_date,
                'days_remaining': days_remaining,
                'is_new': is_new,
                'detail_url': url_for('discografica_album_detail', album_id=album.id, tab='informacion'),
            })

        def _launch_sort_key(item: dict):
            release_date = item.get('release_date') or date.max
            ordinal = release_date.toordinal() if hasattr(release_date, 'toordinal') else 0
            days_remaining = item.get('days_remaining')
            is_future = days_remaining is not None and days_remaining >= 0
            return (
                0 if is_future else 1,
                ordinal if is_future else -ordinal,
                0 if item.get('kind') == 'SONG' else 1,
                (item.get('title') or '').casefold(),
            )

        launches_items.sort(key=_launch_sort_key)

        cal_items_by_date: dict[date, list[dict]] = defaultdict(list)
        months_with_launches: set[date] = set()
        for item in launches_items:
            rd = item.get('release_date')
            if not rd:
                continue
            first = date(rd.year, rd.month, 1)
            months_with_launches.add(first)
            cal_items_by_date.setdefault(rd, []).append(item)

        for first_day in sorted(months_with_launches):
            next_month = _add_months(first_day, 1)
            last_day = next_month - timedelta(days=1)
            if first_day.year == today.year and first_day.month == today.month:
                # En el mes en curso solo se pinta desde la semana actual para ahorrar espacio.
                week_start = today - timedelta(days=today.weekday())
                start_day = max(first_day - timedelta(days=first_day.weekday()), week_start)
            else:
                start_day = first_day - timedelta(days=first_day.weekday())
            end_day = last_day + timedelta(days=(6 - last_day.weekday()))
            weeks = []
            cursor = start_day
            while cursor <= end_day:
                week = []
                for _ in range(7):
                    day_items = list(cal_items_by_date.get(cursor, []))
                    week.append({
                        'date': cursor,
                        'in_month': cursor.month == first_day.month,
                        'items': day_items,
                    })
                    cursor += timedelta(days=1)
                weeks.append(week)
            launches_calendar_months.append({
                'key': first_day.strftime('%Y-%m'),
                'label': _month_label(first_day),
                'weeks': weeks,
            })



    if section in ("editorial", "registros"):
        plataforma = (
            session_db.query(PublishingCompany)
            .filter(func.lower(PublishingCompany.name) == "plataforma musical")
            .first()
        )
        plataforma_id = getattr(plataforma, "id", None)

        if plataforma_id:
            song_rows = (
                session_db.query(Song)
                .join(SongEditorialShare, SongEditorialShare.song_id == Song.id)
                .join(Promoter, Promoter.id == SongEditorialShare.promoter_id)
                .filter(Promoter.publishing_company_id == plataforma_id)
                .options(selectinload(Song.artists))
                .order_by(Song.release_date.desc(), Song.title.asc())
                .all()
            )

            dedup = []
            seen = set()
            for song in song_rows:
                if not song or song.id in seen:
                    continue
                seen.add(song.id)
                dedup.append(song)

            status_map = {}
            if dedup:
                status_map = {
                    row.song_id: row
                    for row in (
                        session_db.query(SongStatus)
                        .filter(SongStatus.song_id.in_([s.id for s in dedup]))
                        .all()
                    )
                    if row and row.song_id
                }

            editorial_artist_ids = set()
            for song in dedup:
                setattr(song, "editorial_artists_str", ", ".join([a.name for a in getattr(song, "artists", [])]) or "—")
                song_status = status_map.get(song.id)
                setattr(song, "editorial_registered", bool(getattr(song_status, "sgae_done", False)))
                setattr(song, "editorial_modification_pending", bool(getattr(song_status, "sgae_modification_pending", False)))
                for art in (getattr(song, "artists", []) or []):
                    if art and getattr(art, "id", None):
                        editorial_artist_ids.add(art.id)

            editorial_pending_songs = [
                s for s in dedup
                if (not getattr(s, "editorial_registered", False)) or bool(getattr(s, "editorial_modification_pending", False))
            ]
            editorial_registered_songs = [s for s in dedup if getattr(s, "editorial_registered", False)]
            editorial_filter_artists = [a for a in artists if a.id in editorial_artist_ids]


    if section == "royalties":
        today = today_local()
        parsed_sem = _parse_semester_key((request.args.get("s") or "").strip())
        if parsed_sem is None:
            if today.month <= 6:
                sem_year, sem_half = today.year - 1, 2
            else:
                sem_year, sem_half = today.year, 1
        else:
            sem_year, sem_half = parsed_sem

        royalty_tab = (request.args.get("roy_tab") or "liquidaciones").strip().lower()
        if royalty_tab not in ("liquidaciones", "resumen", "afavor"):
            royalty_tab = "liquidaciones"

        royalty_semester_key = _semester_key(sem_year, sem_half)
        sem_start, sem_end = _semester_range(sem_year, sem_half)
        royalty_period_label = _semester_label(sem_year, sem_half)
        royalty_selected_artist_id = (request.args.get("artist") or "").strip()
        selected_artist_uuid = to_uuid(royalty_selected_artist_id) if royalty_selected_artist_id else None
        if royalty_selected_artist_id and not selected_artist_uuid:
            royalty_selected_artist_id = ""

        allowed_royalty_statuses = list(ROYALTY_STATUS_FLOW)
        royalty_selected_statuses = [(value or "").strip().upper() for value in request.args.getlist("roy_status") if (value or "").strip()]
        royalty_selected_statuses = [value for value in royalty_selected_statuses if value in allowed_royalty_statuses]
        if not royalty_selected_statuses:
            royalty_selected_statuses = list(allowed_royalty_statuses)

        royalty_semester_tabs = []
        for y, h in _royalty_available_semesters(session_db, sem_start):
            k = _semester_key(y, h)
            royalty_semester_tabs.append(
                {
                    "key": k,
                    "label": _semester_label(y, h),
                    "is_active": k == royalty_semester_key,
                    "url": url_for(
                        "discografica_view",
                        section="royalties",
                        s=k,
                        roy_tab=royalty_tab,
                        artist=royalty_selected_artist_id or None,
                    ),
                }
            )

        royalty_payload = _build_royalty_beneficiaries(
            session_db,
            sem_start,
            sem_end,
            selected_artist_id=selected_artist_uuid,
        )
        royalty_beneficiaries_artists = royalty_payload.get("artists") or []
        royalty_beneficiaries_others = royalty_payload.get("others") or []
        royalty_filter_artists = royalty_payload.get("filter_artists") or []

        def _match_royalty_status(bucket: dict) -> bool:
            bucket_status = (bucket.get("liquidation_status") or "PENDING").upper()
            return bucket_status in set(royalty_selected_statuses or [])

        # Antes de filtrar: cuántas quedan por GENERAR y cuántas sin enviar (para los botones de
        # acción en bloque: primero «Generar todas» y, cuando ya están todas, «Descargar todas»).
        _all_buckets = list(royalty_beneficiaries_artists) + list(royalty_beneficiaries_others)
        royalty_pending_generate = sum(
            1 for b in _all_buckets if (b.get("liquidation_status") or "PENDING").upper() == "PENDING")
        royalty_pending_send = sum(
            1 for b in _all_buckets
            if (b.get("liquidation_status") or "PENDING").upper() in ROYALTY_NOT_SENT_STATUSES)

        royalty_beneficiaries_artists = [bucket for bucket in royalty_beneficiaries_artists if _match_royalty_status(bucket)]
        royalty_beneficiaries_others = [bucket for bucket in royalty_beneficiaries_others if _match_royalty_status(bucket)]

        # Pestaña «A favor»: lo que cobramos nosotros por colaboraciones externas.
        _afavor = _build_afavor_groups(session_db, sem_start, selected_artist_uuid) if royalty_tab == "afavor" else {"groups": [], "total": Decimal("0")}
        afavor_groups = _afavor["groups"]
        afavor_total = _afavor["total"]
        royalty_semester_start_iso = sem_start.isoformat()

    if section == "ingresos":

        # 1) Selección de periodos (meses / semestres)
        today = today_local()
        current_month_start = date(today.year, today.month, 1)
        prev_month_start = _add_months(current_month_start, -1)

        # Mes seleccionado (YYYY-MM)
        sel_month_start = _parse_month_key((request.args.get("m") or "").strip()) or prev_month_start
        if sel_month_start > prev_month_start:
            sel_month_start = prev_month_start
        sel_month_key = _month_key(sel_month_start)

        # Cursor para pestañas de meses (ventana de 12)
        cursor_start = _parse_month_key((request.args.get("mc") or "").strip()) or sel_month_start
        if cursor_start > prev_month_start:
            cursor_start = prev_month_start
        cursor_key = _month_key(cursor_start)

        # Semestre seleccionado (YYYY-S1 / YYYY-S2)
        parsed_sem = _parse_semester_key((request.args.get("s") or "").strip())
        if parsed_sem is None:
            # Semestre anterior "cerrado"
            if today.month <= 6:
                sem_year, sem_half = today.year - 1, 2
            else:
                sem_year, sem_half = today.year, 1
        else:
            sem_year, sem_half = parsed_sem
        sem_key = _semester_key(sem_year, sem_half)
        sem_start, sem_end = _semester_range(sem_year, sem_half)

        # 2) Construcción de pestañas
        # Meses (12 últimos meses, empezando desde el cursor)
        income_month_tabs = []
        for i in range(12):
            d = _add_months(cursor_start, -i)
            key = _month_key(d)
            income_month_tabs.append(
                {
                    "key": key,
                    "label": _month_label(d),
                    "is_active": key == sel_month_key,
                    "url": url_for(
                        "discografica_view",
                        section="ingresos",
                        view="month",
                        m=key,
                        mc=cursor_key,
                        s=sem_key,
                    ),
                }
            )

        # Flechas meses
        left_cursor = _add_months(cursor_start, -1)
        income_month_prev_url = url_for(
            "discografica_view",
            section="ingresos",
            view="month",
            m=_month_key(left_cursor),
            mc=_month_key(left_cursor),
            s=sem_key,
        )
        if cursor_start < prev_month_start:
            right_cursor = _add_months(cursor_start, 1)
            income_month_next_url = url_for(
                "discografica_view",
                section="ingresos",
                view="month",
                m=_month_key(right_cursor),
                mc=_month_key(right_cursor),
                s=sem_key,
            )
        else:
            income_month_next_url = None

        # Semestres (últimos 12 semestres desde el seleccionado)
        income_semester_tabs = []
        for i in range(12):
            y, h = _add_semesters(sem_year, sem_half, -i)
            k = _semester_key(y, h)
            income_semester_tabs.append(
                {
                    "key": k,
                    "label": _semester_label(y, h),
                    "is_active": k == sem_key,
                    "url": url_for(
                        "discografica_view",
                        section="ingresos",
                        view="semester",
                        s=k,
                        m=sel_month_key,
                        mc=cursor_key,
                    ),
                }
            )

        # 3) Periodo activo (el que se está mostrando en el listado)
        if income_view == "semester":
            income_period_type = "SEMESTER"
            income_period_key = sem_key
            period_start = sem_start
            period_end = sem_end
            income_period_label = _semester_label(sem_year, sem_half)
            income_period_start_iso = period_start.isoformat()
            income_report_semesters_selected = [sem_key]
        else:
            income_period_type = "MONTH"
            income_period_key = sel_month_key
            period_start = sel_month_start
            period_end = _month_end(sel_month_start)
            income_period_label = _month_label(sel_month_start)
            income_period_start_iso = period_start.isoformat()
            income_report_months_selected = [sel_month_key]

        # 4) Opciones para informe (últimos 24 meses / 12 semestres)
        income_report_months = [
            {"key": _month_key(_add_months(prev_month_start, -i)), "label": _month_label(_add_months(prev_month_start, -i))}
            for i in range(24)
        ]

        base_sem_year, base_sem_half = (today.year - 1, 2) if today.month <= 6 else (today.year, 1)
        income_report_semesters = [
            {
                "key": _semester_key(*_add_semesters(base_sem_year, base_sem_half, -i)),
                "label": _semester_label(*_add_semesters(base_sem_year, base_sem_half, -i)),
            }
            for i in range(12)
        ]

        # 5) Canciones publicadas hasta el fin del periodo (ordenadas por artista)
        tmp_blocks: list[tuple[Artist, list[Song]]] = []
        for a in artists:
            songs = (
                session_db.query(Song)
                .join(SongArtist, Song.id == SongArtist.song_id)
                .filter(SongArtist.artist_id == a.id)
                .filter(Song.release_date <= period_end)
                .order_by(Song.release_date.desc())
                .all()
            )
            for s in songs:
                _ = s.artists
            if songs:
                tmp_blocks.append((a, songs))

        all_song_ids = [s.id for _, ss in tmp_blocks for s in (ss or [])]

        # Prefetch intérpretes (si no hay, usamos artistas del tema)
        interpreters_by_song: dict[str, list[str]] = {}
        if all_song_ids:
            irows = (
                session_db.query(SongInterpreter.song_id, SongInterpreter.name)
                .filter(SongInterpreter.song_id.in_(all_song_ids))
                .order_by(SongInterpreter.is_main.desc(), SongInterpreter.created_at.asc(), SongInterpreter.name.asc())
                .all()
            )
            for sid, name in irows:
                if sid and name:
                    interpreters_by_song.setdefault(str(sid), []).append(name)

        # Prefetch ISRC principal (AUDIO) o fallback a Song.isrc
        isrc_by_song: dict[str, str] = {}
        if all_song_ids:
            r_isrc = (
                session_db.query(SongISRCCode.song_id, SongISRCCode.code, SongISRCCode.is_primary)
                .filter(SongISRCCode.song_id.in_(all_song_ids))
                .filter(func.upper(SongISRCCode.kind) == "AUDIO")
                .order_by(SongISRCCode.is_primary.desc(), SongISRCCode.code.desc())
                .all()
            )
            for sid, code, _prim in r_isrc:
                sid_s = str(sid)
                if sid_s not in isrc_by_song and code:
                    isrc_by_song[sid_s] = code

        # Prefetch ingresos
        entries_by_song_period: dict[tuple[str, str, date], list[SongRevenueEntry]] = {}
        sem_month_starts: list[date] = []
        if income_view == "semester":
            sem_month_starts = [_add_months(date(sem_start.year, sem_start.month, 1), i) for i in range(6)]

        if all_song_ids:
            if income_view == "month":
                q = (
                    session_db.query(SongRevenueEntry)
                    .filter(SongRevenueEntry.song_id.in_(all_song_ids))
                    .filter(SongRevenueEntry.period_type == "MONTH")
                    .filter(SongRevenueEntry.period_start == period_start)
                )
            else:
                q = (
                    session_db.query(SongRevenueEntry)
                    .filter(SongRevenueEntry.song_id.in_(all_song_ids))
                    .filter(
                        or_(
                            and_(SongRevenueEntry.period_type == "SEMESTER", SongRevenueEntry.period_start == sem_start),
                            and_(SongRevenueEntry.period_type == "MONTH", SongRevenueEntry.period_start.in_(sem_month_starts)),
                        )
                    )
                )

            erows = q.order_by(SongRevenueEntry.is_base.desc(), SongRevenueEntry.created_at.asc()).all()
            for e in erows:
                entries_by_song_period.setdefault((str(e.song_id), e.period_type, e.period_start), []).append(e)

        def _money_input(v: Decimal | None) -> str:
            if v is None:
                return ""
            try:
                return str(Decimal(v).quantize(Decimal("0.01")))
            except Exception:
                return str(v)

        # 6) Construimos bloques enriquecidos para la plantilla
        income_artist_blocks = []
        for a, songs in tmp_blocks:
            rows = []
            for s in songs:
                sid = str(s.id)

                # intérpretes
                inames = interpreters_by_song.get(sid)
                if not inames:
                    inames = [ar.name for ar in (s.artists or []) if ar and ar.name]
                interpreters_str = ", ".join(inames) if inames else ""

                # isrc
                isrc = isrc_by_song.get(sid) or (s.isrc or "")

                # entradas del periodo
                if income_view == "month":
                    entries = entries_by_song_period.get((sid, "MONTH", period_start), [])
                    base = next((x for x in entries if x.is_base), None)
                    extras = [x for x in entries if not x.is_base]

                    total_gross = sum((Decimal(x.gross or 0) for x in entries), Decimal("0"))
                    total_net = sum((Decimal(x.net or 0) for x in entries), Decimal("0"))

                    status = {"label": "Completo" if entries else "Sin datos", "class": "text-bg-success" if entries else "text-bg-danger"}

                    rows.append(
                        {
                            "song": s,
                            "cover_url": s.cover_url,
                            "interpreters": interpreters_str,
                            "isrc": isrc,
                            "status": status,
                            "base_entry_id": str(base.id) if base else "",
                            "base_gross": _money_input(base.gross) if base else "",
                            "base_net": _money_input(base.net) if base else "",
                            "extra_entries": [
                                {"id": str(x.id), "name": x.name, "gross": x.gross or 0, "net": x.net or 0}
                                for x in extras
                            ],
                            "show_total": len(extras) > 0,
                            "total_gross": total_gross,
                            "total_net": total_net,
                            "semester_sum_gross": Decimal("0"),
                            "semester_sum_net": Decimal("0"),
                            "semester_missing_months": None,
                            "semester_has_manual": False,
                        }
                    )

                else:
                    sem_entries = entries_by_song_period.get((sid, "SEMESTER", sem_start), [])
                    base = next((x for x in sem_entries if x.is_base), None)
                    extras = [x for x in sem_entries if not x.is_base]

                    # suma de meses
                    months_with_data = 0
                    sum_gross = Decimal("0")
                    sum_net = Decimal("0")
                    for ms in sem_month_starts:
                        mentries = entries_by_song_period.get((sid, "MONTH", ms), [])
                        if mentries:
                            months_with_data += 1
                        sum_gross += sum((Decimal(x.gross or 0) for x in mentries), Decimal("0"))
                        sum_net += sum((Decimal(x.net or 0) for x in mentries), Decimal("0"))

                    missing = 6 - months_with_data

                    # estado
                    if months_with_data == 0 and not sem_entries:
                        status = {"label": "Sin datos", "class": "text-bg-danger"}
                    elif missing == 0:
                        status = {"label": "Completo", "class": "text-bg-success"}
                    else:
                        status = {"label": "Incompleto", "class": "text-bg-warning"}

                    display_gross = base.gross if base else sum_gross
                    display_net = base.net if base else sum_net

                    extras_gross = sum((Decimal(x.gross or 0) for x in extras), Decimal("0"))
                    extras_net = sum((Decimal(x.net or 0) for x in extras), Decimal("0"))

                    # Total mostrado (base manual o auto + extras) solo cuando hay más de un ingreso (extras).
                    total_gross = Decimal(display_gross or 0) + extras_gross
                    total_net = Decimal(display_net or 0) + extras_net

                    rows.append(
                        {
                            "song": s,
                            "cover_url": s.cover_url,
                            "interpreters": interpreters_str,
                            "isrc": isrc,
                            "status": status,
                            "base_entry_id": str(base.id) if base else "",
                            "base_gross": _money_input(display_gross),
                            "base_net": _money_input(display_net),
                            "extra_entries": [
                                {"id": str(x.id), "name": x.name, "gross": x.gross or 0, "net": x.net or 0}
                                for x in extras
                            ],
                            "show_total": len(extras) > 0,
                            "total_gross": total_gross,
                            "total_net": total_net,
                            "semester_sum_gross": sum_gross,
                            "semester_sum_net": sum_net,
                            "semester_missing_months": missing,
                            "semester_has_manual": bool(base),
                        }
                    )

            income_artist_blocks.append((a, rows))

    if section == "isrc":
        # filtros
        f_artist_id = to_uuid((request.args.get("artist_id") or "").strip())
        f_year = None
        try:
            f_year = int((request.args.get("year") or "").strip())
        except Exception:
            f_year = None

        # Solo mostramos repertorio ISRC de canciones que tengan ISRC
        # y cumplan: master_ownership_pct > 1% o es distribución.
        ownership_cond = (
            (func.coalesce(Song.master_ownership_pct, 0) > 1)
            | (func.coalesce(Song.is_distribution, False) == True)  # noqa: E712
        )

        # años disponibles (release_date) SOLO de canciones con ISRC y filtro de propiedad
        years_rows = (
            session_db.query(func.extract("year", Song.release_date).label("y"))
            .join(SongISRCCode, SongISRCCode.song_id == Song.id)
            .filter(ownership_cond)
            .distinct()
            .order_by(func.extract("year", Song.release_date).desc())
            .all()
        )
        isrc_years = [int(r.y) for r in years_rows if r and r.y]

        # Artistas con canciones con ISRC (y filtro de propiedad)
        arows = (
            session_db.query(SongArtist.artist_id)
            .join(Song, Song.id == SongArtist.song_id)
            .join(SongISRCCode, SongISRCCode.song_id == Song.id)
            .filter(ownership_cond)
            .distinct()
            .all()
        )
        a_set = {r.artist_id for r in arows if r and r.artist_id}
        isrc_filter_artists = [a for a in artists if a.id in a_set]
        isrc_current_filter_artists = list(isrc_filter_artists)

        if isrc_tab == "repertorio":
            # Repertorio ISRC agrupado por artista.
            # - Solo canciones con ISRC
            # - Solo si master_ownership_pct > 1% o es distribución
            # - Ordenado por código ISRC (más actual -> más antiguo)

            artists_iter = [a for a in isrc_filter_artists if (not f_artist_id) or a.id == f_artist_id]

            # subquery: máximo código por canción (para ordenar por ISRC)
            max_code_sq = (
                session_db.query(
                    SongISRCCode.song_id.label("song_id"),
                    func.max(SongISRCCode.code).label("max_code"),
                )
                .group_by(SongISRCCode.song_id)
                .subquery()
            )

            songs_by_artist: dict = {}
            all_song_ids: list = []
            for a in artists_iter:
                q = (
                    session_db.query(Song)
                    .join(SongArtist, Song.id == SongArtist.song_id)
                    .join(max_code_sq, max_code_sq.c.song_id == Song.id)
                    .filter(SongArtist.artist_id == a.id)
                    .filter(ownership_cond)
                )
                if f_year:
                    q = q.filter(func.extract("year", Song.release_date) == f_year)

                songs = q.order_by(max_code_sq.c.max_code.desc()).all()
                songs_by_artist[a.id] = songs
                all_song_ids.extend([s.id for s in songs])

            # Prefetch TODOS los ISRCs (incl. subproductos), ordenados por código desc
            codes_by_song = {}
            if all_song_ids:
                rows = (
                    session_db.query(SongISRCCode)
                    .filter(SongISRCCode.song_id.in_(all_song_ids))
                    .order_by(SongISRCCode.code.desc())
                    .all()
                )
                for r in rows:
                    codes_by_song.setdefault(r.song_id, []).append(r)

            for a in artists_iter:
                songs = songs_by_artist.get(a.id) or []
                enriched = []
                for s in songs:
                    codes = codes_by_song.get(s.id) or []

                    def _split(kind: str):
                        kind = (kind or "").upper()
                        prim = None
                        subs = []
                        for c in codes:
                            if (c.kind or "").upper() != kind:
                                continue
                            if c.is_primary and prim is None:
                                prim = c
                            elif not c.is_primary:
                                subs.append(c)
                        return prim, subs

                    audio_p, audio_subs = _split("AUDIO")
                    video_p, video_subs = _split("VIDEO")

                    # key de orden (max code ya viene por query, pero lo guardamos)
                    max_code = codes[0].code if codes else None
                    enriched.append(
                        {
                            "song": s,
                            "audio_primary": _norm_isrc(audio_p.code) if audio_p else None,
                            "video_primary": _norm_isrc(video_p.code) if video_p else None,
                            "audio_subs": [(_norm_isrc(c.code), c.subproduct_name) for c in audio_subs],
                            "video_subs": [(_norm_isrc(c.code), c.subproduct_name) for c in video_subs],
                            "max_code": _norm_isrc(max_code),
                        }
                    )

                isrc_artist_blocks.append((a, enriched))

            isrc_current_filter_artists = [artist for artist, rows in isrc_artist_blocks if rows]

        elif isrc_tab == "pendientes":
            song_rows = (
                session_db.query(Song)
                .join(SongArtist, Song.id == SongArtist.song_id)
                .join(SongISRCCode, SongISRCCode.song_id == Song.id)
                .filter(ownership_cond)
                .distinct()
                .options(selectinload(Song.artists))
                .order_by(Song.release_date.desc(), Song.title.asc())
                .all()
            )
            if f_artist_id:
                song_rows = [s for s in song_rows if any(getattr(a, 'id', None) == f_artist_id for a in (s.artists or []))]
            if f_year:
                song_rows = [s for s in song_rows if getattr(s, 'release_date', None) and s.release_date.year == f_year]

            song_ids = [s.id for s in song_rows]
            status_map = {}
            if song_ids:
                status_map = {
                    row.song_id: row
                    for row in session_db.query(SongStatus).filter(SongStatus.song_id.in_(song_ids)).all()
                    if row and row.song_id
                }

            codes_by_song = defaultdict(list)
            if song_ids:
                rows = (
                    session_db.query(SongISRCCode)
                    .filter(SongISRCCode.song_id.in_(song_ids))
                    .order_by(SongISRCCode.is_primary.desc(), SongISRCCode.code.asc())
                    .all()
                )
                for row in rows:
                    codes_by_song[row.song_id].append(row)

            pending_artist_ids = set()
            for song in song_rows:
                st = status_map.get(song.id) or _ensure_song_status_row(session_db, song)
                _sync_song_agedi_state(session_db, song.id, st)
                current_codes = _current_song_isrcs(session_db, song.id, include_song_field=True)
                if not current_codes:
                    continue
                registered_codes = set(_norm_isrc_list(getattr(st, 'agedi_registered_isrcs', []) or []))
                pending_codes = [code for code in current_codes if code not in registered_codes]
                if not pending_codes and bool(getattr(st, 'agedi_done', False)):
                    continue
                for art in (song.artists or []):
                    if art and getattr(art, 'id', None):
                        pending_artist_ids.add(art.id)
                isrc_pending_songs.append({
                    'song': song,
                    'artists_label': ", ".join([a.name for a in (song.artists or []) if getattr(a, 'name', None)]) or '—',
                    'registered_codes': [code for code in current_codes if code in registered_codes],
                    'pending_codes': pending_codes if pending_codes else current_codes,
                    'all_codes': [
                        {
                            'code': code,
                            'registered': code in registered_codes,
                            'pending': code not in registered_codes,
                        }
                        for code in current_codes
                    ],
                    'status': st,
                })
            isrc_pending_filter_artists = [a for a in artists if a.id in pending_artist_ids]
            isrc_current_filter_artists = list(isrc_pending_filter_artists)
            session_db.commit()

        else:
            # Configurador
            isrc_config = session_db.get(ISRCConfig, 1)
            if not isrc_config:
                isrc_config = ISRCConfig(id=1)
                session_db.add(isrc_config)
                session_db.commit()

            # Ajustes por artista
            settings_rows = session_db.query(ArtistISRCSetting).all()
            isrc_artist_settings = {r.artist_id: r for r in settings_rows}
            product_code_config = session_db.get(ProductCodeConfig, 1)
            if not product_code_config:
                product_code_config = ProductCodeConfig(id=1)
                session_db.add(product_code_config)
                session_db.commit()
            current_product_code_series = _active_product_code_series(session_db, create_if_missing=True)
            product_code_series_rows = _product_code_series_rows(session_db)
            # Artistas con contrato discográfico / catálogo / distribución.
            # Reutilizamos el cálculo robusto (sin acentos) para evitar listas vacías por variantes.
            isrc_contract_artists = contract_artists

    if section == "registros":
        f_artist_id = to_uuid((request.args.get("artist_id") or "").strip())
        f_year = None
        try:
            f_year = int((request.args.get("year") or "").strip())
        except Exception:
            f_year = None

        registros_selected_artist_id = str(f_artist_id) if f_artist_id else ""
        registros_selected_year = str(f_year) if f_year else ""

        ownership_cond = (
            (func.coalesce(Song.master_ownership_pct, 0) > 1)
            | (func.coalesce(Song.is_distribution, False) == True)  # noqa: E712
        )
        today = today_local()

        upcoming_song_rows = []
        if contract_artist_ids:
            upcoming_song_rows = (
                session_db.query(Song)
                .join(SongArtist, Song.id == SongArtist.song_id)
                .filter(SongArtist.artist_id.in_(list(contract_artist_ids)))
                .filter(Song.release_date >= today)
                .distinct()
                .options(selectinload(Song.artists))
                .order_by(Song.release_date.asc(), Song.title.asc())
                .all()
            )
        seen_song_ids = set()
        for song in upcoming_song_rows:
            if not song or song.id in seen_song_ids:
                continue
            seen_song_ids.add(song.id)
            artist_names = [
                (getattr(artist, 'name', None) or '').strip()
                for artist in (song.artists or [])
                if (getattr(artist, 'name', None) or '').strip()
            ]
            days_remaining = None
            if getattr(song, 'release_date', None):
                try:
                    days_remaining = (song.release_date - today).days
                except Exception:
                    days_remaining = None
            registros_upcoming_releases.append(
                {
                    'item_id': str(song.id),
                    'kind': 'SONG',
                    'kind_label': 'Canción',
                    'title': getattr(song, 'title', None) or '—',
                    'artist_label': ', '.join(artist_names) or '—',
                    'collaborator': (getattr(song, 'collaborator', None) or '').strip(),
                    'cover_url': (getattr(song, 'cover_url', None) or '').strip(),
                    'release_date': getattr(song, 'release_date', None),
                    'days_remaining': days_remaining,
                    'detail_url': url_for('discografica_song_detail', song_id=song.id, tab='informacion'),
                }
            )

        upcoming_album_rows = []
        if contract_artist_ids:
            upcoming_album_rows = (
                session_db.query(Album)
                .options(joinedload(Album.artist))
                .filter(Album.artist_id.in_(list(contract_artist_ids)))
                .filter(Album.release_date >= today)
                .order_by(Album.release_date.asc(), Album.title.asc())
                .all()
            )
        for album in upcoming_album_rows:
            days_remaining = None
            if getattr(album, 'release_date', None):
                try:
                    days_remaining = (album.release_date - today).days
                except Exception:
                    days_remaining = None
            registros_upcoming_releases.append(
                {
                    'kind': 'ALBUM',
                    'kind_label': 'EP' if (getattr(album, 'album_type', None) or '').upper() == 'EP' else 'Disco',
                    'title': getattr(album, 'title', None) or '—',
                    'artist_label': (getattr(getattr(album, 'artist', None), 'name', None) or '').strip() or '—',
                    'collaborator': '',
                    'cover_url': (getattr(album, 'cover_url', None) or '').strip(),
                    'release_date': getattr(album, 'release_date', None),
                    'days_remaining': days_remaining,
                    'detail_url': url_for('discografica_album_detail', album_id=album.id, tab='informacion'),
                }
            )
        registros_upcoming_releases.sort(
            key=lambda item: (
                item.get('release_date') or date.max,
                0 if item.get('kind') == 'SONG' else 1,
                (item.get('title') or '').casefold(),
            )
        )

        registros_sgae_pending_songs = list(editorial_pending_songs or [])

        agedi_song_rows = (
            session_db.query(Song)
            .join(SongArtist, Song.id == SongArtist.song_id)
            .join(SongISRCCode, SongISRCCode.song_id == Song.id)
            .filter(ownership_cond)
            .distinct()
            .options(selectinload(Song.artists))
            .order_by(Song.release_date.desc(), Song.title.asc())
            .all()
        )
        if f_artist_id:
            agedi_song_rows = [
                song
                for song in agedi_song_rows
                if any(getattr(artist, 'id', None) == f_artist_id for artist in (song.artists or []))
            ]
        if f_year:
            agedi_song_rows = [
                song
                for song in agedi_song_rows
                if getattr(song, 'release_date', None) and song.release_date.year == f_year
            ]

        agedi_song_ids = [song.id for song in agedi_song_rows]
        agedi_status_map = {}
        if agedi_song_ids:
            agedi_status_map = {
                row.song_id: row
                for row in session_db.query(SongStatus).filter(SongStatus.song_id.in_(agedi_song_ids)).all()
                if row and row.song_id
            }

        registros_artist_ids = set()
        registros_year_set = set()
        for song in agedi_song_rows:
            st = agedi_status_map.get(song.id) or _ensure_song_status_row(session_db, song)
            _sync_song_agedi_state(session_db, song.id, st)
            current_codes = _current_song_isrcs(session_db, song.id, include_song_field=True)
            if not current_codes:
                continue
            registered_codes = set(_norm_isrc_list(getattr(st, 'agedi_registered_isrcs', []) or []))
            pending_codes = [code for code in current_codes if code not in registered_codes]
            if not pending_codes and bool(getattr(st, 'agedi_done', False)):
                continue
            for artist in (song.artists or []):
                if artist and getattr(artist, 'id', None):
                    registros_artist_ids.add(artist.id)
            if getattr(song, 'release_date', None):
                registros_year_set.add(song.release_date.year)
            registros_agedi_items.append(
                {
                    'kind': 'SONG',
                    'song': song,
                    'item_id': str(song.id),
                    'title': getattr(song, 'title', None) or '—',
                    'cover_url': (getattr(song, 'cover_url', None) or '').strip(),
                    'artists_label': ', '.join([a.name for a in (song.artists or []) if getattr(a, 'name', None)]) or '—',
                    'artist_ids': [str(a.id) for a in (song.artists or []) if getattr(a, 'id', None)],
                    'collaborator': (getattr(song, 'collaborator', None) or '').strip(),
                    'release_date': getattr(song, 'release_date', None),
                    'all_codes': [
                        {
                            'code': code,
                            'registered': code in registered_codes,
                            'pending': code not in registered_codes,
                        }
                        for code in current_codes
                    ],
                    'detail_url': url_for('discografica_song_detail', song_id=song.id, tab='informacion'),
                    'register_url': url_for('discografica_song_agedi_register', song_id=song.id),
                    'album_kind_label': '',
                }
            )

        agedi_album_rows = (
            session_db.query(Album)
            .options(joinedload(Album.artist))
            .filter(Album.artist_id.in_(list(contract_artist_ids)) if contract_artist_ids else text('1=0'))
            .order_by(Album.release_date.desc(), Album.title.asc())
            .all()
        ) if contract_artist_ids else []
        if f_artist_id:
            agedi_album_rows = [album for album in agedi_album_rows if getattr(album, 'artist_id', None) == f_artist_id]
        if f_year:
            agedi_album_rows = [
                album
                for album in agedi_album_rows
                if getattr(album, 'release_date', None) and album.release_date.year == f_year
            ]
        agedi_album_ids = [album.id for album in agedi_album_rows]
        agedi_album_status_map = {}
        if agedi_album_ids:
            agedi_album_status_map = {
                row.album_id: row
                for row in session_db.query(AlbumStatus).filter(AlbumStatus.album_id.in_(agedi_album_ids)).all()
                if row and row.album_id
            }
        for album in agedi_album_rows:
            st = agedi_album_status_map.get(album.id) or _ensure_album_status_row(session_db, album)
            if bool(getattr(st, 'agedi_done', False)):
                continue
            artist = getattr(album, 'artist', None)
            if artist and getattr(artist, 'id', None):
                registros_artist_ids.add(artist.id)
            if getattr(album, 'release_date', None):
                registros_year_set.add(album.release_date.year)
            registros_agedi_items.append(
                {
                    'kind': 'ALBUM',
                    'album': album,
                    'item_id': str(album.id),
                    'title': getattr(album, 'title', None) or '—',
                    'cover_url': (getattr(album, 'cover_url', None) or '').strip(),
                    'artists_label': (getattr(artist, 'name', None) or '').strip() or '—',
                    'artist_ids': [str(getattr(artist, 'id', None) or '')] if getattr(artist, 'id', None) else [],
                    'collaborator': '',
                    'release_date': getattr(album, 'release_date', None),
                    'all_codes': [],
                    'detail_url': url_for('discografica_album_detail', album_id=album.id, tab='informacion'),
                    'register_url': url_for('discografica_album_status_toggle', album_id=album.id),
                    'album_kind_label': 'EP' if (getattr(album, 'album_type', None) or '').upper() == 'EP' else 'Disco',
                }
            )

        registros_agedi_items.sort(
            key=lambda item: (
                item.get('release_date') or date.min,
                (item.get('title') or '').casefold(),
            ),
            reverse=True,
        )

        ritmonet_song_rows = (
            session_db.query(Song)
            .join(SongArtist, Song.id == SongArtist.song_id)
            .join(SongISRCCode, SongISRCCode.song_id == Song.id)
            .filter(ownership_cond)
            .distinct()
            .options(selectinload(Song.artists))
            .order_by(Song.release_date.desc(), Song.title.asc())
            .all()
        )
        if f_artist_id:
            ritmonet_song_rows = [
                song
                for song in ritmonet_song_rows
                if any(getattr(artist, 'id', None) == f_artist_id for artist in (song.artists or []))
            ]
        if f_year:
            ritmonet_song_rows = [
                song
                for song in ritmonet_song_rows
                if getattr(song, 'release_date', None) and song.release_date.year == f_year
            ]
        ritmonet_song_ids = [song.id for song in ritmonet_song_rows]
        ritmonet_status_map = {}
        if ritmonet_song_ids:
            ritmonet_status_map = {
                row.song_id: row
                for row in session_db.query(SongStatus).filter(SongStatus.song_id.in_(ritmonet_song_ids)).all()
                if row and row.song_id
            }
        ritmonet_artist_ids = set()
        ritmonet_year_set = set()
        for song in ritmonet_song_rows:
            st = ritmonet_status_map.get(song.id) or _ensure_song_status_row(session_db, song)
            current_codes = _current_song_isrcs(session_db, song.id, include_song_field=True)
            if not current_codes or bool(getattr(st, 'ritmonet_done', False)):
                continue
            for artist in (song.artists or []):
                if artist and getattr(artist, 'id', None):
                    ritmonet_artist_ids.add(artist.id)
            if getattr(song, 'release_date', None):
                ritmonet_year_set.add(song.release_date.year)
            registros_ritmonet_songs.append(
                {
                    'song': song,
                    'item_id': str(song.id),
                    'title': getattr(song, 'title', None) or '—',
                    'cover_url': (getattr(song, 'cover_url', None) or '').strip(),
                    'artists_label': ', '.join([a.name for a in (song.artists or []) if getattr(a, 'name', None)]) or '—',
                    'artist_ids': [str(a.id) for a in (song.artists or []) if getattr(a, 'id', None)],
                    'collaborator': (getattr(song, 'collaborator', None) or '').strip(),
                    'release_date': getattr(song, 'release_date', None),
                    'all_codes': [{'code': code} for code in current_codes],
                    'detail_url': url_for('discografica_song_detail', song_id=song.id, tab='informacion'),
                }
            )

        if registros_tab == 'sgae':
            registros_filter_artists = list(editorial_filter_artists or [])
            registros_filter_years = []
        elif registros_tab == 'agedi':
            registros_filter_artists = [artist for artist in artists if artist.id in registros_artist_ids]
            registros_filter_years = sorted(registros_year_set, reverse=True)
        else:
            registros_filter_artists = [artist for artist in artists if artist.id in ritmonet_artist_ids]
            registros_filter_years = sorted(ritmonet_year_set, reverse=True)

        session_db.commit()

    display_song_rows: list[Song] = []
    display_song_ids: set[str] = set()

    def _collect_display_song(song_row):
        sid = str(getattr(song_row, 'id', '') or '')
        if not sid or sid in display_song_ids:
            return
        display_song_ids.add(sid)
        display_song_rows.append(song_row)

    for _artist, rows in (artist_blocks or []):
        for song_row in rows or []:
            _collect_display_song(song_row)
    for song_row in (editorial_pending_songs or []):
        _collect_display_song(song_row)
    for song_row in (editorial_registered_songs or []):
        _collect_display_song(song_row)
    for row in (isrc_pending_songs or []):
        if row.get('song') is not None:
            _collect_display_song(row.get('song'))
    for row in (registros_agedi_items or []):
        if row.get('song') is not None:
            _collect_display_song(row.get('song'))
    for row in (registros_ritmonet_songs or []):
        if row.get('song') is not None:
            _collect_display_song(row.get('song'))

    extra_song_ids: list[UUID] = []
    for collection in (registros_upcoming_releases or [], launches_items or []):
        for row in collection:
            if (row.get('kind') or '').upper() != 'SONG':
                continue
            sid = to_uuid(row.get('item_id'))
            if sid and str(sid) not in display_song_ids:
                extra_song_ids.append(sid)
                display_song_ids.add(str(sid))
    if extra_song_ids:
        extra_rows = (
            session_db.query(Song)
            .options(selectinload(Song.artists))
            .filter(Song.id.in_(extra_song_ids))
            .all()
        )
        display_song_rows.extend(extra_rows)

    song_display_map = _annotate_song_display_fields(session_db, display_song_rows, persist=True)

    def _apply_display_collaborator(collection):
        for row in collection or []:
            sid = ''
            if isinstance(row, dict):
                sid = str(row.get('item_id') or getattr(row.get('song'), 'id', '') or '')
            if sid and sid in song_display_map:
                row['collaborator'] = song_display_map[sid].get('collaborator') or ''

    _apply_display_collaborator(isrc_pending_songs)
    _apply_display_collaborator(registros_upcoming_releases)
    _apply_display_collaborator(registros_agedi_items)
    _apply_display_collaborator(registros_ritmonet_songs)
    _apply_display_collaborator(launches_items)

    # Distribuidoras (selectores de alta y edición en bloque) + pestaña Adelantos.
    distributors_all = session_db.query(Distributor).order_by(Distributor.name.asc()).all()
    distributor_by_id = {str(d.id): d for d in distributors_all}
