@app.post("/discografica/isrc/config/update")
@admin_required
def discografica_isrc_config_update():
    """Guardar configuración global de ISRC (país + matrices audio/video)."""

    if not can_edit_discografica():
        return forbid("No tienes permisos para editar la configuración ISRC.")

    country_code = (request.form.get("country_code") or "ES").strip().upper()[:2] or "ES"
    audio_matrix = (request.form.get("audio_matrix") or "").strip()
    video_matrix = (request.form.get("video_matrix") or "").strip()

    # Normalizar: solo dígitos y padding
    def norm_digits(v: str, length: int) -> str:
        v = "".join([c for c in (v or "") if c.isdigit()])
        if not v:
            return "0" * length
        return v.zfill(length)[-length:]

    audio_matrix = norm_digits(audio_matrix, 3)
    video_matrix = norm_digits(video_matrix, 3)

    session_db = db()
    try:
        cfg = session_db.get(ISRCConfig, 1)
        if not cfg:
            cfg = ISRCConfig(id=1)
            session_db.add(cfg)
        cfg.country_code = country_code
        cfg.audio_matrix = audio_matrix
        cfg.video_matrix = video_matrix
        cfg.updated_at = datetime.now(tz=ZoneInfo("Europe/Madrid"))
        session_db.commit()
        flash("Configuración ISRC guardada.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error guardando configuración ISRC: {e}", "danger")
    finally:
        session_db.close()

    return redirect(url_for("discografica_view", section="isrc", isrc_tab="configurador"))


@app.post("/discografica/isrc/artist/<artist_id>/set")
@admin_required
def discografica_isrc_artist_set(artist_id):
    """Guardar número matriz ISRC del artista (2 dígitos)."""

    if not can_edit_discografica():
        return forbid("No tienes permisos para editar ISRC por artista.")

    matrix = (request.form.get("artist_matrix") or "").strip()
    matrix = "".join([c for c in matrix if c.isdigit()]).zfill(2)[-2:] if matrix else None

    session_db = db()
    try:
        aid = to_uuid(artist_id)
        artist = session_db.get(Artist, aid)
        if not artist:
            flash("Artista no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="isrc", isrc_tab="configurador"))

        rec = session_db.get(ArtistISRCSetting, aid)
        if not rec:
            rec = ArtistISRCSetting(artist_id=aid)
            session_db.add(rec)
        rec.artist_matrix = matrix
        rec.updated_at = datetime.now(tz=ZoneInfo("Europe/Madrid"))
        session_db.commit()
        flash(f"ISRC del artista guardado: {artist.name}", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error guardando ISRC del artista: {e}", "danger")
    finally:
        session_db.close()

    return redirect(url_for("discografica_view", section="isrc", isrc_tab="configurador"))


@app.post("/discografica/canciones/bulk-update", endpoint="discografica_songs_bulk_update")
@admin_required
def discografica_songs_bulk_update():
    """Edición EN BLOQUE de canciones del repertorio (distribuidora, categoría, catálogo,
    explícita). Solo aplica los campos con valor; distribuidora/categoría/catálogo se saltan
    las colaboraciones externas (van por su compañía colaboradora)."""
    if not can_edit_discografica():
        return forbid("No tienes permisos para editar canciones.")
    ids = [to_uuid(x) for x in request.form.getlist("song_ids[]")]
    ids = [x for x in ids if x]
    if not ids:
        flash("No hay canciones seleccionadas.", "warning")
        return redirect(url_for("discografica_view", section="canciones", rep_tab="canciones"))
    dist_raw = (request.form.get("distributor_id") or "").strip()
    ownership = (request.form.get("ownership_type") or "").strip().lower()
    catalog_raw = (request.form.get("is_catalog") or "").strip()
    explicit_raw = (request.form.get("is_explicit") or "").strip()
    session_db = db()
    try:
        dist_id = None
        if dist_raw and dist_raw != "__none__":
            dist_id = to_uuid(dist_raw)
            if not dist_id or not session_db.get(Distributor, dist_id):
                flash("Distribuidora no válida.", "warning")
                return redirect(url_for("discografica_view", section="canciones", rep_tab="canciones"))
        songs = session_db.query(Song).filter(Song.id.in_(ids)).all()
        changed = 0
        skipped_external = 0
        for sng in songs:
            touched = False
            if sng.is_external_collab and (dist_raw or ownership or catalog_raw):
                skipped_external += 1
            if not sng.is_external_collab:
                if dist_raw == "__none__" and sng.distributor_id is not None:
                    sng.distributor_id = None; touched = True
                elif dist_id and sng.distributor_id != dist_id:
                    sng.distributor_id = dist_id; touched = True
                if ownership in ("own", "distribution"):
                    new_dist = ownership == "distribution"
                    if bool(sng.is_distribution) != new_dist:
                        sng.is_distribution = new_dist
                        if new_dist:
                            sng.master_ownership_pct = Decimal("0")
                        touched = True
                if catalog_raw in ("0", "1"):
                    new_cat = catalog_raw == "1"
                    if bool(sng.is_catalog) != new_cat:
                        sng.is_catalog = new_cat; touched = True
            if explicit_raw in ("0", "1"):
                new_exp = explicit_raw == "1"
                if bool(sng.is_explicit) != new_exp:
                    sng.is_explicit = new_exp; touched = True
            if touched:
                changed += 1
        session_db.commit()
        msg = f"Cambios aplicados a {changed} canción(es)."
        if skipped_external:
            msg += f" {skipped_external} colaboración(es) externa(s) no se tocaron (distribuidora/categoría no aplican)."
        flash(msg, "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error aplicando los cambios en bloque: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("discografica_view", section="canciones", rep_tab="canciones"))


# ===================== Discográfica · ADELANTOS de distribuidoras =====================
# Un adelanto se RECUPERA con los ingresos del contenido distribuido con su distribuidora,
# según sus condiciones ({%, base bruto/neto, contenido desde/hasta fecha, solo ciertos
# artistas}) y sus excepciones (artistas o canciones que no amortizan). Todo lo que no va a
# amortización es nuestro. Nada se guarda calculado: se recalcula con los ingresos actuales.

def _song_income_periods(session_db, song_ids):
    """Apuntes de ingresos POR PERIODO y canción, deduplicados como en royalties (la fila de
    SEMESTRE prevalece sobre los meses que cubre): {song_id(str): [{'start','end','ptype',
    'gross','net'}]} ordenados por fecha. Alimenta la liquidación de adelantos por
    mes/semestre/año además del total."""
    out = {}
    if not song_ids:
        return out
    sem_ranges = {}
    rows = (
        session_db.query(SongRevenueEntry)
        .filter(SongRevenueEntry.song_id.in_(song_ids))
        .all()
    )
    for r in rows:
        if (r.period_type or "").upper() == "SEMESTER" and r.period_start and r.period_end:
            sem_ranges.setdefault(str(r.song_id), []).append((r.period_start, r.period_end))
    def _dec(v):
        try:
            return Decimal(str(v)) if v is not None else Decimal("0")
        except (InvalidOperation, ValueError):
            return Decimal("0")
    for r in rows:
        sid = str(r.song_id)
        ptype = (r.period_type or "").upper() or "MONTH"
        if ptype == "MONTH":
            covered = any(a <= (r.period_start or date.min) <= b for a, b in sem_ranges.get(sid, []))
            if covered:
                continue
        out.setdefault(sid, []).append({
            "start": r.period_start, "end": r.period_end, "ptype": ptype,
            "gross": _dec(r.gross), "net": _dec(r.net),
        })
    for sid in out:
        out[sid].sort(key=lambda e: (e["start"] or date.min))
    return out


def _add_months(d, months):
    """Suma meses a una fecha ajustando el día al último del mes destino si hace falta."""
    m = d.month - 1 + int(months)
    y = d.year + m // 12
    m = m % 12 + 1
    last = _cal.monthrange(y, m)[1]
    return date(y, m, min(d.day, last))


def _advance_rule_matches(rule, song, song_artist_ids):
    """¿Cubre esta condición a la canción? Fecha de publicación dentro del rango; si limita
    artistas, alguno de los de la canción está en la lista; y si tiene CARENCIA, solo cuando
    ya han pasado N meses desde la publicación de la canción (hasta entonces no amortiza)."""
    if rule.date_from and (not song.release_date or song.release_date < rule.date_from):
        return False
    if rule.date_until and (not song.release_date or song.release_date > rule.date_until):
        return False
    if rule.min_age_months:
        if not song.release_date:
            return False
        if _add_months(song.release_date, int(rule.min_age_months)) > today_local():
            return False
    scope = [str(x) for x in (rule.artist_ids or [])]
    if scope and not (set(scope) & set(song_artist_ids)):
        return False
    return True


def _advance_matching_rule(adv, song, song_artist_ids):
    """Primera condición del adelanto que cubre la canción (o None). Las excepciones del
    adelanto (canción o cualquiera de sus artistas) la excluyen del todo."""
    for exc in (adv.exceptions or []):
        tid = str(exc.target_id)
        if (exc.kind or "").upper() == "SONG" and tid == str(song.id):
            return None
        if (exc.kind or "").upper() == "ARTIST" and tid in song_artist_ids:
            return None
    for rule in (adv.rules or []):
        if _advance_rule_matches(rule, song, song_artist_ids):
            return rule
    return None


_ADV_INCOMES_READY = False


def _build_distributor_advances_context(session_db):
    """Contexto completo de la pestaña Adelantos: por distribuidora, sus adelantos con estado
    de recuperación y la liquidación artista por artista (nº canciones, generado por canción,
    neto, parte que amortiza y parte nuestra). Cada canción amortiza en el PRIMER adelanto
    (por fecha) cuyas condiciones la cubren, hasta agotar su importe."""
    # Blindaje: si el esquema de 2º plano aún no ha creado la tabla de ingresos adicionales
    # (carrera justo tras un deploy), NO reventamos la página — se tratan como vacíos hasta
    # que exista (se cachea en cuanto aparece). Evita el 500 que dejaría «caída» la sección.
    global _ADV_INCOMES_READY
    incomes_ready = _ADV_INCOMES_READY or _table_exists(session_db, "public.distributor_advance_incomes")
    _ADV_INCOMES_READY = incomes_ready
    distributors = session_db.query(Distributor).order_by(Distributor.name.asc()).all()
    _adv_opts = [selectinload(DistributorAdvance.rules),
                 selectinload(DistributorAdvance.exceptions),
                 selectinload(DistributorAdvance.corrections)]
    if incomes_ready:
        _adv_opts.append(selectinload(DistributorAdvance.additional_incomes))
    advances = (
        session_db.query(DistributorAdvance)
        .options(*_adv_opts)
        .order_by(DistributorAdvance.advance_date.asc().nullslast(), DistributorAdvance.created_at.asc())
        .all()
    )
    # Autores de las correcciones e ingresos adicionales (nick + foto, como en el resto de la app).
    corr_user_ids = {str(c.created_by_user_id) for adv in advances for c in (adv.corrections or []) if c.created_by_user_id}
    if incomes_ready:
        corr_user_ids |= {str(i.created_by_user_id) for adv in advances for i in (adv.additional_incomes or []) if i.created_by_user_id}
    corr_authors = {}
    if corr_user_ids:
        for up in session_db.query(UserProfile).filter(UserProfile.user_id.in_([to_uuid(x) for x in corr_user_ids])).all():
            corr_authors[str(up.user_id)] = {"nick": up.nick or "", "photo_url": up.photo_url or ""}
    adv_by_dist = {}
    for adv in advances:
        adv_by_dist.setdefault(str(adv.distributor_id), []).append(adv)

    artists_all = session_db.query(Artist).order_by(Artist.name.asc()).all()
    artist_by_id = {str(a.id): a for a in artists_all}

    blocks = []
    for dist in distributors:
        dist_advs = adv_by_dist.get(str(dist.id), [])
        songs = (
            session_db.query(Song)
            .filter(Song.distributor_id == dist.id, Song.is_external_collab.is_(False))
            .order_by(Song.title.asc())
            .all()
        )
        song_ids = [sng.id for sng in songs]
        sa_rows = (
            session_db.query(SongArtist.song_id, SongArtist.artist_id)
            .filter(SongArtist.song_id.in_(song_ids)).all()
        ) if song_ids else []
        artists_of_song = {}
        for sid, aid in sa_rows:
            artists_of_song.setdefault(str(sid), []).append(str(aid))
        income_periods = _song_income_periods(session_db, song_ids)

        # Cada APUNTE amortiza en orden CRONOLÓGICO (lo cobrado antes recupera antes) en el
        # primer adelanto ACTIVO que: (a) cubre la canción por sus condiciones, y (b) cuyo
        # acuerdo ya estaba FIRMADO — solo cuentan los ingresos generados DESDE la fecha de la
        # firma (advance_date; el periodo que contiene la firma, incluido), NUNCA los ingresos
        # anteriores de esas canciones. Por eso en la liquidación de un adelanto solo aparecen
        # los meses/semestres/años dentro del acuerdo. Si varios adelantos cubren un apunte,
        # gana el primero con importe pendiente (si todos están recuperados, el primero).
        remaining = {}
        corr_total_by_adv = {}
        income_views_by_adv = {}
        income_amort_by_adv = {}
        for adv in dist_advs:
            try:
                amt0 = Decimal(str(adv.amount or 0))
            except (InvalidOperation, ValueError):
                amt0 = Decimal("0")
            corr_total = Decimal("0")
            for c in (adv.corrections or []):
                try:
                    corr_total += Decimal(str(c.amount or 0))
                except (InvalidOperation, ValueError):
                    pass
            corr_total_by_adv[str(adv.id)] = corr_total
            # Ingresos ADICIONALES: cada uno amortiza aplicando su condición de recuperación
            # (base × pct: NET usa el neto, GROSS usa el bruto). Si no tiene regla asignada se
            # aplica la primera del adelanto (al crear, si solo hay una se asigna sola).
            rules_by_id = {str(r.id): r for r in (adv.rules or [])}
            inc_views = []
            inc_amort_total = Decimal("0")
            for inc in ((adv.additional_incomes or []) if incomes_ready else []):
                try:
                    inc_net = Decimal(str(inc.amount_net or 0))
                except (InvalidOperation, ValueError):
                    inc_net = Decimal("0")
                try:
                    inc_gross = Decimal(str(inc.amount_gross or 0))
                except (InvalidOperation, ValueError):
                    inc_gross = Decimal("0")
                rule = rules_by_id.get(str(inc.rule_id)) if inc.rule_id else None
                if rule is None and (adv.rules or []):
                    rule = (adv.rules or [])[0]
                if rule is not None:
                    base = (rule.base or "NET").upper()
                    base_amt = inc_gross if base == "GROSS" else inc_net
                    try:
                        rpct = Decimal(str(rule.pct or 0))
                    except (InvalidOperation, ValueError):
                        rpct = Decimal("0")
                else:
                    base, base_amt, rpct = "NET", inc_net, Decimal("100")
                inc_amort = (base_amt * rpct / Decimal("100")).quantize(Decimal("0.01"))
                inc_amort_total += inc_amort
                # Lo que NO amortiza del ingreso (neto − amortizado) es NUESTRO.
                inc_ours = (inc_net - inc_amort)
                inc_views.append({
                    "id": str(inc.id),
                    "label": inc.label or "Ingreso adicional",
                    "net": inc_net, "gross": inc_gross,
                    "base": base, "pct": rpct, "amort": inc_amort, "ours": inc_ours,
                    "date": inc.income_date,
                    "note": (inc.note or "").strip(),
                    "rule_text": _advance_rule_pdf_text(rule, artist_by_id) if rule is not None else "Sin condición aplicable",
                    "author": corr_authors.get(str(inc.created_by_user_id)) if inc.created_by_user_id else None,
                })
            income_views_by_adv[str(adv.id)] = inc_views
            income_amort_by_adv[str(adv.id)] = inc_amort_total
            # Las correcciones manuales (±) y lo amortizado por los ingresos adicionales entran en
            # la CUENTA GENERAL de amortización: reducen lo pendiente del adelanto.
            remaining[str(adv.id)] = amt0 - corr_total - inc_amort_total
        rows_by_adv = {str(adv.id): [] for adv in dist_advs}
        unassigned_rows = []
        # Para las canciones SIN ingresos (fila a cero en la vista «Todo»): primer adelanto
        # activo que las cubre por condiciones (sin mirar la ventana del acuerdo).
        assign_map = {}
        for sng in songs:
            sid = str(sng.id)
            aids = artists_of_song.get(sid, [])
            chosen = None
            for adv in dist_advs:
                if (adv.status or "ACTIVO").upper() != "ACTIVO":
                    continue
                rule = _advance_matching_rule(adv, sng, aids)
                if rule:
                    chosen = (adv, rule)
                    break
            assign_map[sid] = chosen
        events = []
        for sng in songs:
            for e in income_periods.get(str(sng.id), []):
                events.append((e["start"] or date.min, (sng.title or "").lower(), sng, e))
        events.sort(key=lambda t: (t[0], t[1]))
        for _st, _tt, sng, e in events:
            sid = str(sng.id)
            aids = artists_of_song.get(sid, [])
            row = {
                "song": sng, "artist_ids": aids,
                "start": e["start"], "end": e["end"], "ptype": e["ptype"],
                "gross": e["gross"], "net": e["net"],
                "amort": Decimal("0"), "ours": e["net"],
            }
            period_close = e["end"] or e["start"]
            candidates = []
            for adv in dist_advs:
                if (adv.status or "ACTIVO").upper() != "ACTIVO":
                    continue
                # Fuera del acuerdo: el periodo terminó ANTES de la firma → no retroactivo.
                if adv.advance_date and period_close and period_close < adv.advance_date:
                    continue
                rule = _advance_matching_rule(adv, sng, aids)
                if rule:
                    candidates.append((adv, rule))
            chosen = None
            for adv, rule in candidates:
                if remaining[str(adv.id)] > 0:
                    chosen = (adv, rule)
                    break
            if not chosen and candidates:
                chosen = candidates[0]
            if chosen:
                adv, rule = chosen
                base_amt = e["gross"] if (rule.base or "NET").upper() == "GROSS" else e["net"]
                try:
                    pct = Decimal(str(rule.pct or 0))
                except (InvalidOperation, ValueError):
                    pct = Decimal("0")
                amort_full = (base_amt * pct / Decimal("100")).quantize(Decimal("0.01"))
                take = min(amort_full, max(Decimal("0"), remaining[str(adv.id)]))
                remaining[str(adv.id)] -= take
                row["amort"] = take
                row["ours"] = e["net"] - take
                rows_by_adv[str(adv.id)].append(row)
            else:
                unassigned_rows.append(row)
        # Canciones sin ingresos todavía: fila a cero para que se vean en la vista «Todo».
        for sng in songs:
            sid = str(sng.id)
            if income_periods.get(sid):
                continue
            row = {
                "song": sng, "artist_ids": artists_of_song.get(sid, []),
                "start": None, "end": None, "ptype": None,
                "gross": Decimal("0"), "net": Decimal("0"),
                "amort": Decimal("0"), "ours": Decimal("0"),
            }
            chosen = assign_map.get(sid)
            if chosen:
                rows_by_adv[str(chosen[0].id)].append(row)
            else:
                unassigned_rows.append(row)

        adv_views = []
        for adv in dist_advs:
            try:
                amount = Decimal(str(adv.amount or 0))
            except (InvalidOperation, ValueError):
                amount = Decimal("0")
            rem = max(Decimal("0"), remaining.get(str(adv.id), Decimal("0")))
            recovered = amount - rem
            pct_rec = float(recovered / amount * 100) if amount > 0 else 0.0
            if (adv.status or "ACTIVO").upper() != "ACTIVO":
                state, state_class = "ARCHIVADO", "secondary"
            elif amount > 0 and recovered >= amount:
                state, state_class = "RECUPERADO", "success"
            elif recovered > 0:
                state, state_class = "AMORTIZANDO", "warning"
            else:
                state, state_class = "PENDIENTE", "danger"
            # Agrupar por artista y canción (total histórico, para el PDF y los totales; una
            # canción con varios artistas cuenta en el primero) + filas POR PERIODO para la
            # vista por mes/semestre/año (se agregan en el navegador).
            by_artist = {}
            rows_payload = []
            for row in rows_by_adv.get(str(adv.id), []):
                aid = row["artist_ids"][0] if row["artist_ids"] else ""
                art = artist_by_id.get(aid)
                g = by_artist.setdefault(aid, {
                    "artist": art,
                    "by_song": {},
                    "net": Decimal("0"), "gross": Decimal("0"),
                    "amort": Decimal("0"), "ours": Decimal("0"),
                })
                sk = str(row["song"].id)
                sg = g["by_song"].setdefault(sk, {
                    "song": row["song"],
                    "net": Decimal("0"), "gross": Decimal("0"),
                    "amort": Decimal("0"), "ours": Decimal("0"),
                })
                for k in ("net", "gross", "amort", "ours"):
                    sg[k] += row[k]
                    g[k] += row[k]
                rows_payload.append({
                    "aid": aid,
                    "an": (art.name if art else "Sin artista") or "Sin artista",
                    "ap": (art.photo_url or "") if art else "",
                    "sid": sk,
                    "st": row["song"].title or "",
                    "su": url_for("discografica_song_detail", song_id=row["song"].id),
                    "cv": row["song"].cover_url or "",
                    "ps": row["start"].isoformat() if row["start"] else None,
                    "pt": row["ptype"],
                    "net": float(row["net"]), "gross": float(row["gross"]),
                    "am": float(row["amort"]), "ours": float(row["ours"]),
                })
            artist_groups = []
            for g in by_artist.values():
                g["songs"] = sorted(g.pop("by_song").values(), key=lambda s: (s["song"].title or "").lower())
                artist_groups.append(g)
            artist_groups.sort(key=lambda g: (g["artist"].name.lower() if g["artist"] else "zzz"))
            totals = {
                "songs": sum(len(g["songs"]) for g in artist_groups),
                "net": sum((g["net"] for g in artist_groups), Decimal("0")),
                "amort": sum((g["amort"] for g in artist_groups), Decimal("0")),
                "ours": sum((g["ours"] for g in artist_groups), Decimal("0")),
            }
            corrections_view = []
            for c in sorted((adv.corrections or []), key=lambda x: (x.correction_date or date.min, x.created_at or datetime.min.replace(tzinfo=TZ_MADRID))):
                try:
                    c_amt = Decimal(str(c.amount or 0))
                except (InvalidOperation, ValueError):
                    c_amt = Decimal("0")
                corrections_view.append({
                    "id": str(c.id),
                    "label": c.label or "Corrección",
                    "amount": c_amt,
                    "date": c.correction_date,
                    "note": (c.note or "").strip(),
                    "author": corr_authors.get(str(c.created_by_user_id)) if c.created_by_user_id else None,
                })
            inc_views = income_views_by_adv.get(str(adv.id), [])
            inc_net_sum = sum((iv["net"] for iv in inc_views), Decimal("0"))
            inc_amort_sum = income_amort_by_adv.get(str(adv.id), Decimal("0"))
            inc_ours_sum = sum((iv["ours"] for iv in inc_views), Decimal("0"))
            # El ingreso adicional forma parte de la cuenta: su neto suma al ingreso, lo que
            # amortiza suma a «Amortiza» y el resto (neto − amortizado) suma a «Nuestro».
            totals["net"] += inc_net_sum
            totals["amort"] += inc_amort_sum
            totals["ours"] += inc_ours_sum
            # Filas sintéticas para las vistas por periodo (KPIs/PDF): NO son canciones (inc=1),
            # se filtran del desglose por artista pero cuentan en los totales del periodo.
            for iv in inc_views:
                rows_payload.append({
                    "aid": "__inc__", "an": "Ingresos adicionales", "ap": "",
                    "sid": "inc:" + iv["id"], "st": iv["label"], "su": "", "cv": "",
                    "ps": iv["date"].isoformat() if iv["date"] else None, "pt": None,
                    "net": float(iv["net"]), "gross": float(iv["gross"]),
                    "am": float(iv["amort"]), "ours": float(iv["ours"]),
                    "inc": 1,
                })
            adv_views.append({
                "adv": adv,
                "amount": amount,
                "recovered": recovered,
                "remaining": rem,
                "pct": max(0.0, min(100.0, pct_rec)),
                "state": state,
                "state_class": state_class,
                "artist_groups": artist_groups,
                "totals": totals,
                "rows": rows_payload,
                "corrections": corrections_view,
                "corrections_total": corr_total_by_adv.get(str(adv.id), Decimal("0")),
                "additional_incomes": inc_views,
                "additional_incomes_amort": inc_amort_sum,
                "additional_incomes_net": inc_net_sum,
                "additional_incomes_ours": inc_ours_sum,
            })
        blocks.append({
            "distributor": dist,
            "advances": adv_views,
            "songs": songs,
            "n_songs": len(songs),
            "unassigned": unassigned_rows,
        })
    return {
        "blocks": blocks,
        "distributors": distributors,
        "artists": artists_all,
        "artist_by_id": artist_by_id,
        "has_advances": any(b["advances"] for b in blocks),
    }


@app.post("/discografica/adelantos/crear", endpoint="discografica_advance_create")
@admin_required
def discografica_advance_create():
    if not can_edit_discografica():
        return forbid("No tienes permisos para crear adelantos.")
    session_db = db()
    try:
        dist_id = to_uuid((request.form.get("distributor_id") or "").strip())
        if not dist_id or not session_db.get(Distributor, dist_id):
            flash("Debes seleccionar la distribuidora del adelanto.", "warning")
            return redirect(url_for("discografica_view", section="adelantos"))
        amount = _parse_money_decimal(request.form.get("amount"))
        if amount <= 0:
            flash("El importe del adelanto debe ser mayor que cero.", "warning")
            return redirect(url_for("discografica_view", section="adelantos"))
        contract = request.files.get("contract")
        contract_url = upload_pdf(contract, "distributor_advances") if contract and getattr(contract, "filename", "") else None
        adv = DistributorAdvance(
            distributor_id=dist_id,
            label=(request.form.get("label") or "").strip() or None,
            amount=amount,
            advance_date=parse_optional_date(request.form.get("advance_date")),
            contract_url=contract_url,
            notes=(request.form.get("notes") or "").strip() or None,
        )
        session_db.add(adv)
        session_db.flush()
        session_db.add(_advance_rule_from_form(adv.id, request.form))
        session_db.commit()
        flash("Adelanto creado.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error creando el adelanto: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("discografica_view", section="adelantos"))


def _advance_rule_from_form(advance_id, form, sort_order=0):
    """Construye una condición de recuperación desde el formulario (wizard o «añadir condición»)."""
    try:
        pct = Decimal((form.get("rule_pct") or "100").strip().replace(",", "."))
    except (InvalidOperation, ValueError):
        pct = Decimal("100")
    pct = max(Decimal("0"), min(Decimal("100"), pct))
    base = (form.get("rule_base") or "NET").strip().upper()
    if base not in ("NET", "GROSS"):
        base = "NET"
    scope = (form.get("rule_scope") or "all").strip().lower()
    date_from = parse_optional_date(form.get("rule_date_from")) if scope == "from" else None
    date_until = parse_optional_date(form.get("rule_date_until")) if scope == "until" else None
    artists_mode = (form.get("rule_artists_mode") or "all").strip().lower()
    artist_ids = None
    if artists_mode == "some":
        artist_ids = [str(to_uuid(x)) for x in form.getlist("rule_artist_ids[]") if to_uuid(x)]
        artist_ids = artist_ids or None
    # Carencia: cada canción amortiza solo cuando pasan N meses/años desde SU publicación.
    min_age_months = None
    if (form.get("rule_age_mode") or "now").strip().lower() == "age":
        try:
            n = int((form.get("rule_age_num") or "0").strip() or "0")
        except ValueError:
            n = 0
        unit = (form.get("rule_age_unit") or "months").strip().lower()
        if unit in ("years", "anios", "años"):
            n *= 12
        min_age_months = n if n > 0 else None
    return DistributorAdvanceRule(
        advance_id=advance_id, pct=pct, base=base,
        date_from=date_from, date_until=date_until,
        artist_ids=artist_ids, min_age_months=min_age_months, sort_order=sort_order,
    )


def _get_advance_or_redirect(session_db, aid):
    adv = session_db.get(DistributorAdvance, to_uuid(aid))
    return adv


@app.post("/discografica/adelantos/<aid>/actualizar", endpoint="discografica_advance_update")
@admin_required
def discografica_advance_update(aid):
    if not can_edit_discografica():
        return forbid("No tienes permisos para editar adelantos.")
    session_db = db()
    try:
        adv = _get_advance_or_redirect(session_db, aid)
        if not adv:
            flash("Adelanto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="adelantos"))
        if request.form.get("label") is not None:
            adv.label = (request.form.get("label") or "").strip() or None
        if (request.form.get("amount") or "").strip():
            amt = _parse_money_decimal(request.form.get("amount"))
            if amt > 0:
                adv.amount = amt
        if request.form.get("advance_date") is not None:
            adv.advance_date = parse_optional_date(request.form.get("advance_date"))
        if request.form.get("notes") is not None:
            adv.notes = (request.form.get("notes") or "").strip() or None
        status = (request.form.get("status") or "").strip().upper()
        if status in ("ACTIVO", "ARCHIVADO"):
            adv.status = status
        contract = request.files.get("contract")
        if contract and getattr(contract, "filename", ""):
            adv.contract_url = upload_pdf(contract, "distributor_advances")
        adv.updated_at = datetime.utcnow()
        session_db.commit()
        flash("Adelanto actualizado.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error actualizando el adelanto: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("discografica_view", section="adelantos"))


