def _advance_rule_pdf_text(rule, artist_by_id):
    """Texto corto de una condición de recuperación (para pastillas del PDF)."""
    try:
        pct = Decimal(str(rule.pct or 0))
    except (InvalidOperation, ValueError):
        pct = Decimal("0")
    pct_txt = f"{pct:.2f}".rstrip("0").rstrip(".").replace(".", ",")
    bits = [f"{pct_txt}% sobre {'BRUTO' if (rule.base or 'NET').upper() == 'GROSS' else 'NETO'}"]
    if rule.date_from:
        bits.append("publicado desde " + rule.date_from.strftime("%d/%m/%Y"))
    if rule.date_until:
        bits.append("publicado hasta " + rule.date_until.strftime("%d/%m/%Y"))
    if rule.min_age_months:
        n = int(rule.min_age_months)
        bits.append(("amortiza tras %d año(s)" % (n // 12)) if n % 12 == 0 else ("amortiza tras %d mes(es)" % n))
    if rule.artist_ids:
        names = [getattr(artist_by_id.get(str(a)), "name", None) or "¿?" for a in rule.artist_ids]
        bits.append("solo " + ", ".join(names))
    return " · ".join(bits)


@app.get("/discografica/adelantos/<aid>/pdf", endpoint="discografica_advance_pdf")
@admin_required
def discografica_advance_pdf(aid):
    """Balance del adelanto en PDF con el estilo de casa: logo de PIES arriba a la derecha,
    título centrado, cabecera de PASTILLAS (distribuidora, importe, firma, condiciones,
    excepciones), barra de estado de la devolución en color y «galletas» resumen (importe
    adelantado / adelanto restante / recuperado / nuestro), seguido de la liquidación
    artista por artista."""
    if not REPORTLAB_AVAILABLE:
        abort(503, "Generación de PDF no disponible en el servidor.")
    from reportlab.lib.pagesizes import A4
    from reportlab.lib import colors
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib.units import mm
    from reportlab.lib.utils import ImageReader
    from reportlab.pdfbase.pdfmetrics import stringWidth
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle
    session_db = db()
    try:
        adv = session_db.get(DistributorAdvance, to_uuid(aid))
        if not adv:
            abort(404)
        ctx = _build_distributor_advances_context(session_db)
        view = None
        dist = None
        blk_songs = []
        for block in ctx["blocks"]:
            for v in block["advances"]:
                if str(v["adv"].id) == str(adv.id):
                    view, dist, blk_songs = v, block["distributor"], block["songs"]
                    break
            if view:
                break
        if not view:
            abort(404)
        artist_by_id = ctx["artist_by_id"]

        def eur_txt(x):
            try:
                q = Decimal(str(x or 0)).quantize(Decimal("0.01"))
            except (InvalidOperation, ValueError):
                q = Decimal("0")
            ent, dec = f"{q:.2f}".split(".")
            ent = "{:,}".format(int(ent)).replace(",", ".")
            return f"{ent},{dec} €"

        # ----- Logo de PIES (empresa del grupo; caída al logo estático) -----
        logo_reader = None
        try:
            logo_url, _ = _royalty_liquidation_brand_assets(session_db)
            if logo_url and logo_url.lower().startswith("http"):
                import urllib.request
                raw = urllib.request.urlopen(logo_url, timeout=6).read()
                logo_reader = ImageReader(BytesIO(raw))
        except Exception:
            logo_reader = None
        if logo_reader is None:
            try:
                logo_reader = ImageReader(os.path.join(app.static_folder, "img", "logo.png"))
            except Exception:
                logo_reader = None

        # ----- Cabecera: pastillas (flujo con salto de línea) + barra + galletas -----
        page_w, page_h = A4
        margin = 14 * mm
        usable_w = page_w - 2 * margin
        BRAND = colors.HexColor("#E33D48")
        GREY_T = colors.HexColor("#6b7683")
        state_hex = {"success": "#1e7e34", "warning": "#e0a800", "danger": "#dc3545", "secondary": "#6c757d"}
        state_col = colors.HexColor(state_hex.get(view["state_class"], "#6c757d"))

        pill_font, pill_sz, pill_h, pill_gap = "Helvetica", 8.2, 15.0, 5.0

        def pill_rows(texts, bold_prefixes=False):
            """Reparte pastillas en filas que caben en el ancho útil. [(texto, ancho)]"""
            rows, cur, cur_w = [], [], 0.0
            for t in texts:
                w = stringWidth(t, pill_font, pill_sz) + 14
                w = min(w, usable_w)
                if cur and cur_w + pill_gap + w > usable_w:
                    rows.append(cur)
                    cur, cur_w = [], 0.0
                cur.append((t, w))
                cur_w += (pill_gap if len(cur) > 1 else 0) + w
            if cur:
                rows.append(cur)
            return rows

        data_pills = [
            "Distribuidora: " + (dist.name or "—"),
            "Importe del adelanto: " + eur_txt(view["amount"]),
            "Fecha de la firma: " + (adv.advance_date.strftime("%d/%m/%Y") if adv.advance_date else "—"),
        ]
        if adv.label:
            data_pills.insert(0, "Adelanto: " + adv.label)
        cond_pills = [_advance_rule_pdf_text(r, artist_by_id) for r in (adv.rules or [])] or ["Sin condiciones configuradas"]
        exc_pills = []
        for e in (adv.exceptions or []):
            if (e.kind or "").upper() == "ARTIST":
                a = artist_by_id.get(str(e.target_id))
                exc_pills.append("Artista: " + (a.name if a else "eliminado"))
            else:
                sng = next((s for s in blk_songs if str(s.id) == str(e.target_id)), None)
                exc_pills.append("Canción: " + (sng.title if sng else "eliminada"))

        groups = [
            ("DATOS DEL ADELANTO", data_pills, colors.HexColor("#f6f8fa"), colors.HexColor("#c9d2dc"), colors.HexColor("#212529")),
            ("CONDICIONES DE RECUPERACIÓN", cond_pills, colors.HexColor("#fdecee"), BRAND, colors.HexColor("#8d2630")),
        ]
        if exc_pills:
            groups.append(("EXCEPCIONES (NO AMORTIZAN)", exc_pills, colors.HexColor("#fff8e6"), colors.HexColor("#e0a800"), colors.HexColor("#7a5b00")))

        # Altura total de la cabecera (para que el contenido empiece debajo).
        header_top = page_h - 12 * mm
        y_cursor = header_top - 40          # logo + título
        y_cursor -= 26                      # subtítulo + aire
        group_layouts = []
        for gtitle, texts, bgc, brc, txc in groups:
            rows = pill_rows(texts)
            group_layouts.append((gtitle, rows, bgc, brc, txc))
            y_cursor -= 14                  # rótulo del grupo (+ aire)
            y_cursor -= len(rows) * (pill_h + 4)
            y_cursor -= 4
        y_cursor -= 26                      # título del PERIODO mostrado (centrado)
        y_cursor -= 8 + 16                  # barra de estado
        y_cursor -= 10 + 44                 # galletas
        y_cursor -= 10                      # holgura antes de la tabla
        header_h = header_top - y_cursor

        def draw_header(pdf_c, _doc):
            y = header_top
            # Logo PIES arriba a la DERECHA
            if logo_reader:
                try:
                    iw, ih = logo_reader.getSize()
                    box_w, box_h = 110.0, 34.0
                    sc = min(box_w / iw, box_h / ih)
                    pdf_c.drawImage(logo_reader, page_w - margin - iw * sc, y - ih * sc,
                                    width=iw * sc, height=ih * sc, preserveAspectRatio=True, mask="auto")
                except Exception:
                    pass
            y -= 40
            # Título centrado + subtítulo
            pdf_c.setFillColor(colors.HexColor("#212529"))
            pdf_c.setFont("Helvetica-Bold", 18)
            pdf_c.drawCentredString(page_w / 2, y, "Balance de adelanto")
            y -= 15
            pdf_c.setFillColor(GREY_T)
            pdf_c.setFont("Helvetica", 10)
            sub_bits = [dist.name or "Distribuidora"]
            if adv.label:
                sub_bits.append(adv.label)
            pdf_c.drawCentredString(page_w / 2, y, " · ".join(sub_bits))
            y -= 11
            # Grupos de pastillas
            for gtitle, rows, bgc, brc, txc in group_layouts:
                y -= 10
                pdf_c.setFillColor(GREY_T)
                pdf_c.setFont("Helvetica-Bold", 6.6)
                pdf_c.drawString(margin, y, gtitle)
                y -= 4
                for row in rows:
                    y -= pill_h
                    x = margin
                    for txt, w in row:
                        pdf_c.setFillColor(bgc)
                        pdf_c.setStrokeColor(brc)
                        pdf_c.setLineWidth(0.8)
                        pdf_c.roundRect(x, y, w, pill_h, pill_h / 2, fill=1, stroke=1)
                        pdf_c.setFillColor(txc)
                        pdf_c.setFont(pill_font, pill_sz)
                        pdf_c.drawString(x + 7, y + 4.2, txt)
                        x += w + pill_gap
                    y -= 4
                y -= 4
            # Título del PERIODO mostrado (Total / mes / semestre / año), centrado
            y -= 18
            pdf_c.setFillColor(colors.HexColor("#212529"))
            pdf_c.setFont("Helvetica-Bold", 12.5)
            pdf_c.drawCentredString(page_w / 2, y, period_title)
            y -= 8
            # Barra de estado de la devolución (en color según el estado)
            y -= 8
            bar_h = 16.0
            y -= bar_h
            pdf_c.setFillColor(colors.HexColor("#eef1f5"))
            pdf_c.setStrokeColor(colors.HexColor("#d5dce3"))
            pdf_c.roundRect(margin, y, usable_w, bar_h, bar_h / 2, fill=1, stroke=1)
            fill_w = max(0.0, min(1.0, view["pct"] / 100.0)) * usable_w
            if fill_w > bar_h:
                pdf_c.setFillColor(state_col)
                pdf_c.setStrokeColor(state_col)
                pdf_c.roundRect(margin, y, fill_w, bar_h, bar_h / 2, fill=1, stroke=0)
            pdf_c.setFont("Helvetica-Bold", 8.2)
            pct_txt = f"{view['pct']:.0f}% recuperado · {view['state']}"
            if fill_w > stringWidth(pct_txt, "Helvetica-Bold", 8.2) + 20:
                pdf_c.setFillColor(colors.white)
                pdf_c.drawString(margin + 10, y + 4.6, pct_txt)
            else:
                pdf_c.setFillColor(colors.HexColor("#212529"))
                pdf_c.drawString(margin + max(fill_w, 0) + 8, y + 4.6, pct_txt)
            # Galletas resumen: Importe adelantado · Importe recuperado · Nuestro
            y -= 10
            cookie_h = 44.0
            y -= cookie_h
            cookies = [
                ("IMPORTE ADELANTADO", eur_txt(view["amount"]), colors.HexColor("#212529")),
                (cookie_remaining_label, eur_txt(cookie_remaining), colors.HexColor("#b02a37")),
                (cookie_recovered_label, eur_txt(cookie_recovered), state_col),
                (cookie_ours_label, eur_txt(cookie_ours), colors.HexColor("#1e7e34")),
            ]
            gap = 8.0
            cw = (usable_w - gap * (len(cookies) - 1)) / len(cookies)
            x = margin
            for lab, val, vcol in cookies:
                pdf_c.setFillColor(colors.HexColor("#f6f8fa"))
                pdf_c.setStrokeColor(colors.HexColor("#d5dce3"))
                pdf_c.roundRect(x, y, cw, cookie_h, 8, fill=1, stroke=1)
                pdf_c.setFillColor(GREY_T)
                pdf_c.setFont("Helvetica-Bold", 6.8)
                pdf_c.drawCentredString(x + cw / 2, y + cookie_h - 13, lab)
                pdf_c.setFillColor(vcol)
                # Fuente adaptada al ancho de la galleta (más galletas = menos ancho).
                v_sz = 14.0
                while v_sz > 8.5 and stringWidth(val, "Helvetica-Bold", v_sz) > (cw - 10):
                    v_sz -= 0.5
                pdf_c.setFont("Helvetica-Bold", v_sz)
                pdf_c.drawCentredString(x + cw / 2, y + 10, val)
                x += cw + gap
            # Pie de página
            pdf_c.setFillColor(GREY_T)
            pdf_c.setFont("Helvetica", 8)
            pdf_c.drawRightString(page_w - margin, 10 * mm, "Página 1")

        def draw_later(pdf_c, _doc):
            if logo_reader:
                try:
                    iw, ih = logo_reader.getSize()
                    sc = min(70.0 / iw, 22.0 / ih)
                    pdf_c.drawImage(logo_reader, page_w - margin - iw * sc, page_h - 10 * mm - ih * sc,
                                    width=iw * sc, height=ih * sc, preserveAspectRatio=True, mask="auto")
                except Exception:
                    pass
            pdf_c.setFillColor(GREY_T)
            pdf_c.setFont("Helvetica", 8)
            pdf_c.drawRightString(page_w - margin, 10 * mm, f"Página {pdf_c.getPageNumber()}")

        buf = BytesIO()
        doc = SimpleDocTemplate(buf, pagesize=A4, topMargin=12*mm, bottomMargin=16*mm, leftMargin=margin, rightMargin=margin)
        styles = getSampleStyleSheet()
        h2 = ParagraphStyle("h2x", parent=styles["Heading2"], fontSize=11, spaceBefore=8, spaceAfter=3)
        # ----- Resumen POR ARTISTA (con foto) del periodo elegido en pantalla -----
        MESES_ES = ["enero", "febrero", "marzo", "abril", "mayo", "junio",
                    "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"]
        gran = (request.args.get("gran") or "all").strip().lower()
        p_key = (request.args.get("p") or "").strip() or None

        def _bucket(ps):
            if not ps:
                return None
            y, m = ps[:4], int(ps[5:7] or 1)
            if gran == "year":
                return y
            if gran == "sem":
                return f"{y}-S{1 if m <= 6 else 2}"
            if gran == "month":
                return ps[:7]
            return None

        rows_sel = view["rows"]
        if gran in ("year", "sem", "month") and p_key:
            rows_sel = [r for r in rows_sel if r.get("ps") and _bucket(r["ps"]) == p_key]
            if gran == "month":
                period_title = f"{MESES_ES[int(p_key[5:7]) - 1]} {p_key[:4]}"
            elif gran == "sem":
                period_title = ("1º" if p_key.endswith("S1") else "2º") + " semestre " + p_key[:4]
            else:
                period_title = "Año " + p_key
        else:
            period_title = "Total · todo el acuerdo"

        # Correcciones e ingresos adicionales del PERIODO elegido (por su fecha), para que el PDF
        # cuadre con lo que se ve en pantalla. Sin periodo → todo el acuerdo.
        def _adj_in_period(d):
            if gran not in ("year", "sem", "month") or not p_key:
                return True
            return bool(d) and _bucket(d.isoformat()) == p_key

        corrections_sel = [c for c in view["corrections"] if _adj_in_period(c["date"])]
        incomes_sel = [it for it in view["additional_incomes"] if _adj_in_period(it["date"])]

        # El desglose por artista es SOLO de canciones; los ingresos adicionales (r["inc"]) van
        # en su propia tabla, así la fila de TOTALES cuadra con las filas de artistas.
        song_rows_sel = [r for r in rows_sel if not r.get("inc")]

        # Galletas RECUPERADO y NUESTRO: cuando se ve un PERIODO concreto reflejan ESE periodo
        # (amortización de canciones + ingresos adicionales + correcciones de ese periodo); en
        # «Total» son de todo el acuerdo. El ADELANTO RESTANTE del periodo es el pendiente AL FINAL
        # de ese periodo = importe − amortizado ACUMULADO hasta el final del periodo (todo lo
        # recuperado con fecha dentro o antes del periodo). El importe adelantado es la referencia.
        _is_period = bool(gran in ("year", "sem", "month") and p_key)
        if _is_period:
            _amort_period = sum(float(r["am"]) for r in song_rows_sel) + sum(float(it["amort"]) for it in incomes_sel)
            _corr_period = sum(float(c["amount"]) for c in corrections_sel)
            cookie_recovered = _amort_period + _corr_period
            cookie_ours = sum(float(r["ours"]) for r in song_rows_sel) + sum(float(it["ours"]) for it in incomes_sel)
            cookie_recovered_label = "RECUPERADO EN EL PERIODO"
            cookie_ours_label = "NUESTRO EN EL PERIODO"
            # Recuperado ACUMULADO hasta el final del periodo (bucket <= periodo elegido).
            _cum = 0.0
            for _r in view["rows"]:
                _b = _bucket(_r["ps"]) if _r.get("ps") else None
                if _b is not None and _b <= p_key:
                    _cum += float(_r.get("am") or 0)
            for _c in view["corrections"]:
                _b = _bucket(_c["date"].isoformat()) if _c.get("date") else None
                if _b is not None and _b <= p_key:
                    _cum += float(_c.get("amount") or 0)
            cookie_remaining = max(0.0, float(view["amount"]) - _cum)
            cookie_remaining_label = "RESTANTE TRAS EL PERIODO"
        else:
            cookie_recovered = float(view["recovered"])
            cookie_ours = float(view["totals"]["ours"])
            cookie_recovered_label = "IMPORTE RECUPERADO"
            cookie_ours_label = "NUESTRO"
            cookie_remaining = float(view["remaining"])
            cookie_remaining_label = "ADELANTO RESTANTE"
        by_artist_pdf = {}
        for r in song_rows_sel:
            g = by_artist_pdf.setdefault(r["aid"], {
                "an": r["an"], "ap": r["ap"], "sids": set(),
                "net": 0.0, "am": 0.0, "ours": 0.0,
            })
            g["sids"].add(r["sid"])
            g["net"] += r["net"]; g["am"] += r["am"]; g["ours"] += r["ours"]
        artist_rows = sorted(by_artist_pdf.values(), key=lambda g: (g["an"] or "").lower())

        # Fotos de artistas (remotas, en pequeño; si fallan, celda vacía).
        def _photo_flowable(url):
            if not url:
                return ""
            try:
                import urllib.request
                raw = urllib.request.urlopen(url, timeout=5).read()
                if PILLOW_AVAILABLE and PILImage is not None:
                    with PILImage.open(BytesIO(raw)) as img:
                        img = img.convert("RGB")
                        resampling = getattr(getattr(PILImage, "Resampling", PILImage), "LANCZOS", getattr(PILImage, "LANCZOS", 1))
                        img.thumbnail((80, 80), resampling)
                        out = BytesIO()
                        img.save(out, format="JPEG", quality=80)
                        out.seek(0)
                        raw = out.getvalue()
                return RLImage(BytesIO(raw), width=14, height=14)
            except Exception:
                return ""

        from reportlab.platypus import Image as RLImage
        name_style = ParagraphStyle("anx", parent=styles["Normal"], fontSize=9, leading=11)
        data = [["", "Artista", "Canciones", "Neto generado", "Amortizado", "Nuestro"]]
        for g in artist_rows:
            data.append([
                _photo_flowable(g["ap"]),
                Paragraph((g["an"] or "Sin artista"), name_style),
                str(len(g["sids"])),
                eur_txt(g["net"]), eur_txt(g["am"]), eur_txt(g["ours"]),
            ])
        tot_songs = len({r["sid"] for r in song_rows_sel})
        tot_net = sum(r["net"] for r in song_rows_sel)
        tot_am = sum(r["am"] for r in song_rows_sel)
        tot_ours = sum(r["ours"] for r in song_rows_sel)
        data.append(["", "TOTALES", str(tot_songs), eur_txt(tot_net), eur_txt(tot_am), eur_txt(tot_ours)])

        story = [Spacer(1, header_h)]
        # Correcciones manuales (cuenta de amortización) del periodo elegido, antes del desglose.
        if corrections_sel:
            story.append(Paragraph("Correcciones manuales", h2))
            note_style = ParagraphStyle("cnx", parent=styles["Normal"], fontSize=8.6, leading=10.5)
            cdata = [["Corrección", "Fecha", "Autor", "Importe"]]
            for c in corrections_sel:
                lbl = c["label"] + ((" — " + c["note"]) if c["note"] else "")
                cdata.append([
                    Paragraph(lbl, note_style),
                    c["date"].strftime("%d/%m/%Y") if c["date"] else "—",
                    (c["author"] or {}).get("nick") or "—",
                    ("−" if c["amount"] < 0 else "+") + eur_txt(-c["amount"] if c["amount"] < 0 else c["amount"]),
                ])
            ct_total = sum((c["amount"] for c in corrections_sel), Decimal("0"))
            cdata.append(["Total correcciones", "", "",
                          ("−" if ct_total < 0 else "+") + eur_txt(-ct_total if ct_total < 0 else ct_total)])
            ct = Table(cdata, colWidths=[None, 24*mm, 34*mm, 28*mm], repeatRows=1)
            ct.setStyle(TableStyle([
                ("FONT", (0, 0), (-1, -1), "Helvetica", 8.6),
                ("FONT", (0, 0), (-1, 0), "Helvetica-Bold", 8.4),
                ("FONT", (0, -1), (-1, -1), "Helvetica-Bold", 8.8),
                ("TEXTCOLOR", (0, 0), (-1, 0), colors.HexColor("#49515d")),
                ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#f1f4f8")),
                ("LINEBELOW", (0, 0), (-1, 0), 0.7, colors.HexColor("#c9d2dc")),
                ("LINEABOVE", (0, -1), (-1, -1), 0.9, colors.HexColor("#9aa8b5")),
                ("ALIGN", (1, 0), (-1, -1), "RIGHT"),
                ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
                ("ROWBACKGROUNDS", (0, 1), (-1, -2), [colors.white, colors.HexColor("#fafbfc")]),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
                ("TOPPADDING", (0, 0), (-1, -1), 3),
            ]))
            story.append(ct)
            story.append(Spacer(1, 10))
        # Ingresos adicionales (amortizan aplicando su condición: base × pct) del periodo elegido.
        if incomes_sel:
            story.append(Paragraph("Ingresos adicionales", h2))
            inote = ParagraphStyle("inx", parent=styles["Normal"], fontSize=8.6, leading=10.5)
            idata = [["Ingreso adicional", "Fecha", "Neto", "Bruto", "Amortiza", "Nuestro"]]

            def _xml_escape(txt):
                return (txt or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

            for it in incomes_sel:
                sub = it.get("rule_text") or ""
                if it.get("author"):
                    sub = (sub + " · " if sub else "") + ((it["author"] or {}).get("nick") or "")
                if it.get("note"):
                    sub = (sub + " · " if sub else "") + it["note"]
                lbl = _xml_escape(it["label"]) + (("<br/><font size=7 color='#8a94a1'>" + _xml_escape(sub) + "</font>") if sub else "")
                idata.append([
                    Paragraph(lbl, inote),
                    it["date"].strftime("%d/%m/%Y") if it["date"] else "—",
                    eur_txt(it["net"]), eur_txt(it["gross"]), eur_txt(it["amort"]), eur_txt(it["ours"]),
                ])
            idata.append(["Total ingresos adicionales", "", "", "",
                          eur_txt(sum((it["amort"] for it in incomes_sel), Decimal("0"))),
                          eur_txt(sum((it["ours"] for it in incomes_sel), Decimal("0")))])
            itbl = Table(idata, colWidths=[None, 20*mm, 23*mm, 23*mm, 24*mm, 24*mm], repeatRows=1)
            itbl.setStyle(TableStyle([
                ("FONT", (0, 0), (-1, -1), "Helvetica", 8.6),
                ("FONT", (0, 0), (-1, 0), "Helvetica-Bold", 8.4),
                ("FONT", (0, -1), (-1, -1), "Helvetica-Bold", 8.8),
                ("TEXTCOLOR", (0, 0), (-1, 0), colors.HexColor("#49515d")),
                ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#f1f4f8")),
                ("LINEBELOW", (0, 0), (-1, 0), 0.7, colors.HexColor("#c9d2dc")),
                ("LINEABOVE", (0, -1), (-1, -1), 0.9, colors.HexColor("#9aa8b5")),
                ("ALIGN", (1, 0), (-1, -1), "RIGHT"),
                ("TEXTCOLOR", (4, 1), (4, -1), colors.HexColor("#b02a37")),
                ("TEXTCOLOR", (5, 1), (5, -1), colors.HexColor("#1e7e34")),
                ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
                ("ROWBACKGROUNDS", (0, 1), (-1, -2), [colors.white, colors.HexColor("#fafbfc")]),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
                ("TOPPADDING", (0, 0), (-1, -1), 3),
            ]))
            story.append(itbl)
            story.append(Spacer(1, 10))
        story.append(Paragraph("Desglose por artista", h2))
        if len(data) <= 2 and not artist_rows:
            story.append(Paragraph("Sin ingresos en este periodo.", ParagraphStyle(
                "emptyx", parent=styles["Normal"], fontSize=10, textColor=GREY_T)))
        else:
            t = Table(data, colWidths=[8*mm, None, 22*mm, 30*mm, 30*mm, 30*mm], repeatRows=1)
            t.setStyle(TableStyle([
                ("FONT", (0, 0), (-1, -1), "Helvetica", 9),
                ("FONT", (0, 0), (-1, 0), "Helvetica-Bold", 8.6),
                ("FONT", (0, -1), (-1, -1), "Helvetica-Bold", 9.2),
                ("TEXTCOLOR", (0, 0), (-1, 0), colors.HexColor("#49515d")),
                ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#f1f4f8")),
                ("LINEBELOW", (0, 0), (-1, 0), 0.7, colors.HexColor("#c9d2dc")),
                ("LINEABOVE", (0, -1), (-1, -1), 0.9, colors.HexColor("#9aa8b5")),
                ("BACKGROUND", (0, -1), (-1, -1), colors.HexColor("#f6f8fa")),
                ("ALIGN", (2, 0), (-1, -1), "RIGHT"),
                ("TEXTCOLOR", (4, 1), (4, -1), colors.HexColor("#b02a37")),
                ("TEXTCOLOR", (5, 1), (5, -1), colors.HexColor("#1e7e34")),
                ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
                ("ROWBACKGROUNDS", (0, 1), (-1, -2), [colors.white, colors.HexColor("#fafbfc")]),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
                ("TOPPADDING", (0, 0), (-1, -1), 4),
                ("LEFTPADDING", (0, 0), (0, -1), 2),
                ("RIGHTPADDING", (0, 0), (0, -1), 0),
            ]))
            story.append(t)
        doc.build(story, onFirstPage=draw_header, onLaterPages=draw_later)
        buf.seek(0)
        fname = f"adelanto_{(dist.name or 'distribuidora').replace(' ', '_').lower()}.pdf"
        return send_file(buf, mimetype="application/pdf", as_attachment=False, download_name=fname)
    finally:
        session_db.close()


@app.post("/discografica/canciones/create")
@admin_required
def discografica_song_create():
    if not can_edit_discografica():
        return forbid("No tienes permisos para añadir canciones.")

    title = (request.form.get("title") or "").strip()
    release_date_raw = (request.form.get("release_date") or "").strip()
    artist_id = to_uuid((request.form.get("artist_id") or "").strip())
    is_catalog = bool(request.form.get("is_catalog"))
    interpreter_names = [re.sub(r"\s+", " ", (name or "").strip()) for name in request.form.getlist("interpreter_name[]") if re.sub(r"\s+", " ", (name or "").strip())]
    interpreter_main_values = [(value or "0").strip() for value in request.form.getlist("interpreter_is_main[]")]

    ownership_type = (request.form.get("ownership_type") or "own").strip().lower()
    is_distribution = ownership_type == "distribution"
    is_external_collab = ownership_type == "external_collab"
    master_pct_raw = (request.form.get("master_ownership_pct") or "").strip()

    master_pct = None
    if is_distribution or is_external_collab:
        master_pct = Decimal("0")
    else:
        try:
            master_pct = Decimal(master_pct_raw) if master_pct_raw else Decimal("100")
        except (InvalidOperation, ValueError):
            master_pct = Decimal("100")
        # acotar
        if master_pct < 0:
            master_pct = Decimal("0")
        if master_pct > 100:
            master_pct = Decimal("100")

    # Colaboración externa: % que nos corresponde + base (bruto/neto) + compañía colaboradora (tercero).
    external_company_id = None
    our_pct = Decimal("0")
    our_pct_base = "GROSS"
    if is_external_collab:
        is_catalog = False  # catálogo solo aplica a propia/distribución
        external_company_id = to_uuid((request.form.get("external_company_id") or "").strip())
        try:
            our_pct = Decimal((request.form.get("our_pct") or "").strip() or "0")
        except (InvalidOperation, ValueError):
            our_pct = Decimal("0")
        our_pct = max(Decimal("0"), min(Decimal("100"), our_pct))
        our_pct_base = (request.form.get("our_pct_base") or "GROSS").strip().upper()
        if our_pct_base not in ("GROSS", "NET"):
            our_pct_base = "GROSS"

    if is_external_collab and not external_company_id:
        flash("En una colaboración externa debes indicar la compañía colaboradora (un tercero).", "warning")
        return redirect(url_for("discografica_view", section="canciones"))

    # Distribuidora: solo canciones propias o de distribución (las externas van por su compañía).
    distributor_id = None
    if not is_external_collab:
        distributor_id = to_uuid((request.form.get("distributor_id") or "").strip())

    if not title:
        flash("El nombre de la canción es obligatorio.", "warning")
        return redirect(url_for("discografica_view", section="canciones"))
    if not release_date_raw:
        flash("La fecha de publicación es obligatoria.", "warning")
        return redirect(url_for("discografica_view", section="canciones"))
    if not artist_id:
        flash("Debes seleccionar un artista.", "warning")
        return redirect(url_for("discografica_view", section="canciones"))

    session_db = db()
    try:
        release_date = parse_date(release_date_raw)
        s = Song(
            title=title,
            collaborator=None,
            release_date=release_date,
            is_catalog=is_catalog,
            is_distribution=is_distribution,
            master_ownership_pct=master_pct,
            is_external_collab=is_external_collab,
            external_company_id=external_company_id,
            our_pct=our_pct,
            our_pct_base=our_pct_base,
            distributor_id=distributor_id,
        )
        session_db.add(s)
        session_db.flush()  # para obtener s.id
        session_db.add(SongArtist(song_id=s.id, artist_id=artist_id))

        # Estado por defecto
        session_db.add(SongStatus(song_id=s.id, cover_done=False))

        # Intérpretes: se guardan desde el formulario y los colaboradores se calculan
        # automáticamente como todos los intérpretes que no sean el propio artista.
        primary_artist = session_db.get(Artist, artist_id)
        primary_name = re.sub(r"\s+", " ", (getattr(primary_artist, "name", None) or "").strip())
        interpreter_rows: list[tuple[str, bool]] = []
        seen_interpreters: set[str] = set()
        for idx, raw_name in enumerate(interpreter_names):
            clean_name = re.sub(r"\s+", " ", (raw_name or "").strip())
            if not clean_name:
                continue
            key = _norm_person_name_key(clean_name)
            if key in seen_interpreters:
                continue
            seen_interpreters.add(key)
            main_val = interpreter_main_values[idx] if idx < len(interpreter_main_values) else "0"
            is_main = main_val in ("1", "true", "True", "MAIN")
            interpreter_rows.append((clean_name, is_main))

        if primary_name and _norm_person_name_key(primary_name) not in seen_interpreters:
            interpreter_rows.insert(0, (primary_name, True))
            seen_interpreters.add(_norm_person_name_key(primary_name))
        elif primary_name:
            interpreter_rows = [
                (name, True if _norm_person_name_key(name) == _norm_person_name_key(primary_name) else is_main)
                for name, is_main in interpreter_rows
            ]

        if not interpreter_rows and primary_name:
            interpreter_rows = [(primary_name, True)]

        for clean_name, is_main in interpreter_rows:
            session_db.add(SongInterpreter(song_id=s.id, name=clean_name, is_main=is_main))

        s.collaborator = _song_collaborator_from_names([primary_name] if primary_name else [], [name for name, _is_main in interpreter_rows])

        session_db.commit()
        flash("Canción creada.", "success")
        return redirect(url_for("discografica_song_detail", song_id=str(s.id)))
    except Exception as e:
        session_db.rollback()
        flash(f"Error creando canción: {e}", "danger")
        return redirect(url_for("discografica_view", section="canciones"))
    finally:
        session_db.close()




