@app.post("/discografica/canciones/<song_id>/editorial/sgae/register")
@admin_required
def discografica_song_sgae_register(song_id):
    if not can_edit_discografica():
        if request.is_json:
            return jsonify({"ok": False, "message": "No tienes permisos para actualizar SGAE."}), 403
        return forbid("No tienes permisos para actualizar SGAE.")

    payload = request.get_json(silent=True) if request.is_json else {}
    payload = payload or {}
    nxt = safe_next_or(
        (payload.get("next") if isinstance(payload, dict) else None)
        or request.form.get("next")
        or url_for("discografica_song_detail", song_id=song_id, tab="editorial")
    )

    session_db = db()
    try:
        sid = to_uuid(song_id)
        s = session_db.get(Song, sid)
        if not s:
            if request.is_json:
                return jsonify({"ok": False, "message": "Canción no encontrada."}), 404
            flash("Canción no encontrada.", "warning")
            return redirect(url_for("discografica_view", section="canciones"))

        st = _ensure_song_status_row(session_db, sid)
        already_done = bool(getattr(st, "sgae_done", False))
        _mark_song_sgae_registered(session_db, sid)
        session_db.commit()

        s = session_db.get(Song, sid)
        st = session_db.get(SongStatus, sid)
        email_payload = _build_song_sgae_notification_email(
            session_db,
            s,
            registration_dt=getattr(st, "sgae_updated_at", None) or datetime.now(TZ_MADRID),
        )

        message = "La canción ya se ha marcado como registrada en SGAE."
        if already_done:
            message = "La canción ya estaba marcada como registrada en SGAE."

        if request.is_json:
            return jsonify(
                {
                    "ok": True,
                    "message": message,
                    "song": {
                        "id": str(getattr(s, "id", "") or ""),
                        "title": getattr(s, "title", None) or "",
                        "cover_url": (getattr(s, "cover_url", None) or "").strip(),
                        "interpreters_label": email_payload.get("interpreters_label") or "—",
                        "registration_label": email_payload.get("registration_label") or "",
                        "publication_label": email_payload.get("publication_label") or "",
                    },
                    "delivery": {
                        "authors": email_payload.get("delivery", {}).get("authors") or [],
                        "default_recipients": email_payload.get("delivery", {}).get("default_recipients") or [],
                        "suggested_recipients": email_payload.get("delivery", {}).get("suggested_recipients") or [],
                        "smtp_enabled": _smtp_enabled(),
                    },
                    "editorial_rows": email_payload.get("editorial_rows") or [],
                    "total_pct": email_payload.get("total_pct") or 0,
                }
            )

        flash("Marcado como registrado en SGAE.", "success")
    except Exception as e:
        session_db.rollback()
        if request.is_json:
            return jsonify({"ok": False, "message": f"Error marcando SGAE: {e}"}), 400
        flash(f"Error marcando SGAE: {e}", "danger")
    finally:
        session_db.close()

    return redirect(nxt)


@app.post("/discografica/canciones/<song_id>/editorial/sgae/notify")
@admin_required
def discografica_song_sgae_notify(song_id):
    if not can_edit_discografica():
        if request.is_json:
            return jsonify({"ok": False, "message": "No tienes permisos para enviar avisos de SGAE."}), 403
        return forbid("No tienes permisos para enviar avisos de SGAE.")

    payload = request.get_json(silent=True) if request.is_json else {}
    payload = payload or {}
    nxt = safe_next_or(
        (payload.get("next") if isinstance(payload, dict) else None)
        or request.form.get("next")
        or url_for("discografica_view", section="registros", registros_tab="sgae")
    )

    recipient_values: list[str] = []
    if isinstance(payload, dict):
        raw = payload.get("recipients")
        if isinstance(raw, (list, tuple, set)):
            recipient_values.extend([str(v or "") for v in raw])
        elif isinstance(raw, str):
            recipient_values.append(raw)
        custom = payload.get("custom_recipients")
        if isinstance(custom, (list, tuple, set)):
            recipient_values.extend([str(v or "") for v in custom])
        elif isinstance(custom, str):
            recipient_values.append(custom)
    recipient_values.extend(request.form.getlist("recipients"))
    recipient_values.extend(request.form.getlist("custom_recipients"))

    expanded_values: list[str] = []
    for value in recipient_values:
        expanded_values.extend(re.split(r"[;,\n]+", str(value or "")))
    recipients = _dedupe_valid_email_addresses(expanded_values)
    if not recipients:
        message = "Selecciona al menos un correo válido para enviar la comunicación."
        if request.is_json:
            return jsonify({"ok": False, "message": message}), 400
        flash(message, "warning")
        return redirect(nxt)

    session_db = db()
    try:
        sid = to_uuid(song_id)
        s = session_db.get(Song, sid)
        if not s:
            if request.is_json:
                return jsonify({"ok": False, "message": "Canción no encontrada."}), 404
            flash("Canción no encontrada.", "warning")
            return redirect(url_for("discografica_view", section="canciones"))

        st = _ensure_song_status_row(session_db, sid)
        if not bool(getattr(st, "sgae_done", False)):
            _mark_song_sgae_registered(session_db, sid)
            session_db.commit()
            st = session_db.get(SongStatus, sid)

        email_payload = _build_song_sgae_notification_email(
            session_db,
            s,
            registration_dt=getattr(st, "sgae_updated_at", None) or datetime.now(TZ_MADRID),
        )
        ok, error = _send_optional_email(
            recipients,
            email_payload.get("subject") or f"Su obra {getattr(s, 'title', '')} ya se ha registrado en SGAE.",
            email_payload.get("html_body") or "",
            text_body=email_payload.get("text_body") or None,
        )
        if not ok:
            message = f"No se pudo enviar el correo: {error}"
            if request.is_json:
                return jsonify({"ok": False, "message": message}), 400
            flash(message, "danger")
            return redirect(nxt)

        message = f"Correo enviado a {', '.join(recipients)}."
        if request.is_json:
            return jsonify({"ok": True, "message": message, "sent_to": recipients})
        flash(message, "success")
    except Exception as e:
        session_db.rollback()
        if request.is_json:
            return jsonify({"ok": False, "message": f"Error enviando el correo: {e}"}), 400
        flash(f"Error enviando el correo: {e}", "danger")
    finally:
        session_db.close()

    return redirect(nxt)


@app.post("/discografica/canciones/<song_id>/status/toggle")
@admin_required
def discografica_song_status_toggle(song_id):
    """Toggle de iconos de estado (excepto portada, que es automática)."""

    if not can_edit_discografica():
        return forbid("No tienes permisos para actualizar estados.")

    key = (request.form.get("key") or "").strip().lower()
    allowed = {
        "materials": ("materials_done", "materials_updated_at"),
        "production_contract": ("production_contract_done", "production_contract_updated_at"),
        "collaboration_contract": ("collaboration_contract_done", "collaboration_contract_updated_at"),
        "agedi": ("agedi_done", "agedi_updated_at"),
        "sgae": ("sgae_done", "sgae_updated_at"),
        "ritmonet": ("ritmonet_done", "ritmonet_updated_at"),
        "distributed": ("distributed_done", "distributed_updated_at"),
    }

    nxt = safe_next_or(request.form.get("next") or url_for("discografica_song_detail", song_id=song_id, tab="informacion"))
    if key not in allowed:
        flash("Estado no válido.", "warning")
        return redirect(nxt)

    session_db = db()
    try:
        sid = to_uuid(song_id)
        s = session_db.get(Song, sid)
        if not s:
            flash("Canción no encontrada.", "warning")
            return redirect(url_for("discografica_view", section="canciones"))

        st = session_db.get(SongStatus, sid)
        if not st:
            st = SongStatus(song_id=sid)
            st.cover_done = bool(getattr(s, "cover_url", None))
            if st.cover_done:
                st.cover_updated_at = datetime.now(TZ_MADRID)
            session_db.add(st)

        done_attr, ts_attr = allowed[key]
        current = bool(getattr(st, done_attr) or False)
        now_dt = datetime.now(TZ_MADRID)

        if key == "agedi":
            if current:
                st.agedi_done = False
                st.agedi_updated_at = now_dt
                st.updated_at = now_dt
            else:
                _mark_song_agedi_registered(session_db, sid)
        elif key == "sgae":
            if current:
                st.sgae_done = False
                st.sgae_modification_pending = False
                st.sgae_updated_at = now_dt
                st.updated_at = now_dt
            else:
                _mark_song_sgae_registered(session_db, sid)
        else:
            setattr(st, done_attr, not current)
            setattr(st, ts_attr, now_dt)
            st.updated_at = now_dt
        session_db.add(st)
        session_db.commit()
    except Exception as e:
        session_db.rollback()
        flash(f"Error actualizando estado: {e}", "danger")
    finally:
        session_db.close()

    return redirect(nxt)


@app.post("/discografica/canciones/<song_id>/info/update")
@admin_required
def discografica_song_info_update(song_id):
    """Actualiza la pestaña Información de la ficha de canción."""

    if not can_edit_discografica():
        return forbid("No tienes permisos para editar la ficha de la canción.")

    session_db = db()
    try:
        sid = to_uuid(song_id)
        s = session_db.get(Song, sid)
        if not s:
            flash("Canción no encontrada.", "warning")
            return redirect(url_for("discografica_view", section="canciones"))

        # Base
        s.title = (request.form.get("title") or s.title or "").strip() or s.title
        s.version = (request.form.get("version") or "").strip() or None

        rd = (request.form.get("release_date") or "").strip()
        if rd:
            s.release_date = parse_date(rd)

        s.is_catalog = bool(request.form.get("is_catalog"))

        # Propiedad / distribución
        ownership_type = (request.form.get("ownership_type") or "own").strip().lower()
        s.is_distribution = ownership_type == "distribution"

        master_pct_raw = (request.form.get("master_ownership_pct") or "").strip()
        if s.is_distribution:
            s.master_ownership_pct = Decimal("0")
        else:
            try:
                mp = Decimal(master_pct_raw) if master_pct_raw else Decimal("100")
            except (InvalidOperation, ValueError):
                mp = Decimal("100")
            if mp < 0:
                mp = Decimal("0")
            if mp > 100:
                mp = Decimal("100")
            s.master_ownership_pct = mp

        # Distribuidora (solo canciones que no son colaboración externa; el select solo se
        # muestra en esas, pero se re-valida aquí).
        if not s.is_external_collab:
            s.distributor_id = to_uuid((request.form.get("distributor_id") or "").strip())

        # Portada
        cover = request.files.get("cover")
        cover_uploaded = False
        if cover and getattr(cover, "filename", ""):
            s.cover_url = upload_image(cover, "songs")
            cover_uploaded = True

        # Portada (estado automático)
        st = session_db.get(SongStatus, s.id)
        if not st:
            st = SongStatus(song_id=s.id)
        st.cover_done = bool(s.cover_url)
        if cover_uploaded:
            st.cover_updated_at = datetime.now(TZ_MADRID)
        st.updated_at = datetime.now(TZ_MADRID)
        session_db.add(st)

        # Timing / TikTok start
        s.duration_seconds = parse_timecode_to_seconds(request.form.get("duration") or request.form.get("duration_seconds"))
        s.tiktok_start_seconds = parse_timecode_to_seconds(request.form.get("tiktok_start") or request.form.get("tiktok_start_seconds"))

        # Fecha grabación
        rec_date = (request.form.get("recording_date") or "").strip()
        s.recording_date = parse_date(rec_date) if rec_date else None

        # BPM
        bpm_raw = (request.form.get("bpm") or "").strip()
        if bpm_raw:
            try:
                s.bpm = int(bpm_raw)
            except Exception:
                s.bpm = None
        else:
            s.bpm = None

        s.genre = (request.form.get("genre") or "").strip() or None
        s.copyright_text = (request.form.get("copyright_text") or "").strip() or None

        s.recording_engineer = (request.form.get("recording_engineer") or "").strip() or None
        s.mixing_engineer = (request.form.get("mixing_engineer") or "").strip() or None
        s.mastering_engineer = (request.form.get("mastering_engineer") or "").strip() or None
        s.studio = (request.form.get("studio") or "").strip() or None

        # Listas en JSON
        def to_lines_json(v: str | None):
            raw = (v or "").replace("\r", "")
            items = [x.strip() for x in raw.split("\n") if x.strip()]
            return items or None

        s.producers = to_lines_json(request.form.get("producers"))
        s.arrangers = to_lines_json(request.form.get("arrangers"))

        # Músicos/participantes
        insts = request.form.getlist("musician_instrument[]")
        names = request.form.getlist("musician_name[]")
        mus = []
        for inst, name in zip(insts, names):
            inst = (inst or "").strip()
            name = (name or "").strip()
            if not inst and not name:
                continue
            mus.append({"instrument": inst, "name": name})
        s.musicians = mus or None

        # Intérpretes
        names_i = request.form.getlist("interpreter_name[]")
        mains_i = request.form.getlist("interpreter_is_main[]")

        session_db.query(SongInterpreter).filter(SongInterpreter.song_id == sid).delete(synchronize_session=False)
        clean_interpreters: list[str] = []
        seen_interpreters: set[str] = set()
        for idx, nm in enumerate(names_i):
            nm = re.sub(r"\s+", " ", (nm or "").strip())
            if not nm:
                continue
            key = _norm_person_name_key(nm)
            if key in seen_interpreters:
                continue
            seen_interpreters.add(key)
            clean_interpreters.append(nm)
            main_val = "0"
            if idx < len(mains_i):
                main_val = (mains_i[idx] or "0").strip()
            is_main = main_val in ("1", "true", "True", "MAIN")
            session_db.add(SongInterpreter(song_id=sid, name=nm, is_main=is_main))

        artist_names = _song_artist_name_list(song=s)
        s.collaborator = _song_collaborator_from_names(artist_names, clean_interpreters or artist_names)

        # Asegurar estado / portada auto
        st = session_db.get(SongStatus, sid)
        if not st:
            st = SongStatus(song_id=sid)
        st.cover_done = bool(s.cover_url)
        if cover and getattr(cover, "filename", ""):
            st.cover_updated_at = datetime.now(TZ_MADRID)
        st.updated_at = datetime.now(TZ_MADRID)
        session_db.add(st)

        session_db.commit()
        flash("Ficha actualizada.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error actualizando ficha: {e}", "danger")
    finally:
        session_db.close()

    return redirect(url_for("discografica_song_detail", song_id=song_id, tab="informacion"))


def _isrc_sequence_from_code(code: str | None) -> int | None:
    code = _norm_isrc(code)
    if not code:
        return None
    digits = ''.join(ch for ch in code.split('-')[-1] if ch.isdigit())
    if len(digits) < 3:
        return None
    try:
        seq = int(digits[-3:])
    except Exception:
        return None
    return seq if 1 <= seq <= 999 else None


def _song_primary_audio_isrc_sequence(session_db, song_id) -> int | None:
    if not song_id:
        return None
    row = (
        session_db.query(SongISRCCode)
        .filter(SongISRCCode.song_id == song_id)
        .filter(func.upper(SongISRCCode.kind) == 'AUDIO')
        .filter(SongISRCCode.is_primary == True)  # noqa: E712
        .order_by(SongISRCCode.created_at.asc())
        .first()
    )
    if row:
        seq = int(getattr(row, 'sequence_num', 0) or 0)
        if 1 <= seq <= 999:
            return seq
        seq = _isrc_sequence_from_code(getattr(row, 'code', None))
        if seq:
            return seq
    song = session_db.get(Song, song_id)
    return _isrc_sequence_from_code(getattr(song, 'isrc', None) if song else None)


def _generate_isrc(session_db, *, kind: str, artist_id, country: str, matrix: str, song_id=None) -> tuple[str, int, int]:
    """Genera el primer ISRC libre por artista/año/tipo.

    Para VIDEO intenta reutilizar primero la misma terminación del ISRC principal de AUDIO
    de la canción y, si está ocupada, avanza hasta la siguiente terminación disponible.
    """
    cfg_year = today_local().year
    yy = str(cfg_year % 100).zfill(2)

    aset = session_db.get(ArtistISRCSetting, artist_id)
    if not aset or not (aset.artist_matrix or "").strip():
        raise ValueError("Falta el número matriz ISRC del artista (configurador).")
    artist_matrix = "".join([c for c in (aset.artist_matrix or "") if c.isdigit()]).zfill(2)[-2:]

    country = (country or "ES").strip().upper()[:2] or "ES"
    matrix = "".join([c for c in (matrix or "") if c.isdigit()]).zfill(3)[-3:]
    kind = (kind or 'AUDIO').strip().upper()

    existing_rows = (
        session_db.query(SongISRCCode.code, SongISRCCode.sequence_num)
        .filter(SongISRCCode.artist_id == artist_id)
        .filter(SongISRCCode.year == cfg_year)
        .filter(func.upper(SongISRCCode.kind) == kind)
        .all()
    )
    used_sequences = set()
    used_codes = set()
    for code_value, sequence_value in existing_rows:
        norm_code = _norm_isrc(code_value)
        if norm_code:
            used_codes.add(norm_code)
        try:
            seq = int(sequence_value or 0)
        except Exception:
            seq = 0
        if not (1 <= seq <= 999):
            seq = _isrc_sequence_from_code(norm_code)
        if seq:
            used_sequences.add(seq)

    preferred_seq = _song_primary_audio_isrc_sequence(session_db, song_id) if kind == 'VIDEO' else None
    candidates = []
    if preferred_seq and 1 <= preferred_seq <= 999:
        candidates.extend(range(preferred_seq, 1000))
        candidates.extend(range(1, preferred_seq))
    else:
        candidates.extend(range(1, 1000))

    for seq in candidates:
        code = f"{country}-{matrix}-{yy}-{artist_matrix}{str(seq).zfill(3)}"
        norm_code = _norm_isrc(code)
        if seq in used_sequences or norm_code in used_codes:
            continue
        if session_db.query(SongISRCCode.id).filter(SongISRCCode.code == norm_code).first():
            continue
        return norm_code, cfg_year, seq

    raise ValueError("No quedan secuencias ISRC disponibles para este artista, año y tipo.")


@app.post("/discografica/canciones/<song_id>/isrc/add")
@admin_required
def discografica_song_isrc_add(song_id):
    if not can_edit_discografica():
        return forbid("No tienes permisos para añadir ISRC.")

    kind = (request.form.get("kind") or "AUDIO").strip().upper()
    if kind not in ("AUDIO", "VIDEO"):
        kind = "AUDIO"

    is_primary = (request.form.get("is_primary") or "primary").strip().lower() == "primary"
    subproduct_name = (request.form.get("subproduct_name") or "").strip() or None

    mode = (request.form.get("mode") or "generate").strip().lower()
    manual_code = (request.form.get("code") or "").strip() or None

    session_db = db()
    try:
        sid = to_uuid(song_id)
        s = session_db.get(Song, sid)
        if not s:
            flash("Canción no encontrada.", "warning")
            return redirect(url_for("discografica_view", section="canciones"))

        _ = s.artists
        primary_artist = s.artists[0] if s.artists else None
        if not primary_artist:
            flash("La canción no tiene artista asociado.", "warning")
            return redirect(url_for("discografica_song_detail", song_id=song_id, tab="informacion"))

        year_full = None
        seq = None

        if mode == "manual":
            if not manual_code:
                flash("Debes indicar un código ISRC.", "warning")
                return redirect(url_for("discografica_song_detail", song_id=song_id, tab="informacion"))
            code = _norm_isrc(manual_code)

            # Intento de parseo (opcional)
            try:
                # ES-270-26-01001
                parts = code.split("-")
                if len(parts) == 4 and len(parts[2]) == 2:
                    yy = int(parts[2])
                    year_full = 2000 + yy
                    tail = parts[3]
                    if len(tail) >= 5:
                        seq = int(tail[-3:])
            except Exception:
                year_full = None
                seq = None
        else:
            cfg = session_db.get(ISRCConfig, 1)
            if not cfg:
                cfg = ISRCConfig(id=1)
                session_db.add(cfg)
                session_db.flush()

            matrix = cfg.audio_matrix if kind == "AUDIO" else cfg.video_matrix
            code, year_full, seq = _generate_isrc(
                session_db,
                kind=kind,
                artist_id=primary_artist.id,
                country=cfg.country_code,
                matrix=matrix,
                song_id=sid,
            )

        rec = SongISRCCode(
            song_id=sid,
            artist_id=primary_artist.id,
            kind=kind,
            code=_norm_isrc(code),
            is_primary=is_primary,
            subproduct_name=subproduct_name,
            year=year_full,
            sequence_num=seq,
        )
        session_db.add(rec)

        # Mantener compatibilidad: guardar el ISRC principal de AUDIO en songs.isrc
        if kind == "AUDIO" and is_primary:
            s.isrc = _norm_isrc(code)

        _sync_song_agedi_state(session_db, sid)
        session_db.commit()
        flash("ISRC añadido.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error añadiendo ISRC: {e}", "danger")
    finally:
        session_db.close()

    return redirect(url_for("discografica_song_detail", song_id=song_id, tab="informacion"))


@app.post("/discografica/canciones/<song_id>/isrc/delete/<code_id>")
@admin_required
def discografica_song_isrc_delete(song_id, code_id):
    if not can_edit_discografica():
        return forbid("No tienes permisos para eliminar ISRC.")

    session_db = db()
    try:
        rec = session_db.get(SongISRCCode, to_uuid(code_id))
        if rec:
            was_primary_audio = (rec.kind or "").upper() == "AUDIO" and bool(rec.is_primary)
            sid = rec.song_id

            session_db.delete(rec)
            session_db.flush()

            # Mantener compatibilidad: actualizar songs.isrc si borramos el principal de AUDIO
            if was_primary_audio and sid:
                s = session_db.get(Song, sid)
                if s:
                    other = (
                        session_db.query(SongISRCCode)
                        .filter(SongISRCCode.song_id == sid)
                        .filter(func.upper(SongISRCCode.kind) == "AUDIO")
                        .filter(SongISRCCode.is_primary == True)  # noqa: E712
                        .first()
                    )
                    s.isrc = _norm_isrc(other.code) if other else None

            _sync_song_agedi_state(session_db, sid)
            session_db.commit()
            flash("ISRC eliminado.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error eliminando ISRC: {e}", "danger")
    finally:
        session_db.close()

    return redirect(url_for("discografica_song_detail", song_id=song_id, tab="informacion"))


@app.post("/discografica/canciones/<song_id>/update")
@admin_required
def discografica_song_update(song_id):
    if not can_edit_discografica():
        return forbid("No tienes permisos para editar canciones.")

    session_db = db()
    s = session_db.get(Song, to_uuid(song_id))
    if not s:
        session_db.close()
        flash("Canción no encontrada.", "warning")
        return redirect(url_for("discografica_view", section="canciones"))

    try:
        s.title = (request.form.get("title") or s.title or "").strip() or s.title

        rd = (request.form.get("release_date") or "").strip()
        if rd:
            s.release_date = parse_date(rd)

        s.is_catalog = bool(request.form.get("is_catalog"))
        s.isrc = _norm_isrc((request.form.get("isrc") or "").strip() or None)

        cover = request.files.get("cover")
        if cover and getattr(cover, "filename", ""):
            s.cover_url = upload_image(cover, "songs")

        artist_names = [a.name for a in (getattr(s, 'artists', None) or []) if getattr(a, 'name', None)]
        interpreter_rows = (
            session_db.query(SongInterpreter)
            .filter(SongInterpreter.song_id == s.id)
            .order_by(SongInterpreter.is_main.desc(), SongInterpreter.created_at.asc())
            .all()
        )
        interpreter_names = [re.sub(r"\s+", " ", (getattr(row, 'name', '') or '').strip()) for row in interpreter_rows if re.sub(r"\s+", " ", (getattr(row, 'name', '') or '').strip())]
        if artist_names or interpreter_names:
            s.collaborator = _song_collaborator_from_names(artist_names, interpreter_names or artist_names)

        _sync_song_agedi_state(session_db, s.id)
        session_db.commit()
        flash("Canción actualizada.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error actualizando canción: {e}", "danger")
    finally:
        session_db.close()

    return redirect(url_for("discografica_song_detail", song_id=song_id))


@app.post("/discografica/canciones/<song_id>/set_link")
@admin_required
def discografica_song_set_link(song_id):
    if not can_edit_discografica():
        return forbid("No tienes permisos para editar enlaces.")

    platform = (request.form.get("platform") or "").strip().lower()
    url = (request.form.get("url") or "").strip()
    if not platform:
        flash("Falta la plataforma.", "warning")
        return redirect(url_for("discografica_song_detail", song_id=song_id))
    if not url:
        flash("Debes indicar un enlace.", "warning")
        return redirect(url_for("discografica_song_detail", song_id=song_id))
    if not (url.startswith("http://") or url.startswith("https://")):
        url = "https://" + url

    field_map = {
        "spotify": "spotify_url",
        "apple_music": "apple_music_url",
        "amazon_music": "amazon_music_url",
        "tiktok": "tiktok_url",
        "youtube": "youtube_url",
    }
    field = field_map.get(platform)
    if not field:
        flash("Plataforma no soportada.", "warning")
        return redirect(url_for("discografica_song_detail", song_id=song_id))

    session_db = db()
    s = session_db.get(Song, to_uuid(song_id))
    if not s:
        session_db.close()
        flash("Canción no encontrada.", "warning")
        return redirect(url_for("discografica_view", section="canciones"))

    try:
        setattr(s, field, url)
        # Enlace metido a mano → se fija: Chartmetric no lo volverá a tocar/buscar.
        try:
            locked = set(_json_list(getattr(s, "cm_links_locked", None)))
            locked.add(platform)
            s.cm_links_locked = sorted(locked)
        except Exception:
            pass
        session_db.commit()
        flash("Enlace guardado.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error guardando enlace: {e}", "danger")
    finally:
        session_db.close()

    return redirect(request.form.get("next") or url_for("discografica_song_detail", song_id=song_id))


@app.post("/discografica/canciones/<song_id>/materials/upload")
@admin_required
def discografica_song_material_upload(song_id):
    if not can_edit_discografica():
        return forbid("No tienes permisos para subir materiales.")

    category = (request.form.get("category") or "").strip().upper()
    slot_key = (request.form.get("slot_key") or "DEFAULT").strip().upper()
    display_name = (request.form.get("display_name") or "").strip() or None
    replace_material_id = (request.form.get("material_id") or "").strip() or None
    replace_bundle_key = (request.form.get("bundle_key") or "").strip() or None
    files = []
    for field_name in ("files", "folder_files", "file", "audio_file", "songMaterialFiles", "songMaterialFolderFiles"):
        for storage in request.files.getlist(field_name):
            if storage and getattr(storage, "filename", ""):
                files.append(storage)
    # Evita duplicados si el navegador envía el mismo FileStorage bajo dos nombres.
    deduped_files = []
    seen_file_keys = set()
    for storage in files:
        key = (id(storage), getattr(storage, "filename", ""))
        if key in seen_file_keys:
            continue
        seen_file_keys.add(key)
        deduped_files.append(storage)
    files = deduped_files

    if category not in {"COVER", "MASTER", "INSTRUMENTAL", "TV_TRACK", "STEMS"}:
        flash("Tipo de material no válido.", "warning")
        return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))

    if category == "COVER":
        if slot_key != "COVER_PROVISIONAL":
            slot_key = "COVER"
    elif category == "MASTER" and slot_key not in {"MASTER_48", "MASTER_24", "MASTER_16", "SUBPRODUCT"}:
        slot_key = "MASTER_48"
    elif category in {"INSTRUMENTAL", "TV_TRACK"} and slot_key not in {"DEFAULT", "SUBPRODUCT"}:
        slot_key = "DEFAULT"
    elif category == "STEMS":
        slot_key = "BUNDLE"

    if category in {"MASTER", "INSTRUMENTAL", "TV_TRACK"} and slot_key == "SUBPRODUCT" and not display_name:
        flash("Debes indicar un nombre para el subproducto.", "warning")
        return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))

    if not files:
        flash("Selecciona al menos un archivo.", "warning")
        return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))

    if category in {"MASTER", "INSTRUMENTAL", "TV_TRACK"}:
        non_wav = [f for f in files if Path((f.filename or "").replace("\\", "/")).suffix.lower() not in {".wav", ".wave"}]
        if non_wav:
            flash("Los masters, la instrumental y el TV track deben subirse en formato .wav.", "warning")
            return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))

    session_db = db()
    try:
        song = session_db.get(Song, to_uuid(song_id))
        if not song:
            flash("Canción no encontrada.", "warning")
            return redirect(url_for("discografica_view", section="canciones"))

        if replace_material_id:
            old_row = session_db.get(SongMaterial, to_uuid(replace_material_id))
            if not old_row or old_row.song_id != song.id:
                flash("Material no encontrado.", "warning")
                return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))
            if not display_name and (getattr(old_row, "display_name", None) or "").strip():
                display_name = (old_row.display_name or "").strip()
            if old_row.category == "COVER":
                song.cover_url = None
            session_db.delete(old_row)
            session_db.flush()

        if replace_bundle_key:
            old_rows = (
                session_db.query(SongMaterial)
                .filter(SongMaterial.song_id == song.id)
                .filter(SongMaterial.bundle_key == replace_bundle_key)
                .all()
            )
            if old_rows and not display_name:
                display_name = (getattr(old_rows[0], "display_name", None) or "").strip() or None
            for row in old_rows:
                session_db.delete(row)
            session_db.flush()

        if category == "COVER":
            cover_slot = "COVER_PROVISIONAL" if slot_key == "COVER_PROVISIONAL" else "COVER"
            # Reemplaza solo la portada del MISMO rol (principal o provisional).
            for row in (
                session_db.query(SongMaterial)
                .filter(SongMaterial.song_id == song.id)
                .filter(func.upper(SongMaterial.category) == "COVER")
                .filter(func.upper(SongMaterial.slot_key) == cover_slot)
                .all()
            ):
                session_db.delete(row)
            file_url = upload_image(files[0], "song_materials")
            session_db.add(
                SongMaterial(
                    song_id=song.id,
                    category="COVER",
                    slot_key=cover_slot,
                    display_name="Portada provisional" if cover_slot == "COVER_PROVISIONAL" else "Portada",
                    file_name=Path(files[0].filename or "portada").name,
                    file_url=file_url,
                    mime_type=(getattr(files[0], "mimetype", "") or "").strip() or None,
                )
            )
            session_db.flush()
            _resolve_song_cover_url(session_db, song)

        elif category in {"MASTER", "INSTRUMENTAL", "TV_TRACK"}:
            if slot_key != "SUBPRODUCT":
                for row in (
                    session_db.query(SongMaterial)
                    .filter(SongMaterial.song_id == song.id)
                    .filter(func.upper(SongMaterial.category) == category)
                    .filter(func.upper(SongMaterial.slot_key) == slot_key)
                    .all()
                ):
                    session_db.delete(row)
            file_storage = files[0]
            file_url = upload_file(file_storage, "song_materials", allowed_extensions={".wav", ".wave"})
            session_db.add(
                SongMaterial(
                    song_id=song.id,
                    category=category,
                    slot_key=slot_key,
                    display_name=display_name,
                    file_name=(file_storage.filename or "audio.wav").replace("\\", "/"),
                    file_url=file_url,
                    mime_type=(getattr(file_storage, "mimetype", "") or "").strip() or None,
                )
            )

        else:  # STEMS
            bundle_key = uuid.uuid4().hex
            bundle_label = display_name or "Stems"
            added_any = False
            for file_storage in files:
                fname = (file_storage.filename or "archivo").replace("\\", "/")
                if Path(fname).suffix.lower() == ".zip":
                    # Carpeta comprimida: se descomprime y cada archivo interno entra como un stem del bundle.
                    try:
                        _zf = zipfile.ZipFile(BytesIO(file_storage.read()))
                    except Exception:
                        flash("No se pudo leer el ZIP de stems «%s»." % Path(fname).name, "warning")
                        continue
                    for info in _zf.infolist():
                        if info.is_dir():
                            continue
                        inner_name = Path(info.filename.replace("\\", "/")).name
                        if not inner_name or inner_name.startswith(".") or "__MACOSX/" in info.filename:
                            continue
                        data = _zf.read(info)
                        if not data:
                            continue
                        inner_suffix = Path(inner_name).suffix.lower()
                        key = f"song_materials/{uuid.uuid4().hex}{inner_suffix}"
                        content_type = mimetypes.guess_type(inner_name)[0] or "application/octet-stream"
                        file_url = _upload_bytes(data, key, content_type)
                        session_db.add(
                            SongMaterial(
                                song_id=song.id,
                                category="STEMS",
                                slot_key="BUNDLE",
                                bundle_key=bundle_key,
                                display_name=bundle_label,
                                file_name=inner_name,
                                file_url=file_url,
                                mime_type=content_type,
                            )
                        )
                        added_any = True
                else:
                    file_url = upload_file(file_storage, "song_materials")
                    session_db.add(
                        SongMaterial(
                            song_id=song.id,
                            category="STEMS",
                            slot_key="BUNDLE",
                            bundle_key=bundle_key,
                            display_name=bundle_label,
                            file_name=fname,
                            file_url=file_url,
                            mime_type=(getattr(file_storage, "mimetype", "") or "").strip() or None,
                        )
                    )
                    added_any = True
            if not added_any:
                flash("El ZIP o la carpeta de stems no contenía archivos válidos.", "warning")
                return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))

        song.updated_at = datetime.now(TZ_MADRID)
        session_db.add(song)
        material_rows = (
            session_db.query(SongMaterial)
            .filter(SongMaterial.song_id == song.id)
            .order_by(SongMaterial.created_at.asc())
            .all()
        )
        _refresh_song_material_status(session_db, song, material_rows=material_rows)
        session_db.commit()
        flash("Material guardado.", "success")
    except StorageObjectTooLargeError as e:
        session_db.rollback()
        flash(str(e), "warning")
    except Exception as e:
        session_db.rollback()
        flash(f"Error guardando el material: {e}", "danger")
    finally:
        session_db.close()

    return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))


@app.post("/discografica/canciones/<song_id>/materials/<material_id>/delete")
@admin_required
def discografica_song_material_delete(song_id, material_id):
    if not can_edit_discografica():
        return forbid("No tienes permisos para eliminar materiales.")

    session_db = db()
    try:
        song = session_db.get(Song, to_uuid(song_id))
        row = session_db.get(SongMaterial, to_uuid(material_id))
        if not song or not row or row.song_id != song.id:
            flash("Material no encontrado.", "warning")
            return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))
        was_cover = (row.category or "").upper() == "COVER"
        session_db.delete(row)
        session_db.flush()
        if was_cover:
            _resolve_song_cover_url(session_db, song)
        material_rows = (
            session_db.query(SongMaterial)
            .filter(SongMaterial.song_id == song.id)
            .order_by(SongMaterial.created_at.asc())
            .all()
        )
        _refresh_song_material_status(session_db, song, material_rows=material_rows)
        session_db.commit()
        flash("Material eliminado.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error eliminando el material: {e}", "danger")
    finally:
        session_db.close()

    return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))


@app.post("/discografica/canciones/<song_id>/materials/<material_id>/cover-role")
@admin_required
def discografica_song_cover_role(song_id, material_id):
    if not can_edit_discografica():
        return forbid("No tienes permisos para editar materiales.")
    session_db = db()
    try:
        song = session_db.get(Song, to_uuid(song_id))
        row = session_db.get(SongMaterial, to_uuid(material_id))
        if not song or not row or row.song_id != song.id or (row.category or "").upper() != "COVER":
            flash("Portada no encontrada.", "warning")
            return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))
        current = (row.slot_key or "COVER").strip().upper()
        target = "COVER" if current == "COVER_PROVISIONAL" else "COVER_PROVISIONAL"
        # Solo una principal y una provisional: si ya hay otra en el rol destino, se intercambian.
        other = (
            session_db.query(SongMaterial)
            .filter(SongMaterial.song_id == song.id)
            .filter(func.upper(SongMaterial.category) == "COVER")
            .filter(func.upper(SongMaterial.slot_key) == target)
            .filter(SongMaterial.id != row.id)
            .first()
        )
        if other is not None:
            other.slot_key = current
            other.display_name = "Portada provisional" if current == "COVER_PROVISIONAL" else "Portada"
            session_db.add(other)
        row.slot_key = target
        row.display_name = "Portada provisional" if target == "COVER_PROVISIONAL" else "Portada"
        session_db.add(row)
        session_db.flush()
        _resolve_song_cover_url(session_db, song)
        _refresh_song_material_status(session_db, song)
        session_db.commit()
        flash("Portada actualizada.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error actualizando la portada: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))


