@app.post("/api/contactos/crear", endpoint="api_promoter_contact_create")
@admin_required
def api_promoter_contact_create():
    """Crea una persona de contacto vinculada al tercero.

    Antes de crearla avisa de las que se le parecen (mismo correo, mismo teléfono o nombre
    parecido) para poder VINCULAR la que ya existe en vez de duplicarla. Con `force=1` se crea
    igualmente (el usuario ha dicho que no es la misma persona)."""
    data = request.get_json(silent=True) or request.form
    name = (data.get("name") or "").strip()
    email = (data.get("email") or "").strip()
    phone = (data.get("phone") or "").strip()
    promoter_id = to_uuid((data.get("promoter_id") or "").strip() or None)
    force = _truthy(data.get("force"))
    if not name:
        return jsonify({"ok": False, "error": "Indica al menos el nombre de la persona."}), 400
    if not promoter_id:
        return jsonify({"ok": False, "error": "Elige antes el promotor: la persona queda vinculada a él."}), 400
    session_db = db()
    try:
        promoter = session_db.get(Promoter, promoter_id)
        if not promoter:
            return jsonify({"ok": False, "error": "El promotor ya no existe."}), 404
        if not force:
            dups = _similar_promoter_contacts(session_db, name, email, phone)
            if dups:
                return jsonify({"ok": False, "duplicates": dups})
        parts = name.split()
        contact = PromoterContact(
            promoter_id=promoter.id,
            title="Contacto",
            first_name=parts[0],
            last_name=(" ".join(parts[1:]) or None),
            email=(email or None),
            phone=(phone or None),
        )
        session_db.add(contact)
        session_db.commit()
        return jsonify({"ok": True, "contact": _promoter_contact_payload(contact, promoter)})
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[contactos] no se pudo crear la persona")
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        session_db.close()


def _song_delivery_email_html(song, title_artist, url_pub, cover_url, note=None) -> str:
    logo = _external_url_for("static", filename="img/logo.png")
    cover_img = ('<img src="%s" alt="" style="width:64px;height:64px;object-fit:cover;border-radius:8px;border:1px solid #eee;margin-right:12px;">' % escape(cover_url)) if cover_url else ""
    note_html = ('<div style="border-left:3px solid #E33D48;padding:8px 12px;margin:16px 0;color:#444;white-space:pre-wrap;">%s</div>' % escape(note)) if (note or "").strip() else ""
    return (
        '<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#1e2530;">'
        '<div style="text-align:right;margin-bottom:12px;"><img src="%s" alt="PIES Records" style="height:38px;"></div>'
        '<h2 style="margin:0 0 4px;">Solicitud de entrega de masters</h2>'
        '<p style="color:#555;">Se solicita la entrega de información y materiales de la siguiente canción:</p>'
        '<div style="border:1px solid #eee;border-radius:8px;padding:12px;display:flex;align-items:center;">'
        '%s<div><div style="font-weight:600;">%s</div><div style="color:#666;font-size:14px;">%s</div></div></div>'
        '%s'
        '<div style="text-align:center;margin:24px 0;"><a href="%s" style="background:#E33D48;color:#fff;text-decoration:none;padding:12px 22px;border-radius:8px;font-weight:600;display:inline-block;">Subir masters e información</a></div>'
        '<p style="color:#888;font-size:12px;">Si el botón no funciona, copia este enlace:<br>%s</p>'
        '</div>'
    ) % (escape(logo), cover_img, escape(song.title or ""), escape(title_artist), note_html, escape(url_pub), escape(url_pub))


@app.post("/discografica/canciones/<song_id>/entrega/<link_id>/enviar-correo")
@admin_required
def discografica_song_delivery_send_email(song_id, link_id):
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    recipients = [e.strip() for e in request.form.getlist("recipients") if e.strip()]
    extra = (request.form.get("extra_email") or "").strip()
    if extra:
        recipients.append(extra)
    recipients = list(dict.fromkeys(recipients))  # dedupe conservando orden
    note = (request.form.get("note") or "").strip()
    if not recipients:
        flash("Indica al menos un destinatario.", "warning")
        return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))
    session_db = db()
    try:
        song = session_db.get(Song, to_uuid(song_id))
        link = session_db.get(SongMasterDeliveryLink, to_uuid(link_id))
        if not song or not link or link.song_id != song.id or link.status != "ACTIVE":
            flash("Enlace de entrega no válido.", "warning")
            return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))
        artist = _song_artist_names_str(song)
        collab = (getattr(song, "collaborator", None) or "").strip()
        title_artist = artist + (" (con %s)" % collab if collab else "")
        subject = "Solicitud entrega masters · %s · %s" % (title_artist, song.title or "")
        url_pub = _song_delivery_public_url(link)
        html = _song_delivery_email_html(song, title_artist, url_pub, (song.cover_url or "").strip(), note=note)
        ok, err = _send_optional_email(recipients, subject, html, text_body="Solicitud de entrega de masters. Enlace: " + url_pub, reply_to=_current_user_email())
        if ok:
            link.target_email = recipients[0]
            session_db.add(link)
            session_db.commit()
            flash("Correo de solicitud enviado a %s." % ", ".join(recipients), "success")
        else:
            flash("No se pudo enviar el correo: %s" % (err or "revisa la configuración SMTP"), "danger")
    except Exception as e:
        session_db.rollback()
        flash(f"Error enviando el correo: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))


def _song_delivery_active_link(session_db, token):
    return session_db.query(SongMasterDeliveryLink).filter(
        SongMasterDeliveryLink.token == (token or "").strip(),
        SongMasterDeliveryLink.status == "ACTIVE",
    ).first()


def _delivery_promoter_label(p):
    fn = (getattr(p, "first_name", None) or "").strip()
    ln = (getattr(p, "last_name", None) or "").strip()
    return (fn + " " + ln).strip() or (getattr(p, "nick", None) or "").strip() or "—"


@app.get("/entrega-masters/<token>/api/autores", endpoint="public_song_delivery_authors")
def public_song_delivery_authors(token):
    session_db = db()
    try:
        if not _song_delivery_active_link(session_db, token):
            return jsonify([])
        q = (request.args.get("q") or "").strip()
        if len(q) < 1:
            return jsonify([])
        rows = (
            session_db.query(Promoter)
            .options(joinedload(Promoter.publishing_company))
            .filter(or_(
                _sa_contains_text(Promoter.nick, q),
                _sa_contains_text(Promoter.first_name, q),
                _sa_contains_text(Promoter.last_name, q),
                _sa_contains_text(func.concat(Promoter.first_name, ' ', Promoter.last_name), q),
            ))
            .order_by(Promoter.nick.asc()).limit(10).all()
        )
        out = []
        for p in rows:
            pc = getattr(p, "publishing_company", None)
            out.append({
                "id": str(p.id),
                "name": _delivery_promoter_label(p),
                "logo_url": (getattr(p, "logo_url", None) or ""),
                "publishing_company_id": str(p.publishing_company_id) if getattr(p, "publishing_company_id", None) else "",
                "publishing_company_name": (pc.name if pc else ""),
            })
        return jsonify(out)
    finally:
        session_db.close()


