@app.get("/contratacion", endpoint="contracting_view")
@admin_required
def contracting_view():
    section = (request.args.get("section") or "conciertos").strip().lower()
    if section == "conciertos":
        return redirect(url_for("concerts_view", tab="vista"))
    if section == "facturacion":
        return redirect(url_for("concerts_view", tab="facturacion"))
    if section == "cuadrantes":
        return redirect(url_for("quadrantes_view"))
    valid_sections = {"peticiones", "giras-compradas", "festivales-ciclos", "eventos",
                      "otras-actividades", "simulaciones"}
    if section not in valid_sections:
        section = "giras-compradas"
    if section == "simulaciones":
        return _render_simulations_list()
    if section == "peticiones":
        return _render_booking_requests()
    if section == "giras-compradas":
        return _render_purchased_tours()
    if section == "festivales-ciclos":
        return _render_cycle_festivals()
    if section == "eventos":
        # Por defecto, las ACTIVIDADES agrupadas por evento (como la pestaña de conciertos). Con
        # `?contenedores=1`, la lista de contenedores de evento (para crearlos y ver su ficha).
        if _truthy(request.args.get("contenedores")):
            return _render_cycle_festivals(only_events=True)
        return _render_event_activities()
    session_db = db()
    try:
        query = session_db.query(Concert).options(joinedload(Concert.artist), joinedload(Concert.venue)).order_by(Concert.date.asc().nullslast(), Concert.created_at.desc())
        if section == "giras-compradas":
            query = query.filter(or_(func.upper(func.coalesce(Concert.sale_type, "")) == "GIRAS_COMPRADAS", func.upper(func.coalesce(Concert.activity_type, "")) == "GIRA"))
            title = "Giras compradas"
            subtitle = "Actividades/conciertos clasificados como gira comprada."
            empty = "No hay giras compradas registradas todavía."
        elif section == "festivales-ciclos":
            query = query.filter(or_(func.upper(func.coalesce(Concert.activity_type, "")) == "FESTIVAL", func.upper(func.coalesce(Concert.sale_type, "")) == "CADIZ", _sa_contains_text(Concert.festival_name, "festival"), _sa_contains_text(Concert.festival_name, "ciclo")))
            title = "Festivales / Ciclos"
            subtitle = "Festivales, ciclos y eventos agrupados fuera de conciertos estándar."
            empty = "No hay festivales o ciclos registrados todavía."
        elif section == "otras-actividades":
            query = query.filter(func.upper(func.coalesce(Concert.activity_type, "CONCIERTO")).in_(["EVENTO_PROMOCIONAL", "TV", "MARCA", "OTROS"]))
            title = "Otras actividades"
            subtitle = "Eventos promocionales, televisión, acciones con marca y otras actividades."
            empty = "No hay otras actividades registradas todavía."
        else:
            query = query.filter(text("1=0"))
            title = "Simulaciones"
            subtitle = "Espacio preparado para simulaciones de contratación."
            empty = "Las simulaciones se desarrollarán sobre esta sección."
        rows = query.limit(300).all()
        tour_groups = _tour_groups_from_concerts(rows) if section == "giras-compradas" else []
        artists = session_db.query(Artist).order_by(Artist.name.asc()).all()

        # «Otras actividades» funciona como Conciertos: debajo de las tareas, el filtro por ARTISTA
        # (rejilla con el nº de actividades de cada uno) y, al pinchar uno, sus actividades.
        artist_groups, drill_artist = [], None
        if section == "otras-actividades":
            _mine = _contracting_task_artist_ids()
            counts = {}
            for c in rows:
                if _mine and str(getattr(c, "artist_id", "") or "") not in _mine:
                    continue
                counts[c.artist_id] = counts.get(c.artist_id, 0) + 1
            by_id = {a.id: a for a in artists}
            artist_groups = sorted(
                ({"artist": by_id[aid], "count": n} for aid, n in counts.items() if aid in by_id),
                key=lambda x: (x["artist"].name or "").lower(),
            )
            _drill = to_uuid(request.args.get("artist") or "")
            if _drill:
                drill_artist = by_id.get(_drill)
                rows = [c for c in rows if c.artist_id == _drill]
            elif _mine:
                rows = [c for c in rows if str(getattr(c, "artist_id", "") or "") in _mine]
        promoters = session_db.query(Promoter).options(selectinload(Promoter.companies)).order_by(Promoter.nick.asc()).all()
        companies = session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
        type_choices = [(k, CONCERT_SALE_TYPE_LABELS.get(k, k)) for k in CONCERTS_SECTION_ORDER]
        all_concert_tags = _collect_all_concert_tags(session_db)
        promoters_payload = [
            {
                "id": str(p.id),
                "nick": (p.nick or "").strip(),
                "logo_url": (p.logo_url or "").strip(),
                "companies": [_serialize_promoter_company(x) for x in (p.companies or [])],
            }
            for p in promoters
        ]
        return render_template(
            "contratacion.html",
            section=section,
            title=title,
            subtitle=subtitle,
            empty_message=empty,
            rows=rows,
            tour_groups=tour_groups,
            artist_groups=artist_groups,
            drill_artist=drill_artist,
            artists=artists,
            promoters=promoters,
            promoters_payload=promoters_payload,
            companies=companies,
            type_choices=type_choices,
            all_concert_tags=all_concert_tags,
            wizard_tours=_wizard_group_options(session_db)[0],
            wizard_cycles=_wizard_group_options(session_db)[1],
            CAN_EDIT_CONCERTS=can_edit_concerts(),
        )
    finally:
        session_db.close()


# ============================ PETICIONES (buzón de contratación) ============================
# Buzón de peticiones ENTRANTES: se registra lo que llega a la oficina (artista, fecha aprox.,
# contacto, recinto/ciudad, importe orientativo) y se tramita hasta convertirse en concierto o
# descartarse. Modelo BookingRequest. Sección en Contratación (contratacion.peticiones).
BOOKING_STATUS_ORDER = ["NUEVA", "EN_TRAMITE", "CONVERTIDA", "DESCARTADA"]
BOOKING_STATUS_META = {
    "NUEVA": ("Pendiente", "text-bg-warning text-dark"),
    "EN_TRAMITE": ("Negociando", "text-bg-info text-dark"),
    "CONVERTIDA": ("Aprobada", "text-bg-success"),
    "DESCARTADA": ("Descartada", "text-bg-secondary"),
}
# Estados que siguen "abiertos" (aparecen en el módulo de pendientes); el resto van a archivadas.
BOOKING_OPEN_STATUSES = {"NUEVA", "EN_TRAMITE"}
BOOKING_SOURCE_CHOICES = [
    ("EMAIL", "Email"), ("TELEFONO", "Teléfono"), ("WEB", "Web / formulario"),
    ("PRESENCIAL", "Presencial"), ("OTRO", "Otro"),
]


def _booking_status_meta(status):
    return BOOKING_STATUS_META.get((status or "NUEVA").upper(), ("Nueva", "text-bg-danger"))


def _booking_request_row(r):
    st = (r.status or "NUEVA").upper()
    label, badge = _booking_status_meta(st)
    art = r.artist
    if r.requested_date:
        dlabel = r.requested_date.strftime("%d/%m/%Y")
    else:
        dlabel = (r.date_text or "").strip()
    return {
        "id": str(r.id),
        "subject": (r.subject or "").strip(),
        "artist_id": (str(r.artist_id) if r.artist_id else ""),
        "artist_name": (art.name if art else ""),
        "artist_photo": ((getattr(art, "photo_url", "") or "") if art else ""),
        "date_label": dlabel,
        "requested_date": (r.requested_date.isoformat() if r.requested_date else ""),
        "date_text": (r.date_text or ""),
        "contact_name": (r.contact_name or ""),
        "contact_email": (r.contact_email or ""),
        "contact_phone": (r.contact_phone or ""),
        "municipality": (r.municipality or ""),
        "province": (r.province or ""),
        "fee_text": (r.fee_text or ""),
        "source": (r.source or ""),
        "notes": (r.notes or ""),
        "status": st,
        "status_label": label,
        "status_badge": badge,
        "rejection_reason": (r.rejection_reason or ""),
        "concert_id": (str(r.concert_id) if r.concert_id else ""),
        "created_by": (r.created_by_nick or ""),
        "received_label": (r.received_at.strftime("%d/%m/%Y") if r.received_at else (r.created_at.strftime("%d/%m/%Y") if r.created_at else "")),
    }


def _booking_in_department(r, dept: str) -> bool:
    """¿Esta petición pertenece a `dept`? Se lee de payload['departments']; las
    peticiones antiguas sin departamento se consideran de Contratación."""
    pay = r.payload if isinstance(getattr(r, "payload", None), dict) else {}
    depts = pay.get("departments")
    if isinstance(depts, list) and depts:
        return dept.upper() in [str(d).strip().upper() for d in depts]
    return dept.upper() == "CONTRATACION"


def _render_booking_requests():
    s = db()
    try:
        status_filter = (request.args.get("status") or "").strip().upper()
        rows_all = (
            s.query(BookingRequest)
            .options(joinedload(BookingRequest.artist), joinedload(BookingRequest.promoter), joinedload(BookingRequest.venue))
            .order_by(BookingRequest.received_at.desc().nullslast(), BookingRequest.created_at.desc())
            .limit(500).all()
        )
        # Peticiones de Contratación (con caché o legado sin departamento).
        mine = [r for r in rows_all if _booking_in_department(r, "CONTRATACION")]
        pending = [r for r in mine if (r.status or "NUEVA").upper() in BOOKING_OPEN_STATUSES]
        archived = [r for r in mine if (r.status or "NUEVA").upper() not in BOOKING_OPEN_STATUSES]
        counts = {k: sum(1 for r in mine if (r.status or "NUEVA").upper() == k) for k in BOOKING_STATUS_ORDER}
        # Por defecto se muestran las PENDIENTES; «Archivadas» muestra aprobadas/descartadas.
        if status_filter == "ARCHIVED":
            rows = archived
        elif status_filter in BOOKING_STATUS_META:
            rows = [r for r in mine if (r.status or "NUEVA").upper() == status_filter]
        else:
            rows = pending
        payload = [_booking_request_row(r) for r in rows]
        artists = s.query(Artist).order_by(Artist.name.asc()).all()
        return render_template(
            "peticiones.html",
            section="peticiones",
            # «Pedir promoción» sale también aquí: lo puede hacer cualquiera de la empresa.
            promo_creator_datasets=_promo_creator_datasets(s),
            booking_rows=payload,
            booking_counts=counts,
            booking_total=len(mine),
            booking_pending_total=len(pending),
            booking_archived_total=len(archived),
            status_filter=status_filter,
            booking_status_order=BOOKING_STATUS_ORDER,
            booking_status_meta=BOOKING_STATUS_META,
            booking_source_choices=BOOKING_SOURCE_CHOICES,
            artists=artists,
            CAN_EDIT_CONCERTS=can_edit_concerts(),
        )
    finally:
        s.close()


def _booking_apply_form(r, form):
    r.subject = (form.get("subject") or "").strip() or None
    aid = (form.get("artist_id") or "").strip()
    r.artist_id = to_uuid(aid) if aid else None
    r.artist_ids = [aid] if aid else []
    r.requested_date = parse_optional_date(form.get("requested_date"))
    r.date_text = (form.get("date_text") or "").strip() or None
    r.contact_name = (form.get("contact_name") or "").strip() or None
    r.contact_email = (form.get("contact_email") or "").strip() or None
    r.contact_phone = (form.get("contact_phone") or "").strip() or None
    r.municipality = (form.get("municipality") or "").strip() or None
    r.province = (form.get("province") or "").strip() or None
    r.fee_text = (form.get("fee_text") or "").strip() or None
    r.source = (form.get("source") or "").strip().upper() or None
    r.notes = (form.get("notes") or "").strip() or None


@app.post("/contratacion/peticiones/crear", endpoint="booking_request_create")
@admin_required
def booking_request_create():
    s = db()
    try:
        r = BookingRequest(status="NUEVA")
        _booking_apply_form(r, request.form)
        if not (r.subject or r.artist_id or r.contact_name):
            flash("Indica al menos un artista, un contacto o un asunto para la petición.", "warning")
            return redirect(url_for("contracting_view", section="peticiones"))
        st = _current_user_state()
        r.created_by_user_id = to_uuid(st.get("user_id")) if st.get("user_id") else None
        r.created_by_nick = st.get("nick") or None
        s.add(r)
        s.commit()
        flash("Petición registrada en el buzón.", "success")
    except Exception as exc:
        s.rollback()
        flash(f"No se pudo registrar la petición: {exc}", "danger")
    finally:
        s.close()
    return redirect(url_for("contracting_view", section="peticiones"))


@app.post("/contratacion/peticiones/<rid>/editar", endpoint="booking_request_update")
@admin_required
def booking_request_update(rid):
    s = db()
