# ----------------------------- Ciclos / Festivales -----------------------------
def _cycle_concerts(s, cf_id):
    return (
        s.query(Concert).options(joinedload(Concert.artist), joinedload(Concert.venue))
        .filter(Concert.cycle_festival_id == cf_id)
        .order_by(Concert.date.asc().nullslast(), Concert.created_at.asc()).all()
    )


# Etiquetas de las categorías que agrupan fechas (contenedores de Contratación).
# Tipos de CONTENEDOR de fechas. GIRA es el contenedor propio de un EVENTO: «la ruta del Aguilar»
# es el evento (el sujeto, como si fuera un artista) y de él se organiza una GIRA con sus fechas.
# No es una «gira comprada» (esas son `PurchasedTour`, se le compran a un promotor) ni un ciclo.
# EVENTO se conserva por los contenedores ya creados; los nuevos de un evento son GIRA/CICLO/FESTIVAL.
CYCLE_FESTIVAL_KIND_LABELS = {"FESTIVAL": "Festival", "CICLO": "Ciclo", "EVENTO": "Evento", "GIRA": "Gira"}
# Contenedores que pertenecen a un EVENTO (viven en la pestaña Eventos, no en Festivales/Ciclos).
CYCLE_FESTIVAL_EVENT_KINDS = ("EVENTO", "GIRA")


def _render_event_activities():
    """Pestaña EVENTOS: como la de Conciertos, pero agrupada por EVENTO (un evento no tiene artista).
    Sus actividades salen SOLO aquí (en Conciertos se filtran). Rejilla de eventos → actividades."""
    s = db()
    try:
        hoy = today_local()
        show_past = _truthy(request.args.get("pasadas"))
        drill_id = to_uuid(request.args.get("event") or "")
        q = (s.query(Concert)
             .options(joinedload(Concert.venue), joinedload(Concert.artist))
             .filter(Concert.event_id.isnot(None)))
        if not show_past:
            q = q.filter(or_(Concert.date.is_(None), Concert.date >= hoy))
        actividades = q.order_by(Concert.date.asc().nullslast(), Concert.created_at.desc()).all()

        eventos = {str(e.id): e for e in s.query(AppEvent).all()}
        grupos = {}
        for c in actividades:
            key = str(c.event_id)
            g = grupos.setdefault(key, {"id": key, "name": "", "logo_url": "", "count": 0, "dates": []})
            g["count"] += 1
            if c.date:
                g["dates"].append(c.date)
        for key, g in grupos.items():
            ev = eventos.get(key)
            g["name"] = (getattr(ev, "name", "") or "Evento")
            g["logo_url"] = (getattr(ev, "logo_url", "") or "")
            g["date_range"] = _date_range_label(min(g["dates"]), max(g["dates"])) if g["dates"] else ""
        event_groups = sorted(grupos.values(), key=lambda g: (g["name"] or "").lower())

        rows, drill_event, drill_group_id = [], None, None
        if drill_id:
            drill_event = eventos.get(str(drill_id))
            rows = [c for c in actividades if str(c.event_id) == str(drill_id)]
            for c in rows:
                setattr(c, "sale_type_label", _sale_type_label(c.sale_type))
                setattr(c, "location_summary", _concert_location_summary(c))
                # Un evento no tiene artista: el título es el del evento (o el nombre de la fecha).
                setattr(c, "title_label", (getattr(drill_event, "name", "") or "Actividad"))
            grupo = (s.query(CycleFestival)
                     .filter(CycleFestival.event_id == drill_id)
                     .order_by(CycleFestival.created_at.desc()).first())
            drill_group_id = str(grupo.id) if grupo else None
        return render_template(
            "eventos.html",
            section="eventos",
            event_groups=event_groups,
            rows=rows,
            drill_event=drill_event,
            drill_group_id=drill_group_id,
            show_past=show_past,
            CAN_EDIT_CONCERTS=can_edit_concerts(),
            # Sin esta bandera `eventos.html` no incluye el asistente y el botón «+ Actividad»
            # no abría nada (el modal no llegaba siquiera al HTML).
            wizard_available=True,
            **_concert_wizard_context(s),
        )
    finally:
        s.close()


def _render_cycle_festivals(only_events: bool = False):
    """Listado de contenedores: «Festivales / Ciclos» o «Eventos» (misma pantalla, mismo trato)."""
    s = db()
    try:
        q = (s.query(CycleFestival).options(joinedload(CycleFestival.managing_company), joinedload(CycleFestival.venue)))
        # Un contenedor es «de evento» si lo dice su tipo (EVENTO / GIRA) o si cuelga de un AppEvent
        # (una gira o un ciclo pueden ser de un evento). Los demás son de Festivales / Ciclos.
        _de_evento = or_(
            func.upper(func.coalesce(CycleFestival.kind, "")).in_(list(CYCLE_FESTIVAL_EVENT_KINDS)),
            CycleFestival.event_id.isnot(None),
        )
        q = q.filter(_de_evento) if only_events else q.filter(~_de_evento)
        items = q.order_by(CycleFestival.status.asc(), CycleFestival.start_date.desc().nullslast(),
                          CycleFestival.created_at.desc()).all()
        counts = dict(
            s.query(Concert.cycle_festival_id, func.count(Concert.id))
            .filter(Concert.cycle_festival_id.isnot(None)).group_by(Concert.cycle_festival_id).all()
        )
        rows = []
        for cf in items:
            label, badge = _group_status_meta(cf.status)
            rows.append({
                "id": str(cf.id), "name": cf.name, "logo_url": (cf.logo_url or ""),
                "kind": (cf.kind or "FESTIVAL").upper(),
                "kind_label": CYCLE_FESTIVAL_KIND_LABELS.get((cf.kind or "FESTIVAL").upper(), "Festival"),
                "edition": (cf.edition or ""),
                "company": (cf.managing_company.name if cf.managing_company else ""),
                "company_logo": (cf.managing_company.logo_url if cf.managing_company else ""),
                "venue_name": (cf.venue.name if cf.venue else ""),
                "date_range": _date_range_label(cf.start_date, cf.end_date),
                "status": (cf.status or "ACTIVO").upper(), "status_label": label, "status_badge": badge,
                "count": int(counts.get(cf.id, 0)),
            })
        artists = s.query(Artist).order_by(Artist.name.asc()).all()
        companies = s.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
        events = s.query(AppEvent).order_by(AppEvent.name.asc()).all()
        venues = s.query(Venue).order_by(Venue.name.asc()).all()
        return render_template(
            "festivales_ciclos.html",
            section=("eventos" if only_events else "festivales-ciclos"),
            only_events=only_events,
            page_title=("Eventos · giras y ciclos" if only_events else "Festivales / Ciclos"),
            page_subtitle=("Lo que se organiza de un evento: su gira propia (con varias fechas), un ciclo "
                           "o un festival. No son giras compradas: eso es lo que se le compra a un promotor."
                           if only_events else
                           "Festivales y ciclos organizados por el grupo, con sus conciertos."),
            rows=rows, artists=artists, companies=companies, events=events, venues=venues,
            CAN_EDIT_CONCERTS=can_edit_concerts(),
        )
    finally:
        s.close()


def _apply_cycle_form(cf, form):
    # ⚠️ Si el formulario NO trae «kind» se conserva el que ya tenía. El modal de editar de la ficha
    # solo ofrecía FESTIVAL/CICLO, así que guardar un contenedor de EVENTO lo degradaba a CICLO y,
    # de rebote, le borraba el vínculo con el evento (el `event_id` solo se mantiene en esa rama).
    kind = (form.get("kind") or getattr(cf, "kind", None) or "FESTIVAL").strip().upper()
    cf.kind = kind if kind in CYCLE_FESTIVAL_KIND_LABELS else "FESTIVAL"
    cf.name = ((form.get("name") or "").strip()
               or {"EVENTO": "Evento", "GIRA": "Gira"}.get(cf.kind, "Ciclo / Festival"))
    # Queda enganchado al EVENTO de la base de datos si se eligió (una gira o un ciclo pueden ser
    # de un evento, igual que de un artista). Si el formulario no trae el campo (p. ej. el modal de
    # editar), se conserva el vínculo actual en vez de borrarlo.
    if "event_id" in form:
        _ev = (form.get("event_id") or "").strip()
        cf.event_id = to_uuid(_ev) if _ev else None
    cid = (form.get("managing_company_id") or "").strip()
    cf.managing_company_id = to_uuid(cid) if cid else None
    cf.edition = (form.get("edition") or "").strip() or None
    vid = (form.get("venue_id") or "").strip()
    cf.venue_id = to_uuid(vid) if vid else None
    cf.municipality = (form.get("municipality") or "").strip() or None
    cf.province = (form.get("province") or "").strip() or None
    cf.logo_url = (form.get("logo_url") or "").strip() or (cf.logo_url or None)
    cf.start_date = parse_optional_date(form.get("start_date"))
    cf.end_date = parse_optional_date(form.get("end_date"))
    cf.notes = (form.get("notes") or "").strip() or None


@app.post("/contratacion/ciclos/crear", endpoint="cycle_festival_create")
@admin_required
def cycle_festival_create():
    s = db()
    cid = None
    try:
        cf = CycleFestival(status="ACTIVO")
        _apply_cycle_form(cf, request.form)
        _apply_group_create_economics(cf, request.form)
        # Logo: si se elige un evento y no hay logo propio, hereda el del evento.
        ev_id = (request.form.get("event_id") or "").strip()
        if ev_id and not cf.logo_url:
            ev = s.get(AppEvent, to_uuid(ev_id))
            if ev:
                cf.logo_url = ev.logo_url or None
                if not (request.form.get("name") or "").strip():
                    cf.name = ev.name
        st = _current_user_state()
        cf.created_by_user_id = to_uuid(st.get("user_id")) if st.get("user_id") else None
        cf.created_by_nick = st.get("nick") or None
        s.add(cf)
        s.commit()
        cid = str(cf.id)
        flash({"EVENTO": "Evento creado.", "GIRA": "Gira del evento creada."}.get(
            (cf.kind or "").upper(), "Ciclo/Festival creado."), "success")
    except Exception as exc:
        s.rollback()
        flash(f"No se pudo crear: {exc}", "danger")
    finally:
        s.close()
    if cid:
        return redirect(url_for("cycle_festival_detail", cfid=cid))
    return redirect(url_for("contracting_view", section="festivales-ciclos"))


@app.get("/contratacion/ciclos/<cfid>", endpoint="cycle_festival_detail")
@admin_required
def cycle_festival_detail(cfid):
    s = db()
    try:
        cf = s.query(CycleFestival).options(joinedload(CycleFestival.managing_company), joinedload(CycleFestival.venue)).filter(CycleFestival.id == to_uuid(cfid)).first()
        if not cf:
            abort(404)
        concerts = _cycle_concerts(s, cf.id)
        rows = [_group_concert_row(c) for c in concerts]
        for _row, _c in zip(rows, concerts):
            _row["econ"] = _group_concert_econ(s, _c)
        general = _group_general(cf)
        gen_total = general["advance"] + sum(x["amount"] for x in general["expenses"])
        candidates = (
            s.query(Concert).options(joinedload(Concert.artist), joinedload(Concert.venue))
            .filter(Concert.cycle_festival_id.is_(None))
            .order_by(Concert.date.asc().nullslast()).limit(150).all()
        )
        cand_rows = [{"id": str(c.id), "label": ((c.date.strftime("%d/%m/%Y") + " · ") if c.date else "") + ((c.artist.name + " · ") if c.artist else "") + (c.venue.name if c.venue else (c.manual_venue_name or c.festival_name or "Concierto"))} for c in candidates]
        label, badge = _group_status_meta(cf.status)
        artists = s.query(Artist).order_by(Artist.name.asc()).all()
        companies = s.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
        venues = s.query(Venue).order_by(Venue.name.asc()).all()
        # Selector de simulaciones a vincular: solo las ACTIVAS (las archivadas ya se
        # convirtieron o se guardaron aparte; las que YA estén vinculadas siguen viéndose).
        simulations = (
            s.query(Simulation).options(joinedload(Simulation.artist))
            .filter(func.upper(func.coalesce(Simulation.status, "ACTIVE")) != "ARCHIVED")
            .order_by(Simulation.created_at.desc()).limit(200).all()
        )
        return render_template(
            "activity_group_detail.html",
            # Cartelería de TODO el ciclo/festival/evento.
            **_artwork_group_context(s, "CYCLE", cf.id),
            # Marketing del ciclo/festival/evento entero.
            **_promotion_panel_context(s, "CICLO", cf.id),
            can_validate_artwork=_can_validate_artwork(),
            group_kind=(cf.kind or "FESTIVAL").upper(),
            # Un contenedor es de un EVENTO por su tipo o por colgar de un AppEvent.
            group_is_event=bool(cf.event_id) or (cf.kind or "").upper() in CYCLE_FESTIVAL_EVENT_KINDS,
            group=cf, concerts=rows, general=general,
            advance_share=0.0, gen_total=gen_total, candidates=cand_rows,
            status_label=label, status_badge=badge, artists=artists, companies=companies,
            venues=venues, simulations=simulations, linked_sims=_group_linked_sims(s, general),
            general_roadmap=_group_general_roadmap(concerts),
            group_result=_group_result_context(s, concerts, general),
            CAN_EDIT_CONCERTS=can_edit_concerts(),
        )
    finally:
        s.close()


