@app.get("/api/artists/<aid>/wizard-meta", endpoint="api_artist_wizard_meta")
@admin_required
def api_artist_wizard_meta(aid):
    """Datos del artista para el asistente de actividad: su repertorio (eventos promocionales
    donde el artista canta) y los # que ya usa (sugerencias del paso de gira, sin duplicados)."""
    s = db()
    try:
        artist_uuid = to_uuid(aid)
        if not artist_uuid:
            return jsonify({"songs": [], "tags": []})
        songs = _repertoire_songs_for_artists(s, [artist_uuid])
        tags = []
        seen = set()
        for (tags_json,) in s.query(Concert.hashtags).filter(Concert.artist_id == artist_uuid).all():
            for raw in (tags_json or []):
                tag = _norm_concert_tag(raw)
                key = _norm_text_key(tag)
                if tag and key not in seen:
                    seen.add(key)
                    tags.append(tag)
        return jsonify({
            "songs": [{"id": row["id"], "title": row["title"]} for row in songs],
            "tags": tags,
        })
    finally:
        s.close()


@app.post("/api/events/create", endpoint="api_create_event")
@admin_required
def api_create_event():
    """Alta rápida de evento (quick_create.js): nombre + logo opcional, con aviso de similares."""
    s = db()
    try:
        name = (request.form.get("name") or "").strip()
        if not name:
            return jsonify({"error": "El nombre del evento es obligatorio."}), 400
        force_new = _truthy(request.form.get("force_new"))
        rows = [
            {"id": str(e.id), "label": (e.name or "").strip(), "logo_url": (e.logo_url or "").strip()}
            for e in s.query(AppEvent).order_by(AppEvent.name.asc()).all()
        ]
        exact = s.query(AppEvent).filter(func.lower(AppEvent.name) == name.lower()).first()
        similar = _build_similarity_rows(name, rows, threshold=0.78)
        if exact and not force_new:
            similar = [{"id": str(exact.id), "label": (exact.name or "").strip(), "score": 1.0, "logo_url": (exact.logo_url or "").strip()}]
        if similar and not force_new:
            return jsonify({"error": "Ya existe un evento similar.", "similar": similar}), 409
        logo = request.files.get("logo")
        logo_url = upload_image(logo, "events") if logo and getattr(logo, "filename", "") else None
        ev = AppEvent(name=name, logo_url=logo_url)
        s.add(ev)
        s.commit()
        return jsonify({"id": str(ev.id), "label": ev.name, "text": ev.name, "name": ev.name, "logo_url": ev.logo_url})
    except Exception as e:
        s.rollback()
        return jsonify({"error": str(e)}), 400
    finally:
        s.close()


# ============================ Bases de datos · DISTRIBUIDORAS ============================
# Distribuidoras digitales (nombre + logo): se asignan a canciones/álbumes propios o de
# distribución y son la contraparte de los ADELANTOS de Discográfica.

@app.get("/distribuidoras", endpoint="distributors_view")
@admin_required
def distributors_view():
    s = db()
    try:
        q = (request.args.get("q") or "").strip()
        rows = s.query(Distributor).order_by(Distributor.name.asc()).all()
        if q:
            qn = _norm_text_key(q)
            rows = [d for d in rows if qn in _norm_text_key(d.name or "")]
        song_counts = {
            str(k): v
            for k, v in s.query(Song.distributor_id, func.count(Song.id))
            .filter(Song.distributor_id.isnot(None)).group_by(Song.distributor_id).all()
        }
        adv_counts = {
            str(k): v
            for k, v in s.query(DistributorAdvance.distributor_id, func.count(DistributorAdvance.id))
            .group_by(DistributorAdvance.distributor_id).all()
        }
        return render_template("distribuidoras_list.html", distributors=rows, query_text=q,
                               song_counts=song_counts, adv_counts=adv_counts,
                               CAN_EDIT=can_edit_catalogs())
    finally:
        s.close()


