@app.post("/api/distributors/create", endpoint="api_create_distributor")
@admin_required
def api_create_distributor():
    """Alta rápida de distribuidora (quick_create.js): nombre + logo, con aviso de similares."""
    s = db()
    try:
        name = (request.form.get("name") or "").strip()
        if not name:
            return jsonify({"error": "El nombre de la distribuidora es obligatorio."}), 400
        force_new = _truthy(request.form.get("force_new"))
        rows = [
            {"id": str(d.id), "label": (d.name or "").strip(), "logo_url": (d.logo_url or "").strip()}
            for d in s.query(Distributor).order_by(Distributor.name.asc()).all()
        ]
        exact = s.query(Distributor).filter(func.lower(Distributor.name) == name.lower()).first()
        similar = _build_similarity_rows(name, rows, threshold=0.78)
        if exact and not force_new:
            similar = [{"id": str(exact.id), "label": (exact.name or "").strip(), "score": 1.0, "logo_url": (exact.logo_url or "").strip()}]
        if similar and not force_new:
            return jsonify({"error": "Ya existe una distribuidora similar.", "similar": similar}), 409
        logo = request.files.get("logo")
        logo_url = upload_image(logo, "distributors") if logo and getattr(logo, "filename", "") else None
        d = Distributor(name=name, logo_url=logo_url)
        s.add(d)
        s.commit()
        return jsonify({"id": str(d.id), "label": d.name, "text": d.name, "name": d.name, "logo_url": d.logo_url})
    except Exception as e:
        s.rollback()
        return jsonify({"error": str(e)}), 400
    finally:
        s.close()


def _expense_template_owner(session_db, ot, oid):
    """Nombre, foto y URL de vuelta del dueño de una plantilla de gastos."""
    ot = (ot or "").upper()
    if ot == "ARTIST":
        row = session_db.get(Artist, oid)
        return ((row.name if row else "Artista"), (getattr(row, "photo_url", "") or ""),
                url_for("artist_detail_view", artist_id=str(oid), tab="plantillas"))
    if ot == "EVENT":
        row = session_db.get(AppEvent, oid)
        return ((row.name if row else "Evento"), (getattr(row, "logo_url", "") or ""),
                url_for("events_view"))
    row = session_db.get(Venue, oid)
    return ((row.name if row else "Recinto"), (getattr(row, "photo_url", "") or ""),
            url_for("venue_detail_view", vid=str(oid)) if row else url_for("venues_view"))


def _expense_template_items_payload(tpl) -> list:
    """Las líneas de la plantilla en el formato que espera el módulo de gastos."""
    out = []
    for it in (tpl.items or []):
        out.append({
            "category": (it.category or "OTROS"),
            "concept": (it.concept or ""),
            "amount_net": float(_money_or_zero(it.amount_net)),
            "quantity": float(_money_or_zero(it.quantity) or 1),
            "iva_pct": float(_money_or_zero(it.iva_pct)),
            "includes_iva": bool(it.includes_iva),
            "iva_exempt": bool(it.iva_exempt),
            "is_variable": bool(it.is_variable),
            "var_type": (it.var_type or None),
            "var_value": float(_money_or_zero(it.var_value)),
        })
    return out


