def _setlist_pdf_header(s, owner_type, owner_id):
    """(artista, subtítulo) para la cabecera del PDF: nombre del concierto o, si no, municipio y fecha."""
    ot = (owner_type or "").strip().upper()
    oid = _sim_safe_uuid(owner_id)
    artist, subtitle = "", ""
    if ot == "CONCERT" and oid:
        c = (s.query(Concert).options(joinedload(Concert.artist), joinedload(Concert.venue))
             .filter(Concert.id == oid).first())
        if c:
            artist = (c.artist.name if c.artist else "") or (c.festival_name or "")
            if c.festival_name:
                subtitle = c.festival_name
            else:
                muni = (c.venue.municipality if c.venue else None) or c.manual_municipality or ""
                d = c.date.strftime("%d/%m/%Y") if c.date else ""
                subtitle = " · ".join(x for x in [muni, d] if x)
    elif ot == "ACTION" and oid:
        a = (s.query(CompanyAction).options(joinedload(CompanyAction.venue))
             .filter(CompanyAction.id == oid).first())
        if a:
            arts = _artists_from_ids(s, getattr(a, "artist_ids", []) or [])
            artist = ", ".join([x.name for x in arts if getattr(x, "name", None)]) or (a.title or "")
            muni = (a.venue.municipality if a.venue else None) or ""
            d = a.start_date.strftime("%d/%m/%Y") if getattr(a, "start_date", None) else ""
            subtitle = a.title or (" · ".join(x for x in [muni, d] if x))
    return {"artist": artist, "subtitle": subtitle}


@app.get("/setlist/pdf", endpoint="setlist_pdf")
@admin_required
def setlist_pdf():
    """Set list en PDF: A4 fondo negro, títulos en MAYÚSCULAS/negrita numerados, letra lo más grande
    posible que quepa; incluye líneas de parón y comentarios; SIN duraciones."""
    if not REPORTLAB_AVAILABLE:
        abort(503)
    from reportlab.pdfgen import canvas as _canvas
    from reportlab.lib.pagesizes import A4
    s = db()
    try:
        owner_type = (request.args.get("owner_type") or "").strip().upper()
        owner_id = _sim_safe_uuid(request.args.get("owner_id"))
        t = _get_setlist(s, owner_type, owner_id)
        header = _setlist_pdf_header(s, owner_type, owner_id)
        items = sorted((t.items or []) if t else [], key=lambda x: (x.sort_order or 0))

        lines = []  # {t, type: song|break|note|comment, num}
        n = 0
        for it in items:
            kind = (it.kind or "SONG").upper()
            if kind == "SONG":
                n += 1
                lines.append({"t": (it.title or "").upper(), "type": "song", "num": n})
                if (it.note or "").strip():
                    lines.append({"t": (it.note or "").strip(), "type": "comment"})
            elif kind == "BREAK":
                lines.append({"t": (it.title or "").strip().upper(), "type": "break"})
            else:
                lines.append({"t": (it.title or "").strip().upper(), "type": "note"})

        buf = BytesIO()
        W, H = A4
        c = _canvas.Canvas(buf, pagesize=A4)
        c.setFillColorRGB(0, 0, 0)
        c.rect(0, 0, W, H, stroke=0, fill=1)  # fondo negro
        margin = 34
        usable_w = W - 2 * margin

        # Cabecera: "SET LIST" + artista + (concierto / municipio·fecha)
        c.setFillColorRGB(1, 1, 1)
        c.setFont("Helvetica-Bold", 30)
        y = H - margin - 30
        c.drawCentredString(W / 2, y, "SET LIST")
        if (header.get("artist") or "").strip():
            y -= 24
            c.setFont("Helvetica-Bold", 16)
            c.drawCentredString(W / 2, y, header["artist"])
        if (header.get("subtitle") or "").strip():
            y -= 18
            c.setFont("Helvetica", 12)
            c.setFillColorRGB(0.8, 0.8, 0.8)
            c.drawCentredString(W / 2, y, header["subtitle"])

        content_top = y - 22
        avail_h = content_top - margin
        if not lines:
            c.showPage(); c.save(); buf.seek(0)
            return send_file(buf, mimetype="application/pdf", as_attachment=False, download_name="setlist.pdf")

        units = sum(0.55 if ln["type"] == "comment" else 1.0 for ln in lines) or 1.0
        line_h = avail_h / units
        font_sz = min(line_h * 0.72, 64)

        def widest(sz):
            mw = 0
            for ln in lines:
                if ln["type"] == "comment":
                    continue
                prefix = (f'{ln["num"]}. ' if ln["type"] == "song" else "")
                mw = max(mw, c.stringWidth(prefix + ln["t"], "Helvetica-Bold", sz))
            return mw
        while font_sz > 9 and widest(font_sz) > usable_w:
            font_sz -= 1
        comment_sz = max(font_sz * 0.5, 8)

        y = content_top - line_h
        for ln in lines:
            if ln["type"] == "comment":
                c.setFont("Helvetica-Oblique", comment_sz)
                c.setFillColorRGB(0.72, 0.72, 0.72)
                c.drawString(margin + font_sz * 0.6, y + (line_h * 0.55 - comment_sz) / 2, ln["t"])
                y -= line_h * 0.55
                continue
            baseline = y + (line_h - font_sz) / 2
            if ln["type"] == "song":
                c.setFillColorRGB(1, 1, 1)
                c.setFont("Helvetica-Bold", font_sz)
                c.drawString(margin, baseline, f'{ln["num"]}. {ln["t"]}')
            elif ln["type"] == "break":
                c.setStrokeColorRGB(0.55, 0.55, 0.55)
                c.setLineWidth(max(1, font_sz * 0.04))
                if ln["t"]:
                    c.setFillColorRGB(0.7, 0.7, 0.7)
                    c.setFont("Helvetica-Oblique", font_sz * 0.55)
                    c.drawCentredString(W / 2, baseline, ln["t"])
                else:
                    mid = y + line_h / 2
                    c.line(margin, mid, W - margin, mid)
            else:  # note / agradecimiento
                c.setFillColorRGB(0.92, 0.86, 0.55)
                c.setFont("Helvetica-Bold", font_sz * 0.8)
                c.drawString(margin, baseline, ln["t"])
            y -= line_h

        c.showPage()
        c.save()
        buf.seek(0)
        return send_file(buf, mimetype="application/pdf", as_attachment=False, download_name="setlist.pdf")
    finally:
        s.close()


# ============================ SIMULACIONES (Contratación) ============================

def _sim_safe_uuid(v):
    """UUID o None (sin lanzar)."""
    if v is None:
        return None
    if isinstance(v, str):
        v = v.strip()
        if not v:
            return None
    try:
        return to_uuid(v)
    except Exception:
        return None


def _sim_parse_date(v):
    v = (v or "").strip()
    if not v:
        return None
    try:
        return datetime.strptime(v, "%Y-%m-%d").date()
    except Exception:
        return None


# --- Constantes de cálculo de simulaciones ---
SIM_IVA_TICKET = Decimal("0.10")     # IVA de las entradas (10%) — por defecto
SIM_SGAE_RATE = Decimal("0.0765")    # SGAE: 7,65% sobre el precio sin IVA — por defecto
SIM_IVA_EXTRA = Decimal("0.10")      # IVA de complementos (10%) — por defecto


def _sim_tax_cfg(activity):
    """Tasas fiscales del ticketing (IVA entradas/complementos y SGAE) configurables por la rueda.

    Se guardan en activity.settings['tax'] como PORCENTAJES (10 = 10%). Si no hay nada,
    devuelve las de la casa. Devuelve porcentajes (Decimal) para mostrar y fracciones para el motor.
    """
    tax = {}
    try:
        tax = dict((activity.settings or {}).get("tax") or {}) if activity is not None else {}
    except Exception:
        tax = {}
    def _pct(key, default_frac):
        v = tax.get(key)
        if v is None or v == "":
            return default_frac * Decimal("100")
        try:
            return Decimal(str(v))
        except Exception:
            return default_frac * Decimal("100")
    return {
        "iva_ticket_pct": _pct("iva_ticket", SIM_IVA_TICKET),
        "iva_extra_pct": _pct("iva_extra", SIM_IVA_EXTRA),
        "sgae_pct": _pct("sgae", SIM_SGAE_RATE),
    }

# Categorías de GASTOS del simulador (tarjetas «bocadillo», orden fijo) + icono FA.
SIM_EXPENSE_CATEGORIES = [
    ("RECINTO", "Gastos del recinto", "fa-building"),
    ("RIDER", "Rider", "fa-list-check"),
    ("SONIDO_LUCES", "Producción técnica e infraestructuras", "fa-sliders"),
    ("PERSONAL", "Personal", "fa-users-gear"),
    ("MUSICOS", "Músicos", "fa-guitar"),
    ("LOGISTICA", "Logística", "fa-truck"),
    ("ALOJAMIENTO", "Alojamiento", "fa-bed"),
    ("MARKETING", "Marketing y promoción", "fa-bullhorn"),
    ("PERMISOS", "Permisos y licencias", "fa-stamp"),
    ("OTROS", "Otros gastos", "fa-shapes"),
]
# Categorías cuyos gastos se introducen por CANTIDAD (importe unitario × cantidad).
SIM_EXPENSE_QTY_CATEGORIES = ["ALOJAMIENTO", "LOGISTICA", "PERSONAL", "MUSICOS"]
SIM_EXPENSE_CATEGORY_LABELS = {k: l for k, l, _ic in SIM_EXPENSE_CATEGORIES}
SIM_EXPENSE_CATEGORY_ICONS = {k: ic for k, _l, ic in SIM_EXPENSE_CATEGORIES}
# PRORRATEO: categoría CALCULADA (no editable) que reparte los gastos generales del ciclo/gira en
# cada fecha. Solo etiqueta/icono para mostrarla; nunca entra en el editor de gastos.
SIM_EXPENSE_CATEGORY_LABELS["PRORRATEO"] = "Prorrateo (gastos generales)"
SIM_EXPENSE_CATEGORY_ICONS["PRORRATEO"] = "fa-layer-group"
# Datos antiguos guardados con claves de bolsas: se reubican en su categoría nueva.
SIM_EXPENSE_LEGACY_MAP = {"TRANSPORTE": "LOGISTICA", "HOTELES": "ALOJAMIENTO", "PRORRATEOS": "OTROS"}


def _sim_expense_cat(key):
    k = (key or "OTROS").upper()
    k = SIM_EXPENSE_LEGACY_MAP.get(k, k)
    return k if k in SIM_EXPENSE_CATEGORY_LABELS else "OTROS"


def _sim_d(v):
    """Decimal seguro (acepta Decimal/num/str/None)."""
    if isinstance(v, Decimal):
        return v
    if v is None or v == "":
        return Decimal("0")
    try:
        return Decimal(str(v))
    except Exception:
        return Decimal("0")


def _sim_int(v):
    try:
        return int(_sim_d(v))
    except Exception:
        return 0


def _sim_ticketing_summary(activity):
    """Resumen de ticketing de una actividad, al 100% del aforo a la venta.

    Por entrada (vendible = aforo - invitaciones):
      - precio configurado = sin IVA, INCLUYE SGAE.
      - SGAE = 7,65% del precio sin IVA · IVA = 10% sobre el precio sin IVA.
      - neto (sin IVA y sin SGAE) = precio · (1 - 0,0765).
    """
    out = {
        "zones": {
            "PISTA": {"label": "Pista", "qty": 0, "invitations": 0, "sellable": 0},
            "GRADA": {"label": "Grada", "qty": 0, "invitations": 0, "sellable": 0},
            "PALCO": {"label": "Palcos", "qty": 0, "invitations": 0, "sellable": 0},
        },
        "aforo_total": 0, "invitations": 0, "sellable": 0,
        "ticket_sin_iva": Decimal("0"),   # sin IVA (incluye SGAE)
        "sgae": Decimal("0"), "iva": Decimal("0"),
        "ticket_net": Decimal("0"),       # neto sin IVA y sin SGAE
        "ticket_gross": Decimal("0"),     # con IVA (precio público)
        "extras_gross": Decimal("0"),     # complementos (IVA incl.), informativo en 2a
        "n_categories": 0,
    }
    _tax = _sim_tax_cfg(activity)
    _sgae_rate = _tax["sgae_pct"] / Decimal("100")
    _iva_rate = _tax["iva_ticket_pct"] / Decimal("100")
    for c in (activity.ticket_categories or []):
        zone = (c.zone or "PISTA").upper()
        if zone not in out["zones"]:
            zone = "PISTA"
        q = max(int(c.quantity or 0), 0)
        inv = max(int(c.invitations or 0), 0)
        sellable = max(q - inv, 0)
        price = _sim_d(c.price_net)
        sin_iva = price * sellable
        sgae = price * _sgae_rate * sellable
        iva = price * _iva_rate * sellable
        extra_per = sum((_sim_d(e.amount_gross) for e in (c.extras or [])), Decimal("0"))
        z = out["zones"][zone]
        z["qty"] += q; z["invitations"] += inv; z["sellable"] += sellable
        out["aforo_total"] += q; out["invitations"] += inv; out["sellable"] += sellable
        out["ticket_sin_iva"] += sin_iva
        out["sgae"] += sgae
        out["iva"] += iva
        out["ticket_net"] += (sin_iva - sgae)
        out["ticket_gross"] += (sin_iva + iva)
        out["extras_gross"] += extra_per * sellable
        out["n_categories"] += 1
    out["avg_price_sin_iva"] = (out["ticket_sin_iva"] / out["sellable"]) if out["sellable"] else Decimal("0")
    return out


def _sim_ticketing_payload(activity):
    """Estructura JSON para rehidratar el editor de ticketing (precios como float)."""
    rows = []
    for c in sorted(activity.ticket_categories or [], key=lambda x: ((x.zone or ""), x.sort_order or 0)):
        rows.append({
            "zone": (c.zone or "PISTA").upper(),
            "name": c.name or "",
            "price": float(_sim_d(c.price_net)),
            "qty": int(c.quantity or 0),
            "inv": int(c.invitations or 0),
            "extras": [
                {"name": e.name or "", "amount": float(_sim_d(e.amount_gross))}
                for e in sorted(c.extras or [], key=lambda x: x.sort_order or 0)
            ],
        })
    return rows


def _sim_cost_cfg(o):
    """Config de variable (común a caché/comisión) en dict plano para sim_calc."""
    return {
        "var_type": o.var_type, "var_value": float(_sim_d(o.var_value)),
        "var_threshold_type": o.var_threshold_type, "var_threshold_value": float(_sim_d(o.var_threshold_value)),
    }


def _sim_build_calc_data(sim, activity, artist_intl=None, prorateo=0.0):
    """Convierte los modelos ORM de una actividad al dict plano que espera sim_calc.

    artist_intl: mapa {artist_id(str): is_international} para resolver la retención por
    caché (festival: según el artista del caché; ciclo: según el artista del concierto).
    """
    if activity is None:
        return {}
    artist_intl = artist_intl or {}
    base_intl = bool(sim.artist.is_international) if sim.artist else False
    act_intl = artist_intl.get(str(activity.artist_id), base_intl) if activity.artist_id else base_intl
    cats = []
    for c in (activity.ticket_categories or []):
        cats.append({
            "zone": c.zone, "price_net": float(_sim_d(c.price_net)),
            "quantity": int(c.quantity or 0), "invitations": int(c.invitations or 0),
            "extras": [{"amount_gross": float(_sim_d(e.amount_gross))} for e in (c.extras or [])],
        })
    caches = []
    for c in (activity.caches or []):
        aids = [str(x) for x in (c.artist_ids or [])]
        c_intl = any(artist_intl.get(a, False) for a in aids) if aids else act_intl
        d = _sim_cost_cfg(c)
        d.update({
            "mode": c.mode, "amount": float(_sim_d(c.amount)),
            "includes_iva": bool(c.includes_iva), "includes_retention": bool(c.includes_retention),
            "retention_exempt": bool(c.retention_exempt),
            "is_international": c_intl,
        })
        caches.append(d)
    commissions = []
    for c in (activity.commissions or []):
        d = _sim_cost_cfg(c)
        d.update({
            "mode": c.mode, "amount": float(_sim_d(c.amount)),
            "includes_iva": bool(c.includes_iva), "exempt_amount": float(_sim_d(c.exempt_amount)),
        })
        commissions.append(d)
    production = []
    for p in (activity.production_items or []):
        d = _sim_cost_cfg(p)
        d.update({
            "category": _sim_expense_cat(p.category), "amount_net": float(_sim_d(p.amount_net)),
            "quantity": float(_sim_d(getattr(p, "quantity", 1) or 1)),
            "iva_pct": float(_sim_d(p.iva_pct)), "is_variable": bool(p.is_variable),
            "includes_iva": bool(getattr(p, "includes_iva", False)),
            "iva_exempt": bool(getattr(p, "iva_exempt", False)),
            "cond_under_tickets": (float(_sim_d(p.cond_under_tickets)) if p.cond_under_tickets is not None else None),
        })
        production.append(d)

    # Prorrateo de gastos generales (ciclo/gira/festival): línea CALCULADA en cada fecha, ya en neto
    # (sin IVA). No se edita; el total de la gira es la suma de las fechas (no se suma aparte).
    if prorateo and float(prorateo) != 0.0:
        production.append({
            "category": "PRORRATEO", "amount_net": float(prorateo), "quantity": 1,
            "iva_pct": 0, "is_variable": False, "includes_iva": False, "iva_exempt": True,
            "cond_under_tickets": None,
        })

    def _active(i):
        return (getattr(i, "status", None) or "ACTIVE").upper() not in ("OMIT", "NA")

    subventions = [float(_sim_d(i.amount_net)) for i in (activity.income_items or []) if (i.kind or "").upper() == "SUBVENCION" and _active(i)]
    sponsorships = [float(_sim_d(i.amount_net)) for i in (activity.income_items or []) if (i.kind or "").upper() == "PATROCINIO" and _active(i)]
    overrides = {}
    try:
        overrides = dict((activity.settings or {}).get("income_overrides") or {})
    except Exception:
        overrides = {}
    _tax = _sim_tax_cfg(activity)
    return {
        "is_international": act_intl,
        "allows_bars": bool(activity.venue.allows_bars) if activity.venue else False,
        "categories": cats, "caches": caches, "commissions": commissions,
        "production": production, "subventions": subventions, "sponsorships": sponsorships,
        "income_overrides": overrides,
        # Tasas fiscales configurables (fracciones) para el motor.
        "iva_ticket": float(_tax["iva_ticket_pct"]) / 100.0,
        "iva_extra": float(_tax["iva_extra_pct"]) / 100.0,
        "sgae_rate": float(_tax["sgae_pct"]) / 100.0,
    }


def _sim_festival_breakdown(activity, calc, artist_intl_map, lineup):
    """Reparto por artista de los cachés y comisiones de un festival (al 100%).

    Un coste asignado a N artistas se reparte a partes iguales (1/N) entre ellos.
    Devuelve filas [{name, photo, caches, commissions, total}] siguiendo el lineup,
    más una fila «Sin asignar» si hay costes sin artista. La suma coincide con el
    total de cachés+retenciones+comisiones del motor (la producción es general).
    """
    if activity is None or not calc:
        return []
    sellable = calc["ticketing"]["sellable"]
    taquilla = calc["ticketing"]["taquilla_sin_iva"]
    avg = calc["ticketing"]["avg_price_sin_iva"]
    rows = {}
    UN = "__none__"

    def add(aid, key, amt):
        b = rows.setdefault(aid, {"caches": 0.0, "commissions": 0.0, "total": 0.0})
        b[key] += amt
        b["total"] += amt

    for c in (activity.caches or []):
        cfg = {"var_type": c.var_type, "var_value": float(_sim_d(c.var_value)),
               "var_threshold_type": c.var_threshold_type, "var_threshold_value": float(_sim_d(c.var_threshold_value))}
        net = sim_calc.variable_amount(cfg, sellable, taquilla, avg) if (c.mode or "FIXED").upper() == "VARIABLE" else float(_sim_d(c.amount))
        if c.includes_iva:
            net = net / 1.21
        aids = [str(x) for x in (c.artist_ids or [])]
        intl = any(artist_intl_map.get(a, False) for a in aids) if aids else False
        ret = 0.24 * net if (intl and not c.retention_exempt and not c.includes_retention) else 0.0
        cost = net + ret
        targets = aids or [UN]
        for a in targets:
            add(a, "caches", cost / len(targets))

    for c in (activity.commissions or []):
        cfg = {"var_type": c.var_type, "var_value": float(_sim_d(c.var_value)),
               "var_threshold_type": c.var_threshold_type, "var_threshold_value": float(_sim_d(c.var_threshold_value))}
        if (c.mode or "FIXED").upper() == "VARIABLE":
            base = max(taquilla - float(_sim_d(c.exempt_amount)), 0.0)
            net = sim_calc.variable_amount(cfg, sellable, base, avg)
        else:
            net = float(_sim_d(c.amount))
        if c.includes_iva:
            net = net / 1.21
        aids = [str(x) for x in (c.artist_ids or [])]
        targets = aids or [UN]
        for a in targets:
            add(a, "commissions", net / len(targets))

    out = []
    for la in (lineup or []):
        aid = str(la.artist_id)
        if aid in rows:
            r = rows.pop(aid)
            out.append({"name": (la.artist.name if la.artist else "—"), "photo": (la.artist.photo_url if la.artist else None), **r})
    for aid, r in rows.items():
        out.append({"name": ("Sin asignar" if aid == UN else "Otro artista"), "photo": None, **r})
    return out


def _sim_expenses_payload(activity):
    """Datos JSON para rehidratar los editores de cachés/comisiones/producción."""
    if activity is None:
        return {"caches": [], "commissions": [], "production": []}

    def cfg(o):
        return {
            "var_type": (o.var_type or ""), "var_value": float(_sim_d(o.var_value)),
            "var_threshold_type": (o.var_threshold_type or ""), "var_threshold_value": float(_sim_d(o.var_threshold_value)),
        }

    caches = []
    for c in sorted(activity.caches or [], key=lambda x: x.sort_order or 0):
        d = cfg(c)
        d.update({
            "mode": (c.mode or "FIXED"), "label": (c.label or ""), "amount": float(_sim_d(c.amount)),
            "includes_iva": bool(c.includes_iva), "includes_retention": bool(c.includes_retention),
            "retention_exempt": bool(c.retention_exempt),
            "artist_ids": [str(x) for x in (c.artist_ids or [])],
        })
        caches.append(d)

    commissions = []
    for c in sorted(activity.commissions or [], key=lambda x: x.sort_order or 0):
        d = cfg(c)
        d.update({
            "mode": (c.mode or "FIXED"),
            "promoter_id": (str(c.promoter_id) if c.promoter_id else ""),
            "media_outlet_id": (str(c.media_outlet_id) if getattr(c, "media_outlet_id", None) else ""),
            "name": (c.name or (c.promoter.nick if c.promoter else "") or (c.media_outlet.name if getattr(c, "media_outlet", None) else "")),
            "logo": ((c.promoter.logo_url if c.promoter else "") or (c.media_outlet.logo_url if getattr(c, "media_outlet", None) else "")),
            "amount": float(_sim_d(c.amount)),
            "includes_iva": bool(c.includes_iva), "includes_retention": bool(c.includes_retention),
            "retention_exempt": bool(c.retention_exempt), "exempt_amount": float(_sim_d(c.exempt_amount)),
            "artist_ids": [str(x) for x in (c.artist_ids or [])],
        })
        commissions.append(d)

    production = []
    for p in sorted(activity.production_items or [], key=lambda x: x.sort_order or 0):
        d = cfg(p)
        d.update({
            "category": _sim_expense_cat(p.category), "concept": (p.concept or ""),
            "amount_net": float(_sim_d(p.amount_net)), "iva_pct": float(_sim_d(p.iva_pct)),
            "quantity": float(_sim_d(getattr(p, "quantity", 1) or 1)),
            "includes_iva": bool(getattr(p, "includes_iva", False)),
            "iva_exempt": bool(getattr(p, "iva_exempt", False)),
            "cond_under_tickets": (float(_sim_d(p.cond_under_tickets)) if p.cond_under_tickets is not None else None),
            "is_variable": bool(p.is_variable),
        })
        production.append(d)

    return {"caches": caches, "commissions": commissions, "production": production}


def _venue_ticketing_payload(cats):
    """Plantilla de ticketing del recinto (sin precio) para rehidratar el editor."""
    rows = []
    for c in sorted(cats or [], key=lambda x: ((x.zone or ""), x.sort_order or 0)):
        rows.append({
            "zone": (c.zone or "PISTA").upper(), "name": c.name or "",
            "qty": int(c.quantity or 0), "inv": int(c.invitations or 0),
            "extras": [{"name": e.name or "", "amount": float(_sim_d(e.amount_gross))} for e in sorted(c.extras or [], key=lambda x: x.sort_order or 0)],
        })
    return rows


def _venue_ticketing_summary(cats):
    """Aforo total / a la venta / invitaciones del recinto (desde su plantilla)."""
    zones = {"PISTA": {"label": "Pista", "qty": 0, "inv": 0, "sellable": 0},
             "GRADA": {"label": "Grada", "qty": 0, "inv": 0, "sellable": 0},
             "PALCO": {"label": "Palcos", "qty": 0, "inv": 0, "sellable": 0},
             "OTROS": {"label": "Otros", "qty": 0, "inv": 0, "sellable": 0}}
    tq = ti = ts = 0
    for c in (cats or []):
        zone = (c.zone or "PISTA").upper()
        if zone not in zones:
            zone = "PISTA"
        q = max(int(c.quantity or 0), 0)
        inv = max(int(c.invitations or 0), 0)
        s = max(q - inv, 0)
        zones[zone]["qty"] += q; zones[zone]["inv"] += inv; zones[zone]["sellable"] += s
        tq += q; ti += inv; ts += s
    return {"zones": zones, "aforo_total": tq, "invitations": ti, "sellable": ts, "has": bool(cats)}


def _sim_subject(sim):
    """Nombre y foto/logo del sujeto de la simulación (artista o evento)."""
    if sim.artist:
        return {"name": sim.artist.name, "photo": sim.artist.photo_url, "is_event": False}
    if sim.event:
        return {"name": sim.event.name, "photo": sim.event.logo_url, "is_event": True}
    return {"name": "Simulación", "photo": None, "is_event": False}


def _sim_global_partners(sim):
    return [p for p in sorted(sim.partners or [], key=lambda x: x.sort_order or 0) if not p.activity_id]


def _sim_partners_for_activity(sim, activity):
    """Socios efectivos de una fecha: los PROPIOS de la fecha si existen; si no, los comunes."""
    allp = sorted(sim.partners or [], key=lambda x: x.sort_order or 0)
    if activity is not None:
        own = [p for p in allp if p.activity_id and str(p.activity_id) == str(activity.id)]
        if own:
            return own
    return [p for p in allp if not p.activity_id]


def _sim_partner_row_payload(p):
    name = (p.company.name if p.company else (p.promoter.nick if p.promoter else (p.name or "Socio")))
    logo = (p.company.logo_url if p.company else (p.promoter.logo_url if p.promoter else None))
    return {
        "name": name, "logo": (logo or ""), "pct": float(_sim_d(p.pct)),
        "company_id": (str(p.company_id) if p.company_id else ""),
        "promoter_id": (str(p.promoter_id) if p.promoter_id else ""),
        "label": (p.name or ""),
        "no_loss": bool(getattr(p, "no_loss", False)),
    }


def _sim_commission_desc(c) -> str:
    """Comisión CONFIGURADA de un comisionista, legible: «Fija · 1.000 €», «Variable · 10% sobre
    ingresos (taquilla)», «Variable · 5% sobre el beneficio», «Variable · 0,50 € por entrada»…
    con umbral e importe exento si los hay. Se muestra bajo el nombre en el módulo Resultados."""
    def _n(v):
        try:
            f = float(_sim_d(v))
        except Exception:
            f = 0.0
        s = ("%.2f" % f).rstrip("0").rstrip(".")
        ent, _, dec = s.partition(".")
        try:
            ent = "{:,}".format(int(ent)).replace(",", ".")
        except Exception:
            pass
        return ent + ("," + dec if dec else "")
    if (c.mode or "FIXED").upper() == "VARIABLE":
        vt = (c.var_type or "").upper()
        if vt == "PER_TICKET":
            base = f"Variable · {_n(c.var_value)} € por entrada"
        elif vt == "PERCENT_PROFIT":
            base = f"Variable · {_n(c.var_value)}% sobre el beneficio"
        else:
            base = f"Variable · {_n(c.var_value)}% sobre ingresos (taquilla)"
        tt = (c.var_threshold_type or "").upper()
        if tt == "TICKETS" and float(_sim_d(c.var_threshold_value)) > 0:
            base += f" · a partir de {_n(c.var_threshold_value)} entradas"
        elif tt == "AMOUNT" and float(_sim_d(c.var_threshold_value)) > 0:
            base += f" · a partir de {_n(c.var_threshold_value)} €"
        if float(_sim_d(getattr(c, "exempt_amount", 0) or 0)) > 0:
            base += f" · exento hasta {_n(c.exempt_amount)} €"
        return base
    extras = []
    if getattr(c, "includes_iva", False):
        extras.append("IVA incluido")
    return f"Fija · {_n(c.amount)} €" + ((" · " + " · ".join(extras)) if extras else "")


def _sim_partner_module_payload(sim, activity, calc, extra_fixed_cost=0.0, label=None):
    """Datos de UNA fecha para el módulo de RESULTADOS (socios + comisionistas + gastos con
    slider 0–100%). Cada punto de la serie lleva el desglose (g/com) que pinta sim_partners.js
    en vivo al arrastrar la barra.

    extra_fixed_cost: gastos generales del ciclo repartidos a esta fecha (fijos, no
    escalan con la venta): se suman a los gastos y se restan del resultado en cada punto.
    """
    fine = []
    for pt in (calc.get("series_fine") or []):
        g = dict(pt.get("g") or {})
        if extra_fixed_cost:
            prod = dict(g.get("prod") or {})
            prod["PRORRATEO"] = round((prod.get("PRORRATEO") or 0.0) + extra_fixed_cost, 2)
            g["prod"] = prod
        fine.append({
            "pct": pt["pct"], "tickets": pt["tickets"],
            "ingresos": pt["ingresos"],
            "gastos": round(pt["gastos"] + extra_fixed_cost, 2),
            "resultado": round(pt["resultado"] - extra_fixed_cost, 2),
            "g": g,
            "com": list(pt.get("com") or []),
        })
    be_pct = None
    be_tickets = None
    for pt in fine:
        if pt["resultado"] >= 0:
            be_pct = pt["pct"]
            be_tickets = pt["tickets"]
            break
    # Comisionistas (mismo ORDEN que las series "com": el de activity.commissions, que es el que
    # usa _sim_build_calc_data): nombre + logo/foto (tercero o medio) + la comisión CONFIGURADA
    # (fija o variable, y si es variable sobre qué: entradas, ingresos o beneficio).
    commissions_meta = []
    for c in sorted((activity.commissions or []) if activity is not None else [], key=lambda x: x.sort_order or 0):
        name = (c.name or "").strip() or (
            (c.promoter.nick if c.promoter else None) or (c.media_outlet.name if c.media_outlet else None) or "Comisionista")
        logo = (c.promoter.logo_url if c.promoter else None) or (getattr(c.media_outlet, "logo_url", None) if c.media_outlet else None) or ""
        commissions_meta.append({"name": name, "logo": logo, "desc": _sim_commission_desc(c)})
    return {
        "label": label or "",
        "partners": [_sim_partner_row_payload(p) for p in _sim_partners_for_activity(sim, activity)],
        "commissions": commissions_meta,
        "series": fine,
        "sellable": calc["ticketing"]["sellable"] if calc else 0,
        "break_even_pct": be_pct,
        "break_even_tickets": be_tickets,
    }


def _sim_expense_templates_payload(s, sim, activity):
    """Plantillas de gastos aplicables a esta actividad (recinto + artista/evento), recientes primero."""
    out = []
    if activity is not None and activity.venue_id:
        vname = activity.venue.name if activity.venue else "Recinto"
        for t in _expense_templates_for(s, "VENUE", activity.venue_id):
            out.append(_expense_template_payload(t, "VENUE", vname))
    art_id = (activity.artist_id if (activity is not None and activity.artist_id) else sim.artist_id)
    if art_id:
        a = s.get(Artist, art_id)
        for t in _expense_templates_for(s, "ARTIST", art_id):
            out.append(_expense_template_payload(t, "ARTIST", a.name if a else "Artista"))
    if sim.event_id:
        for t in _expense_templates_for(s, "EVENT", sim.event_id):
            out.append(_expense_template_payload(t, "EVENT", sim.event.name if sim.event else "Evento"))
    out.sort(key=lambda x: x.get("updated_ts") or "", reverse=True)
    return out


def _simulation_converted_info(session_db, sim) -> dict | None:
    """Qué se creó a partir de una simulación archivada (para enlazarlo desde «Archivadas»).

    Si lo creado ya no existe se devuelve el nombre guardado sin enlace: la simulación sigue
    archivada, pero el usuario ve que su destino desapareció y puede restaurarla."""
    info = (sim.settings or {}).get("converted") if isinstance(sim.settings, dict) else None
    if not isinstance(info, dict):
        return None
    kind = (info.get("kind") or "").strip().upper()
    target_id = info.get("target_id")
    labels = {"TOUR": "Gira comprada", "CYCLE": "Ciclo", "FESTIVAL": "Festival",
              "EVENT": "Evento", "CONCERT": "Concierto"}
    out = {
        "kind": kind,
        "label": labels.get(kind, "Actividad"),
        "name": (info.get("target_name") or "").strip() or "Actividad",
        "dates": len(info.get("concert_ids") or []),
        "url": "",
        "missing": True,
    }
    try:
        uid = to_uuid(target_id) if target_id else None
        if uid and kind == "TOUR" and session_db.get(PurchasedTour, uid):
            out.update(url=url_for("purchased_tour_detail", tid=str(uid)), missing=False)
        elif uid and kind in ("CYCLE", "FESTIVAL", "EVENT") and session_db.get(CycleFestival, uid):
            out.update(url=url_for("cycle_festival_detail", cfid=str(uid)), missing=False)
        elif uid and kind == "CONCERT" and session_db.get(Concert, uid):
            out.update(url=url_for("concert_detail_view", cid=str(uid)), missing=False)
    except Exception:
        pass
    return out


def _render_simulations_list():
    """Listado de simulaciones agrupadas por artista (solo artistas con simulaciones).

    Por defecto solo las ACTIVAS: al convertir una simulación en gira/ciclo/festival/concierto
    pasa a ARCHIVED y desaparece de aquí, pero se puede consultar con «Ver archivadas»."""
    s = db()
    try:
        show_archived = _truthy(request.args.get("archivadas"))
        base = s.query(Simulation).options(
            joinedload(Simulation.artist),
            joinedload(Simulation.event),
            joinedload(Simulation.managing_company),
            selectinload(Simulation.activities).joinedload(SimulationActivity.venue),
        )
        archived_cond = func.upper(func.coalesce(Simulation.status, "ACTIVE")) == "ARCHIVED"
        sims = (
            base.filter(archived_cond if show_archived else ~archived_cond)
            .order_by(Simulation.created_at.desc())
            .all()
        )
        archived_count = (
            s.query(func.count(Simulation.id)).filter(archived_cond).scalar() or 0
        )
        converted = {str(sim.id): _simulation_converted_info(s, sim) for sim in sims} if show_archived else {}
        groups = {}
        for sim in sims:
            a = sim.artist
            ev = sim.event if not a else None
            key = ("a:" + str(a.id)) if a else (("e:" + str(ev.id)) if ev else "__none__")
            g = groups.get(key)
            if not g:
                g = {"artist": a, "event": ev, "sims": []}
                groups[key] = g
            g["sims"].append(sim)

        def _group_sort_name(gr):
            if gr["artist"]:
                return (gr["artist"].name or "").lower()
            if gr["event"]:
                return (gr["event"].name or "").lower()
            return "zzz"

        groups_list = sorted(groups.values(), key=_group_sort_name)
        artists = s.query(Artist).order_by(Artist.name.asc()).all()
        companies = s.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
        return render_template(
            "simulaciones_list.html",
            section="simulaciones",
            groups=groups_list,
            total_sims=len(sims),
            artists=artists,
            companies=companies,
            show_archived=show_archived,
            archived_count=archived_count,
            converted=converted,
            CAN_EDIT=can_edit_simulations(),
        )
    finally:
        s.close()


def _simulation_partners_from_form(form):
    """Filas de socios desde el asistente (arrays paralelos kind/ref/label/pct)."""
    kinds = form.getlist("partner_kind[]")
    refs = form.getlist("partner_ref[]")
    labels = form.getlist("partner_label[]")
    pcts = form.getlist("partner_pct[]")
    no_losses = form.getlist("partner_no_loss[]")
    rows = []
    n = max(len(kinds), len(refs), len(labels), len(pcts)) if (kinds or refs or labels or pcts) else 0
    for i in range(n):
        kind = (kinds[i] if i < len(kinds) else "").strip().lower()
        ref = (refs[i] if i < len(refs) else "").strip()
        label = (labels[i] if i < len(labels) else "").strip()
        pct = _money_or_zero(pcts[i] if i < len(pcts) else "0")
        no_loss = _truthy(no_losses[i]) if i < len(no_losses) else False
        company_id = promoter_id = None
        if kind == "company":
            company_id = _sim_safe_uuid(ref)
        elif kind == "promoter":
            promoter_id = _sim_safe_uuid(ref)
        if not company_id and not promoter_id and not label:
            continue
        rows.append({"company_id": company_id, "promoter_id": promoter_id, "name": label or None, "pct": pct, "no_loss": no_loss})
    return rows


@app.post("/contratacion/simulaciones/crear", endpoint="simulation_create")
@admin_required
def simulation_create():
    if not can_edit_simulations():
        flash("No tienes permisos para crear simulaciones.", "warning")
        return redirect(url_for("contracting_view", section="simulaciones"))
    s = db()
    try:
        # Sujeto de la simulación: un ARTISTA o un EVENTO (uno de los dos).
        artist_id = _sim_safe_uuid(request.form.get("artist_id"))
        event_id = _sim_safe_uuid(request.form.get("event_id"))
        subject_kind = (request.form.get("subject_kind") or ("EVENT" if (event_id and not artist_id) else "ARTIST")).strip().upper()
        if subject_kind == "EVENT":
            artist_id = None
            if not event_id or not s.get(AppEvent, event_id):
                flash("Debes seleccionar (o crear) un evento para la simulación.", "warning")
                return redirect(url_for("contracting_view", section="simulaciones"))
        else:
            event_id = None
            if not artist_id or not s.get(Artist, artist_id):
                flash("Debes seleccionar un artista para la simulación.", "warning")
                return redirect(url_for("contracting_view", section="simulaciones"))
        kind = (request.form.get("kind") or "CONCERT").strip().upper()
        if kind not in ("CONCERT", "TOUR", "CYCLE", "FESTIVAL", "EVENT"):
            kind = "CONCERT"
        sim = Simulation(
            artist_id=artist_id,
            event_id=event_id,
            managing_company_id=_sim_safe_uuid(request.form.get("managing_company_id")),
            kind=kind,
            status="ACTIVE",
            title=(request.form.get("title") or "").strip() or None,
            created_by_user_id=_sim_safe_uuid(session.get("user_id")),
        )
        s.add(sim)
        s.flush()  # asegura sim.id

        # Primera actividad (fecha + recinto). En gira se añaden más desde la ficha.
        date_unknown = _truthy(request.form.get("date_unknown"))
        venue_unknown = _truthy(request.form.get("venue_unknown"))
        venue_id = None if venue_unknown else _sim_safe_uuid(request.form.get("venue_id"))
        label = (request.form.get("activity_label") or "").strip() or None
        if not label and venue_id and kind in ("TOUR", "CYCLE"):
            # Con más de una fecha, el nombre por defecto es el municipio del recinto.
            _v = s.get(Venue, venue_id)
            label = ((_v.municipality or "").strip() or None) if _v else None
        act = SimulationActivity(
            simulation_id=sim.id,
            sort_order=0,
            label=label,
            event_date=None if date_unknown else _sim_parse_date(request.form.get("event_date")),
            date_unknown=date_unknown,
            venue_id=venue_id,
            venue_unknown=venue_unknown,
        )
        if kind == "CYCLE":
            act.artist_id = artist_id  # la primera fecha del ciclo es de este artista (si hay artista)
        s.add(act)

        # NOTA: la plantilla de ticketing del recinto ya NO se autocarga: al abrir la pestaña
        # Ticketing se ofrece aplicarla (aviso «¿quieres aplicarla?»).

        if kind in ("CYCLE", "TOUR"):
            # Contenedor de gastos generales del ciclo/gira (sin ticketing ni artista): se prorratean
            # entre las fechas mediante la categoría PRORRATEO.
            s.add(SimulationActivity(simulation_id=sim.id, sort_order=9999, is_shared=True, label="Gastos generales"))
        if kind == "FESTIVAL" and artist_id:
            # El artista principal entra en el lineup del festival.
            s.add(SimulationArtist(simulation_id=sim.id, artist_id=artist_id, sort_order=0))

        for idx, pr in enumerate(_simulation_partners_from_form(request.form)):
            s.add(SimulationPartner(
                simulation_id=sim.id,
                company_id=pr["company_id"],
                promoter_id=pr["promoter_id"],
                name=pr["name"],
                pct=pr["pct"],
                no_loss=bool(pr.get("no_loss")),
                sort_order=idx,
            ))
        s.commit()
        flash("Simulación creada.", "success")
        return redirect(url_for("simulation_detail_view", sid=sim.id))
    except Exception as e:
        s.rollback()
        flash(f"Error creando la simulación: {e}", "danger")
        return redirect(url_for("contracting_view", section="simulaciones"))
    finally:
        s.close()


@app.get("/contratacion/simulaciones/<sid>", endpoint="simulation_detail_view")
@admin_required
def simulation_detail_view(sid):
    s = db()
    try:
        sim = (
            s.query(Simulation)
            .options(
                joinedload(Simulation.artist),
                joinedload(Simulation.event),
                joinedload(Simulation.managing_company),
                selectinload(Simulation.activities).joinedload(SimulationActivity.venue),
                selectinload(Simulation.activities).joinedload(SimulationActivity.artist),
                selectinload(Simulation.activities)
                    .selectinload(SimulationActivity.ticket_categories)
                    .selectinload(SimulationTicketCategory.extras),
                selectinload(Simulation.activities).selectinload(SimulationActivity.caches),
                selectinload(Simulation.activities).selectinload(SimulationActivity.commissions).joinedload(SimulationCommission.promoter),
                selectinload(Simulation.activities).selectinload(SimulationActivity.commissions).joinedload(SimulationCommission.media_outlet),
                selectinload(Simulation.activities).selectinload(SimulationActivity.production_items),
                selectinload(Simulation.activities).selectinload(SimulationActivity.income_items),
                selectinload(Simulation.partners).joinedload(SimulationPartner.company),
                selectinload(Simulation.partners).joinedload(SimulationPartner.promoter),
            )
            .filter(Simulation.id == _sim_safe_uuid(sid))
            .first()
        )
        if not sim:
            flash("Simulación no encontrada.", "warning")
            return redirect(url_for("contracting_view", section="simulaciones"))
        return _simulation_detail_response(s, sim)
    finally:
        s.close()


def _simulation_detail_response(s, sim, public=False, public_token=""):
    """Renderiza la ficha COMPLETA de una simulación (pestañas, fechas, módulos).
    Con public=True es el ENLACE COMPARTIDO (solo visualización): sin edición, con base
    layout_public, URLs de navegación por token (PUBLIC_VIEW/PUBLIC_TOKEN en la plantilla)
    y sin ingresos a 0 / omitidos / no aplican. No cierra la sesión: eso es del caller."""
    tab = (request.args.get("tab") or "resumen").strip().lower()
    if tab not in ("resumen", "ticketing", "ingresos", "gastos", "resultado", "socios"):
        tab = "resumen"
    all_activities = sorted(sim.activities or [], key=lambda a: a.sort_order or 0)
    kind = (sim.kind or "").upper()
    is_tour = kind == "TOUR"
    is_cycle = kind == "CYCLE"
    is_festival = kind == "FESTIVAL"
    is_multi = is_tour or is_cycle           # navegación por actividades (fechas/conciertos)
    shared_activity = next((a for a in all_activities if a.is_shared), None)
    # Gira/ciclo sin contenedor de gastos generales (creadas antes de esta función): se crea aquí.
    if is_multi and shared_activity is None and not public:
        try:
            shared_activity = SimulationActivity(simulation_id=sim.id, sort_order=9999, is_shared=True, label="Gastos generales")
            s.add(shared_activity)
            s.commit()
            all_activities = sorted(sim.activities or [], key=lambda a: a.sort_order or 0)
        except Exception:
            s.rollback()
            shared_activity = next((a for a in all_activities if a.is_shared), None)
    activities = [a for a in all_activities if not a.is_shared]   # fechas/conciertos (o el evento)
    lineup = sorted(sim.lineup or [], key=lambda x: x.sort_order or 0)
    all_artists = s.query(Artist).order_by(Artist.name.asc()).all() if (is_multi or is_festival) else []
    artist_intl_map = {str(a.id): bool(a.is_international) for a in all_artists}
    festival_artists = [{"id": str(la.artist_id), "name": (la.artist.name if la.artist else "")} for la in lineup] if is_festival else []
    act_param = (request.args.get("act") or "").strip()
    if is_multi:
        active_activity = next((a for a in activities if str(a.id) == act_param), None)
        if active_activity is None and shared_activity is not None and act_param == str(shared_activity.id):
            active_activity = shared_activity   # abrir el contenedor de "Generales"
    else:
        active_activity = activities[0] if activities else None
    show_general = is_multi and active_activity is None

    # Gastos generales del ciclo/gira (fijos, repartidos entre las fechas mediante la categoría
    # PRORRATEO en cada fecha). El total de la gira es la SUMA de las fechas (el prorrateo ya
    # está dentro del cálculo de cada una), así no se duplica.
    general_net = 0.0
    if is_multi and shared_activity is not None:
        general_net = sim_calc.compute(_sim_build_calc_data(sim, shared_activity, artist_intl_map))["at_100"]["gastos"]["total"]
    general_share = (general_net / (len(activities) or 1)) if (is_multi and activities) else 0.0

    tour_rows = []
    tour_totals = None
    tour_points = []
    partner_module_payload = None
    tour_series = []
    if show_general:
        ti = tg = tr = 0.0
        tsell = 0
        gen_acts = []
        series_acc = {}  # pct -> {ingresos, gastos, resultado} agregado de todas las fechas
        for idx, a in enumerate(activities, start=1):
            c = sim_calc.compute(_sim_build_calc_data(sim, a, artist_intl_map, prorateo=general_share))
            ing = c["at_100"]["ingresos"]["total"]
            gas = c["at_100"]["gastos"]["total"]   # ya incluye el prorrateo
            row_label = a.label or (("Concierto " if is_cycle else "Fecha ") + str(idx))
            tour_rows.append({
                "activity": a, "calc": c, "ingresos": ing, "gastos": gas, "resultado": ing - gas,
                "n": idx,
            })
            ti += ing; tg += gas; tr += (ing - gas)
            tsell += c["ticketing"]["sellable"]
            gen_acts.append(_sim_partner_module_payload(sim, a, c, label=row_label))
            # Serie agregada (mismo % de venta en todas las fechas) para la tabla general.
            for pt in (c.get("series") or []):
                acc = series_acc.setdefault(pt["pct"], {"tickets": 0, "ingresos": 0.0, "gastos": 0.0, "resultado": 0.0})
                acc["tickets"] += pt["tickets"]
                acc["ingresos"] += pt["ingresos"]
                acc["gastos"] += pt["gastos"]
                acc["resultado"] += pt["resultado"]
        tour_totals = {"ingresos": ti, "gastos": tg, "resultado": tr, "sellable": tsell, "general": general_net}
        partner_module_payload = {"mode": "general", "activities": gen_acts, "labels": SIM_EXPENSE_CATEGORY_LABELS}
        tour_series = [
            {"pct": pct, "tickets": v["tickets"], "ingresos": round(v["ingresos"], 2), "gastos": round(v["gastos"], 2), "resultado": round(v["resultado"], 2)}
            for pct, v in sorted(series_acc.items())
        ]
        # Chinchetas del mapa numeradas por ORDEN DE FECHA (fechas sin definir al final).
        dated = sorted(
            tour_rows,
            key=lambda r: (r["activity"].date_unknown or not r["activity"].event_date,
                           r["activity"].event_date or date.max,
                           r["activity"].sort_order or 0),
        )
        n = 0
        for r in dated:
            v = r["activity"].venue
            if v and (v.municipality or "").strip():
                n += 1
                tour_points.append({
                    "n": n, "name": (v.name or ""),
                    "city": (v.municipality or "").strip(), "province": (v.province or "").strip(),
                    "date": (r["activity"].event_date.strftime("%d/%m/%Y") if (r["activity"].event_date and not r["activity"].date_unknown) else ""),
                })
    # Mapa también en el RESUMEN de una fecha individual: un único pin con su recinto.
    if not show_general and active_activity is not None and not active_activity.is_shared:
        _v = active_activity.venue
        if _v and (_v.municipality or "").strip():
            tour_points.append({
                "n": 1, "name": _v.name or "",
                "city": (_v.municipality or "").strip(), "province": (_v.province or "").strip(),
                "date": (active_activity.event_date.strftime("%d/%m/%Y") if (active_activity.event_date and not active_activity.date_unknown) else ""),
            })
    summary = _sim_ticketing_summary(active_activity) if active_activity else None
    ticketing_payload = _sim_ticketing_payload(active_activity) if active_activity else []
    # En una fecha concreta (no el contenedor de generales) se aplica el prorrateo.
    _act_prorateo = general_share if (active_activity is not None and not active_activity.is_shared) else 0.0
    calc = sim_calc.compute(_sim_build_calc_data(sim, active_activity, artist_intl_map, prorateo=_act_prorateo)) if active_activity else None
    artist_breakdown = _sim_festival_breakdown(active_activity, calc, artist_intl_map, lineup) if is_festival else None
    if active_activity is not None and calc and not active_activity.is_shared:
        partner_module_payload = {
            "mode": "activity",
            "activities": [_sim_partner_module_payload(sim, active_activity, calc)],
            "labels": SIM_EXPENSE_CATEGORY_LABELS,
        }
    venue_tpl = []
    if active_activity and active_activity.venue_id:
        # Si el recinto tiene MAPA DE BUTACAS con reparto por categorías, la plantilla que se
        # ofrece sale del mapa (seatmap_calc: conteos reales por categoría y zona). Si no,
        # se ofrece el ticketing clásico del recinto (VenueTicketCategory), como siempre.
        try:
            _sm = _venue_seatmap_default(s, active_activity.venue_id)
            if _sm and (_sm.layout_json or {}).get("sections"):
                venue_tpl = seatmap_calc.ticketing_template(_sm.layout_json or {}, _sm.assignments_json or {})
        except Exception:
            venue_tpl = []
        if not venue_tpl:
            # Ticketing clásico del FORMATO PRINCIPAL del recinto (subpestañas de la ficha).
            _vtc = _venue_ticket_categories_for(s, active_activity.venue_id, _venue_seatmap_default(s, active_activity.venue_id))
            venue_tpl = _venue_ticketing_payload(_vtc)
    expenses_payload = _sim_expenses_payload(active_activity)

    # Retención del 24%: solo tiene sentido con artista extranjero (por actividad).
    if is_festival:
        retention_relevant = any(artist_intl_map.get(str(la.artist_id), False) for la in lineup)
    elif active_activity is not None and active_activity.artist_id:
        retention_relevant = artist_intl_map.get(str(active_activity.artist_id), bool(sim.artist and sim.artist.is_international))
    else:
        retention_relevant = bool(sim.artist and sim.artist.is_international)

    # Ingresos: estado actual de omitidos/no aplica (líneas calculadas).
    income_overrides = {}
    if active_activity is not None:
        try:
            income_overrides = dict((active_activity.settings or {}).get("income_overrides") or {})
        except Exception:
            income_overrides = {}

    # Plantillas de gastos aplicables (recinto / artista / evento) + aviso de primera vez.
    expense_templates_payload = _sim_expense_templates_payload(s, sim, active_activity) if active_activity else []
    show_expense_tpl_prompt = bool(
        tab == "gastos" and active_activity is not None and expense_templates_payload
        and not (active_activity.production_items or [])
    )
    show_venue_tpl_prompt = bool(
        tab == "ticketing" and active_activity is not None and venue_tpl
        and not (active_activity.ticket_categories or [])
    )

    subject = _sim_subject(sim)
    global_partners = _sim_global_partners(sim)
    activity_partners_own = []
    if active_activity is not None:
        activity_partners_own = [
            p for p in sorted(sim.partners or [], key=lambda x: x.sort_order or 0)
            if p.activity_id and str(p.activity_id) == str(active_activity.id)
        ]
    effective_partners = _sim_partners_for_activity(sim, active_activity) if active_activity else global_partners

    return render_template(
        "simulacion_detail.html",
        sim=sim,
        sim_archived=((sim.status or "").strip().upper() == "ARCHIVED"),
        converted_info=(None if public else _simulation_converted_info(s, sim)),
        subject=subject,
        activities=activities,
        active_activity=active_activity,
        is_tour=is_tour,
        is_cycle=is_cycle,
        is_festival=is_festival,
        is_multi=is_multi,
        shared_activity=shared_activity,
        lineup=lineup,
        all_artists=all_artists,
        festival_artists=festival_artists,
        artist_breakdown=artist_breakdown,
        show_general=show_general,
        tour_rows=tour_rows,
        tour_totals=tour_totals,
        tour_points=tour_points,
        tour_series=tour_series,
        tab=tab,
        summary=summary,
        ticketing_payload=ticketing_payload,
        calc=calc,
        tax_cfg=(_sim_tax_cfg(active_activity) if active_activity else _sim_tax_cfg(None)),
        venue_tpl=venue_tpl,
        show_venue_tpl_prompt=show_venue_tpl_prompt,
        expenses_payload=expenses_payload,
        expense_templates_payload=expense_templates_payload,
        show_expense_tpl_prompt=show_expense_tpl_prompt,
        retention_relevant=retention_relevant,
        income_overrides=income_overrides,
        general_share=general_share,
        partner_module_payload=partner_module_payload,
        global_partners=global_partners,
        activity_partners_own=activity_partners_own,
        effective_partners=effective_partners,
        group_companies=s.query(GroupCompany).order_by(GroupCompany.name.asc()).all(),
        edit_artists=s.query(Artist).order_by(Artist.name.asc()).all(),
        public_link=("" if public else (_external_url_for("public_simulation_view", token=_simulation_ensure_public_token(s, sim)) if can_edit_simulations() else "")),
        CAN_EDIT=(False if public else can_edit_simulations()),
        PUBLIC_VIEW=public,
        PUBLIC_TOKEN=public_token,
        og=(_simulation_share_meta(sim) if public else None),
    )


@app.get("/contratacion/simulaciones/<sid>/imprimir", endpoint="simulation_print")
@admin_required
def simulation_print(sid):
    s = db()
    try:
        sim = (
            s.query(Simulation)
            .options(
                joinedload(Simulation.artist),
                joinedload(Simulation.event),
                joinedload(Simulation.managing_company),
                selectinload(Simulation.activities).joinedload(SimulationActivity.venue),
                selectinload(Simulation.activities).joinedload(SimulationActivity.artist),
                selectinload(Simulation.activities).selectinload(SimulationActivity.ticket_categories).selectinload(SimulationTicketCategory.extras),
                selectinload(Simulation.activities).selectinload(SimulationActivity.caches),
                selectinload(Simulation.activities).selectinload(SimulationActivity.commissions),
                selectinload(Simulation.activities).selectinload(SimulationActivity.production_items),
                selectinload(Simulation.activities).selectinload(SimulationActivity.income_items),
                selectinload(Simulation.partners).joinedload(SimulationPartner.company),
                selectinload(Simulation.partners).joinedload(SimulationPartner.promoter),
                selectinload(Simulation.lineup).joinedload(SimulationArtist.artist),
            )
            .filter(Simulation.id == _sim_safe_uuid(sid))
            .first()
        )
        if not sim:
            flash("Simulación no encontrada.", "warning")
            return redirect(url_for("contracting_view", section="simulaciones"))
        return render_template("simulacion_print.html", public=False, **_simulation_print_context(s, sim))
    finally:
        s.close()


def _simulation_share_meta(sim):
    """Metadatos para compartir una simulación por WhatsApp/correo (previsualización social del
    enlace público y cabecera del correo). Se comparten para que el enlace y el correo se vean igual.
    - imagen: el CARTEL PRINCIPAL (`poster_url`) si lo hay; si no, la foto del artista o el logo del
      evento; en último término el logo corporativo (así SIEMPRE hay imagen de previsualización).
      Para el og:image se usa `public_simulation_og_image` (JPEG 1200×630 servido desde nuestro
      dominio): WhatsApp descarta imágenes grandes, sin content-type de imagen o sin dimensiones,
      y al fallar la imagen colapsa la tarjeta a solo título+dominio (sin descripción).
    - descripción secundaria: si hay VARIAS fechas, el número de eventos; si es UNA sola, la fecha y
      el recinto."""
    subject = _sim_subject(sim)
    kind_label = {"CONCERT": "Concierto", "TOUR": "Gira", "CYCLE": "Ciclo", "FESTIVAL": "Festival",
                 "EVENT": "Evento"}.get((sim.kind or "").upper(), "Concierto")
    image_src = (sim.poster_url or "").strip() or (subject.get("photo") or "").strip() or url_for("static", filename="img/logo_33_producciones.png")
    image_raw = _absolute_media_url(image_src)
    if sim.public_token:
        image = _external_url_for("public_simulation_og_image", token=sim.public_token)
        image_processed = True
        share_url = _external_url_for("public_simulation_view", token=sim.public_token)
    else:
        image, image_processed, share_url = image_raw, False, ""
    activities = [a for a in (sim.activities or []) if not a.is_shared]
    # Descripción (línea bajo el título): nº de fechas si hay varias; con UNA sola, el municipio
    # (o el nombre del festival, si lo hay) y la fecha.
    if len(activities) > 1:
        desc = f"{len(activities)} fechas"
    elif activities:
        a0 = activities[0]
        parts = []
        is_festival = (sim.kind or "").upper() == "FESTIVAL"
        v0 = a0.venue
        place = ""
        if is_festival and (sim.title or "").strip():
            place = sim.title.strip()
        elif v0 and not a0.venue_unknown:
            place = (v0.municipality or "").strip() or (v0.name or "").strip()
        if place:
            parts.append(place)
        if a0.event_date and not a0.date_unknown:
            parts.append(a0.event_date.strftime("%d/%m/%Y"))
        desc = " · ".join(parts) or kind_label
    else:
        desc = kind_label
    return {"title": f"Simulación - {sim.title or subject['name'] or 'Sin título'}", "description": desc,
            "image": image, "image_raw": image_raw, "image_processed": image_processed,
            "url": share_url, "kind_label": kind_label, "subject": subject}


def _simulation_print_context(s, sim):
    """Contexto de solo lectura (PDF / enlace público): bloques por fecha, totales y prorrateo.
    Compartido por el PDF interno y la vista pública. Incluye los MISMOS módulos que las pestañas
    del detalle: serie por % de aforo (tabla con barras), socios (beneficio/riesgo), ticketing por
    categorías, ingresos con omitidos y gastos por categorías."""
    all_activities = sorted(sim.activities or [], key=lambda a: a.sort_order or 0)
    kind = (sim.kind or "").upper()
    is_cycle = kind == "CYCLE"
    is_festival = kind == "FESTIVAL"
    is_multi = kind in ("TOUR", "CYCLE")
    shared_activity = next((a for a in all_activities if a.is_shared), None)
    activities = [a for a in all_activities if not a.is_shared]
    all_artists = s.query(Artist).all() if (is_multi or is_festival) else []
    artist_intl_map = {str(a.id): bool(a.is_international) for a in all_artists}
    general_net = 0.0
    if is_multi and shared_activity is not None:
        general_net = sim_calc.compute(_sim_build_calc_data(sim, shared_activity, artist_intl_map))["at_100"]["gastos"]["total"]
    general_share = (general_net / (len(activities) or 1)) if (is_multi and activities) else 0.0
    blocks = [{"activity": a, "calc": sim_calc.compute(_sim_build_calc_data(sim, a, artist_intl_map, prorateo=general_share))} for a in activities]
    totals = {"ingresos": 0.0, "gastos": 0.0, "resultado": 0.0, "sellable": 0, "general": general_net}
    series_acc = {}
    partner_acts = []
    for idx, b in enumerate(blocks, start=1):
        a = b["activity"]
        ing = b["calc"]["at_100"]["ingresos"]["total"]
        gas = b["calc"]["at_100"]["gastos"]["total"]
        b["ingresos"] = ing; b["gastos"] = gas; b["resultado"] = ing - gas
        totals["ingresos"] += ing; totals["gastos"] += gas; totals["resultado"] += (ing - gas)
        totals["sellable"] += b["calc"]["ticketing"]["sellable"]
        # Igual que en las pestañas: líneas de ingresos omitidas/no aplican de esta fecha.
        try:
            b["income_overrides"] = dict((a.settings or {}).get("income_overrides") or {})
        except Exception:
            b["income_overrides"] = {}
        row_label = a.label or (("Concierto " if is_cycle else "Fecha ") + str(idx))
        _pp = _sim_partner_module_payload(sim, a, b["calc"], label=row_label)
        partner_acts.append(_pp)
        # Socios de la propia fecha (tabla estática en su hoja).
        b["partners_summary"] = _sim_partner_print_summary([_pp]) if _pp.get("partners") else None
        # Serie agregada (mismo % de venta en todas las fechas) para la tabla general.
        for pt in (b["calc"].get("series") or []):
            acc = series_acc.setdefault(pt["pct"], {"tickets": 0, "ingresos": 0.0, "gastos": 0.0, "resultado": 0.0})
            acc["tickets"] += pt["tickets"]; acc["ingresos"] += pt["ingresos"]
            acc["gastos"] += pt["gastos"]; acc["resultado"] += pt["resultado"]
    tour_series = [
        {"pct": pct, "tickets": v["tickets"], "ingresos": round(v["ingresos"], 2), "gastos": round(v["gastos"], 2), "resultado": round(v["resultado"], 2)}
        for pct, v in sorted(series_acc.items())
    ] if is_multi else []
    partners_summary = _sim_partner_print_summary(partner_acts)
    # Chinchetas del mapa (solo PDF interno: el geocoding requiere sesión), por orden de fecha.
    tour_points = []
    if is_multi:
        dated = sorted(
            blocks,
            key=lambda b: (b["activity"].date_unknown or not b["activity"].event_date,
                           b["activity"].event_date or date.max,
                           b["activity"].sort_order or 0),
        )
        n = 0
        for r in dated:
            v = r["activity"].venue
            if v and (v.municipality or "").strip():
                n += 1
                tour_points.append({
                    "n": n, "name": (v.name or ""),
                    "city": (v.municipality or "").strip(), "province": (v.province or "").strip(),
                    "date": (r["activity"].event_date.strftime("%d/%m/%Y") if (r["activity"].event_date and not r["activity"].date_unknown) else ""),
                })
    kind_label = {"CONCERT": "Concierto", "TOUR": "Gira", "CYCLE": "Ciclo", "FESTIVAL": "Festival",
                 "EVENT": "Evento"}.get(kind, "Concierto")
    lineup_sorted = sorted(sim.lineup or [], key=lambda x: x.sort_order or 0)
    festival_breakdown = _sim_festival_breakdown(activities[0], blocks[0]["calc"], artist_intl_map, lineup_sorted) if (is_festival and blocks) else None
    # ¿Hay nombres de fecha en la gira? Si no, la tabla de resumen no pinta una columna vacía.
    has_row_labels = any((getattr(b["activity"], "label", "") or "").strip() for b in blocks)
    # Resumen AGREGADO de ingresos y gastos (multi-fecha): mismos conceptos que las tablas por hoja,
    # sumando todas las fechas y respetando los «omitidos/no aplican» por línea de ingresos.
    summary_income = {"ticketing": 0.0, "complementos": 0.0, "rebate": 0.0, "barras": 0.0,
                      "incentivos": 0.0, "subvenciones": 0.0, "patrocinios": 0.0, "total": 0.0}
    summary_expense = {"caches": 0.0, "retenciones": 0.0, "comisiones": 0.0, "total": 0.0}
    summary_expense_cat = {}
    if is_multi:
        for b in blocks:
            ing = b["calc"]["at_100"]["ingresos"]
            ov = b.get("income_overrides") or {}
            for key in ("ticketing", "complementos", "rebate", "barras", "incentivos", "subvenciones", "patrocinios"):
                if (ov.get(key) or "").upper() not in ("OMIT", "NA"):
                    summary_income[key] += ing.get(key) or 0.0
            summary_income["total"] += ing.get("total") or 0.0
            g = b["calc"]["at_100"]["gastos"]
            summary_expense["caches"] += g.get("caches") or 0.0
            summary_expense["retenciones"] += g.get("retenciones") or 0.0
            summary_expense["comisiones"] += g.get("comisiones") or 0.0
            summary_expense["total"] += g.get("total") or 0.0
            for ck, cv in (g.get("produccion_por_categoria") or {}).items():
                summary_expense_cat[ck] = summary_expense_cat.get(ck, 0.0) + (cv or 0.0)
    return dict(
        sim=sim, subject=_sim_subject(sim), kind=kind, kind_label=kind_label,
        is_multi=is_multi, is_cycle=is_cycle, is_festival=is_festival,
        blocks=blocks, totals=totals, general_net=general_net, general_share=general_share,
        tour_series=tour_series, partners_summary=partners_summary, tour_points=tour_points,
        lineup=lineup_sorted, festival_breakdown=festival_breakdown, has_row_labels=has_row_labels,
        summary_income=summary_income, summary_expense=summary_expense, summary_expense_cat=summary_expense_cat,
        bag_labels=dict(BAG_EXPENSE_CATEGORIES), company=sim.managing_company,
        og=_simulation_share_meta(sim),
    )


def _sim_partner_print_summary(partner_acts, pct=100):
    """Versión ESTÁTICA (para el PDF y el enlace público) del módulo de socios de sim_partners.js:
    agrega las fechas del payload y reparte beneficio (resultado × % del socio) y riesgo (gastos;
    los «no soporta pérdidas» no asumen gasto y su parte se reparte entre el resto proporcional a
    su %). Devuelve filas por socio + totales y punto de empate agregado, al pct dado (100%)."""
    acts = [a for a in (partner_acts or []) if a and (a.get("series") or [])]
    if not acts:
        return None
    agg = []
    for p in range(0, 101):
        t = {"pct": p, "tickets": 0, "ingresos": 0.0, "gastos": 0.0, "resultado": 0.0}
        for a in acts:
            serie = a["series"]
            pt = serie[p] if p < len(serie) else serie[-1]
            t["tickets"] += pt["tickets"]; t["ingresos"] += pt["ingresos"]
            t["gastos"] += pt["gastos"]; t["resultado"] += pt["resultado"]
        agg.append(t)
    be = next((x for x in agg if x["resultado"] >= 0), None)
    order = []
    rows = {}
    for a in acts:
        for pr in (a.get("partners") or []):
            k = pr.get("company_id") or pr.get("promoter_id") or ("label:" + (pr.get("label") or pr.get("name") or ""))
            if k not in rows:
                rows[k] = {"name": pr.get("name") or "Socio", "logo": pr.get("logo") or "", "beneficio": 0.0, "riesgo": 0.0, "pcts": []}
                order.append(k)
    for a in acts:
        serie = a["series"]
        pt = serie[pct] if pct < len(serie) else serie[-1]
        loss_pct_sum = sum((float(pr.get("pct") or 0)) for pr in (a.get("partners") or []) if not pr.get("no_loss"))
        for pr in (a.get("partners") or []):
            k = pr.get("company_id") or pr.get("promoter_id") or ("label:" + (pr.get("label") or pr.get("name") or ""))
            p2 = float(pr.get("pct") or 0)
            rows[k]["beneficio"] += pt["resultado"] * (p2 / 100.0)
            if pr.get("no_loss"):
                pass
            elif loss_pct_sum > 0:
                rows[k]["riesgo"] += pt["gastos"] * (p2 / loss_pct_sum)
            else:
                rows[k]["riesgo"] += pt["gastos"] * (p2 / 100.0)
            _p2s = ("%g" % p2)   # 50.0 → "50" (como el módulo JS)
            if _p2s not in rows[k]["pcts"]:
                rows[k]["pcts"].append(_p2s)
    at = agg[pct if pct < len(agg) else -1]
    return {
        "rows": [rows[k] for k in order],
        "at": at,
        "sellable": sum(int(a.get("sellable") or 0) for a in acts),
        "break_even_pct": (be["pct"] if be else None),
        "break_even_tickets": (be["tickets"] if be else None),
    }


def _simulation_public_load(s, token):
    """Carga completa de una simulación por su token público (para la vista de solo lectura)."""
    return (
        s.query(Simulation)
        .options(
            joinedload(Simulation.artist), joinedload(Simulation.event), joinedload(Simulation.managing_company),
            selectinload(Simulation.activities).joinedload(SimulationActivity.venue),
            selectinload(Simulation.activities).joinedload(SimulationActivity.artist),
            selectinload(Simulation.activities).selectinload(SimulationActivity.ticket_categories).selectinload(SimulationTicketCategory.extras),
            selectinload(Simulation.activities).selectinload(SimulationActivity.caches),
            selectinload(Simulation.activities).selectinload(SimulationActivity.commissions).joinedload(SimulationCommission.promoter),
            selectinload(Simulation.activities).selectinload(SimulationActivity.commissions).joinedload(SimulationCommission.media_outlet),
            selectinload(Simulation.activities).selectinload(SimulationActivity.production_items),
            selectinload(Simulation.activities).selectinload(SimulationActivity.income_items),
            selectinload(Simulation.partners).joinedload(SimulationPartner.company),
            selectinload(Simulation.partners).joinedload(SimulationPartner.promoter),
            selectinload(Simulation.lineup).joinedload(SimulationArtist.artist),
        )
        .filter(Simulation.public_token == token)
        .first()
    )


def _promoter_email_addresses(s, promoter_id):
    """Correos de un tercero (principal + emails vinculados) para compartir a socios."""
    out = []
    try:
        p = s.get(Promoter, to_uuid(promoter_id))
        if not p:
            return out
        if getattr(p, "contact_email", None):
            out.append(p.contact_email)
        for e in s.query(PromoterEmail).filter(PromoterEmail.promoter_id == p.id).all():
            if getattr(e, "email", None):
                out.append(e.email)
    except Exception:
        pass
    return out


def _simulation_email_body(s, sim, link):
    """Correo de compartir simulación: resumen breve + botón «Ver datos completos» al enlace público.
    Los gráficos y el detalle viven en la página pública (el correo no ejecuta JS)."""
    meta = _simulation_share_meta(sim)
    subj = meta["subject"]
    kind_label = meta["kind_label"]
    logo = _invitation_event_logo_url(s, None, external=True)
    esc = html.escape
    # Imagen de cabecera: cartel principal si lo hay, si no la foto del artista / logo del evento.
    # La versión SIN procesar (cuadrada): la og es 1200×630 y en un avatar redondo se vería mal.
    photo = meta.get("image_raw") or meta["image"]
    subject = f"Simulación · {subj['name']} ({kind_label})"
    photo_html = (f'<img src="{esc(photo)}" width="56" height="56" style="width:56px;height:56px;border-radius:50%;object-fit:cover;border:1px solid #eceef1;vertical-align:middle;margin-right:10px">' if photo else '')
    # Línea secundaria: nº de fechas (varias) o fecha + recinto (una sola).
    sub_line = meta["description"] or f"Simulación · {kind_label}"
    body = (
        f'<div style="font-family:Arial,sans-serif;color:#111;line-height:1.45;max-width:640px;margin:0 auto">'
        f'<div style="text-align:right;margin-bottom:6px"><img src="{esc(logo)}" style="max-height:52px;max-width:180px" alt=""></div>'
        f'<div style="background:#f6f7f9;border:1px solid #eceef1;border-radius:14px;padding:14px 16px;margin:8px 0 16px">'
        f'{photo_html}<span style="font-size:17px;font-weight:700">{esc(meta["title"])}</span>'
        f'<div style="font-size:13px;color:#555;margin-top:2px">{esc(sub_line)}</div></div>'
        f'<p>Te comparto el resumen de esta simulación. Pulsa el botón para ver todos los datos y gráficos.</p>'
        f'<p style="text-align:center;margin:18px 0"><a href="{esc(link)}" style="background:#E33D48;color:#fff;text-decoration:none;padding:11px 20px;border-radius:10px;font-weight:700;display:inline-block">Ver datos completos</a></p>'
        f'<p style="font-size:12px;color:#888">Si el botón no funciona, copia este enlace: {esc(link)}</p>'
        f'</div>'
    )
    text = f"Simulación {subj['name']} ({kind_label}). Ver datos completos: {link}"
    return subject, body, text


def _simulation_ensure_public_token(s, sim):
    if not sim.public_token:
        sim.public_token = _invitation_token()
        s.commit()
    return sim.public_token


