# Miniaturas og:image ya procesadas, por token de simulación: {token: (src, bytes)}.
_SIM_OG_IMAGE_CACHE: dict = {}


def _og_image_jpeg_bytes(source_url: str) -> bytes | None:
    """Normaliza una imagen a tarjeta OG: JPEG 1200×630 (contain sobre blanco), <300 KB.
    Los previsualizadores (WhatsApp sobre todo) descartan og:image grandes o sin dimensiones."""
    if not PILLOW_AVAILABLE:
        return None
    try:
        rel = (source_url or "").strip()
        if rel.startswith("/static/"):
            with open(os.path.join(app.static_folder, rel[len("/static/"):]), "rb") as fh:
                data = fh.read()
        else:
            data, _ctype = _download_remote_content(rel, timeout=10)
        img = ImageOps.exif_transpose(PILImage.open(BytesIO(data)))
        if img.mode not in ("RGB", "L"):
            img = img.convert("RGB")
        img = ImageOps.contain(img, (1200, 630))
        canvas = PILImage.new("RGB", (1200, 630), (255, 255, 255))
        canvas.paste(img, ((1200 - img.width) // 2, (630 - img.height) // 2))
        out = BytesIO()
        canvas.save(out, format="JPEG", quality=85, optimize=True)
        return out.getvalue()
    except Exception:
        return None


@app.get("/simulaciones/ver/<token>/og.jpg", endpoint="public_simulation_og_image")
def public_simulation_og_image(token):
    """Imagen de previsualización (og:image) del enlace público de una simulación. Se sirve desde
    nuestro dominio y procesada (cartel → foto del artista / logo del evento → logo corporativo)."""
    s = db()
    try:
        sim = (s.query(Simulation)
               .options(joinedload(Simulation.artist), joinedload(Simulation.event))
               .filter(Simulation.public_token == token).first())
        if not sim:
            abort(404)
        src = ((sim.poster_url or "").strip()
               or (_sim_subject(sim).get("photo") or "").strip()
               or url_for("static", filename="img/logo_33_producciones.png"))
    finally:
        s.close()
    cached = _SIM_OG_IMAGE_CACHE.get(token)
    data = cached[1] if (cached and cached[0] == src) else None
    if data is None:
        data = _og_image_jpeg_bytes(src if src.startswith("/static/") else _absolute_media_url(src))
        if data:
            if len(_SIM_OG_IMAGE_CACHE) > 200:
                _SIM_OG_IMAGE_CACHE.clear()
            _SIM_OG_IMAGE_CACHE[token] = (src, data)
    if not data:
        return redirect(_absolute_media_url(src))
    resp = send_file(BytesIO(data), mimetype="image/jpeg")
    resp.headers["Cache-Control"] = "public, max-age=21600"
    return resp


# Miniaturas og:image de CONCIERTOS ya procesadas, por id: {cid: (src, bytes)}.
_CONCERT_OG_IMAGE_CACHE: dict = {}


@app.get("/og/concierto/<cid>.jpg", endpoint="public_concert_og_image")
def public_concert_og_image(cid):
    """Imagen de previsualización (og:image) de los enlaces públicos de un concierto: invitaciones
    por WhatsApp/SMS/correo, planos, hoja de ruta… Cartel principal → foto del artista → logo,
    normalizada a JPEG 1200×630 y servida desde nuestro dominio (mismo tratamiento que
    public_simulation_og_image: WhatsApp descarta imágenes grandes o sin dimensiones)."""
    s = db()
    try:
        concert = s.get(Concert, _safe_uuid(cid))
        if not concert:
            abort(404)
        src = _public_share_og_source(s, concert, logo=_invitation_event_logo_url(s, concert, external=True))
    finally:
        s.close()
    if not src:
        abort(404)
    key = str(cid)
    cached = _CONCERT_OG_IMAGE_CACHE.get(key)
    data = cached[1] if (cached and cached[0] == src) else None
    if data is None:
        data = _og_image_jpeg_bytes(src)
        if data:
            if len(_CONCERT_OG_IMAGE_CACHE) > 200:
                _CONCERT_OG_IMAGE_CACHE.clear()
            _CONCERT_OG_IMAGE_CACHE[key] = (src, data)
    if not data:
        return redirect(src)
    resp = send_file(BytesIO(data), mimetype="image/jpeg")
    resp.headers["Cache-Control"] = "public, max-age=21600"
    return resp


@app.post("/contratacion/simulaciones/<sid>/compartir", endpoint="simulation_share")
@admin_required
def simulation_share(sid):
    """Comparte la simulación: por correo (a destinatarios o a todos los socios). WhatsApp/SMS se
    resuelven en el cliente con el enlace público. Devuelve JSON para el modal de vista previa."""
    if not can_edit_simulations():
        return jsonify({"ok": False, "error": "Sin permiso."}), 403
    s = db()
    try:
        sim = s.query(Simulation).options(
            selectinload(Simulation.partners).joinedload(SimulationPartner.promoter)
        ).filter(Simulation.id == _sim_safe_uuid(sid)).first()
        if not sim:
            return jsonify({"ok": False, "error": "Simulación no encontrada."}), 404
        token = _simulation_ensure_public_token(s, sim)
        link = _external_url_for("public_simulation_view", token=token)
        target = (request.form.get("target") or "email").strip().lower()
        recipients = []
        if target == "partners":
            for p in (sim.partners or []):
                if p.promoter_id:
                    recipients += _promoter_email_addresses(s, p.promoter_id)
        recipients += request.form.getlist("recipients") + request.form.getlist("extra_emails")
        recipients = _dedupe_valid_email_addresses(recipients)
        if not recipients:
            return jsonify({"ok": False, "error": "No hay destinatarios con correo válido."}), 400
        subject, html_body, text_body = _simulation_email_body(s, sim, link)
        reply_to = _current_user_email()
        ok, err = _send_optional_email(recipients, subject, html_body, text_body=text_body, reply_to=reply_to)
        if ok:
            return jsonify({"ok": True, "recipients": recipients})
        return jsonify({"ok": False, "error": err or "No se pudo enviar el correo."}), 400
    except Exception as exc:
        s.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        s.close()


@app.post("/contratacion/simulaciones/<sid>/config", endpoint="simulation_config_update")
@admin_required
def simulation_config_update(sid):
    """Edita la configuración inicial del conjunto: título, empresa, tipo y sujeto (artista/evento)."""
    if not can_edit_simulations():
        flash("No tienes permisos para editar la simulación.", "warning")
        return redirect(url_for("simulation_detail_view", sid=sid))
    s = db()
    try:
        sim = s.get(Simulation, _sim_safe_uuid(sid))
        if not sim:
            flash("Simulación no encontrada.", "warning")
            return redirect(url_for("contracting_view", section="simulaciones"))
        sim.title = (request.form.get("title") or "").strip() or None
        sim.managing_company_id = _sim_safe_uuid(request.form.get("managing_company_id"))
        kind = (request.form.get("kind") or sim.kind or "CONCERT").strip().upper()
        if kind in ("CONCERT", "TOUR", "CYCLE", "FESTIVAL", "EVENT"):
            sim.kind = kind
        subject_kind = (request.form.get("subject_kind") or "").strip().upper()
        if subject_kind == "EVENT":
            eid = _sim_safe_uuid(request.form.get("event_id"))
            if eid and s.get(AppEvent, eid):
                sim.event_id = eid
                sim.artist_id = None
        elif subject_kind == "ARTIST":
            aid = _sim_safe_uuid(request.form.get("artist_id"))
            if aid and s.get(Artist, aid):
                sim.artist_id = aid
                sim.event_id = None
        sim.updated_at = datetime.utcnow()
        s.commit()
        flash("Configuración de la simulación actualizada.", "success")
    except Exception as e:
        s.rollback()
        flash(f"Error actualizando la simulación: {e}", "danger")
    finally:
        s.close()
    return redirect(url_for("simulation_detail_view", sid=sid))


@app.post("/contratacion/simulaciones/<sid>/fechas/<aid>/editar", endpoint="simulation_activity_update")
@admin_required
def simulation_activity_update(sid, aid):
    """Edita/renombra una fecha: label, fecha, recinto y (ciclo) artista."""
    if not can_edit_simulations():
        flash("No tienes permisos para editar la simulación.", "warning")
        return redirect(url_for("simulation_detail_view", sid=sid))
    s = db()
    try:
        act = s.get(SimulationActivity, _sim_safe_uuid(aid))
        if not act or str(act.simulation_id) != str(_sim_safe_uuid(sid)):
            flash("Fecha no encontrada.", "warning")
            return redirect(url_for("simulation_detail_view", sid=sid))
        # Renombrar (solo label) o edición completa según los campos presentes.
        if "activity_label" in request.form or "label" in request.form:
            act.label = (request.form.get("activity_label") or request.form.get("label") or "").strip() or None
        if "event_date" in request.form or request.form.get("date_unknown") is not None:
            date_unknown = _truthy(request.form.get("date_unknown"))
            act.date_unknown = date_unknown
            act.event_date = None if date_unknown else _sim_parse_date(request.form.get("event_date"))
        if "venue_id" in request.form or request.form.get("venue_unknown") is not None:
            venue_unknown = _truthy(request.form.get("venue_unknown"))
            act.venue_unknown = venue_unknown
            act.venue_id = None if venue_unknown else _sim_safe_uuid(request.form.get("venue_id"))
        if request.form.get("cycle_artist_id"):
            act.artist_id = _sim_safe_uuid(request.form.get("cycle_artist_id"))
        s.commit()
        flash("Fecha actualizada.", "success")
    except Exception as e:
        s.rollback()
        flash(f"Error actualizando la fecha: {e}", "danger")
    finally:
        s.close()
    return redirect(url_for("simulation_detail_view", sid=sid, act=aid, tab=(request.form.get("back_tab") or "resumen")))


