@app.route('/canales-venta/<token>', methods=['GET', 'POST'], endpoint='public_sale_channels')
def public_sale_channels(token):
    """Página PÚBLICA para que el promotor configure los canales de venta del evento:
    ticketera (catálogo con logos u otra nueva) + link de venta; puede añadir varias."""
    session = db()
    try:
        req = session.query(ConcertSaleChannelRequest).filter(ConcertSaleChannelRequest.public_token == (token or '').strip()).first()
        if not req:
            abort(404)
        concert = (
            session.query(Concert)
            .options(joinedload(Concert.artist), joinedload(Concert.venue), joinedload(Concert.billing_company),
                     selectinload(Concert.ticketers).joinedload(ConcertTicketer.ticketer))
            .filter(Concert.id == req.concert_id)
            .first()
        )
        if not concert:
            abort(404)
        if request.method == 'POST':
            ticketer_ids = request.form.getlist('channel_ticketer_id[]')
            other_names = request.form.getlist('channel_other_name[]')
            urls = request.form.getlist('channel_sale_url[]')
            saved = 0
            for i, url_raw in enumerate(urls or []):
                sale_url = (url_raw or '').strip()
                if not sale_url:
                    continue
                if not re.match(r'^https?://', sale_url, re.I):
                    sale_url = 'https://' + sale_url
                tid = to_uuid((ticketer_ids[i] if i < len(ticketer_ids) else '').strip() or None)
                if not tid:
                    t = _ensure_ticketer_by_name(session, other_names[i] if i < len(other_names) else '')
                    tid = t.id if t else None
                if not tid:
                    continue
                row = (session.query(ConcertTicketer)
                       .filter(ConcertTicketer.concert_id == concert.id, ConcertTicketer.ticketer_id == tid)
                       .first())
                if not row:
                    row = ConcertTicketer(concert_id=concert.id, ticketer_id=tid)
                    session.add(row)
                row.sale_url = sale_url
                saved += 1
            if saved:
                req.status = 'DONE'
                req.updated_at = datetime.now(ZoneInfo('Europe/Madrid'))
                session.commit()
                flash('¡Gracias! Links de venta guardados correctamente.', 'success')
            else:
                flash('Añade al menos un link de venta (con su ticketera).', 'warning')
            return redirect(url_for('public_sale_channels', token=token))
        ticketers = session.query(Ticketer).order_by(Ticketer.name.asc()).all()
        return render_template(
            'public_sale_channels.html',
            concert=concert,
            req=req,
            ticketers=ticketers,
            channels=_concert_sale_channel_rows(concert),
        )
    finally:
        session.close()


def _process_sale_channel_reminders(session) -> int:
    """Recordatorio SEMANAL al promotor mientras el evento confirmado no tenga link de venta.
    Devuelve cuántos correos se han enviado. Best-effort (lo dispara el cron)."""
    now = datetime.now(ZoneInfo('Europe/Madrid'))
    cutoff = now - timedelta(days=7)
    sent = 0
    reqs = (session.query(ConcertSaleChannelRequest)
            .filter(ConcertSaleChannelRequest.status == 'ACTIVE',
                    ConcertSaleChannelRequest.auto_remind.is_(True))
            .all())
    for req in reqs:
        try:
            last = req.last_sent_at
            if last is not None and last.tzinfo is None:
                last = last.replace(tzinfo=ZoneInfo('UTC'))
            if last is not None and last > cutoff:
                continue
            concert = (
                session.query(Concert)
                .options(joinedload(Concert.artist), joinedload(Concert.venue), joinedload(Concert.billing_company),
                         selectinload(Concert.ticketers))
                .filter(Concert.id == req.concert_id)
                .first()
            )
            if not concert:
                continue
            if (concert.status or '').upper() != 'CONFIRMADO':
                continue
            if concert.date and concert.date < date.today():
                req.status = 'CANCELLED'
                continue
            if any((ct.sale_url or '').strip() for ct in (concert.ticketers or [])):
                req.status = 'DONE'
                continue
            ok, _err = _send_sale_channels_email(concert, req, kind='REMINDER')
            if ok:
                req.last_sent_at = now
                req.updated_at = now
                sent += 1
        except Exception:
            session.rollback()
            continue
    session.commit()
    return sent


@app.get('/cron/promoter-requests', endpoint='cron_promoter_requests')
def cron_promoter_requests():
    """Cron externo: recordatorios semanales de links de venta (misma clave que Enterticket)."""
    key = (request.args.get('key') or '').strip()
    expected = (os.environ.get('PROMOTER_CRON_KEY') or os.environ.get('ENTERTICKET_CRON_KEY') or '').strip()
    if not expected or key != expected:
        abort(403)
    session = db()
    try:
        sent = _process_sale_channel_reminders(session)
        return jsonify({'ok': True, 'reminders_sent': sent})
    finally:
        session.close()




@app.get('/conciertos/<cid>/carteleria/assets/<asset_id>/download', endpoint='concert_artwork_asset_download')
@admin_required
def concert_artwork_asset_download(cid, asset_id):
    session = db()
    try:
        asset = (
            session.query(ConcertArtworkAsset)
            .join(ConcertArtworkRequest, ConcertArtworkRequest.id == ConcertArtworkAsset.artwork_request_id)
            .filter(ConcertArtworkRequest.concert_id == to_uuid(cid), ConcertArtworkAsset.id == to_uuid(asset_id))
            .first()
        )
        if not asset:
            flash('Formato no encontrado.', 'warning')
            return redirect(url_for('concert_detail_view', cid=cid, tab='carteleria'))
        filename = (asset.original_name or asset.format_label or 'carteleria').strip()
        mimetype = (asset.mime_type or '').strip() or 'application/octet-stream'
        try:
            req = Request(asset.file_url, headers={'User-Agent': 'Mozilla/5.0'})
            with urlopen(req, timeout=25) as resp:
                content = resp.read()
                guessed = getattr(resp, 'headers', {}).get_content_type() if getattr(resp, 'headers', None) else None
                if guessed:
                    mimetype = guessed
            return send_file(BytesIO(content), mimetype=mimetype, as_attachment=True, download_name=filename)
        except Exception as exc:
            flash(f'No se pudo descargar el formato: {exc}', 'danger')
            return redirect(url_for('concert_detail_view', cid=cid, tab='carteleria'))
    finally:
        session.close()


@app.get('/conciertos/<cid>/carteleria/descargar-todos', endpoint='concert_artwork_download_all')
@admin_required
def concert_artwork_download_all(cid):
    """Descarga TODOS los carteles aprobados de la actividad en un ZIP."""
    session_db = db()
    try:
        concert = (session_db.query(Concert).options(joinedload(Concert.artist))
                   .filter(Concert.id == to_uuid(cid)).first())
        row = getattr(concert, 'artwork_request', None) if concert else None
        assets = [a for a in ((row.assets if row else None) or [])
                  if not a.is_archived and (a.validation_status or 'APPROVED') == 'APPROVED']
        if not assets:
            flash('No hay carteles aprobados que descargar.', 'warning')
            return redirect(url_for('concert_detail_view', cid=cid, tab='carteleria'))
        buf = BytesIO()
        usados = set()
        with zipfile.ZipFile(buf, "w", compression=zipfile.ZIP_DEFLATED) as zf:
            for a in assets:
                nombre = (a.original_name or a.format_label or 'cartel').strip()
                base, ext = os.path.splitext(nombre)
                n = 1
                while nombre.lower() in usados:          # dos ficheros con el mismo nombre
                    n += 1
                    nombre = f"{base} ({n}){ext}"
                usados.add(nombre.lower())
                try:
                    req = Request(a.file_url, headers={'User-Agent': 'Mozilla/5.0'})
                    with urlopen(req, timeout=25) as resp:
                        zf.writestr(nombre, resp.read())
                except Exception:
                    continue
        buf.seek(0)
        etiqueta = " ".join([x for x in [
            (concert.artist.name if concert and concert.artist else "Carteleria"),
            (concert.date.strftime("%Y-%m-%d") if concert and concert.date else "")] if x])
        etiqueta = re.sub(r"[\\/:*?\"<>|]+", " ", etiqueta).strip() or "Carteleria"
        return send_file(buf, mimetype="application/zip", as_attachment=True,
                         download_name=f"Carteles {etiqueta}.zip")
    finally:
        session_db.close()


@app.post('/conciertos/<cid>/carteleria/compartido', endpoint='concert_artwork_mark_shared')
@admin_required
def concert_artwork_mark_shared(cid):
    """Marca la cartelería como COMPARTIDA con el artista o con el promotor (etiqueta de la
    pestaña). Lo llama el propio menú de compartir al pulsar correo/WhatsApp/SMS."""
    session = db()
    try:
        concert = session.get(Concert, to_uuid(cid))
        if not concert:
            return jsonify({"ok": False, "error": "Actividad no encontrada"}), 404
        req = getattr(concert, 'artwork_request', None)
        if not req:
            return jsonify({"ok": False, "error": "Sin solicitud de cartelería"}), 404
        who = (request.form.get('who') or 'artist').strip().lower()
        undo = _truthy(request.form.get('undo'))
        stamp = None if undo else _now_madrid()
        if who == 'promoter':
            req.shared_with_promoter_at = stamp
        else:
            req.shared_with_artist_at = stamp
        session.commit()
        if request.form.get('ajax'):
            return jsonify({"ok": True, "who": who, "shared": not undo})
        return redirect(safe_next_or(url_for('concert_detail_view', cid=cid, tab='carteleria')))
    except Exception as exc:
        session.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        session.close()


