@app.post("/ventas/<cid>/ticketer/<tid>/day/save", endpoint="sales_ticketer_day_save")
@admin_required
def sales_ticketer_day_save(cid, tid):
    """Guarda las entradas vendidas HOY por ticketera y tipo."""
    session_db = db()
    try:
        concert_id = to_uuid(cid)
        ticketer_id = to_uuid(tid)
        day = parse_date(request.form.get("day") or date.today().isoformat())

        # Validar que el concierto existe
        c = session_db.query(Concert).options(selectinload(Concert.ticket_types)).get(concert_id)
        if not c:
            flash("Concierto no encontrado.", "warning")
            return redirect(request.referrer or url_for("sales_update_view"))

        # Guarda de servidor: la ticketera Enterticket de un concierto VINCULADO se actualiza sola
        # desde la API (el bloqueo de la plantilla no basta: una pestaña vieja o un POST directo
        # pisaría la rejilla espejada con ceros).
        tk_row = session_db.get(Ticketer, ticketer_id)
        if (tk_row and (tk_row.name or "").strip().lower() == "enterticket"
                and session_db.query(EnterticketEvent.id)
                .filter(EnterticketEvent.concert_id == concert_id).first()):
            flash("Esta ticketera se actualiza sola desde la API de Enterticket; no se guardan apuntes manuales.", "warning")
            return redirect(request.referrer or url_for("sales_update_view"))

        # Precio bruto por tipo para esta ticketera (configuración)
        cfg_rows = (
            session_db.query(ConcertTicketerTicketType.ticket_type_id, ConcertTicketerTicketType.price_gross)
            .filter(ConcertTicketerTicketType.concert_id == concert_id)
            .filter(ConcertTicketerTicketType.ticketer_id == ticketer_id)
            .all()
        )
        cfg_price_map = {ttid: float(p or 0.0) for ttid, p in cfg_rows}

        # Upsert para cada tipo de entrada del concierto
        types = list(c.ticket_types or [])
        if not types:
            raise ValueError("Primero añade al menos un tipo de entrada")

        for tt in types:
            field = f"qty_{tt.id}"
            raw = (request.form.get(field) or "").strip()
            qty_int = int(raw) if raw else 0
            if qty_int < 0:
                qty_int = 0

            price_gross = float(cfg_price_map.get(tt.id, 0.0) or 0.0)
            if price_gross <= 0:
                # Fallback (modo antiguo): precio en la categoría
                price_gross = float(getattr(tt, "price", 0) or 0.0)

            row = (
                session_db.query(TicketSaleDetail)
                .filter_by(concert_id=concert_id, day=day, ticketer_id=ticketer_id, ticket_type_id=tt.id)
                .first()
            )
            if row:
                row.qty = qty_int
                row.unit_price_gross = price_gross
                row.updated_at = func.now()
            else:
                session_db.add(
                    TicketSaleDetail(
                        concert_id=concert_id,
                        day=day,
                        ticketer_id=ticketer_id,
                        ticket_type_id=tt.id,
                        qty=qty_int,
                        unit_price_gross=price_gross,
                    )
                )

        session_db.commit()
        flash("Ventas por ticketera guardadas.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error guardando ventas por ticketera: {e}", "danger")
    finally:
        session_db.close()

    day_s = request.form.get("day") or request.args.get("day")
    return redirect(url_for("sales_update_view", d=day_s, open_sales=str(cid)) + f"#concert-{cid}" if day_s else (request.referrer or url_for("sales_update_view")))


# ------------- REPORTE DE VENTAS (PUBLIC Y ADMIN) -----------

def concerts_for_report(session, day: date, past: bool = False, promoter_id=None, artist_id=None, company_id=None):
    """
    Devuelve conciertos para el reporte de ventas, precargando TODAS las relaciones usadas en la plantilla.

    - Próximos: fecha >= (día-2)
    - Anteriores: fecha < (día-2)

    Filtros opcionales:
      - promoter_id: conciertos vendidos por ese promotor o con participación de promotor.
      - company_id: conciertos EMPRESA (empresa/grupo o facturación) o con participación de empresa.
      - artist_id: filtra por artista.
    """
    cutoff = day - timedelta(days=2)

    q = (
        session.query(Concert)
        .options(
            # entidades directas de la tarjeta
            joinedload(Concert.artist),
            joinedload(Concert.venue),
            joinedload(Concert.promoter),          # VENDIDO
            joinedload(Concert.group_company),
            joinedload(Concert.billing_company),   # EMPRESA
            # colecciones y sus relaciones anidadas (participaciones)
            selectinload(Concert.promoter_shares).joinedload(ConcertPromoterShare.promoter),
            selectinload(Concert.company_shares).joinedload(ConcertCompanyShare.company),
            joinedload(Concert.sales_config),
            selectinload(Concert.ticketers).joinedload(ConcertTicketer.ticketer),
        )
        # Solo los tipos con ventas (excluye "GRATUITO")
        .filter(Concert.sale_type.in_(SALES_SECTION_ORDER))
    )

    if past:
        q = q.filter(Concert.date < cutoff)
    else:
        q = q.filter(Concert.date >= cutoff)

    concerts = q.order_by(Concert.date.asc()).all()

    def _safe_uuid(x):
        try:
            return to_uuid(x) if x else None
        except Exception:
            return None

    pid = _safe_uuid(promoter_id)
    aid = _safe_uuid(artist_id)
    cid = _safe_uuid(company_id)

    if aid:
        concerts = [c for c in concerts if c.artist_id == aid]

    if pid:
        def _has_promoter(c):
            if c.promoter_id == pid:
                return True
            for s in (c.promoter_shares or []):
                if s.promoter_id == pid:
                    return True
            return False
        concerts = [c for c in concerts if _has_promoter(c)]

    if cid:
        def _has_company(c):
            if c.group_company_id == cid or getattr(c, "billing_company_id", None) == cid:
                return True
            for s in (c.company_shares or []):
                if s.company_id == cid:
                    return True
            return False
        concerts = [c for c in concerts if _has_company(c)]

    return concerts

def build_sales_report_context(day: date, *, past=False, promoter_id=None, artist_id=None, company_id=None,
                               artist_ids=None, sale_types=None, q_text="", only_et=False,
                               include_filters=True):
    session = db()
    try:
        concerts = concerts_for_report(
            session,
            day,
            past=past,
            promoter_id=promoter_id,
            artist_id=artist_id,
            company_id=company_id,
        )

        # --- Filtros de la vista (homogéneos con el listado de conciertos) ---
        artist_uuid_set = set()
        for raw in (artist_ids or []):
            try:
                u = to_uuid(raw)
                if u:
                    artist_uuid_set.add(u)
            except Exception:
                continue
        if artist_uuid_set:
            concerts = [c for c in concerts if c.artist_id in artist_uuid_set]
        type_set = {t for t in (sale_types or []) if t in SALES_SECTION_ORDER}
        if type_set:
            concerts = [c for c in concerts if c.sale_type in type_set]
        qn = _norm_text_key(q_text or "")
        if qn:
            def _search_blob(c):
                v = c.venue
                parts = [c.artist.name if c.artist else "", c.festival_name or "",
                         (v.name if v else "") or (c.manual_venue_name or ""),
                         (v.municipality if v else "") or (c.manual_municipality or ""),
                         (v.province if v else "") or (c.manual_province or "")]
                return _norm_text_key(" ".join(p for p in parts if p))
            concerts = [c for c in concerts if qn in _search_blob(c)]
        concert_ids = [c.id for c in concerts]

        # Enterticket: los conciertos vinculados llegan al reporte SIEMPRE al día — al abrirlo se
        # dispara (en segundo plano, con guarda de 5 min) la sincronización de los que estén viejos,
        # y el reporte marca cada concierto integrado con su hora de última actualización. El JS del
        # reporte vigila /ventas/et/estado y recarga una vez cuando terminan los syncs lanzados.
        et_map = {}
        et_stamp = 0
        if concert_ids and et_api.enterticket_configured():
            try:
                for _ev in (session.query(EnterticketEvent)
                            .filter(EnterticketEvent.concert_id.in_(concert_ids)).all()):
                    _et_maybe_sync_event(_ev, max_age_min=5)
                    # La etiqueta del reporte imita a "Actualizado hoy" (verde) añadiendo la HORA y un
                    # icono de conexión, para que se vea que la cifra viene de la conexión con Enterticket.
                    _last_local = _ev.last_synced_at
                    if _last_local is not None and _last_local.tzinfo is not None:
                        _last_local = _last_local.astimezone(TZ_MADRID)
                    et_map[_ev.concert_id] = {
                        "last": _et_fmt_dt(_ev.last_synced_at),  # compat: "dd/mm/YYYY HH:MM"
                        "time": _last_local.strftime("%H:%M") if _last_local else "",
                        "date": _last_local.strftime("%d/%m/%Y") if _last_local else "",
                        "is_today": bool(_last_local and _last_local.date() == today_local()),
                        "synced": bool(_ev.last_synced_at),
                    }
                    if _ev.last_synced_at:
                        et_stamp = max(et_stamp, int(_ev.last_synced_at.timestamp()))
            except Exception:
                et_map, et_stamp = {}, 0
        if only_et:
            concerts = [c for c in concerts if c.id in et_map]
            concert_ids = [c.id for c in concerts]

        # Aforo a la venta (si hay categorías por tipo, suma de aforos por tipo)
        if concert_ids:
            cap_rows = (
                session.query(
                    ConcertTicketType.concert_id,
                    func.coalesce(func.sum(ConcertTicketType.qty_for_sale), 0).label("sum_qty"),
                )
                .filter(ConcertTicketType.concert_id.in_(concert_ids))
                .group_by(ConcertTicketType.concert_id)
                .all()
            )
            cap_map = {cid: int(s or 0) for cid, s in cap_rows}
            for c in concerts:
                cap_sum = cap_map.get(c.id, 0)
                if cap_sum > 0:
                    c.capacity = cap_sum

        totals, today_map, last_map, gross_map, _gross_today = sales_maps_unified(session, day, concert_ids)

        # Neto (IVA primero, luego SGAE sobre base sin IVA)
        net_map = {}
        for c in concerts:
            gross = float(gross_map.get(c.id, 0.0) or 0.0)
            vat = float(getattr(c.sales_config, "vat_pct", 0) or 0) if getattr(c, "sales_config", None) else 0.0
            sgae = float(getattr(c.sales_config, "sgae_pct", 0) or 0) if getattr(c, "sales_config", None) else 0.0
            net_map[c.id] = float(_sales_net_breakdown(gross, vat, sgae).get("net") or 0.0)

        # Rebate neto (por ticketera) — ingreso separado de ventas
        ticketer_totals_map = {}
        rebate_net_map = {}
        if concert_ids:
            rows = (
                session.query(
                    TicketSaleDetail.concert_id,
                    TicketSaleDetail.ticketer_id,
                    func.sum(TicketSaleDetail.qty),
                    func.sum(TicketSaleDetail.qty * TicketSaleDetail.unit_price_gross),
                )
                .filter(TicketSaleDetail.concert_id.in_(concert_ids))
                .filter(TicketSaleDetail.day <= day)
                .group_by(TicketSaleDetail.concert_id, TicketSaleDetail.ticketer_id)
                .all()
            )
            for cid2, tid2, sold, gross in rows:
                ticketer_totals_map.setdefault(cid2, {})[tid2] = {"sold": int(sold or 0), "gross": float(gross or 0.0)}

        for c in concerts:
            vat_pct = float(getattr(c.sales_config, "vat_pct", 0) or 0) if getattr(c, "sales_config", None) else 0.0
            cid2 = c.id
            total_rebate_net = 0.0
            for ct in (c.ticketers or []):
                tid2 = ct.ticketer_id
                sold_i = int((ticketer_totals_map.get(cid2, {}) or {}).get(tid2, {}).get("sold", 0) or 0)
                gross_f = float((ticketer_totals_map.get(cid2, {}) or {}).get(tid2, {}).get("gross", 0.0) or 0.0)

                rn = 0.0
                mode = (getattr(ct, "rebate_mode", None) or "").upper()
                if mode == "FIXED":
                    fixed_gross = float(getattr(ct, "rebate_fixed_gross", 0) or 0.0)
                    # Neto del rebate fijo usando el IVA configurado del concierto (no 21% fijo).
                    vat_factor = 1.0 + (vat_pct / 100.0)
                    rn = (sold_i * fixed_gross) / vat_factor if (fixed_gross and vat_factor > 0) else 0.0
                elif mode == "PERCENT":
                    pct = float(getattr(ct, "rebate_pct", 0) or 0.0)
                    if pct and gross_f:
                        vat_factor = 1.0 + (vat_pct / 100.0)
                        base_no_vat_ticketer = (gross_f / vat_factor) if vat_factor > 0 else gross_f
                        rn = base_no_vat_ticketer * (pct / 100.0)

                if rn < 0:
                    rn = 0.0
                total_rebate_net += rn

            rebate_net_map[cid2] = total_rebate_net

        sections = {k: [] for k in SALES_SECTION_ORDER}
        for c in concerts:
            if c.sale_type in sections:
                sections[c.sale_type].append(c)
        for k in sections:
            sections[k].sort(key=lambda x: (x.date or date.max, x.artist.name if x.artist else ""))

        # Lista PLANA en orden cronológico: próximos = del más cercano al más lejano; anteriores = del
        # más reciente al más antiguo. Es el nuevo listado por defecto (el agrupado por tipo/artista lo
        # hace el JS en cliente). El nombre del sujeto es el artista o, si no hay, el nombre del evento.
        def _subject_name(c):
            return (c.artist.name if c.artist else None) or (c.festival_name or "")
        rows = sorted(
            concerts,
            key=lambda c: (c.date or date.max, _subject_name(c).lower()),
            reverse=bool(past),
        )

        # ¿Actualizado hoy? (por conexión Enterticket hoy, o actualización manual con fecha de hoy).
        updated_map = {}
        for c in concerts:
            et = et_map.get(c.id)
            updated_map[c.id] = bool((et and et.get("is_today")) or (last_map.get(c.id) == day))

        # Entidades del filtro superior (chips con foto): artistas y EVENTOS que tienen conciertos en
        # esta vista. Un evento (concierto sin artista, con nombre de festival) sale "como un artista
        # más". `entity_key_map` da la clave de cada concierto para casar tarjeta<->chip en el JS.
        entity_key_map = {}
        entities = {}
        for c in concerts:
            if c.artist_id and c.artist:
                key = str(c.artist_id)
                entities.setdefault(key, {"key": key, "kind": "artist", "name": c.artist.name or "—",
                                          "photo": c.artist.photo_url or ""})
            elif (c.festival_name or "").strip():
                fn = c.festival_name.strip()
                key = "event:" + _norm_text_key(fn)
                entities.setdefault(key, {"key": key, "kind": "event", "name": fn, "photo": ""})
            else:
                key = "otros"
                entities.setdefault(key, {"key": key, "kind": "event", "name": "Otros", "photo": ""})
            entity_key_map[c.id] = key
        filter_entities = sorted(entities.values(), key=lambda e: e["name"].lower())

        # KPIs de cabecera del reporte (sobre lo filtrado).
        kpis = {
            "count": len(concerts),
            "today": sum(int(today_map.get(c.id, 0) or 0) for c in concerts),
            "total": sum(int(totals.get(c.id, 0) or 0) for c in concerts),
            "capacity": sum(int(c.capacity or 0) for c in concerts if not c.no_capacity),
            "gross": sum(float(gross_map.get(c.id, 0) or 0) for c in concerts),
            "net": sum(float(net_map.get(c.id, 0) or 0) for c in concerts),
            "et_count": sum(1 for c in concerts if c.id in et_map),
        }

        # Opciones de los filtros (dicts planos: la sesión se cierra al salir). Solo para las
        # vistas que pintan la tarjeta de filtros (el PDF, el envío y los reportes por entidad
        # se las saltan: include_filters=False).
        artists_filter = []
        companies_filter = []
        promoters_filter = []
        if include_filters:
            artists_filter = [{"id": str(a.id), "name": a.name or "", "photo": a.photo_url or ""}
                              for a in session.query(Artist).order_by(Artist.name.asc()).all()]
            companies_filter = [{"id": str(g.id), "name": g.name or "", "logo": g.logo_url or ""}
                                for g in session.query(GroupCompany).order_by(GroupCompany.name.asc()).all()]
            seen_proms = {}
            for c in concerts:
                if c.promoter:
                    seen_proms[str(c.promoter.id)] = {"id": str(c.promoter.id), "name": c.promoter.nick or "", "logo": c.promoter.logo_url or ""}
                for sh in (c.promoter_shares or []):
                    if sh.promoter:
                        seen_proms[str(sh.promoter.id)] = {"id": str(sh.promoter.id), "name": sh.promoter.nick or "", "logo": sh.promoter.logo_url or ""}
            promoters_filter = sorted(seen_proms.values(), key=lambda x: x["name"].lower())

        return dict(
            day=day,
            past=past,
            sections=sections,
            order=SALES_SECTION_ORDER,
            titles=SALES_SECTION_TITLE,
            totals=totals,
            today_map=today_map,
            last_map=last_map,
            gross_map=gross_map,
            net_map=net_map,
            rebate_net_map=rebate_net_map,
            et_map=et_map,
            et_stamp=et_stamp,
            kpis=kpis,
            rows=rows,
            updated_map=updated_map,
            filter_entities=filter_entities,
            entity_key_map=entity_key_map,
            artists_filter=artists_filter,
            companies_filter=companies_filter,
            promoters_filter=promoters_filter,
            type_choices=[(k, SALES_TYPE_CHIP_LABEL.get(k, SALES_SECTION_TITLE[k]), SALES_TYPE_ICON.get(k, "fa-tag")) for k in SALES_SECTION_ORDER],
            f_artist_ids=[str(x) for x in (artist_ids or [])],
            f_sale_types=list(sale_types or []),
            f_company_id=(str(company_id) if company_id else ""),
            f_promoter_id=(str(promoter_id) if promoter_id else ""),
            f_q=(q_text or ""),
            f_only_et=bool(only_et),
        )
    finally:
        session.close()


def _sales_report_filters_from_request(source=None) -> dict:
    """Filtros del reporte (mismo esquema que el listado de conciertos) desde GET o desde los
    hidden del modal de envío (POST)."""
    src = source if source is not None else request.args
    return dict(
        artist_ids=src.getlist("artist"),
        sale_types=src.getlist("type"),
        company_id=(src.get("company") or None),
        promoter_id=(src.get("promoter") or None),
        q_text=(src.get("q") or "").strip(),
        only_et=((src.get("et") or "") == "1"),
    )


def _sales_report_filter_args(filters: dict) -> dict:
    """Los mismos filtros como querystring (para navegación día anterior/siguiente y redirects)."""
    out = {}
    if filters.get("artist_ids"):
        out["artist"] = filters["artist_ids"]
    if filters.get("sale_types"):
        out["type"] = filters["sale_types"]
    if filters.get("company_id"):
        out["company"] = filters["company_id"]
    if filters.get("promoter_id"):
        out["promoter"] = filters["promoter_id"]
    if filters.get("q_text"):
        out["q"] = filters["q_text"]
    if filters.get("only_et"):
        out["et"] = "1"
    return out


@app.get("/ventas/reporte", endpoint="sales_report_view")
def sales_report_view():
    day = get_day("d")
    filters = _sales_report_filters_from_request()
    ctx = build_sales_report_context(day, **filters)
    args = _sales_report_filter_args(filters)
    ctx["pdf_url"] = url_for("sales_report_pdf", d=day.isoformat(), **args)
    ctx["nav_prev_url"] = url_for("sales_report_view", d=(day - timedelta(days=1)).isoformat(), **args)
    ctx["nav_next_url"] = url_for("sales_report_view", d=(day + timedelta(days=1)).isoformat(), **args)
    ctx["filter_action_url"] = url_for("sales_report_view")
    ctx["clear_url"] = url_for("sales_report_view", d=day.isoformat())
    ctx["email_recipients"] = _sales_report_recipients() if (can_edit_sales() or is_master()) else []
    return render_template("sales_report.html", **ctx)

