@app.get('/promotores/<pid>', endpoint='promoter_detail_view')
@admin_required
def promoter_detail_view(pid):
    session = db()
    try:
        promoter = (
            session.query(Promoter)
            .options(selectinload(Promoter.companies), selectinload(Promoter.contacts))
            .filter(Promoter.id == to_uuid(pid))
            .first()
        )
        if not promoter:
            flash('Tercero no encontrado.', 'warning')
            return redirect(url_for('promoters_view'))
        tab = (request.args.get('tab') or 'general').strip().lower()
        if tab not in {'general', 'contactos', 'vinculaciones', 'invitaciones', 'documentos', 'prl', 'adelantos'}:
            tab = 'general'
        promoter_email_addresses = (
            session.query(PromoterEmail)
            .filter(PromoterEmail.promoter_id == promoter.id)
            .order_by(PromoterEmail.created_at.asc(), PromoterEmail.concept.asc())
            .all()
        )
        grouped = defaultdict(list)
        for contact in promoter.contacts or []:
            key = (contact.title or 'Sin título').strip() or 'Sin título'
            grouped[key].append(contact)
        # Invitaciones de este tercero (como invitado): solicitudes que pidió y compromisos en los
        # que figura como destinatario. En vigor (evento activo) y anteriores. Se gestionan con los
        # 3 puntos igual que en la gestión del evento; los compromisos son de lectura (con enlace).
        promoter_invitations_count = ((
            session.query(func.count(InvitationRequest.id))
            .filter(InvitationRequest.guest_promoter_id == promoter.id)
            .scalar()
        ) or 0) + ((
            session.query(func.count(InvitationCommitment.id))
            .filter(InvitationCommitment.guest_promoter_id == promoter.id)
            .scalar()
        ) or 0)
        promoter_invitations_active = []
        promoter_invitations_past = []
        promoter_commitments_active = []
        promoter_commitments_past = []
        if tab == 'invitaciones' and promoter_invitations_count:
            cat_cache: dict[str, list] = {}

            def _cats_for(concert, concert_id):
                cats = cat_cache.get(str(concert_id))
                if cats is None:
                    cats = _invitation_get_categories(session, concert, ensure_defaults=False) if concert else []
                    cat_cache[str(concert_id)] = cats
                return cats

            for r in (
                session.query(InvitationRequest)
                .filter(InvitationRequest.guest_promoter_id == promoter.id)
                .order_by(InvitationRequest.created_at.desc())
                .all()
            ):
                concert = r.concert or (session.get(Concert, r.concert_id) if r.concert_id else None)
                cats = _cats_for(concert, r.concert_id)
                item = _invitation_request_payload(r, cats)
                item.update(_invitation_request_kind_flags(session, r, cats))
                item['event'] = _invitation_event_payload(session, concert) if concert else {
                    'id': '', 'title': 'Evento', 'artist_names': '', 'date_label': '', 'date': '',
                }
                active = _invitation_event_is_active_for_requests(concert) if concert else False
                item['_sort_date'] = item['event'].get('date') or ''
                (promoter_invitations_active if active else promoter_invitations_past).append(item)
            promoter_invitations_active.sort(key=lambda i: i['_sort_date'] or '9999')  # próximos primero
            promoter_invitations_past.sort(key=lambda i: i['_sort_date'], reverse=True)  # recientes primero

            for c in (
                session.query(InvitationCommitment)
                .filter(InvitationCommitment.guest_promoter_id == promoter.id)
                .order_by(InvitationCommitment.created_at.desc())
                .all()
            ):
                concert = c.concert or (session.get(Concert, c.concert_id) if c.concert_id else None)
                cats = _cats_for(concert, c.concert_id)
                name_map = _invitation_category_name_map(cats)
                q = _json_dict(c.quantities_json)
                statuses = [st for (st,) in session.query(InvitationTicket.status).filter(InvitationTicket.assigned_commitment_id == c.id).all()]
                _lbl, _bdg = _invitation_commitment_state_from_statuses(statuses)
                citem = {
                    'id': str(c.id),
                    'name': c.name,
                    'reason': c.reason or '',
                    'note': c.note or '',
                    'quantities_label': _invitation_quantities_label(q, name_map),
                    'status_label': _lbl,
                    'status_badge': _bdg,
                    'event': _invitation_event_payload(session, concert) if concert else {
                        'id': '', 'title': 'Evento', 'artist_names': '', 'date_label': '', 'date': '',
                    },
                }
                active = _invitation_event_is_active_for_requests(concert) if concert else False
                citem['_sort_date'] = citem['event'].get('date') or ''
                (promoter_commitments_active if active else promoter_commitments_past).append(citem)
            promoter_commitments_active.sort(key=lambda i: i['_sort_date'] or '9999')
            promoter_commitments_past.sort(key=lambda i: i['_sort_date'], reverse=True)
        return render_template(
            'promoter_detail.html',
            promoter=promoter,
            tab=tab,
            travel_prefs=_travel_prefs_of(promoter),
            travel_summary=_travel_summary(promoter),
            contacts_by_title=sorted(grouped.items(), key=lambda x: _norm_text_key(x[0])),
            promoter_email_addresses=promoter_email_addresses,
            # Adelantos y deudas con las empresas del grupo (lo que avisa al ir a pagarle).
            party_debts=(_party_debt_rows(session, promoter_id=promoter.id, only_open=False) if tab == 'adelantos' else []),
            party_debt_kinds=PARTY_DEBT_KINDS,
            group_companies_all=(session.query(GroupCompany).order_by(GroupCompany.name.asc()).all() if tab == 'adelantos' else []),
            promoter_invitations_count=promoter_invitations_count,
            promoter_invitations_active=promoter_invitations_active,
            promoter_invitations_past=promoter_invitations_past,
            promoter_commitments_active=promoter_commitments_active,
            promoter_commitments_past=promoter_commitments_past,
            entity_links=_entity_link_rows(session, 'promoter', promoter.id),
            entity_link_context={'type': 'promoter', 'id': str(promoter.id), 'label': promoter.nick or 'tercero'},
            entity_link_types=APP33_ENTITY_LINK_TYPES,
            entity_links_can_edit=(can_edit_catalogs() or can_edit_discografica()),
            person_documents=_person_documents_for(session, "PROMOTER", promoter.id),
            person_docs_owner_type="PROMOTER",
            person_docs_owner_name=(" ".join([x for x in [(promoter.first_name or "").strip(), (promoter.last_name or "").strip()] if x]).strip() or promoter.nick or ""),
            person_docs_owner_id=str(promoter.id),
            person_docs_save_url=url_for("promoter_document_save", pid=promoter.id),
            person_docs_delete_base=url_for("promoter_document_delete", pid=promoter.id, doc_id="__ID__"),
            person_docs_can_edit=(can_edit_catalogs() or can_edit_discografica()),
            loyalty_brands=PERSON_LOYALTY_BRANDS,
            prl_docs=(session.query(PersonComplianceDoc)
                      .filter(PersonComplianceDoc.owner_type == 'PROMOTER', PersonComplianceDoc.owner_id == promoter.id)
                      .order_by(PersonComplianceDoc.created_at.desc()).all()) if tab == 'prl' else [],
            prl_owner_type='PROMOTER',
            prl_owner_id=str(promoter.id),
            prl_can_edit=(can_edit_catalogs() or can_edit_discografica()),
            prl_doc_labels=PRL_DOC_LABELS,
            prl_worker_types=PRL_WORKER_TYPES,
            prl_worker_type=(promoter.prl_type or ''),
            prl_next=url_for('promoter_detail_view', pid=promoter.id, tab='prl'),
            prl_today=date.today(),
        )
    finally:
        session.close()


@app.post('/promotores/<pid>/emails/create', endpoint='promoter_email_create')
@admin_required
def promoter_email_create(pid):
    session = db()
    try:
        promoter = session.get(Promoter, to_uuid(pid))
        if not promoter:
            flash('Tercero no encontrado.', 'warning')
            return redirect(url_for('promoters_view'))
        concept = (request.form.get('concept') or '').strip()
        email = (request.form.get('email') or '').strip()
        if not concept or not email:
            flash('Debes indicar concepto y email.', 'warning')
            return redirect(url_for('promoter_detail_view', pid=pid, tab='general'))
        if not _looks_like_email_address(email):
            flash('La dirección de correo no es válida.', 'warning')
            return redirect(url_for('promoter_detail_view', pid=pid, tab='general'))
        session.add(PromoterEmail(promoter_id=promoter.id, concept=concept, email=email))
        session.commit()
        flash('Correo añadido.', 'success')
    except Exception as exc:
        session.rollback()
        flash(f'Error creando correo: {exc}', 'danger')
    finally:
        session.close()
    return redirect(url_for('promoter_detail_view', pid=pid, tab='general'))


