@app.get('/api/concerts/check-artist-conflict', endpoint='api_concert_artist_conflicts')
@admin_required
def api_concert_artist_conflicts():
    """Aviso de solape por artista y fecha (o rango): conciertos, acciones, bloqueos/notas de
    agenda y PETICIONES. Acepta `date` (día) o `start`/`end` (rango). Cada resultado lleva `summary`
    (compat con el asistente) + `kind`/`url`. Casa también co-artistas (artist_ids)."""
    session = db()
    try:
        aid = to_uuid((request.args.get('artist_id') or '').strip())
        raw_date = (request.args.get('date') or '').strip()
        raw_start = (request.args.get('start') or '').strip()
        raw_end = (request.args.get('end') or '').strip()
        if raw_start or raw_end:
            start = parse_date(raw_start or raw_end)
            end = parse_date(raw_end or raw_start)
        else:
            start = end = parse_date(raw_date)
        if end < start:
            start, end = end, start
        exclude_id_raw = (request.args.get('exclude_id') or '').strip() or None
        aid_s = str(aid)
        out = []
        # Conciertos (por artista principal o co-artista).
        cq = (
            session.query(Concert).options(joinedload(Concert.venue))
            .filter(or_(Concert.artist_id == aid, Concert.artist_ids.contains([aid_s])))
            .filter(Concert.date >= start, Concert.date <= end)
        )
        if exclude_id_raw:
            try:
                cq = cq.filter(Concert.id != to_uuid(exclude_id_raw))
            except Exception:
                pass
        for c in cq.order_by(Concert.date.asc()).all():
            base = ' · '.join([x for x in [c.festival_name or 'Concierto', _concert_venue_name(c), _concert_city(c)] if x])
            out.append({
                'id': str(c.id), 'kind': 'Concierto', 'date': (c.date.isoformat() if c.date else ''),
                'festival_name': (c.festival_name or '').strip(), 'venue_name': _concert_venue_name(c),
                'municipality': _concert_city(c), 'province': _concert_province_value(c),
                'summary': ((c.date.strftime('%d/%m') + ' · ') if c.date else '') + base + ((' [' + c.status + ']') if (c.status and c.status.upper() != 'CONFIRMADO') else ''),
                'url': url_for('concert_detail_view', cid=c.id),
            })
        # Acciones (CompanyAction), con solape de rango.
        try:
            aq = (
                session.query(CompanyAction)
                .filter(CompanyAction.artist_ids.contains([aid_s]))
                .filter(CompanyAction.start_date.isnot(None))
                .filter(CompanyAction.start_date <= end)
                .filter(func.coalesce(CompanyAction.end_date, CompanyAction.start_date) >= start)
                .filter(func.upper(func.coalesce(CompanyAction.status, '')).in_(['RESERVA', 'CONFIRMADO', 'CERRADA']))
            )
            for a in aq.order_by(CompanyAction.start_date.asc()).all():
                out.append({
                    'id': str(a.id), 'kind': 'Acción', 'date': (a.start_date.isoformat() if a.start_date else ''),
                    'summary': ((a.start_date.strftime('%d/%m') + ' · ') if a.start_date else '') + (a.title or 'Acción'),
                })
        except Exception:
            pass
        # Bloqueos / notas de agenda (solape de rango).
        try:
            iq = (
                session.query(ArtistAgendaItem)
                .filter(ArtistAgendaItem.artist_id == aid)
                .filter(ArtistAgendaItem.start_date <= end)
                .filter(ArtistAgendaItem.end_date >= start)
            )
            for it in iq.order_by(ArtistAgendaItem.start_date.asc()).all():
                k = 'Bloqueo' if (it.kind or '').upper() == 'BLOCK' else 'Nota'
                out.append({
                    'id': str(it.id), 'kind': k, 'date': (it.start_date.isoformat() if it.start_date else ''),
                    'summary': ((it.start_date.strftime('%d/%m') + ' · ') if it.start_date else '') + (it.title or it.note or k),
                })
        except Exception:
            pass
        # Peticiones de contratación activas.
        try:
            bq = (
                session.query(BookingRequest)
                .filter(BookingRequest.artist_id == aid)
                .filter(BookingRequest.requested_date.isnot(None))
                .filter(BookingRequest.requested_date >= start, BookingRequest.requested_date <= end)
                .filter(func.upper(func.coalesce(BookingRequest.status, 'NUEVA')).in_(['NUEVA', 'EN_TRAMITE']))
            )
            for b in bq.order_by(BookingRequest.requested_date.asc()).all():
                out.append({
                    'id': str(b.id), 'kind': 'Petición', 'date': (b.requested_date.isoformat() if b.requested_date else ''),
                    'summary': ((b.requested_date.strftime('%d/%m') + ' · ') if b.requested_date else '') + (b.subject or 'Petición'),
                    'url': url_for('contracting_view', section='peticiones'),
                })
        except Exception:
            pass
        return jsonify(out)
    except Exception as exc:
        return jsonify({'error': str(exc)}), 400
    finally:
        session.close()


def _ensure_promoter_for_media(session, media_id):
    """El promotor de una actividad también puede ser un MEDIO de comunicación: como
    Concert.promoter_id apunta a promoters, se reutiliza (o crea) el tercero espejo con
    el nombre y el logo del medio."""
    media = session.get(MediaOutlet, media_id) if media_id else None
    if not media:
        return None
    name = (media.name or '').strip()
    if not name:
        return None
    existing = (
        session.query(Promoter)
        .filter(func.lower(Promoter.nick) == name.lower())
        .first()
    )
    if existing:
        if not existing.logo_url and media.logo_url:
            existing.logo_url = media.logo_url
        return existing
    p = Promoter(nick=name, logo_url=media.logo_url, kind='empresa')
    session.add(p)
    session.flush()
    return p


def _parse_wizard_ticket_types(form) -> list[dict]:
    """Tipos de entrada del asistente: nombre + precio (+ cupo e invitaciones opcionales)."""
    names = form.getlist('wt_name[]')
    prices = form.getlist('wt_price[]')
    qtys = form.getlist('wt_qty[]')
    invites = form.getlist('wt_invites[]')
    rows = []
    seen = set()
    for i, raw_name in enumerate(names or []):
        name = (raw_name or '').strip()
        price = _parse_optional_decimal(prices[i] if i < len(prices) else None)
        qty = _parse_optional_positive_int((qtys[i] if i < len(qtys) else '') or '')
        inv = _parse_optional_positive_int((invites[i] if i < len(invites) else '') or '')
        if not name and price is None and not qty and not inv:
            continue
        name = name or f'Entrada {len(rows) + 1}'
        key = name.casefold()
        if key in seen:
            continue
        seen.add(key)
        rows.append({
            'name': name,
            'price': float(price or 0),
            'qty_for_sale': int(qty or 0),
            'invites_total': int(inv or 0),
        })
    return rows


def _parse_wizard_sale_seller(session, form, billing_company_id=None, promoter_id=None, venue_id=None):
    """«¿Quién saca las entradas a la venta?» del asistente → dict para ticketing_payload."""
    kind = (form.get('sale_seller_kind') or '').strip().upper()
    if kind not in ('US', 'PROMOTER', 'VENUE', 'THIRD'):
        return None
    seller = {'kind': kind, 'label': ''}
    if kind == 'US' and billing_company_id:
        co = session.get(GroupCompany, billing_company_id)
        seller['label'] = (co.name if co else '') or 'Empresa del grupo'
    elif kind == 'PROMOTER' and promoter_id:
        p = session.get(Promoter, promoter_id)
        seller['label'] = (p.nick if p else '') or 'Promotor'
    elif kind == 'VENUE':
        v = session.get(Venue, venue_id) if venue_id else None
        seller['label'] = ((v.name if v else '') or (form.get('sale_seller_venue_label') or '').strip() or 'Recinto')
    elif kind == 'THIRD':
        third_kind = (form.get('sale_seller_third_kind') or 'promoter').strip().lower()
        third_id = to_uuid((form.get('sale_seller_third_id') or '').strip() or None)
        if third_kind == 'media' and third_id:
            m = session.get(MediaOutlet, third_id)
            if m:
                seller['media_id'] = str(third_id)
                seller['label'] = (m.name or '').strip()
        elif third_id:
            p = session.get(Promoter, third_id)
            if p:
                seller['promoter_id'] = str(third_id)
                seller['label'] = (p.nick or '').strip()
        if not seller.get('label'):
            seller['label'] = (form.get('sale_seller_third_label') or '').strip() or 'Tercero'
    if not seller['label']:
        seller['label'] = {'US': 'Empresa del grupo', 'PROMOTER': 'Promotor', 'VENUE': 'Recinto', 'THIRD': 'Tercero'}[kind]
    return seller


def _replace_concert_ticket_types_manual(session, concert_id, rows):
    """Reemplaza los tipos de entrada configurados a mano (NUNCA toca los espejados de
    Enterticket, et_managed=True; tampoco crea uno manual que choque con uno de ET)."""
    et_names = {
        (t.name or '').casefold()
        for t in session.query(ConcertTicketType).filter_by(concert_id=concert_id, et_managed=True).all()
    }
    session.query(ConcertTicketType).filter_by(concert_id=concert_id, et_managed=False).delete(synchronize_session=False)
    session.flush()
    for r in rows or []:
        if (r.get('name') or '').casefold() in et_names:
            continue
        session.add(ConcertTicketType(
            concert_id=concert_id,
            name=r['name'],
            qty_for_sale=int(r.get('qty_for_sale') or 0),
            price=r.get('price') or 0,
        ))


def _wizard_performance_payload(session, form, is_promo: bool) -> dict:
    """Bloque «¿En qué consiste la actividad?» de los eventos promocionales/TV/marca/otros:
    descripción + si el artista canta (nº de canciones, repertorio y formación)."""
    perf = {
        'sings': None,
        'songs_count': None,
        'songs': [],
        'formation_kind': None,
        'formation_text': '',
    }
    if not is_promo:
        return perf
    sings_raw = (form.get('artist_sings') or '').strip()
    if not sings_raw:
        return perf
    sings = _truthy(sings_raw)
    perf['sings'] = sings
    if not sings:
        return perf
    perf['songs_count'] = _parse_optional_positive_int((form.get('performance_songs_count') or '').strip())
    song_ids = []
    for raw in form.getlist('performance_song_ids[]'):
        sid = to_uuid((raw or '').strip() or None)
        if sid and sid not in song_ids:
            song_ids.append(sid)
    if song_ids:
        titles = {str(s.id): (s.title or '').strip() for s in session.query(Song).filter(Song.id.in_(song_ids)).all()}
        perf['songs'] = [{'id': str(sid), 'title': titles.get(str(sid), '')} for sid in song_ids if str(sid) in titles]
        if not perf['songs_count']:
            perf['songs_count'] = len(perf['songs'])
    fk = (form.get('formation_kind') or '').strip().upper()
    if fk in ('SOLO', 'PLUS'):
        perf['formation_kind'] = fk
        if fk == 'PLUS':
            perf['formation_text'] = (form.get('formation_text') or '').strip()
    return perf


def _performance_formation_label(perf: dict | None) -> str:
    perf = perf or {}
    fk = (perf.get('formation_kind') or '').strip().upper()
    if fk == 'SOLO':
        return 'Solo artista'
    if fk == 'PLUS':
        extra = (perf.get('formation_text') or '').strip()
        return f'Artista + {extra}' if extra else 'Artista +'
    return ''


# ==================== SIMULACIÓN → ACTIVIDADES REALES (volcado de datos) ====================
# Convertir una simulación NO es empezar de cero: las fechas simuladas se crean como conciertos
# reales con todo lo que ya estaba pensado (recinto, artista, empresa, aforo y tipos de entrada,
# cachés con sus condiciones, comisionistas, socios y presupuesto). La simulación no se borra:
# queda ARCHIVADA con el vínculo a lo que se creó, para poder consultar de dónde salió.

def _sim_budget_rows(act) -> list[dict]:
    """Gastos previstos de una fecha de la simulación, en el formato del presupuesto del concierto.

    OJO: en `ConcertBudgetItem`, `amount_net`/`amount_gross` son el TOTAL de la partida (así los
    suma la ficha de producción); `quantity` viaja solo como dato informativo."""
    rows = []
    for it in sorted((act.production_items or []), key=lambda x: (x.sort_order or 0)):
        qty = _sim_d(getattr(it, "quantity", 1) or 1)
        if qty <= 0:
            qty = Decimal("1")
        unit = _sim_d(getattr(it, "amount_net", 0) or 0)
        total = unit * qty
        iva = _sim_d(getattr(it, "iva_pct", 21) or 0)
        concept = (it.concept or "").strip() or "Gasto"
        iva_exempt = bool(getattr(it, "iva_exempt", False))
        if getattr(it, "is_variable", False):
            # El presupuesto del concierto no tiene gastos variables: la línea se deja a 0 con la
            # condición escrita en el concepto para no perder el dato.
            vt = (it.var_type or "").upper()
            vdesc = f"{_sim_d(it.var_value or 0)}%" if vt == "PERCENT" else f"{_sim_d(it.var_value or 0)} €/entrada"
            concept = f"{concept} (variable: {vdesc})"
            net = gross = Decimal("0")
            qty = Decimal("1")
        elif iva_exempt:
            net = gross = total
        elif getattr(it, "includes_iva", False):
            gross = total
            net = (total / (Decimal("1") + iva / Decimal("100"))) if iva else total
        else:
            net = total
            gross = total * (Decimal("1") + iva / Decimal("100")) if iva else total
        rows.append({
            "category": _sim_expense_cat(it.category),
            "concept": concept,
            "amount_net": net.quantize(Decimal("0.01")),
            "amount_gross": gross.quantize(Decimal("0.01")),
            "quantity": qty,
            "iva_pct": (Decimal("0") if iva_exempt else iva),
            "iva_exempt": iva_exempt,
        })
    return rows


def _sim_add_budget_rows(session, concert_id, rows, start_order: int = 0) -> int:
    for n, r in enumerate(rows or []):
        session.add(ConcertBudgetItem(
            concert_id=concert_id,
            category=r["category"],
            concept=r["concept"],
            amount_net=r["amount_net"],
            amount_gross=r["amount_gross"],
            quantity=r.get("quantity") or Decimal("1"),
            iva_pct=r.get("iva_pct") if r.get("iva_pct") is not None else Decimal("21"),
            iva_exempt=bool(r.get("iva_exempt")),
            sort_order=start_order + n * 10,
        ))
    return len(rows or [])


def _copy_simulation_budget_to_concert(session, sim_id, concert_id) -> int:
    """Todos los gastos previstos de la simulación → presupuesto de UN concierto (lo usa el
    asistente cuando se crea el concierto desde una simulación de una sola fecha)."""
    sim = session.get(Simulation, sim_id)
    if not sim:
        return 0
    rows = []
    for act in (sim.activities or []):
        if getattr(act, "is_shared", False):
            continue
        rows.extend(_sim_budget_rows(act))
    return _sim_add_budget_rows(session, concert_id, rows)


def _sim_ticket_rows(act) -> list[dict]:
    """Categorías de entrada simuladas → tipos de entrada reales. Los nombres se hacen únicos
    porque `concert_ticket_types` tiene UNIQUE(concert_id, name) y en la simulación puede haber
    la misma categoría en Pista y en Grada."""
    zone_labels = {"PISTA": "Pista", "GRADA": "Grada", "PALCO": "Palco"}
    rows, used = [], set()
    for cat in sorted((act.ticket_categories or []), key=lambda x: (x.sort_order or 0)):
        zone = (cat.zone or "PISTA").strip().upper()
        base = (cat.name or "").strip() or zone_labels.get(zone, zone.capitalize())
        name = base
        if name.casefold() in used:
            name = f"{base} · {zone_labels.get(zone, zone.capitalize())}"
        n = 2
        while name.casefold() in used:
            name = f"{base} ({n})"
            n += 1
        used.add(name.casefold())
        rows.append({
            "name": name,
            "qty_for_sale": int(cat.quantity or 0),
            "price": _sim_d(cat.price_net or 0),
            "invites_total": int(cat.invitations or 0),
            "zone": zone,
        })
    return rows


def _sim_cache_rows(act) -> list[dict]:
    """Cachés simulados → `ConcertCache`. Los fijos van tal cual; los variables se traducen a la
    condición equivalente de la ficha (`config.option`) y se guarda el original en `config` para
    no perder los matices fiscales que el concierto no modela."""
    rows = []
    for ch in sorted((act.caches or []), key=lambda x: (x.sort_order or 0)):
        origin = {
            "from_simulation": True,
            "label": (ch.label or None),
            "includes_iva": bool(ch.includes_iva),
            "includes_retention": bool(ch.includes_retention),
            "retention_exempt": bool(ch.retention_exempt),
        }
        mode = (ch.mode or "FIXED").strip().upper()
        if mode != "VARIABLE":
            amount = _sim_d(ch.amount or 0)
            if amount == 0:
                continue
            rows.append({
                "kind": "FIXED", "concept": None, "amount": amount,
                "pct": None, "pct_base": None, "config": origin,
            })
            continue
        value = _sim_d(ch.var_value or 0)
        if value == 0:
            continue
        thr_type = (ch.var_threshold_type or "").strip().upper()
        thr_value = _sim_d(ch.var_threshold_value or 0)
        cfg = dict(origin)
        if (ch.var_type or "").strip().upper() == "PERCENT":
            cfg["mode"] = "PERCENT"
            if thr_type == "TICKETS":
                cfg["option"] = "PCT_FROM_TICKETS"
                cfg["min_tickets"] = int(thr_value)
            else:
                cfg["option"] = "PCT_FROM_REVENUE"
                cfg["min_revenue"] = float(thr_value)
            rows.append({
                "kind": "VARIABLE", "concept": None, "amount": None,
                "pct": value, "pct_base": "GROSS", "config": cfg,
            })
        else:
            # PER_TICKET: importe fijo por entrada vendida a partir de la entrada X.
            cfg["mode"] = "FIXED"
            cfg["option"] = "FIXED_PER_TICKET_FROM"
            cfg["from_ticket"] = int(thr_value) if thr_type == "TICKETS" and thr_value > 0 else 1
            if thr_type == "AMOUNT" and thr_value > 0:
                cfg["min_revenue"] = float(thr_value)
            rows.append({
                "kind": "VARIABLE", "concept": None, "amount": value,
                "pct": None, "pct_base": None, "config": cfg,
            })
    return rows


def _sim_commission_rows(session, act) -> list[dict]:
    """Comisionistas simulados → `ConcertZoneAgent`. Un comisionista que sea un MEDIO se espeja a
    tercero (la FK apunta a `promoters`), igual que hace el asistente."""
    rows = []
    for cm in sorted((act.commissions or []), key=lambda x: (x.sort_order or 0)):
        promoter_id = cm.promoter_id
        if not promoter_id and cm.media_outlet_id:
            mirror = _ensure_promoter_for_media(session, cm.media_outlet_id)
            if mirror is not None:
                session.flush()
                promoter_id = mirror.id
        if not promoter_id:
            continue
        concept = (cm.name or "").strip() or None
        exempt = _sim_d(cm.exempt_amount or 0)
        if (cm.mode or "FIXED").strip().upper() == "VARIABLE" and (cm.var_type or "").strip().upper() == "PERCENT":
            pct = _sim_d(cm.var_value or 0)
            if pct == 0:
                continue
            rows.append({
                "id": str(promoter_id), "commission_type": "PERCENT", "commission_pct": pct,
                "commission_base": "GROSS", "commission_amount": None,
                "exempt_amount": (exempt or None), "concept": concept,
            })
            continue
        amount = _sim_d(cm.amount or 0) or _sim_d(cm.var_value or 0)
        if amount == 0:
            continue
        rows.append({
            "id": str(promoter_id), "commission_type": "AMOUNT", "commission_pct": None,
            "commission_base": None, "commission_amount": amount,
            "exempt_amount": (exempt or None), "concept": concept,
        })
    return rows


def _sim_partner_share_rows(sim, act) -> tuple[list[dict], list[dict]]:
    """Socios → participaciones del concierto. Reparten el RESULTADO, así que la base es PROFIT."""
    companies, promoters = [], []
    for p in _sim_partners_for_activity(sim, act):
        pct = _sim_d(p.pct or 0)
        if pct <= 0:
            continue
        pct_int = int(pct.quantize(Decimal("1")))
        if pct_int <= 0:
            continue
        if p.company_id:
            companies.append({"id": str(p.company_id), "pct": pct_int, "pct_base": "PROFIT",
                              "amount": None, "amount_base": None})
        elif p.promoter_id:
            promoters.append({"id": str(p.promoter_id), "pct": pct_int, "pct_base": "PROFIT",
                              "amount": None, "amount_base": None})
    return companies, promoters


def _sim_sale_type(sim, default: str = "EMPRESA") -> str:
    """Tipo de venta del concierto que sale de la simulación: PARTICIPADOS si hay socios de
    verdad (un tercero, o más de una empresa repartiéndose), si no el que llegue por defecto."""
    rows = [p for p in (sim.partners or []) if _sim_d(p.pct or 0) > 0]
    if any(p.promoter_id for p in rows) or len({(str(p.company_id), str(p.promoter_id)) for p in rows}) > 1:
        return "PARTICIPADOS"
    return default


def _ensure_artist_for_event(session, event):
    """Artista ESPEJO de un evento, creándolo la primera vez.

    Una actividad (Concert) exige artista y un EVENTO no lo es, así que para que una simulación de
    evento se pueda convertir en actividades se espeja el evento como artista con su nombre y su
    logo. Se reconoce por `Artist.event_id` y NO sale en el listado de artistas ni en sus buscadores
    (el evento sigue estando en Bases de datos → Eventos). Mismo patrón que `_ensure_promoter_for_media`.
    """
    if event is None:
        return None
    existente = session.query(Artist).filter(Artist.event_id == event.id).first()
    if existente is not None:
        # Si al evento le cambian el nombre o el logo, el espejo lo sigue.
        nombre = (event.name or "").strip()
        if nombre and existente.name != nombre and not (
                session.query(Artist.id).filter(func.lower(Artist.name) == nombre.lower(),
                                                Artist.id != existente.id).first()):
            existente.name = nombre
        if event.logo_url and not (existente.photo_url or "").strip():
            existente.photo_url = event.logo_url
        return existente
    nombre = (event.name or "Evento").strip()[:200]
    # `Artist.name` es ÚNICO: si ya hay un artista con ese nombre, el espejo lleva sufijo.
    if session.query(Artist.id).filter(func.lower(Artist.name) == nombre.lower()).first():
        nombre = f"{nombre} (evento)"[:200]
    espejo = Artist(name=nombre, photo_url=event.logo_url, event_id=event.id)
    session.add(espejo)
    session.flush()
    return espejo


def _sim_activity_artist_id(sim, act, session=None):
    """Artista de la fecha: el suyo, el de la simulación o el primero del lineup (festivales).

    Si la simulación es de un EVENTO (no hay artista en ninguna parte), se usa el artista ESPEJO del
    evento: así la conversión a actividades funciona igual y en las pantallas se ve el nombre y el
    logo del evento donde iría el artista.
    """
    if getattr(act, "artist_id", None):
        return act.artist_id
    if sim.artist_id:
        return sim.artist_id
    for row in (sim.lineup or []):
        if row.artist_id:
            return row.artist_id
    if session is not None and getattr(sim, "event_id", None):
        evento = getattr(sim, "event", None) or session.get(AppEvent, sim.event_id)
        espejo = _ensure_artist_for_event(session, evento)
        if espejo is not None:
            return espejo.id
    return None


def _simulation_dump_activity(session, sim, act, *, sale_type, group_name=None,
                              activity_type="CONCIERTO", tour=None, cycle=None) -> tuple[object | None, str]:
    """Crea el CONCIERTO real de una fecha simulada con todo lo que la simulación ya sabía.

    Devuelve (concierto, motivo). Si no se puede crear devuelve (None, motivo) — el concierto
    exige fecha y artista, así que una fecha «por definir» o sin artista no se puede materializar
    y se deja constancia para avisar al usuario."""
    label = (act.label or "").strip()
    if act.date_unknown or not act.event_date:
        return None, f"«{label or 'Fecha sin nombre'}»: sin fecha concreta"
    # En una simulación de EVENTO no hay artista: se usa el espejo del evento (ver
    # `_ensure_artist_for_event`), así la conversión funciona igual con el evento como sujeto.
    artist_id = _sim_activity_artist_id(sim, act, session)
    if not artist_id:
        return None, f"«{label or act.event_date.strftime('%d/%m/%Y')}»: sin artista ni evento"

    tickets = _sim_ticket_rows(act)
    capacity = sum(int(t["qty_for_sale"] or 0) for t in tickets)
    venue = act.venue if not act.venue_unknown else None
    concert = Concert(
        date=act.event_date,
        festival_name=(label or group_name or None),
        venue_id=(venue.id if venue else None),
        manual_venue_name=(None if venue else (label or None)),
        sale_type=sale_type,
        artist_id=artist_id,
        artist_ids=[str(artist_id)],
        activity_type=activity_type,
        capacity=capacity,
        status="BORRADOR",
        group_company_id=sim.managing_company_id,
        billing_company_id=sim.managing_company_id,
        purchased_tour_id=(tour.id if tour is not None else None),
        cycle_festival_id=(cycle.id if cycle is not None else None),
        event_id=getattr(sim, "event_id", None),
        contracting_payload={"simulation_id": str(sim.id), "simulation_activity_id": str(act.id)},
        ticketing_payload={"ticket_types": [
            {"name": t["name"], "price": float(t["price"]), "qty_for_sale": t["qty_for_sale"],
             "invites_total": t["invites_total"], "zone": t["zone"]}
            for t in tickets
        ]},
    )
    session.add(concert)
    session.flush()

    if tickets:
        _replace_concert_ticket_types_manual(session, concert.id, tickets)
    cache_rows = _sim_cache_rows(act)
    if cache_rows:
        _replace_concert_caches(session, concert.id, cache_rows)
    zone_rows = _sim_commission_rows(session, act)
    if zone_rows:
        _replace_concert_zone_agents(session, concert.id, zone_rows)
    company_rows, promoter_rows = _sim_partner_share_rows(sim, act)
    if company_rows:
        _replace_concert_company_shares(session, concert.id, company_rows)
    if promoter_rows:
        _replace_concert_promoter_shares(session, concert.id, promoter_rows)
    _sim_add_budget_rows(session, concert.id, _sim_budget_rows(act))
    return concert, ""


def _simulation_general_expenses(sim) -> list[dict]:
    """Gastos generales del contenedor compartido (ciclo/gira) → bloque «Producción general»."""
    out = []
    for act in (sim.activities or []):
        if not getattr(act, "is_shared", False):
            continue
        for r in _sim_budget_rows(act):
            out.append({"concept": r["concept"], "amount": float(r["amount_net"])})
    return out


def _simulation_mark_converted(sim, *, kind: str, target_id, target_name: str, concert_ids: list) -> None:
    """La simulación pasa a ARCHIVADA con el vínculo a lo que se creó. No se borra nada: se puede
    consultar desde «Archivadas» y restaurar si hiciera falta."""
    settings = dict(sim.settings or {})
    settings["converted"] = {
        "kind": kind,
        "target_id": (str(target_id) if target_id else None),
        "target_name": target_name,
        "concert_ids": [str(x) for x in (concert_ids or [])],
        "at": datetime.now(TZ_MADRID).isoformat(),
    }
    sim.settings = settings
    sim.status = "ARCHIVED"


def _parse_wizard_promoter_share_rows(form) -> list[dict]:
    rows = []
    ids = form.getlist('wizard_partner_promoter_id[]')
    kinds = form.getlist('wizard_partner_kind[]')
    company_ids = form.getlist('wizard_partner_company_id[]')
    pcts = form.getlist('wizard_partner_pct[]')
    bases = form.getlist('wizard_partner_base[]')
    for i, raw_id in enumerate(ids or []):
        raw_id = (raw_id or '').strip()
        if not raw_id:
            continue
        pct = _parse_optional_decimal(pcts[i] if i < len(pcts) else None)
        if pct is None:
            continue
        kind = ((kinds[i] if i < len(kinds) else '') or 'promoter').strip().lower()
        rows.append({
            'id': raw_id,
            'kind': 'media' if kind == 'media' else 'promoter',
            'company_id': (company_ids[i] if i < len(company_ids) else '').strip() or None,
            'pct': pct,
            'pct_base': _norm_base(bases[i] if i < len(bases) else None),
            'amount': None,
            'amount_base': None,
        })
    dedup = {}
    for row in rows:
        dedup[(row['id'], row.get('company_id') or '')] = row
    return list(dedup.values())


def _resolve_wizard_entity_rows(session, rows) -> list[dict]:
    """Los socios/comisionistas del asistente pueden ser MEDIOS (buscador mixto): se espejan
    a su tercero (`_ensure_promoter_for_media`) porque las tablas apuntan a promoters."""
    out = []
    for row in rows or []:
        if (row.get('kind') or 'promoter') == 'media':
            try:
                mirrored = _ensure_promoter_for_media(session, to_uuid(row.get('id')))
            except Exception:
                mirrored = None
            if not mirrored:
                continue
            row = dict(row)
            row['id'] = str(mirrored.id)
            row['company_id'] = None
        out.append(row)
    return out


def _parse_wizard_zone_rows(form) -> list[dict]:
    rows = []
    ids = form.getlist('wizard_zone_promoter_id[]')
    kinds = form.getlist('wizard_zone_kind[]')
    company_ids = form.getlist('wizard_zone_company_id[]')
    modes = form.getlist('wizard_zone_mode[]')
    amounts = form.getlist('wizard_zone_amount[]')
    pcts = form.getlist('wizard_zone_pct[]')
    bases = form.getlist('wizard_zone_base[]')
    concepts = form.getlist('wizard_zone_concept[]')
    for i, raw_id in enumerate(ids or []):
        raw_id = (raw_id or '').strip()
        if not raw_id:
            continue
        kind = ((kinds[i] if i < len(kinds) else '') or 'promoter').strip().lower()
        kind = 'media' if kind == 'media' else 'promoter'
        mode = (modes[i] if i < len(modes) else 'PERCENT').strip().upper()
        if mode not in {'PERCENT', 'FIXED'}:
            mode = 'PERCENT'
        if mode == 'FIXED':
            amount = _parse_optional_decimal(amounts[i] if i < len(amounts) else None)
            if amount is None:
                continue
            rows.append({
                'id': raw_id,
                'kind': kind,
                'company_id': (company_ids[i] if i < len(company_ids) else '').strip() or None,
                'commission_type': 'AMOUNT',
                'commission_pct': None,
                'commission_base': None,
                'commission_amount': amount,
                'concept': (concepts[i] if i < len(concepts) else '').strip() or None,
                'exempt_amount': None,
            })
        else:
            pct = _parse_optional_decimal(pcts[i] if i < len(pcts) else None)
            if pct is None:
                continue
            rows.append({
                'id': raw_id,
                'kind': kind,
                'company_id': (company_ids[i] if i < len(company_ids) else '').strip() or None,
                'commission_type': 'PERCENT',
                'commission_pct': pct,
                'commission_base': _norm_base(bases[i] if i < len(bases) else None),
                'commission_amount': None,
                'concept': (concepts[i] if i < len(concepts) else '').strip() or None,
                'exempt_amount': None,
            })
    return rows


@app.post('/conciertos/wizard/create', endpoint='concert_wizard_create')
@admin_required
def concert_wizard_create():
    if not (is_master() or can_edit_concerts()):
        return forbid('Tu usuario no tiene permisos para crear conciertos.')
    session = db()
    try:
        mode = (request.form.get('wizard_mode') or 'direct').strip().lower()
        # EL SUJETO puede ser un ARTISTA o un EVENTO (un evento funciona igual que un artista: las
        # actividades son las mismas, solo que cuelgan del evento). Si el evento no existe todavía se
        # crea aquí mismo con el nombre que se escriba. El artista de la actividad es el ESPEJO del
        # evento (`_ensure_artist_for_event`), porque Concert.artist_id no puede ir vacío.
        subject_kind = (request.form.get('subject_kind') or 'ARTIST').strip().upper()
        event_uuid = None
        if subject_kind == 'EVENT':
            event_uuid = to_uuid((request.form.get('event_id') or '').strip() or None)
            nuevo_evento = (request.form.get('new_event_name') or '').strip()
            evento = session.get(AppEvent, event_uuid) if event_uuid else None
            if evento is None and nuevo_evento:
                evento = (session.query(AppEvent)
                          .filter(func.lower(AppEvent.name) == nuevo_evento.lower()).first())
                if evento is None:
                    evento = AppEvent(name=nuevo_evento[:200])
                    session.add(evento)
                    session.flush()
            if evento is None:
                raise ValueError('Elige un evento o escribe el nombre del evento nuevo.')
            event_uuid = evento.id
            espejo = _ensure_artist_for_event(session, evento)
            session.flush()
            request_artist_ids = [str(espejo.id)]
        else:
            request_artist_ids = None
        raw_artist_ids = (request_artist_ids if request_artist_ids is not None
                          else request.form.getlist('artist_id') + request.form.getlist('artist_ids'))
        artist_ids = []
        for raw_artist_id in raw_artist_ids:
            raw_artist_id = (raw_artist_id or '').strip()
            if not raw_artist_id:
                continue
            try:
                uid = to_uuid(raw_artist_id)
            except Exception:
                continue
            if uid and uid not in artist_ids:
                artist_ids.append(uid)
        if not artist_ids:
            raise ValueError('Debes seleccionar al menos un artista.' if subject_kind != 'EVENT'
                             else 'No se pudo preparar el evento.')
        artist_id = artist_ids[0]
        artist_ids_payload = [str(uid) for uid in artist_ids]
        event_date = parse_date(request.form.get('date') or '')
        activity_type = (request.form.get('activity_type') or 'CONCIERTO').strip().upper()
        activity_type_aliases = {
            'CONCIERTO': 'CONCIERTO',
            'FESTIVAL': 'FESTIVAL',
            'EVENTO_PROMOCIONAL': 'EVENTO_PROMOCIONAL',
            'PROMOCIONAL': 'EVENTO_PROMOCIONAL',
            'PROGRAMA_TV': 'TV',
            'TV': 'TV',
            'MARCA': 'MARCA',
            'ACCION_MARCA': 'MARCA',
            'OTROS': 'OTROS',
        }
        activity_type = activity_type_aliases.get(activity_type, 'CONCIERTO')
        activity_subtype = (request.form.get('activity_subtype') or request.form.get('concert_kind') or '').strip().upper() or None
        sale_type = (request.form.get('sale_type') or 'EMPRESA').strip().upper()
        if sale_type not in CONCERT_SALE_TYPES_ALL_SET:
            sale_type = 'EMPRESA'
        # Chips del gestor de tags (concert_tags[]) con fallback al campo de texto legacy.
        hashtags = _dedupe_concert_tags(request.form.getlist('concert_tags[]')) or _parse_hashtag_text(request.form.get('wizard_hashtags_text'))
        billing_company_id = to_uuid((request.form.get('billing_company_id') or '').strip() or None)
        festival_name = (request.form.get('festival_name') or '').strip() or None
        venue_id = to_uuid((request.form.get('venue_id') or '').strip() or None)
        manual_venue_name = (request.form.get('manual_venue_name') or '').strip() or None
        manual_venue_address = (request.form.get('manual_venue_address') or '').strip() or None
        manual_municipality = (request.form.get('manual_municipality') or '').strip() or None
        manual_province = (request.form.get('manual_province') or '').strip() or None
        manual_postal_code = (request.form.get('manual_postal_code') or '').strip() or None
        if not (venue_id or manual_municipality or manual_province):
            raise ValueError('Debes indicar recinto o al menos municipio y provincia.')

        # Si el usuario selecciona un recinto existente y completa datos de
        # localización que estaban vacíos o se han corregido, dejamos el recinto
        # actualizado para futuras altas.
        if venue_id:
            venue_row = session.get(Venue, venue_id)
            if venue_row:
                if manual_venue_address:
                    venue_row.address = manual_venue_address
                if manual_municipality:
                    venue_row.municipality = manual_municipality
                if manual_province:
                    venue_row.province = manual_province

        # ¿Es una actividad promocional (no concierto/festival)? Cambia pasos y opciones.
        is_promo_activity = activity_type in ('EVENTO_PROMOCIONAL', 'TV', 'MARCA', 'OTROS')
        performance = _wizard_performance_payload(session, request.form, is_promo_activity)
        formation_label = _performance_formation_label(performance) or (request.form.get('formation') or '').strip()

        wizard_payload = {
            'activity_type': activity_type,
            'activity_subtype': activity_subtype,
            'artist_ids': artist_ids_payload,
            'description': (request.form.get('activity_description') or '').strip(),
            'performance': performance,
            'formation': formation_label,
            'performance_duration': (request.form.get('performance_duration') or '').strip(),
            'meet_greet': {
                'enabled': _truthy(request.form.get('meet_greet')),
                'quantity': (request.form.get('meet_greet_quantity') or '').strip(),
                'moment': (request.form.get('meet_greet_moment') or '').strip(),
            },
            'other_commitments': (request.form.get('other_commitments') or '').strip(),
            'carteleria': (request.form.get('artwork_choice') or request.form.get('artwork_owner') or '').strip(),
            'announcement_note': (request.form.get('announcement_note') or '').strip(),
            'billing_plan': _parse_payment_terms_rows(request.form),
        }
        ticket_type_rows = _parse_wizard_ticket_types(request.form)
        ticketing_payload = {
            'total_capacity': (request.form.get('capacity_total') or request.form.get('capacity') or '').strip(),
            'sale_capacity': (request.form.get('capacity_sale') or '').strip(),
            'sale_owner': (request.form.get('sale_owner') or '').strip(),
            'ticket_types': ticket_type_rows,
            'channels': request.form.getlist('ticketer_ids[]') or request.form.getlist('ticketer_id[]'),
            'invitations': request.form.getlist('invitation_qty[]'),
        }
        equipment_payload = {
            'mode': (request.form.get('equipment_mode') or '').strip(),
            'amount': (request.form.get('equipment_amount') or '').strip(),
            'notes': (request.form.get('equipment_notes') or request.form.get('equipment_note_body[]') or '').strip(),
        }
        promoter_costs_payload = _parse_promoter_costs_form(request.form)

        if mode == 'request_sheet':
            promoter_email = (request.form.get('promoter_email') or '').strip()
            if not promoter_email:
                raise ValueError('Debes indicar el email del promotor.')
            concert = Concert(
                date=event_date,
                festival_name=festival_name,
                venue_id=venue_id,
                sale_type=sale_type,
                event_id=event_uuid,
                artist_id=artist_id,
                artist_ids=artist_ids_payload,
                activity_type=activity_type,
                activity_subtype=activity_subtype,
                contracting_payload=wizard_payload,
                ticketing_payload=ticketing_payload,
                equipment_payload=equipment_payload,
                promoter_costs_payload=promoter_costs_payload,
                capacity=0,
                no_capacity=True,
                sale_start_date=None,
                sale_start_tbc=True,
                break_even_ticket=None,
                sold_out=False,
                group_company_id=billing_company_id if sale_type == 'EMPRESA' else None,
                billing_company_id=billing_company_id,
                hashtags=hashtags,
                status='BORRADOR',
                manual_venue_name=manual_venue_name,
                manual_venue_address=manual_venue_address,
                manual_municipality=manual_municipality,
                manual_province=manual_province,
                manual_postal_code=manual_postal_code,
            )
            session.add(concert)
            session.flush()
            artist = session.get(Artist, artist_id)
            sheet = ConcertContractSheet(
                concert_id=concert.id,
                public_token=uuid.uuid4().hex,
                promoter_email=promoter_email,
                status='REQUESTED',
                request_payload={
                    'artist_name': (artist.name if artist else ''),
                    'gala_date': event_date.isoformat() if event_date else '',
                    'gala_venue': _concert_venue_name(concert),
                    'gala_municipality': _concert_city(concert),
                    'gala_province': _concert_province_value(concert),
                    'hashtags': hashtags,
                    'sale_type': sale_type,
                },
            )
            session.add(sheet)
            session.commit()
            concert = session.get(Concert, concert.id)
            sheet = session.query(ConcertContractSheet).filter(ConcertContractSheet.concert_id == concert.id).first()
            company = session.get(GroupCompany, billing_company_id) if billing_company_id else None
            form_url = _external_url_for('concert_contract_public_form', token=sheet.public_token)
            logo_html = ''
            if company and company.logo_url:
                logo_html = f'<div style="margin-bottom:20px;"><img src="{company.logo_url}" style="max-height:64px;max-width:220px;"></div>'
            photo_html = ''
            if artist and artist.photo_url:
                photo_html = f'<img src="{artist.photo_url}" style="width:70px;height:70px;object-fit:cover;border-radius:50%;">'
            html_body = f'''<div style="font-family:Arial,sans-serif;color:#1f2937;">{logo_html}<h2 style="margin:0 0 16px;">Solicitud ficha de contratación</h2><div style="border:1px solid #e5e7eb;border-radius:12px;padding:16px;margin-bottom:18px;"><div style="display:flex;gap:16px;align-items:center;"><div>{photo_html}</div><div><div style="font-size:18px;font-weight:700;">{artist.name if artist else ''}</div><div>Fecha: {event_date.strftime('%d/%m/%Y')}</div><div>{_concert_venue_name(concert) or 'Recinto pendiente'}</div><div>{_concert_city(concert)} {('· ' + _concert_province_value(concert)) if _concert_province_value(concert) else ''}</div></div></div></div><p>Puedes cumplimentar la ficha de contratación desde este enlace:</p><p><a href="{form_url}" style="display:inline-block;background:#0d6efd;color:#fff;padding:10px 16px;border-radius:8px;text-decoration:none;">Cumplimentar ficha de contratación</a></p><p style="color:#6b7280;font-size:13px;">Si el enlace deja de estar disponible es porque la ficha ya fue enviada o cerrada.</p></div>'''
            ok, error = _send_optional_email(promoter_email, 'Solicitud ficha de contratación', html_body, text_body=form_url)
            if ok:
                flash('Concierto creado en borrador y ficha de contratación enviada al promotor.', 'success')
            else:
                flash(f'Concierto creado en borrador. No se pudo enviar el correo automáticamente: {error}', 'warning')
            return redirect(url_for('concert_detail_view', cid=concert.id, tab='ficha'))

        promoter_id = to_uuid((request.form.get('promoter_id') or '').strip() or None)
        promoter_company_id = to_uuid((request.form.get('promoter_company_id') or '').strip() or None)
        # El promotor también puede ser un MEDIO de comunicación (espejado a tercero).
        if not promoter_id:
            promoter_media_id = to_uuid((request.form.get('promoter_media_id') or '').strip() or None)
            if promoter_media_id:
                media_promoter = _ensure_promoter_for_media(session, promoter_media_id)
                promoter_id = media_promoter.id if media_promoter else None
        # Sociedad nueva creada sobre la marcha desde el propio asistente.
        new_company_name = (request.form.get('new_promoter_company_name') or '').strip()
        if promoter_id and not promoter_company_id and new_company_name:
            new_company = PromoterCompany(
                promoter_id=promoter_id,
                legal_name=new_company_name,
                tax_id=(request.form.get('new_promoter_company_tax_id') or '').strip() or None,
            )
            session.add(new_company)
            session.flush()
            promoter_company_id = new_company.id
        if sale_type == 'EMPRESA':
            # En conciertos a empresa la contraparte es la empresa del grupo
            # seleccionada arriba; no se fuerza un tercero/promotor externo.
            promoter_id = None
            promoter_company_id = None

        show_time_tbc = _truthy(request.form.get('show_time_tbc'))
        doors_time_tbc = _truthy(request.form.get('doors_time_tbc'))
        do_not_announce = _truthy(request.form.get('do_not_announce'))
        announcement_date = None if do_not_announce else parse_optional_date(request.form.get('announcement_date'))

        # Entrada: ¿evento gratuito o con venta de entradas? (paso «Entradas» del asistente).
        entry_mode = (request.form.get('entry_mode') or '').strip().upper()
        if entry_mode not in ('FREE', 'SALE'):
            entry_mode = ''
        if entry_mode == 'FREE':
            no_capacity = _truthy(request.form.get('free_capacity_unlimited'))
            capacity = 0 if no_capacity else (_parse_optional_positive_int(request.form.get('free_capacity')) or 0)
            sale_start_tbc = False
            sale_start_date = None
            ticket_type_rows = []
            ticketing_payload['ticket_types'] = []
        elif entry_mode == 'SALE':
            no_capacity = False
            qty_sum = sum(int(r.get('qty_for_sale') or 0) for r in ticket_type_rows)
            capacity = _parse_optional_positive_int(request.form.get('capacity')) or qty_sum or 0
            sale_start_tbc = _truthy(request.form.get('sale_start_tbc'))
            sale_start_date = None if sale_start_tbc else parse_optional_date(request.form.get('sale_start_date'))
        else:
            # Compatibilidad con formularios antiguos (sin entry_mode).
            no_capacity = _truthy(request.form.get('no_capacity'))
            capacity = 0 if no_capacity else (_parse_optional_positive_int(request.form.get('capacity')) or 0)
            sale_start_tbc = _truthy(request.form.get('sale_start_tbc'))
            sale_start_date = None if sale_start_tbc else parse_optional_date(request.form.get('sale_start_date'))

        sale_seller = None
        if entry_mode == 'SALE':
            sale_seller = _parse_wizard_sale_seller(
                session, request.form,
                billing_company_id=billing_company_id,
                promoter_id=promoter_id,
                venue_id=venue_id,
            )
        ticketing_payload['entry_mode'] = entry_mode or None
        ticketing_payload['free_capacity_unlimited'] = bool(entry_mode == 'FREE' and no_capacity)
        if sale_seller:
            ticketing_payload['sale_seller'] = sale_seller
            if not ticketing_payload.get('sale_owner'):
                ticketing_payload['sale_owner'] = sale_seller.get('label') or ''

        # Invitaciones pactadas: por tipo de entrada o total por contrato.
        invitations_mode = (request.form.get('invitations_mode') or '').strip().upper()
        invitation_rows = []
        if invitations_mode == 'TOTAL':
            inv_total = _parse_optional_positive_int(request.form.get('invitations_total')) or 0
            if inv_total:
                invitation_rows = [{'category': 'Invitaciones por contrato', 'artist_qty': 0, 'office_qty': inv_total, 'total_qty': inv_total}]
            ticketing_payload['invitations_total'] = inv_total
        elif invitations_mode == 'BY_TYPE':
            for r in ticket_type_rows:
                inv_total = int(r.get('invites_total') or 0)
                if inv_total:
                    invitation_rows.append({'category': r['name'], 'artist_qty': 0, 'office_qty': inv_total, 'total_qty': inv_total})
        if invitations_mode:
            ticketing_payload['invitations_mode'] = invitations_mode
        if not invitation_rows:
            invitation_rows = _parse_invitation_rows(request.form)

        # Estado inicial elegido de forma visual en el asistente (por defecto BORRADOR).
        initial_status = _norm_status(request.form.get('status'))

        concert = Concert(
            date=event_date,
            festival_name=festival_name,
            venue_id=venue_id,
            sale_type=sale_type,
            event_id=event_uuid,
            promoter_id=promoter_id,
            promoter_company_id=promoter_company_id,
            artist_id=artist_id,
            artist_ids=artist_ids_payload,
            activity_type=activity_type,
            activity_subtype=activity_subtype,
            contracting_payload=wizard_payload,
            ticketing_payload=ticketing_payload,
            equipment_payload=equipment_payload,
            promoter_costs_payload=promoter_costs_payload,
            capacity=capacity,
            no_capacity=no_capacity,
            sale_start_date=sale_start_date,
            sale_start_tbc=sale_start_tbc,
            break_even_ticket=None,
            sold_out=False,
            group_company_id=billing_company_id if sale_type == 'EMPRESA' else None,
            billing_company_id=billing_company_id,
            hashtags=hashtags,
            status=initial_status,
            manual_venue_name=manual_venue_name,
            manual_venue_address=manual_venue_address,
            manual_municipality=manual_municipality,
            manual_province=manual_province,
            manual_postal_code=manual_postal_code,
            show_time=(request.form.get('show_time') or '').strip() or None,
            doors_time=(request.form.get('doors_time') or '').strip() or None,
            show_time_tbc=show_time_tbc,
            doors_time_tbc=doors_time_tbc,
            invitations_json=invitation_rows,
            payment_terms_json=_parse_payment_terms_rows(request.form),
            announcement_date=announcement_date,
            do_not_announce=do_not_announce,
        )
        session.add(concert)
        session.flush()

        # Tipos de entrada del asistente → tipos reales (nombre, precio, cupo) del concierto.
        if ticket_type_rows:
            _replace_concert_ticket_types_manual(session, concert.id, ticket_type_rows)

        # Conversión desde una SIMULACIÓN: los gastos previstos pasan a ser el PRESUPUESTO.
        _wsim = to_uuid((request.form.get('wizard_simulation_id') or '').strip() or None)
        if _wsim:
            try:
                _copy_simulation_budget_to_concert(session, _wsim, concert.id)
            except Exception:
                app.logger.exception('[wizard] no se pudo copiar el presupuesto de la simulación')

        # Meet & Greet marcado en el asistente → actividad MG en la hoja de ruta.
        _sync_meet_greet_roadmap(concert)

        # Personas de contacto elegidas en el asistente (producción / ticketing / comunicación).
        _replace_concert_contacts(session, concert.id, _parse_concert_contacts_form(request.form))

        # Hojas de ruta que tendrá la actividad (general / técnica). Por defecto, las dos.
        _set_roadmap_kinds(concert, _parse_roadmap_kinds_form(request.form))

        # Vínculo opcional a una gira comprada / ciclo o festival (paso del asistente).
        _ptid = (request.form.get('wizard_purchased_tour_id') or '').strip()
        _cfid = (request.form.get('wizard_cycle_festival_id') or '').strip()
        if _ptid:
            try:
                concert.purchased_tour_id = to_uuid(_ptid)
            except Exception:
                pass
        if _cfid:
            try:
                concert.cycle_festival_id = to_uuid(_cfid)
            except Exception:
                pass

        _replace_concert_promoter_shares(session, concert.id, _resolve_wizard_entity_rows(session, _parse_wizard_promoter_share_rows(request.form)))
        _replace_concert_zone_agents(session, concert.id, _resolve_wizard_entity_rows(session, _parse_wizard_zone_rows(request.form)))
        _replace_concert_company_shares(session, concert.id, [])

        cache_rows = _parse_cache_rows(
            request.form.getlist('cache_kind[]'),
            request.form.getlist('cache_concept[]'),
            request.form.getlist('cache_amount[]'),
            request.form.getlist('cache_var_mode[]'),
            request.form.getlist('cache_var_option[]'),
            request.form.getlist('cache_from_ticket[]'),
            request.form.getlist('cache_min_tickets[]'),
            request.form.getlist('cache_min_revenue[]'),
            request.form.getlist('cache_pct[]'),
            request.form.getlist('cache_pct_base[]'),
            request.form.getlist('cache_ticket_type[]'),
        )
        _replace_concert_caches(session, concert.id, cache_rows)
        _upsert_equipment_from_request(session, concert.id)
        _add_equipment_docs_from_request(session, concert.id)
        _add_equipment_notes_from_request(session, concert.id)
        _ensure_internal_contract_sheet(session, concert)

        # Cartelería elegida en el asistente: quién hace los carteles y, si somos nosotros,
        # la solicitud automática a diseño (formatos + logos + notas).
        artwork_choice = (request.form.get('artwork_choice') or '').strip().upper()
        artwork_row = None
        artwork_send = False
        if artwork_choice in ('PROMOTER', 'REQUEST'):
            now = datetime.now(ZoneInfo('Europe/Madrid'))
            artwork_row = ConcertArtworkRequest(concert_id=concert.id, public_token=uuid.uuid4().hex)
            session.add(artwork_row)
            if artwork_choice == 'PROMOTER':
                artwork_row.handled_by = 'PROMOTER'
                artwork_row.status = 'PROMOTER'
            else:
                artwork_row.handled_by = 'OURS'
                artwork_row.status = 'REQUESTED'
                artwork_row.requested_at = now
                artwork_row.group_company_ids = _parse_uuid_list(request.form.getlist('artwork_company_ids[]'))
                artwork_row.ticketer_ids = _parse_uuid_list(request.form.getlist('artwork_ticketer_ids[]'))
                artwork_row.requested_formats = _parse_artwork_formats(request.form)
                _vid = _parse_artwork_video(request.form)
                artwork_row.video_requested = _vid["requested"]
                artwork_row.video_notes = _vid["notes"]
                artwork_row.video_formats = _vid["formats"]
                logo_others = (request.form.get('artwork_logo_others') or '').strip()
                artwork_row.logo_notes = f'Otros logos: {logo_others}' if logo_others else None
                artwork_row.other_notes = (request.form.get('artwork_notes') or '').strip() or None
                artwork_row.delivery_deadline = parse_optional_date(request.form.get('artwork_deadline'))
                artwork_send = True
            artwork_row.updated_at = now
            artwork_row.event_snapshot = _concert_artwork_snapshot(concert)

        session.commit()
        if artwork_send and artwork_row:
            try:
                ok, error = _send_artwork_request_email(concert, artwork_row, is_update=False)
            except Exception as exc:
                ok, error = False, str(exc)
            if ok:
                flash('Actividad creada y solicitud de cartelería enviada a diseño.', 'success')
            else:
                flash(f'Actividad creada. La solicitud de cartelería quedó registrada pero el correo no se pudo enviar: {error}', 'warning')
        else:
            flash('Actividad creada correctamente.', 'success')
        return redirect(url_for('concert_detail_view', cid=concert.id, tab='general'))
    except Exception as exc:
        session.rollback()
        flash(f'Error creando concierto: {exc}', 'danger')
        return redirect(url_for('concerts_view', tab='vista'))
    finally:
        session.close()


@app.route('/ficha-contratacion/<token>', methods=['GET', 'POST'], endpoint='concert_contract_public_form')
def concert_contract_public_form(token):
    session = db()
    try:
        sheet = (
            session.query(ConcertContractSheet)
            .filter(ConcertContractSheet.public_token == (token or '').strip())
            .first()
        )
        if not sheet:
            abort(404)
        concert = (
            session.query(Concert)
            .options(
                joinedload(Concert.artist),
                joinedload(Concert.venue),
                joinedload(Concert.billing_company),
            )
            .filter(Concert.id == sheet.concert_id)
            .first()
        )
        if not concert:
            abort(404)
        if request.method == 'POST':
            if not _contract_sheet_can_submit(sheet):
                flash('Esta ficha ya no admite más envíos.', 'warning')
                return redirect(url_for('concert_contract_public_form', token=token))
            data = _parse_contract_sheet_form(request.form)
            sheet.data = data
            sheet.status = 'RECEIVED'
            sheet.submitted_at = datetime.now(ZoneInfo('Europe/Madrid'))
            sheet.updated_at = datetime.now(ZoneInfo('Europe/Madrid'))
            sheet.allow_resubmission = False
            session.commit()
            return render_template(
                'concert_contract_public.html',
                concert=concert,
                sheet=sheet,
                data=data,
                submitted=True,
                can_submit=False,
                public_mode=True,
                form_action=url_for('concert_contract_public_form', token=token),
            )
        data = _contract_sheet_prefill(concert, sheet)
        can_submit = _contract_sheet_can_submit(sheet)
        return render_template(
            'concert_contract_public.html',
            concert=concert,
            sheet=sheet,
            data=data,
            submitted=False,
            can_submit=can_submit,
            public_mode=True,
            form_action=url_for('concert_contract_public_form', token=token),
        )
    finally:
        session.close()


@app.route('/conciertos/<cid>/ficha-contratacion/revisar', methods=['GET', 'POST'], endpoint='concert_contract_sheet_review')
@admin_required
def concert_contract_sheet_review(cid):
    session = db()
    try:
        concert = (
            session.query(Concert)
            .options(
                joinedload(Concert.artist),
                joinedload(Concert.venue),
                selectinload(Concert.contract_sheet),
            )
            .filter(Concert.id == to_uuid(cid))
            .first()
        )
        if not concert or not concert.contract_sheet:
            flash('No hay ficha de contratación para este concierto.', 'warning')
            return redirect(url_for('concert_detail_view', cid=cid, tab='ficha'))
        sheet = concert.contract_sheet
        auto_updates, conflicts = _prepare_contract_sheet_merge(concert, sheet.data or {})
        if request.method == 'POST':
            updates = list(auto_updates)
            for item in conflicts:
                updates.append({'field': item['field'], 'label': item['label'], 'value': item['incoming']})
            decisions = {}
            for item in conflicts:
                decisions[item['field']] = (request.form.get(f'decision_{item["field"]}') or 'keep').strip().lower()
            applied = _apply_contract_sheet_merge(concert, updates, decisions)
            try:
                session.flush()
                session.expire(concert, ['venue'])
            except Exception:
                pass
            _sync_artwork_request_refresh_flag(concert)
            sheet.status = 'ACCEPTED'
            sheet.allow_resubmission = False
            now = datetime.now(ZoneInfo('Europe/Madrid'))
            sheet.accepted_at = now
            sheet.reviewed_at = now
            sheet.updated_at = now
            sheet.merge_log = list(sheet.merge_log or []) + [{
                'at': now.isoformat(),
                'applied': applied,
                'decisions': decisions,
            }]
            session.commit()
            if applied:
                flash('Ficha aceptada. Se completaron automáticamente: ' + ', '.join(applied), 'success')
            else:
                flash('Ficha aceptada.', 'success')
            return redirect(url_for('concert_detail_view', cid=cid, tab='ficha'))
        return render_template(
            'concert_contract_merge.html',
            concert=concert,
            sheet=sheet,
            auto_updates=auto_updates,
            conflicts=conflicts,
        )
    finally:
        session.close()


@app.post('/conciertos/<cid>/ficha-contratacion/rechazar', endpoint='concert_contract_sheet_reject')
@admin_required
def concert_contract_sheet_reject(cid):
    session = db()
    try:
        concert = (
            session.query(Concert)
            .options(selectinload(Concert.contract_sheet), joinedload(Concert.artist))
            .filter(Concert.id == to_uuid(cid))
            .first()
        )
        if not concert or not concert.contract_sheet:
            flash('No hay ficha de contratación para este concierto.', 'warning')
            return redirect(url_for('concert_detail_view', cid=cid, tab='ficha'))
        reason = (request.form.get('reason') or '').strip()
        if not reason:
            flash('Debes indicar el motivo del rechazo.', 'warning')
            return redirect(url_for('concert_detail_view', cid=cid, tab='ficha'))
        sheet = concert.contract_sheet
        now = datetime.now(ZoneInfo('Europe/Madrid'))
        sheet.status = 'REJECTED'
        sheet.rejection_reason = reason
        sheet.allow_resubmission = True
        sheet.rejected_at = now
        sheet.reviewed_at = now
        sheet.updated_at = now
        session.commit()
        form_url = _external_url_for('concert_contract_public_form', token=sheet.public_token)
        html_body = f'''<div style="font-family:Arial,sans-serif;color:#1f2937;"><h2>Solicitud de subsanación de ficha de contratación</h2><p>La ficha enviada para <strong>{concert.artist.name if concert.artist else 'el concierto'}</strong> necesita correcciones.</p><p><strong>Motivo:</strong><br>{reason}</p><p><a href="{form_url}" style="display:inline-block;background:#0d6efd;color:#fff;padding:10px 16px;border-radius:8px;text-decoration:none;">Subsanar ficha</a></p></div>'''
        ok, error = _send_optional_email(sheet.promoter_email or '', 'Subsanación ficha de contratación', html_body, text_body=form_url)
        if ok:
            flash('Ficha rechazada y solicitud de subsanación enviada.', 'warning')
        else:
            flash(f'Ficha rechazada. No se pudo enviar el correo automáticamente: {error}', 'warning')
    except Exception as exc:
        session.rollback()
        flash(f'Error rechazando ficha: {exc}', 'danger')
    finally:
        session.close()
    return redirect(url_for('concert_detail_view', cid=cid, tab='ficha'))


@app.route('/conciertos/<cid>/ficha-contratacion/editar', methods=['GET', 'POST'], endpoint='concert_contract_sheet_edit')
@admin_required
def concert_contract_sheet_edit(cid):
    session = db()
    try:
        concert = (
            session.query(Concert)
            .options(selectinload(Concert.contract_sheet), joinedload(Concert.artist), joinedload(Concert.venue), joinedload(Concert.billing_company))
            .filter(Concert.id == to_uuid(cid))
            .first()
        )
        if not concert:
            flash('No hay ficha de contratación para este concierto.', 'warning')
            return redirect(url_for('concert_detail_view', cid=cid, tab='ficha'))
        sheet = concert.contract_sheet or _ensure_internal_contract_sheet(session, concert)
        if request.method == 'POST':
            sheet.data = _parse_contract_sheet_form(request.form)
            sheet.updated_at = datetime.now(ZoneInfo('Europe/Madrid'))
            if sheet.status == 'REQUESTED':
                sheet.status = 'RECEIVED'
            session.commit()
            flash('Ficha actualizada.', 'success')
            return redirect(url_for('concert_detail_view', cid=cid, tab='ficha'))
        return render_template(
            'concert_contract_public.html',
            concert=concert,
            sheet=sheet,
            data=_contract_sheet_prefill(concert, sheet),
            submitted=False,
            can_submit=True,
            public_mode=False,
            admin_mode=True,
            form_action=url_for('concert_contract_sheet_edit', cid=cid),
        )
    finally:
        session.close()


@app.get('/conciertos/<cid>/ficha-contratacion/pdf', endpoint='concert_contract_sheet_pdf')
@admin_required
def concert_contract_sheet_pdf(cid):
    """PDF de la ficha de contratación: MISMA cabecera visual que la ficha (foto del artista,
    estado con color, tile de calendario, recinto, logos de empresa y promotor, tipo, anuncio,
    salida a la venta, canta/formación y M&G) + las mismas secciones/cabeceras que la ficha,
    solo con los campos cumplimentados, compacto para caber en un A4."""
    if not REPORTLAB_AVAILABLE:
        return abort(503)
    session = db()
    try:
        concert = (
            session.query(Concert)
            .options(
                selectinload(Concert.contract_sheet), joinedload(Concert.artist),
                joinedload(Concert.venue), joinedload(Concert.promoter),
                joinedload(Concert.promoter_company), joinedload(Concert.billing_company),
            )
            .filter(Concert.id == to_uuid(cid))
            .first()
        )
        if not concert:
            flash('No hay ficha de contratación para este concierto.', 'warning')
            return redirect(url_for('concert_detail_view', cid=cid, tab='general'))

        cpay = concert.contracting_payload if isinstance(concert.contracting_payload, dict) else {}
        perf = cpay.get('performance') if isinstance(cpay.get('performance'), dict) else {}
        mg = cpay.get('meet_greet') if isinstance(cpay.get('meet_greet'), dict) else {}

        buf = BytesIO()
        doc = SimpleDocTemplate(buf, pagesize=A4, leftMargin=28, rightMargin=28, topMargin=22, bottomMargin=22)
        styles = getSampleStyleSheet()
        title_style = ParagraphStyle('ContractSheetTitle', parent=styles['Title'], alignment=TA_CENTER, fontSize=16, leading=19, spaceAfter=2)
        cell_lbl = ParagraphStyle('CellLbl', parent=styles['Normal'], fontSize=6.6, leading=8, textColor=colors.HexColor('#6b7280'))
        cell_val = ParagraphStyle('CellVal', parent=styles['Normal'], fontSize=8, leading=10)
        cell_val_b = ParagraphStyle('CellValB', parent=cell_val, fontName='Helvetica-Bold')
        sec_txt = ParagraphStyle('SecTxt', parent=styles['Normal'], fontSize=9, leading=11, fontName='Helvetica-Bold', textColor=colors.HexColor('#E33D48'))
        body_txt = ParagraphStyle('BodyTxt', parent=styles['Normal'], fontSize=8, leading=10.5)
        story = []

        def _img(url, w, h):
            u = (url or '').strip()
            if not u:
                return None
            try:
                req = Request(u, headers={'User-Agent': 'Mozilla/5.0'})
                with urlopen(req, timeout=20) as resp:
                    return RLImage(BytesIO(resp.read()), width=w, height=h, kind='proportional')
            except Exception:
                return None

        # ---- Logo empresa arriba a la DERECHA + título centrado (como la ficha/correos) ----
        logo_url = (getattr(getattr(concert, 'billing_company', None), 'logo_url', None)
                    or getattr(getattr(concert, 'group_company', None), 'logo_url', None) or '')
        logo_cell = _img(logo_url, 110, 40) or ''
        logo_row = Table([['', logo_cell]], colWidths=[419, 120])
        logo_row.setStyle(TableStyle([('ALIGN', (1, 0), (1, 0), 'RIGHT'), ('VALIGN', (0, 0), (-1, -1), 'TOP')]))
        story.append(logo_row)
        story.append(Paragraph('Ficha de contratación', title_style))
        story.append(Spacer(1, 3))

        # ---- CABECERA VISUAL (misma franja-resumen que la ficha) ----
        def strip_cell(label, flow):
            inner = Table([[Paragraph(label.upper(), cell_lbl)], [flow]], colWidths=[126])
            inner.setStyle(TableStyle([
                ('LEFTPADDING', (0, 0), (-1, -1), 4), ('RIGHTPADDING', (0, 0), (-1, -1), 4),
                ('TOPPADDING', (0, 0), (-1, -1), 1.5), ('BOTTOMPADDING', (0, 0), (-1, -1), 1.5),
                ('VALIGN', (0, 0), (-1, -1), 'TOP'),
            ]))
            return inner

        status = (concert.status or '').strip().upper()
        status_colors = {'CONFIRMADO': '#198754', 'CANCELADO': '#dc3545', 'ANULADO': '#dc3545',
                         'BORRADOR': '#6c757d', 'RESERVA': '#f59f00', 'TBC': '#f59f00'}
        st_style = ParagraphStyle('StVal', parent=cell_val_b, textColor=colors.HexColor(status_colors.get(status, '#334155')))
        items = [('Estado', Paragraph(status or '—', st_style))]

        art_img = _img(getattr(concert.artist, 'photo_url', None), 22, 22)
        art_name = Paragraph(concert.artist.name if concert.artist else '—', cell_val_b)
        items.append(('Artista', Table([[art_img or '', art_name]], colWidths=[24, 94],
                                       style=TableStyle([('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                                                         ('LEFTPADDING', (0, 0), (-1, -1), 0),
                                                         ('RIGHTPADDING', (0, 0), (-1, -1), 2)]))))

        if concert.date:
            _MES = ['ENE', 'FEB', 'MAR', 'ABR', 'MAY', 'JUN', 'JUL', 'AGO', 'SEP', 'OCT', 'NOV', 'DIC']
            cal_tile = Table([
                [Paragraph(f"<font color='white'><b>{_MES[concert.date.month - 1]} {concert.date.year}</b></font>",
                           ParagraphStyle('CalM', parent=cell_lbl, alignment=1, fontSize=6, textColor=colors.white))],
                [Paragraph(f"<b>{concert.date.day:02d}</b>", ParagraphStyle('CalD', parent=cell_val_b, alignment=1, fontSize=12, leading=13))],
            ], colWidths=[40])
            cal_tile.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (0, 0), colors.HexColor('#E33D48')),
                ('BACKGROUND', (0, 1), (0, 1), colors.white),
                ('BOX', (0, 0), (-1, -1), 0.6, colors.HexColor('#e5e7eb')),
                ('TOPPADDING', (0, 0), (-1, -1), 1), ('BOTTOMPADDING', (0, 0), (-1, -1), 1),
            ]))
            items.append(('Fecha', cal_tile))

        venue_bits = [x for x in [_concert_venue_name(concert), _concert_city(concert), _concert_province_value(concert)] if x]
        if venue_bits:
            extra = ''
            if not getattr(concert, 'no_capacity', False) and getattr(concert, 'capacity', None):
                extra = f"<br/><font size=6.5 color='#6b7280'>Aforo a la venta: {concert.capacity}</font>"
            items.append(('Recinto', Paragraph('<b>' + ' · '.join(venue_bits[:1]) + '</b><br/><font size=6.5 color="#6b7280">' + ' · '.join(venue_bits[1:]) + '</font>' + extra, cell_val)))

        if getattr(concert, 'billing_company', None):
            bc_img = _img(concert.billing_company.logo_url, 60, 22)
            items.append(('Factura', bc_img or Paragraph(concert.billing_company.name, cell_val_b)))

        type_label = QUAD_ACTIVITY_LABELS.get((concert.activity_type or '').strip().upper(),
                                              (concert.activity_type or 'Concierto').replace('_', ' ').title())
        items.append(('Tipo', Paragraph(f"{type_label}<br/><font size=6.5 color='#6b7280'>{(concert.sale_type or '').title()}</font>", cell_val_b)))

        if getattr(concert, 'promoter', None):
            pr_img = _img(concert.promoter.logo_url, 20, 20)
            pr_txt = concert.promoter.nick or ''
            if getattr(concert, 'promoter_company', None):
                pr_txt += f"<br/><font size=6.5 color='#6b7280'>{getattr(concert.promoter_company, 'legal_name', None) or getattr(concert.promoter_company, 'name', '')}</font>"
            items.append(('Promotor', Table([[pr_img or '', Paragraph(pr_txt, cell_val_b)]], colWidths=[22, 96],
                                            style=TableStyle([('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                                                              ('LEFTPADDING', (0, 0), (-1, -1), 0),
                                                              ('RIGHTPADDING', (0, 0), (-1, -1), 2)]))))

        if getattr(concert, 'do_not_announce', False):
            items.append(('Anuncio', Paragraph('No anunciar', cell_val_b)))
        elif getattr(concert, 'announcement_date', None):
            items.append(('Anuncio', Paragraph(concert.announcement_date.strftime('%d/%m/%Y'), cell_val_b)))
        else:
            items.append(('Anuncio', Paragraph('TBC', cell_val)))
        if getattr(concert, 'sale_start_tbc', False):
            items.append(('A la venta', Paragraph('TBC', cell_val)))
        elif getattr(concert, 'sale_start_date', None):
            items.append(('A la venta', Paragraph(concert.sale_start_date.strftime('%d/%m/%Y'), cell_val_b)))
        if perf.get('sings') is not None:
            items.append(('¿Canta?', Paragraph('Sí' if perf.get('sings') else 'No', cell_val_b)))
        if cpay.get('formation'):
            items.append(('Formación', Paragraph(str(cpay.get('formation')), cell_val_b)))
        if mg.get('enabled'):
            mg_txt = 'Sí' + (f" · {mg.get('quantity')} pers." if (str(mg.get('quantity') or '')).strip() else '')
            items.append(('Meet & Greet', Paragraph(mg_txt, cell_val_b)))
        if getattr(concert, 'show_time', None) or getattr(concert, 'show_time_tbc', False):
            items.append(('Hora show', Paragraph('TBC' if concert.show_time_tbc else str(concert.show_time), cell_val_b)))

        per_row = 4
        grid_rows = [[strip_cell(l, f) for (l, f) in items[i:i + per_row]] for i in range(0, len(items), per_row)]
        for r in grid_rows:
            while len(r) < per_row:
                r.append('')
        strip = Table(grid_rows, colWidths=[134.75] * per_row)
        strip.setStyle(TableStyle([
            ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#e5e7eb')),
            ('BACKGROUND', (0, 0), (-1, -1), colors.HexColor('#fbfcfe')),
            ('VALIGN', (0, 0), (-1, -1), 'TOP'),
            ('TOPPADDING', (0, 0), (-1, -1), 2), ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
        ]))
        story.append(strip)

        # ---- Secciones con las MISMAS cabeceras que la ficha ----
        def sec(title):
            band = Table([[Paragraph(title, sec_txt)]], colWidths=[539])
            band.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (-1, -1), colors.HexColor('#fdeef0')),
                ('LEFTPADDING', (0, 0), (-1, -1), 6), ('RIGHTPADDING', (0, 0), (-1, -1), 6),
                ('TOPPADDING', (0, 0), (-1, -1), 2.5), ('BOTTOMPADDING', (0, 0), (-1, -1), 2.5),
            ]))
            story.append(Spacer(1, 5))
            story.append(band)
            story.append(Spacer(1, 2))

        def pairs_table(pairs):
            cells, pair = [], []
            for label, value in pairs:
                pair.append(Paragraph(str(label), cell_lbl))
                pair.append(Paragraph(str(value), cell_val))
                if len(pair) == 4:
                    cells.append(pair)
                    pair = []
            if pair:
                pair += [''] * (4 - len(pair))
                cells.append(pair)
            t = Table(cells, colWidths=[95, 175, 95, 174])
            t.setStyle(TableStyle([
                ('VALIGN', (0, 0), (-1, -1), 'TOP'),
                ('LINEBELOW', (0, 0), (-1, -1), 0.3, colors.HexColor('#eceff3')),
                ('LEFTPADDING', (0, 0), (-1, -1), 2), ('RIGHTPADDING', (0, 0), (-1, -1), 6),
                ('TOPPADDING', (0, 0), (-1, -1), 1.5), ('BOTTOMPADDING', (0, 0), (-1, -1), 1.5),
            ]))
            story.append(t)

        # Descripción de la actividad (primero, como en la ficha)
        if (cpay.get('description') or '').strip():
            sec('Descripción de la actividad')
            story.append(Paragraph(str(cpay.get('description')), body_txt))

        # Más información de la actividad (mismos campos y filtro que la ficha)
        summary_labels = {'Artista/s', 'Tipo de actividad', 'Subtipo', 'Estado', 'Fecha', 'Empresa que factura',
                          'Promotor', 'Sociedad promotor', 'Salida a la venta', 'Aforo', 'En qué consiste',
                          '¿El artista canta?', 'Formación', 'Anuncio', 'Meet & Greet'}
        info_pairs = [(r['label'], r['value']) for r in _concert_contracting_general_rows(session, concert)
                      if r.get('label') not in summary_labels and r.get('kind', 'text') == 'text']
        if info_pairs:
            sec('Más información de la actividad')
            pairs_table(info_pairs)

        # Colaboradores
        colab_pairs = []
        for s in (getattr(concert, 'company_shares', None) or []):
            val = f"{s.pct}% · {'Bruto' if s.pct_base == 'GROSS' else 'Neto'}" if s.pct else (f"{format_eur(s.amount)}" if s.amount else 'Participa')
            colab_pairs.append((s.company.name if s.company else 'Empresa', val))
        for s in (getattr(concert, 'promoter_shares', None) or []):
            val = f"{s.pct}% · {'Bruto' if s.pct_base == 'GROSS' else 'Neto'}" if s.pct else (f"{format_eur(s.amount)}" if s.amount else 'Participa')
            colab_pairs.append((s.promoter.nick if s.promoter else 'Tercero', val))
        if colab_pairs:
            sec('Colaboradores')
            pairs_table(colab_pairs)

        # Comisionistas
        com_pairs = []
        for z in (getattr(concert, 'zone_agents', None) or []):
            name = (z.promoter.nick if z.promoter else 'Comisionista') + (f" · {z.concept}" if z.concept else '')
            val = f"{z.commission_pct}% · {'Bruto' if z.commission_base == 'GROSS' else 'Neto'}" if z.commission_type == 'PERCENT' else format_eur(z.commission_amount)
            com_pairs.append((name, val))
        if com_pairs:
            sec('Comisionistas')
            pairs_table(com_pairs)

        # Cachés + lo que cubre el promotor
        cache_pairs = []
        for ch in (getattr(concert, 'caches', None) or []):
            lbl = 'Caché fijo' if ch.kind == 'FIXED' else ('Caché variable' if ch.kind == 'VARIABLE' else (ch.concept or 'Otros'))
            if ch.kind == 'VARIABLE' and ch.pct:
                val = f"{ch.pct}% · {'Bruto' if ch.pct_base == 'GROSS' else 'Neto'}"
            else:
                val = format_eur(ch.amount) if ch.amount else '—'
            cache_pairs.append((lbl, val))
        pc_rows = _promoter_costs_rows(getattr(concert, 'promoter_costs_payload', None))
        for pc in pc_rows:
            val = ('Facturamos nosotros' if pc.get('managed_by') == 'US' else 'Lo gestiona el promotor')
            if pc.get('max_amount'):
                val += f" · máx. {format_eur(pc.get('max_amount'))}"
            if pc.get('note'):
                val += f" · {pc.get('note')}"
            cache_pairs.append((f"Promotor cubre: {pc.get('label')}", val))
        if cache_pairs:
            sec('Cachés')
            pairs_table(cache_pairs)

        # Entradas (tipos con importes e invitaciones, como la pestaña de la ficha)
        ticket_rows = _concert_entradas_ticket_rows(concert)
        tpay = concert.ticketing_payload if isinstance(concert.ticketing_payload, dict) else {}
        entry_pairs = []
        if (tpay.get('entry_mode') or '').upper() == 'FREE':
            entry_pairs.append(('Entrada', 'Evento gratuito'))
        elif tpay.get('entry_mode'):
            entry_pairs.append(('Entrada', 'Venta de entradas'))
        seller = tpay.get('sale_seller') if isinstance(tpay.get('sale_seller'), dict) else {}
        if seller.get('label'):
            entry_pairs.append(('Vende', seller.get('label')))
        if tpay.get('invitations_total'):
            entry_pairs.append(('Invitaciones por contrato', str(tpay.get('invitations_total'))))
        if entry_pairs or ticket_rows:
            sec('Entradas y venta')
            if entry_pairs:
                pairs_table(entry_pairs)
            if ticket_rows:
                trows = [[Paragraph(x, cell_lbl) for x in ['Tipo', 'Importe', 'Entradas a la venta', 'Invitaciones']]]
                for r in ticket_rows:
                    trows.append([
                        Paragraph(str(r.get('name') or 'Entrada'), cell_val),
                        Paragraph(format_eur(r.get('price')), cell_val),
                        Paragraph(str(r.get('qty_for_sale') or ''), cell_val),
                        Paragraph(str(r.get('invites_total') or ''), cell_val),
                    ])
                t = Table(trows, colWidths=[200, 100, 130, 109])
                t.setStyle(TableStyle([
                    ('GRID', (0, 0), (-1, -1), 0.3, colors.HexColor('#e5e7eb')),
                    ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#f8f9fb')),
                    ('LEFTPADDING', (0, 0), (-1, -1), 3), ('RIGHTPADDING', (0, 0), (-1, -1), 3),
                    ('TOPPADDING', (0, 0), (-1, -1), 1.5), ('BOTTOMPADDING', (0, 0), (-1, -1), 1.5),
                ]))
                story.append(t)

        # Equipamiento
        eq = getattr(concert, 'equipment', None)
        eq_lines = []
        if eq is not None:
            if getattr(eq, 'covered_by_promoter', False) and getattr(eq, 'covered_mode', '') == 'RIDER':
                eq_lines.append('Rider de festival')
            elif getattr(eq, 'covered_by_promoter', False):
                eq_lines.append('Promotor cubre equipos')
            elif getattr(eq, 'covered_mode', '') == 'ARTIST':
                eq_lines.append('Equipo a cargo del artista')
            elif getattr(eq, 'included', False) or getattr(eq, 'other', False):
                eq_lines.append('Equipos incluidos')
        for n in (getattr(concert, 'equipment_notes', None) or []):
            if (n.body or '').strip():
                eq_lines.append(n.body.strip())
        if eq_lines:
            sec('Equipamiento')
            for line in eq_lines:
                story.append(Paragraph(line, body_txt))

        # Plan de facturación / cobro
        payment_rows = _concert_payment_rows(concert, pending_only=False)
        if payment_rows:
            sec('Plan de facturación / cobro')
            trows = [[Paragraph(x, cell_lbl) for x in ['Concepto', 'Importe', 'Fecha límite', 'Estado']]]
            for r in payment_rows:
                due = r.get('due_date')
                due_txt = due if isinstance(due, str) else (due.strftime('%d/%m/%Y') if due else '')
                trows.append([
                    Paragraph(str(r.get('concept') or 'Pago'), cell_val),
                    Paragraph(format_eur(r.get('amount')), cell_val),
                    Paragraph(due_txt or '', cell_val),
                    Paragraph(str(r.get('status') or ''), cell_val),
                ])
            t = Table(trows, colWidths=[230, 100, 100, 109])
            t.setStyle(TableStyle([
                ('GRID', (0, 0), (-1, -1), 0.3, colors.HexColor('#e5e7eb')),
                ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#f8f9fb')),
                ('LEFTPADDING', (0, 0), (-1, -1), 3), ('RIGHTPADDING', (0, 0), (-1, -1), 3),
                ('TOPPADDING', (0, 0), (-1, -1), 1.5), ('BOTTOMPADDING', (0, 0), (-1, -1), 1.5),
            ]))
            story.append(t)

        # Notas de contratación
        note_lines = [(n.body or '').strip() for n in (getattr(concert, 'notes', None) or []) if (n.body or '').strip()]
        if note_lines:
            sec('Notas de contratación')
            for line in note_lines:
                story.append(Paragraph('· ' + line, body_txt))

        doc.build(story)
        buf.seek(0)
        filename = f"ficha_contratacion_{(concert.artist.name if concert.artist else 'concierto').replace(' ', '_')}.pdf"
        return send_file(buf, mimetype='application/pdf', as_attachment=False, download_name=filename)
    finally:
        session.close()

