def _prl_admin_altas_context(session_db) -> dict:
    """Contexto de la pestaña Altas de Administración: ITA vigente por empresa del grupo."""
    companies = session_db.query(GroupCompany).order_by(GroupCompany.name).all()
    docs = _prl_company_ita_docs(session_db)
    today = date.today()
    by_company = {}
    for d in docs:
        key = str(d.company_id or d.owner_id)
        by_company.setdefault(key, []).append(d)
    name_by_ref = {}
    for ref in {r for d in docs for r in (d.linked_person_ids or [])}:
        try:
            kind_s, _, id_s = str(ref).partition(":")
            if kind_s == "PROMOTER":
                p = session_db.get(Promoter, to_uuid(id_s))
                if p:
                    name_by_ref[ref] = p.nick or ""
            elif kind_s == "USER":
                u = session_db.query(UserProfile).filter(UserProfile.user_id == to_uuid(id_s)).first()
                if u:
                    name_by_ref[ref] = (u.nick or u.full_name or "")
        except Exception:
            continue
    rows = []
    for comp in companies:
        comp_docs = by_company.get(str(comp.id), [])
        current = comp_docs[0] if comp_docs else None
        valid = bool(current) and _prl_doc_valid_on(current, today)
        rows.append({
            "company": comp, "current": current, "valid": valid,
            "history": comp_docs[1:6],
            "workers": ((current.detected_meta or {}).get("workers") or []) if current else [],
            "linked_names": [name_by_ref.get(r, "") for r in (current.linked_person_ids or [])] if current else [],
        })
    return {"altas_rows": rows, "altas_today": today}


def _home_my_expenses_summary() -> dict:
    """Panel de Inicio: mis facturas y gastos de Pleo sin asignar a una bolsa, con la cuenta atrás.

    El módulo se muestra SIEMPRE (también a dirección y sin nada pendiente: entonces dice «sin gastos
    pendientes de asignar»), así se sabe que la sección existe. Lo que no aplica a dirección es la
    RECLAMACIÓN por correo ni el escalado (eso lo decide el cron, ver `cron_unassigned_expenses`).
    """
    empty = {"rows": [], "overdue": 0, "total": 0, "visible": bool(session.get("user_id"))}
    uid = session.get("user_id")
    if not uid:
        return empty
    session_db = db()
    try:
        rows = _personal_expenses_for(session_db, uid, status=("PENDING", "IN_BAG"))
        pause = _expense_pause_context(session_db, uid)
        return {
            "rows": rows[:8],
            "total": len(rows),
            "overdue": len([r for r in rows if r["overdue"]]),
            "amount": sum((r["amount_gross"] for r in rows), Decimal("0")),
            "visible": True,
            # Plazo parado (para esta persona o para todos): se dice y no se mete prisa.
            "deadline_paused": pause["paused"],
            "deadline_paused_label": ("Plazo de gastos parado para todo el personal" if pause["all_paused"]
                                      else "Tienes el plazo de gastos parado" if pause["paused"] else ""),
        }
    except Exception:
        return empty
    finally:
        session_db.close()


def _home_admin_altas_pending() -> list:
    """Empresas del grupo con ITA caducado o sin ITA (tarea pendiente de Administración).
    Solo se la enseñamos a quien le toca (responsabilidad ITA); ver `_admin_task_is_mine`."""
    session_db = db()
    try:
        if not _admin_task_is_mine(session_db, "ITA"):
            return []
        ctx = _prl_admin_altas_context(session_db)
        return [{"name": r["company"].name, "logo_url": r["company"].logo_url,
                 "until": r["current"].valid_until.strftime("%d/%m/%Y") if (r["current"] and r["current"].valid_until) else None}
                for r in ctx["altas_rows"] if not r["valid"]]
    except Exception:
        return []
    finally:
        session_db.close()


def _admin_promo_bag_ids(session_db) -> set:
    """Bolsas EN ADMINISTRACIÓN que son de una promoción de prensa y **no tienen nada que pagar**:
    esas las liquida quien lleve «gastos de promoción sin pagos pendientes», no quien liquida bolsas."""
    try:
        bags = (session_db.query(WorkflowBag)
                .filter(WorkflowBag.is_archived == False)  # noqa: E712
                .filter(func.upper(func.coalesce(WorkflowBag.linked_type, '')) == 'PROMOTION')
                .filter(or_(WorkflowBag.status == "CERRADA",
                            WorkflowBag.liquidation_status.in_(ADMIN_BAG_LIQUIDACION_STATUSES + ADMIN_BAG_CIERRE_STATUSES)))
                .limit(400).all())
        return {str(bag.id) for bag in bags if not _bag_has_pending_payments(session_db, bag)}
    except Exception:
        return set()


def _admin_promo_liquidation_counts(session_db) -> dict:
    """Cuántas de esas bolsas hay en cada bandeja (liquidación / cierre)."""
    ids = _admin_promo_bag_ids(session_db)
    out = {"liquidacion": 0, "cierre": 0}
    if not ids:
        return out
    try:
        rows = (session_db.query(WorkflowBag.id, WorkflowBag.liquidation_status)
                .filter(WorkflowBag.id.in_([to_uuid(x) for x in ids])).all())
        for _bid, estado in rows:
            estado = (estado or "").strip().upper()
            if estado in ADMIN_BAG_LIQUIDACION_STATUSES:
                out["liquidacion"] += 1
            elif estado in ADMIN_BAG_CIERRE_STATUSES:
                out["cierre"] += 1
    except Exception:
        pass
    return out


def _home_admin_pending() -> list:
    """Módulo de Inicio «Tareas pendientes · Administración»: un bloque por tipo de tarea, con su
    número y su enlace, y SOLO los tipos que le tocan a quien mira (los suyos, más los que no
    tienen responsable). Sin responsabilidades asignadas se ven todos."""
    session_db = db()
    try:
        if not has_access_key("administracion", include_descendants=True):
            return []
        datos = _admin_pending_counts(session_db)
        counts, pending = datos["counts"], datos["pending_counts"]
        # Las bolsas de PROMOCIÓN sin nada que pagar son su propia tarea (y su propia persona).
        promo_liq = _admin_promo_liquidation_counts(session_db)
        bloques = [
            ("GASTOS_SIN_TICKET", "Gastos sin ticket y pagos urgentes", "fa-receipt",
             pending.get("solicitudes", 0), url_for("administracion_view", tab="pendiente", subtab="solicitudes")),
            ("PAGOS", "Pendiente de pago", "fa-money-bill-transfer",
             pending.get("pago", 0), url_for("administracion_view", tab="pendiente", subtab="pago")),
            ("FACTURAS_SOLICITADAS", "Pendiente de facturación", "fa-file-invoice",
             pending.get("facturacion", 0), url_for("administracion_view", tab="pendiente", subtab="facturacion")),
            ("LIQUIDACIONES", "Bolsas por liquidar", "fa-scale-balanced",
             max(0, pending.get("liquidacion", 0) - promo_liq.get("liquidacion", 0)),
             url_for("administracion_view", tab="pendiente", subtab="liquidacion")),
            ("LIQUIDACIONES_PROMO", "Promoción sin pagos pendientes", "fa-microphone-lines",
             promo_liq.get("liquidacion", 0), url_for("administracion_view", tab="pendiente", subtab="liquidacion")),
            ("LIQUIDACIONES", "Bolsas por cerrar", "fa-box-archive",
             max(0, pending.get("cierre", 0) - promo_liq.get("cierre", 0)),
             url_for("administracion_view", tab="pendiente", subtab="cierre")),
            ("LIQUIDACIONES_PROMO", "Promoción por cerrar", "fa-box-archive",
             promo_liq.get("cierre", 0), url_for("administracion_view", tab="pendiente", subtab="cierre")),
            ("ITA", "Altas e ITAs", "fa-id-card-clip",
             counts.get("altas", 0), url_for("administracion_view", tab="altas")),
            ("EMBARGOS", "Órdenes de embargo", "fa-gavel",
             counts.get("embargos", 0), url_for("administracion_view", tab="embargos")),
        ]
        out = []
        for clave, label, icono, n, url in bloques:
            if not n:
                continue
            if not _admin_task_is_mine(session_db, clave):
                continue
            out.append({"key": clave, "label": label, "icon": icono, "count": int(n), "url": url})
        return out
    except Exception:
        return []
    finally:
        session_db.close()


def _home_admin_requests(limit: int = 12) -> list[dict]:
    """Módulo de Inicio «Peticiones · Administración»: lo que LE PIDEN a administración y sigue sin
    resolver.

    No es un departamento de peticiones más (`BookingRequest` no llega a administración): son las
    peticiones que ya existen en el trabajo diario —alguien pide pasar un gasto sin factura, alguien
    pide que se le pague ya, y las facturas que hemos pedido a un proveedor y no han llegado—.
    Se filtra por el REPARTO de administración, igual que las tareas: lo que le toca a quien mira
    más lo que no tiene responsable (nada se pierde en silencio)."""
    session_db = db()
    try:
        if not has_access_key("administracion", include_descendants=True):
            return []
        hoy = today_local()

        def _dias(valor):
            try:
                return (hoy - valor.date()).days if valor else None
            except Exception:
                return None

        filas = []
        # 1) Gastos de una bolsa que piden pasar SIN factura.
        if _admin_task_is_mine(session_db, "GASTOS_SIN_TICKET"):
            rows = (session_db.query(BagExpense)
                    .options(joinedload(BagExpense.bag), joinedload(BagExpense.provider))
                    .filter(BagExpense.status != "ELIMINADO",
                            BagExpense.consolidation_status == "SIN_FACTURA_SOLICITADO")
                    .order_by(BagExpense.updated_at.desc().nullslast()).limit(60).all())
            url = url_for("administracion_view", tab="pendiente", subtab="solicitudes")
            for r in rows:
                filas.append({
                    "kind": "SIN_FACTURA", "kind_label": "Pide pasar sin factura", "icon": "fa-receipt",
                    "color": "warning",
                    "title": (r.concept or "Gasto"),
                    "subtitle": " · ".join([x for x in [
                        _promoter_display_name(r.provider),
                        (getattr(r.bag, "title", None) or ""),
                    ] if x]),
                    "person": (r.created_by_nick or "").strip(),
                    "note": (r.no_invoice_reason or ""),
                    "amount": _money_or_zero(r.amount_gross),
                    "days_since": _dias(r.updated_at or r.created_at),
                    "url": url,
                })
            # 2) Pagos que piden hacer ya (van en la misma bandeja).
            rows = (session_db.query(BagExpense)
                    .options(joinedload(BagExpense.bag), joinedload(BagExpense.provider))
                    .filter(BagExpense.status != "ELIMINADO",
                            BagExpense.immediate_payment_requested == True)  # noqa: E712
                    .order_by(BagExpense.immediate_payment_requested_at.desc().nullslast()).limit(60).all())
            for r in rows:
                filas.append({
                    "kind": "PAGO_YA", "kind_label": "Pide pago inmediato", "icon": "fa-bolt",
                    "color": "danger",
                    "title": (r.concept or "Gasto"),
                    "subtitle": " · ".join([x for x in [
                        _promoter_display_name(r.provider),
                        (getattr(r.bag, "title", None) or ""),
                    ] if x]),
                    "person": (r.created_by_nick or "").strip(),
                    "note": (r.immediate_payment_reason or ""),
                    "amount": _money_or_zero(r.immediate_payment_amount or r.amount_gross),
                    "days_since": _dias(r.immediate_payment_requested_at or r.created_at),
                    "url": url,
                })
        # 3) Gastos de OFICINA / inversión de artista que piden pasar sin factura.
        if _admin_task_is_mine(session_db, "GASTOS_OFICINA"):
            url = url_for("administracion_view", tab="pendiente", subtab="oficina")
            for r in _personal_no_invoice_pending(session_db):
                filas.append({
                    "kind": "SIN_FACTURA_OFICINA", "kind_label": "Pide pasar sin factura", "icon": "fa-building-columns",
                    "color": "warning",
                    "title": r.get("concept") or "Gasto",
                    "subtitle": r.get("provider_name") or "",
                    "person": r.get("person") or "",
                    "note": r.get("reason") or "",
                    "amount": r.get("amount_gross"),
                    "days_since": None,
                    "url": url,
                })
        # 4) Facturas que HEMOS pedido a un proveedor y no han llegado.
        if _admin_task_is_mine(session_db, "FACTURAS_SOLICITADAS"):
            rows = (session_db.query(BagInvoiceRequest)
                    .options(joinedload(BagInvoiceRequest.bag), joinedload(BagInvoiceRequest.provider))
                    .filter(func.upper(func.coalesce(BagInvoiceRequest.status, "ACTIVE")) == "ACTIVE")
                    .order_by(BagInvoiceRequest.last_sent_at.desc().nullslast(),
                              BagInvoiceRequest.created_at.desc()).limit(60).all())
            for r in rows:
                nombre = _promoter_display_name(r.provider) or "Proveedor"
                n_conceptos = len([x for x in (r.expense_ids or []) if x])
                filas.append({
                    "kind": "FACTURA_PEDIDA", "kind_label": "Factura pedida sin llegar", "icon": "fa-file-invoice",
                    "color": "info",
                    "title": nombre,
                    "subtitle": " · ".join([x for x in [
                        (getattr(r.bag, "title", None) or ""),
                        (f"{n_conceptos} concepto{'' if n_conceptos == 1 else 's'}" if n_conceptos else ""),
                    ] if x]),
                    "person": "",
                    "note": "",
                    "amount": None,
                    "days_since": _dias(r.last_sent_at or r.created_at),
                    "url": url_for("administracion_view", tab="pendiente", subtab="facturacion"),
                })
        # Lo que lleva más tiempo esperando, primero (lo que no se sabe, al final).
        filas.sort(key=lambda x: (x["days_since"] is None, -(x["days_since"] or 0)))
        return filas[:limit]
    except Exception:
        return []
    finally:
        session_db.close()


@app.post('/hoja-ruta/<entity_type>/<entity_id>/personal', endpoint='roadmap_personnel_save')
@admin_required
def roadmap_personnel_save(entity_type, entity_id):
    session_db = db()
    try:
        _kind, row = _roadmap_entity(session_db, entity_type, entity_id)
        if not row:
            abort(404)
        data = request.get_json(silent=True) or {}
        payload = _roadmap_load(row)
        people = payload.setdefault("personnel", [])
        person = _roadmap_personnel_from_json(data)
        if not person["name"]:
            return jsonify({"ok": False, "error": "Falta el nombre."}), 400
        pid = (data.get("id") or "").strip()
        idx, current = _roadmap_find(people, pid) if pid else (-1, None)
        if current is not None:
            person["id"] = pid
            people[idx] = person
        else:
            # Evita duplicar la misma persona vinculada (mismo kind+ref_id).
            if person["ref_id"]:
                for existing in people:
                    if existing.get("kind") == person["kind"] and str(existing.get("ref_id")) == person["ref_id"]:
                        person["id"] = existing["id"]
                        existing.update(person)
                        _roadmap_save(session_db, row, payload)
                        return jsonify({"ok": True, "payload": payload, "days": _roadmap_days(row, payload), "person_id": person["id"]})
            people.append(person)
        _roadmap_save(session_db, row, payload)
        return jsonify({"ok": True, "payload": payload, "days": _roadmap_days(row, payload), "person_id": person["id"]})
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        session_db.close()


@app.post('/hoja-ruta/<entity_type>/<entity_id>/personal/delete', endpoint='roadmap_personnel_delete')
@admin_required
def roadmap_personnel_delete(entity_type, entity_id):
    session_db = db()
    try:
        _kind, row = _roadmap_entity(session_db, entity_type, entity_id)
        if not row:
            abort(404)
        data = request.get_json(silent=True) or {}
        rid = (data.get("id") or "").strip()
        payload = _roadmap_load(row)
        payload["personnel"] = [x for x in payload.get("personnel", []) if str(x.get("id")) != rid]
        # Limpia referencias en pasajeros y asignaciones de hotel.
        for it in payload.get("agenda", []):
            tr = it.get("transport") or {}
            if tr.get("passengers"):
                tr["passengers"] = [p for p in tr["passengers"] if str(p.get("personnel_id")) != rid]
        for h in payload.get("hotels", []):
            if h.get("assignee_ids"):
                h["assignee_ids"] = [x for x in h["assignee_ids"] if str(x) != rid]
        return _roadmap_ok(session_db, row, payload)
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        session_db.close()


@app.post('/hoja-ruta/<entity_type>/<entity_id>/adjunto', endpoint='roadmap_attachment_upload')
@admin_required
def roadmap_attachment_upload(entity_type, entity_id):
    session_db = db()
    try:
        _kind, row = _roadmap_entity(session_db, entity_type, entity_id)
        if not row:
            abort(404)
        scope = (request.form.get("scope") or "item").strip().lower()
        target_id = (request.form.get("id") or "").strip()
        fs = request.files.get("file")
        if not fs or not getattr(fs, "filename", ""):
            return jsonify({"ok": False, "error": "Selecciona un archivo."}), 400
        url = upload_file(fs, "roadmaps", allowed_extensions=ROADMAP_ATTACHMENT_EXTS)
        if not url:
            return jsonify({"ok": False, "error": "Formato de archivo no permitido."}), 400
        name = fs.filename
        payload = _roadmap_load(row)
        att = {"id": _roadmap_new_id(), "url": url, "name": name}
        if scope == "hotel":
            _idx, hotel = _roadmap_find(payload.get("hotels", []), target_id)
            if hotel is not None:
                hotel.setdefault("attachments", []).append(att)
        elif scope == "passenger":
            pidx = _roadmap_int(request.form.get("passenger_index"), -1)
            _idx, item = _roadmap_find(payload.get("agenda", []), target_id)
            if item is not None:
                passengers = (item.get("transport") or {}).get("passengers") or []
                if 0 <= pidx < len(passengers):
                    passengers[pidx]["ticket_url"] = url
                    passengers[pidx]["ticket_name"] = name
        else:
            _idx, item = _roadmap_find(payload.get("agenda", []), target_id)
            if item is not None:
                item.setdefault("attachments", []).append(att)
        return _roadmap_ok(session_db, row, payload)
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        session_db.close()


