def _generate_temporary_password(length: int = 12) -> str:
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789"
    digest = hashlib.sha256(f"{uuid.uuid4()}::{_now_madrid().isoformat()}".encode("utf-8")).hexdigest()
    chars = []
    for idx in range(length):
        chars.append(alphabet[int(digest[idx * 2: idx * 2 + 2], 16) % len(alphabet)])
    return "".join(chars)


def _coarse_endpoint_resource(endpoint: str, path: str) -> str | None:
    """Resuelve un endpoint a su recurso de SECCIÓN/PESTAÑA, sin args y sin el fallback "auto.".

    Solo se usa para decidir COBERTURA en la auto-discovery (¿ya hay un recurso curado que cubra
    este endpoint?). No interviene en el enforcement, que usa _resolve_request_resource_key().
    """
    if not endpoint:
        return None
    if endpoint in {"landing", "admin_login", "admin_logout"} | PUBLIC_ENDPOINTS_EXTRA:
        return None
    if endpoint == "home":
        return "home"
    fixed = {
        "summary_view": "radio.reportes", "plays_view": "radio.actualizar", "stations_view": "radio.emisoras",
        "sales_report_view": "ventas.reportes", "sales_update_view": "ventas.actualizar",
        "discografica_view": "discografica", "discografica_song_detail": "discografica.canciones",
        "discografica_album_detail": "discografica.canciones", "artist_detail_view": "artists",
        "contracting_view": "contratacion", "concerts_view": "contratacion.conciertos",
        "concert_detail_view": "contratacion.conciertos", "quadrantes_view": "contratacion.cuadrantes",
        "songs_view": "discografica.canciones", "song_update": "discografica.canciones",
        "song_delete": "discografica.canciones", "playlisting_view": "playlisting",
        "integrations_view": "integraciones",
        # Pleo se configura por empresa desde Integraciones (los endpoints exigen además dirección).
        "pleo_account_save": "integraciones", "pleo_account_test": "integraciones",
        "pleo_account_sync": "integraciones", "pleo_employee_link_save": "integraciones",
        "cabify_account_save": "integraciones", "cabify_account_test": "integraciones",
        "cabify_account_sync": "integraciones", "cabify_user_link_save": "integraciones",
    }
    if endpoint in fixed:
        return fixed[endpoint]
    if endpoint in {"artists_view", "artist_update", "artist_delete", "artist_create"}:
        return "artists"
    # Plantillas del artista (personal / rooming / hoja de ruta) y las PERSONAS del artista (que son
    # terceros que forman parte de él): viven en su ficha.
    if endpoint.startswith("artist_template") or endpoint.startswith("artist_person"):
        return "artists"
    # Cartelería de TODA una gira / ciclo / evento: vive en su ficha, dentro de Contratación.
    if endpoint.startswith("group_artwork"):
        return "contratacion.conciertos"
    if endpoint in {"registros_view", "registros_concert_declare", "registros_promo_declare", "registros_repertoire_link"}:
        return "registros.pendiente"
    if endpoint in {"media_gallery_view", "media_artist_view", "media_panel_view", "api_media_artist_activities"}:
        return "fotos"
    if endpoint == "promoters_view" or endpoint.startswith("promoter_"):
        return "third_parties"
    if endpoint == "venues_view" or endpoint.startswith("venue_"):
        return "databases.venues"
    if endpoint == "ticketers_view" or endpoint.startswith("ticketer_"):
        return "databases.ticketers"
    if endpoint == "publishing_companies_view" or endpoint.startswith("publishing_company_"):
        return "databases.publishing_companies"
    if endpoint == "banks_view" or endpoint.startswith("bank_"):
        return "databases.banks"
    # Las remesas se preparan en Administración → Pendiente → Pago.
    if endpoint.startswith("payment_batch_"):
        return "administracion.pendiente"
    if endpoint == "companies_view" or endpoint.startswith("company_"):
        return "databases.group_companies"
    # Promoción de prensa antes que Marketing: `promo_` no es `promotion_` (ver el enforcement).
    if endpoint == "promo_view" or endpoint.startswith("promo_"):
        return "promo"
    if endpoint in {"promocion_view", "marketing_view"} or endpoint.startswith("promotion_"):
        return "promocion"
    if endpoint in {"acciones_view", "action_detail_view"} or endpoint.startswith("action_") or endpoint.startswith("acciones_"):
        return "acciones"
    if endpoint == "produccion_view":
        return "produccion"
    if endpoint == "administracion_view":
        return "administracion"
    if endpoint == "contabilidad_view":
        return "contabilidad"
    if endpoint == "personnel_view":
        return "personal.usuarios"
    if endpoint in {"personnel_detail_view", "personnel_bulk_access", "personnel_document_save",
                    "personnel_document_delete", "personnel_expense_deadline_toggle",
                    "personnel_expense_deadline_toggle_all"}:
        return "personal.usuarios.accesos"
    if endpoint == "events_view" or endpoint.startswith("event_"):
        return "databases.events"
    if endpoint == "distributors_view" or endpoint.startswith("distributor_"):
        return "databases.distributors"
    if endpoint.startswith("discografica_advance"):
        return "discografica.adelantos"
    # Royalties: acciones en bloque y liquidaciones «a favor» (sus endpoints no llevan el prefijo
    # discografica_, así que hay que mapearlos a mano: si no, solo dirección podría usarlos).
    if endpoint.startswith("royalty_liquidations") or endpoint.startswith("afavor_"):
        return "discografica.royalties"
    if endpoint.startswith("administration_afavor"):
        return "administracion.pendiente"
    # Validar gastos de oficina / inversión de artista y su pago: es tarea de la pestaña Pendiente.
    if (endpoint.startswith("administration_direct_expense")
            or endpoint.startswith("administration_personal_no_invoice")):
        return "administracion.pendiente"
    if endpoint == "discografica_songs_bulk_update":
        return "discografica.canciones"
    if endpoint.startswith("media_"):
        return "databases.media"
    if endpoint.startswith("bag_") or endpoint == "bags_view":
        return "databases.bags"
    if endpoint.startswith("invoice_") or endpoint == "invoices_view":
        return "databases.invoices"
    if endpoint in {"invitations_view", "api_invitation_events", "api_invitation_event_categories"}:
        return "invitaciones"
    if endpoint == "invitation_request_create":
        return "invitaciones.pedir"
    if endpoint.startswith("invitation_") or endpoint.startswith("api_invitation_"):
        return "invitaciones.gestionar"
    return _infer_group_key_from_path(path)


def _build_access_resources_from_app() -> list[dict]:
    """Catálogo efectivo = recursos curados + auto-descubrimiento de funciones nuevas.

    Auto-discovery (futuro-proof, sin duplicados):
    - Si un endpoint YA está cubierto por un recurso curado, no se duplica (esto elimina los
      "auto.*" fantasma que antes clonaban las pantallas de sección).
    - Si un endpoint de ESCRITURA no está cubierto, se registra DESACTIVADO (bajo su sección por
      segmento, o en «Otras funciones») para que sea visible y asignable —nunca accesible solo
      para dirección de forma silenciosa—.
    - Los endpoints de apoyo (alta rápida, vinculaciones, hoja de ruta, búsquedas) NO generan
      recurso: los autoriza la capa SUPPORT_*.
    """
    rows = [dict(item) for item in CURATED_ACCESS_RESOURCES]
    known = {row["key"] for row in rows}
    support = SUPPORT_ACTION_ENDPOINTS | SUPPORT_READ_ENDPOINTS | set(SUPPORT_ECON_READ_ENDPOINTS)
    framework = {"static", "landing", "admin_login", "admin_logout", "personnel_bulk_access",
                 "impersonate_start", "impersonate_stop"}
    write_methods = {"POST", "PUT", "PATCH", "DELETE"}
    dynamic_sort = 901
    for rule in app.url_map.iter_rules():
        endpoint = (rule.endpoint or "").strip()
        if not endpoint or endpoint in framework or endpoint in support:
            continue
        if endpoint.startswith("public_") or "public" in endpoint or endpoint in PUBLIC_ENDPOINTS_EXTRA:
            continue
        path = (rule.rule or "").strip()
        coarse = _coarse_endpoint_resource(endpoint, path)
        if coarse and coarse in known:
            continue  # ya cubierto por un recurso curado -> no duplicar
        # Solo bucketizamos ESCRITURAS: así una función nueva nunca queda solo-dirección en
        # silencio. Las GET sin clasificar conservan su comportamiento (no se ocultan de golpe).
        if not (set(rule.methods or set()) & write_methods):
            continue
        key = f"auto.{endpoint}"
        if key in known:
            continue
        known.add(key)
        segment = path.strip("/").split("/", 1)[0] if path.strip("/") else ""
        parent = AUTO_SEGMENT_PARENT.get(segment)
        if not parent or parent not in known:
            parent = "otros"
        rows.append({
            "key": key,
            "label": _resource_label_from_key(endpoint),
            "section_key": (parent.split(".", 1)[0] if "." in parent else parent),
            "parent_key": parent,
            "level": "TAB",
            "economic_capable": False,
            "sort_order": dynamic_sort,
            "description": f"Función nueva sin clasificar (endpoint «{endpoint}»). Asígnale permisos o reclasifícala en el catálogo.",
        })
        dynamic_sort += 1
    return rows


def _rebuild_resource_caches(resource_rows: list[dict]):
    global _ACCESS_RESOURCE_MAP, _ACCESS_CHILDREN
    _ACCESS_RESOURCE_MAP = {row["key"]: row for row in resource_rows}
    children = defaultdict(list)
    for row in resource_rows:
        parent = row.get("parent_key")
        if parent:
            children[parent].append(row["key"])
    _ACCESS_CHILDREN = children


# Recursos retirados en el rediseño (duplicados/legado): se podan del catálogo y sus grants
# caen en cascada. Quitar de aquí solo si se confirma que ya no existen en ninguna BD.
LEGACY_REMOVED_ACCESS_KEYS = {
    "concerts", "concerts.vista", "concerts.facturacion", "concerts.alta",
    "quadrantes", "marketing",
}


def _sync_access_resources(session_db):
    # Carrera entre WORKERS (procesos): en un deploy con recursos de permisos NUEVOS, varios workers
    # pueden intentar INSERTARLOS a la vez; el segundo espera el lock del índice único y acaba en
    # UniqueViolation ("duplicate key ... user_access_resources_pkey") -> antes eso tumbaba la
    # petición (500 incluso en /static/... -> web en blanco). Un lock de threading NO protege entre
    # procesos, así que se reintenta una vez sobre el estado ya confirmado: en la segunda pasada las
    # claves ya existen y pasan por la rama de UPDATE en vez de INSERT.
    from sqlalchemy.exc import IntegrityError
    try:
        return _sync_access_resources_once(session_db)
    except IntegrityError:
        session_db.rollback()
        return _sync_access_resources_once(session_db)


def _sync_access_resources_once(session_db):
    resource_rows = _build_access_resources_from_app()
    _rebuild_resource_caches(resource_rows)
    desired = {row["key"] for row in resource_rows}
    existing = {r.key: r for r in session_db.query(UserAccessResource).all()}
    for row in resource_rows:
        rec = existing.get(row["key"])
        if not rec:
            rec = UserAccessResource(
                key=row["key"],
                parent_key=row.get("parent_key"),
                section_key=row.get("section_key") or row["key"],
                label=row.get("label") or _resource_label_from_key(row["key"]),
                level=row.get("level") or "SECTION",
                economic_capable=bool(row.get("economic_capable")),
                sort_order=int(row.get("sort_order") or 0),
            )
            session_db.add(rec)
        else:
            rec.parent_key = row.get("parent_key")
            rec.section_key = row.get("section_key") or row["key"]
            rec.label = row.get("label") or rec.label
            rec.level = row.get("level") or rec.level
            rec.economic_capable = bool(row.get("economic_capable"))
            rec.sort_order = int(row.get("sort_order") or 0)
    # Poda segura: elimina recursos retirados (legado) y auto-descubiertos que ya no aplican
    # (p. ej. los "auto.*" fantasma que clonaban pantallas ya cubiertas). NO toca recursos
    # curados ni de modelo: solo legado conocido y "auto.*" huérfanos. Los grants caen en cascada.
    for key, rec in existing.items():
        if key in desired:
            continue
        if key in LEGACY_REMOVED_ACCESS_KEYS or key.startswith("auto."):
            session_db.delete(rec)
    session_db.flush()
    return resource_rows


def _ensure_user_profile(session_db, user: User, legacy_full_seed: bool = False, **kwargs) -> UserProfile:
    profile = session_db.get(UserProfile, user.id)
    if profile:
        changed = False
        if legacy_full_seed and not profile.legacy_permissions_seeded:
            profile.legacy_permissions_seeded = True
            changed = True
        for attr, value in kwargs.items():
            if value is None:
                continue
            if getattr(profile, attr, None) != value:
                setattr(profile, attr, value)
                changed = True
        if changed:
            profile.updated_at = _now_madrid()
        return profile
    profile = UserProfile(
        user_id=user.id,
        nick=(kwargs.get("nick") or _email_to_nick(user.email or "")).strip() or "Usuario",
        photo_url=kwargs.get("photo_url"),
        first_name=kwargs.get("first_name"),
        last_name=kwargs.get("last_name"),
        dni=kwargs.get("dni"),
        birth_date=kwargs.get("birth_date"),
        address=kwargs.get("address"),
        mobile_phones=_normalize_phone_rows(kwargs.get("mobile_phones") or []),
        departments=_normalize_departments(kwargs.get("departments") or []),
        assigned_artist_ids=_normalize_assigned_artist_ids(kwargs.get("assigned_artist_ids") or []),
        # En el ALTA el bucle de kwargs de arriba no se ejecuta: hay que pasarlo aquí a mano.
        admin_responsibilities=_normalize_admin_responsibilities(kwargs.get("admin_responsibilities") or []),
        legacy_permissions_seeded=bool(legacy_full_seed),
    )
    session_db.add(profile)
    session_db.flush()
    return profile


def _ensure_user_security(session_db, user: User) -> UserSecurity:
    # NOTA SEGURIDAD: ya no se almacena la contraseña en claro (password_preview). La gestión de
    # contraseñas se hace solo por hash + enlace de restablecimiento.
    security = session_db.get(UserSecurity, user.id)
    if security:
        return security
    security = UserSecurity(user_id=user.id)
    session_db.add(security)
    session_db.flush()
    return security


def _sync_user_access_grants(session_db, user: User, profile: UserProfile):
    resources = session_db.query(UserAccessResource).order_by(UserAccessResource.sort_order.asc(), UserAccessResource.label.asc()).all()
    existing = {g.resource_key: g for g in session_db.query(UserAccessGrant).filter(UserAccessGrant.user_id == user.id).all()}
    if not existing:
        for resource in resources:
            if profile.legacy_permissions_seeded:
                grant = UserAccessGrant(
                    user_id=user.id,
                    resource_key=resource.key,
                    can_view_basic=True,
                    can_view_econ=bool(resource.economic_capable),
                    can_edit=(resource.key != "home"),
                )
            else:
                grant = UserAccessGrant(
                    user_id=user.id,
                    resource_key=resource.key,
                    can_view_basic=(resource.key == "home"),
                    can_view_econ=False,
                    can_edit=False,
                )
            session_db.add(grant)
        session_db.flush()
        return
    for resource in resources:
        if resource.key in existing:
            continue
        session_db.add(UserAccessGrant(
            user_id=user.id,
            resource_key=resource.key,
            can_view_basic=False,
            can_view_econ=False,
            can_edit=False,
        ))
    session_db.flush()


_ACCESS_BOOTSTRAP_LOCK = threading.Lock()
_ACCESS_CACHES_BUILT = False


def _ensure_access_caches():
    """Construye UNA VEZ POR PROCESO los caches en memoria del catálogo de permisos
    (_ACCESS_RESOURCE_MAP/_ACCESS_CHILDREN) por introspección de la app — SIN tocar la BD.
    Es lo único que necesita cada worker para resolver permisos en las peticiones. La SIEMBRA
    en BD (recursos/usuarios/grants) es aparte: corre una vez por contenedor en 2º plano
    (_bootstrap_personnel_bg). Antes la siembra completa corría en la PRIMERA PETICIÓN de cada
    worker (~10 s con la BD real): las peticiones se encolaban, el escáner de puertos de Render
    veía probes lentísimas y tumbaba la instancia -> web caída/en blanco."""
    global _ACCESS_CACHES_BUILT
    if _ACCESS_CACHES_BUILT:
        return
    with _ACCESS_BOOTSTRAP_LOCK:
        if _ACCESS_CACHES_BUILT:
            return
        _rebuild_resource_caches(_build_access_resources_from_app())
        _ACCESS_CACHES_BUILT = True


def _bootstrap_access_and_personnel():
    # SIEMBRA PESADA (DDL de personal + recursos en BD + usuarios de users.txt + grants + auditoría).
    # La ejecuta SOLO el hilo de 2º plano _bootstrap_personnel_bg (una vez por contenedor, con cerrojo
    # de fichero) — NUNCA el camino de las peticiones, que usa _ensure_access_caches() (sin BD).
    global _ACCESS_BOOTSTRAP_DONE
    if _ACCESS_BOOTSTRAP_DONE:
        return
    with _ACCESS_BOOTSTRAP_LOCK:
        if _ACCESS_BOOTSTRAP_DONE:
            return
        _do_bootstrap_access_and_personnel()


def _do_bootstrap_access_and_personnel():
    # IMPORTANTE: transacciones CORTAS (commit tras los recursos y tras CADA usuario). Antes toda la
    # siembra iba en UNA transacción de minutos: mantenía locks sobre grants/perfiles y cualquier
    # página que sincronizara los grants de SU usuario (mismas filas) se quedaba ESPERANDO esa
    # transacción -> threads del servidor agotados -> timeouts aleatorios (hasta en estáticos) ->
    # Render reiniciaba la instancia -> la siembra volvía a empezar -> bucle de caída perpetuo.
    global _ACCESS_BOOTSTRAP_DONE
    ensure_personnel_and_operations_schema()
    session_db = db()
    try:
        _sync_access_resources(session_db)
        session_db.commit()  # libera cuanto antes los locks del catálogo de recursos
        txt_users = load_users_from_txt()
        for email, rec in txt_users.items():
            email = (email or "").strip().lower()
            if not email:
                continue
            user = session_db.query(User).filter(func.lower(User.email) == email).first()
            if not user:
                user = User(
                    email=email,
                    password_hash=generate_password_hash((rec.get("password") or _generate_temporary_password())),
                    role=int(rec.get("role") or 10),
                )
                session_db.add(user)
                session_db.flush()
            else:
                try:
                    user.role = int(rec.get("role") or getattr(user, "role", 10) or 10)
                except Exception:
                    pass
            # NO pasar nick aquí: la siembra corre en CADA arranque/deploy y, con el perfil ya
            # existente, `nick=` SOBRESCRIBÍA el nick personalizado con el derivado del email (el
            # usuario cambiaba el nick y «al poco tiempo» —tras un deploy— volvía el anterior). Al
            # crear un perfil nuevo, _ensure_user_profile ya usa _email_to_nick(email) como defecto.
            _ensure_user_profile(session_db, user, legacy_full_seed=True)
            _ensure_user_security(session_db, user)
            session_db.commit()  # por usuario: locks brevísimos
        users = session_db.query(User).all()
        for user in users:
            try:
                profile = _ensure_user_profile(session_db, user, legacy_full_seed=True)
                _ensure_user_security(session_db, user)
                _sync_user_access_grants(session_db, user, profile)
                session_db.commit()  # por usuario: locks brevísimos
            except Exception:
                # Carrera con la petición de ese mismo usuario (insertando sus propios grants):
                # rollback y seguimos con el resto — lo que falte se completa en la siguiente pasada.
                session_db.rollback()
        _ACCESS_BOOTSTRAP_DONE = True
    finally:
        session_db.close()
    # Auto-chequeo de cobertura de permisos: avisa (sin romper el arranque) si alguna función
    # de escritura quedó sin recurso -> accesible solo para dirección. Así una funcionalidad
    # nueva mal cableada se detecta en el log en vez de dar "errores de permisos" silenciosos.
    try:
        report = _audit_access_coverage()
        if report["count"]:
            app.logger.warning(
                "[accesos] %d endpoint(s) de escritura sin cobertura de permisos: %s",
                report["count"],
                ", ".join(f"{ep} ({why})" for ep, _path, why in report["offenders"]),
            )
    except Exception:
        pass


def _resource_ancestors(key: str) -> list[str]:
    out = []
    seen = set()
    current = (_ACCESS_RESOURCE_MAP.get(key) or {}).get("parent_key")
    while current and current not in seen:
        out.append(current)
        seen.add(current)
        current = (_ACCESS_RESOURCE_MAP.get(current) or {}).get("parent_key")
    return out


def _descendant_keys(key: str) -> list[str]:
    out = []
    queue = list(_ACCESS_CHILDREN.get(key, []))
    while queue:
        item = queue.pop(0)
        out.append(item)
        queue.extend(_ACCESS_CHILDREN.get(item, []))
    return out


def _resource_has_children(key: str) -> bool:
    return bool(_ACCESS_CHILDREN.get(key))


def _coherent_grant_values(resource, *, view: bool, econ: bool, edit: bool) -> tuple[bool, bool, bool]:
    """Normaliza un grant para que NUNCA tenga contradicciones de permisos.

    Reglas de coherencia:
    - Recursos contenedor (con pestañas hijas): su acceso se DERIVA de las hijas
      (el enforcement usa include_descendants), por lo que su grant propio queda en
      False. Así, activar una sección es solo un atajo sobre sus pestañas y las
      funcionalidades nuevas entran siempre desactivadas.
    - "Ver datos económicos" solo aplica si el recurso tiene datos económicos.
    - Editar ⟹ Ver;  Ver económico ⟹ Ver;  sin Ver ⟹ nada.
    - Editar un recurso con datos económicos ⟹ poder verlos (para poder ejecutarlo).
    """
    if _resource_has_children(resource.key):
        return (False, False, False)
    economic = bool(getattr(resource, "economic_capable", False))
    edit = bool(edit)
    econ = bool(econ) and economic
    view = bool(view) or edit or econ
    if not view:
        return (False, False, False)
    if edit and economic:
        econ = True
    return (view, econ, edit)


def _leaf_keys_under(key: str) -> list[str]:
    """Devuelve las hojas (recursos sin hijos) bajo un recurso; el propio si ya es hoja."""
    leaves = [k for k in _descendant_keys(key) if not _resource_has_children(k)]
    if not leaves and not _resource_has_children(key):
        return [key]
    return leaves


def _grant_matches(grant: dict | None, *, edit: bool = False, econ: bool = False) -> bool:
    if not grant:
        return False
    if edit:
        return bool(grant.get("can_edit"))
    if econ:
        return bool(grant.get("can_view_econ") or grant.get("can_edit"))
    return bool(grant.get("can_view_basic") or grant.get("can_view_econ") or grant.get("can_edit"))


def _state_has_access(state: dict, key: str | None, *, edit: bool = False, econ: bool = False, include_descendants: bool = False) -> bool:
    if not key:
        return False
    if int(state.get("role") or 0) == 10:
        return True
    grants = state.get("grants") or {}
    keys_to_check = [key] + _resource_ancestors(key)
    if include_descendants:
        keys_to_check.extend(_descendant_keys(key))
    seen = set()
    for candidate in keys_to_check:
        if candidate in seen:
            continue
        seen.add(candidate)
        if _grant_matches(grants.get(candidate), edit=edit, econ=econ):
            return True
    return False


def _infer_group_key_from_path(path: str) -> str | None:
    path = (path or "").strip()
    if not path or path == "/":
        return "home"
    for prefix, key in [
        ("/artistas", "artists"),
        ("/discografica", "discografica"),
        ("/promotores", "third_parties"),
        ("/actividades", "actividades"),
        ("/contratacion", "contratacion"),
        ("/conciertos", "contratacion.conciertos"),
        ("/cuadrantes", "contratacion.cuadrantes"),
        ("/emisoras", "radio.emisoras"),
        ("/tocadas", "radio.actualizar"),
        ("/ventas", "ventas"),
        ("/recintos", "databases.venues"),
        ("/ticketeras", "databases.ticketers"),
        ("/editoriales", "databases.publishing_companies"),
        ("/empresas", "databases.group_companies"),
        ("/medios", "databases.media"),
        ("/eventos", "databases.events"),
        ("/distribuidoras", "databases.distributors"),
        ("/bancos", "databases.banks"),
        ("/compradores", "databases.buyers"),
        ("/bolsas", "databases.bags"),
        ("/facturas", "databases.invoices"),
        ("/personal", "personal"),
        ("/promocion", "promocion"),
        ("/marketing", "promocion"),
        ("/acciones", "acciones"),
        ("/produccion", "produccion"),
        ("/administracion", "administracion"),
        ("/contabilidad", "contabilidad"),
        ("/invitaciones", "invitaciones"),
    ]:
        if path.startswith(prefix):
            return key
    return None


# Secciones cuyo TRABAJO vive dentro de la ficha de la actividad: producción monta la hoja de ruta,
# administración la bolsa, promoción su marketing, registros lo que se declara… Todas ellas tienen que
# poder ABRIR la actividad aunque no tengan la pestaña «Conciertos» de Contratación. Para MODIFICARLA
# sigue haciendo falta el permiso de edición de su sección (esto solo afecta a la lectura).
ACTIVITY_READ_ACCESS_KEYS = ("contratacion", "produccion", "administracion", "promocion",
                             "registros", "contabilidad", "acciones", "invitaciones")


def _activity_read_resource_key(default_key: str) -> str:
    """Recurso con el que se comprueba el acceso de LECTURA a una actividad.

    Devuelve la primera sección de `ACTIVITY_READ_ACCESS_KEYS` que el usuario tenga concedida; si no
    tiene ninguna, el recurso por defecto (para que el 403 diga lo que le falta de verdad). Sin esto,
    quien trabaja en Producción se comía un 403 al pinchar cualquier concierto: la ficha exigía la
    pestaña «Conciertos» de Contratación, que no tiene por qué tener.
    """
    if request.method in ("POST", "PUT", "PATCH", "DELETE"):
        return default_key
    try:
        for key in ACTIVITY_READ_ACCESS_KEYS:
            if has_access_key(key, include_descendants=True):
                return key
    except Exception:
        pass
    return default_key


def _resolve_request_resource_key() -> str | None:
    endpoint = (request.endpoint or "").strip()
    if not endpoint:
        return None
    if endpoint in {"landing", "admin_login", "admin_logout"} | PUBLIC_ENDPOINTS_EXTRA:
        return None
    if endpoint == "home":
        return "home"
    if endpoint == "summary_view":
        return "radio.reportes"
    if endpoint == "plays_view":
        return "radio.actualizar"
    if endpoint == "stations_view":
        return "radio.emisoras"
    if endpoint == "sales_report_view":
        return "ventas.reportes"
    if endpoint == "sales_update_view":
        return "ventas.actualizar"
    if endpoint in {"artists_view", "artist_update", "artist_delete", "artist_create"}:
        return "artists"
    # Plantillas del artista (personal / rooming / hoja de ruta) y las PERSONAS del artista (que son
    # terceros que forman parte de él): viven en su ficha.
    if endpoint.startswith("artist_template") or endpoint.startswith("artist_person"):
        return "artists"
    # Cartelería de TODA una gira / ciclo / evento: vive en su ficha, dentro de Contratación.
    if endpoint.startswith("group_artwork"):
        return "contratacion.conciertos"
    if endpoint == "artist_detail_view":
        tab = (request.args.get("tab") or "datos").strip().lower()
        if tab == "personas":
            return "artists.datos"
        if tab in {"datos", "contratos", "conciertos", "discografica", "agenda", "promocion", "marketing", "liquidaciones"}:
            return "artists.promocion" if tab == "marketing" else f"artists.{tab}"
        return "artists"
    if endpoint == "discografica_view":
        section = (request.args.get("section") or "canciones").strip().lower()
        if section == "royalties":
            royalty_tab = (request.args.get("royalty_tab") or request.args.get("tab") or "liquidaciones").strip().lower()
            if royalty_tab in {"liquidaciones", "resumen"}:
                return f"discografica.royalties.{royalty_tab}"
        if section in {"lanzamientos", "canciones", "royalties", "editorial", "registros", "ingresos", "isrc", "adelantos"}:
            return f"discografica.{section}"
        return "discografica"
    if endpoint == "discografica_song_detail":
        tab = (request.args.get("tab") or "informacion").strip().lower()
        mapping = {
            "informacion": "discografica.canciones",
            "materiales": "discografica.canciones",
            "editorial": "discografica.editorial",
            "royalties": "discografica.royalties",
            "ingresos": "discografica.ingresos",
            "radio": "radio.reportes",
            "promocion": "promocion",
            "marketing": "promocion",
            "gastos": "contabilidad",
        }
        return mapping.get(tab, "discografica.canciones")
    if endpoint in {"registros_view", "registros_concert_declare", "registros_promo_declare", "registros_repertoire_link"}:
        tab = (request.args.get("tab") or "pendiente").strip().lower()
        return "registros.sgae" if tab == "sgae" else "registros.pendiente"
    if endpoint == "discografica_album_detail":
        tab = (request.args.get("tab") or "informacion").strip().lower()
        mapping = {
            "informacion": "discografica.canciones",
            "canciones": "discografica.canciones",
            "materiales": "discografica.canciones",
            "beneficiarios": "discografica.royalties",
            "promocion": "promocion",
            "marketing": "promocion",
        }
        return mapping.get(tab, "discografica.canciones")
    if endpoint in {"media_gallery_view", "media_artist_view", "media_panel_view", "api_media_artist_activities"}:
        return "fotos"
    if endpoint == "promoters_view" or endpoint.startswith("promoter_"):
        return "third_parties"
    if endpoint == "venues_view" or endpoint.startswith("venue_"):
        return "databases.venues"
    if endpoint == "ticketers_view" or endpoint.startswith("ticketer_"):
        return "databases.ticketers"
    if endpoint == "publishing_companies_view" or endpoint.startswith("publishing_company_"):
        return "databases.publishing_companies"
    if endpoint == "banks_view" or endpoint.startswith("bank_"):
        return "databases.banks"
    # Las remesas se preparan en Administración → Pendiente → Pago.
    if endpoint.startswith("payment_batch_"):
        return "administracion.pendiente"
    if endpoint == "companies_view" or endpoint.startswith("company_"):
        return "databases.group_companies"
    if endpoint == "activities_view":
        return _activity_read_resource_key("actividades.todas")
    if endpoint == "contracting_view":
        section = (request.args.get("section") or "conciertos").strip().lower()
        mapping = {
            "conciertos": "contratacion.conciertos",
            "peticiones": "contratacion.peticiones",
            "giras-compradas": "contratacion.giras",
            "festivales-ciclos": "contratacion.festivales",
            "eventos": "contratacion.eventos",
            "otras-actividades": "contratacion.otras",
            "cuadrantes": "contratacion.cuadrantes",
            "facturacion": "contratacion.facturacion",
            "simulaciones": "contratacion.simulaciones",
        }
        return mapping.get(section, "contratacion")
    if endpoint.startswith("booking_request"):
        return "contratacion.peticiones"
    if endpoint.startswith("purchased_tour"):
        return "contratacion.giras"
    if endpoint.startswith("cycle_festival"):
        return "contratacion.festivales"
    if endpoint == "concerts_view":
        tab = (request.args.get("tab") or "vista").strip().lower()
        if tab == "facturacion":
            return "contratacion.facturacion"     # la facturación sí es de contratación
        return _activity_read_resource_key("contratacion.conciertos")
    if endpoint == "concert_detail_view":
        tab = (request.args.get("tab") or "general").strip().lower()
        if tab in {"promocion", "marketing"}:
            return "promocion"
        return _activity_read_resource_key("contratacion.conciertos")
    if endpoint == "quadrantes_view":
        return "contratacion.cuadrantes"
    # Contenedores de fechas: el detalle de ciclo/festival y de EVENTO comparten pantalla.
    if endpoint.startswith("cycle_festival"):
        return "contratacion.festivales"
    if endpoint.startswith("simulation_") or endpoint.startswith("api_simulation_"):
        return "contratacion.simulaciones"
    if endpoint == "events_view" or endpoint.startswith("event_"):
        return "databases.events"
    if endpoint == "distributors_view" or endpoint.startswith("distributor_"):
        return "databases.distributors"
    if endpoint.startswith("discografica_advance"):
        return "discografica.adelantos"
    # Royalties: acciones en bloque y liquidaciones «a favor» (sus endpoints no llevan el prefijo
    # discografica_, así que hay que mapearlos a mano: si no, solo dirección podría usarlos).
    if endpoint.startswith("royalty_liquidations") or endpoint.startswith("afavor_"):
        return "discografica.royalties"
    if endpoint.startswith("administration_afavor"):
        return "administracion.pendiente"
    # Validar gastos de oficina / inversión de artista y su pago: es tarea de la pestaña Pendiente.
    if (endpoint.startswith("administration_direct_expense")
            or endpoint.startswith("administration_personal_no_invoice")):
        return "administracion.pendiente"
    if endpoint == "discografica_songs_bulk_update":
        return "discografica.canciones"
    # ⚠️ `promo_` (con guion bajo) es la PROMOCIÓN de prensa y NO pisa a `promotion_`, que es
    # Marketing: "promotion_create" no empieza por "promo_". Todo lo nuevo de promoción se llama
    # `promo_*` justamente para heredar el permiso de su sección sin mapear uno a uno.
    if endpoint == "promo_view" or endpoint.startswith("promo_"):
        # ABRIR la ficha de una promoción lo tiene que poder hacer también quien la produce o quien
        # viaja con el artista, que no tienen por qué tener la sección de Promoción (mismo criterio
        # que `_activity_read_resource_key` con las actividades). Modificar sigue exigiendo `promo`:
        # los endpoints de escritura comprueban `can_edit_promo()` por dentro.
        if endpoint == "promo_detail_view" and request.method == "GET":
            for clave in ("promo", "produccion", "promocion", "administracion"):
                if has_access_key(clave, include_descendants=True):
                    return clave
        return "promo"
    if endpoint == "diseno_view" or endpoint.startswith("diseno_peticion"):
        return "diseno"
    if endpoint == "admin_ita_upload":
        return "administracion.altas"
    if endpoint in {"promocion_view", "marketing_view", "acciones_view", "action_detail_view", "produccion_view", "administracion_view", "contabilidad_view", "personnel_view", "personnel_detail_view", "personnel_bulk_access",
                    "personnel_expense_deadline_toggle", "personnel_expense_deadline_toggle_all"}:
        if endpoint == "administracion_view":
            admin_tab = (request.args.get("tab") or "pendiente").strip().lower()
            if admin_tab in {"pendiente", "liquidaciones", "pagos", "cobros", "embargos", "altas"}:
                return f"administracion.{admin_tab}"
            return "administracion"
        mapping = {
            "promocion_view": "promocion",
            "marketing_view": "promocion",
            "acciones_view": "acciones",
            "action_detail_view": "acciones",
            "produccion_view": "produccion",
            "contabilidad_view": "contabilidad",
            "personnel_view": "personal.usuarios",
            "personnel_detail_view": "personal.usuarios.accesos",
            "personnel_bulk_access": "personal.usuarios.accesos",
            "personnel_document_save": "personal.usuarios.accesos",
            "personnel_document_delete": "personal.usuarios.accesos",
            # Parar/reactivar el plazo de gastos: además exigen dirección dentro del endpoint.
            "personnel_expense_deadline_toggle": "personal.usuarios.accesos",
            "personnel_expense_deadline_toggle_all": "personal.usuarios.accesos",
        }
        return mapping.get(endpoint)
    if endpoint.startswith("action_") or endpoint.startswith("acciones_"):
        return "acciones"
    if endpoint.startswith("promotion_"):
        return "promocion"
    if endpoint.startswith("media_"):
        return "databases.media"
    if endpoint.startswith("bag_") or endpoint == "bags_view":
        return "databases.bags"
    if endpoint.startswith("invoice_") or endpoint == "invoices_view":
        return "databases.invoices"
    # Invitaciones: la página y las APIs de lectura cuelgan de la sección; "pedir" y "gestionar"
    # van a su pestaña concreta. (Los endpoints públicos ya retornan None más arriba.)
    if endpoint in {"invitations_view", "api_invitation_events", "api_invitation_event_categories"}:
        return "invitaciones"
    if endpoint == "invitation_request_create":
        return "invitaciones.pedir"
    # Acciones sobre una solicitud que puede hacer su DUEÑO (con solo "pedir") o un GESTOR (con
    # "gestionar"): se enrutan a la sección para que cualquiera de los dos tabs habilite el POST; el
    # control fino (dueño vs gestor) lo hacen las propias vistas (_is_owner / _ensure_can_manage).
    if endpoint in {"invitation_request_delete", "invitation_request_update", "invitation_request_status"}:
        return "invitaciones"
    if endpoint.startswith("invitation_") or endpoint.startswith("api_invitation_"):
        return "invitaciones.gestionar"
    # Repertorio (canciones) vive bajo /canciones, fuera del prefijo /discografica.
    if endpoint in {"songs_view", "song_update", "song_delete"}:
        return "discografica.canciones"
    if endpoint == "playlisting_view":
        return "playlisting"
    if endpoint == "integrations_view" or endpoint.startswith("pleo_") or endpoint.startswith("cabify_"):
        return "integraciones"
    auto_key = f"auto.{endpoint}"
    if auto_key in _ACCESS_RESOURCE_MAP:
        return auto_key
    return _infer_group_key_from_path(request.path)


def _snapshot_user_profile(profile: UserProfile | None) -> SimpleNamespace | None:
    if not profile:
        return None
    return SimpleNamespace(
        user_id=str(getattr(profile, "user_id", "") or ""),
        nick=(getattr(profile, "nick", None) or "").strip(),
        photo_url=(getattr(profile, "photo_url", None) or "").strip(),
        first_name=(getattr(profile, "first_name", None) or "").strip(),
        last_name=(getattr(profile, "last_name", None) or "").strip(),
        dni=(getattr(profile, "dni", None) or "").strip(),
        birth_date=getattr(profile, "birth_date", None),
        mobile_phones=list(getattr(profile, "mobile_phones", None) or []),
        departments=list(getattr(profile, "departments", None) or []),
        assigned_artist_ids=list(getattr(profile, "assigned_artist_ids", None) or []),
        assigned_artist_ids_produccion=list(getattr(profile, "assigned_artist_ids_produccion", None) or []),
        assigned_artist_ids_sello=list(getattr(profile, "assigned_artist_ids_sello", None) or []),
        # ⚠️ Lo que no esté en este snapshot es INVISIBLE desde `_current_user_state()` y desde las
        # plantillas: es un SimpleNamespace, no el objeto del ORM.
        admin_responsibilities=list(getattr(profile, "admin_responsibilities", None) or []),
        legacy_permissions_seeded=bool(getattr(profile, "legacy_permissions_seeded", False)),
    )


def _snapshot_user_security(security: UserSecurity | None) -> SimpleNamespace | None:
    if not security:
        return None
    return SimpleNamespace(
        user_id=str(getattr(security, "user_id", "") or ""),
        is_blocked=bool(getattr(security, "is_blocked", False)),
        blocked_at=getattr(security, "blocked_at", None),
        is_deleted=bool(getattr(security, "is_deleted", False)),
        deleted_at=getattr(security, "deleted_at", None),
        last_login_at=getattr(security, "last_login_at", None),
        password_last_changed_at=getattr(security, "password_last_changed_at", None),
        password_reset_sent_at=getattr(security, "password_reset_sent_at", None),
    )


def _current_user_state() -> dict:
    cached = getattr(g, "_current_user_state", None)
    if cached is not None:
        return cached
    state = {
        "user_id": None,
        "email": "",
        "role": current_role(),
        "profile": None,
        "security": None,
        "grants": {},
        "nick": "",
        "departments": [],
        "assigned_artist_ids": [],
        "admin_responsibilities": [],
        "photo_url": "",
        "full_name": "",
    }
    uid = session.get("user_id")
    if not uid:
        g._current_user_state = state
        return state
    # Solo caches en memoria (sin BD): la siembra pesada corre en 2º plano (_bootstrap_personnel_bg).
    try:
        _ensure_access_caches()
    except Exception:
        app.logger.exception("[accesos] no se pudieron construir los caches de permisos")
    session_db = db()
    try:
        user = session_db.get(User, to_uuid(uid))
        if not user:
            g._current_user_state = state
            return state
        profile = _ensure_user_profile(session_db, user, legacy_full_seed=False)
        security = _ensure_user_security(session_db, user)
        try:
            _sync_user_access_grants(session_db, user, profile)
            session_db.commit()
        except Exception:
            # Carrera con la siembra en 2º plano (insertando los MISMOS grants de este usuario):
            # rollback y seguimos leyendo los grants existentes — la página no se cae ni espera;
            # los grants que falten aparecen en la siguiente petición.
            session_db.rollback()
        grants = {}
        for grant in session_db.query(UserAccessGrant).filter(UserAccessGrant.user_id == user.id).all():
            grants[grant.resource_key] = {
                "can_view_basic": bool(grant.can_view_basic),
                "can_view_econ": bool(grant.can_view_econ),
                "can_edit": bool(grant.can_edit),
            }
        profile_snapshot = _snapshot_user_profile(profile)
        security_snapshot = _snapshot_user_security(security)
        state.update({
            "user_id": str(user.id),
            "email": (user.email or "").strip(),
            "role": int(getattr(user, "role", 10) or 10),
            "profile": profile_snapshot,
            "security": security_snapshot,
            "grants": grants,
            "nick": (getattr(profile_snapshot, "nick", None) or _email_to_nick(user.email or "")).strip(),
            "departments": list(getattr(profile_snapshot, "departments", None) or []),
            "assigned_artist_ids": list(getattr(profile_snapshot, "assigned_artist_ids", None) or []),
            "admin_responsibilities": list(getattr(profile_snapshot, "admin_responsibilities", None) or []),
            "photo_url": (getattr(profile_snapshot, "photo_url", None) or "").strip(),
            "full_name": _profile_full_name(profile_snapshot),
        })
        g._current_user_state = state
        return state
    finally:
        session_db.close()


def has_access_key(key: str | None, *, edit: bool = False, econ: bool = False, include_descendants: bool = False) -> bool:
    state = _current_user_state()
    return _state_has_access(state, key, edit=edit, econ=econ, include_descendants=include_descendants)


def can_view_economics() -> bool:
    state = _current_user_state()
    key = _resolve_request_resource_key() or _infer_group_key_from_path(request.path)
    if key and _state_has_access(state, key, econ=True, include_descendants=True):
        return True
    return int(state.get("role") or 0) in (3, 4, 6, 10)


def can_edit_radio() -> bool:
    return has_access_key("radio", edit=True, include_descendants=True) or current_role() in (2, 10)


def can_edit_concerts() -> bool:
    return has_access_key("contratacion", edit=True, include_descendants=True) or current_role() in (5, 6, 10)


def can_view_concert_contracts() -> bool:
    """Los contratos de una actividad son confidenciales: solo DIRECCIÓN, CONTRATACIÓN y
    ADMINISTRACIÓN. El resto de la oficina ve la ficha entera menos esa sección (y tampoco puede
    descargarlos: el mismo check protege los endpoints de subida/borrado y el PDF)."""
    return (
        is_master()
        or has_access_key("contratacion", include_descendants=True)
        or has_access_key("administracion", include_descendants=True)
    )


def can_edit_simulations() -> bool:
    # El check sobre "contratacion.simulaciones" ya incluye al antecesor "contratacion".
    return has_access_key("contratacion.simulaciones", edit=True, include_descendants=True) or current_role() in (5, 6, 10)


def can_edit_catalogs() -> bool:
    return (
        has_access_key("artists", edit=True, include_descendants=True)
        or has_access_key("third_parties", edit=True, include_descendants=True)
        or has_access_key("databases", edit=True, include_descendants=True)
        or current_role() in (5, 6, 10)
    )


def can_edit_discografica() -> bool:
    return has_access_key("discografica", edit=True, include_descendants=True) or current_role() in (2, 5, 6, 10)


def can_edit_promocion() -> bool:
    return (has_access_key("promocion", edit=True, include_descendants=True) or current_role() in (2, 5, 6, 10))

def can_edit_marketing() -> bool:
    return can_edit_promocion()


def can_edit_promo() -> bool:
    """PROMOCIÓN de prensa (entrevistas, junts de prensa). Es su propia sección: quien lleva
    marketing no tiene por qué llevar prensa, y al revés."""
    return (has_access_key("promo", edit=True, include_descendants=True) or current_role() in (2, 5, 6, 10))


def can_edit_artists_stations() -> bool:
    return (
        has_access_key("artists", edit=True, include_descendants=True)
        or has_access_key("radio.emisoras", edit=True)
        or current_role() in (2, 5, 6, 10)
    )


def can_edit_sales() -> bool:
    return has_access_key("ventas", edit=True, include_descendants=True) or current_role() in (3, 10)


def can_view_sales_report() -> bool:
    return has_access_key("ventas.reportes", include_descendants=True) or can_edit_sales() or is_master()


def _build_current_user_summary() -> dict:
    state = _current_user_state()
    profile = state.get("profile")
    return {
        "id": state.get("user_id"),
        "nick": state.get("nick") or "Usuario",
        "email": state.get("email") or "",
        "photo_url": state.get("photo_url") or url_for("static", filename="img/placeholder_photo.png"),
        "departments": list(state.get("departments") or []),
        "full_name": state.get("full_name") or "",
        "phones": list(getattr(profile, "mobile_phones", None) or []),
    }


