# Orden canónico (así cada departamento sale en el orden pedido).
_HOME_QUICK_ORDER = ["actividad", "peticion", "simulacion", "cuadrantes", "single",
                     "pagos", "liquidar", "facturas", "gastos_mios", "invitaciones"]

# Acciones por DEPARTAMENTO (nombres tal cual en PERSONNEL_DEPARTMENTS).
_HOME_QUICK_BY_DEPARTMENT = {
    "Contratación": ["actividad", "peticion", "simulacion", "cuadrantes", "invitaciones"],
    "Sello": ["actividad", "peticion", "invitaciones"],
    "Registros": ["peticion", "single", "invitaciones"],
    "Administración": ["peticion", "pagos", "liquidar", "facturas", "gastos_mios"],
}
# Quien no está en ninguno de los departamentos de arriba ve lo transversal.
_HOME_QUICK_DEFAULT = ["peticion", "invitaciones"]


def _build_home_quick_actions() -> list[dict]:
    state = _current_user_state()
    depts = [str(d).strip() for d in (state.get("departments") or []) if str(d).strip()]
    wanted: set = set()
    for dept in depts:
        for k in _HOME_QUICK_BY_DEPARTMENT.get(dept, []):
            wanted.add(k)
    if is_master():
        wanted = set(_HOME_QUICK_ORDER)     # dirección lo ve todo
    elif not wanted:
        wanted = set(_HOME_QUICK_DEFAULT)
    defs = _home_quick_action_defs()
    out = []
    for key in _HOME_QUICK_ORDER:
        if key not in wanted:
            continue
        row = defs.get(key)
        if not row:
            continue
        access = row.get("access")
        if access and not has_access_key(access, include_descendants=True):
            continue
        out.append(row)
    return out


def _build_personnel_access_rows() -> list[dict]:
    session_db = db()
    try:
        rows = session_db.query(UserAccessResource).order_by(UserAccessResource.sort_order.asc(), UserAccessResource.label.asc()).all()
        # Adjuntamos la descripción (función + pestaña) desde el catálogo en memoria para que la
        # pantalla de Accesos sea autoexplicativa. No es columna de BD: atributo transitorio.
        for row in rows:
            row.access_desc = (_ACCESS_RESOURCE_MAP.get(row.key) or {}).get("description", "") or ""
        grouped = []
        section_map = {}
        for row in rows:
            if row.level == "SECTION":
                section_entry = {"section": row, "children": []}
                grouped.append(section_entry)
                section_map[row.key] = section_entry
        for row in rows:
            if row.level == "SECTION":
                continue
            parent = section_map.get(row.section_key) or section_map.get(row.parent_key)
            if parent is None:
                continue
            parent["children"].append(row)
        return grouped
    finally:
        session_db.close()


def _media_contact_display(contact: MediaContact | None) -> str:
    if not contact:
        return ""
    name = " ".join([x for x in [
        (contact.first_name or "").strip(),
        (contact.last_name or "").strip(),
    ] if x]).strip()
    pieces = [
        (contact.program or "").strip(),
        (contact.role or "").strip(),
        name,
        (contact.phone or "").strip(),
        (contact.email or "").strip(),
    ]
    return " · ".join([p for p in pieces if p])


# ============================================================================================
# TAREAS PENDIENTES de Contratación (motor único de la barra de pestañas y del módulo de arriba)
#
# El NÚMERO de cada pestaña NO es cuántas actividades hay, sino cuántas TAREAS quedan por hacer
# en ella (se recalcula en cada carga, así que va siempre al día). Las mismas tareas se pintan en
# el módulo «Tareas pendientes» que abre cada pestaña (`templates/_contracting_tasks.html`).
#
# Qué es una tarea, por actividad VIVA (de hoy en adelante):
#   · sin confirmar               → hay que cerrarla;
#   · confirmada sin contrato     → falta subir el contrato;
#   · confirmada sin anuncio      → nadie ha decidido cuándo se anuncia (ni «no anunciar»);
#   · confirmada sin mandar a producción (sin bolsa, y solo si le toca `_concert_needs_production`).
# El dinero pendiente NO es tarea de la pestaña de la actividad: los pagos por facturar y por
# cobrar son tareas de **Facturación** (y ahí sí cuentan también las fechas ya pasadas, que son
# justo las que urgen). Las peticiones abiertas son las tareas de **Peticiones**.
#
# Alcance: se filtra por los ARTISTAS ASIGNADOS del usuario; quien no tenga ninguno (y dirección)
# ve todas.
# ============================================================================================
CONTRACTING_COUNT_TABS = ("peticiones", "conciertos", "giras-compradas", "festivales-ciclos",
                          "eventos", "otras-actividades", "facturacion")

# Pantallas que llevan la barra de pestañas de Contratación (y por tanto necesitan las tareas).
CONTRACTING_TAB_ENDPOINTS = {"contracting_view", "concerts_view", "quadrantes_view", "tour_detail_view"}

# Catálogo de tareas: etiqueta · icono · color de la pastilla · orden de urgencia.
CONTRACTING_TASK_META = {
    "REQUEST":    ("Petición sin tramitar", "fa-inbox", "text-bg-danger", 0),
    "CONFIRM":    ("Pendiente de confirmar", "fa-circle-question", "text-bg-warning text-dark", 1),
    "CONTRACT":   ("Sin contrato", "fa-file-signature", "text-bg-secondary", 2),
    "ANNOUNCE":   ("Pendiente de anunciar", "fa-bullhorn", "text-bg-info text-dark", 3),
    "PRODUCTION": ("Sin mandar a producción", "fa-people-carry-box", "text-bg-dark", 4),
    "INVOICE":    ("Pendiente de facturar", "fa-file-circle-plus", "text-bg-secondary", 5),
    "COLLECT":    ("Pendiente de cobrar", "fa-hourglass-half", "text-bg-warning text-dark", 6),
}


def _contracting_activity_tabs(c) -> list[str]:
    """En qué pestañas de Contratación sale esta actividad (mismo criterio que sus listados).

    Una actividad puede salir en dos (p. ej. un concierto dentro de un ciclo): su tarea aparece
    en las dos, porque en cada pestaña sigue siendo trabajo por hacer.
    """
    if getattr(c, "event_id", None):
        return ["eventos"]          # las de un evento salen SOLO en su pestaña
    sale = (getattr(c, "sale_type", None) or "").upper()
    act = (getattr(c, "activity_type", None) or "CONCIERTO").upper()
    tabs = []
    if sale == "GIRAS_COMPRADAS" or act == "GIRA" or getattr(c, "purchased_tour_id", None):
        tabs.append("giras-compradas")
    if act == "FESTIVAL" or getattr(c, "cycle_festival_id", None):
        tabs.append("festivales-ciclos")
    if act in ("EVENTO_PROMOCIONAL", "TV", "MARCA", "OTROS"):
        tabs.append("otras-actividades")
    if (sale not in ("GIRAS_COMPRADAS", "CADIZ")
            and act not in ("FESTIVAL", "GIRA", "EVENTO_PROMOCIONAL", "TV", "MARCA", "OTROS")):
        tabs.append("conciertos")
    return tabs or ["conciertos"]


def _contracting_task_artist_ids() -> set:
    """Artistas asignados al usuario. Conjunto vacío = ve todas (dirección y quien no tenga)."""
    if is_master():
        return set()
    try:
        return {str(x) for x in (_current_user_state().get("assigned_artist_ids") or []) if x}
    except Exception:
        return set()


def _contracting_task_badge(kind: str) -> dict:
    """La pastilla de UNA tarea (para poder poner varias en la misma fila de una actividad)."""
    label, icon, badge, order = CONTRACTING_TASK_META.get(
        kind, ("Pendiente", "fa-circle-exclamation", "text-bg-light border", 9))
    return {"kind": kind, "label": label, "icon": icon, "badge": badge, "order": order}


def _contracting_task_row(c, kind: str, payment: dict | None = None, event=None) -> dict:
    """Una fila del módulo de tareas.

    La cabecera es la IDENTIDAD de la actividad, en este orden: de quién es (artista o EVENTO, con
    su foto), qué es (concierto, acto promocional…), cuándo, cómo se llama (si es un festival) y
    dónde (municipio, provincia y recinto). Debajo van sus tareas.
    ⚠️ Si la actividad es de un EVENTO manda el evento, no el artista ESPEJO (`Artist.event_id`),
    que es un apaño interno y no debe verse.
    """
    label, icon, badge, order = CONTRACTING_TASK_META.get(
        kind, ("Pendiente", "fa-circle-exclamation", "text-bg-light border", 9))
    art = getattr(c, "artist", None)
    venue = getattr(c, "venue", None)
    es_evento = bool(event)
    if kind == "PRODUCTION":
        url = url_for("concert_detail_view", cid=c.id, tab="produccion")
    elif kind in ("INVOICE", "COLLECT"):
        url = url_for("concerts_view", tab="facturacion") + "#billing-" + str(c.id)
    else:
        url = url_for("concert_detail_view", cid=c.id, tab="general")
    extra = ""
    if payment:
        extra = " · ".join([x for x in [(payment.get("concept") or "").strip(),
                                        format_eur(payment.get("amount"))] if x])
    act = (getattr(c, "activity_type", None) or "").strip().upper()
    act_key = QUAD_ACTIVITY_ALIASES.get(act, act if act in QUAD_ACTIVITY_LABELS else "CONCIERTO")
    return {
        "kind": kind, "label": label, "icon": icon, "badge": badge, "order": order,
        "id": str(c.id),
        # --- De quién es (con su foto): el EVENTO si lo hay, si no el artista ---
        "subject_name": ((getattr(event, "name", None) or "") if es_evento
                         else (getattr(art, "name", None) or "")),
        "subject_photo": ((getattr(event, "logo_url", None) or "") if es_evento
                          else (getattr(art, "photo_url", None) or "")),
        "subject_id": (str(getattr(event, "id", "")) if es_evento
                       else (str(c.artist_id) if getattr(c, "artist_id", None) else "")),
        "is_event": es_evento,
        # --- Qué es ---
        "activity_label": QUAD_ACTIVITY_LABELS.get(act_key, "Concierto"),
        "activity_icon": QUAD_ACTIVITY_ICONS.get(act_key, "fa-guitar"),
        # --- Cuándo ---
        "date": getattr(c, "date", None),
        "date_label": (c.date.strftime("%d/%m/%Y") if getattr(c, "date", None) else ""),
        # --- Cómo se llama y dónde ---
        "festival_name": (getattr(c, "festival_name", None) or "").strip(),
        "municipality": ((getattr(venue, "municipality", None) or "")
                         or (getattr(c, "manual_municipality", None) or "")).strip(),
        "province": ((getattr(venue, "province", None) or "")
                     or (getattr(c, "manual_province", None) or "")).strip(),
        "venue_name": ((getattr(venue, "name", None) or "")
                       or (getattr(c, "manual_venue_name", None) or "")).strip(),
        "extra": extra,
        "url": url,
        # Compatibilidad con lo que ya leía la plantilla.
        "artist_name": (getattr(art, "name", None) or ""),
        "title": (getattr(c, "festival_name", None) or "").strip(),
    }


def _contracting_tasks_data() -> dict:
    """Tareas pendientes agrupadas por pestaña. Se calcula UNA vez por petición (`g`), porque lo
    piden a la vez la barra de pestañas (el número) y el módulo de arriba (las filas)."""
    cached = getattr(g, "_contracting_tasks_cache", None)
    if cached is not None:
        return cached
    by_tab = {k: [] for k in CONTRACTING_COUNT_TABS}
    session_db = db()
    try:
        hoy = today_local()
        mios = _contracting_task_artist_ids()

        def _visible(obj) -> bool:
            if not mios:
                return True
            if str(getattr(obj, "artist_id", "") or "") in mios:
                return True
            return any(str(x) in mios for x in (getattr(obj, "artist_ids", None) or []))

        # ---- Actividades vivas: confirmar · contrato · anuncio · producción ----
        vivas = (session_db.query(Concert)
                 .options(joinedload(Concert.artist), joinedload(Concert.venue))
                 .filter(or_(Concert.date.is_(None), Concert.date >= hoy))
                 .order_by(Concert.date.asc().nullslast())
                 .all())
        vivas = [c for c in vivas if _visible(c)]
        ids = [c.id for c in vivas]
        # Los EVENTOS de golpe: en la fila manda el evento, no el artista espejo.
        eventos = {}
        _ev_ids = {c.event_id for c in vivas if getattr(c, "event_id", None)}
        if _ev_ids:
            eventos = {e.id: e for e in session_db.query(AppEvent).filter(AppEvent.id.in_(_ev_ids)).all()}
        con_contrato, con_bolsa = set(), set()
        if ids:
            con_contrato = {r[0] for r in session_db.query(ConcertContract.concert_id)
                            .filter(ConcertContract.concert_id.in_(ids)).all()}
            con_bolsa = {r[0] for r in session_db.query(WorkflowBag.linked_id)
                         .filter(WorkflowBag.linked_type.in_(("CONCERT", "concert")),
                                 WorkflowBag.linked_id.in_(ids)).all()}
        for c in vivas:
            kinds = []
            if (getattr(c, "status", None) or "BORRADOR").upper() != "CONFIRMADO":
                kinds.append("CONFIRM")
            else:
                if c.id not in con_contrato:
                    kinds.append("CONTRACT")
                if not getattr(c, "announcement_date", None) and not getattr(c, "do_not_announce", False):
                    kinds.append("ANNOUNCE")
                if _concert_needs_production(c, session_db) and c.id not in con_bolsa:
                    kinds.append("PRODUCTION")
            if not kinds:
                continue
            tabs = _contracting_activity_tabs(c)
            # Una sola fila por ACTIVIDAD, con TODAS sus tareas dentro: si a un concierto le faltan
            # el contrato, el anuncio y mandarlo a producción, se ve de un vistazo en una línea en
            # vez de repetir la misma actividad tres veces.
            row = _contracting_task_row(c, kinds[0], event=eventos.get(getattr(c, "event_id", None)))
            row["tasks"] = [_contracting_task_badge(k) for k in kinds]
            for t in tabs:
                by_tab.setdefault(t, []).append(row)

        # ---- Facturación: pagos por facturar y por cobrar (también de fechas pasadas) ----
        try:
            con_pagos = (session_db.query(Concert)
                         .options(joinedload(Concert.artist), joinedload(Concert.venue))
                         .filter(func.jsonb_typeof(Concert.payment_terms_json) == "array")
                         .filter(func.jsonb_array_length(Concert.payment_terms_json) > 0)
                         .order_by(Concert.date.asc().nullslast())
                         .all())
        except Exception:
            con_pagos = []
        _ev_pagos = {c.event_id for c in con_pagos if getattr(c, "event_id", None)}
        if _ev_pagos:
            for e in session_db.query(AppEvent).filter(AppEvent.id.in_(_ev_pagos)).all():
                eventos[e.id] = e
        for c in con_pagos:
            if not _visible(c):
                continue
            for p in _concert_payment_rows(c, pending_only=True):
                kind = "INVOICE" if (p.get("status") or "") == "PENDING_INVOICE" else "COLLECT"
                fila = _contracting_task_row(c, kind, payment=p,
                                             event=eventos.get(getattr(c, "event_id", None)))
                fila["tasks"] = [_contracting_task_badge(kind)]
                by_tab["facturacion"].append(fila)

        # ---- Peticiones abiertas (las sin artista concreto las ve todo el mundo) ----
        try:
            abiertas = (session_db.query(BookingRequest)
                        .options(joinedload(BookingRequest.artist))
                        .filter(func.upper(func.coalesce(BookingRequest.status, "NUEVA"))
                                .in_(list(BOOKING_OPEN_STATUSES)))
                        .order_by(BookingRequest.received_at.desc().nullslast(),
                                  BookingRequest.created_at.desc())
                        .limit(300).all())
        except Exception:
            abiertas = []
        label, icon, badge, order = CONTRACTING_TASK_META["REQUEST"]
        for r in abiertas:
            if not _booking_in_department(r, "CONTRATACION"):
                continue
            if mios and getattr(r, "artist_id", None) and str(r.artist_id) not in mios:
                continue
            row = _booking_request_row(r)
            row.update({
                "kind": "REQUEST", "label": row.get("status_label") or label, "icon": icon,
                "badge": row.get("status_badge") or badge, "order": order,
                "title": (row.get("subject") or ""),
                "activity_label": "Petición",
                "date": getattr(r, "requested_date", None),
                "place": " · ".join([x for x in [row.get("municipality"), row.get("province")] if x]),
                "extra": (row.get("fee_text") or ""),
                "url": url_for("booking_request_detail_view", rid=r.id),
            })
            row.update({
                "subject_name": row.get("artist_name") or "",
                "subject_photo": row.get("artist_photo") or "",
                "subject_id": row.get("artist_id") or "",
                "is_event": False,
                "activity_label": "Petición",
                "activity_icon": "fa-inbox",
                "festival_name": (row.get("subject") or ""),
                "municipality": (row.get("municipality") or ""),
                "province": (row.get("province") or ""),
                "venue_name": "",
            })
            row["tasks"] = [{"kind": "REQUEST", "label": row["label"], "icon": icon,
                             "badge": row["badge"]}]
            by_tab["peticiones"].append(row)
    except Exception:
        pass
    finally:
        session_db.close()
    for rows in by_tab.values():
        for r in rows:
            if not r.get("tasks"):
                r["tasks"] = [_contracting_task_badge(r.get("kind") or "")]
            r["tasks_count"] = len(r["tasks"])
            # La fila se ordena por su tarea MÁS urgente.
            r["order"] = min((t.get("order") or 9) for t in r["tasks"])
        rows.sort(key=lambda r: (r.get("date") or date.max, r.get("order") or 9,
                                 (r.get("artist_name") or "").lower()))
    # El número de la pestaña son las ACTIVIDADES que tienen algo pendiente, no las tareas sueltas:
    # una actividad a la que le faltan el contrato, el anuncio y mandarla a producción cuenta UNA.
    # Es lo que se lee de un vistazo («me quedan 4 conciertos por rematar»), y cuadra con las filas
    # que se ven debajo.
    data = {"tasks": by_tab, "counts": {k: len(v) for k, v in by_tab.items() if v}}
    try:
        g._contracting_tasks_cache = data
    except Exception:
        pass
    return data


def _contracting_tab_counts() -> dict:
    """Número de la barra de pestañas = TAREAS pendientes de cada una (no cuántas actividades hay)."""
    try:
        return _contracting_tasks_data()["counts"]
    except Exception:
        return {}


def _section_stats_counts() -> dict:
    session_db = db()
    try:
        return {
            "media": session_db.query(MediaOutlet).count(),
            "bags_active": session_db.query(WorkflowBag).filter(WorkflowBag.is_archived == False).count(),  # noqa: E712
            "invoices": session_db.query(InvoiceRecord).count(),
            "users": session_db.query(User).count(),
        }
    finally:
        session_db.close()


def _impersonator_nick() -> str:
    """Nick del usuario real (dirección) cuando se está en modo «Ver como»."""
    imp = session.get("impersonator_id")
    if not imp:
        return ""
    session_db = db()
    try:
        prof = session_db.get(UserProfile, to_uuid(imp))
        if prof and (getattr(prof, "nick", None) or "").strip():
            return prof.nick.strip()
        u = session_db.get(User, to_uuid(imp))
        return _email_to_nick(u.email) if u and u.email else "dirección"
    except Exception:
        return "dirección"
    finally:
        session_db.close()


