def _promotion_calendar_months(items, months_count=3):
    months = []
    today = today_local()
    month_cursor = date(today.year, today.month, 1)
    month_limit = _add_months(month_cursor, months_count)
    by_date = defaultdict(list)
    for item in items or []:
        dt = item.get("date")
        if not dt or dt < month_cursor or dt >= month_limit:
            continue
        by_date[dt].append(item)
    for month_idx in range(months_count):
        first_day = _add_months(month_cursor, month_idx)
        next_month = _add_months(first_day, 1)
        last_day = next_month - timedelta(days=1)
        start_day = first_day - timedelta(days=first_day.weekday())
        end_day = last_day + timedelta(days=(6 - last_day.weekday()))
        weeks = []
        cursor = start_day
        while cursor <= end_day:
            week = []
            for _ in range(7):
                week.append({
                    "date": cursor,
                    "in_month": cursor.month == first_day.month,
                    "items": list(by_date.get(cursor, [])),
                })
                cursor += timedelta(days=1)
            weeks.append(week)
        months.append({"key": first_day.strftime("%Y-%m"), "label": _month_label(first_day), "weeks": weeks})
    return months


def _promotion_creator_datasets(session_db):
    default_cover = url_for("static", filename="img/placeholder_photo.png")
    artists = session_db.query(Artist).order_by(Artist.name.asc()).all()
    artist_items = [{"id": str(a.id), "name": a.name, "photo_url": (a.photo_url or default_cover)} for a in artists]

    song_rows = session_db.query(Song).options(selectinload(Song.artists)).order_by(Song.release_date.desc().nullslast(), Song.created_at.desc()).all()
    _annotate_song_display_fields(session_db, song_rows, persist=False)
    song_items = []
    for song in song_rows:
        song_items.append({
            "id": str(song.id),
            "artist_ids": [str(a.id) for a in (song.artists or []) if getattr(a, 'id', None)],
            "title": song.title,
            "subtitle": ", ".join([a.name for a in (song.artists or []) if getattr(a, 'name', None)]) or "—",
            "meta": (getattr(song, 'display_collaborator', None) or getattr(song, 'collaborator', None) or '').strip(),
            "cover_url": (song.cover_url or default_cover),
            "date": song.release_date.isoformat() if getattr(song, 'release_date', None) else "",
        })

    album_rows = session_db.query(Album).options(joinedload(Album.artist)).order_by(Album.release_date.desc().nullslast(), Album.created_at.desc()).all()
    album_items = []
    for album in album_rows:
        album_items.append({
            "id": str(album.id),
            "artist_ids": [str(album.artist_id)] if getattr(album, 'artist_id', None) else [],
            "title": album.title,
            "subtitle": (getattr(getattr(album, 'artist', None), 'name', None) or '—'),
            "meta": ("EP" if (getattr(album, 'album_type', None) or '').strip().upper() == 'EP' else 'Álbum'),
            "cover_url": (album.cover_url or default_cover),
            "date": album.release_date.isoformat() if getattr(album, 'release_date', None) else "",
        })

    concert_rows = session_db.query(Concert).options(joinedload(Concert.artist), joinedload(Concert.venue), joinedload(Concert.billing_company)).order_by(Concert.date.desc().nullslast(), Concert.created_at.desc()).all()
    concert_items = []
    for concert in concert_rows:
        concert_items.append({
            "id": str(concert.id),
            "artist_ids": [str(concert.artist_id)] if getattr(concert, 'artist_id', None) else [],
            "title": (getattr(getattr(concert, 'artist', None), 'name', None) or 'Concierto'),
            "subtitle": _concert_venue_name(concert) or 'Recinto pendiente',
            "meta": concert.date.strftime('%d/%m/%Y') if getattr(concert, 'date', None) else '',
            "cover_url": (getattr(getattr(concert, 'artist', None), 'photo_url', None) or default_cover),
            "date": concert.date.isoformat() if getattr(concert, 'date', None) else '',
            "default_company_id": str(concert.billing_company_id) if getattr(concert, 'billing_company_id', None) else '',
        })

    # Eventos propios (Bases de datos → Eventos): no cuelgan de ningún artista, así que se listan
    # siempre, sin filtrar por los artistas marcados.
    event_items = [{
        "id": str(ev.id),
        "artist_ids": [],
        "title": (ev.name or "Evento"),
        "subtitle": "Evento",
        "meta": "",
        "cover_url": (ev.logo_url or default_cover),
        "date": "",
        "any_artist": True,
    } for ev in session_db.query(AppEvent).order_by(AppEvent.name.asc()).all()]

    # Giras compradas y festivales/ciclos: se ELIGEN de las creadas en Contratación para que el
    # marketing quede colgado del contenedor y se vea en su ficha (antes la gira era texto libre y
    # la campaña se quedaba huérfana, sin aparecer en ningún sitio).
    tour_items = [{
        "id": str(t.id),
        "artist_ids": _promotion_normalized_artist_ids(
            ([str(t.artist_id)] if getattr(t, "artist_id", None) else []) + [str(x) for x in (getattr(t, "artist_ids", None) or [])]
        ),
        "title": (t.name or "Gira"),
        "subtitle": (getattr(getattr(t, "artist", None), "name", None) or "Gira comprada"),
        "meta": t.start_date.strftime('%d/%m/%Y') if getattr(t, "start_date", None) else "",
        "cover_url": ((t.logo_url or "").strip() or (getattr(getattr(t, "artist", None), "photo_url", None) or default_cover)),
        "date": t.start_date.isoformat() if getattr(t, "start_date", None) else "",
        "default_company_id": str(t.managing_company_id) if getattr(t, "managing_company_id", None) else "",
    } for t in (session_db.query(PurchasedTour)
                .options(joinedload(PurchasedTour.artist))
                .order_by(PurchasedTour.start_date.desc().nullslast(), PurchasedTour.created_at.desc()).all())]

    cycle_items = [{
        "id": str(cf.id),
        "artist_ids": [],
        "title": (cf.name or "Ciclo"),
        "subtitle": CYCLE_FESTIVAL_KIND_LABELS.get((cf.kind or "FESTIVAL").upper(), "Ciclo"),
        "meta": " · ".join([x for x in [(cf.edition or "").strip(), (cf.municipality or "").strip()] if x]),
        "cover_url": ((cf.logo_url or "").strip() or default_cover),
        "date": cf.start_date.isoformat() if getattr(cf, "start_date", None) else "",
        "default_company_id": str(cf.managing_company_id) if getattr(cf, "managing_company_id", None) else "",
        "any_artist": True,
    } for cf in session_db.query(CycleFestival).order_by(CycleFestival.start_date.desc().nullslast(), CycleFestival.created_at.desc()).all()]

    company_items = [{"id": str(c.id), "name": c.name} for c in session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all()]

    return {
        "artists": artist_items,
        "subjects": {
            "ARTIST": [{"id": x["id"], "artist_ids": [x["id"]], "title": x["name"], "subtitle": "Marketing general de artista", "meta": "Artista", "cover_url": x["photo_url"], "date": ""} for x in artist_items],
            "SONG": song_items,
            "ALBUM": album_items,
            "CONCERT": concert_items,
            "EVENT": event_items,
            "GIRA": tour_items,
            "CICLO": cycle_items,
        },
        "companies": company_items,
    }


def _promotion_request_recipients(row):
    emails = []
    requested_by_email = (getattr(row, 'requested_by_email', None) or '').strip()
    if requested_by_email and _looks_like_email_address(requested_by_email):
        emails.append(requested_by_email)
    return _dedupe_valid_email_addresses(emails)


def _build_promotion_rejection_email(row, reviewer_label, reason):
    snap = dict(getattr(row, 'snapshot', None) or {})
    title = (snap.get('title') or 'promoción').strip()
    kind_label = (snap.get('kind_label') or 'Marketing').strip()
    reviewer_label = (reviewer_label or 'Usuario del Back Office').strip()
    reason = (reason or '').strip() or 'Sin motivo indicado.'
    html_body = (
        '<div style="font-family:Arial,sans-serif;color:#1f2937;">'
        f'<h2 style="margin-bottom:12px;">Solicitud de promoción rechazada</h2>'
        f'<p>La solicitud para <strong>{html.escape(title)}</strong> ({html.escape(kind_label)}) ha sido rechazada.</p>'
        f'<p><strong>Revisado por:</strong> {html.escape(reviewer_label)}</p>'
        f'<p><strong>Motivo:</strong><br>{html.escape(reason).replace(chr(10), "<br>")}</p>'
        '</div>'
    )
    text_body = f"Solicitud de promoción rechazada\n\nElemento: {title} ({kind_label})\nRevisado por: {reviewer_label}\nMotivo: {reason}"
    subject = f"Solicitud de promoción rechazada · {title}"
    return subject, html_body, text_body


def _promotion_primary_artist_uuid(promotion_row):
    artist_ids = _promotion_normalized_artist_ids(getattr(promotion_row, 'artist_ids', None) or [])
    if not artist_ids:
        return None
    try:
        return to_uuid(artist_ids[0])
    except Exception:
        return None


def _ensure_promotion_bag(session_db, promotion_row):
    if getattr(promotion_row, 'bag_id', None):
        return
    snap = dict(getattr(promotion_row, 'snapshot', None) or {})
    title = (snap.get('title') or 'Marketing').strip() or 'Marketing'
    bag = WorkflowBag(
        title=f"Marketing · {title}",
        artist_id=_promotion_primary_artist_uuid(promotion_row),
        company_id=getattr(promotion_row, 'company_id', None),
        start_date=getattr(promotion_row, 'target_date', None),
        description=((getattr(promotion_row, 'objectives_notes', None) or '').strip() or None),
        status='ACTIVA',
        is_archived=False,
    )
    session_db.add(bag)
    session_db.flush()
    promotion_row.bag_id = bag.id


def _marketing_seed_action(session_db, promotion_row):
    """Una «acción concreta» de marketing tiene que acabar CREADA y a gestionar.

    Antes solo se creaba el contenedor (la campaña) y la pestaña Acciones salía vacía: no había nada
    que gestionar ni nada que sumar en la ficha del artista / concierto / gira. Aquí se materializa la
    acción con lo que ya dijo el asistente (tipo, fechas y objetivos), pendiente de consolidar."""
    if (getattr(promotion_row, "request_kind", None) or "PLAN").strip().upper() != "ACTION":
        return None
    types = [str(x).strip().upper() for x in (getattr(promotion_row, "action_types", None) or []) if str(x).strip()]
    action_type = next((x for x in types if x in MARKETING_ACTION_TYPE_LABELS), "OTRA")
    starts_on = getattr(promotion_row, "starts_on", None)
    ends_on = getattr(promotion_row, "ends_on", None)
    # `activity_date` es NOT NULL: si no hay plazo se ancla en la fecha objetivo (o en hoy).
    when = starts_on or getattr(promotion_row, "target_date", None) or today_local()
    waves = []
    if starts_on or ends_on:
        waves = [{"start": starts_on.isoformat() if starts_on else None,
                  "end": ends_on.isoformat() if ends_on else None, "note": None}]
    row = PromotionActivity(
        promotion_id=promotion_row.id,
        activity_date=when,
        activity_kind="MARKETING",
        action_type=action_type,
        execution_mode="PERIODO",
        waves_json=waves,
        details_json={"end_date": ends_on.isoformat() if ends_on else None,
                      "seeded_from_wizard": True},
        task_description=(getattr(promotion_row, "objectives_notes", None) or "").strip() or None,
        consolidation_status="PENDIENTE",
        created_by_user_id=getattr(promotion_row, "created_by_user_id", None),
        created_by_nick=(getattr(promotion_row, "created_by_nick", None) or "").strip() or None,
    )
    session_db.add(row)
    return row


def _promotion_activity_time_sort(row):
    if bool(getattr(row, 'time_tbc', False)):
        return ('99:99', '99:99')
    start = (getattr(row, 'start_time', None) or '').strip() or '99:99'
    end = (getattr(row, 'end_time', None) or '').strip() or start
    return (start, end)


def _promotion_activity_time_label(row):
    if bool(getattr(row, 'time_tbc', False)):
        return 'TBC'
    start = (getattr(row, 'start_time', None) or '').strip()
    end = (getattr(row, 'end_time', None) or '').strip()
    if start and end:
        return f"{start} - {end}"
    if start:
        return start
    return 'Sin hora'


def _promotion_activity_display(row, song_title_map):
    details = dict(getattr(row, 'details_json', None) or {})
    label = PROMOTION_ACTIVITY_KIND_LABELS.get((getattr(row, 'activity_kind', None) or '').strip().upper(), getattr(row, 'activity_kind', None) or 'Actividad')
    subtitle_parts = []
    if (getattr(row, 'activity_kind', None) or '').strip().upper() == 'PROMOCION':
        media_label = (getattr(getattr(row, 'media', None), 'name', None) or details.get('media_name') or '').strip()
        program_label = (details.get('program_name') or '').strip()
        if media_label:
            subtitle_parts.append(media_label)
        if program_label:
            subtitle_parts.append(program_label)
    elif (getattr(row, 'activity_kind', None) or '').strip().upper() == 'LOGISTICA':
        subtype = (getattr(row, 'subtype', None) or '').strip()
        origin = (details.get('origin') or '').strip()
        destination = (details.get('destination') or '').strip()
        if subtype:
            subtitle_parts.append(dict(PROMOTION_TRANSPORT_TYPES).get(subtype, subtype))
        if origin or destination:
            subtitle_parts.append(' → '.join([x for x in [origin, destination] if x]))
    elif (getattr(row, 'activity_kind', None) or '').strip().upper() == 'ALOJAMIENTO':
        hotel = (details.get('hotel_name') or '').strip()
        city = (details.get('city') or '').strip()
        if hotel:
            subtitle_parts.append(hotel)
        if city:
            subtitle_parts.append(city)
    performed_song_labels = []
    for sid in _promotion_normalized_artist_ids(getattr(row, 'performed_song_ids', None) or []):
        if sid in song_title_map:
            performed_song_labels.append(song_title_map[sid])
    return {
        'id': str(row.id),
        'label': label,
        'time_label': _promotion_activity_time_label(row),
        'subtitle': ' · '.join([x for x in subtitle_parts if x]),
        'description': (getattr(row, 'task_description', None) or '').strip(),
        'details': details,
        'artist_performed': bool(getattr(row, 'artist_performed', False)),
        'performed_song_labels': performed_song_labels,
        'has_fee': bool(getattr(row, 'has_fee', False)),
        'fee_amount': float(getattr(row, 'fee_amount', 0) or 0),
        'covered_costs': list(getattr(row, 'covered_costs', None) or []),
        'cost_note': (getattr(row, 'cost_note', None) or '').strip(),
        'created_by_nick': (getattr(row, 'created_by_nick', None) or '').strip(),
    }


def _marketing_index_response(default_tab="requested"):
    tab = (request.args.get("tab") or default_tab).strip().lower()
    if tab not in {"requested", "active", "archived"}:
        tab = default_tab
    session_db = db()
    try:
        requested_rows = (
            session_db.query(PromotionRequest)
            .order_by(PromotionRequest.subject_date.asc().nullslast(), PromotionRequest.created_at.desc())
            .all()
        )
        requested_display = [_promotion_display_request(row) for row in requested_rows if (getattr(row, 'status', None) or 'REQUESTED').strip().upper() == 'REQUESTED']
        rejected_display = [_promotion_display_request(row) for row in requested_rows if (getattr(row, 'status', None) or '').strip().upper() in {'REJECTED', 'ARCHIVED'}]

        promotion_rows = (
            session_db.query(Promotion)
            .options(joinedload(Promotion.company))
            .order_by(Promotion.target_date.asc().nullslast(), Promotion.created_at.desc())
            .all()
        )
        active_promotions = [_promotion_display_promotion(row) for row in promotion_rows if (getattr(row, 'status', None) or 'ACTIVE').strip().upper() == 'ACTIVE']
        archived_promotions = [_promotion_display_promotion(row) for row in promotion_rows if (getattr(row, 'status', None) or '').strip().upper() == 'ARCHIVED']

        requested_display.sort(key=lambda x: ((x.get('date') or date.max), (x.get('title') or '').casefold()))
        active_promotions.sort(key=lambda x: ((x.get('date') or date.max), (x.get('title') or '').casefold()))
        archived_promotions.sort(key=lambda x: ((x.get('date') or date.max), (x.get('title') or '').casefold()), reverse=False)
        rejected_display.sort(key=lambda x: ((x.get('date') or date.max), (x.get('title') or '').casefold()))

        return render_template(
            "marketing.html",
            tab=tab,
            requested_items=requested_display,
            active_promotions=active_promotions,
            archived_promotions=archived_promotions,
            rejected_requests=rejected_display,
            promotion_calendar_months=_promotion_calendar_months(requested_display, months_count=3),
            promotion_creator_datasets=_promotion_creator_datasets(session_db),
            request_count=len(requested_display),
            active_count=len(active_promotions),
            archived_count=len(archived_promotions) + len(rejected_display),
            can_edit_promocion=can_edit_marketing(),
            marketing_action_types=MARKETING_ACTION_TYPES,
            marketing_digital_platforms=MARKETING_DIGITAL_PLATFORMS,
        )
    finally:
        session_db.close()


@app.route("/marketing", endpoint="marketing_view")
@admin_required
def marketing_view():
    return _marketing_index_response(default_tab="requested")


@app.route("/promocion", endpoint="promocion_view")
@admin_required
def promocion_view():
    return _marketing_index_response(default_tab="requested")




def _marketing_request_fields_from_form(form, *, source_request=None):
    source_request = source_request or None
    request_kind = (form.get("request_kind") or getattr(source_request, "request_kind", None) or "PLAN").strip().upper()
    if request_kind not in {"PLAN", "ACTION"}:
        request_kind = "PLAN"
    action_types = _marketing_action_types_from_form(form, single=(request_kind == "ACTION"))
    if not action_types and source_request is not None:
        action_types = list(getattr(source_request, "action_types", None) or [])
    if request_kind == "ACTION" and len(action_types) > 1:
        action_types = action_types[:1]
    budget_mode = (form.get("budget_mode") or getattr(source_request, "budget_mode", None) or "REQUEST_BUDGET").strip().upper()
    if budget_mode not in {"REQUEST_BUDGET", "MAX_AMOUNT"}:
        budget_mode = "REQUEST_BUDGET"
    budget_max = _parse_money(form.get("budget_max")) if form.get("budget_max") not in (None, "") else getattr(source_request, "budget_max", None)
    budget_by_action = {}
    for key in action_types:
        raw = form.get(f"budget_{key}")
        if raw not in (None, ""):
            val = _parse_money(raw)
            if val is not None:
                budget_by_action[key] = str(val)
    if not budget_by_action and source_request is not None:
        budget_by_action = dict(getattr(source_request, "budget_by_action", None) or {})
    return {
        "request_kind": request_kind,
        "action_types": action_types,
        "budget_mode": budget_mode,
        "budget_max": budget_max,
        "budget_by_action": budget_by_action,
        "starts_on": parse_optional_date(form.get("starts_on")) or getattr(source_request, "starts_on", None),
        "ends_on": parse_optional_date(form.get("ends_on")) or getattr(source_request, "ends_on", None),
        "deadline_notes": (form.get("deadline_notes") or getattr(source_request, "deadline_notes", None) or "").strip() or None,
    }

@app.post('/marketing/solicitudes/crear')
@app.post('/promocion/solicitudes/crear')
@admin_required
def promotion_request_create():
    if not can_edit_promocion():
        return forbid('No tienes permisos para solicitar Marketing.')
    source_type = (request.form.get('source_type') or '').strip().upper()
    source_id = (request.form.get('source_id') or '').strip()
    next_url = request.form.get('next') or url_for('promocion_view')
    session_db = db()
    try:
        snapshot = _promotion_request_snapshot_from_source(session_db, source_type, source_id)
        if not snapshot:
            flash('No se ha podido identificar el elemento a promocionar.', 'warning')
            return redirect(next_url)
        subject_date = _promotion_target_date_from_source(session_db, source_type, source_id)
        state = _current_user_state()
        marketing_fields = _marketing_request_fields_from_form(request.form)
        row = PromotionRequest(
            source_type=source_type,
            source_id=to_uuid(source_id) if source_id else None,
            artist_ids=_promotion_normalized_artist_ids(snapshot.get('artist_ids') or []),
            snapshot=snapshot,
            subject_date=subject_date,
            objectives_notes=(request.form.get('objectives_notes') or '').strip() or None,
            budget_notes=(request.form.get('budget_notes') or '').strip() or None,
            request_kind=marketing_fields["request_kind"],
            action_types=marketing_fields["action_types"],
            budget_mode=marketing_fields["budget_mode"],
            budget_max=marketing_fields["budget_max"],
            budget_by_action=marketing_fields["budget_by_action"],
            starts_on=marketing_fields["starts_on"],
            ends_on=marketing_fields["ends_on"],
            deadline_notes=marketing_fields["deadline_notes"],
            status='REQUESTED',
            requested_by_user_id=to_uuid(state.get('user_id')) if state.get('user_id') else None,
            requested_by_email=(state.get('email') or '').strip() or None,
            requested_by_nick=(state.get('nick') or '').strip() or None,
        )
        session_db.add(row)
        session_db.commit()
        flash('Solicitud de marketing enviada.', 'success')
    except Exception as exc:
        session_db.rollback()
        flash(f'Error creando la solicitud de marketing: {exc}', 'danger')
    finally:
        session_db.close()
    return redirect(next_url)


@app.post('/marketing/solicitudes/<request_id>/rechazar')
@app.post('/promocion/solicitudes/<request_id>/rechazar')
@admin_required
def promotion_request_reject(request_id):
    if not can_edit_promocion():
        return forbid('No tienes permisos para rechazar solicitudes de Marketing.')
    next_url = request.form.get('next') or url_for('promocion_view', tab='active')
    reason = (request.form.get('reason') or '').strip()
    if not reason:
        flash('Debes indicar el motivo del rechazo.', 'warning')
        return redirect(next_url)
    session_db = db()
    try:
        row = session_db.get(PromotionRequest, to_uuid(request_id))
        if not row:
            flash('Solicitud no encontrada.', 'warning')
            return redirect(next_url)
        state = _current_user_state()
        reviewer_label = (state.get('nick') or state.get('email') or 'Usuario').strip()
        row.status = 'REJECTED'
        row.reviewed_at = _now_madrid()
        row.rejection_reason = reason
        row.reviewed_by_user_id = to_uuid(state.get('user_id')) if state.get('user_id') else None
        row.reviewed_by_nick = reviewer_label
        row.updated_at = _now_madrid()
        recipients = _promotion_request_recipients(row)
        if recipients:
            subject, html_body, text_body = _build_promotion_rejection_email(row, reviewer_label, reason)
            _send_optional_email(recipients, subject, html_body, text_body=text_body)
        session_db.commit()
        flash('Solicitud rechazada y archivada.', 'success')
    except Exception as exc:
        session_db.rollback()
        flash(f'Error rechazando la solicitud: {exc}', 'danger')
    finally:
        session_db.close()
    return redirect(next_url)


@app.post('/marketing/crear')
@app.post('/promocion/crear')
@admin_required
def promotion_create():
    if not can_edit_promocion():
        return forbid('No tienes permisos para crear campañas de Marketing.')
    next_url = request.form.get('next') or url_for('promocion_view', tab='active')
    request_id_raw = (request.form.get('source_request_id') or '').strip()
    subject_type = (request.form.get('subject_type') or '').strip().upper()
    subject_id = (request.form.get('subject_id') or '').strip()
    manual_title = (request.form.get('manual_title') or '').strip()
    artist_ids = _promotion_normalized_artist_ids(request.form.getlist('artist_ids'))
    objectives_notes = (request.form.get('objectives_notes') or '').strip() or None
    budget_notes = (request.form.get('budget_notes') or '').strip() or None
    company_id_raw = (request.form.get('company_id') or '').strip()
    session_db = db()
    try:
        source_request = session_db.get(PromotionRequest, to_uuid(request_id_raw)) if request_id_raw else None
        if source_request:
            if not subject_type:
                subject_type = (getattr(source_request, 'source_type', None) or '').strip().upper()
            if not subject_id and getattr(source_request, 'source_id', None):
                subject_id = str(source_request.source_id)
            if not artist_ids:
                artist_ids = _promotion_normalized_artist_ids(getattr(source_request, 'artist_ids', None) or [])
            if not objectives_notes:
                objectives_notes = (getattr(source_request, 'objectives_notes', None) or '').strip() or None
            if not budget_notes:
                budget_notes = (getattr(source_request, 'budget_notes', None) or '').strip() or None
        if subject_type not in {'ARTIST', 'SONG', 'ALBUM', 'CONCERT', 'GIRA', 'CICLO', 'EVENT'}:
            flash('Debes seleccionar qué se promociona.', 'warning')
            return redirect(next_url)
        snapshot = _promotion_request_snapshot_from_source(session_db, subject_type, subject_id, manual_title=manual_title, manual_artist_ids=artist_ids)
        if not snapshot:
            flash('No se ha podido preparar la promoción.', 'warning')
            return redirect(next_url)
        if not artist_ids:
            artist_ids = _promotion_normalized_artist_ids(snapshot.get('artist_ids') or [])
        target_date = _promotion_target_date_from_source(session_db, subject_type, subject_id)
        if not target_date and source_request and getattr(source_request, 'subject_date', None):
            target_date = source_request.subject_date
        company_id = to_uuid(company_id_raw) if company_id_raw else None
        if not company_id and snapshot.get('company_id'):
            try:
                company_id = to_uuid(snapshot.get('company_id'))
            except Exception:
                company_id = None
        marketing_fields = _marketing_request_fields_from_form(request.form, source_request=source_request)
        state = _current_user_state()
        promotion = Promotion(
            subject_type=subject_type,
            subject_id=to_uuid(subject_id) if subject_id else None,
            artist_ids=artist_ids,
            snapshot=snapshot,
            source_request_id=getattr(source_request, 'id', None),
            company_id=company_id,
            objectives_notes=objectives_notes,
            budget_notes=budget_notes,
            request_kind=marketing_fields["request_kind"],
            action_types=marketing_fields["action_types"],
            budget_mode=marketing_fields["budget_mode"],
            budget_max=marketing_fields["budget_max"],
            budget_by_action=marketing_fields["budget_by_action"],
            starts_on=marketing_fields["starts_on"],
            ends_on=marketing_fields["ends_on"],
            deadline_notes=marketing_fields["deadline_notes"],
            target_date=target_date,
            status='ACTIVE',
            created_by_user_id=to_uuid(state.get('user_id')) if state.get('user_id') else None,
            created_by_nick=(state.get('nick') or state.get('email') or '').strip() or None,
        )
        session_db.add(promotion)
        session_db.flush()
        _ensure_promotion_bag(session_db, promotion)
        seeded_action = _marketing_seed_action(session_db, promotion)
        if source_request:
            source_request.status = 'APPROVED'
            source_request.reviewed_at = _now_madrid()
            source_request.reviewed_by_user_id = to_uuid(state.get('user_id')) if state.get('user_id') else None
            source_request.reviewed_by_nick = (state.get('nick') or state.get('email') or '').strip() or None
            source_request.updated_at = _now_madrid()
        session_db.commit()
        if seeded_action is not None:
            flash('Acción de marketing creada. La tienes en «Acciones» para gestionarla.', 'success')
            return redirect(url_for('promotion_detail_view', promotion_id=promotion.id, tab='acciones'))
        flash('Campaña de marketing creada.', 'success')
        return redirect(url_for('promotion_detail_view', promotion_id=promotion.id))
    except Exception as exc:
        session_db.rollback()
        flash(f'Error creando la campaña de marketing: {exc}', 'danger')
        return redirect(next_url)
    finally:
        session_db.close()


@app.get('/marketing/<promotion_id>')
@app.get('/promocion/<promotion_id>', endpoint='promotion_detail_view')
@admin_required
def promotion_detail_view(promotion_id):
    session_db = db()
    try:
        promotion = (
            session_db.query(Promotion)
            .options(joinedload(Promotion.company), joinedload(Promotion.bag))
            .filter(Promotion.id == to_uuid(promotion_id))
            .first()
        )
        if not promotion:
            flash('Campaña de marketing no encontrada.', 'warning')
            return redirect(url_for('promocion_view'))
        tab = (request.args.get('tab') or 'informacion').strip().lower()
        if tab not in {'informacion', 'acciones', 'gastos', 'hoja_ruta'}:
            tab = 'informacion'
        artist_ids = _promotion_normalized_artist_ids(getattr(promotion, 'artist_ids', None) or [])
        artist_rows = []
        if artist_ids:
            artist_rows = session_db.query(Artist).filter(Artist.id.in_([to_uuid(x) for x in artist_ids])).order_by(Artist.name.asc()).all()
        song_options = []
        if artist_ids:
            song_rows = (
                session_db.query(Song)
                .join(SongArtist, SongArtist.song_id == Song.id)
                .options(selectinload(Song.artists))
                .filter(SongArtist.artist_id.in_([to_uuid(x) for x in artist_ids]))
                .distinct()
                .order_by(Song.release_date.desc().nullslast(), Song.title.asc())
                .all()
            )
            _annotate_song_display_fields(session_db, song_rows, persist=False)
            song_options = song_rows
        song_title_map = {str(s.id): (s.title or 'Canción') for s in (song_options or []) if getattr(s, 'id', None)}
        activity_rows = (
            session_db.query(PromotionActivity)
            .options(joinedload(PromotionActivity.media), joinedload(PromotionActivity.media_contact), joinedload(PromotionActivity.provider), joinedload(PromotionActivity.provider_company), joinedload(PromotionActivity.bag_expense))
            .filter(PromotionActivity.promotion_id == promotion.id)
            .all()
        )
        activity_rows.sort(key=lambda row: ((getattr(row, 'activity_date', None) or date.max), _promotion_activity_time_sort(row)))
        grouped_days = []
        bucket = defaultdict(list)
        for row in activity_rows:
            bucket[getattr(row, 'activity_date', None)].append(_promotion_activity_display(row, song_title_map))
        for day in sorted([x for x in bucket.keys() if x], key=lambda x: x):
            grouped_days.append({'date': day, 'label': day.strftime('%d/%m/%Y'), 'items': bucket[day]})
        invoices = []
        if getattr(promotion, 'bag_id', None):
            invoices = session_db.query(InvoiceRecord).filter(InvoiceRecord.bag_id == promotion.bag_id).order_by(InvoiceRecord.issue_date.desc(), InvoiceRecord.created_at.desc()).all()
        media_outlets = session_db.query(MediaOutlet).order_by(MediaOutlet.media_type.asc(), MediaOutlet.name.asc()).all()
        promoters = session_db.query(Promoter).order_by(Promoter.nick.asc()).all()
        promoter_companies = session_db.query(PromoterCompany).order_by(PromoterCompany.legal_name.asc().nullslast(), PromoterCompany.name.asc().nullslast()).all()
        bags_for_split = session_db.query(WorkflowBag).filter(WorkflowBag.is_archived == False).order_by(WorkflowBag.start_date.asc().nullslast(), WorkflowBag.title.asc()).all()  # noqa: E712
        media_contacts = session_db.query(MediaContact).order_by(MediaContact.created_at.asc()).all()
        media_contacts_payload = []
        for contact in media_contacts:
            media_contacts_payload.append({
                'id': str(contact.id),
                'media_id': str(contact.media_id),
                'label': ' · '.join([x for x in [((contact.first_name or '') + ' ' + (contact.last_name or '')).strip(), (contact.program or '').strip(), (contact.role or '').strip()] if x]),
            })
        action_groups = []
        totals_net = Decimal('0')
        totals_gross = Decimal('0')
        by_action = defaultdict(list)
        for row in activity_rows:
            key = (getattr(row, 'action_type', None) or getattr(row, 'media_type', None) or 'OTRA').strip().upper()
            by_action[key].append(row)
            totals_net += Decimal(str(getattr(row, 'amount_net', 0) or 0))
            totals_gross += Decimal(str(getattr(row, 'amount_gross', 0) or 0))
        for key in [k for k, _label, _icon in MARKETING_ACTION_TYPES] + sorted([k for k in by_action.keys() if k not in MARKETING_ACTION_TYPE_LABELS]):
            rows = by_action.get(key) or []
            if rows:
                action_groups.append({
                    'key': key,
                    'label': _marketing_action_label(key),
                    'icon': _marketing_action_icon(key),
                    'rows': rows,
                })
        roadmap_ctx = _roadmap_context(session_db, 'promotion', promotion)
        session_db.commit()
        return render_template(
            'marketing_detail.html',
            promotion=promotion,
            promotion_display=_promotion_display_promotion(promotion),
            tab=tab,
            activity_days=grouped_days,
            artist_rows=artist_rows,
            song_options=song_options,
            invoices=invoices,
            media_outlets=media_outlets,
            media_contacts_payload=media_contacts_payload,
            transport_types=PROMOTION_TRANSPORT_TYPES,
            covered_cost_options=PROMOTION_COVERED_COST_OPTIONS,
            can_edit_promocion=can_edit_marketing(),
            marketing_action_types=MARKETING_ACTION_TYPES,
            marketing_action_type_labels=MARKETING_ACTION_TYPE_LABELS,
            marketing_exterior_subtypes=MARKETING_EXTERIOR_SUBTYPES,
            marketing_digital_platforms=MARKETING_DIGITAL_PLATFORMS,
            action_groups=action_groups,
            action_totals_net=totals_net,
            action_totals_gross=totals_gross,
            promoters=promoters,
            promoter_companies=promoter_companies,
            bags_for_split=bags_for_split,
            marketing_action_status=_marketing_action_status,
            roadmap_ctx=roadmap_ctx,
        )
    finally:
        session_db.close()


@app.post('/marketing/<promotion_id>/archivar')
@app.post('/promocion/<promotion_id>/archivar')
@admin_required
def promotion_archive_toggle(promotion_id):
    if not can_edit_promocion():
        return forbid('No tienes permisos para archivar promociones.')
    next_url = request.form.get('next') or url_for('promotion_detail_view', promotion_id=promotion_id)
    session_db = db()
    try:
        row = session_db.get(Promotion, to_uuid(promotion_id))
        if not row:
            flash('Campaña de marketing no encontrada.', 'warning')
            return redirect(next_url)
        if (getattr(row, 'status', None) or 'ACTIVE').strip().upper() == 'ARCHIVED':
            row.status = 'ACTIVE'
            row.archived_at = None
            if getattr(row, 'bag', None):
                row.bag.is_archived = False
                row.bag.archived_at = None
            flash('Promoción reactivada.', 'success')
        else:
            row.status = 'ARCHIVED'
            row.archived_at = _now_madrid()
            if getattr(row, 'bag', None):
                row.bag.is_archived = True
                row.bag.archived_at = _now_madrid()
            flash('Promoción archivada.', 'success')
        row.updated_at = _now_madrid()
        session_db.commit()
    except Exception as exc:
        session_db.rollback()
        flash(f'Error actualizando la campaña de marketing: {exc}', 'danger')
    finally:
        session_db.close()
    return redirect(next_url)


@app.post('/promocion/<promotion_id>/actividades/crear')
@app.post('/marketing/<promotion_id>/acciones/crear')
@admin_required
def promotion_activity_create(promotion_id):
    if not can_edit_marketing():
        return forbid('No tienes permisos para editar Marketing.')
    next_url = request.form.get('next') or url_for('promotion_detail_view', promotion_id=promotion_id, tab='acciones')
    action_type = (request.form.get('action_type') or request.form.get('media_type') or 'OTRA').strip().upper()
    if action_type not in MARKETING_ACTION_TYPE_LABELS:
        action_type = 'OTRA'
    session_db = db()
    try:
        promotion = session_db.get(Promotion, to_uuid(promotion_id))
        if not promotion:
            flash('Campaña de marketing no encontrada.', 'warning')
            return redirect(url_for('marketing_view'))
        if not getattr(promotion, 'bag_id', None):
            _ensure_promotion_bag(session_db, promotion)
            session_db.flush()
        state = _current_user_state()
        start_date = parse_optional_date(request.form.get('start_date')) or parse_optional_date(request.form.get('activity_date')) or today_local()
        end_date = parse_optional_date(request.form.get('end_date'))
        execution_mode = (request.form.get('execution_mode') or 'PERIODO').strip().upper()
        if execution_mode not in {'PERIODO', 'OLEADAS'}:
            execution_mode = 'PERIODO'
        waves = []
        wave_starts = request.form.getlist('wave_start')
        wave_ends = request.form.getlist('wave_end')
        wave_notes = request.form.getlist('wave_note')
        for ws, we, wn in zip(wave_starts, wave_ends, wave_notes):
            if not (ws or we or wn):
                continue
            waves.append({'start': ws or None, 'end': we or None, 'note': (wn or '').strip() or None})
        if execution_mode == 'PERIODO' and (start_date or end_date):
            waves = [{'start': start_date.isoformat() if start_date else None, 'end': end_date.isoformat() if end_date else None, 'note': None}]

        media_id = _safe_uuid(request.form.get('media_id')) if (request.form.get('media_id') or '').strip() else None
        if not media_id and (request.form.get('new_media_name') or '').strip():
            new_media_type = (request.form.get('new_media_type') or '').strip() or ({'RADIO': 'Radio', 'TV': 'TV', 'PRENSA': 'Prensa', 'DIGITAL': 'Digital'}.get(action_type) or 'Digital')
            if new_media_type not in MEDIA_TYPES:
                new_media_type = 'Digital'
            media_country_code, media_country_name = _country_payload_from_form(request.form)
            media_logo = request.files.get('new_media_logo')
            media_logo_url = upload_png(media_logo, 'media') if (media_logo and getattr(media_logo, 'filename', '')) else None
            new_media = MediaOutlet(
                media_type=new_media_type,
                name=(request.form.get('new_media_name') or '').strip(),
                logo_url=media_logo_url,
                country_code=media_country_code,
                country_name=media_country_name,
                address=(request.form.get('new_media_address') or '').strip() or None,
            )
            session_db.add(new_media)
            session_db.flush()
            media_id = new_media.id
        provider_id = _safe_uuid(request.form.get('provider_id')) if (request.form.get('provider_id') or '').strip() else None
        provider_company_id = _safe_uuid(request.form.get('provider_company_id')) if (request.form.get('provider_company_id') or '').strip() else None
        provider = session_db.get(Promoter, provider_id) if provider_id else None
        provider_company = session_db.get(PromoterCompany, provider_company_id) if provider_company_id else None
        provider_snapshot = {}
        if provider:
            provider_snapshot.update({'id': str(provider.id), 'nick': provider.nick, 'email': getattr(provider, 'contact_email', None)})
        if provider_company:
            provider_snapshot.update({'company_id': str(provider_company.id), 'company_name': getattr(provider_company, 'legal_name', None) or getattr(provider_company, 'name', None)})

        amount_net = _parse_money(request.form.get('amount_net')) or Decimal('0')
        amount_tax = _parse_money(request.form.get('amount_tax')) or Decimal('0')
        amount_gross = _parse_money(request.form.get('amount_gross')) or Decimal('0')
        if amount_gross == 0 and (amount_net or amount_tax):
            amount_gross = amount_net + amount_tax
        document_type = (request.form.get('document_type') or 'FACTURA').strip().upper()
        if document_type not in {'FACTURA', 'TICKET', 'SIN_DOCUMENTO'}:
            document_type = 'FACTURA'
        media_target = {
            'city': (request.form.get('city') or '').strip() or None,
            'platform': (request.form.get('platform') or '').strip() or None,
            'digital_platform': (request.form.get('digital_platform') or '').strip() or None,
            'other_name': (request.form.get('other_name') or '').strip() or None,
            'media_name_fallback': (request.form.get('media_name_fallback') or '').strip() or None,
        }
        details = {
            'description': (request.form.get('task_description') or request.form.get('description') or '').strip() or None,
            'end_date': end_date.isoformat() if end_date else None,
            'group_with_existing': (request.form.get('group_with_existing') or '').strip() or None,
            'allocation_note': (request.form.get('allocation_note') or '').strip() or None,
        }
        doc = request.files.get('document')
        attachment_url = attachment_name = attachment_mime = None
        consolidation_status = 'PENDIENTE'
        if doc and getattr(doc, 'filename', ''):
            attachment_url, attachment_name, attachment_mime = _bag_document_upload(doc)
            consolidation_status = 'CONSOLIDADO'
        elif document_type == 'SIN_DOCUMENTO':
            consolidation_status = 'SIN_FACTURA_SOLICITADO'

        row = PromotionActivity(
            promotion_id=promotion.id,
            activity_date=start_date,
            activity_kind='MARKETING',
            action_type=action_type,
            subtype=(request.form.get('subtype') or '').strip().upper() or None,
            exterior_subtype=(request.form.get('exterior_subtype') or '').strip().upper() or None,
            media_type=action_type,
            media_id=media_id,
            media_target_json=media_target,
            details_json=details,
            task_description=details.get('description'),
            execution_mode=execution_mode,
            waves_json=waves,
            provider_id=provider_id,
            provider_company_id=provider_company_id,
            provider_snapshot=provider_snapshot,
            budget_group_key=(request.form.get('budget_group_key') or '').strip() or None,
            amount_net=amount_net,
            amount_tax=amount_tax,
            amount_gross=amount_gross,
            allocation_mode=(request.form.get('allocation_mode') or 'SOURCE').strip().upper(),
            allocation_json=[],
            document_type=document_type,
            invoice_number=(request.form.get('invoice_number') or '').strip() or None,
            issue_date=parse_optional_date(request.form.get('issue_date')),
            attachment_url=attachment_url,
            attachment_name=attachment_name,
            attachment_mime=attachment_mime,
            consolidation_status=consolidation_status,
            created_by_user_id=to_uuid(state.get('user_id')) if state.get('user_id') else None,
            created_by_nick=(state.get('nick') or state.get('email') or '').strip() or None,
        )
        session_db.add(row)
        session_db.flush()

        if getattr(promotion, 'bag_id', None) and (amount_gross or amount_net or attachment_url or document_type == 'SIN_DOCUMENTO'):
            expense = BagExpense(
                bag_id=promotion.bag_id,
                category='MARKETING',
                concept=f"{_marketing_action_label(action_type)} · {(row.task_description or dict(getattr(promotion, 'snapshot', {}) or {}).get('title') or 'Marketing')}"[:500],
                provider_id=provider_id,
                provider_company_id=provider_company_id,
                provider_snapshot=provider_snapshot,
                document_type=document_type,
                invoice_number=row.invoice_number,
                issue_date=row.issue_date,
                amount_net=amount_net,
                amount_tax=amount_tax,
                amount_gross=amount_gross,
                consolidation_status=consolidation_status,
                attachment_url=attachment_url,
                attachment_name=attachment_name,
                attachment_mime=attachment_mime,
                created_by_user_id=row.created_by_user_id,
                created_by_nick=row.created_by_nick,
            )
            session_db.add(expense)
            session_db.flush()
            row.bag_expense_id = expense.id
        promotion.updated_at = _now_madrid()
        session_db.commit()
        flash('Acción de marketing añadida.', 'success')
    except Exception as exc:
        session_db.rollback()
        flash(f'Error creando la acción de marketing: {exc}', 'danger')
    finally:
        session_db.close()
    return redirect(next_url)


@app.post('/marketing/<promotion_id>/acciones/<activity_id>/documento')
@admin_required
def marketing_action_document_upload(promotion_id, activity_id):
    next_url = request.form.get('next') or url_for('promotion_detail_view', promotion_id=promotion_id, tab='acciones')
    session_db = db()
    try:
        row = session_db.query(PromotionActivity).filter(PromotionActivity.id == to_uuid(activity_id), PromotionActivity.promotion_id == to_uuid(promotion_id)).first()
        if not row:
            flash('Acción no encontrada.', 'warning')
            return redirect(next_url)
        doc = request.files.get('document')
        if not doc or not getattr(doc, 'filename', ''):
            flash('Selecciona una factura o ticket.', 'warning')
            return redirect(next_url)
        url, name, mime = _bag_document_upload(doc)
        row.attachment_url = url
        row.attachment_name = name
        row.attachment_mime = mime
        row.consolidation_status = 'CONSOLIDADO'
        if row.bag_expense_id:
            exp = session_db.get(BagExpense, row.bag_expense_id)
            if exp:
                exp.attachment_url = url
                exp.attachment_name = name
                exp.attachment_mime = mime
                exp.consolidation_status = 'CONSOLIDADO'
                exp.updated_at = _now_madrid()
        session_db.commit()
        flash('Factura/ticket vinculada a la acción.', 'success')
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo subir el documento: {exc}', 'danger')
    finally:
        session_db.close()
    return redirect(next_url)


