# --------------- Bolsa de una promoción: quién la cierra y a quién le llega -----------------------
def _promo_for_bag(session_db, bag):
    """La promoción de una bolsa (si la bolsa es de una promoción de prensa)."""
    if not bag or (getattr(bag, "linked_type", None) or "").strip().upper() != "PROMOTION":
        return None
    try:
        row = session_db.get(Promotion, bag.linked_id) if getattr(bag, "linked_id", None) else None
    except Exception:
        row = None
    return row if (row is not None and _promo_is_promo(row)) else None


def _promo_bag_closer_ids(promotion) -> set:
    """Quién puede CERRAR la bolsa y mandarla a liquidación.

    Si la promoción lleva producción, la cierra quien la esté produciendo (es quien gestiona los
    gastos). Si no, la cierra promoción o **la persona que viaja con el artista**."""
    ids = set()
    if bool(getattr(promotion, "production_needed", False)):
        if getattr(promotion, "production_owner_user_id", None):
            ids.add(str(promotion.production_owner_user_id))
        return ids
    if (getattr(promotion, "escort_kind", None) or "NONE").strip().upper() == "USER" and getattr(promotion, "escort_user_id", None):
        ids.add(str(promotion.escort_user_id))
    if getattr(promotion, "created_by_user_id", None):
        ids.add(str(promotion.created_by_user_id))
    return ids


def _promo_bag_can_close(session_db, bag) -> bool:
    """¿Puede el usuario actual cerrar ESTA bolsa de promoción? Dirección y administración siempre."""
    promotion = _promo_for_bag(session_db, bag)
    if promotion is None:
        return True                       # no es una bolsa de promoción: como siempre
    if is_master() or has_access_key("administracion", include_descendants=True):
        return True
    uid = str(session.get("user_id") or "")
    if uid and uid in _promo_bag_closer_ids(promotion):
        return True
    # Con producción de por medio manda producción; si no, promoción.
    if bool(getattr(promotion, "production_needed", False)):
        return has_access_key("produccion", edit=True, include_descendants=True)
    return can_edit_promo()


def _bag_has_pending_payments(session_db, bag) -> bool:
    """¿Queda algo por PAGAR en la bolsa? (lo que ya se pagó con tarjeta/Pleo no cuenta)."""
    rows = (session_db.query(BagExpense)
            .filter(BagExpense.bag_id == bag.id, BagExpense.status != "ELIMINADO").all())
    for exp in rows:
        estado = (getattr(exp, "payment_status", None) or "NO_PAGADO").strip().upper()
        if estado not in {"PAGADO", "NO_APLICA"}:
            return True
    return False


def _bag_liquidation_responsibility(session_db, bag) -> str:
    """Qué responsabilidad de administración le toca a esta liquidación.

    Una bolsa de PROMOCIÓN **sin pagos pendientes** es un caso aparte (no hay que pagar a nadie, solo
    revisar y cerrar), así que va a su propia categoría; el resto, a «Liquidar bolsas»."""
    promotion = _promo_for_bag(session_db, bag)
    if promotion is not None and not _bag_has_pending_payments(session_db, bag):
        return "LIQUIDACIONES_PROMO"
    return "LIQUIDACIONES"


# --------------- Lo gastado en una promoción, en la ficha del artista y del lanzamiento -----------
def _promo_spend_rows(session_db, *, artist_id=None, subject_type=None, subject_id=None) -> dict:
    """Gasto de promoción YA LIQUIDADO (bolsa cerrada por administración) que se le imputa a un
    artista o a lo que se promocionaba (single, disco…).

    ⚠️ Un mismo gasto sale en la ficha del ARTISTA y, si la promoción era de una canción o un disco,
    también en la de esa canción o disco: es el mismo dinero visto desde dos sitios, así que cada
    consulta devuelve su propio total y **no se suman entre sí**."""
    query = (session_db.query(Promotion)
             .filter(func.upper(func.coalesce(Promotion.kind, 'MARKETING')) == PROMO_KIND)
             .filter(Promotion.bag_id.isnot(None)))
    if subject_type and subject_id:
        query = query.filter(Promotion.subject_type == (subject_type or "").strip().upper())
        try:
            query = query.filter(Promotion.subject_id == to_uuid(str(subject_id)))
        except Exception:
            return {"rows": [], "total": Decimal("0")}
    promos = query.order_by(Promotion.starts_on.desc().nullslast()).limit(400).all()
    if artist_id:
        key = str(artist_id)
        promos = [p for p in promos if key in set(_promotion_normalized_artist_ids(getattr(p, "artist_ids", None) or []))]
    if not promos:
        return {"rows": [], "total": Decimal("0")}
    bag_ids = [p.bag_id for p in promos if getattr(p, "bag_id", None)]
    bags = {}
    if bag_ids:
        for bag in session_db.query(WorkflowBag).filter(WorkflowBag.id.in_(bag_ids)).all():
            bags[str(bag.id)] = bag
    rows, total = [], Decimal("0")
    for promo in promos:
        bag = bags.get(str(getattr(promo, "bag_id", "")))
        # Solo lo LIQUIDADO: mientras la bolsa esté abierta no es un gasto cerrado.
        if bag is None or (getattr(bag, "liquidation_status", None) or "").strip().upper() != "CERRADA":
            continue
        importe = Decimal("0")
        for exp in (session_db.query(BagExpense)
                    .filter(BagExpense.bag_id == bag.id, BagExpense.status != "ELIMINADO").all()):
            importe += _money_or_zero(getattr(exp, "amount_gross", 0))
        if not importe:
            continue
        total += importe
        snap = dict(getattr(promo, "snapshot", None) or {})
        rows.append({
            "id": str(promo.id),
            "title": _promo_title(promo),
            "subject_label": (snap.get("title") or "").strip(),
            "date_label": (promo.starts_on or promo.target_date).strftime("%d/%m/%Y") if (promo.starts_on or promo.target_date) else "",
            "amount_gross": importe,
            "bag_url": url_for("bag_detail_view", bag_id=bag.id),
            "detail_url": url_for("promo_detail_view", promotion_id=promo.id),
        })
    return {"rows": rows, "total": total}


# --------------- Tareas de la promoción (Inicio) --------------------------------------------------
def _promo_task_is_open(promotion, bag) -> bool:
    """¿Sigue siendo trabajo? Deja de serlo cuando la bolsa se cierra y se manda a liquidación."""
    if (getattr(promotion, "status", None) or "ACTIVE").strip().upper() != "ACTIVE":
        return False
    if (getattr(promotion, "promo_status", None) or "").strip().upper() == "CANCELADO":
        return False
    if bag is not None and (getattr(bag, "status", None) or "").strip().upper() in {"CERRADA", "ARCHIVADA"}:
        return False
    return True


def _promo_last_day(promotion) -> "date | None":
    return (getattr(promotion, "ends_on", None) or getattr(promotion, "starts_on", None)
            or getattr(promotion, "target_date", None))


def _home_promo_tasks(limit: int = 12) -> list:
    """«Tus tareas» de una promoción.

    Le sale a PROMOCIÓN mientras se está gestionando y a **la persona que viaja** con el artista.
    Si la promoción lleva PRODUCCIÓN, a esos dos les desaparece **al día siguiente** de terminar (a
    partir de ahí el trabajo es de producción); la bolsa sigue estando en «Mis gastos» por si hay que
    asignar algo. Sin producción, se queda hasta que se cierra la bolsa y se manda a liquidación."""
    uid = session.get("user_id")
    if not uid:
        return []
    s = db()
    try:
        soy_promocion = can_edit_promo() or has_access_key("promo", include_descendants=True)
        rows = (s.query(Promotion)
                .filter(func.upper(func.coalesce(Promotion.kind, 'MARKETING')) == PROMO_KIND)
                .filter(func.upper(func.coalesce(Promotion.status, 'ACTIVE')) == 'ACTIVE')
                .order_by(Promotion.starts_on.asc().nullslast()).limit(120).all())
        bag_ids = [r.bag_id for r in rows if getattr(r, "bag_id", None)]
        bags = {}
        if bag_ids:
            for bag in s.query(WorkflowBag).filter(WorkflowBag.id.in_(bag_ids)).all():
                bags[str(bag.id)] = bag
        hoy = today_local()
        out = []
        for promo in rows:
            bag = bags.get(str(getattr(promo, "bag_id", "")))
            if not _promo_task_is_open(promo, bag):
                continue
            es_acompanante = ((promo.escort_kind or "NONE").strip().upper() == "USER"
                              and str(promo.escort_user_id or "") == str(uid))
            if not (soy_promocion or es_acompanante):
                continue
            # Con producción de por medio, a promoción y al acompañante se les cae al día siguiente.
            if bool(getattr(promo, "production_needed", False)):
                fin = _promo_last_day(promo)
                if fin and hoy > fin:
                    continue
            artists = _artists_from_ids(s, _promotion_normalized_artist_ids(getattr(promo, "artist_ids", None) or []))
            when = getattr(promo, "starts_on", None) or getattr(promo, "target_date", None)
            out.append({
                "id": str(promo.id),
                "title": _promo_title(promo),
                "artist_name": _artist_label_from_rows(artists),
                "artist_photo": ((getattr(artists[0], "photo_url", None) or "") if artists else ""),
                "date_label": when.strftime("%d/%m/%Y") if when else "Sin fecha",
                "status_label": _promo_status_meta(getattr(promo, "promo_status", None))[0],
                "status_badge": _promo_status_meta(getattr(promo, "promo_status", None))[1],
                "role": "Acompañas al artista" if es_acompanante else "Promoción",
                "needs_bag_close": bool(bag is not None and (bag.status or "ACTIVA").upper() == "ACTIVA"
                                        and str(uid) in _promo_bag_closer_ids(promo)),
                "bag_url": (url_for("bag_detail_view", bag_id=promo.bag_id) if getattr(promo, "bag_id", None) else ""),
                "url": url_for("promo_detail_view", promotion_id=promo.id),
            })
            if len(out) >= limit:
                break
        return out
    except Exception:
        return []
    finally:
        s.close()


# --------------- Avisos de cambio / cancelación a producción --------------------------------------
def _promo_alert_add(session_db, promotion, activity, kind: str, message: str) -> None:
    """Deja el aviso a quien lleva la producción de la promoción (si hay alguien)."""
    target = getattr(promotion, "production_owner_user_id", None)
    if not target or not bool(getattr(promotion, "production_needed", False)):
        return
    state = _current_user_state()
    # No avisarse a uno mismo: quien hace el cambio ya lo sabe.
    if str(target) == str(state.get("user_id") or ""):
        return
    session_db.add(PromotionAlert(
        promotion_id=promotion.id,
        activity_id=getattr(activity, "id", None),
        kind=(kind or "CHANGE").strip().upper(),
        message=message[:1000],
        target_user_id=target,
        created_by_nick=(state.get("nick") or state.get("email") or "").strip() or None,
    ))


def _promo_activity_change_summary(before: dict, activity) -> str:
    """Qué ha cambiado de lo que le importa a producción: día, hora y sitio."""
    after = {
        "date": getattr(activity, "activity_date", None),
        "start": (getattr(activity, "start_time", None) or "").strip(),
        "end": (getattr(activity, "end_time", None) or "").strip(),
        "place": " · ".join([x for x in [(getattr(activity, "location_name", None) or "").strip(),
                                         (getattr(activity, "location_address", None) or "").strip()] if x]),
    }
    bits = []
    if before.get("date") != after["date"]:
        antes = before["date"].strftime("%d/%m/%Y") if before.get("date") else "sin fecha"
        ahora = after["date"].strftime("%d/%m/%Y") if after["date"] else "sin fecha"
        bits.append(f"fecha: {antes} → {ahora}")
    if (before.get("start") or "") != after["start"] or (before.get("end") or "") != after["end"]:
        antes = " - ".join([x for x in [before.get("start"), before.get("end")] if x]) or "sin hora"
        ahora = " - ".join([x for x in [after["start"], after["end"]] if x]) or "sin hora"
        bits.append(f"hora: {antes} → {ahora}")
    if (before.get("place") or "") != after["place"]:
        bits.append(f"sitio: {before.get('place') or 'sin sitio'} → {after['place'] or 'sin sitio'}")
    return "; ".join(bits)


def _home_promo_alerts(limit: int = 10) -> list:
    """Avisos sin leer de promociones que produce esta persona."""
    uid = session.get("user_id")
    if not uid:
        return []
    s = db()
    try:
        rows = (s.query(PromotionAlert)
                .options(joinedload(PromotionAlert.promotion))
                .filter(PromotionAlert.target_user_id == to_uuid(str(uid)))
                .filter(PromotionAlert.read_at.is_(None))
                .order_by(PromotionAlert.created_at.desc()).limit(limit).all())
        out = []
        for row in rows:
            promo = getattr(row, "promotion", None)
            out.append({
                "id": str(row.id),
                "kind": (row.kind or "CHANGE").upper(),
                "message": (row.message or "").strip(),
                "title": _promo_title(promo) if promo is not None else "Promoción",
                "by": (row.created_by_nick or "").strip(),
                "when_label": row.created_at.strftime("%d/%m/%Y %H:%M") if row.created_at else "",
                "url": (url_for("promo_detail_view", promotion_id=row.promotion_id) if row.promotion_id else ""),
            })
        return out
    except Exception:
        return []
    finally:
        s.close()


@app.post("/promocion-prensa/avisos/<alert_id>/leido", endpoint="promo_alert_read")
@admin_required
def promo_alert_read(alert_id):
    """Marcar un aviso como visto (solo su destinatario)."""
    next_url = safe_next_or(request.form.get("next") or url_for("home"))
    session_db = db()
    try:
        row = session_db.get(PromotionAlert, to_uuid(alert_id))
        if row is not None and str(row.target_user_id or "") == str(session.get("user_id") or ""):
            row.read_at = _now_madrid()
            session_db.commit()
    except Exception:
        session_db.rollback()
    finally:
        session_db.close()
    return redirect(next_url)


@app.post("/promocion-prensa/<promotion_id>/cancelar", endpoint="promo_cancel")
@admin_required
def promo_cancel(promotion_id):
    """Cancelar una promoción: se avisa a quien la estuviera produciendo."""
    if not can_edit_promo():
        return forbid("No tienes permisos para cancelar promociones.")
    next_url = safe_next_or(request.form.get("next") or url_for("promo_detail_view", promotion_id=promotion_id))
    reason = (request.form.get("reason") or "").strip()
    session_db = db()
    try:
        promotion = _promo_or_404(session_db, promotion_id)
        if not promotion:
            flash("Promoción no encontrada.", "warning")
            return redirect(url_for("promo_view"))
        promotion.promo_status = "CANCELADO"
        promotion.updated_at = _now_madrid()
        for row in (session_db.query(PromotionActivity)
                    .filter(PromotionActivity.promotion_id == promotion.id)
                    .filter(func.upper(func.coalesce(PromotionActivity.activity_kind, '')) == 'PROMOCION').all()):
            row.status = "CANCELADO"
            row.updated_at = _now_madrid()
            _promo_roadmap_sync_item(session_db, promotion, row)
        _promo_alert_add(session_db, promotion, None, "CANCELLED",
                         f"Se ha CANCELADO «{_promo_title(promotion)}»" + (f": {reason}" if reason else "."))
        session_db.commit()
        flash("Promoción cancelada.", "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo cancelar: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(next_url)


# --------------- Permisos de la sección: se le dan al departamento de Promoción -------------------
def _access_seed_for_department(marker: str, resource_key: str, departamentos: set, *, edit: bool = True) -> None:
    """Le da un recurso a todo el que esté en esos departamentos, UNA sola vez (marca en AppSetting).

    Los recursos nuevos nacen desactivados, así que sin esto habría que ir dándolos de uno en uno.
    Dirección (role 10) no lo necesita: ya lo ve todo."""
    session_db = db()
    try:
        if _get_app_setting(marker):
            return
        if session_db.get(UserAccessResource, resource_key) is None:
            return                                   # aún no se ha sincronizado el catálogo
        fuera = _inactive_user_ids(session_db)
        buscados = {d.strip().lower() for d in departamentos}
        tocados = 0
        for user, profile in (session_db.query(User, UserProfile)
                              .join(UserProfile, UserProfile.user_id == User.id).all()):
            if user.id in fuera:
                continue
            deps = {str(d).strip().lower() for d in (getattr(profile, "departments", None) or [])}
            if not (deps & buscados):
                continue
            grant = (session_db.query(UserAccessGrant)
                     .filter(UserAccessGrant.user_id == user.id,
                             UserAccessGrant.resource_key == resource_key).first())
            if grant is None:
                grant = UserAccessGrant(user_id=user.id, resource_key=resource_key)
                session_db.add(grant)
            if not grant.can_view_basic or (edit and not grant.can_edit):
                grant.can_view_basic = True
                if edit:
                    grant.can_edit = True
                tocados += 1
        session_db.commit()
        _set_app_setting(marker, "1")
        if tocados:
            app.logger.info("Acceso «%s» concedido a %s persona(s).", resource_key, tocados)
    except Exception as exc:
        session_db.rollback()
        app.logger.warning("No se pudo sembrar el acceso a %s: %s", resource_key, exc)
    finally:
        session_db.close()


def _produccion_bags_access_seed() -> None:
    """PRODUCCIÓN necesita entrar en las bolsas: es quien gestiona los gastos de lo que produce y
    quien cierra la bolsa de una promoción con producción."""
    _access_seed_for_department("produccion_bags_access_seed_v1", "databases.bags", {"producción", "produccion"})


def _promo_access_seed() -> None:
    """Da acceso a «Promoción» a quien está en ese departamento, una sola vez.

    La sección es nueva y los recursos nuevos nacen DESACTIVADOS, así que sin esto el equipo de
    promoción no vería lo suyo hasta que dirección fuese tocando permisos uno a uno. Dirección (role
    10) no lo necesita: ya lo ve todo."""
    session_db = db()
    try:
        if _get_app_setting("promo_access_seed_v1"):
            return
        resource = session_db.get(UserAccessResource, "promo")
        if resource is None:
            return                                   # aún no se ha sincronizado el catálogo
        fuera = _inactive_user_ids(session_db)
        tocados = 0
        for user, profile in (session_db.query(User, UserProfile)
                              .join(UserProfile, UserProfile.user_id == User.id).all()):
            if user.id in fuera:
                continue
            deps = [str(d).strip().lower() for d in (getattr(profile, "departments", None) or [])]
            if "promoción" not in deps and "promocion" not in deps:
                continue
            grant = (session_db.query(UserAccessGrant)
                     .filter(UserAccessGrant.user_id == user.id, UserAccessGrant.resource_key == "promo").first())
            if grant is None:
                grant = UserAccessGrant(user_id=user.id, resource_key="promo")
                session_db.add(grant)
            if not (grant.can_view_basic and grant.can_edit):
                grant.can_view_basic = True
                grant.can_edit = True
                tocados += 1
        session_db.commit()
        _set_app_setting("promo_access_seed_v1", "1")
        if tocados:
            app.logger.info("Promoción: acceso concedido a %s persona(s) del departamento.", tocados)
    except Exception as exc:
        session_db.rollback()
        app.logger.warning("No se pudo sembrar el acceso a Promoción: %s", exc)
    finally:
        session_db.close()


# --------------- Peticiones de PROMOCIÓN (las crea cualquiera; las gestiona promoción) ------------
PROMO_REQUEST_KINDS = [
    ("ENTREVISTA", "Entrevista", "fa-microphone-lines"),
    ("JUNT", "Junt de prensa", "fa-users-rectangle"),
    ("PHONER", "Phoner", "fa-phone-volume"),
    ("ACTUACION", "Actuación en un programa", "fa-guitar"),
    ("SESION", "Sesión de fotos o vídeo", "fa-camera"),
    ("OTRA", "Otra cosa", "fa-asterisk"),
]
PROMO_REQUEST_KIND_LABELS = {k: l for k, l, _i in PROMO_REQUEST_KINDS}


@app.post("/promocion-prensa/peticiones/crear", endpoint="promo_peticion_create")
@admin_required
def promo_peticion_create():
    """Petición de promoción: la puede crear CUALQUIERA de la empresa (no hace falta tener la
    sección), como el resto de peticiones. Va a la bandeja de Promoción."""
    next_url = safe_next_or(request.form.get("next") or url_for("promo_view"))
    session_db = db()
    try:
        subject_kind = (request.form.get("subject_kind") or "ARTIST").strip().upper()
        subject_id = (request.form.get("subject_id") or "").strip()
        if not subject_id:
            flash("Dinos de qué artista o evento es la promoción.", "warning")
            return redirect(next_url)
        promo_kind = (request.form.get("promo_kind") or "ENTREVISTA").strip().upper()
        if promo_kind not in PROMO_REQUEST_KIND_LABELS:
            promo_kind = "OTRA"
        media_id = _safe_uuid(request.form.get("media_id")) if (request.form.get("media_id") or "").strip() else None
        media = session_db.get(MediaOutlet, media_id) if media_id else None

        row = BookingRequest(status="NUEVA", source="OTRO")
        artist = None
        event = None
        if subject_kind == "EVENT":
            event = session_db.get(AppEvent, to_uuid(subject_id))
        else:
            artist = session_db.get(Artist, to_uuid(subject_id))
            if artist is not None:
                row.artist_id = artist.id
                row.artist_ids = [str(artist.id)]
        if artist is None and event is None:
            flash("No se ha encontrado el artista o el evento.", "warning")
            return redirect(next_url)

        kind = (request.form.get("date_kind") or "EXACT").strip().upper()
        payload_dates = {}
        if kind == "EXACT":
            row.requested_date = parse_optional_date(request.form.get("requested_date"))
            if not row.requested_date:
                kind = "UNKNOWN"
        if kind == "RANGE":
            desde = (request.form.get("range_start") or "").strip()
            hasta = (request.form.get("range_end") or "").strip()
            payload_dates = {"range_start": desde, "range_end": hasta}
            row.date_text = f"Franja: {desde or '?'} → {hasta or '?'}"
        elif kind == "UNKNOWN":
            row.date_text = "Fecha sin definir"

        sujeto = (getattr(artist, "name", None) or getattr(event, "name", None) or "").strip()
        row.subject = " · ".join([x for x in [PROMO_REQUEST_KIND_LABELS.get(promo_kind, "Promoción"), sujeto,
                                              (getattr(media, "name", None) or "")] if x])[:500]
        row.notes = (request.form.get("description") or "").strip() or None
        row.municipality = (request.form.get("place") or "").strip() or None
        row.contact_name = (request.form.get("contact_name") or "").strip() or None
        row.contact_email = (request.form.get("contact_email") or "").strip() or None
        row.contact_phone = (request.form.get("contact_phone") or "").strip() or None

        state = _current_user_state()
        if not row.contact_name:
            row.contact_name = (state.get("nick") or state.get("email") or "").strip() or None
        row.payload = {
            # ⚠️ El reparto va SIEMPRE en payload['departments'] (lista); lo lee `_booking_in_department`.
            "departments": ["PROMO"],
            "origin": "PROMOCION",
            "promo_request": True,
            "promo_kind": promo_kind,
            "subject_kind": subject_kind,
            "subject_id": subject_id,
            "media_id": str(media.id) if media is not None else "",
            "media_name": (getattr(media, "name", None) or ""),
            "program_name": (request.form.get("program_name") or "").strip(),
            "place": row.municipality or "",
            "date_kind": kind,
            "description": row.notes or "",
            **payload_dates,
        }
        row.created_by_user_id = to_uuid(state.get("user_id")) if state.get("user_id") else None
        row.created_by_nick = (state.get("nick") or state.get("email") or "").strip() or None
        session_db.add(row)
        session_db.commit()
        flash("Petición de promoción enviada.", "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo crear la petición: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(next_url)


@app.post("/marketing/peticiones/crear", endpoint="marketing_peticion_create")
@admin_required
def marketing_peticion_create():
    """PEDIR una acción o una campaña de marketing. La puede pedir cualquiera de la empresa (como el
    resto de peticiones); quien la valora y la monta es Marketing, en su pestaña «Peticiones».

    ⚠️ No es `promotion_request_create`: ese exige poder EDITAR marketing porque se lanza desde la
    ficha del elemento. Este es el botón global de peticiones, que no exige nada."""
    next_url = safe_next_or(request.form.get("next") or url_for("marketing_view", tab="requested"))
    session_db = db()
    try:
        subject_type = (request.form.get("subject_type") or "").strip().upper()
        subject_id = (request.form.get("subject_id") or "").strip()
        artist_ids = _promotion_normalized_artist_ids(request.form.getlist("artist_ids"))
        if subject_type not in {"ARTIST", "SONG", "ALBUM", "CONCERT", "GIRA", "CICLO", "EVENT"}:
            flash("Dinos qué se quiere promocionar.", "warning")
            return redirect(next_url)
        if subject_type == "ARTIST" and not subject_id and len(artist_ids) == 1:
            subject_id = artist_ids[0]
        snapshot = _promotion_request_snapshot_from_source(
            session_db, subject_type, subject_id,
            manual_title=(request.form.get("manual_title") or "").strip(),
            manual_artist_ids=artist_ids)
        if not snapshot:
            flash("No se ha podido identificar lo que se quiere promocionar.", "warning")
            return redirect(next_url)
        if not artist_ids:
            artist_ids = _promotion_normalized_artist_ids(snapshot.get("artist_ids") or [])
        campos = _marketing_request_fields_from_form(request.form)
        state = _current_user_state()
        row = PromotionRequest(
            source_type=subject_type,
            source_id=to_uuid(subject_id) if subject_id else None,
            artist_ids=artist_ids,
            snapshot=snapshot,
            subject_date=_promotion_target_date_from_source(session_db, subject_type, subject_id),
            objectives_notes=(request.form.get("objectives_notes") or "").strip() or None,
            budget_notes=(request.form.get("budget_notes") or "").strip() or None,
            request_kind=campos["request_kind"],
            action_types=campos["action_types"],
            budget_mode=campos["budget_mode"],
            budget_max=campos["budget_max"],
            budget_by_action=campos["budget_by_action"],
            starts_on=campos["starts_on"],
            ends_on=campos["ends_on"],
            deadline_notes=campos["deadline_notes"],
            status="REQUESTED",
            requested_by_user_id=to_uuid(state.get("user_id")) if state.get("user_id") else None,
            requested_by_email=(state.get("email") or "").strip() or None,
            requested_by_nick=(state.get("nick") or "").strip() or None,
        )
        session_db.add(row)
        session_db.commit()
        flash("Petición de marketing enviada.", "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo enviar la petición: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(next_url)


@app.post("/promocion-prensa/peticiones/<request_id>/crear-promocion", endpoint="promo_from_request")
@admin_required
def promo_from_request(request_id):
    """Convierte una petición de promoción en una promoción de verdad, con lo que ya venía puesto.
    Nace en BORRADOR (todavía no ocupa sitio en el calendario) para que promoción la termine."""
    if not can_edit_promo():
        return forbid("No tienes permisos para crear promociones.")
    next_url = safe_next_or(request.form.get("next") or url_for("promo_view"))
    session_db = db()
    try:
        peticion = session_db.get(BookingRequest, to_uuid(request_id))
        if peticion is None:
            flash("Petición no encontrada.", "warning")
            return redirect(next_url)
        payload = dict(getattr(peticion, "payload", None) or {})
        subject_kind = (payload.get("subject_kind") or "ARTIST").strip().upper()
        subject_id = (payload.get("subject_id") or "").strip()
        artist_ids = []
        if subject_kind == "EVENT" and subject_id:
            snapshot_type, snapshot_id = "EVENT", subject_id
        else:
            snapshot_type = "ARTIST"
            snapshot_id = subject_id or (str(peticion.artist_id) if peticion.artist_id else "")
            if snapshot_id:
                artist_ids = [snapshot_id]
        snapshot = _promotion_request_snapshot_from_source(session_db, snapshot_type, snapshot_id,
                                                           manual_artist_ids=artist_ids)
        if not snapshot:
            flash("La petición no dice de qué artista o evento es.", "warning")
            return redirect(next_url)
        if not artist_ids:
            artist_ids = _promotion_normalized_artist_ids(snapshot.get("artist_ids") or [])
        state = _current_user_state()
        cuando = getattr(peticion, "requested_date", None)
        promotion = Promotion(
            kind=PROMO_KIND,
            promo_status="BORRADOR",
            subject_type=snapshot_type,
            subject_id=to_uuid(snapshot_id) if snapshot_id else None,
            artist_ids=artist_ids,
            snapshot=snapshot,
            objectives_notes=(payload.get("description") or getattr(peticion, "notes", None) or "").strip() or None,
            request_kind="ACTION",
            action_types=[],
            budget_mode="REQUEST_BUDGET",
            budget_by_action={},
            starts_on=cuando,
            ends_on=cuando,
            target_date=cuando,
            status="ACTIVE",
            created_by_user_id=to_uuid(state.get("user_id")) if state.get("user_id") else None,
            created_by_nick=(state.get("nick") or state.get("email") or "").strip() or None,
        )
        session_db.add(promotion)
        session_db.flush()
        _ensure_promo_bag(session_db, promotion)
        # La entrevista con lo poco o mucho que traía la petición.
        activity = PromotionActivity(
            promotion_id=promotion.id,
            activity_kind="PROMOCION",
            activity_date=cuando or today_local(),
            status="BORRADOR",
            media_id=(to_uuid(payload.get("media_id")) if (payload.get("media_id") or "").strip() else None),
            task_description=(payload.get("description") or "").strip() or None,
            location_name=(payload.get("place") or "").strip() or None,
            details_json={"program_name": (payload.get("program_name") or "").strip() or None,
                          "from_request_id": str(peticion.id)},
            created_by_user_id=promotion.created_by_user_id,
            created_by_nick=promotion.created_by_nick,
        )
        session_db.add(activity)
        session_db.flush()
        _promo_roadmap_sync_item(session_db, promotion, activity)
        peticion.status = "CONVERTIDA"
        peticion.updated_at = _now_madrid()
        pay = dict(getattr(peticion, "payload", None) or {})
        pay["promotion_id"] = str(promotion.id)
        peticion.payload = pay
        session_db.commit()
        flash("Promoción creada desde la petición.", "success")
        return redirect(url_for("promo_detail_view", promotion_id=promotion.id))
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo crear la promoción: {exc}", "danger")
        return redirect(next_url)
    finally:
        session_db.close()


# ======================= BANCOS, CUENTAS DE LA EMPRESA Y REMESAS DE PAGO =========================
# El fichero que se sube al banco lo arma `sepa_utils` (motor puro). Aquí va lo de la app: de dónde
# salen los pagos, quién es el beneficiario de cada uno y qué pasa cuando la remesa se paga.
SEPA_BANK_FORMAT_CHOICES = [(key, meta["label"]) for key, meta in SEPA_BANK_PROFILES.items()]

PAYMENT_BATCH_STATUS_META = {
    "BORRADOR": ("En preparación", "text-bg-light border text-dark"),
    "EXPORTADA": ("Fichero generado", "text-bg-info text-dark"),
    "PAGADA": ("Pagada", "text-bg-success"),
}
# Etiquetas de lo que le falta a un pago para poder ir en la remesa.
REMESA_MISSING_LABELS = {
    "name": "el nombre del beneficiario",
    "iban": "el IBAN",
    "bic": "el SWIFT/BIC",
    "amount": "el importe",
}


def _payment_batch_status_meta(code):
    return PAYMENT_BATCH_STATUS_META.get((code or "BORRADOR").strip().upper(),
                                         PAYMENT_BATCH_STATUS_META["BORRADOR"])


def _bank_rows(session_db) -> list:
    return session_db.query(Bank).order_by(Bank.name.asc()).all()


def _company_bank_accounts(session_db, company_id=None) -> list:
    query = session_db.query(GroupCompanyBankAccount).options(joinedload(GroupCompanyBankAccount.bank))
    if company_id is not None:
        query = query.filter(GroupCompanyBankAccount.company_id == to_uuid(str(company_id)))
    return query.order_by(GroupCompanyBankAccount.is_default.desc(),
                          GroupCompanyBankAccount.alias.asc().nullslast()).all()


def _iban_masked(value) -> str:
    """Para enseñarlo en pantalla sin cantar la cuenta entera."""
    iban = sepa_normalize_iban(value)
    if len(iban) < 8:
        return iban
    return f"{iban[:4]} •••• {iban[-4:]}"


def _expense_beneficiary(session_db, expense) -> dict:
    """A quién y a qué cuenta se le paga un gasto de bolsa."""
    provider = getattr(expense, "provider", None)
    company = getattr(expense, "provider_company", None)
    snapshot = dict(getattr(expense, "provider_snapshot", None) or {})
    nombre = ""
    if company is not None:
        nombre = (getattr(company, "legal_name", None) or getattr(company, "name", None) or "").strip()
    if not nombre and provider is not None:
        nombre = (getattr(provider, "nick", None) or "").strip() or " ".join(
            filter(None, [getattr(provider, "first_name", None), getattr(provider, "last_name", None)])).strip()
    if not nombre:
        nombre = (snapshot.get("company_name") or snapshot.get("nick") or "").strip()
    iban = ""
    bic = ""
    if company is not None:
        iban = (getattr(company, "bank_account", None) or "").strip()
        bic = (getattr(company, "bank_bic", None) or "").strip()
    if not iban and provider is not None:
        iban = (getattr(provider, "bank_account", None) or "").strip()
        bic = bic or (getattr(provider, "bank_bic", None) or "").strip()
    return {
        "name": nombre,
        "iban": iban,
        "bic": bic,
        "provider_id": (str(provider.id) if provider is not None else ""),
        "provider_company_id": (str(company.id) if company is not None else ""),
    }


def _expense_pending_amount(expense) -> Decimal:
    """Lo que queda por pagar de un gasto (bruto menos lo ya pagado)."""
    bruto = _money_or_zero(getattr(expense, "amount_gross", 0))
    pagado = _money_or_zero(getattr(expense, "paid_amount", 0))
    resto = bruto - pagado
    return resto if resto > 0 else Decimal("0")


def _payment_pending_expenses(session_db, *, company_id=None, limit=800) -> list:
    """Gastos de bolsa pendientes de pago, ya consolidados (lo que de verdad hay que pagar)."""
    query = (session_db.query(BagExpense)
             .options(joinedload(BagExpense.bag), joinedload(BagExpense.provider),
                      joinedload(BagExpense.provider_company))
             .filter(BagExpense.status != "ELIMINADO")
             .filter(BagExpense.covered_by == "BOLSA")
             .filter(BagExpense.consolidation_status.in_(list(BAG_CONSOLIDATED_STATUSES)))
             .filter(BagExpense.payment_status.in_(["NO_PAGADO", "PENDIENTE", "PARCIAL"])))
    rows = query.order_by(BagExpense.created_at.desc()).limit(limit).all()
    if company_id is not None:
        cid = str(company_id)
        rows = [e for e in rows if str(getattr(getattr(e, "bag", None), "company_id", "") or "") == cid]
    return rows


def _payment_expense_row(session_db, expense) -> dict:
    """Una línea de «pendiente de pago» lista para pintar."""
    ben = _expense_beneficiary(session_db, expense)
    importe = _expense_pending_amount(expense)
    faltan = sepa_check_payment({"name": ben["name"], "iban": ben["iban"], "bic": ben["bic"], "amount": importe})
    bag = getattr(expense, "bag", None)
    batch_id = str(getattr(expense, "payment_batch_id", "") or "")
    bruto = _money_or_zero(getattr(expense, "amount_gross", 0))
    ya_pagado = _money_or_zero(getattr(expense, "paid_amount", 0))
    # Antes de abonarle algo a alguien hay que saber si tiene una ORDEN DE EMBARGO vigente o si la
    # casa le ha ADELANTADO dinero (o nos debe algo): las dos cosas se avisan en la propia línea.
    _prov = getattr(expense, "provider", None)
    embargos_prov, deudas_prov = [], []
    if _prov is not None:
        try:
            embargos_prov = [_embargo_order_summary(o) for o in _active_embargo_orders_for_promoter(session_db, _prov)]
        except Exception:
            embargos_prov = []
        deudas_prov = _party_debt_rows(session_db, promoter_id=getattr(_prov, "id", None))
    return {
        "embargos": embargos_prov,
        "debts": deudas_prov,
        "id": str(expense.id),
        "concept": (getattr(expense, "concept", None) or "Sin concepto").strip(),
        # `amount` es SIEMPRE lo que queda por pagar: es lo que se manda al banco y lo que se ve.
        "amount": importe,
        "gross": bruto,
        "paid": ya_pagado,
        "partial": bool(ya_pagado > 0 and importe > 0),
        "beneficiary": ben["name"] or "Sin proveedor",
        "iban_masked": _iban_masked(ben["iban"]) if ben["iban"] else "",
        "missing": faltan,
        "missing_labels": [REMESA_MISSING_LABELS.get(x, x) for x in faltan],
        "provider_id": ben["provider_id"],
        "bag_id": (str(bag.id) if bag is not None else ""),
        "bag_title": (getattr(bag, "title", None) or "").strip(),
        "company_id": str(getattr(bag, "company_id", "") or "") if bag is not None else "",
        "attachment_url": (getattr(expense, "attachment_url", None) or ""),
        "attachment_name": (getattr(expense, "attachment_name", None) or ""),
        "batch_id": batch_id,
        "in_batch": bool(batch_id),
    }


def _payment_pending_context(session_db) -> list:
    """«Pendiente de pago» agrupado por EMPRESA DEL GRUPO, y dentro por liquidación (bolsa).

    Cada bolsa se enseña con su total pendiente y cuántos gastos incluye; al desplegarla salen los
    gastos. Los gastos sueltos (sin bolsa) van aparte. Así no se mezclan empresas, que es de donde
    venían los líos al preparar una remesa."""
    expenses = _payment_pending_expenses(session_db)
    companies = {str(c.id): c for c in session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all()}
    accounts = defaultdict(list)
    for acc in _company_bank_accounts(session_db):
        accounts[str(acc.company_id)].append(acc)
    batches = (session_db.query(PaymentBatch)
               .options(joinedload(PaymentBatch.bank), joinedload(PaymentBatch.account))
               .filter(PaymentBatch.status.in_(["BORRADOR", "EXPORTADA"]))
               .order_by(PaymentBatch.created_at.desc()).limit(200).all())
    batch_counts = defaultdict(lambda: {"n": 0, "total": Decimal("0")})
    for item in (session_db.query(PaymentBatchItem)
                 .filter(PaymentBatchItem.batch_id.in_([b.id for b in batches])).all() if batches else []):
        info = batch_counts[str(item.batch_id)]
        info["n"] += 1
        info["total"] += _money_or_zero(item.amount)

    grupos = {}

    def _grupo(cid):
        clave = str(cid or "")
        if clave not in grupos:
            company = companies.get(clave)
            grupos[clave] = {
                "company_id": clave,
                "company_name": (getattr(company, "name", None) or "Sin empresa"),
                "company_logo": (getattr(company, "logo_url", None) or ""),
                "accounts": accounts.get(clave, []),
                "bags": {},
                "loose": [],
                "royalties": [],
                "batches": [],
                "total": Decimal("0"),
                "count": 0,
            }
        return grupos[clave]

    for expense in expenses:
        row = _payment_expense_row(session_db, expense)
        grupo = _grupo(row["company_id"])
        grupo["total"] += row["amount"]
        grupo["count"] += 1
        if row["bag_id"]:
            bolsa = grupo["bags"].setdefault(row["bag_id"], {
                "bag_id": row["bag_id"], "title": row["bag_title"] or "Liquidación",
                "rows": [], "total": Decimal("0"),
                "url": url_for("bag_detail_view", bag_id=row["bag_id"]),
            })
            bolsa["rows"].append(row)
            bolsa["total"] += row["amount"]
        else:
            grupo["loose"].append(row)

    for batch in batches:
        info = batch_counts.get(str(batch.id)) or {"n": 0, "total": Decimal("0")}
        etiqueta, clase = _payment_batch_status_meta(batch.status)
        _grupo(str(batch.company_id or "")).setdefault("batches", []).append({
            "id": str(batch.id),
            "reference": batch.reference,
            "status": (batch.status or "BORRADOR").upper(),
            "status_label": etiqueta,
            "status_badge": clase,
            "count": info["n"],
            "total": info["total"],
            "bank_name": (getattr(getattr(batch, "bank", None), "name", None) or ""),
            "bank_logo": (getattr(getattr(batch, "bank", None), "logo_url", None) or ""),
            "url": url_for("payment_batch_detail", batch_id=batch.id),
        })

    # LIQUIDACIONES DE ROYALTIES ya facturadas y validadas: son un pago más. Antes desaparecían al
    # validar la factura (no son gastos de bolsa y nadie las listaba aquí).
    for fila in _royalty_payment_pending_rows(session_db):
        grupo = _grupo(fila["company_id"])
        grupo["royalties"].append(fila)
        grupo["total"] += fila["amount"]
        grupo["count"] += 1

    salida = []
    for grupo in grupos.values():
        grupo["bags"] = sorted(grupo["bags"].values(), key=lambda b: (b["title"] or "").casefold())
        salida.append(grupo)
    salida.sort(key=lambda g: (g["company_name"] or "").casefold())
    return salida


ROYALTY_PAYMENT_STATES = [
    ("INVOICED", "Pendiente de pago", "text-bg-warning text-dark"),
    ("PAID", "Pagada", "text-bg-success"),
]
ROYALTY_PAYMENT_LABELS = {k: l for k, l, _c in ROYALTY_PAYMENT_STATES}


def _royalty_payment_state_meta(status):
    st = (status or "").upper()
    for clave, etiqueta, clase in ROYALTY_PAYMENT_STATES:
        if clave == st:
            return etiqueta, clase
    return (st or "—"), "text-bg-light border text-dark"


def _royalty_mark_paid(rec, *, method: str = "", batch=None):
    """Da por PAGADA una liquidación: pasa a contabilidad (pendiente de contabilizar). Al pagarla se
    archiva de las tareas de administración, que es lo que se pidió: lo que está pagado ya no es
    trabajo de pagos."""
    if rec is None:
        return
    rec.status = "PAID"
    rec.paid_at = _now_madrid()
    rec.payment_method = (method or "").strip() or None
    if batch is not None:
        rec.payment_batch_id = batch.id
    rec.updated_at = _now_madrid()
    _royalty_history_add(rec, "PAID", note=(method or ""))


def _royalty_accounting_pending_rows(session_db, limit: int = 300) -> list[dict]:
    """Liquidaciones PAGADAS que contabilidad todavía no ha contabilizado."""
    try:
        recs = (session_db.query(RoyaltyLiquidation)
                .filter(func.upper(func.coalesce(RoyaltyLiquidation.status, "")) == "PAID")
                .filter(RoyaltyLiquidation.accounted_at.is_(None))
                .order_by(RoyaltyLiquidation.paid_at.asc().nullslast()).limit(limit).all())
    except Exception:
        return []
    filas = []
    for rec in recs:
        congelada = _royalty_frozen_beneficiary(rec) or {}
        inv = session_db.get(SupplierInvoice, rec.invoice_id) if getattr(rec, "invoice_id", None) else None
        filas.append({
            "id": str(rec.id),
            "name": (congelada.get("name") or "Beneficiario"),
            "period_label": _royalty_liquidation_period_label_from_dates(rec.period_start, rec.period_end),
            # El mismo número que se pagó: base + IVA.
            "amount": _royalty_invoice_totals(congelada)["gross"],
            "net": _money_or_zero(congelada.get("total_amount")),
            "paid_label": (rec.paid_at.strftime("%d/%m/%Y") if rec.paid_at else ""),
            "method": (getattr(rec, "payment_method", None) or ""),
            "invoice_url": (getattr(inv, "file_url", None) or ""),
            "invoice_number": (getattr(inv, "invoice_number", None) or ""),
            "pdf_url": (rec.last_sent_pdf_url or rec.snapshot_pdf_url or ""),
        })
    return filas


def _royalty_payment_pending_rows(session_db) -> list[dict]:
    """Liquidaciones de royalties con la factura VALIDADA y sin pagar: pendientes de pago.

    Se pagan a nombre de quien facturó (el `promoter_id` de la factura, que es de donde salen el IBAN
    y el BIC) y se agrupan bajo la empresa del grupo que factura los royalties (PIES). Llevan sus
    avisos: orden de embargo vigente y adelantos/deudas con la casa."""
    # ⚠️ Pendiente de pago = la factura está **VALIDADA**. `status='INVOICED'` solo dice que la
    # factura ha llegado (se pone al subirla por el enlace), así que filtrando por el estado a secas
    # se colaban liquidaciones sin factura o con la factura aún por validar: salían como filas vacías
    # («Beneficiario», sin datos) y sin importe. Se cruza con la factura.
    try:
        recs = (session_db.query(RoyaltyLiquidation)
                .join(SupplierInvoice, SupplierInvoice.id == RoyaltyLiquidation.invoice_id)
                .filter(func.upper(func.coalesce(RoyaltyLiquidation.status, "")) == "INVOICED")
                .filter(func.upper(func.coalesce(SupplierInvoice.status, "")) == "VALIDADA")
                .filter(RoyaltyLiquidation.paid_at.is_(None))
                .order_by(RoyaltyLiquidation.invoice_uploaded_at.asc().nullslast()).limit(400).all())
    except Exception:
        return []
    if not recs:
        return []
    try:
        company = _pies_group_company(session_db)
    except Exception:
        company = None
    company_id = str(getattr(company, "id", "") or "")
    filas = []
    for rec in recs:
        congelada = _royalty_frozen_beneficiary(rec) or {}
        inv = session_db.get(SupplierInvoice, rec.invoice_id) if getattr(rec, "invoice_id", None) else None
        promoter = session_db.get(Promoter, inv.promoter_id) if (inv is not None and inv.promoter_id) else None
        nombre = (_promoter_display_name(promoter)
                  or (getattr(promoter, "nick", None) or "").strip()
                  or (congelada.get("name") or "").strip())
        # LO QUE SE PAGA es lo que se le pidió facturar: la base de la liquidación MÁS el IVA. Así la
        # liquidación, la factura y la remesa dicen el mismo número.
        base = congelada
        if not base:
            try:
                base, _c = _royalty_effective_beneficiary(
                    session_db, rec, rec.beneficiary_kind, str(rec.beneficiary_id),
                    rec.period_start.year, 1 if rec.period_start.month <= 6 else 2)
            except Exception:
                base = None
            if base and not nombre:
                nombre = (base.get("name") or "").strip()
        totales = _royalty_invoice_totals(base or {})
        importe = totales["gross"]
        # El IMPORTE no puede faltar en algo ya validado: en último caso, el de la propia factura.
        if importe <= 0 and inv is not None:
            importe = _money_or_zero(getattr(inv, "amount_gross", None))
        if not nombre:
            nombre = "Sin beneficiario"
        iban = (getattr(promoter, "bank_account", None) or "").strip()
        bic = (getattr(promoter, "bank_bic", None) or "").strip()
        faltan = sepa_check_payment({"name": nombre, "iban": iban, "bic": bic, "amount": importe})
        embargos = []
        if promoter is not None and "_active_embargo_orders_for_promoter" in globals():
            try:
                embargos = [_embargo_order_summary(o) for o in _active_embargo_orders_for_promoter(session_db, promoter)]
            except Exception:
                embargos = []
        deudas = _party_debt_rows(
            session_db,
            promoter_id=(getattr(promoter, "id", None)),
            artist_id=(rec.beneficiary_id if (rec.beneficiary_kind or "").upper() == "ARTIST" else None),
        )
        etiqueta, clase = _royalty_payment_state_meta(rec.status)
        filas.append({
            "id": str(rec.id),
            "kind": "royalty",
            "company_id": company_id,
            "name": nombre,
            "concept": "Royalties · " + _royalty_liquidation_period_label_from_dates(rec.period_start, rec.period_end),
            "period_label": _royalty_liquidation_period_label_from_dates(rec.period_start, rec.period_end),
            "amount": importe,
            "net": totales["net"],
            "vat": totales["vat"],
            "vat_pct": totales["vat_pct"],
            "iban": iban,
            "iban_masked": (_iban_masked(iban) if iban else ""),
            "missing": faltan,
            # En español: la lista cruda de `sepa_check_payment` viene en inglés («amount», «iban»…)
            # y se estaba pintando tal cual.
            "missing_labels": [REMESA_MISSING_LABELS.get(x, x) for x in faltan],
            "status": (rec.status or "").upper(),
            "status_label": etiqueta,
            "status_badge": clase,
            "batch_id": str(getattr(rec, "payment_batch_id", "") or ""),
            "invoice_url": (getattr(inv, "file_url", None) or ""),
            "pdf_url": (rec.last_sent_pdf_url or rec.snapshot_pdf_url or ""),
            "review_url": (url_for("administration_royalty_invoice_review", invoice_id=inv.id) if inv is not None else ""),
            "embargos": embargos,
            "debts": deudas,
            "photo_url": (congelada.get("photo_url") or ""),
        })
    return filas


def _payment_batch_next_reference(session_db) -> str:
    """REM-aaaa-nnnn, correlativo por año."""
    year = today_local().year
    prefijo = f"REM-{year}-"
    ultimo = (session_db.query(PaymentBatch)
              .filter(PaymentBatch.reference.like(f"{prefijo}%"))
              .order_by(PaymentBatch.reference.desc()).first())
    siguiente = 1
    if ultimo is not None:
        try:
            siguiente = int((ultimo.reference or "").rsplit("-", 1)[-1]) + 1
        except Exception:
            siguiente = 1
    return f"{prefijo}{siguiente:04d}"


def _payment_batch_context(session_db, batch) -> dict:
    """Todo lo que enseña la ficha de una remesa: sus pagos, lo que falta y los totales."""
    items = (session_db.query(PaymentBatchItem)
             .options(joinedload(PaymentBatchItem.expense), joinedload(PaymentBatchItem.provider))
             .filter(PaymentBatchItem.batch_id == batch.id)
             .order_by(PaymentBatchItem.created_at.asc()).all())
    bank_slug = (getattr(getattr(batch, "bank", None), "file_format", None) or "SEPA_PAIN001")
    filas, total, incompletos = [], Decimal("0"), 0
    for item in items:
        importe = _money_or_zero(item.amount)
        faltan = sepa_check_payment({"name": item.beneficiary_name, "iban": item.beneficiary_iban,
                                     "bic": item.beneficiary_bic, "amount": importe},
                                    require_bic=bool(sepa_bank_profile(bank_slug).get("require_bic")))
        if faltan:
            incompletos += 1
        else:
            total += importe
        filas.append({
            "id": str(item.id),
            "expense_id": str(item.expense_id or ""),
            "provider_id": str(item.provider_id or ""),
            "name": (item.beneficiary_name or ""),
            "iban": (item.beneficiary_iban or ""),
            "iban_masked": _iban_masked(item.beneficiary_iban) if item.beneficiary_iban else "",
            "bic": (item.beneficiary_bic or ""),
            "concept": (item.concept or ""),
            "amount": importe,
            "missing": faltan,
            "missing_labels": [REMESA_MISSING_LABELS.get(x, x) for x in faltan],
        })
    etiqueta, clase = _payment_batch_status_meta(batch.status)
    return {
        "rows": filas,
        "total": total,
        "count_ready": len(filas) - incompletos,
        "count_incomplete": incompletos,
        "status_label": etiqueta,
        "status_badge": clase,
        "bank_slug": bank_slug,
        "bank_label": sepa_bank_profile(bank_slug).get("label"),
    }


def _payment_batch_refresh_total(session_db, batch) -> None:
    total = Decimal("0")
    for item in session_db.query(PaymentBatchItem).filter(PaymentBatchItem.batch_id == batch.id).all():
        total += _money_or_zero(item.amount)
    batch.total_amount = total
    batch.updated_at = _now_madrid()


def _payment_batch_add_expenses(session_db, batch, expense_ids) -> int:
    """Mete gastos en la remesa. Solo los de SU empresa: mezclar empresas en una remesa es pagar
    desde una cuenta lo que le toca a otra."""
    añadidos = 0
    ya = {str(i.expense_id) for i in session_db.query(PaymentBatchItem)
          .filter(PaymentBatchItem.batch_id == batch.id).all() if i.expense_id}
    for raw in expense_ids or []:
        try:
            eid = to_uuid(str(raw).strip())
        except Exception:
            continue
        if not eid or str(eid) in ya:
            continue
        expense = (session_db.query(BagExpense)
                   .options(joinedload(BagExpense.bag), joinedload(BagExpense.provider),
                            joinedload(BagExpense.provider_company))
                   .filter(BagExpense.id == eid).first())
        if expense is None:
            continue
        if (getattr(expense, "payment_status", None) or "").upper() == "PAGADO":
            continue
        bag_company = str(getattr(getattr(expense, "bag", None), "company_id", "") or "")
        if str(batch.company_id or "") and bag_company and bag_company != str(batch.company_id):
            continue
        ben = _expense_beneficiary(session_db, expense)
        session_db.add(PaymentBatchItem(
            batch_id=batch.id,
            expense_id=expense.id,
            provider_id=(to_uuid(ben["provider_id"]) if ben["provider_id"] else None),
            beneficiary_name=ben["name"] or None,
            beneficiary_iban=sepa_normalize_iban(ben["iban"]) or None,
            beneficiary_bic=(ben["bic"] or None),
            # El concepto del pago = el de la FACTURA que se paga (ver `_payment_concept_for_expense`).
            concept=_payment_concept_for_expense(session_db, expense),
            amount=_expense_pending_amount(expense),
        ))
        expense.payment_batch_id = batch.id
        ya.add(str(expense.id))
        añadidos += 1
    session_db.flush()
    _payment_batch_refresh_total(session_db, batch)
    return añadidos


def _payment_file_part(value: str) -> str:
    """Un trozo del nombre del fichero: sin acentos, sin separadores raros y sin espacios."""
    base = unicodedata.normalize("NFD", str(value or "")).encode("ascii", "ignore").decode("ascii")
    base = re.sub(r"[^A-Za-z0-9]+", " ", base).strip()
    return re.sub(r"\s+", "", base.title())[:40]


def _payment_batch_file_name(session_db, batch) -> str:
    """Nombre del fichero de pagos, para reconocerlo de un vistazo en la carpeta y en el banco:

      · de UNA bolsa → `Remesa_<Artista>_<Festival o municipio>_<Fecha del evento>`
      · varios sueltos → `Remesa_Varios_<Fecha en que se genera>`

    Del evento se coge el nombre del FESTIVAL y, si no lo tiene, el MUNICIPIO."""
    bolsas, sueltos = set(), 0
    try:
        for item in (session_db.query(PaymentBatchItem)
                     .filter(PaymentBatchItem.batch_id == batch.id).all()):
            expense = session_db.get(BagExpense, item.expense_id) if item.expense_id else None
            bag_id = getattr(expense, "bag_id", None) if expense is not None else None
            if bag_id:
                bolsas.add(str(bag_id))
            else:
                sueltos += 1
    except Exception:
        bolsas, sueltos = set(), 1
    hoy = (batch.execution_date or today_local()).strftime("%d-%m-%Y")
    if len(bolsas) != 1 or sueltos:
        return "Remesa_Varios_%s" % hoy
    bag = session_db.get(WorkflowBag, to_uuid(next(iter(bolsas))))
    if bag is None:
        return "Remesa_Varios_%s" % hoy
    artista = _payment_file_part(getattr(getattr(bag, "artist", None), "name", "") or "")
    concert = None
    if (bag.linked_type or "").upper() == "CONCERT" and bag.linked_id:
        concert = session_db.get(Concert, bag.linked_id)
    festival = _payment_file_part(getattr(concert, "festival_name", None) or "")
    municipio = _payment_file_part(
        (getattr(getattr(concert, "venue", None), "municipality", None) or "")
        or (getattr(concert, "manual_municipality", None) or ""))
    fecha = (getattr(concert, "date", None) or bag.start_date or batch.execution_date or today_local())
    trozos = ["Remesa"]
    if artista:
        trozos.append(artista)
    trozos.append(festival or municipio or _payment_file_part(bag.title or "") or "Bolsa")
    trozos.append(fecha.strftime("%d-%m-%Y"))
    return "_".join(trozos)


def _payment_concept_for_expense(session_db, expense) -> str:
    """CONCEPTO del pago: se intenta que sea el de la FACTURA que se va a pagar.

    Es lo que ve el proveedor en su extracto, así que cuanto más se parezca a su factura, mejor lo
    reconoce. Orden: el concepto de la factura subida → el nº de factura → el concepto del gasto."""
    partes = []
    try:
        filas = (session_db.query(BagExpenseInvoice)
                 .filter(BagExpenseInvoice.bag_expense_id == expense.id)
                 .order_by(BagExpenseInvoice.created_at.desc()).all())
    except Exception:
        filas = []
    numero = ""
    for fila in filas:
        numero = numero or (fila.invoice_number or "").strip()
        inv = (session_db.get(SupplierInvoice, fila.supplier_invoice_id)
               if getattr(fila, "supplier_invoice_id", None) else None)
        if inv is not None:
            numero = numero or (inv.invoice_number or "").strip()
            texto = (inv.concept_text or "").strip()
            if texto:
                partes.append(texto)
                break
    numero = numero or (getattr(expense, "invoice_number", None) or "").strip()
    if not partes:
        # Sin factura con concepto, el del propio gasto (es lo que se le pidió facturar).
        propio = (getattr(expense, "concept", None) or "").strip()
        if propio:
            partes.append(propio)
    if numero:
        partes.append("Fra. " + numero)
    return " · ".join([x for x in partes if x])[:140] or "Pago"


def _payment_batch_add_royalties(session_db, batch, liquidation_ids) -> int:
    """Mete LIQUIDACIONES DE ROYALTIES validadas en la remesa. El beneficiario es quien facturó (de
    ahí salen el IBAN y el BIC) y se congela en el item, como el resto de los pagos."""
    añadidos = 0
    ya = {str(i.royalty_liquidation_id) for i in session_db.query(PaymentBatchItem)
          .filter(PaymentBatchItem.batch_id == batch.id).all() if getattr(i, "royalty_liquidation_id", None)}
    for raw in liquidation_ids or []:
        try:
            rid = to_uuid(str(raw).strip())
        except Exception:
            continue
        if not rid or str(rid) in ya:
            continue
        rec = session_db.get(RoyaltyLiquidation, rid)
        if rec is None or (rec.status or "").upper() != "INVOICED" or rec.paid_at is not None:
            continue
        congelada = _royalty_frozen_beneficiary(rec) or {}
        inv = session_db.get(SupplierInvoice, rec.invoice_id) if getattr(rec, "invoice_id", None) else None
        promoter = session_db.get(Promoter, inv.promoter_id) if (inv is not None and inv.promoter_id) else None
        # Lo que va al banco es lo que se le pidió facturar: base de la liquidación + IVA.
        importe = _royalty_invoice_totals(congelada)["gross"]
        if importe <= 0 and inv is not None:
            importe = _money_or_zero(getattr(inv, "amount_gross", None))
        session_db.add(PaymentBatchItem(
            batch_id=batch.id,
            royalty_liquidation_id=rec.id,
            provider_id=(promoter.id if promoter is not None else None),
            beneficiary_name=(_promoter_display_name(promoter) or (congelada.get("name") or "") or None),
            beneficiary_iban=(sepa_normalize_iban(getattr(promoter, "bank_account", None) or "") or None),
            beneficiary_bic=((getattr(promoter, "bank_bic", None) or "").strip() or None),
            concept=("Royalties " + _royalty_liquidation_period_label_from_dates(rec.period_start, rec.period_end))[:140],
            amount=importe,
        ))
        rec.payment_batch_id = batch.id
        rec.updated_at = _now_madrid()
        ya.add(str(rec.id))
        añadidos += 1
    session_db.flush()
    _payment_batch_refresh_total(session_db, batch)
    return añadidos


def _payment_batch_expense_ids_from_form(session_db, form) -> list:
    """Ids de gasto que llegan del formulario: sueltos y/o todos los de las bolsas marcadas."""
    ids = [x for x in (form.getlist("expense_ids") or []) if (x or "").strip()]
    for bag_id in (form.getlist("bag_ids") or []):
        if not (bag_id or "").strip():
            continue
        try:
            bid = to_uuid(bag_id.strip())
        except Exception:
            continue
        for expense in _payment_pending_expenses(session_db):
            if str(getattr(expense, "bag_id", "")) == str(bid):
                ids.append(str(expense.id))
    # Sin duplicados y conservando el orden en que se eligieron.
    vistos, salida = set(), []
    for x in ids:
        if x in vistos:
            continue
        vistos.add(x)
        salida.append(x)
    return salida


def _bag_close_if_fully_paid(session_db, bag) -> bool:
    """Cuando en una bolsa ya no queda nada por pagar, se cierra y se archiva: a partir de ahí es
    cosa de contabilidad. Devuelve True si la ha archivado."""
    if bag is None:
        return False
    if _bag_has_pending_payments(session_db, bag):
        return False
    bag.liquidation_status = "CERRADA"
    bag.liquidation_paid_at = _now_madrid()
    bag.status = "ARCHIVADA"
    bag.is_archived = True
    bag.archived_at = _now_madrid()
    bag.updated_at = _now_madrid()
    return True


