def _person_loyalty_icon_guess(name):
    """Icono del tipo de compañía a partir de palabras clave del nombre (marca desconocida)."""
    k = _norm_text_key(name or "")
    if any(w in k for w in ("air", "fly", "aero", "avia", "vuelo", "wizz", "easyjet", "lufthansa")):
        return "fa-plane"
    if any(w in k for w in ("renfe", "tren", "train", "rail", "ave", "ouigo", "iryo")):
        return "fa-train"
    if any(w in k for w in ("hotel", "resort", "hostel", "hoteles", "bonvoy", "hilton", "melia", "marriott", "nh")):
        return "fa-bed"
    if any(w in k for w in ("gas", "oil", "petrol", "combust", "carburante", "repsol", "cepsa", "shell", "bp", "galp")):
        return "fa-gas-pump"
    if any(w in k for w in ("corte", "carrefour", "super", "mercado", "tienda", "shop", "store", "compras", "market")):
        return "fa-bag-shopping"
    return "fa-tag"


def _person_loyalty_brand_for(company):
    key = _norm_text_key(company or "").replace(" ", "")
    for b in PERSON_LOYALTY_BRANDS:
        if b["key"] in key or key in b["key"]:
            return b
    return {"key": "", "label": (company or "").strip(), "color": "#334155", "color2": "#64748b",
            "fg": "#ffffff", "icon": _person_loyalty_icon_guess(company)}


def _person_doc_owner(session_db, owner_type, owner_id):
    """(owner_obj, ot) para USER (User) o PROMOTER (Promoter); (None, None) si no válido."""
    ot = (owner_type or "").strip().upper()
    if ot == "USER":
        return session_db.get(User, to_uuid(owner_id)), ot
    if ot == "PROMOTER":
        return session_db.get(Promoter, to_uuid(owner_id)), ot
    return None, None


def _person_doc_store_image(fs):
    """Sube una imagen de documento a Storage (carpeta 'documents'); convierte HEIC/… a JPEG para
    que se vea en el navegador. Devuelve URL absoluta o None."""
    if not fs or not getattr(fs, "filename", ""):
        return None
    fname = fs.filename or "doc"
    ext = os.path.splitext(fname.lower())[1]
    try:
        if ext in {".jpg", ".jpeg", ".png", ".webp", ".gif"}:
            return _absolute_media_url(upload_image(fs, "documents"))
        if ext in PERSON_DOC_IMAGE_EXTS and PILLOW_AVAILABLE:
            try:
                raw = fs.read()
                img = ImageOps.exif_transpose(PILImage.open(BytesIO(raw)))
                if img.mode not in ("RGB", "L"):
                    img = img.convert("RGB")
                out = BytesIO()
                img.save(out, format="JPEG", quality=90)
                return _absolute_media_url(_upload_bytes(out.getvalue(), "documents/%s.jpg" % uuid.uuid4().hex, "image/jpeg"))
            except Exception:
                try:
                    fs.stream.seek(0)
                except Exception:
                    pass
        return _absolute_media_url(upload_file(fs, "documents", allowed_extensions=PERSON_DOC_IMAGE_EXTS))
    except ValueError:
        return None


def _person_document_payload(doc):
    brand = _person_loyalty_brand_for(doc.company) if doc.kind == "LOYALTY" else None
    return {
        "id": str(doc.id),
        "kind": doc.kind,
        "label": doc.label or "",
        "company": doc.company or "",
        "doc_number": doc.doc_number or "",
        "full_name": doc.full_name or "",
        "birth_date": doc.birth_date.isoformat() if doc.birth_date else "",
        "expiry_date": doc.expiry_date.isoformat() if doc.expiry_date else "",
        "issue_date": doc.issue_date.isoformat() if doc.issue_date else "",
        "address": doc.address or "",
        "front_url": doc.front_url or "",
        "back_url": doc.back_url or "",
        "brand": brand,
    }


def _person_documents_for(session_db, owner_type, owner_id):
    rows = (
        session_db.query(PersonDocument)
        .filter(PersonDocument.owner_type == owner_type, PersonDocument.owner_id == owner_id)
        .order_by(PersonDocument.sort_order.asc(), PersonDocument.created_at.asc())
        .all()
    )
    return [_person_document_payload(r) for r in rows]


# Datos OFICIALES de una persona: los que salen del DNI/pasaporte/carnet. ⚠️ El **nick** NO es un
# dato oficial: es como llamamos a esa persona (o a la empresa), así que NUNCA se toca al escanear un
# documento. Lo oficial es nombre + apellidos + nº de DNI/NIF + nacimiento + domicilio.
PERSON_DOC_OFFICIAL_LABELS = {
    "first_name": "Nombre",
    "last_name": "Apellidos",
    "id_number": "DNI / NIF",
    "birth_date": "Fecha de nacimiento",
    "address": "Domicilio",
}


def _person_doc_official_target(session_db, ot, owner):
    """(fila donde viven los datos oficiales, {campo lógico: atributo}). El nick queda fuera."""
    if ot == "USER":
        profile = _ensure_user_profile(session_db, owner, legacy_full_seed=False)
        return profile, {"first_name": "first_name", "last_name": "last_name", "id_number": "dni",
                         "birth_date": "birth_date", "address": "address"}
    if ot == "PROMOTER":
        # El tercero no guarda fecha de nacimiento (se queda en el documento).
        return owner, {"first_name": "first_name", "last_name": "last_name", "id_number": "tax_id",
                       "address": "address"}
    return None, {}


def _person_doc_official_values(doc, first_override=None, last_override=None) -> dict:
    """Datos oficiales que trae el documento. El nº solo vale como DNI/NIF cuando es un DNI (el de
    pasaporte o carnet no lo es). `first_override`/`last_override`: frontera nombre/apellidos que el
    MRZ ya conoce (la manda el cliente); tiene prioridad sobre partir `full_name` por heurística (que
    falla con nombres extranjeros de varios nombres de pila y un solo apellido)."""
    fo = (first_override or "").strip()
    lo = (last_override or "").strip()
    if fo or lo:
        first, last = fo.title(), lo.title()
    else:
        first, last = _split_full_name(doc.full_name) if doc.full_name else ("", "")
    return {
        "first_name": first or "",
        "last_name": last or "",
        "id_number": (doc.doc_number or "").strip() if doc.kind == "DNI" else "",
        "birth_date": doc.birth_date,
        "address": (getattr(doc, "address", None) or "").strip(),
    }


def _person_doc_same_value(a, b) -> bool:
    """¿Es el mismo dato? En texto, sin distinguir mayúsculas ni acentos (y en el DNI, sin puntos)."""
    if isinstance(a, date) or isinstance(b, date):
        return a == b
    sa, sb = (a or ""), (b or "")
    if not sa and not sb:
        return True
    return _prl_norm_dni(sa) == _prl_norm_dni(sb) or _norm_text_key(sa) == _norm_text_key(sb)


def _person_doc_apply_to_profile(session_db, ot, owner, doc, first_override=None, last_override=None,
                                 choices=None):
    """DNI/carnet/pasaporte → datos OFICIALES de la ficha.

    - Campo VACÍO en la ficha: se rellena con lo del documento sin preguntar.
    - Campo que NO COINCIDE: se devuelve como **conflicto** para que la persona decida cuál se queda
      (el documento manda por defecto, pero se puede conservar el de la ficha). Con `choices`
      (`{campo: 'doc'|'ficha'}`) se aplica lo decidido.
    - El **nick** no se toca nunca: no es un dato oficial.

    Devuelve `(aplicados, conflictos)`: listas de dicts con campo, etiqueta y valores.
    """
    if doc.kind not in {"DNI", "LICENSE", "PASSPORT"}:
        return [], []
    fila, campos = _person_doc_official_target(session_db, ot, owner)
    if fila is None:
        return [], []
    detectado = _person_doc_official_values(doc, first_override, last_override)
    choices = choices or {}
    aplicados, conflictos = [], []
    for campo, attr in campos.items():
        nuevo = detectado.get(campo)
        if not nuevo:
            continue                                  # el documento no trae ese dato
        actual = getattr(fila, attr, None)
        vacio = (actual is None) or (isinstance(actual, str) and not actual.strip())
        info = {
            "field": campo,
            "label": PERSON_DOC_OFFICIAL_LABELS.get(campo, campo),
            "current": (actual.isoformat() if isinstance(actual, date) else (actual or "")),
            "detected": (nuevo.isoformat() if isinstance(nuevo, date) else nuevo),
        }
        if vacio:
            setattr(fila, attr, nuevo)
            aplicados.append(info)
            continue
        if _person_doc_same_value(actual, nuevo):
            continue                                  # ya coincide: nada que decidir
        elegido = (choices.get(campo) or "").strip().lower()
        if elegido == "doc":
            setattr(fila, attr, nuevo)
            aplicados.append(info)
        elif elegido == "ficha":
            pass                                      # se queda lo que había
        else:
            conflictos.append(info)                    # que lo decida quien está subiendo el documento
    return aplicados, conflictos


def _split_full_name(full):
    """«APELLIDO1 APELLIDO2, NOMBRE» o «NOMBRE APELLIDO1 APELLIDO2» → (nombre, apellidos)."""
    s = " ".join((full or "").split())
    if not s:
        return "", ""
    if "," in s:
        last, first = s.split(",", 1)
        return first.strip().title(), last.strip().title()
    parts = s.split(" ")
    if len(parts) >= 3:
        return " ".join(parts[:-2]).title(), " ".join(parts[-2:]).title()
    if len(parts) == 2:
        return parts[0].title(), parts[1].title()
    return s.title(), ""


def _person_document_save(session_db, ot, owner):
    """Crea o actualiza un documento de la persona desde el form multipart.

    Devuelve `(payload, aplicados, conflictos)`: lo que se ha volcado a los datos oficiales de la
    ficha y lo que NO COINCIDE (para que quien sube el documento decida cuál se queda).
    Con `resolve_only=1` no toca el documento: solo aplica lo decidido (`apply_choices`).
    """
    state = _current_user_state()
    doc_id = to_uuid(request.form.get("doc_id"))
    doc = session_db.get(PersonDocument, doc_id) if doc_id else None
    if doc and (doc.owner_type != ot or str(doc.owner_id) != str(owner.id)):
        doc = None

    # Segunda vuelta: la persona ya ha decidido qué se queda en cada campo que no coincidía.
    if _truthy(request.form.get("resolve_only")) and doc is not None:
        try:
            elegido = json.loads(request.form.get("apply_choices") or "{}")
        except Exception:
            elegido = {}
        aplicados, _pend = _person_doc_apply_to_profile(
            session_db, ot, owner, doc,
            first_override=(request.form.get("doc_first_name") or "").strip() or None,
            last_override=(request.form.get("doc_last_name") or "").strip() or None,
            choices={k: v for k, v in (elegido or {}).items()},
        )
        session_db.commit()
        return _person_document_payload(doc), aplicados, []

    creating = doc is None
    if creating:
        base = (
            session_db.query(func.coalesce(func.max(PersonDocument.sort_order), -1))
            .filter(PersonDocument.owner_type == ot, PersonDocument.owner_id == owner.id)
            .scalar()
        )
        doc = PersonDocument(
            owner_type=ot, owner_id=owner.id, sort_order=int(base) + 1,
            created_by_user_id=to_uuid(state.get("user_id")),
            created_by_nick=(state.get("nick") or "").strip() or None,
        )
        session_db.add(doc)

    kind = (request.form.get("kind") or doc.kind or "DNI").strip().upper()
    if kind not in PERSON_DOC_KINDS:
        kind = "DNI"
    doc.kind = kind
    doc.label = (request.form.get("label") or "").strip() or None
    doc.company = (request.form.get("company") or "").strip() or None
    doc.doc_number = (request.form.get("doc_number") or "").strip() or None
    doc.full_name = (request.form.get("full_name") or "").strip() or None
    doc.birth_date = parse_optional_date(request.form.get("birth_date"))
    doc.expiry_date = parse_optional_date(request.form.get("expiry_date"))
    doc.issue_date = parse_optional_date(request.form.get("issue_date"))
    doc.address = (request.form.get("address") or "").strip() or None

    front = _person_doc_store_image(request.files.get("front"))
    if front:
        doc.front_url = front
    elif request.form.get("front_url_clear") == "1":
        doc.front_url = None
    back = _person_doc_store_image(request.files.get("back"))
    if back:
        doc.back_url = back
    elif request.form.get("back_url_clear") == "1":
        doc.back_url = None

    aplicados, conflictos = [], []
    if _truthy(request.form.get("apply_to_profile", "1")):
        aplicados, conflictos = _person_doc_apply_to_profile(
            session_db, ot, owner, doc,
            first_override=(request.form.get("doc_first_name") or "").strip() or None,
            last_override=(request.form.get("doc_last_name") or "").strip() or None,
        )

    session_db.commit()
    return _person_document_payload(doc), aplicados, conflictos


CF_EVENT_KIND_REPAIR_KEY = "cycle_festival_event_kind_repair_v1"


def _cycle_festival_event_kind_repair():
    """UNA SOLA VEZ: devuelve su tipo a los contenedores de EVENTO que el modal de editar degradó a
    CICLO (solo ofrecía festival/ciclo y marcaba ciclo por defecto).

    ⚠️ Solo toca los que quedaron como **CICLO**: un contenedor de evento puede ser legítimamente una
    GIRA (la gira propia del evento) o un FESTIVAL, y esos NO se tocan. Y va con marca en
    `AppSetting`, no como sentencia del esquema: si se ejecutara en cada arranque convertiría en
    EVENTO cualquier gira o ciclo de un evento creado después.
    """
    if (_get_app_setting(CF_EVENT_KIND_REPAIR_KEY) or "").strip() == "done":
        return
    session_db = db()
    try:
        filas = (session_db.query(CycleFestival)
                 .filter(CycleFestival.event_id.isnot(None))
                 .filter(func.upper(func.coalesce(CycleFestival.kind, "")) == "CICLO")
                 .all())
        for cf in filas:
            cf.kind = "EVENTO"
        session_db.commit()
        if filas:
            app.logger.info("[eventos] reparados %d contenedores degradados a ciclo", len(filas))
        _set_app_setting(CF_EVENT_KIND_REPAIR_KEY, "done")
    except Exception:
        session_db.rollback()
        app.logger.exception("[eventos] no se pudo reparar el tipo de los contenedores de evento")
    finally:
        session_db.close()


ROYALTY_FREEZE_BACKFILL_KEY = "royalty_freeze_backfill_v1"
# Estados en los que una liquidación YA está en la calle: tiene que estar consignada.
ROYALTY_MUST_BE_FROZEN_STATUSES = ("GENERATED", "DOWNLOADED", "SENT", "INVOICED", "PAID")


def _royalty_freeze_backfill(session_db=None) -> dict:
    """CONSIGNA las liquidaciones ya GENERADAS o ENVIADAS que no tienen sus datos guardados.

    Las liquidaciones anteriores a que existiera el congelado no guardaban nada, así que cada vez que
    se abrían se recalculaban con los ingresos del momento y «los importes se actualizaban». Aquí se
    les fija su detalle una vez y para siempre:

      · si tenemos el congelado de lo que se ENVIÓ (`last_sent_snapshot`), se consigna ESO: es
        exactamente lo que recibió el beneficiario;
      · si no hay nada, se consigna lo que sale AHORA y se deja dicho en el propio congelado
        (`consigned_from='LIVE'` + la fecha), porque los importes originales no se pueden recuperar.

    Idempotente y best-effort: solo toca las que no tienen nada congelado. Devuelve el recuento."""
    propia = session_db is None
    if propia:
        session_db = db()
    salida = {"revisadas": 0, "consignadas_enviado": 0, "consignadas_ahora": 0, "sin_datos": 0}
    try:
        recs = (session_db.query(RoyaltyLiquidation)
                .filter(func.upper(func.coalesce(RoyaltyLiquidation.status, "")).in_(ROYALTY_MUST_BE_FROZEN_STATUSES))
                .order_by(RoyaltyLiquidation.period_start.asc()).all())
        ahora = _now_madrid()
        for rec in recs:
            salida["revisadas"] += 1
            # ⚠️ Se mira `snapshot` A SECAS, no `_royalty_frozen_beneficiary` (que cae a lo enviado):
            # justo las que solo tienen el congelado del envío son las que hay que dejar consignadas.
            propio = getattr(rec, "snapshot", None)
            if isinstance(propio, dict) and ("total_amount" in propio or propio.get("items")):
                continue          # ya está consignada: no se toca
            enviado = getattr(rec, "last_sent_snapshot", None)
            datos, origen = None, ""
            if isinstance(enviado, dict) and ("total_amount" in enviado or enviado.get("items")):
                datos, origen = json.loads(json.dumps(enviado, default=str)), "SENT"
            else:
                try:
                    datos, _s, _e, _b = _get_royalty_liquidation_beneficiary_data(
                        session_db, rec.beneficiary_kind, str(rec.beneficiary_id),
                        rec.period_start.year, 1 if rec.period_start.month <= 6 else 2,
                        apply_frozen=False)
                    datos = json.loads(json.dumps(datos, default=str))
                    origen = "LIVE"
                except Exception:
                    datos = None
            if not datos:
                salida["sin_datos"] += 1
                continue
            datos["consigned_from"] = origen
            datos["consigned_at"] = ahora.isoformat()
            rec.snapshot = datos
            rec.snapshot_signature = _royalty_data_signature(datos)
            rec.updated_at = ahora
            _royalty_history_add(rec, "CONSIGNED",
                                 note=("consignada con lo que se envió" if origen == "SENT"
                                       else "consignada con los datos de ese momento"),
                                 total=format_eur(_money_or_zero(datos.get("total_amount"))))
            salida["consignadas_enviado" if origen == "SENT" else "consignadas_ahora"] += 1
        session_db.commit()
    except Exception:
        session_db.rollback()
        app.logger.exception("_royalty_freeze_backfill")
    finally:
        if propia:
            session_db.close()
    return salida


def _royalty_freeze_backfill_once():
    """El relleno de arriba, una sola vez en el arranque (marca en `AppSetting`)."""
    if (_get_app_setting(ROYALTY_FREEZE_BACKFILL_KEY) or "").strip() == "done":
        return
    datos = _royalty_freeze_backfill()
    _set_app_setting(ROYALTY_FREEZE_BACKFILL_KEY, "done")
    app.logger.info("Liquidaciones de royalties consignadas: %s con lo enviado, %s con los datos del "
                    "momento, %s sin datos, de %s revisadas.",
                    datos["consignadas_enviado"], datos["consignadas_ahora"],
                    datos["sin_datos"], datos["revisadas"])


@app.post("/discografica/royalties/consignar", endpoint="royalty_liquidations_consign")
@admin_required
def royalty_liquidations_consign():
    """Consigna a mano las liquidaciones generadas o enviadas que no tengan sus datos guardados.
    Sirve para las que aparezcan después del relleno del arranque."""
    if not is_master():
        return forbid("Solo dirección puede consignar liquidaciones.")
    datos = _royalty_freeze_backfill()
    if datos["consignadas_enviado"] or datos["consignadas_ahora"]:
        flash("Consignadas %s liquidaciones (%s con lo que se envió y %s con los datos del momento). "
              "A partir de ahora sus importes no cambian."
              % (datos["consignadas_enviado"] + datos["consignadas_ahora"],
                 datos["consignadas_enviado"], datos["consignadas_ahora"]), "success")
    else:
        flash("Todas las liquidaciones generadas o enviadas ya estaban consignadas.", "success")
    if datos["sin_datos"]:
        flash("%s liquidación(es) no tienen datos recuperables: revísalas a mano." % datos["sin_datos"],
              "warning")
    return redirect(safe_next_or(url_for("discografica_view", section="royalties")))


PERSON_DOCS_BACKFILL_KEY = "person_docs_official_backfill_v1"


def _person_docs_backfill_official_data():
    """UNA SOLA VEZ: a quien YA tenía un DNI o un pasaporte subido, se le ponen en la ficha los datos
    OFICIALES del documento (nombre, apellidos, DNI/NIF, nacimiento y domicilio), sustituyendo lo que
    hubiera. El **nick** no se toca (no es un dato oficial) y un campo que el documento no traiga se
    queda como está. Si una persona tiene varios, manda el DNI (y el más reciente de cada tipo).

    Se ejecuta en el arranque, con marca en `AppSetting` para no repetirse. Best-effort: si algo falla
    se anota en el log y la app sigue.
    """
    if (_get_app_setting(PERSON_DOCS_BACKFILL_KEY) or "").strip() == "done":
        return
    session_db = db()
    tocados, revisados = 0, 0
    try:
        docs = (session_db.query(PersonDocument)
                .filter(PersonDocument.kind.in_(("DNI", "PASSPORT")))
                .order_by(PersonDocument.created_at.asc())
                .all())
        # Por persona, el mejor documento: DNI antes que pasaporte; dentro de cada tipo, el último.
        mejor = {}
        for d in docs:
            clave = (d.owner_type, str(d.owner_id))
            actual = mejor.get(clave)
            if actual is None or (actual.kind != "DNI" and d.kind == "DNI") or (actual.kind == d.kind):
                mejor[clave] = d
        for (ot, owner_id), doc in mejor.items():
            revisados += 1
            owner, ot_ok = _person_doc_owner(session_db, ot, owner_id)
            if owner is None or not ot_ok:
                continue
            fila, campos = _person_doc_official_target(session_db, ot_ok, owner)
            if fila is None:
                continue
            valores = _person_doc_official_values(doc)
            cambio = False
            for campo, attr in campos.items():
                nuevo = valores.get(campo)
                if not nuevo:
                    continue
                if not _person_doc_same_value(getattr(fila, attr, None), nuevo):
                    setattr(fila, attr, nuevo)
                    cambio = True
            if cambio:
                tocados += 1
        session_db.commit()
        _set_app_setting(PERSON_DOCS_BACKFILL_KEY, "done")
        app.logger.info("Datos oficiales desde documentos: %s fichas actualizadas de %s con DNI/pasaporte.",
                        tocados, revisados)
    except Exception:
        session_db.rollback()
        app.logger.exception("_person_docs_backfill_official_data")
    finally:
        session_db.close()


def _person_document_delete_one(session_db, ot, owner, doc_id):
    doc = session_db.get(PersonDocument, to_uuid(doc_id))
    if not doc or doc.owner_type != ot or str(doc.owner_id) != str(owner.id):
        return False
    session_db.delete(doc)
    session_db.commit()
    return True


def _store_doc_image_from_dataurl(dataurl):
    """Sube a Storage (carpeta 'documents') una imagen recibida como data URL base64 (los recortes
    del alta con documento viajan así en el formulario). Devuelve URL absoluta o None."""
    if not dataurl or "," not in dataurl:
        return None
    try:
        import base64
        header, b64 = dataurl.split(",", 1)
        raw = base64.b64decode(b64)
        if not raw:
            return None
        is_png = "png" in header.lower()
        ext, ctype = ("png", "image/png") if is_png else ("jpg", "image/jpeg")
        return _absolute_media_url(_upload_bytes(raw, "documents/%s.%s" % (uuid.uuid4().hex, ext), ctype))
    except Exception:
        return None


def _parse_date_soft(value):
    """Fecha opcional que NO revienta con una fecha imposible.

    `parse_optional_date` propaga el error a propósito (en cientos de rutas es lo que se quiere),
    pero para lo que llega de un escáner en un campo oculto conviene lo contrario: si el dato es
    basura se descarta y ya lo corregirá quien lo revise."""
    try:
        return parse_optional_date(value)
    except Exception:
        return None


def _person_document_create_from_intake(session_db, ot, owner):
    """En el alta de una persona/tercero desde documento, crea un PersonDocument con los campos con
    prefijo `doc_` del formulario (doc_kind, doc_number, doc_full_name, doc_*_date y los recortes
    doc_front_b64/doc_back_b64). Devuelve el doc o None si no se subió/introdujo documento."""
    kind = (request.form.get("doc_kind") or "").strip().upper()
    if kind not in PERSON_DOC_KINDS:
        return None
    front = _store_doc_image_from_dataurl(request.form.get("doc_front_b64"))
    back = _store_doc_image_from_dataurl(request.form.get("doc_back_b64"))
    number = (request.form.get("doc_number") or "").strip() or None
    full_name = (request.form.get("doc_full_name") or "").strip() or None
    if not (front or back or number or full_name):
        return None
    state = _current_user_state()
    doc = PersonDocument(
        owner_type=ot, owner_id=owner.id, kind=kind, sort_order=0,
        doc_number=number, full_name=full_name,
        # ⚠️ Estas tres fechas llegan de campos OCULTOS que rellena el escáner: si el OCR lee mal un
        # día y sale una fecha imposible (31 de febrero), `parse_optional_date` lanza y el alta se
        # cae con un 500. Aquí se descarta el valor y se sigue: es un dato que se puede corregir a
        # mano, no un motivo para tumbar la creación de la persona.
        birth_date=_parse_date_soft(request.form.get("doc_birth_date")),
        expiry_date=_parse_date_soft(request.form.get("doc_expiry_date")),
        issue_date=_parse_date_soft(request.form.get("doc_issue_date")),
        address=(request.form.get("doc_address") or "").strip() or None,
        front_url=front, back_url=back,
        created_by_user_id=to_uuid(state.get("user_id")),
        created_by_nick=(state.get("nick") or "").strip() or None,
    )
    session_db.add(doc)
    return doc


@app.post("/personal/<user_id>/documentos/guardar", endpoint="personnel_document_save")
@admin_required
def personnel_document_save(user_id):
    session_db = db()
    try:
        user = session_db.get(User, to_uuid(user_id))
        if not user:
            return jsonify({"ok": False, "error": "Usuario no encontrado."}), 404
        payload, aplicados, conflictos = _person_document_save(session_db, "USER", user)
        # `aplicados` = datos oficiales que se han rellenado o sustituido; `conflictos` = los que NO
        # coinciden con la ficha, para que quien sube el documento decida cuál se queda.
        return jsonify({"ok": True, "document": payload, "applied": aplicados, "conflicts": conflictos})
    except Exception as e:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(e)}), 500
    finally:
        session_db.close()


