@app.post("/personal/<user_id>/plazo-gastos", endpoint="personnel_expense_deadline_toggle")
@admin_required
def personnel_expense_deadline_toggle(user_id):
    """PARA o REACTIVA el plazo para asignar gastos a bolsas de UNA persona (solo dirección).

    Al reanudar se guarda el tramo parado para descontarlo del plazo: si a alguien se le paró
    tres semanas, al volver no le aparecen los gastos de golpe fuera de plazo.
    """
    if not is_master():
        abort(403)
    session_db = db()
    try:
        user = session_db.get(User, to_uuid(user_id))
        if not user:
            abort(404)
        profile = _ensure_user_profile(session_db, user)
        hoy = today_local()
        if getattr(profile, "expense_deadline_paused", False):
            log = list(profile.expense_pause_log or [])
            log.append({"from": (profile.expense_paused_since or hoy).isoformat(), "to": hoy.isoformat()})
            profile.expense_pause_log = log[-40:]          # histórico acotado
            profile.expense_deadline_paused = False
            profile.expense_paused_since = None
            flash("Plazo de gastos reactivado. Los días que ha estado parado no cuentan.", "success")
        else:
            profile.expense_deadline_paused = True
            profile.expense_paused_since = hoy
            flash("Plazo de gastos parado: no se le reclamará hasta que lo reactives.", "info")
        session_db.commit()
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo cambiar el plazo: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(request.form.get("next") or url_for("personnel_detail_view", user_id=user_id))


@app.post("/personal/plazo-gastos-todos", endpoint="personnel_expense_deadline_toggle_all")
@admin_required
def personnel_expense_deadline_toggle_all():
    """PARA o REACTIVA el plazo de gastos para TODO el personal a la vez (solo dirección)."""
    if not is_master():
        abort(403)
    estado = _expense_pause_global()
    hoy = today_local()
    if estado["paused"]:
        log = [{"from": d.isoformat(), "to": h.isoformat()} for d, h in estado["log"]]
        log.append({"from": (estado["since"] or hoy).isoformat(), "to": hoy.isoformat()})
        _set_app_setting(EXPENSE_PAUSE_ALL_LOG_KEY, json.dumps(log[-40:]))
        _set_app_setting(EXPENSE_PAUSE_ALL_KEY, "0")
        _set_app_setting(EXPENSE_PAUSE_ALL_SINCE_KEY, "")
        flash("Plazo de gastos reactivado para todo el personal.", "success")
    else:
        _set_app_setting(EXPENSE_PAUSE_ALL_KEY, "1")
        _set_app_setting(EXPENSE_PAUSE_ALL_SINCE_KEY, hoy.isoformat())
        flash("Plazo de gastos parado para todo el personal.", "info")
    return redirect(request.form.get("next") or url_for("personnel_view"))


@app.post("/promotores/<pid>/adelantos/guardar", endpoint="promoter_debt_save")
@admin_required
def promoter_debt_save(pid):
    """Crea o actualiza un ADELANTO / DEUDA de un tercero con una empresa del grupo."""
    if not (can_edit_catalogs() or is_master()):
        return forbid("No tienes permisos para anotar adelantos.")
    next_url = safe_next_or(request.form.get("next") or url_for("promoter_detail_view", pid=pid, tab="adelantos"))
    session_db = db()
    try:
        promoter = session_db.get(Promoter, to_uuid(pid))
        if promoter is None:
            flash("Tercero no encontrado.", "warning")
            return redirect(url_for("promoters_view"))
        did = (request.form.get("debt_id") or "").strip()
        row = session_db.get(PartyDebt, to_uuid(did)) if did else None
        if row is None:
            row = PartyDebt(promoter_id=promoter.id)
            session_db.add(row)
        company = session_db.get(GroupCompany, to_uuid((request.form.get("company_id") or "").strip() or "0")) \
            if (request.form.get("company_id") or "").strip() else None
        if company is None:
            flash("Elige la empresa del grupo.", "warning")
            return redirect(next_url)
        kind = (request.form.get("kind") or "ADELANTO").strip().upper()
        row.kind = kind if kind in PARTY_DEBT_LABELS else "ADELANTO"
        row.company_id = company.id
        row.concept = (request.form.get("concept") or "").strip() or None
        row.amount = _parse_money_decimal(request.form.get("amount"))
        row.amount_recovered = _parse_money_decimal(request.form.get("amount_recovered"))
        row.debt_date = parse_optional_date(request.form.get("debt_date"))
        row.due_date = parse_optional_date(request.form.get("due_date"))
        row.notes = (request.form.get("notes") or "").strip() or None
        doc = request.files.get("document")
        if doc and getattr(doc, "filename", ""):
            row.document_url = upload_file(doc, "party_debts")
            row.document_name = (getattr(doc, "filename", "") or "").strip() or None
        # Cerrada a mano, o sola cuando ya no queda nada por recuperar.
        cerrar = _truthy(request.form.get("close"))
        pendiente = _money_or_zero(row.amount) - _money_or_zero(row.amount_recovered)
        if cerrar or pendiente <= 0:
            row.status = "CERRADA"
            row.closed_at = row.closed_at or _now_madrid()
        else:
            row.status = "ABIERTA"
            row.closed_at = None
        state = _current_user_state()
        if not row.created_by_user_id and state.get("user_id"):
            row.created_by_user_id = to_uuid(state.get("user_id"))
            row.created_by_nick = (state.get("nick") or state.get("email") or "").strip() or None
        row.updated_at = _now_madrid()
        session_db.commit()
        flash("Guardado.", "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo guardar: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(next_url)


