def _expense_alert_email(rows: list, title: str, intro: str, person=None) -> str:
    """Correo de aviso con el listado de gastos e importes (y la foto de la persona al escalar)."""
    lines = ""
    total = Decimal("0")
    for r in rows:
        total += _money_or_zero(r.get("amount_gross"))
        lines += (
            "<tr>"
            f"<td style='padding:7px 9px;border-bottom:1px solid #eceef1;font-size:13px;color:#111'>{escape(r.get('concept') or 'Gasto')}"
            f"<br><span style='color:#6b7280;font-size:12px'>{escape(r.get('source_label') or '')}"
            f"{(' · ' + escape(r.get('date_label'))) if r.get('date_label') else ''}</span></td>"
            f"<td style='padding:7px 9px;border-bottom:1px solid #eceef1;font-size:13px;text-align:right;white-space:nowrap'>{format_eur(r.get('amount_gross'))}</td>"
            "</tr>"
        )
    person_html = ""
    if person is not None:
        photo = (getattr(person, "photo_url", None) or "").strip()
        person_html = (
            "<div style='display:flex;align-items:center;gap:10px;margin:0 0 14px;'>"
            + (f"<img src='{escape(photo)}' width='48' height='48' style='border-radius:50%;object-fit:cover'>" if photo else "")
            + f"<div style='font-size:16px;font-weight:700;color:#111'>{escape(getattr(person, 'nick', '') or '')}</div></div>"
        )
    return f"""
    <div style="font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;max-width:620px;margin:0 auto;">
      <h2 style="font-size:19px;color:#111;margin:0 0 12px;">{escape(title)}</h2>
      {person_html}
      <p style="font-size:14px;color:#374151;margin:0 0 14px;">{intro}</p>
      <table style="width:100%;border-collapse:collapse;margin:0 0 10px;">
        <tbody>{lines}</tbody>
        <tfoot><tr>
          <td style="padding:8px 9px;font-size:13px;font-weight:700;color:#111">Total</td>
          <td style="padding:8px 9px;font-size:13px;font-weight:700;text-align:right;white-space:nowrap">{format_eur(total)}</td>
        </tr></tfoot>
      </table>
      <p style="text-align:center;margin:18px 0;">
        <a href="{_external_url_for('my_expenses_assign')}" style="background:#E33D48;color:#fff;text-decoration:none;padding:12px 26px;border-radius:8px;font-weight:600;display:inline-block;">Asignar mis gastos</a>
      </p>
    </div>
    """


@app.get('/cron/gastos-sin-asignar', endpoint='cron_unassigned_expenses')
def cron_unassigned_expenses():
    """Avisos de gastos sin asignar: a la PERSONA cuando pasa la semana y a DIRECCIÓN a los 15 días.
    No aplica a dirección. Lo llama una tarea programada (misma clave que los otros cron)."""
    key = (request.args.get("key") or "").strip()
    expected = (settings.ENTERTICKET_CRON_KEY or settings.CHARTMETRIC_CRON_KEY or "").strip()
    if not expected or key != expected:
        abort(404)
    notified, escalated = 0, 0
    session_db = db()
    try:
        rows = (session_db.query(PersonalExpense)
                .filter(PersonalExpense.status.in_(("PENDING", "IN_BAG")))
                .all())
        by_user = {}
        for r in rows:
            by_user.setdefault(str(r.user_id), []).append(r)
        pause_all = _expense_pause_global()
        if pause_all["paused"]:
            # Plazo parado para todo el personal: no se reclama nada a nadie.
            return jsonify({"ok": True, "notified": 0, "escalated": 0, "paused": "ALL"})
        for uid, items in by_user.items():
            if _user_is_direccion(session_db, uid):
                continue
            profile = session_db.query(UserProfile).filter(UserProfile.user_id == to_uuid(uid)).first()
            pause = _expense_pause_context(session_db, uid, pause_all, profile)
            if pause["paused"]:
                continue                      # a esta persona se le ha parado el plazo
            user = session_db.get(User, to_uuid(uid))
            email_to = (getattr(user, "email", None) or "").strip()
            overdue = [r for r in items if _expense_days_left(r, pause) < 0]
            if not overdue:
                continue
            # 1) Aviso a la persona (una vez por gasto).
            fresh = [r for r in overdue if not r.notified_at]
            if fresh and email_to:
                ok, _err = _send_optional_email(
                    email_to,
                    f"Tienes {len(overdue)} gasto{'s' if len(overdue) != 1 else ''} sin asignar a una bolsa",
                    _expense_alert_email(
                        [_personal_expense_row(r, pause) for r in overdue],
                        "Gastos sin asignar",
                        f"Tienes <strong>{len(overdue)}</strong> gasto{'s' if len(overdue) != 1 else ''} "
                        f"sin asignar a una bolsa. Tienes <strong>una semana</strong> para asignarlos.",
                    ),
                )
                if ok:
                    for r in fresh:
                        r.notified_at = _now_madrid()
                    notified += 1
            # 2) Escalado a dirección a los 15 días.
            very_old = [r for r in overdue
                        if not r.escalated_at
                        and _expense_days_left(r, pause) <= (EXPENSE_ASSIGN_DAYS - EXPENSE_ESCALATE_DAYS)]
            if very_old:
                _inactive_dir = _inactive_user_ids(session_db)
                dir_emails = [u.email for u in session_db.query(User).filter(User.role == 10).all()
                              if (u.email or "").strip() and u.id not in _inactive_dir]
                if dir_emails:
                    ok, _err = _send_optional_email(
                        dir_emails[:5],
                        f"{getattr(profile, 'nick', '') or 'Una persona'}: gastos sin asignar desde hace más de {EXPENSE_ESCALATE_DAYS} días",
                        _expense_alert_email(
                            [_personal_expense_row(r, pause) for r in very_old],
                            "Gastos sin asignar a una bolsa",
                            f"tiene los siguientes gastos sin asignar a una bolsa desde hace más de "
                            f"<strong>{EXPENSE_ESCALATE_DAYS} días</strong>.",
                            person=profile,
                        ),
                    )
                    if ok:
                        for r in very_old:
                            r.escalated_at = _now_madrid()
                        escalated += 1
        session_db.commit()
        return jsonify({"ok": True, "notified": notified, "escalated": escalated})
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        session_db.close()


# ===========================================================================
#  PLEO · importación automática de los gastos del personal
#  ------------------------------------------------------------------------
#  Hay una cuenta de Pleo POR EMPRESA del grupo (`PleoAccount`, se configura en
#  Integraciones → Pleo, una subpestaña por empresa) y cada persona tiene su
#  usuario en cada una. El sondeo:
#    1. refresca los empleados de la empresa y los empareja con el personal por
#       CORREO (el principal o cualquiera de los «correos de integraciones» de su
#       ficha); lo que no cuadra queda para vincular a mano.
#    2. trae los apuntes de una ventana de días y los deja en «Mis gastos» de su
#       dueño, con importe, comercio, nota, etiquetas y justificante.
#    3. repesca los que siguen incompletos (sin justificante o sin liquidar)
#       aunque sean viejos: en Pleo la foto del ticket llega días después.
#  ANTIDUPLICADOS: `personal_expenses.pleo_entry_id` tiene índice UNIQUE, así que
#  ni dos sondeos simultáneos ni volver a gestionar el archivo pueden duplicar
#  nada. Un gasto ya tipificado NUNCA se reescribe: como mucho se le engancha el
#  justificante que faltaba o se anota un aviso.
#  Pleo no tiene webhooks de gastos, por eso esto va por sondeo (cron + botón).
# ===========================================================================

PLEO_DEFAULT_WINDOW_DAYS = 45      # días hacia atrás que revisa cada sondeo
PLEO_CHASE_LIMIT = 250             # tope de repescas individuales por sondeo
PLEO_RECEIPTS_MAX = 6              # justificantes que se bajan por gasto
PLEO_EMPLOYEES_TTL_H = 12          # cada cuánto se refrescan los empleados
PLEO_CATALOG_TTL_H = 24            # cada cuánto se refresca el catálogo (IVA, etiquetas)


def _pleo_norm_email(value) -> str:
    return (value or "").strip().lower()


def _pleo_fmt_dt(value) -> str:
    try:
        return value.strftime("%d/%m/%Y %H:%M") if value else ""
    except Exception:
        return ""


def _pleo_not_newer(remote, stored) -> bool:
    """True si el apunte de Pleo no es más nuevo que lo que ya tenemos (comparación a prueba de tz)."""
    if not remote or not stored:
        return False
    try:
        a, b = remote, stored
        if getattr(a, "tzinfo", None) is None and getattr(b, "tzinfo", None) is not None:
            a = a.replace(tzinfo=b.tzinfo)
        elif getattr(b, "tzinfo", None) is None and getattr(a, "tzinfo", None) is not None:
            b = b.replace(tzinfo=a.tzinfo)
        return a <= b
    except Exception:
        return False


@contextmanager
def _pleo_pg_lock(key: str):
    """Exclusión ENTRE workers/procesos con un advisory lock de Postgres (igual que Enterticket).

    yields False si otro proceso ya está sincronizando esa cuenta (hay que saltarse el trabajo).
    Si la BD no responde, yields True: mejor sincronizar sin cerrojo que no sincronizar.
    """
    from models import engine as _pleo_engine
    conn = None
    got = True
    try:
        conn = _pleo_engine.connect()
        got = bool(conn.exec_driver_sql("SELECT pg_try_advisory_lock(hashtext(%s))", (key,)).scalar())
    except Exception:
        got = True
    try:
        yield got
    finally:
        if conn is not None:
            try:
                if got:
                    conn.exec_driver_sql("SELECT pg_advisory_unlock(hashtext(%s))", (key,))
            except Exception:
                pass
            try:
                conn.close()
            except Exception:
                pass


def _pleo_client_for(acc):
    """Cliente de Pleo de una cuenta. Import perezoso: un fallo del módulo no toca el arranque."""
    import pleo_utils
    return pleo_utils.PleoClient((getattr(acc, "api_key", "") or settings.PLEO_API_KEY or "").strip())


def _pleo_email_index(session_db) -> dict:
    """{correo → user_id} de TODO el personal actual.

    Incluye el correo de acceso (`User.email`) y los «correos de integraciones» de la ficha
    (`UserProfile.integration_emails`), que existen justo para esto: en Pleo la gente suele estar
    con el correo de otra de las empresas del grupo. El principal manda si hay choque.
    Se excluyen los eliminados (sus gastos quedan huérfanos y los ve dirección).
    """
    out = {}
    dead = set()
    try:
        for (uid,) in (session_db.query(UserSecurity.user_id)
                       .filter(UserSecurity.is_deleted.is_(True)).all()):
            if uid:
                dead.add(str(uid))
    except Exception:
        dead = set()
    try:
        for uid, email in session_db.query(User.id, User.email).all():
            if str(uid) in dead:
                continue
            e = _pleo_norm_email(email)
            if e:
                out.setdefault(e, uid)
    except Exception:
        return out
    try:
        for prof in session_db.query(UserProfile).all():
            if not prof.user_id or str(prof.user_id) in dead:
                continue
            for item in (getattr(prof, "integration_emails", None) or []):
                e = _pleo_norm_email(item if isinstance(item, str) else (item or {}).get("email"))
                if e:
                    out.setdefault(e, prof.user_id)
    except Exception:
        pass
    return out


def _parse_integration_emails(raw) -> list:
    """Normaliza los «correos de integraciones» de la ficha (uno por línea, coma o punto y coma)."""
    if isinstance(raw, (list, tuple)):
        items = list(raw)
    else:
        items = re.split(r"[\n,;]+", str(raw or ""))
    out = []
    for item in items:
        e = _pleo_norm_email(item)
        if not e or "@" not in e:
            continue
        if e not in out:
            out.append(e)
    return out[:20]


def _pleo_refresh_employees(session_db, acc, client) -> tuple:
    """Trae los empleados de la empresa en Pleo y los empareja por correo.

    Un vínculo puesto a MANO (o descartado) NO se pisa nunca con el automático.
    Devuelve (total, sin_vincular).
    """
    emails = _pleo_email_index(session_db)
    total = unresolved = 0
    for emp in client.employees(acc.pleo_company_id):
        pid = str(emp.get("id") or "").strip()
        if not pid:
            continue
        total += 1
        link = (session_db.query(PleoEmployeeLink)
                .filter(PleoEmployeeLink.account_id == acc.id,
                        PleoEmployeeLink.pleo_employee_id == pid).first())
        if link is None:
            link = PleoEmployeeLink(account_id=acc.id, pleo_employee_id=pid)
            session_db.add(link)
        link.email = _pleo_norm_email(emp.get("email")) or None
        link.first_name = (emp.get("firstName") or "").strip() or None
        link.last_name = (emp.get("lastName") or "").strip() or None
        link.code = (emp.get("code") or "").strip() or None
        link.last_seen_at = _now_madrid()
        link.updated_at = _now_madrid()
        if (link.match_mode or "NONE").upper() not in {"MANUAL", "IGNORED"}:
            uid = emails.get(link.email or "")
            link.user_id = uid
            link.match_mode = "AUTO_EMAIL" if uid else "NONE"
        if not link.user_id and (link.match_mode or "").upper() != "IGNORED":
            unresolved += 1
    acc.last_employees_sync_at = _now_madrid()
    acc.updated_at = _now_madrid()
    session_db.flush()
    return (total, unresolved)


def _pleo_refresh_catalog(session_db, acc, client) -> None:
    """Cachea el IVA (para desglosar la base) y las etiquetas (para MOSTRARLAS con su nombre).

    Best-effort: si a la credencial le falta el permiso de alguno de los dos, la importación sigue
    funcionando igual (sin desglose de IVA o sin nombres de etiqueta).
    """
    try:
        taxes = {}
        for tc in client.tax_codes(acc.pleo_company_id):
            tid = str(tc.get("id") or "").strip()
            if not tid:
                continue
            taxes[tid] = {
                "rate": str(tc.get("rate") or "0"),
                "type": (tc.get("type") or "").strip().lower(),
                "name": (tc.get("name") or "").strip(),
                "code": (tc.get("code") or "").strip(),
            }
        if taxes:
            acc.tax_codes = taxes
    except Exception as exc:
        app.logger.info("[pleo] no se pudieron leer los códigos de IVA: %s", exc)
    try:
        tags = {}
        for tg in client.tags_catalog(acc.pleo_company_id):
            tid = str(tg.get("id") or "").strip()
            if not tid:
                continue
            grp = tg.get("group") or {}
            tags[tid] = {
                "group": (grp.get("name") or "").strip(),
                "value": (tg.get("name") or "").strip(),
            }
        if tags:
            acc.tag_catalog = tags
    except Exception as exc:
        app.logger.info("[pleo] no se pudo leer el catálogo de etiquetas: %s", exc)
    acc.last_catalog_sync_at = _now_madrid()
    acc.updated_at = _now_madrid()


def _pleo_amounts(entry, tax_codes) -> tuple:
    """(bruto, neto, IVA, divisa) de un apunte, en Decimal.

    El BRUTO es siempre lo que se pagó de verdad (`transactionValue`): no se inventa nada. Si el
    código de IVA del apunte lleva tipo, se deduce la base; con IVA invertido (`reverse`) o sin
    código, base = bruto y que lo ajuste quien lo tipifique.
    """
    from decimal import ROUND_HALF_UP
    import pleo_utils
    tv = entry.get("transactionValue") or {}
    gross = pleo_utils.money_to_decimal(tv)
    currency = (tv.get("currency") or "EUR").upper()
    if not gross:
        bill = entry.get("totalBillValue") or {}
        if bill:
            gross = pleo_utils.money_to_decimal(bill)
            currency = (bill.get("currency") or currency).upper()
    info = (tax_codes or {}).get(str(entry.get("taxCodeId") or "")) or {}
    try:
        rate = Decimal(str(info.get("rate") or "0"))
    except (InvalidOperation, ValueError):
        rate = Decimal("0")
    kind = (info.get("type") or "").lower()
    gross = gross.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    if rate > 0 and kind in {"inclusive", "exclusive"}:
        net = (gross / (Decimal(1) + rate)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    else:
        net = gross
    return (gross, net, (gross - net), currency)


# MCC (código de categoría del comercio) → módulo de gasto sugerido de la bolsa. Es solo una
# SUGERENCIA para que tipificar sea un clic: quien lo asigna puede soltarlo donde quiera.
def _pleo_suggest_category(mcc: str, merchant: str, note: str) -> str:
    code = (mcc or "").strip()
    n = int(code) if code.isdigit() else 0
    if n:
        if 3500 <= n <= 3999 or n == 7011:
            return "ALOJAMIENTO"
        if (3000 <= n <= 3499) or n in {4111, 4112, 4121, 4131, 4457, 4468, 4511, 4582, 4789,
                                        5541, 5542, 5983, 7512, 7513, 7519, 7523, 7524}:
            return "LOGISTICA"
        if n in {5811, 5812, 5813, 5814}:
            return "PERSONAL"
        if n in {5733, 5735, 7841}:
            return "MUSICOS"
        if n in {7311, 7392, 5968, 2741, 7333, 7338, 7339}:
            return "MARKETING"
        if n in {9211, 9222, 9311, 9399, 9402, 9405}:
            return "PERMISOS"
        if 4900 <= n <= 4999:
            return "RECINTO"
        if n in {7922, 7929, 7932, 7933, 7996, 7999}:
            return "SONIDO_LUCES"
    txt = _norm_text_key(" ".join([merchant or "", note or ""]))
    for words, cat in (
        (("hotel", "hostal", "apartament", "airbnb", "booking", "pension", "albergue"), "ALOJAMIENTO"),
        (("renfe", "iberia", "vueling", "ryanair", "taxi", "uber", "cabify", "gasolin", "repsol",
          "cepsa", "galp", "shell", "bp ", "peaje", "parking", "aparcamiento", "autopista",
          "avis", "hertz", "europcar", "alsa", "blablacar", "flixbus", "aena", "furgo"), "LOGISTICA"),
        (("catering", "rider", "agua", "fruta"), "RIDER"),
        (("restaurant", "cafeteria", "cerveceria", "menu", "comida", "bar ", "tapas"), "PERSONAL"),
        (("cuerdas", "baqueta", "parche", "instrument", "backline", "amplificador"), "MUSICOS"),
        (("sonido", "luces", "iluminacion", "escenario", "truss", "estructura", "vallas"), "SONIDO_LUCES"),
        (("publicidad", "meta ", "facebook", "instagram", "google ads", "imprenta", "cartel",
          "flyer", "merch", "fotografo"), "MARKETING"),
        (("sgae", "aie", "tasa", "licencia", "ayuntamiento", "seguro", "notaria"), "PERMISOS"),
    ):
        for w in words:
            if w in txt:
                return cat
    return "OTROS"


def _pleo_tag_rows(entry, tag_catalog) -> list:
    """Etiquetas del apunte con su nombre legible (los apuntes solo traen los IDs).

    No se usan para clasificar nada: se MUESTRAN en «Mis gastos» y en la bolsa para que asignar el
    gasto sea más fácil.
    """
    out = []
    for tag in (entry.get("tags") or []):
        tid = str((tag or {}).get("tagId") or "").strip()
        if not tid:
            continue
        info = (tag_catalog or {}).get(tid) or {}
        value = (info.get("value") or "").strip()
        if not value:
            continue
        out.append({"group": (info.get("group") or "").strip(), "value": value})
    return out


def _pleo_document_type(entry) -> str:
    """FACTURA si Pleo tiene los datos fiscales del proveedor; si no, TICKET."""
    sup = entry.get("supplier") or {}
    if (sup.get("documentType") or "").upper() == "FACTURA" or (sup.get("documentNumber") or "").strip():
        return "FACTURA"
    return "TICKET"


def _pleo_concept(entry) -> str:
    merchant = ((entry.get("merchant") or {}).get("name") or "").strip()
    note = (entry.get("note") or "").strip()
    fam = (entry.get("family") or "").upper()
    base = merchant or note or {"MILEAGE": "Kilometraje", "PER_DIEM": "Dietas"}.get(fam, "Gasto de Pleo")
    return base[:200]


def _pleo_sync_receipts(session_db, acc, client, row, entry) -> int:
    """Baja los justificantes NUEVOS y los guarda en nuestro Storage.

    Nunca vuelve a bajar uno ya guardado (`pleo_receipt_ids`): por eso «gestionar el archivo» no
    duplica nada. Si el gasto ya estaba tipificado y su gasto de la bolsa no tenía adjunto, se le
    engancha ahora (es el caso típico: el cargo llega hoy y la foto del ticket, tres días después).
    """
    import pleo_utils
    ids = [str(x) for x in (entry.get("receiptIds") or []) if x]
    if not ids:
        row.needs_receipt = True
        return 0
    have = {str(x) for x in (row.pleo_receipt_ids or [])}
    todo = [x for x in ids if x not in have]
    if not todo:
        row.needs_receipt = not bool(row.file_url)
        return 0
    metas = {}
    try:
        for rc in client.receipts(str(entry.get("id") or "")):
            rid = str(rc.get("id") or "")
            if rid:
                metas[rid] = rc
    except pleo_utils.PleoError as exc:
        app.logger.info("[pleo] justificantes de %s no disponibles: %s", entry.get("id"), exc)
        return 0
    files = list(row.pleo_files or [])
    added = 0
    stem = _norm_text_key(row.provider_name or "gasto").replace(" ", "-")[:40] or "gasto"
    for rid in todo[:PLEO_RECEIPTS_MAX]:
        rc = metas.get(rid) or {}
        url = (rc.get("url") or "").strip()
        if not url:
            continue
        try:
            data, ctype = client.download(url)
        except pleo_utils.PleoError as exc:
            app.logger.info("[pleo] no se pudo bajar el justificante %s: %s", rid, exc)
            continue
        if not data:
            continue
        mime = (rc.get("mimeType") or ctype or "application/pdf").split(";")[0].strip()
        ext = pleo_utils.ext_for_mime(mime)
        try:
            stored = _absolute_media_url(_upload_bytes(data, "pleo/%s.%s" % (uuid.uuid4().hex, ext), mime))
        except Exception as exc:
            app.logger.warning("[pleo] no se pudo guardar el justificante %s: %s", rid, exc)
            continue
        date_part = (row.expense_date.isoformat() if row.expense_date else date.today().isoformat())
        files.append({
            "url": stored,
            "name": "pleo-%s-%s.%s" % (date_part, stem, ext),
            "mime": mime,
            "receipt_id": rid,
            "source": (rc.get("source") or ""),
        })
        have.add(rid)
        added += 1
    row.pleo_files = files
    row.pleo_receipt_ids = sorted(have)
    if files and not (row.file_url or "").strip():
        row.file_url = files[0]["url"]
        row.original_name = files[0]["name"]
    row.needs_receipt = not bool((row.file_url or "").strip())
    # Ya tipificado y sin adjunto: se le pone el justificante que faltaba (sin tocar nada más).
    if row.bag_expense_id and (row.file_url or "").strip():
        be = session_db.get(BagExpense, row.bag_expense_id)
        if be is not None and not (be.attachment_url or "").strip():
            be.attachment_url = row.file_url
            be.attachment_name = row.original_name
            be.attachment_mime = (files[0].get("mime") if files else None)
            if (be.consolidation_status or "PENDIENTE").upper() == "PENDIENTE":
                be.consolidation_status = "PENDIENTE_VALIDAR"
            be.updated_at = _now_madrid()
    return added


def _pleo_upsert_entry(session_db, acc, entry, links, client, stats) -> None:
    """Crea o actualiza el «gasto personal» de un apunte de Pleo. Idempotente."""
    import pleo_utils
    eid = str(entry.get("id") or "").strip()
    if not eid:
        return
    fam = (entry.get("family") or "").upper()
    sub = (entry.get("subFamily") or "").upper()
    st = (entry.get("status") or "").upper()
    if fam not in set(pleo_utils.PERSONAL_FAMILIES) or sub in pleo_utils.SKIP_SUBFAMILIES:
        stats["skipped"] += 1
        return
    # populate_existing: si la fila ya estaba cargada en esta sesión (p. ej. porque la persona la ha
    # asignado a una bolsa mientras corría el sondeo), se relee de la BD. Así nunca se decide sobre
    # un estado viejo (y por tanto no se reescribe algo que ya está tipificado).
    row = (session_db.query(PersonalExpense).populate_existing()
           .filter(PersonalExpense.pleo_entry_id == eid).first())
    # --- Anulado o borrado en Pleo ---
    if entry.get("deletedAt") or st in pleo_utils.DEAD_STATUSES:
        if row is None:
            stats["skipped"] += 1
            return
        if (row.status or "PENDING") == "PENDING" and not row.bag_id:
            session_db.delete(row)                     # nunca llegó a ser un gasto: fuera
        else:
            row.is_cancelled = True
            row.sync_warning = ("Pleo lo ha anulado o borrado DESPUÉS de asignarlo. "
                                "Revísalo con administración.")
            row.last_synced_at = _now_madrid()
        stats["cancelled"] += 1
        return
    # --- ¿De quién es? ---
    emp_id = str(entry.get("employeeId") or "").strip()
    link = links.get(emp_id)
    user_id = getattr(link, "user_id", None) if link else None
    if not user_id:
        # Sin dueño no se puede guardar (`user_id` es obligatorio). Se cuenta y sale en
        # Integraciones; al vincular a la persona se importan sus gastos de golpe.
        stats["orphans"] += 1
        return
    gross, net, tax, currency = _pleo_amounts(entry, acc.tax_codes or {})
    merchant = ((entry.get("merchant") or {}).get("name") or "").strip()
    note = (entry.get("note") or "").strip()
    performed = _pleo_date(entry.get("performedAt")) or _pleo_date(entry.get("bookkeepingDate"))
    updated = _pleo_dt(entry.get("updatedAt"))
    concept = _pleo_concept(entry)
    if gross < 0:
        concept = ("Abono · " + concept)[:200]
    is_new = row is None
    if is_new:
        # Con «solo con justificante» activado, el gasto no entra hasta que Pleo tenga la foto o la
        # factura (se comprueba ANTES de crearlo para no dejar rastro ni tener que borrarlo luego).
        if bool(getattr(acc, "require_receipt", False)) and not (entry.get("receiptIds") or []):
            stats["skipped"] += 1
            return
        row = PersonalExpense(user_id=user_id, source="PLEO", pleo_entry_id=eid, status="PENDING")
        session_db.add(row)
    else:
        # Ya está tipificado: NO se reescribe nada. Solo se avisa si el importe ha cambiado y se
        # aprovecha para engancharle el justificante que faltara (más abajo).
        if (row.status or "") == "ASSIGNED":
            if row.amount_gross is not None and _money_or_zero(row.amount_gross) != gross:
                row.sync_warning = ("El importe ha cambiado en Pleo (%s → %s) después de asignarlo."
                                    % (_money_or_zero(row.amount_gross), gross))
            row.pleo_updated_at = updated or row.pleo_updated_at
            row.pleo_status = st or row.pleo_status
            row.pleo_review_status = (entry.get("reviewStatus") or "").upper() or row.pleo_review_status
            row.last_synced_at = _now_madrid()
            stats["receipts"] += _pleo_sync_receipts(session_db, acc, client, row, entry)
            stats["updated"] += 1
            return
        # Sin cambios en Pleo y con justificante ya bajado: nada que hacer.
        if _pleo_not_newer(updated, row.pleo_updated_at) and not row.needs_receipt:
            return
    row.user_id = user_id
    row.pleo_account_id = acc.id
    row.pleo_company_id = acc.pleo_company_id
    row.pleo_employee_id = emp_id or None
    row.pleo_updated_at = updated
    row.pleo_status = st or None
    row.pleo_family = fam or None
    row.pleo_subfamily = sub or None
    row.pleo_review_status = (entry.get("reviewStatus") or "").upper() or None
    row.pleo_note = note or None
    row.pleo_tags = _pleo_tag_rows(entry, acc.tag_catalog or {})
    row.pleo_account_code = (entry.get("accountCode") or "").strip() or None
    row.merchant_mcc = ((entry.get("merchant") or {}).get("merchantCategoryCode") or "").strip() or None
    row.concept = concept
    row.provider_name = merchant or None
    row.expense_date = performed
    row.amount_gross = gross
    row.amount_net = net
    row.amount_tax = tax
    row.currency = currency
    row.document_type = _pleo_document_type(entry)
    row.invoice_number = ((entry.get("supplier") or {}).get("documentNumber") or "").strip() or None
    row.suggested_category = _pleo_suggest_category(row.merchant_mcc, merchant, note)
    row.is_cancelled = False
    row.last_synced_at = _now_madrid()
    row.updated_at = _now_madrid()
    session_db.flush()
    stats["receipts"] += _pleo_sync_receipts(session_db, acc, client, row, entry)
    stats["created" if is_new else "updated"] += 1


def _pleo_date(value):
    """Fecha de un campo ISO de Pleo (acepta fecha o fecha-hora, con o sin Z)."""
    if not value:
        return None
    txt = str(value).strip()
    try:
        return datetime.fromisoformat(txt.replace("Z", "+00:00")).date()
    except ValueError:
        pass
    try:
        return date.fromisoformat(txt[:10])
    except ValueError:
        return None


def _pleo_dt(value):
    if not value:
        return None
    try:
        return datetime.fromisoformat(str(value).strip().replace("Z", "+00:00"))
    except ValueError:
        return None


def _pleo_sync_account(session_db, acc, *, window_days=None, employee_ids=None,
                       since=None, chase=True) -> dict:
    """Sincroniza UNA empresa. Devuelve el recuento de lo que ha hecho.

    Estrategia: ventana móvil por `performedAt` (la API de Pleo no permite filtrar por `updatedAt`)
    + repesca individual de los gastos que siguen incompletos, aunque queden fuera de la ventana.
    """
    from sqlalchemy.exc import IntegrityError
    import pleo_utils
    stats = {"seen": 0, "created": 0, "updated": 0, "receipts": 0,
             "orphans": 0, "cancelled": 0, "skipped": 0, "errors": 0, "chased": 0}
    if not (acc.pleo_company_id or "").strip():
        raise pleo_utils.PleoError("Falta el ID de empresa de Pleo (company_id).")
    client = _pleo_client_for(acc)
    # Empleados y catálogo, con su propio TTL para no gastar llamadas de más.
    if _pleo_stale(acc.last_employees_sync_at, PLEO_EMPLOYEES_TTL_H):
        _pleo_refresh_employees(session_db, acc, client)
    if _pleo_stale(acc.last_catalog_sync_at, PLEO_CATALOG_TTL_H):
        _pleo_refresh_catalog(session_db, acc, client)
    session_db.commit()
    links = {l.pleo_employee_id: l for l in
             session_db.query(PleoEmployeeLink).filter(PleoEmployeeLink.account_id == acc.id).all()}
    days = int(window_days or acc.sync_window_days or PLEO_DEFAULT_WINDOW_DAYS)
    frm = since or (date.today() - timedelta(days=max(1, days)))
    for entry in client.search_entries(acc.pleo_company_id,
                                       performed_from=frm.isoformat(),
                                       statuses=pleo_utils.LIVE_STATUSES + sorted(pleo_utils.DEAD_STATUSES),
                                       employee_ids=employee_ids):
        stats["seen"] += 1
        try:
            with session_db.begin_nested():        # savepoint por gasto: uno malo no tira el resto
                _pleo_upsert_entry(session_db, acc, entry, links, client, stats)
        except IntegrityError:
            stats["skipped"] += 1                  # ya existía (lo impide el UNIQUE): perfecto
        except Exception as exc:
            stats["errors"] += 1
            app.logger.warning("[pleo] gasto %s: %s", entry.get("id"), exc)
        if stats["seen"] % 50 == 0:
            session_db.commit()
    session_db.commit()
    # --- Repesca: los que siguen sin justificante o sin liquidar, por viejos que sean ---
    if chase and not employee_ids:
        pend = (session_db.query(PersonalExpense)
                .filter(PersonalExpense.pleo_account_id == acc.id,
                        PersonalExpense.pleo_entry_id.isnot(None),
                        PersonalExpense.is_cancelled == False,        # noqa: E712
                        or_(PersonalExpense.needs_receipt == True,    # noqa: E712
                            PersonalExpense.pleo_status == "PENDING"),
                        or_(PersonalExpense.expense_date < frm,
                            PersonalExpense.expense_date.is_(None)))
                .order_by(PersonalExpense.last_synced_at.asc().nullsfirst())
                .limit(PLEO_CHASE_LIMIT).all())
        for row in pend:
            try:
                entry = client.entry(row.pleo_entry_id)
                if not entry:
                    continue
                stats["chased"] += 1
                with session_db.begin_nested():
                    _pleo_upsert_entry(session_db, acc, entry, links, client, stats)
            except Exception as exc:
                stats["errors"] += 1
                app.logger.info("[pleo] repesca de %s: %s", row.pleo_entry_id, exc)
        session_db.commit()
    return stats


def _pleo_stale(ts, hours) -> bool:
    """True si `ts` es None o tiene más de `hours` horas (comparación a prueba de tz)."""
    if not ts:
        return True
    try:
        now = _now_madrid()
        ref = ts
        if getattr(ref, "tzinfo", None) is None and getattr(now, "tzinfo", None) is not None:
            ref = ref.replace(tzinfo=now.tzinfo)
        return (now - ref) > timedelta(hours=hours)
    except Exception:
        return True


def _pleo_sync_all(*, window_days=None) -> dict:
    """Sondea TODAS las empresas activas. Cada una con su cerrojo, y un fallo no para a las demás."""
    out = {"accounts": 0, "ok": 0, "failed": 0, "created": 0, "updated": 0,
           "receipts": 0, "orphans": 0}
    session_db = db()
    try:
        accounts = (session_db.query(PleoAccount)
                    .filter(PleoAccount.is_active == True)          # noqa: E712
                    .all())
        for acc in accounts:
            if not (acc.api_key or settings.PLEO_API_KEY or "").strip():
                continue
            out["accounts"] += 1
            with _pleo_pg_lock("pleo:%s" % acc.id) as got:
                if not got:
                    continue                     # otro worker ya está con esta empresa
                try:
                    stats = _pleo_sync_account(session_db, acc, window_days=window_days)
                    acc.last_sync_at = _now_madrid()
                    acc.last_sync_ok = True
                    acc.last_error = None
                    acc.last_stats = stats
                    acc.updated_at = _now_madrid()
                    session_db.commit()
                    out["ok"] += 1
                    for k in ("created", "updated", "receipts", "orphans"):
                        out[k] += int(stats.get(k) or 0)
                except Exception as exc:
                    session_db.rollback()
                    out["failed"] += 1
                    try:
                        acc.last_sync_at = _now_madrid()
                        acc.last_sync_ok = False
                        acc.last_error = str(exc)[:500]
                        session_db.commit()
                    except Exception:
                        session_db.rollback()
                    app.logger.warning("[pleo] empresa %s: %s", acc.group_company_id, exc)
    finally:
        session_db.close()
    return out


def _pleo_import_for_link(session_db, link) -> dict:
    """Importa los gastos de UNA persona en UNA empresa (al vincularla a mano).

    Así los gastos que quedaron huérfanos por un correo que no cuadraba entran de golpe, sin
    esperar al siguiente sondeo ni depender de la ventana de días.
    """
    acc = session_db.get(PleoAccount, link.account_id)
    if acc is None or not link.user_id:
        return {}
    days = max(int(acc.sync_window_days or PLEO_DEFAULT_WINDOW_DAYS), 180)
    since = acc.backfill_from or (date.today() - timedelta(days=days))
    return _pleo_sync_account(session_db, acc, since=since,
                              employee_ids=[link.pleo_employee_id], chase=False)


def _pleo_account_rows(session_db) -> list:
    """Una fila por EMPRESA DEL GRUPO para la pestaña Pleo de Integraciones (subpestaña por empresa).

    Las empresas sin cuenta salen igual, con los campos vacíos listos para pegar la credencial.
    """
    companies = session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
    accounts = {str(a.group_company_id): a for a in session_db.query(PleoAccount).all()}
    rows = []
    for comp in companies:
        acc = accounts.get(str(comp.id))
        employees, pending_links = [], 0
        counts = {"total": 0, "pending": 0, "no_receipt": 0, "warnings": 0}
        if acc is not None:
            links = (session_db.query(PleoEmployeeLink)
                     .filter(PleoEmployeeLink.account_id == acc.id)
                     .order_by(PleoEmployeeLink.email.asc().nullslast()).all())
            people = {}
            for uid, nick in (session_db.query(UserProfile.user_id, UserProfile.nick).all()):
                people[str(uid)] = nick
            for l in links:
                mode = (l.match_mode or "NONE").upper()
                if not l.user_id and mode != "IGNORED":
                    pending_links += 1
                employees.append({
                    "id": str(l.id),
                    "email": (l.email or ""),
                    "name": (" ".join([x for x in [(l.first_name or ""), (l.last_name or "")] if x]).strip()),
                    "user_id": (str(l.user_id) if l.user_id else ""),
                    "user_nick": people.get(str(l.user_id), "") if l.user_id else "",
                    "mode": mode,
                })
            counts["total"] = (session_db.query(func.count(PersonalExpense.id))
                               .filter(PersonalExpense.pleo_account_id == acc.id).scalar()) or 0
            counts["pending"] = (session_db.query(func.count(PersonalExpense.id))
                                 .filter(PersonalExpense.pleo_account_id == acc.id,
                                         PersonalExpense.status == "PENDING").scalar()) or 0
            counts["no_receipt"] = (session_db.query(func.count(PersonalExpense.id))
                                    .filter(PersonalExpense.pleo_account_id == acc.id,
                                            PersonalExpense.needs_receipt == True).scalar()) or 0   # noqa: E712
            counts["warnings"] = (session_db.query(func.count(PersonalExpense.id))
                                  .filter(PersonalExpense.pleo_account_id == acc.id,
                                          PersonalExpense.sync_warning.isnot(None)).scalar()) or 0
        stats = (acc.last_stats if acc is not None else None) or {}
        rows.append({
            "company_id": str(comp.id),
            "company_name": (comp.name or "Empresa"),
            "company_logo": (comp.logo_url or ""),
            "slug": re.sub(r"[^a-z0-9]+", "-", (comp.name or "empresa").lower()).strip("-") or "empresa",
            "has_account": acc is not None,
            "pleo_company_id": (getattr(acc, "pleo_company_id", "") or ""),
            "pleo_organization_id": (getattr(acc, "pleo_organization_id", "") or ""),
            "has_key": bool((getattr(acc, "api_key", "") or "").strip()),
            "key_hint": (("…" + (acc.api_key or "")[-6:]) if acc is not None and (acc.api_key or "") else ""),
            "is_active": bool(getattr(acc, "is_active", False)),
            "require_receipt": bool(getattr(acc, "require_receipt", False)),
            "sync_window_days": int(getattr(acc, "sync_window_days", 0) or PLEO_DEFAULT_WINDOW_DAYS),
            "backfill_from": (acc.backfill_from.isoformat() if acc is not None and acc.backfill_from else ""),
            "last_sync": (_pleo_fmt_dt(acc.last_sync_at) if acc is not None else ""),
            "last_ok": (getattr(acc, "last_sync_ok", None)),
            "last_error": (getattr(acc, "last_error", "") or ""),
            "last_stats": stats,
            "orphans": int(stats.get("orphans") or 0),
            "employees": employees,
            "pending_links": pending_links,
            "counts": counts,
        })
    return rows


def _pleo_configured_any(session_db) -> bool:
    """True si alguna empresa tiene la integración lista (para el badge de la pestaña)."""
    try:
        for acc in session_db.query(PleoAccount).filter(PleoAccount.is_active == True).all():   # noqa: E712
            if (acc.api_key or settings.PLEO_API_KEY or "").strip() and (acc.pleo_company_id or "").strip():
                return True
    except Exception:
        return False
    return False


def _pleo_get_or_create_account(session_db, company_id):
    comp = session_db.get(GroupCompany, to_uuid(str(company_id)) or uuid.uuid4())
    if comp is None:
        return (None, None)
    acc = (session_db.query(PleoAccount)
           .filter(PleoAccount.group_company_id == comp.id).first())
    if acc is None:
        acc = PleoAccount(group_company_id=comp.id)
        session_db.add(acc)
        session_db.flush()
    return (comp, acc)


def _pleo_back():
    return redirect(url_for("integrations_view") + "#tab-pleo")


@app.post("/integraciones/pleo/<company_id>/guardar", endpoint="pleo_account_save")
@admin_required
def pleo_account_save(company_id):
    """Guarda la configuración de Pleo de UNA empresa del grupo."""
    if not is_master():
        return forbid("Solo dirección puede configurar las integraciones.")
    session_db = db()
    try:
        comp, acc = _pleo_get_or_create_account(session_db, company_id)
        if comp is None:
            flash("Empresa no encontrada.", "warning")
            return _pleo_back()
        acc.pleo_company_id = (request.form.get("pleo_company_id") or "").strip() or None
        acc.pleo_organization_id = (request.form.get("pleo_organization_id") or "").strip() or None
        # La credencial solo se toca si escriben una nueva (el campo va vacío por seguridad).
        new_key = (request.form.get("api_key") or "").strip()
        if new_key:
            acc.api_key = new_key
        if request.form.get("clear_key") == "1":
            acc.api_key = None
        acc.is_active = (request.form.get("is_active") == "1")
        acc.require_receipt = (request.form.get("require_receipt") == "1")
        try:
            acc.sync_window_days = max(1, min(int(request.form.get("sync_window_days") or PLEO_DEFAULT_WINDOW_DAYS), 400))
        except (TypeError, ValueError):
            acc.sync_window_days = PLEO_DEFAULT_WINDOW_DAYS
        acc.backfill_from = parse_optional_date(request.form.get("backfill_from"))
        acc.updated_at = _now_madrid()
        session_db.commit()
        flash("Pleo · %s: configuración guardada." % (comp.name or "empresa"), "success")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudo guardar la configuración de Pleo: %s" % exc, "danger")
    finally:
        session_db.close()
    return _pleo_back()


@app.post("/integraciones/pleo/<company_id>/probar", endpoint="pleo_account_test")
@admin_required
def pleo_account_test(company_id):
    """Prueba la credencial de una empresa contra la API real de Pleo."""
    if not is_master():
        return forbid("Solo dirección puede configurar las integraciones.")
    session_db = db()
    try:
        comp, acc = _pleo_get_or_create_account(session_db, company_id)
        if comp is None:
            flash("Empresa no encontrada.", "warning")
            return _pleo_back()
        session_db.commit()
        client = _pleo_client_for(acc)
        ok, msg = client.ping((acc.pleo_company_id or "").strip() or None)
        flash("Pleo · %s: %s" % (comp.name or "empresa", msg), "success" if ok else "danger")
    except Exception as exc:
        session_db.rollback()
        flash("Error probando Pleo: %s" % exc, "danger")
    finally:
        session_db.close()
    return _pleo_back()


@app.post("/integraciones/pleo/<company_id>/sincronizar", endpoint="pleo_account_sync")
@admin_required
def pleo_account_sync(company_id):
    """Sondea ahora una empresa. Con `full=1` usa el histórico configurado en vez de la ventana."""
    if not is_master():
        return forbid("Solo dirección puede configurar las integraciones.")
    session_db = db()
    try:
        comp, acc = _pleo_get_or_create_account(session_db, company_id)
        if comp is None:
            flash("Empresa no encontrada.", "warning")
            return _pleo_back()
        session_db.commit()
        full = (request.form.get("full") == "1")
        since = (acc.backfill_from if full else None)
        with _pleo_pg_lock("pleo:%s" % acc.id) as got:
            if not got:
                flash("Pleo · %s: ya se está sincronizando en este momento." % (comp.name or "empresa"), "info")
                return _pleo_back()
            stats = _pleo_sync_account(session_db, acc, since=since)
            acc.last_sync_at = _now_madrid()
            acc.last_sync_ok = True
            acc.last_error = None
            acc.last_stats = stats
            acc.updated_at = _now_madrid()
            session_db.commit()
        msg = ("%s gastos revisados · %s nuevos · %s actualizados · %s justificantes"
               % (stats.get("seen", 0), stats.get("created", 0), stats.get("updated", 0), stats.get("receipts", 0)))
        if stats.get("orphans"):
            msg += " · ⚠ %s sin dueño (vincula a esas personas más abajo)" % stats["orphans"]
        flash("Pleo · %s: %s" % (comp.name or "empresa", msg), "success")
    except Exception as exc:
        session_db.rollback()
        try:
            comp2, acc2 = _pleo_get_or_create_account(session_db, company_id)
            if acc2 is not None:
                acc2.last_sync_at = _now_madrid()
                acc2.last_sync_ok = False
                acc2.last_error = str(exc)[:500]
                session_db.commit()
        except Exception:
            session_db.rollback()
        flash("Pleo: %s" % exc, "danger")
    finally:
        session_db.close()
    return _pleo_back()


@app.post("/integraciones/pleo/empleado/<link_id>/vincular", endpoint="pleo_employee_link_save")
@admin_required
def pleo_employee_link_save(link_id):
    """Vincula a mano un empleado de Pleo con una persona de la app (o lo descarta).

    Al vincularlo se importan de inmediato SUS gastos, que hasta ahora quedaban sin dueño.
    """
    if not is_master():
        return forbid("Solo dirección puede configurar las integraciones.")
    session_db = db()
    try:
        link = session_db.get(PleoEmployeeLink, to_uuid(str(link_id)) or uuid.uuid4())
        if link is None:
            flash("Empleado de Pleo no encontrado.", "warning")
            return _pleo_back()
        action = (request.form.get("link_action") or "link").strip().lower()
        if action == "ignore":
            link.user_id = None
            link.match_mode = "IGNORED"
            link.updated_at = _now_madrid()
            session_db.commit()
            flash("Empleado de Pleo descartado: sus gastos no se importarán.", "info")
            return _pleo_back()
        uid = to_uuid((request.form.get("user_id") or "").strip())
        if not uid or session_db.get(User, uid) is None:
            flash("Elige a la persona con la que vincularlo.", "warning")
            return _pleo_back()
        link.user_id = uid
        link.match_mode = "MANUAL"
        link.updated_at = _now_madrid()
        session_db.commit()
        stats = {}
        try:
            stats = _pleo_import_for_link(session_db, link) or {}
            session_db.commit()
        except Exception as exc:
            session_db.rollback()
            app.logger.warning("[pleo] import tras vincular: %s", exc)
        created = int(stats.get("created") or 0)
        flash("Empleado vinculado.%s" % (" Se han importado %s gastos suyos." % created if created else ""), "success")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudo vincular: %s" % exc, "danger")
    finally:
        session_db.close()
    return _pleo_back()


# ============================ INTEGRACIÓN CON CABIFY ============================
# Una cuenta por EMPRESA DEL GRUPO. La gente de la cuenta de empresa está en Cabify con su correo
# de esa empresa, así que el emparejamiento es por correo contra `User.email` y los «correos de
# integraciones» de la ficha — el mismo índice que ya usa Pleo (`_pleo_email_index`).
#
# La API de Cabify NO tiene webhooks de gastos ni permite filtrar por «modificado desde», así que
# se sondea con una ventana móvil de días, usuario por usuario (el listado global de ventas no dice
# de quién es cada una; el de usuario, sí).
#
# ⚠️ El esquema documentado de la API no expone un PDF por viaje: se importa el gasto con todo su
# detalle fiscal y, si algún día Cabify publica el documento, `CabifyClient.sale_receipt_url` lo
# recoge y se adjunta solo.
CABIFY_DEFAULT_WINDOW_DAYS = 45


def _cabify_client(acc):
    from cabify_utils import CabifyClient
    return CabifyClient(acc.client_id or "", acc.client_secret or "", acc.base_url or None)


def _cabify_person_name(session_db, link) -> str:
    """Nombre para el justificante: el de la ficha de la app y, si no hay, el que tiene en Cabify."""
    prof = None
    if getattr(link, "user_id", None):
        prof = (session_db.query(UserProfile)
                .filter(UserProfile.user_id == link.user_id).first())
    if prof:
        completo = " ".join([x for x in [(prof.first_name or "").strip(),
                                         (prof.last_name or "").strip()] if x]).strip()
        if completo:
            return completo
        if (prof.nick or "").strip():
            return prof.nick.strip()
    return " ".join([x for x in [(getattr(link, "first_name", "") or "").strip(),
                                 (getattr(link, "last_name", "") or "").strip()] if x]).strip()


CABIFY_FAKE_RECEIPTS_PURGE_KEY = "cabify_fake_receipts_purge_v1"
# Carpeta de Storage donde la app dejaba los PDF que se fabricaba. Todo lo que cuelgue de ahí es
# nuestro invento; una factura subida a mano vive en otra carpeta y NO se toca.
CABIFY_FAKE_RECEIPT_MARK = "/cabify/"


def _cabify_purge_fake_receipts(session_db, limit: int | None = None) -> dict:
    """Borra los PDF que la app se fabricaba y hacía pasar por justificante de Cabify.

    ⚠️ Aquellos documentos NO eran de Cabify: los generaba la propia app con los datos de la venta.
    Se quitan del gasto y se borran de Storage. Solo se tocan los `file_url` que apuntan a la
    carpeta `cabify/` de nuestro bucket: una factura que alguien subiera a mano vive en otra
    carpeta y se respeta.
    """
    out = {"revisados": 0, "borrados": 0, "storage": 0}
    q = (session_db.query(PersonalExpense)
         .filter(PersonalExpense.source == "CABIFY")
         .filter(PersonalExpense.file_url.isnot(None))
         .filter(PersonalExpense.file_url != ""))
    if limit:
        q = q.limit(int(limit))
    for row in q.all():
        url = (row.file_url or "").strip()
        out["revisados"] += 1
        if CABIFY_FAKE_RECEIPT_MARK not in url:
            continue                      # no es de los nuestros: se deja como está
        try:
            from supabase_utils import delete_object_by_url
            if delete_object_by_url(url):
                out["storage"] += 1
        except Exception:
            pass                          # que no se pueda borrar el fichero no impide desengancharlo
        row.file_url = None
        row.original_name = None
        if (row.document_type or "").upper() in ("JUSTIFICANTE", "FACTURA"):
            row.document_type = None
        out["borrados"] += 1
    session_db.commit()
    return out


def _cabify_purge_fake_receipts_bg():
    """Purga de los PDF inventados en el ARRANQUE, con marca (best-effort, una sola vez)."""
    if (_get_app_setting(CABIFY_FAKE_RECEIPTS_PURGE_KEY) or "").strip() == "done":
        return
    session_db = db()
    try:
        out = _cabify_purge_fake_receipts(session_db)
        app.logger.info("[cabify] justificantes inventados: %d revisados, %d desenganchados, "
                        "%d borrados de Storage", out["revisados"], out["borrados"], out["storage"])
        _set_app_setting(CABIFY_FAKE_RECEIPTS_PURGE_KEY, "done")
    except Exception:
        session_db.rollback()
        app.logger.exception("[cabify] no se pudieron quitar los justificantes inventados")
    finally:
        session_db.close()


def _cabify_sync_account(session_db, acc, since=None, user_ids=None) -> dict:
    """Trae los gastos de UNA cuenta de Cabify y los mete en «Mis gastos» de cada persona."""
    from cabify_utils import CabifyClient, CabifyError, parse_sale   # noqa: F401
    from sqlalchemy.exc import IntegrityError

    stats = {"users": 0, "linked": 0, "sales": 0, "created": 0, "skipped": 0, "unmatched": 0,
             "receipts": 0, "supplements": 0}
    if not acc or not acc.is_active:
        return stats
    client = _cabify_client(acc)
    hoy = today_local()
    desde = since or (hoy - timedelta(days=int(acc.sync_window_days or CABIFY_DEFAULT_WINDOW_DAYS)))
    email_index = _pleo_email_index(session_db)

    # 1) Empleados de la cuenta → filas de enlace, emparejando por correo.
    enlaces = {}
    for row in client.users(state="active"):
        cid = str(row.get("id") or "").strip()
        if not cid:
            continue
        stats["users"] += 1
        email = _pleo_norm_email(row.get("email"))
        link = (session_db.query(CabifyUserLink)
                .filter(CabifyUserLink.account_id == acc.id,
                        CabifyUserLink.cabify_user_id == cid).first())
        if link is None:
            link = CabifyUserLink(account_id=acc.id, cabify_user_id=cid)
            session_db.add(link)
        link.email = email or link.email
        link.first_name = (row.get("name") or "").strip() or link.first_name
        link.last_name = (row.get("surname") or "").strip() or link.last_name
        link.last_seen_at = datetime.now(TZ_MADRID)
        # Solo se auto-empareja lo que no se haya tocado a mano ni descartado.
        if (link.match_mode or "NONE").upper() in ("NONE", "AUTO_EMAIL"):
            uid = email_index.get(email) if email else None
            link.user_id = uid
            link.match_mode = "AUTO_EMAIL" if uid else "NONE"
        if link.user_id:
            stats["linked"] += 1
            enlaces[cid] = link
        elif (link.match_mode or "").upper() != "IGNORED":
            stats["unmatched"] += 1
    session_db.flush()

    # 2) Gastos de cada persona vinculada.
    objetivo = {k: v for k, v in enlaces.items() if not user_ids or k in set(user_ids)}
    empresa = getattr(acc, "company", None) or session_db.get(GroupCompany, acc.group_company_id)
    for cid, link in objetivo.items():
        quien = _cabify_person_name(session_db, link)
        # Un VIAJE puede generar VARIAS ventas (el trayecto y sus suplementos: espera, peaje,
        # limpieza…). Se agrupan por viaje para que en «Mis gastos» salga UNA línea con el total,
        # no cuatro sueltas. La venta «principal» es la que trae el trayecto.
        por_viaje: dict = {}
        for venta in client.user_sales(cid, desde, hoy, acc.currency or "EUR"):
            datos = parse_sale(venta)
            if not datos["code"]:
                continue
            stats["sales"] += 1
            clave = datos["journey_id"] or ("venta:" + datos["code"])
            grupo = por_viaje.setdefault(clave, {"principal": None, "ventas": []})
            grupo["ventas"].append(datos)
            if grupo["principal"] is None or (not datos["is_supplement"] and not datos["is_rectification"]
                                              and grupo["principal"]["is_supplement"]):
                if not datos["is_supplement"] or grupo["principal"] is None:
                    grupo["principal"] = datos

        for clave, grupo in por_viaje.items():
            principal = grupo["principal"] or grupo["ventas"][0]
            codigos = [v["code"] for v in grupo["ventas"]]
            journey = principal["journey_id"] or ""
            bruto = sum((v["amount_gross"] for v in grupo["ventas"]), Decimal("0"))
            neto = sum((v["amount_net"] for v in grupo["ventas"]), Decimal("0"))
            iva = sum((v["amount_tax"] for v in grupo["ventas"]), Decimal("0"))
            datos = dict(principal)
            datos.update({"amount_gross": bruto, "amount_net": neto, "amount_tax": iva,
                          "supplements": len([v for v in grupo["ventas"] if v["is_supplement"]])})

            # ¿Ya está? Se busca por VIAJE (para poder engancharle suplementos que lleguen después)
            # y, si no, por el código de la venta principal.
            existe = None
            if journey:
                existe = (session_db.query(PersonalExpense)
                          .filter(PersonalExpense.cabify_journey_id == journey).first())
            if existe is None:
                existe = (session_db.query(PersonalExpense)
                          .filter(PersonalExpense.cabify_sale_code.in_(codigos)).first())
            if existe is not None:
                stats["skipped"] += 1
                cambiado = False
                # Suplementos que aún no se habían sumado (la lista de códigos evita sumar dos veces).
                aplicados = set(getattr(existe, "cabify_sale_codes", None) or [])
                if not aplicados:
                    aplicados = {existe.cabify_sale_code} if existe.cabify_sale_code else set()
                nuevos = [v for v in grupo["ventas"] if v["code"] not in aplicados]
                if nuevos and existe.status in ("PENDING", "IN_BAG"):
                    existe.amount_gross = _money_or_zero(existe.amount_gross) + sum(
                        (v["amount_gross"] for v in nuevos), Decimal("0"))
                    existe.amount_net = _money_or_zero(existe.amount_net) + sum(
                        (v["amount_net"] for v in nuevos), Decimal("0"))
                    existe.amount_tax = _money_or_zero(existe.amount_tax) + sum(
                        (v["amount_tax"] for v in nuevos), Decimal("0"))
                    aplicados.update(v["code"] for v in nuevos)
                    existe.cabify_sale_codes = sorted(aplicados)
                    existe.concept = datos["concept"]
                    cambiado = True
                    stats["supplements"] += len(nuevos)
                elif nuevos:
                    existe.sync_warning = ("Este viaje tiene suplementos posteriores por "
                                           + format_eur(sum((v["amount_gross"] for v in nuevos), Decimal("0")))
                                           + " que no se han sumado porque el gasto ya estaba asignado.")
                    cambiado = True
                if journey and not (existe.cabify_journey_id or ""):
                    existe.cabify_journey_id = journey
                    cambiado = True
                # Los viajes que se importaron sin justificante (o cuyo PDF falló) lo reciben ahora:
                # así ningún gasto de Cabify se queda con el semáforo de factura en rojo.
                # Si Cabify llega a servir el recibo del viaje, se adjunta ESE. La app NO fabrica
                # ningún documento: un PDF hecho por nosotros no es el justificante de Cabify.
                if not (existe.file_url or "").strip() and (datos["receipt_url"] or "").strip():
                    existe.file_url = datos["receipt_url"].strip()
                    existe.document_type = "FACTURA"
                    stats["receipts"] += 1
                continue

            # Solo se adjunta el documento que dé CABIFY. Su API no lo expone hoy (verificado en el
            # índice completo de su referencia: no hay ningún endpoint de recibo en PDF), así que el
            # gasto entra SIN factura y quien lo tenga la sube desde «Mis gastos», o pide que se
            # acepte sin ella. Antes se fabricaba un PDF propio: eso no es un justificante.
            justificante = (datos["receipt_url"] or "").strip()
            if justificante:
                stats["receipts"] += 1
            fecha = hoy
            for candidata in (datos.get("trip_date"), datos.get("invoice_date")):
                try:
                    if candidata:
                        fecha = date.fromisoformat(str(candidata)[:10])
                        break
                except ValueError:
                    continue
            try:
                with session_db.begin_nested():
                    session_db.add(PersonalExpense(
                        user_id=link.user_id,
                        source="CABIFY",
                        cabify_sale_code=principal["code"],
                        cabify_journey_id=(journey or None),
                        cabify_sale_codes=sorted(set(codigos)),
                        concept=datos["concept"],
                        provider_name="Cabify",
                        expense_date=fecha,
                        amount_net=datos["amount_net"],
                        amount_gross=datos["amount_gross"],
                        amount_tax=datos["amount_tax"],
                        currency=datos["currency"],
                        invoice_number=principal["code"],
                        document_type=("FACTURA" if justificante else None),
                        file_url=(justificante or None),
                        # La etiqueta del viaje (charge code) se guarda como etiqueta del gasto:
                        # es lo que dice a qué actividad iba, y se pinta igual que las de Pleo.
                        pleo_tags=([{"group": "", "value": datos["charge_code"]}]
                                   if datos.get("charge_code") else []),
                        status="PENDING",
                    ))
                stats["created"] += 1
            except IntegrityError:
                # Ya existía (lo impide el UNIQUE). ⚠️ NO se llama a session_db.rollback(): el
                # savepoint lo deshace ya el `with begin_nested()`, y un rollback aquí tiraría la
                # transacción ENTERA (todo lo importado antes en este sondeo). Igual que en Pleo.
                stats["skipped"] += 1

    acc.last_sync_at = datetime.now(TZ_MADRID)
    acc.last_sync_ok = True
    acc.last_error = None
    acc.last_stats = stats
    if acc.backfill_from and (not acc.backfill_done_from or acc.backfill_done_from > desde):
        acc.backfill_done_from = desde
    session_db.commit()
    return stats


def _cabify_sync_all(window_days: int | None = None) -> dict:
    """Sondea TODAS las cuentas activas de Cabify. Cada empresa por su lado; si una falla, sigue."""
    out = {"accounts": 0, "created": 0, "errors": []}
    session_db = db()
    try:
        cuentas = session_db.query(CabifyAccount).filter(CabifyAccount.is_active.is_(True)).all()
        for acc in cuentas:
            with _pleo_pg_lock(f"cabify:{acc.id}") as libre:
                if not libre:
                    continue
                out["accounts"] += 1
                try:
                    desde = None
                    if window_days:
                        desde = today_local() - timedelta(days=int(window_days))
                    stats = _cabify_sync_account(session_db, acc, since=desde)
                    out["created"] += int(stats.get("created") or 0)
                except Exception as exc:
                    session_db.rollback()
                    acc.last_sync_at = datetime.now(TZ_MADRID)
                    acc.last_sync_ok = False
                    acc.last_error = str(exc)[:500]
                    session_db.commit()
                    out["errors"].append({"company_id": str(acc.group_company_id), "error": str(exc)[:200]})
        return out
    finally:
        session_db.close()


def _cabify_account_rows(session_db) -> list:
    """Una fila por EMPRESA DEL GRUPO para la pestaña Cabify de Integraciones."""
    from cabify_utils import SANDBOX_BASE_URL
    companies = session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
    accounts = {str(a.group_company_id): a for a in session_db.query(CabifyAccount).all()}
    people = {str(uid): nick for uid, nick in session_db.query(UserProfile.user_id, UserProfile.nick).all()}
    rows = []
    for comp in companies:
        acc = accounts.get(str(comp.id))
        usuarios, pendientes, total_gastos = [], 0, 0
        if acc is not None:
            for l in (session_db.query(CabifyUserLink)
                      .filter(CabifyUserLink.account_id == acc.id)
                      .order_by(CabifyUserLink.email.asc().nullslast()).all()):
                mode = (l.match_mode or "NONE").upper()
                if not l.user_id and mode != "IGNORED":
                    pendientes += 1
                usuarios.append({
                    "id": str(l.id), "email": (l.email or ""),
                    "name": " ".join([x for x in [(l.first_name or ""), (l.last_name or "")] if x]).strip(),
                    "user_id": (str(l.user_id) if l.user_id else ""),
                    "user_nick": people.get(str(l.user_id), "") if l.user_id else "",
                    "mode": mode,
                })
            total_gastos = (session_db.query(func.count(PersonalExpense.id))
                            .filter(PersonalExpense.source == "CABIFY",
                                    PersonalExpense.user_id.in_(
                                        [to_uuid(u["user_id"]) for u in usuarios if u["user_id"]] or [uuid.uuid4()]
                                    )).scalar()) or 0
        rows.append({
            "company": comp, "account": acc,
            "base_url": (getattr(acc, "base_url", None) or SANDBOX_BASE_URL),
            "users": usuarios, "pending_links": pendientes, "expenses": total_gastos,
        })
    return rows


@app.post('/integraciones/cabify/cuenta', endpoint='cabify_account_save')
@admin_required
def cabify_account_save():
    """Guarda la credencial de Cabify de UNA empresa del grupo."""
    if not is_master():
        flash("Solo dirección puede configurar las integraciones.", "warning")
        return redirect(url_for("integrations_view", tab="cabify"))
    session_db = db()
    try:
        cid = to_uuid(request.form.get("group_company_id") or "")
        comp = session_db.get(GroupCompany, cid) if cid else None
        if not comp:
            flash("Empresa no válida.", "warning")
            return redirect(url_for("integrations_view", tab="cabify"))
        acc = (session_db.query(CabifyAccount)
               .filter(CabifyAccount.group_company_id == comp.id).first())
        if acc is None:
            acc = CabifyAccount(group_company_id=comp.id)
            session_db.add(acc)
        acc.base_url = (request.form.get("base_url") or "").strip() or None
        acc.client_id = (request.form.get("client_id") or "").strip() or None
        # El secreto solo se pisa si escriben uno nuevo (en pantalla va enmascarado).
        nuevo_secreto = (request.form.get("client_secret") or "").strip()
        if nuevo_secreto and not nuevo_secreto.startswith("•"):
            acc.client_secret = nuevo_secreto
        acc.currency = (request.form.get("currency") or "EUR").strip().upper()[:3] or "EUR"
        acc.is_active = _truthy(request.form.get("is_active"))
        try:
            acc.sync_window_days = max(int(request.form.get("sync_window_days") or CABIFY_DEFAULT_WINDOW_DAYS), 1)
        except (TypeError, ValueError):
            acc.sync_window_days = CABIFY_DEFAULT_WINDOW_DAYS
        acc.backfill_from = parse_optional_date(request.form.get("backfill_from"))
        acc.updated_at = datetime.now(TZ_MADRID)
        session_db.commit()
        flash(f"Cuenta de Cabify de {comp.name} guardada.", "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo guardar la cuenta de Cabify: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("integrations_view", tab="cabify"))


@app.post('/integraciones/cabify/<company_id>/probar', endpoint='cabify_account_test')
@admin_required
def cabify_account_test(company_id):
    """Comprueba que las credenciales valen (pide la primera página de usuarios)."""
    if not is_master():
        return jsonify({"ok": False, "error": "Solo dirección."}), 403
    session_db = db()
    try:
        acc = (session_db.query(CabifyAccount)
               .filter(CabifyAccount.group_company_id == to_uuid(company_id)).first())
        if not acc:
            return jsonify({"ok": False, "error": "Esta empresa aún no tiene cuenta de Cabify."}), 404
        # La URL de producción no la publica Cabify: se prueba la configurada y, si no responde, las
        # candidatas conocidas. La que funcione se guarda, para que no haya que adivinarla.
        from cabify_utils import find_working_base_url
        try:
            base, info = find_working_base_url(acc.client_id or "", acc.client_secret or "", acc.base_url)
        except Exception as exc:
            return jsonify({"ok": False, "error": str(exc)})
        cambiada = (base or "").rstrip("/") != (acc.base_url or "").rstrip("/")
        if cambiada:
            acc.base_url = base
            acc.updated_at = datetime.now(TZ_MADRID)
            session_db.commit()
        return jsonify({"ok": True, "base_url": base, "base_url_changed": cambiada, **info})
    finally:
        session_db.close()


@app.post('/integraciones/cabify/<company_id>/sincronizar', endpoint='cabify_account_sync')
@admin_required
def cabify_account_sync(company_id):
    """Sondeo manual de una cuenta desde Integraciones."""
    if not is_master():
        flash("Solo dirección puede sincronizar.", "warning")
        return redirect(url_for("integrations_view", tab="cabify"))
    session_db = db()
    try:
        acc = (session_db.query(CabifyAccount)
               .filter(CabifyAccount.group_company_id == to_uuid(company_id)).first())
        if not acc:
            flash("Esta empresa aún no tiene cuenta de Cabify.", "warning")
            return redirect(url_for("integrations_view", tab="cabify"))
        stats = _cabify_sync_account(session_db, acc)
        aviso = (f"Cabify: {stats.get('created', 0)} gasto(s) nuevo(s) · "
                 f"{stats.get('receipts', 0)} justificante(s) adjuntado(s) · "
                 f"{stats.get('linked', 0)} persona(s) vinculada(s) · "
                 f"{stats.get('unmatched', 0)} sin emparejar.")
        if stats.get("supplements"):
            aviso += f" Se sumaron {stats['supplements']} suplemento(s) a su viaje."
        flash(aviso, "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo sincronizar con Cabify: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("integrations_view", tab="cabify"))


@app.post('/integraciones/cabify/justificantes', endpoint='cabify_purge_fake_receipts')
@admin_required
def cabify_purge_fake_receipts():
    """Quita los PDF que la app se fabricaba y hacía pasar por justificante de Cabify.

    Los borra de Storage y desengancha el gasto, para que el semáforo diga la verdad: ese viaje NO
    tiene todavía su factura. Solo toca los ficheros que generó la app; una factura subida a mano se
    respeta."""
    if not is_master():
        flash("Solo dirección puede hacerlo.", "warning")
        return redirect(url_for("integrations_view", tab="cabify"))
    session_db = db()
    try:
        out = _cabify_purge_fake_receipts(session_db)
        if out["borrados"]:
            flash(f"Cabify: se han quitado {out['borrados']} justificante(s) que generaba la app "
                  f"({out['storage']} borrado(s) también del almacenamiento). Esos viajes quedan "
                  "sin factura, que es lo que son.", "success")
        else:
            flash("Cabify: no queda ningún justificante generado por la app.", "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudieron quitar: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("integrations_view", tab="cabify"))


@app.post('/integraciones/cabify/enlace/<link_id>', endpoint='cabify_user_link_save')
@admin_required
def cabify_user_link_save(link_id):
    """Vincula a mano un usuario de Cabify con una persona de la app (o lo descarta).

    Al vincularlo se importan sus gastos en el momento, sin esperar al siguiente sondeo.
    """
    if not is_master():
        flash("Solo dirección puede tocar los enlaces.", "warning")
        return redirect(url_for("integrations_view", tab="cabify"))
    session_db = db()
    try:
        link = session_db.get(CabifyUserLink, to_uuid(link_id) or uuid.uuid4())
        if not link:
            abort(404)
        accion = (request.form.get("action") or "link").strip().lower()
        if accion == "ignore":
            link.user_id = None
            link.match_mode = "IGNORED"
            session_db.commit()
            flash("Usuario de Cabify descartado: sus gastos no se importarán.", "success")
            return redirect(url_for("integrations_view", tab="cabify"))
        uid = to_uuid(request.form.get("user_id") or "")
        link.user_id = uid
        link.match_mode = "MANUAL" if uid else "NONE"
        session_db.commit()
        if uid:
            acc = session_db.get(CabifyAccount, link.account_id)
            dias = max(int(getattr(acc, "sync_window_days", 0) or CABIFY_DEFAULT_WINDOW_DAYS), 180)
            desde = (getattr(acc, "backfill_from", None) or (today_local() - timedelta(days=dias)))
            stats = _cabify_sync_account(session_db, acc, since=desde, user_ids=[link.cabify_user_id])
            flash(f"Vinculado. Se han importado {stats.get('created', 0)} gasto(s) suyos.", "success")
        else:
            flash("Enlace actualizado.", "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo actualizar el enlace: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("integrations_view", tab="cabify"))


@app.get("/cron/cabify/refresh", endpoint="cron_cabify_refresh")
def cron_cabify_refresh():
    """Sondeo periódico de Cabify (tarea programada externa con ?key=). Sin sesión.

    Cabify no manda webhooks de gastos, así que este cron es lo que hace que la importación sea
    automática. Recomendado cada 1-2 horas."""
    expected = (getattr(settings, "CABIFY_CRON_KEY", "") or settings.PLEO_CRON_KEY
                or settings.CHARTMETRIC_CRON_KEY or "").strip()
    key = (request.args.get("key") or "").strip()
    if not expected or key != expected:
        return ("forbidden", 403)
    try:
        window = int(request.args.get("dias") or 0) or None
    except (TypeError, ValueError):
        window = None
    try:
        out = _cabify_sync_all(window_days=window)
    except Exception as exc:
        app.logger.exception("[cabify] cron falló")
        return (jsonify({"ok": False, "error": str(exc)}), 500)
    return jsonify({"ok": True, **out})


@app.get("/cron/pleo/refresh", endpoint="cron_pleo_refresh")
def cron_pleo_refresh():
    """Sondeo periódico de Pleo (tarea programada externa con ?key=). Sin sesión.

    Pleo no manda webhooks de gastos, así que este cron es lo que hace que la importación sea
    AUTOMÁTICA. Recomendado cada 30-60 minutos.
    """
    expected = (settings.PLEO_CRON_KEY or settings.CHARTMETRIC_CRON_KEY or "").strip()
    key = (request.args.get("key") or "").strip()
    if not expected or key != expected:
        return ("forbidden", 403)
    try:
        window = int(request.args.get("dias") or 0) or None
    except (TypeError, ValueError):
        window = None
    try:
        out = _pleo_sync_all(window_days=window)
    except Exception as exc:
        app.logger.exception("[pleo] cron falló")
        return (jsonify({"ok": False, "error": str(exc)}), 500)
    return jsonify({"ok": True, **out})


