# ==================== FACTURAS IMPUTADAS A GASTOS DE LA BOLSA ====================
# Una factura puede cubrir VARIOS gastos y un gasto puede necesitar varias facturas. La relación
# vive en `bag_expense_invoices` con el importe imputado a cada gasto; las filas de la misma
# factura física comparten `group_key`.

def _bag_expense_invoice_apply(session_db, expense, *, file_url, file_name=None, file_mime=None,
                               invoice_number=None, amount=None, group_key=None,
                               supplier_invoice_id=None, personal_expense_id=None):
    """Imputa una factura a UN gasto. Devuelve la fila creada."""
    row = BagExpenseInvoice(
        bag_expense_id=expense.id,
        group_key=(group_key or uuid.uuid4().hex),
        supplier_invoice_id=supplier_invoice_id,
        personal_expense_id=personal_expense_id,
        file_url=file_url,
        file_name=(file_name or "")[:200] or None,
        file_mime=file_mime,
        invoice_number=(invoice_number or "")[:80] or None,
        amount=_money_or_zero(amount),
    )
    session_db.add(row)
    # El adjunto del gasto sigue apuntando a la factura, para que todo lo que ya lo lee (validación,
    # PDF de la bolsa, avisos) siga funcionando igual.
    expense.attachment_url = file_url
    expense.attachment_name = row.file_name
    expense.attachment_mime = file_mime
    if row.invoice_number:
        expense.invoice_number = row.invoice_number
    if (getattr(expense, "consolidation_status", "") or "").upper() not in BAG_CONSOLIDATED_STATUSES:
        expense.consolidation_status = "PENDIENTE_VALIDAR"
    return row


def _bag_expense_invoice_rows(session_db, expense_id) -> list[dict]:
    """Facturas imputadas a un gasto, para enseñarlas en la bolsa."""
    rows = (session_db.query(BagExpenseInvoice)
            .filter(BagExpenseInvoice.bag_expense_id == expense_id)
            .order_by(BagExpenseInvoice.created_at.asc()).all())
    out = []
    for r in rows:
        shared = (session_db.query(func.count(BagExpenseInvoice.id))
                  .filter(BagExpenseInvoice.group_key == r.group_key).scalar() or 1)
        out.append({
            "id": str(r.id), "url": r.file_url, "name": r.file_name or "Factura",
            "invoice_number": r.invoice_number or "", "amount": float(_money_or_zero(r.amount)),
            "shared_with": max(int(shared) - 1, 0),   # a cuántos gastos MÁS cubre esta misma factura
        })
    return out


def _personal_expense_allocated(session_db, personal_expense_id) -> Decimal:
    """Cuánto de un gasto importado ya se ha imputado a gastos de bolsa."""
    total = (session_db.query(func.coalesce(func.sum(BagExpenseInvoice.amount), 0))
             .filter(BagExpenseInvoice.personal_expense_id == personal_expense_id).scalar())
    return _money_or_zero(total)


@app.post('/bolsas/<bag_id>/gastos-importados/<expense_id>/vincular/<target_id>', endpoint='bag_imported_expense_link')
@admin_required
def bag_imported_expense_link(bag_id, expense_id, target_id):
    """Vincula un gasto importado (una factura que llegó a «Mis gastos») a un gasto YA EXISTENTE
    de la bolsa, en vez de crear uno nuevo.

    Si la factura vale MÁS que el gasto al que se suelta, no se decide por el usuario: se le
    devuelve la situación para que elija entre subir el importe del gasto o repartir la factura
    entre varios gastos. Con `mode`:
      - (vacío)        → solo pregunta si hace falta decidir; si cuadra, imputa y termina.
      - update_amount  → el gasto pasa a valer lo que la factura.
      - split          → imputa al gasto lo que le corresponde y deja el resto pendiente para
                         soltarlo en otro gasto, hasta repartirlo todo.
    """
    session_db = db()
    try:
        bag = session_db.get(WorkflowBag, to_uuid(bag_id) or uuid.uuid4())
        row = session_db.get(PersonalExpense, to_uuid(expense_id) or uuid.uuid4())
        target = session_db.get(BagExpense, to_uuid(target_id) or uuid.uuid4())
        if not bag or not row or not target or target.bag_id != bag.id:
            return jsonify({"ok": False, "error": "No encontrado"}), 404
        if not row.file_url:
            return jsonify({"ok": False, "error": "Este gasto no trae ninguna factura que vincular."}), 400

        total = _money_or_zero(row.amount_gross)
        ya = _personal_expense_allocated(session_db, row.id)
        pendiente = total - ya
        if pendiente <= 0:
            return jsonify({"ok": False, "error": "Esta factura ya está repartida del todo."}), 400
        hueco = _money_or_zero(target.amount_gross)
        mode = (request.form.get("mode") or "").strip().lower()

        # Si sobra factura para ese gasto y aún no se ha decidido qué hacer, se pregunta.
        if mode not in ("update_amount", "split") and hueco and pendiente > hueco:
            return jsonify({
                "ok": True, "needs_decision": True,
                "pending": float(pendiente), "expense_amount": float(hueco),
                "expense_concept": (target.concept or "Gasto"),
                "rest": float(pendiente - hueco),
            })

        if mode == "update_amount" or not hueco:
            # El gasto pasa a valer lo que queda de factura (o toda, si no tenía importe).
            imputado = pendiente
            target.amount_gross = pendiente
            if _money_or_zero(target.amount_net) == 0:
                target.amount_net = pendiente
        else:
            # Reparto: a este gasto le entra como mucho lo que vale.
            imputado = min(pendiente, hueco)

        group_key = None
        prev = (session_db.query(BagExpenseInvoice)
                .filter(BagExpenseInvoice.personal_expense_id == row.id).first())
        if prev:
            group_key = prev.group_key
        _bag_expense_invoice_apply(
            session_db, target, file_url=row.file_url, file_name=row.original_name,
            file_mime=getattr(row, "mime_type", None), invoice_number=row.invoice_number,
            amount=imputado, group_key=group_key,
            supplier_invoice_id=getattr(row, "supplier_invoice_id", None), personal_expense_id=row.id,
        )
        session_db.flush()
        restante = total - _personal_expense_allocated(session_db, row.id)
        if restante <= 0:
            row.status = "ASSIGNED"
            row.bag_expense_id = target.id
        session_db.commit()
        return jsonify({
            "ok": True, "needs_decision": False,
            "applied": float(imputado), "remaining": float(max(restante, Decimal("0"))),
            "done": restante <= 0, "expense_id": str(target.id),
        })
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("bag_imported_expense_link")
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        session_db.close()


@app.post('/bolsas/<bag_id>/gastos-importados/<expense_id>/tipificar', endpoint='bag_imported_expense_assign')
@admin_required
def bag_imported_expense_assign(bag_id, expense_id):
    """Tipifica un gasto importado dentro de la bolsa: crea su BagExpense en la categoría elegida."""
    session_db = db()
    try:
        bag = session_db.get(WorkflowBag, to_uuid(bag_id) or uuid.uuid4())
        row = session_db.get(PersonalExpense, to_uuid(expense_id) or uuid.uuid4())
        if not bag or not row:
            return jsonify({"ok": False, "error": "No encontrado"}), 404
        category = (request.form.get("category") or "").strip().upper()
        if category not in dict(BAG_EXPENSE_CATEGORIES):
            return jsonify({"ok": False, "error": "Categoría no válida"}), 400
        gross = _money_or_zero(row.amount_gross)
        net = _money_or_zero(row.amount_net) or gross
        tax = _money_or_zero(getattr(row, "amount_tax", None))
        if not tax and gross and net and gross >= net:
            tax = gross - net
        # ⚠️ REPARTO: si esta factura ya se imputó en parte a otros gastos (se soltó encima de uno y
        # se eligió «repartir»), aquí solo entra lo que QUEDA. Si no se descontara, el importe se
        # contaría dos veces en la bolsa (una en el gasto al que se imputó y otra completa aquí).
        ya_imputado = _personal_expense_allocated(session_db, row.id)
        if ya_imputado > 0:
            resto = gross - ya_imputado
            if resto <= 0:
                return jsonify({"ok": False, "error": "Esta factura ya está repartida por completo "
                                                     "entre otros gastos de la bolsa."}), 400
            # El neto y el IVA se ajustan a la misma proporción que el importe que queda.
            proporcion = (resto / gross) if gross else Decimal("0")
            net = (net * proporcion).quantize(Decimal("0.01"))
            tax = (resto - net) if resto >= net else Decimal("0")
            gross = resto
        is_pleo = (row.source or "") == "PLEO"
        # El tipo de documento lo trae Pleo (FACTURA si tiene los datos fiscales del proveedor).
        doc_type = (getattr(row, "document_type", "") or "").upper()
        if doc_type not in {"FACTURA", "TICKET"}:
            doc_type = "FACTURA" if (row.source or "") == "INVOICE" else "TICKET"
        expense = BagExpense(
            bag_id=bag.id, category=category,
            concept=(row.concept or "Gasto importado"),
            document_type=doc_type,
            invoice_number=row.invoice_number,
            issue_date=row.expense_date,
            amount_net=net, amount_gross=gross,
            amount_tax=tax,
            attachment_url=row.file_url, attachment_name=row.original_name,
            consolidation_status=("PENDIENTE_VALIDAR" if row.file_url else "PENDIENTE"),
        )
        # Todo lo que viene de PLEO ya está pagado (con la tarjeta Pleo): entra marcado como PAGADO
        # y con «Pleo» como método de pago, para que no se reclame ni se vuelva a pagar.
        if is_pleo:
            expense.payment_status = "PAGADO"
            expense.paid_amount = gross
            expense.payment_method = "Pleo"
        session_db.add(expense)
        session_db.flush()
        # Se anota la imputación de esta factura a este gasto: así el «ya imputado» del reparto
        # sigue cuadrando si la misma factura se reparte entre más gastos.
        if row.file_url:
            _bag_expense_invoice_apply(
                session_db, expense, file_url=row.file_url, file_name=row.original_name,
                file_mime=getattr(row, "file_mime", None), invoice_number=row.invoice_number,
                amount=gross, personal_expense_id=row.id,
            )
        if is_pleo and gross:
            # Queda el rastro del pago para que en la bolsa se vea cuándo y cómo se pagó.
            session_db.add(BagPaymentInteraction(
                expense_id=expense.id, kind="PAGO_REGISTRADO",
                description="Pagado con la tarjeta Pleo (importado de Pleo).",
                amount=gross, method="Pleo",
            ))
        row.bag_id = bag.id
        row.bag_expense_id = expense.id
        row.status = "ASSIGNED"
        row.updated_at = _now_madrid()
        session_db.commit()
        if request.form.get("ajax"):
            return jsonify({"ok": True, "expense_id": str(expense.id), "category": category})
        flash("Gasto añadido a la bolsa.", "success")
        return redirect(safe_next_or(url_for("bag_detail_view", bag_id=bag.id)))
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        session_db.close()


@app.post('/bolsas/<bag_id>/cargar-plantillas', endpoint='bag_load_templates')
@admin_required
def bag_load_templates(bag_id):
    """Carga una o VARIAS plantillas de gastos (del artista y/o del recinto) en la bolsa."""
    session_db = db()
    try:
        bag = session_db.get(WorkflowBag, to_uuid(bag_id))
        if not bag:
            flash("Bolsa no encontrada.", "warning")
            return redirect(url_for("bags_view"))
        ids = [x for x in request.form.getlist("expense_template_ids[]") if (x or "").strip()]
        if not ids:
            flash("Elige al menos una plantilla de gastos.", "warning")
            return redirect(safe_next_or(url_for("bag_detail_view", bag_id=bag.id)))
        added = 0
        names = []
        for tid in ids:
            tpl = session_db.get(ExpenseTemplate, to_uuid(tid) or uuid.uuid4())
            if not tpl:
                continue
            added += _bag_load_expense_template(session_db, bag, tpl)
            names.append(tpl.name or "Plantilla")
        session_db.commit()
        if added:
            flash(f"Cargados {added} gastos de {', '.join(names)}.", "success")
        else:
            flash("Las plantillas elegidas no tenían gastos.", "warning")
        return redirect(safe_next_or(url_for("bag_detail_view", bag_id=bag.id)))
    except Exception as exc:
        session_db.rollback()
        flash(f"Error cargando plantillas: {exc}", "danger")
        return redirect(safe_next_or(url_for("bag_detail_view", bag_id=bag_id)))
    finally:
        session_db.close()


# ---------------------------------------------------------------------------
#  MIS GASTOS · facturas recibidas por el formulario y gastos de Pleo que una
#  persona todavía no ha asignado a una bolsa. Plazo de 1 semana; a los 15 días
#  se escala a dirección (no aplica a dirección).
# ---------------------------------------------------------------------------

EXPENSE_ASSIGN_DAYS = 7          # plazo para asignar un gasto a una bolsa
EXPENSE_ESCALATE_DAYS = 15       # a partir de aquí se avisa a dirección

# --- PARAR EL PLAZO -------------------------------------------------------------------------
# El plazo se puede PARAR por persona (`UserProfile.expense_deadline_paused`) o para TODO el
# personal a la vez (ajuste global, mismas claves que el «modo trabajo»). Mientras está parado:
# no corre la cuenta atrás, no se reclama por correo y no se escala a dirección.
# Los tramos parados se guardan para DESCONTARLOS del plazo al reanudar; si no, al volver a
# activarlo todos los gastos aparecerían de golpe fuera de plazo.
EXPENSE_PAUSE_ALL_KEY = "expense_deadline_pause_all"
EXPENSE_PAUSE_ALL_SINCE_KEY = "expense_deadline_pause_all_since"
EXPENSE_PAUSE_ALL_LOG_KEY = "expense_deadline_pause_all_log"


def _expense_pause_parse_log(raw) -> list:
    """Tramos parados guardados: [{"from": "AAAA-MM-DD", "to": "AAAA-MM-DD"}] → [(desde, hasta)]."""
    if isinstance(raw, str):
        raw = _json_loads_safe(raw, [])
    out = []
    for item in (raw or []):
        if not isinstance(item, dict):
            continue
        try:
            desde = date.fromisoformat(str(item.get("from") or "")[:10])
        except ValueError:
            continue
        try:
            hasta = date.fromisoformat(str(item.get("to") or "")[:10])
        except ValueError:
            hasta = desde
        out.append((desde, max(hasta, desde)))
    return out


def _expense_pause_merge(tramos) -> list:
    """Une los tramos que se solapan y los corta a hoy (un tramo sin fin = sigue parado)."""
    hoy = today_local()
    limpio = []
    for desde, hasta in tramos:
        if not desde:
            continue
        fin = min(hasta or hoy, hoy)
        if fin >= desde:
            limpio.append((desde, fin))
    limpio.sort()
    out = []
    for desde, hasta in limpio:
        if out and desde <= out[-1][1]:
            out[-1] = (out[-1][0], max(out[-1][1], hasta))
        else:
            out.append((desde, hasta))
    return out


def _expense_paused_days(ref_date, ranges) -> int:
    """Días parados que caen DESPUÉS de recibirse el gasto: los que no cuentan para su plazo."""
    if not ref_date or not ranges:
        return 0
    hoy = today_local()
    total = 0
    for desde, hasta in ranges:
        ini, fin = max(desde, ref_date), min(hasta, hoy)
        if fin > ini:
            # Días COMPLETOS congelados: parar hoy no regala un día, pero parar hace 5 descuenta 5.
            total += (fin - ini).days
    return total


def _expense_pause_global() -> dict:
    """Parada GENERAL del plazo (todo el personal), guardada en los ajustes globales."""
    activa = str(_get_app_setting(EXPENSE_PAUSE_ALL_KEY, "0") or "0") == "1"
    try:
        desde = date.fromisoformat(str(_get_app_setting(EXPENSE_PAUSE_ALL_SINCE_KEY, "") or "")[:10])
    except ValueError:
        desde = None
    return {"paused": activa, "since": desde,
            "log": _expense_pause_parse_log(_get_app_setting(EXPENSE_PAUSE_ALL_LOG_KEY, "[]"))}


def _expense_pause_context(session_db, user_id, global_state=None, profile=None) -> dict:
    """Estado del plazo de UNA persona: su parada, la general, y los tramos a descontar."""
    g = global_state if global_state is not None else _expense_pause_global()
    prof = profile
    if prof is None and user_id:
        prof = (session_db.query(UserProfile)
                .filter(UserProfile.user_id == to_uuid(str(user_id))).first())
    propia = bool(getattr(prof, "expense_deadline_paused", False))
    desde_propia = getattr(prof, "expense_paused_since", None)
    tramos = list(g["log"]) + _expense_pause_parse_log(getattr(prof, "expense_pause_log", None))
    if g["paused"]:
        tramos.append((g["since"] or today_local(), None))
    if propia:
        tramos.append((desde_propia or today_local(), None))
    return {
        "paused": bool(propia or g["paused"]),
        "person_paused": propia,
        "all_paused": bool(g["paused"]),
        "since": (desde_propia if propia else None) or (g["since"] if g["paused"] else None),
        "ranges": _expense_pause_merge(tramos),
    }


def _expense_days_left(row, pause=None) -> int:
    """Días que quedan para asignarlo (negativo = ya pasado el plazo).

    Los días en los que el plazo estuvo PARADO no cuentan.
    """
    ref = getattr(row, "received_at", None) or getattr(row, "created_at", None)
    if not ref:
        return EXPENSE_ASSIGN_DAYS
    try:
        ref_date = ref.date() if hasattr(ref, "date") else ref
    except Exception:
        return EXPENSE_ASSIGN_DAYS
    transcurrido = (today_local() - ref_date).days
    transcurrido -= _expense_paused_days(ref_date, (pause or {}).get("ranges") or [])
    return EXPENSE_ASSIGN_DAYS - max(transcurrido, 0)


def _personal_expense_row(row, pause=None) -> dict:
    days = _expense_days_left(row, pause)
    parado = bool((pause or {}).get("paused"))
    # En Cabify el proveedor ES Cabify y el nº de venta no dice nada a quien asigna el gasto: la
    # línea de datos se queda en «Cabify · fecha» (+ trayecto en el concepto y la etiqueta del viaje).
    es_cabify = (row.source or "") == "CABIFY"
    is_pleo = (row.source or "") == "PLEO"
    # Etiquetas y nota de Pleo: NO clasifican nada, se muestran para que asignar el gasto a su
    # bolsa y tipificarlo sea más fácil (a menudo la nota dice el concierto o el artista).
    tags = []
    for t in (getattr(row, "pleo_tags", None) or []):
        if not isinstance(t, dict):
            continue
        value = (t.get("value") or "").strip()
        if not value:
            continue
        tags.append({"group": (t.get("group") or "").strip(), "value": value})
    files = [f for f in (getattr(row, "pleo_files", None) or []) if isinstance(f, dict) and f.get("url")]
    cat = (getattr(row, "suggested_category", "") or "").upper()
    return {
        "id": str(row.id),
        "source": (row.source or "INVOICE"),
        "source_label": {"PLEO": "Pleo", "INVOICE": "Factura recibida",
                         "CABIFY": "Cabify"}.get((row.source or ""), "Gasto"),
        "source_icon": {"PLEO": "fa-credit-card", "INVOICE": "fa-file-invoice-dollar",
                        "CABIFY": "fa-taxi"}.get((row.source or ""), "fa-receipt"),
        "concept": (row.concept or "Gasto"),
        "provider_name": ("" if es_cabify else (row.provider_name or "")),
        "invoice_number": ("" if es_cabify else (row.invoice_number or "")),
        "date_label": (row.expense_date.strftime("%d/%m/%Y") if row.expense_date else ""),
        "amount_gross": _money_or_zero(row.amount_gross),
        "file_url": (row.file_url or ""),
        "status": (row.status or "PENDING"),
        "bag_id": (str(row.bag_id) if row.bag_id else ""),
        "days_left": days,
        "overdue": days < 0 and not parado,
        "urgent": 0 <= days <= EXPENSE_ASSIGN_DAYS and not parado,
        # Plazo parado: no hay cuenta atrás ni «fuera de plazo» (se dice por qué).
        "deadline_paused": parado,
        "deadline_paused_label": ("Plazo parado para todos" if (pause or {}).get("all_paused")
                                 else "Plazo parado" if parado else ""),
        # --- Pleo ---
        "is_pleo": is_pleo,
        "note": (getattr(row, "pleo_note", "") or ""),
        "tags": tags,
        "files": files,
        "currency": (getattr(row, "currency", "") or "EUR"),
        "document_type": (getattr(row, "document_type", "") or ""),
        "needs_receipt": bool(getattr(row, "needs_receipt", False)) and is_pleo,
        "sync_warning": (getattr(row, "sync_warning", "") or ""),
        "is_cancelled": bool(getattr(row, "is_cancelled", False)),
        "suggested_category": cat,
        "suggested_label": BAG_EXPENSE_CATEGORY_LABELS.get(cat, ""),
        "suggested_icon": BAG_EXPENSE_CATEGORY_ICONS.get(cat, "fa-shapes"),
        "paid_label": ("Pagado con Pleo" if is_pleo else ""),
        # --- Justificante y gastos DIRECTOS (oficina / inversión de artista) ---
        "justification": _personal_expense_justification_state(row),
        "can_go_direct": _personal_expense_has_justification(row),
        "direct_target": ((getattr(row, "direct_target", "") or "").upper()),
        "direct_target_label": PERSONAL_DIRECT_TARGETS.get(
            (getattr(row, "direct_target", "") or "").upper(), ("", ""))[0],
        "direct_target_icon": PERSONAL_DIRECT_TARGETS.get(
            (getattr(row, "direct_target", "") or "").upper(), ("", "fa-receipt"))[1],
        "direct_artist_id": (str(row.direct_artist_id) if getattr(row, "direct_artist_id", None) else ""),
        "validation_status": ((getattr(row, "validation_status", "") or "").upper()),
        "validation_note": (getattr(row, "validation_note", "") or ""),
        "no_invoice_reason": (getattr(row, "no_invoice_reason", "") or ""),
        "no_invoice_status": ((getattr(row, "no_invoice_status", "") or "").upper()),
        "payment_status": ((getattr(row, "payment_status", "") or "NO_PAGADO").upper()),
        "prepaid": _personal_expense_is_prepaid(row),
    }


# ================== GASTOS DIRECTOS: de OFICINA o INVERSIÓN en un ARTISTA ==================
# Son gastos que NO van contra ninguna bolsa. Se mandan desde «Mis gastos» arrastrándolos a la
# primera tarjeta de la pantalla de asignar (partida en dos), y los tiene que VALIDAR
# administración. Requisito para mandarlos: llevar factura/ticket, o que administración haya
# aceptado que no lo lleva (mismo trato que el «sin ticket» de los gastos de bolsa).
PERSONAL_DIRECT_TARGETS = {
    "OFICINA": ("Gasto de oficina", "fa-building-columns"),
    "ARTIST_INVESTMENT": ("Inversión de artista", "fa-arrow-trend-up"),
}


def _personal_expense_has_justification(row) -> bool:
    """¿Se puede mandar a validar? Lleva factura/ticket o el «sin factura» está APROBADO."""
    if (getattr(row, "file_url", None) or "").strip():
        return True
    return (getattr(row, "no_invoice_status", None) or "").upper() == "APROBADO"


def _personal_expense_is_prepaid(row) -> bool:
    """Lo de Pleo y Cabify ya está pagado con la tarjeta de empresa: no genera pendiente de pago."""
    return (getattr(row, "source", "") or "").upper() in ("PLEO", "CABIFY")


def _personal_expense_justification_state(row) -> dict:
    """Semáforo del justificante, para pintar el icono en «Mis gastos» y en la pantalla de asignar."""
    if (getattr(row, "file_url", None) or "").strip():
        tipo = (getattr(row, "document_type", "") or "").upper()
        return {"ok": True, "key": "FILE", "icon": "fa-file-invoice",
                "label": ("Ticket adjunto" if tipo == "TICKET" else "Factura adjunta")}
    estado = (getattr(row, "no_invoice_status", None) or "").upper()
    if estado == "APROBADO":
        return {"ok": True, "key": "NO_INVOICE_OK", "icon": "fa-file-circle-check",
                "label": "Validado sin factura"}
    if estado == "SOLICITADO":
        return {"ok": False, "key": "NO_INVOICE_WAIT", "icon": "fa-file-circle-question",
                "label": "Sin factura, pendiente de que administración lo acepte"}
    if estado == "RECHAZADO":
        return {"ok": False, "key": "NO_INVOICE_KO", "icon": "fa-file-circle-xmark",
                "label": "Administración no aceptó que fuera sin factura"}
    return {"ok": False, "key": "NONE", "icon": "fa-file-circle-xmark",
            "label": "Sin factura ni ticket"}


def _personal_direct_expenses_pending(session_db) -> list[dict]:
    """Gastos directos PENDIENTES de validar por administración (oficina e inversión de artista)."""
    rows = (session_db.query(PersonalExpense)
            .filter(PersonalExpense.status == "VALIDATING")
            .filter(func.upper(func.coalesce(PersonalExpense.validation_status, "")) == "PENDIENTE")
            .order_by(PersonalExpense.validation_requested_at.asc().nullslast()).all())
    out = []
    for r in rows:
        artista = session_db.get(Artist, r.direct_artist_id) if r.direct_artist_id else None
        prof = session_db.query(UserProfile).filter(UserProfile.user_id == r.user_id).first()
        etiqueta, icono = PERSONAL_DIRECT_TARGETS.get((r.direct_target or "").upper(),
                                                      ("Gasto directo", "fa-receipt"))
        out.append({
            "id": str(r.id), "concept": (r.concept or "Gasto"),
            "provider_name": (r.provider_name or ""),
            "amount_gross": _money_or_zero(r.amount_gross),
            "date_label": (r.expense_date.strftime("%d/%m/%Y") if r.expense_date else ""),
            "file_url": (r.file_url or ""),
            "justification": _personal_expense_justification_state(r),
            "target": (r.direct_target or "").upper(), "target_label": etiqueta, "target_icon": icono,
            "artist_name": (getattr(artista, "name", "") or ""),
            "artist_photo": (getattr(artista, "photo_url", "") or ""),
            "person": ((prof.nick if prof else "") or "").strip() or "Alguien",
            "prepaid": _personal_expense_is_prepaid(r),
        })
    return out


def _personal_no_invoice_pending(session_db) -> list[dict]:
    """Gastos personales cuyo dueño pide que se acepten SIN factura."""
    rows = (session_db.query(PersonalExpense)
            .filter(func.upper(func.coalesce(PersonalExpense.no_invoice_status, "")) == "SOLICITADO")
            .order_by(PersonalExpense.updated_at.desc().nullslast()).all())
    out = []
    for r in rows:
        prof = session_db.query(UserProfile).filter(UserProfile.user_id == r.user_id).first()
        out.append({
            "id": str(r.id), "concept": (r.concept or "Gasto"),
            "provider_name": (r.provider_name or ""),
            "amount_gross": _money_or_zero(r.amount_gross),
            "date_label": (r.expense_date.strftime("%d/%m/%Y") if r.expense_date else ""),
            "reason": (r.no_invoice_reason or ""),
            "person": ((prof.nick if prof else "") or "").strip() or "Alguien",
        })
    return out


def _personal_direct_expenses_payable(session_db) -> list[dict]:
    """Gastos directos ya validados y sin pagar (los de Pleo/Cabify ya están pagados)."""
    rows = (session_db.query(PersonalExpense)
            .filter(PersonalExpense.status == "DIRECT")
            .filter(func.upper(func.coalesce(PersonalExpense.validation_status, "")) == "APROBADO")
            .filter(func.upper(func.coalesce(PersonalExpense.payment_status, "NO_PAGADO")) != "PAGADO")
            .order_by(PersonalExpense.validated_at.asc().nullslast()).all())
    out = []
    for r in rows:
        if _personal_expense_is_prepaid(r):
            continue
        artista = session_db.get(Artist, r.direct_artist_id) if r.direct_artist_id else None
        etiqueta, icono = PERSONAL_DIRECT_TARGETS.get((r.direct_target or "").upper(),
                                                      ("Gasto directo", "fa-receipt"))
        prof = session_db.query(UserProfile).filter(UserProfile.user_id == r.user_id).first()
        out.append({
            "id": str(r.id), "concept": (r.concept or "Gasto"),
            "provider_name": (r.provider_name or ""),
            "amount_gross": _money_or_zero(r.amount_gross),
            "date_label": (r.expense_date.strftime("%d/%m/%Y") if r.expense_date else ""),
            "file_url": (r.file_url or ""),
            "target_label": etiqueta, "target_icon": icono,
            "artist_name": (getattr(artista, "name", "") or ""),
            "person": ((prof.nick if prof else "") or "").strip() or "Alguien",
        })
    return out


def _artist_investment_rows(session_db, artist_id) -> dict:
    """Balance de gasto de INVERSIÓN de un artista: los gastos directos validados que se le han
    imputado. Es lo que se enseña en su ficha."""
    aid = to_uuid(str(artist_id)) if artist_id else None
    if not aid:
        return {"rows": [], "total": Decimal("0")}
    rows = (session_db.query(PersonalExpense)
            .filter(PersonalExpense.direct_artist_id == aid)
            .filter(PersonalExpense.status == "DIRECT")
            .filter(func.upper(func.coalesce(PersonalExpense.validation_status, "")) == "APROBADO")
            .order_by(PersonalExpense.expense_date.desc().nullslast()).all())
    out, total = [], Decimal("0")
    for r in rows:
        importe = _money_or_zero(r.amount_gross)
        total += importe
        prof = session_db.query(UserProfile).filter(UserProfile.user_id == r.user_id).first()
        out.append({
            "id": str(r.id), "concept": (r.concept or "Gasto"),
            "provider_name": (r.provider_name or ""),
            "date_label": (r.expense_date.strftime("%d/%m/%Y") if r.expense_date else ""),
            "amount_gross": importe,
            "file_url": (r.file_url or ""),
            "person": ((prof.nick if prof else "") or "").strip() or "",
            "paid": (r.payment_status or "").upper() == "PAGADO" or _personal_expense_is_prepaid(r),
        })
    # Lo gastado en PROMOCIÓN también es inversión en el artista: todo lo que se le imputa aparece
    # aquí, aunque además se vea en la ficha del single o del disco que se promocionaba (allí es el
    # mismo dinero visto desde otro sitio; el total de cada pantalla cuenta cada gasto UNA vez).
    promo = _promo_spend_rows(session_db, artist_id=aid)
    for row in promo.get("rows") or []:
        total += row["amount_gross"]
        out.append({
            "id": row["id"],
            "concept": f"Promoción · {row['title']}" + (f" ({row['subject_label']})" if row.get("subject_label") else ""),
            "provider_name": "",
            "date_label": row["date_label"],
            "amount_gross": row["amount_gross"],
            "file_url": "",
            "person": "",
            "paid": True,
            "promo_url": row["detail_url"],
        })
    return {"rows": out, "total": total}


def _user_is_direccion(session_db, user_id) -> bool:
    """Dirección «pura»: role 10 (la regla de plazos no les aplica)."""
    try:
        u = session_db.get(User, to_uuid(str(user_id)))
        return bool(u) and int(getattr(u, "role", 0) or 0) == 10
    except Exception:
        return False


def _personal_expenses_for(session_db, user_id, status=("PENDING",)) -> list:
    uid = to_uuid(str(user_id)) if user_id else None
    if not uid:
        return []
    q = (session_db.query(PersonalExpense)
         .filter(PersonalExpense.user_id == uid))
    if status:
        q = q.filter(PersonalExpense.status.in_(list(status)))
    pause = _expense_pause_context(session_db, uid)
    return [_personal_expense_row(r, pause) for r in q.order_by(PersonalExpense.received_at.asc()).all()]


def _open_bags_for_user(session_db, user_id, artist_query: str = "") -> list:
    """Bolsas NO cerradas agrupadas por artista, ordenadas por proximidad de la actividad.
    Por defecto las del usuario (sus artistas asignados); con `artist_query` busca otras."""
    closed = {"CERRADA", "LIQUIDADA", "ARCHIVADA"}
    bags = (session_db.query(WorkflowBag)
            .filter(WorkflowBag.is_archived == False)     # noqa: E712
            .order_by(WorkflowBag.start_date.desc().nullslast())
            .all())
    assigned_ids = set()
    if user_id and not _user_is_direccion(session_db, user_id):
        prof = session_db.query(UserProfile).filter(UserProfile.user_id == to_uuid(str(user_id))).first()
        assigned_ids = {str(x) for x in ((getattr(prof, "assigned_artist_ids", None) or []) if prof else [])}
    want = _norm_text_key(artist_query or "")
    groups = {}
    for bag in bags:
        if (bag.status or "").upper() in closed:
            continue
        artists = _bag_artist_rows(session_db, bag)
        art = artists[0] if artists else None
        aid = str(art.id) if art else ""
        art_name = (art.name if art else "Sin artista")
        if want:
            if want not in _norm_text_key(art_name):
                continue
        elif assigned_ids and aid and aid not in assigned_ids:
            continue
        g = groups.setdefault(aid or "sin", {
            "artist_id": aid, "artist_name": art_name,
            "artist_photo": ((getattr(art, "photo_url", "") or "") if art else ""),
            "bags": [],
        })
        g["bags"].append({
            "id": str(bag.id),
            "title": (bag.title or "Bolsa"),
            "date": bag.start_date,
            "date_label": (bag.start_date.strftime("%d/%m/%Y") if bag.start_date else ""),
            "linked_title": (bag.linked_title or ""),
            "status": (bag.status or ""),
        })
    out = list(groups.values())
    today = date.today()
    for g in out:
        g["bags"].sort(key=lambda b: abs((b["date"] - today).days) if b["date"] else 99999)
        g["next_date"] = g["bags"][0]["date"] if g["bags"] and g["bags"][0]["date"] else None
    out.sort(key=lambda g: abs((g["next_date"] - today).days) if g["next_date"] else 99999)
    return out


def _bag_expense_has_invoice(expense) -> bool:
    """¿Este gasto ya tiene su factura/justificante subido? (o está justificado sin factura)."""
    if (getattr(expense, "attachment_url", None) or "").strip():
        return True
    if (getattr(expense, "no_invoice_reason", None) or "").strip():
        return True
    return (getattr(expense, "consolidation_status", "") or "").upper() in BAG_CONSOLIDATED_STATUSES


def _bag_providers_pending_invoice(session_db, bag) -> list[dict]:
    """Proveedores de la bolsa con conceptos SIN factura subida, con sus importes."""
    expenses = (session_db.query(BagExpense)
                .options(joinedload(BagExpense.provider))
                .filter(BagExpense.bag_id == bag.id, BagExpense.status != "ELIMINADO")
                .order_by(BagExpense.category.asc(), BagExpense.sort_order.asc())
                .all())
    by_provider = {}
    for exp in expenses:
        if _bag_expense_has_invoice(exp):
            continue
        provider = getattr(exp, "provider", None)
        if not provider:
            continue
        row = by_provider.setdefault(str(provider.id), {
            "provider": provider,
            "provider_id": str(provider.id),
            "name": provider.nick or "Proveedor",
            "logo_url": (provider.logo_url or ""),
            "email": (provider.contact_email or ""),
            "items": [],
            "net": Decimal("0"),
            "gross": Decimal("0"),
        })
        net = _money_or_zero(getattr(exp, "amount_net", 0))
        gross = _money_or_zero(getattr(exp, "amount_gross", 0)) or net
        row["items"].append({
            "id": str(exp.id),
            "concept": (exp.concept or "Gasto"),
            "category": _bag_expense_display_cat(getattr(exp, "category", "OTROS")),
            "net": net,
            "gross": gross,
        })
        row["net"] += net
        row["gross"] += gross
    rows = list(by_provider.values())
    rows.sort(key=lambda r: r["name"].lower())
    return rows


