@app.post('/conciertos/<cid>/produccion/presupuesto/cargar-plantilla', endpoint='concert_budget_load_template')
@admin_required
def concert_budget_load_template(cid):
    """Carga un presupuesto guardado del ARTISTA (ExpenseTemplate) como partidas del presupuesto
    del concierto (ConcertBudgetItem), igual que en los simuladores."""
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(cid))
        if not concert:
            abort(404)
        # Acepta VARIAS plantillas (del artista y/o del recinto), igual que la bolsa.
        ids = [x for x in request.form.getlist('expense_template_ids[]') if (x or '').strip()]
        single = (request.form.get('template_id') or '').strip()
        if single:
            ids.append(single)
        tpls = []
        for tid in ids:
            tpl = (session_db.query(ExpenseTemplate).options(selectinload(ExpenseTemplate.items))
                   .filter(ExpenseTemplate.id == to_uuid(tid)).first()) if to_uuid(tid) else None
            if tpl:
                tpls.append(tpl)
        if not tpls:
            flash('Elige al menos una plantilla de gastos.', 'warning')
            return redirect(safe_next_or(url_for('concert_detail_view', cid=cid, tab='produccion', ptab='presupuesto')))
        uid = _safe_uuid(session.get('user_id')) if session.get('user_id') else None
        nick = _email_to_nick(_current_user_email() or '')
        n = 0
        for tpl in tpls:
            for it in sorted(tpl.items or [], key=lambda x: x.sort_order or 0):
                cat = _bag_expense_display_cat((it.category or 'OTROS').upper())
                qty = _money_or_zero(getattr(it, 'quantity', 1) or 1)
                if qty <= 0:
                    qty = Decimal('1')
                unit = _money_or_zero(it.amount_net)
                iva_exempt = bool(getattr(it, 'iva_exempt', False))
                iva_pct = Decimal('0') if iva_exempt else _money_or_zero(getattr(it, 'iva_pct', 21))
                iva_rate = iva_pct / Decimal('100')
                divisor = (Decimal('1') + iva_rate) if (getattr(it, 'includes_iva', False) and iva_rate > 0) else Decimal('1')
                net = ((unit * qty) / divisor).quantize(Decimal('0.01'))
                gross = (net * (Decimal('1') + iva_rate)).quantize(Decimal('0.01'))
                session_db.add(ConcertBudgetItem(
                    concert_id=concert.id, category=cat, concept=(it.concept or 'Gasto'),
                    amount_net=net, amount_gross=gross, quantity=qty, iva_pct=iva_pct,
                    iva_exempt=iva_exempt, sort_order=n,
                    created_by_user_id=uid, created_by_nick=nick,
                ))
                n += 1
        session_db.commit()
        flash(f"Cargadas {n} partida{'s' if n != 1 else ''} de {', '.join(t.name or 'plantilla' for t in tpls)}.", 'success')
        return redirect(safe_next_or(url_for('concert_detail_view', cid=cid, tab='produccion', ptab='presupuesto')))
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo cargar el presupuesto: {exc}', 'danger')
        return redirect(safe_next_or(url_for('concert_detail_view', cid=cid, tab='produccion', ptab='presupuesto')))
    finally:
        session_db.close()


@app.post('/conciertos/<cid>/produccion/presupuesto/<item_id>/mover', endpoint='concert_budget_item_move')
@admin_required
def concert_budget_item_move(cid, item_id):
    """Cambia la categoría de una partida del presupuesto (arrastrar entre bocadillos)."""
    session_db = db()
    try:
        item = session_db.get(ConcertBudgetItem, to_uuid(item_id) or uuid.uuid4())
        if not item or str(item.concert_id) != str(to_uuid(cid)):
            return jsonify({"ok": False, "error": "Partida no encontrada"}), 404
        cat = (request.form.get('category') or '').strip().upper()
        if cat not in SIM_EXPENSE_CATEGORY_LABELS:
            return jsonify({"ok": False, "error": "Categoría no válida"}), 400
        item.category = cat
        session_db.commit()
        if request.form.get('ajax'):
            return jsonify({"ok": True, "category": cat})
        return redirect(safe_next_or(url_for('concert_detail_view', cid=cid, tab='produccion', ptab='presupuesto')))
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        session_db.close()


@app.post('/conciertos/<cid>/ticketing/formato', endpoint='concert_seat_map_save')
@admin_required
def concert_seat_map_save(cid):
    """Qué FORMATO del recinto usa esta actividad. De él dependen el casado de las invitaciones, el
    asignador sobre el plano y el plano en vivo de Enterticket."""
    if not can_edit_concerts():
        return forbid('No tienes permisos para cambiar el formato del recinto.')
    next_url = safe_next_or(request.form.get('next') or url_for('concert_detail_view', cid=cid, tab='ticketing'))
    session_db = db()
    try:
        c = session_db.get(Concert, to_uuid(cid))
        if c is None:
            flash('Actividad no encontrada.', 'warning')
            return redirect(url_for('concerts_view'))
        raw = (request.form.get('seat_map_id') or '').strip()
        if not raw:
            c.seat_map_id = None
            flash('La actividad usará el formato principal del recinto.', 'success')
        else:
            sm = session_db.get(VenueSeatMap, to_uuid(raw))
            if sm is None or str(sm.venue_id) != str(c.venue_id or ''):
                flash('Ese formato no es de este recinto.', 'warning')
                return redirect(next_url)
            c.seat_map_id = sm.id
            flash('Formato «%s» asignado a esta actividad.' % (sm.name or 'Principal'), 'success')
        session_db.commit()
    except Exception as exc:
        session_db.rollback()
        flash('No se pudo guardar el formato: %s' % exc, 'danger')
    finally:
        session_db.close()
    return redirect(next_url)


@app.post('/conciertos/<cid>/ticketing/cargar-recinto', endpoint='concert_ticketing_load_venue')
@admin_required
def concert_ticketing_load_venue(cid):
    """Precarga las categorías de invitación del concierto desde la plantilla del recinto
    (VenueTicketCategory: zona + nº de invitaciones), para no configurarlas a mano."""
    session_db = db()
    try:
        c = session_db.get(Concert, to_uuid(cid))
        if not c:
            abort(404)
        if not c.venue_id:
            flash('Este concierto no tiene recinto asignado.', 'warning')
            return redirect(url_for('concert_detail_view', cid=cid, tab='ticketing'))
        # Solo el FORMATO PRINCIPAL del recinto (subpestañas de la ficha del recinto).
        cats = sorted(
            _venue_ticket_categories_for(session_db, c.venue_id, _venue_seatmap_default(session_db, c.venue_id)),
            key=lambda x: x.sort_order or 0,
        )
        existing = {(x.name or '').strip().lower() for x in session_db.query(InvitationCategory).filter(InvitationCategory.concert_id == c.id).all()}
        n = 0
        for vc in cats:
            inv = int(vc.invitations or 0)
            if inv <= 0:
                continue
            nm = (vc.name or vc.zone or 'Invitaciones').strip()
            if nm.lower() in existing:
                continue
            session_db.add(InvitationCategory(
                concert_id=c.id, name=nm, zone=((vc.zone or 'PISTA').strip().upper() if (vc.zone or '').strip().upper() in ('PISTA', 'GRADA', 'PALCO') else 'PISTA'),
                qty_contract=inv, qty_extra=0, source='TICKETING',
            ))
            existing.add(nm.lower())
            n += 1
        session_db.commit()
        if n:
            flash(f'Cargadas {n} categoría(s) de invitación del recinto.', 'success')
        else:
            flash('El recinto no tiene invitaciones por zona configuradas (o ya estaban cargadas).', 'info')
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo cargar del recinto: {exc}', 'danger')
    finally:
        session_db.close()
    return redirect(url_for('concert_detail_view', cid=cid, tab='ticketing'))


