@app.get('/recintos/<vid>', endpoint='venue_detail_view')
@admin_required
def venue_detail_view(vid):
    session_db = db()
    try:
        venue = session_db.get(Venue, to_uuid(vid))
        if not venue:
            abort(404)
        concert_rows = (
            session_db.query(Concert)
            .options(joinedload(Concert.artist), joinedload(Concert.venue))
            .filter(Concert.venue_id == venue.id)
            .order_by(Concert.date.desc().nullslast())
            .all()
        )
        action_rows = (
            session_db.query(CompanyAction)
            .options(joinedload(CompanyAction.venue))
            .filter(CompanyAction.venue_id == venue.id)
            .order_by(CompanyAction.start_date.desc().nullslast())
            .all()
        )
        activities = [_production_concert_row(session_db, row) for row in concert_rows]
        activities.extend([_action_display_row(session_db, row) for row in action_rows])
        activities.sort(key=lambda item: (item.get('date') or date.min), reverse=True)
        # Pestaña Actividad: PRÓXIMAS (la más cercana primero) y debajo las ANTERIORES.
        _today = date.today()
        activities_upcoming = sorted(
            [a for a in activities if (a.get('date') or date.min) >= _today],
            key=lambda item: (item.get('date') or date.min),
        )
        activities_past = [a for a in activities if (a.get('date') or date.min) < _today]
        _tab = (request.args.get('tab') or 'actividad').strip().lower()
        # FORMATO activo (subpestaña de Ticketing): ?map=<id> o el principal. Las categorías
        # clásicas y el mapa que se muestran/editan son SIEMPRE los del formato activo.
        _active_map = _venue_seatmap_resolve(session_db, venue.id, request.args.get('map'))
        venue_cats = _venue_ticket_categories_for(session_db, venue.id, _active_map)
        return render_template(
            'venue_detail.html',
            venue=venue,
            activities=activities,
            activities_upcoming=activities_upcoming,
            activities_past=activities_past,
            edit=_truthy(request.args.get('edit')) and can_edit_catalogs(),
            CAN_EDIT_CATALOGS=can_edit_catalogs(),
            tab=_tab,
            venue_ticketing_payload=_venue_ticketing_payload(venue_cats),
            venue_tk_summary=_venue_ticketing_summary(venue_cats),
            venue_seatmap_payload=(_venue_seatmap_payload(_active_map) if _tab == 'ticketing' else None),
            venue_seatmaps=([{'id': str(m.id), 'name': m.name or 'Principal', 'is_default': bool(m.is_default)} for m in _venue_seatmap_all(session_db, venue.id)] if _tab == 'ticketing' else []),
            venue_active_map=({'id': str(_active_map.id), 'name': _active_map.name or 'Principal', 'is_default': bool(_active_map.is_default)} if (_tab == 'ticketing' and _active_map is not None) else None),
            expense_templates=_expense_templates_for(session_db, "VENUE", venue.id),
            entity_links=_entity_link_rows(session_db, 'venue', venue.id),
            entity_link_context={'type': 'venue', 'id': str(venue.id), 'label': venue.name or 'recinto'},
            entity_link_types=APP33_ENTITY_LINK_TYPES,
            entity_links_can_edit=can_edit_catalogs(),
        )
    finally:
        session_db.close()


