@app.post("/fotos/<owner_type>/<owner_id>/upload", endpoint="fotos_upload")
@admin_required
def fotos_upload(owner_type, owner_id):
    ot = _photo_owner_type_norm(owner_type)
    if not ot:
        return jsonify({"ok": False, "error": "Tipo no válido."}), 400

    files = []
    for field in ("files", "files[]", "file", "photos[]"):
        files.extend([f for f in request.files.getlist(field) if f and getattr(f, "filename", "")])
    if not files:
        return jsonify({"ok": False, "error": "No se han recibido archivos."}), 400

    photographer_unknown = _truthy(request.form.get("photographer_unknown"))
    photographer_id = None if photographer_unknown else to_uuid(request.form.get("photographer_promoter_id"))

    state = _current_user_state()
    session_db = db()
    try:
        owner, artist_id, _title = _photo_resolve_owner(session_db, ot, owner_id)
        if not owner:
            return jsonify({"ok": False, "error": "No encontrado."}), 404

        base_order = (
            session_db.query(func.coalesce(func.max(Photo.sort_order), -1))
            .filter(Photo.owner_type == ot, Photo.owner_id == owner.id)
            .scalar()
        )
        next_order = int(base_order) + 1

        created = []
        errors = []       # [{name, reason}] — motivo CLARO por archivo (antes se tragaban)
        duplicates = []   # [{name, prev_date}] — mismo contenido ya subido a esta actividad

        # sha256 de lo YA subido a este owner (dedupe contra BD; fotos antiguas sin hash no cuentan).
        existing_shas = {
            sha: dt
            for sha, dt in session_db.query(Photo.file_sha256, Photo.created_at)
            .filter(Photo.owner_type == ot, Photo.owner_id == owner.id, Photo.file_sha256.isnot(None))
            .all()
            if sha
        }
        seen_batch = set()

        for fs in files:
            fname = fs.filename or "archivo"
            kind = _photo_kind_for_filename(fname)
            ext = os.path.splitext(fname.lower())[1]
            stored_name = fname
            stored_mime = (getattr(fs, "mimetype", "") or "").strip() or None

            # Hash del contenido ORIGINAL (detección de duplicados) sin cargarlo entero en memoria.
            file_sha = None
            try:
                fs.stream.seek(0)
                hasher = hashlib.sha256()
                while True:
                    chunk = fs.stream.read(1024 * 1024)
                    if not chunk:
                        break
                    hasher.update(chunk)
                file_sha = hasher.hexdigest()
                fs.stream.seek(0)
            except Exception:
                file_sha = None
            if file_sha and file_sha in existing_shas:
                prev = existing_shas.get(file_sha)
                try:
                    prev_txt = prev.astimezone(TZ_MADRID).strftime("%d/%m/%Y") if prev else ""
                except Exception:
                    prev_txt = prev.strftime("%d/%m/%Y") if prev else ""
                duplicates.append({"name": fname, "prev_date": prev_txt})
                continue
            if file_sha and file_sha in seen_batch:
                duplicates.append({"name": fname, "prev_date": "hoy, en este mismo lote"})
                continue
            if file_sha:
                seen_batch.add(file_sha)

            try:
                if ext in {".jpg", ".jpeg", ".png", ".webp", ".gif", ".svg"}:
                    # Formatos web estándar: validados por upload_image.
                    file_url = upload_image(fs, "photos")
                elif kind == "IMAGE":
                    # Imagen no-web (HEIC/HEIF de iPhone, BMP, TIFF…): convertir a JPEG para que
                    # se vea en el navegador. Si no se puede, se guarda el original.
                    file_url = None
                    if PILLOW_AVAILABLE:
                        try:
                            raw = fs.read()
                            img = ImageOps.exif_transpose(PILImage.open(BytesIO(raw)))
                            if img.mode not in ("RGB", "L"):
                                img = img.convert("RGB")
                            out = BytesIO()
                            img.save(out, format="JPEG", quality=90)
                            file_url = _upload_bytes(out.getvalue(), "photos/%s.jpg" % uuid.uuid4().hex, "image/jpeg")
                            stored_name = (os.path.splitext(fname)[0] or "foto") + ".jpg"
                            stored_mime = "image/jpeg"
                        except Exception:
                            file_url = None
                    if not file_url:
                        try:
                            fs.stream.seek(0)
                        except Exception:
                            pass
                        file_url = upload_file(fs, "photos", allowed_extensions=(PHOTO_IMAGE_EXTS | PHOTO_VIDEO_EXTS))
                else:
                    # Vídeos y demás: se almacenan tal cual.
                    file_url = upload_file(fs, "photos", allowed_extensions=(PHOTO_IMAGE_EXTS | PHOTO_VIDEO_EXTS))
                if not file_url:
                    errors.append({"name": fname, "reason": "No se pudo guardar el archivo."})
                    continue
            except StorageObjectTooLargeError as e:
                size_mb = None
                try:
                    size_mb = round((e.size_bytes or 0) / (1024 * 1024))
                except Exception:
                    pass
                errors.append({
                    "name": fname,
                    "reason": "Supera el tamaño máximo del almacenamiento"
                              + (f" (el archivo ocupa ~{size_mb} MB)" if size_mb else "")
                              + ". Hay que ampliar el límite de subida en Supabase → Storage.",
                })
                continue
            except ValueError as e:
                errors.append({"name": fname, "reason": str(e) or "Formato de archivo no permitido."})
                continue
            except Exception as e:
                errors.append({"name": fname, "reason": (str(e) or "Error desconocido al subir.")[:300]})
                continue
            row = Photo(
                owner_type=ot,
                owner_id=owner.id,
                artist_id=artist_id,
                kind=kind,
                title=os.path.splitext(os.path.basename(fname))[0] or fname,
                file_name=stored_name,
                file_url=file_url,
                mime_type=stored_mime,
                photographer_promoter_id=photographer_id,
                photographer_unknown=bool(photographer_unknown),
                file_sha256=file_sha,
                sort_order=next_order,
                created_by_user_id=to_uuid(state.get("user_id")),
                created_by_nick=(state.get("nick") or "").strip() or None,
            )
            session_db.add(row)
            next_order += 1
            created.append(row)

        session_db.commit()
        # Generar la miniatura/póster de cada vídeo en 2º plano (no bloquea la respuesta).
        for p in created:
            if (getattr(p, "kind", None) or "").upper() == "VIDEO" and not (getattr(p, "poster_url", None) or "").strip():
                _video_poster_schedule(p.id, p.file_url)
        promo_map = _photo_promoter_map(session_db, created)
        return jsonify({
            "ok": True,
            "created": [_photo_payload(p, promo_map.get(p.photographer_promoter_id)) for p in created],
            "errors": errors,
            "duplicates": duplicates,
        })
    except Exception as e:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(e)}), 500
    finally:
        session_db.close()


def _remote_object_exists(url: str, attempts: int = 3) -> bool:
    """HEAD a una URL pública para confirmar que el objeto se subió de verdad (evita crear filas
    Photo fantasma). Reintenta un par de veces: tras un PUT directo puede haber un microdesfase de
    propagación y un único HEAD fallido daría un falso negativo."""
    if not url or not isinstance(url, str) or not url.startswith(("http://", "https://")):
        return False
    for i in range(max(1, attempts)):
        try:
            req = Request(url, method="HEAD", headers={"User-Agent": "Mozilla/5.0"})
            with urlopen(req, timeout=6) as resp:
                code = getattr(resp, "status", None) or resp.getcode()
                if 200 <= int(code) < 400:
                    return True
        except Exception:
            pass
        if i < attempts - 1:
            time.sleep(0.5)
    return False


@app.post("/fotos/<owner_type>/<owner_id>/video/sign", endpoint="fotos_video_sign")
@admin_required
def fotos_video_sign(owner_type, owner_id):
    """Paso 1 de la subida DIRECTA de vídeos: valida propietario + extensión de vídeo y devuelve una
    URL firmada de Supabase para que el navegador suba el archivo sin pasar por el servidor."""
    ot = _photo_owner_type_norm(owner_type)
    if not ot:
        return jsonify({"ok": False, "error": "Tipo no válido."}), 400
    data = request.get_json(silent=True) or {}
    filename = (data.get("filename") or "").strip()
    ext = os.path.splitext(filename.lower())[1]
    if ext not in PHOTO_VIDEO_EXTS:
        return jsonify({"ok": False, "error": "La subida directa es solo para vídeos."}), 400
    session_db = db()
    try:
        owner, _artist_id, _title = _photo_resolve_owner(session_db, ot, owner_id)
        if not owner:
            return jsonify({"ok": False, "error": "No encontrado."}), 404
    finally:
        session_db.close()
    try:
        info = create_signed_upload_url_for("photos", ext)
    except Exception as e:
        return jsonify({"ok": False, "error": "No se pudo preparar la subida directa: " + (str(e)[:200])}), 502
    if not info.get("signed_url"):
        return jsonify({"ok": False, "error": "No se pudo preparar la subida directa."}), 502
    return jsonify({"ok": True, "key": info["key"], "upload_url": info["signed_url"]})


@app.post("/fotos/<owner_type>/<owner_id>/video/register", endpoint="fotos_video_register")
@admin_required
def fotos_video_register(owner_type, owner_id):
    """Paso 2 de la subida DIRECTA de vídeos: el navegador ya subió el/los archivo(s) a Supabase;
    aquí se dan de alta las filas Photo (kind=VIDEO). Devuelve la MISMA forma que fotos_upload."""
    ot = _photo_owner_type_norm(owner_type)
    if not ot:
        return jsonify({"ok": False, "error": "Tipo no válido."}), 400
    data = request.get_json(silent=True) or {}
    items = data.get("items") or []
    photographer_unknown = _truthy(data.get("photographer_unknown"))
    photographer_id = None if photographer_unknown else to_uuid(data.get("photographer_promoter_id"))
    state = _current_user_state()
    session_db = db()
    try:
        owner, artist_id, _title = _photo_resolve_owner(session_db, ot, owner_id)
        if not owner:
            return jsonify({"ok": False, "error": "No encontrado."}), 404
        base_order = (
            session_db.query(func.coalesce(func.max(Photo.sort_order), -1))
            .filter(Photo.owner_type == ot, Photo.owner_id == owner.id)
            .scalar()
        )
        next_order = int(base_order) + 1
        # Huellas débiles (fp) ya presentes en este owner, para un dedup BLANDO de vídeos.
        existing_fps = {
            sha for (sha,) in session_db.query(Photo.file_sha256)
            .filter(Photo.owner_type == ot, Photo.owner_id == owner.id, Photo.file_sha256.isnot(None)).all()
            if sha
        }
        created, errors, duplicates = [], [], []
        # Tope de ítems por llamada (normalmente 1): evita que un JSON con miles de items dispare
        # miles de HEAD de red y bloquee un hilo del worker.
        for it in (items if isinstance(items, list) else [])[:50]:
            fname = (str(it.get("file_name") or "vídeo")).strip() or "vídeo"
            key = (str(it.get("key") or "")).strip()
            # key debe ser exactamente una que el servidor firmó: photos/<hex>.<extvideo>
            if not re.match(r"^photos/[0-9a-fA-F]{16,}\.[a-z0-9]{2,5}$", key):
                errors.append({"name": fname, "reason": "Referencia de archivo no válida."})
                continue
            ext = os.path.splitext(key.lower())[1]
            if ext not in PHOTO_VIDEO_EXTS:
                errors.append({"name": fname, "reason": "Formato no permitido."})
                continue
            try:
                file_url = public_url_for_key(key)
            except Exception:
                file_url = ""
            if not file_url:
                errors.append({"name": fname, "reason": "No se encontró el archivo subido; reinténtalo."})
                continue
            # IDEMPOTENCIA: si ya existe una fila con esta file_url (mismo key único), un reintento
            # del register tras perderse la respuesta NO crea un duplicado -> se devuelve la existente.
            existing_row = (
                session_db.query(Photo)
                .filter(Photo.owner_type == ot, Photo.owner_id == owner.id, Photo.file_url == file_url)
                .first()
            )
            if existing_row is not None:
                created.append(existing_row)
                continue
            if not _remote_object_exists(file_url):
                errors.append({"name": fname, "reason": "No se encontró el archivo subido; reinténtalo."})
                continue
            fp = (str(it.get("fp") or "")).strip()
            fp_key = ("wk:" + fp) if fp else None
            if fp_key and fp_key in existing_fps:
                duplicates.append({"name": fname, "prev_date": "ya subido antes"})
                continue
            mime = (str(it.get("mime_type") or "")).strip() or None
            row = Photo(
                owner_type=ot,
                owner_id=owner.id,
                artist_id=artist_id,
                kind="VIDEO",
                title=os.path.splitext(os.path.basename(fname))[0] or fname,
                file_name=fname,
                file_url=file_url,
                mime_type=mime,
                photographer_promoter_id=photographer_id,
                photographer_unknown=bool(photographer_unknown),
                file_sha256=fp_key,
                sort_order=next_order,
                created_by_user_id=to_uuid(state.get("user_id")),
                created_by_nick=(state.get("nick") or "").strip() or None,
            )
            session_db.add(row)
            if fp_key:
                existing_fps.add(fp_key)
            next_order += 1
            created.append(row)
        session_db.commit()
        # Generar la miniatura/póster de cada vídeo en 2º plano (no bloquea la respuesta).
        for p in created:
            if (getattr(p, "kind", None) or "").upper() == "VIDEO" and not (getattr(p, "poster_url", None) or "").strip():
                _video_poster_schedule(p.id, p.file_url)
        promo_map = _photo_promoter_map(session_db, created)
        return jsonify({
            "ok": True,
            "created": [_photo_payload(p, promo_map.get(p.photographer_promoter_id)) for p in created],
            "errors": errors,
            "duplicates": duplicates,
        })
    except Exception as e:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(e)}), 500
    finally:
        session_db.close()


@app.post("/fotos/<owner_type>/<owner_id>/reorder", endpoint="fotos_reorder")
@admin_required
def fotos_reorder(owner_type, owner_id):
    ot = _photo_owner_type_norm(owner_type)
    if not ot:
        return jsonify({"ok": False, "error": "Tipo no válido."}), 400
    payload = request.get_json(silent=True) or {}
    order = [to_uuid(x) for x in (payload.get("order") or []) if to_uuid(x)]
    album_id = to_uuid(payload.get("album_id"))
    session_db = db()
    try:
        owner, _artist_id, _title = _photo_resolve_owner(session_db, ot, owner_id)
        if not owner:
            return jsonify({"ok": False, "error": "No encontrado."}), 404
        if album_id:
            # Orden dentro de un álbum (PhotoAlbumItem).
            rows = {it.photo_id: it for it in session_db.query(PhotoAlbumItem).filter(PhotoAlbumItem.album_id == album_id).all()}
            for idx, pid in enumerate(order):
                it = rows.get(pid)
                if it:
                    it.sort_order = idx
        else:
            # Orden de las fotos sueltas del owner.
            rows = {
                p.id: p
                for p in session_db.query(Photo).filter(Photo.owner_type == ot, Photo.owner_id == owner.id).all()
            }
            for idx, pid in enumerate(order):
                p = rows.get(pid)
                if p:
                    p.sort_order = idx
        session_db.commit()
        return jsonify({"ok": True})
    except Exception as e:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(e)}), 500
    finally:
        session_db.close()


