@app.get("/fotos/<owner_type>/<owner_id>/emails", endpoint="api_fotos_owner_emails")
@admin_required
def api_fotos_owner_emails(owner_type, owner_id):
    ot = _photo_owner_type_norm(owner_type)
    if not ot:
        return jsonify({"ok": False, "error": "Tipo no válido."}), 400
    session_db = db()
    try:
        owner, artist_id, _t = _photo_resolve_owner(session_db, ot, owner_id)
        out = []
        seen = set()
        def _add(email, label):
            e = (email or "").strip()
            if e and e.lower() not in seen:
                seen.add(e.lower()); out.append({"email": e, "label": label})
        artist = session_db.get(Artist, artist_id) if artist_id else None
        if artist:
            _add(getattr(artist, "email", None), artist.name)
            for ae in session_db.query(ArtistEmail).filter(ArtistEmail.artist_id == artist.id).all():
                _add(getattr(ae, "email", None), getattr(ae, "label", None) or artist.name)
        if ot == "CONCERT" and getattr(owner, "promoter_id", None):
            pr = session_db.get(Promoter, owner.promoter_id)
            if pr:
                _add(getattr(pr, "contact_email", None), (pr.nick or "Promotor"))
        return jsonify({"ok": True, "emails": out})
    finally:
        session_db.close()


def _photo_share_email_html(session_db, share, photos, owner_title, note):
    """Correo de envío de materiales con el estilo de las comunicaciones de la app (como
    invitaciones): logo de la empresa a la derecha, «Hola,» + nota, cabecera del evento en
    galleta, botón principal para VER Y DESCARGAR, listado con miniaturas y botón ZIP."""
    company = session_db.get(GroupCompany, share.brand_company_id) if share.brand_company_id else None
    logo = (company.logo_url if company and company.logo_url else url_for("static", filename="img/logo.png", _external=True))
    urls = _photo_share_urls(share.token)
    owner, _aid, _tt = _photo_resolve_owner(session_db, share.owner_type, share.owner_id)
    card = _public_share_card(session_db, share.owner_type, owner, artist_id=_aid)
    header_html = _photo_event_header_email_html(card, owner_title)
    intro = '<p>Hola,</p>'
    if note:
        intro += "".join(f'<p>{escape(line)}</p>' for line in note.splitlines() if line.strip())
    else:
        intro += '<p>aquí tienes los materiales. Puedes verlos en grande y descargarlos, todos o uno a uno.</p>'
    main_btn = ('<p style="margin:14px 0"><a href="%s" style="background:#e83b4b;color:#fff;padding:11px 22px;'
                'border-radius:10px;text-decoration:none;font-weight:700;display:inline-block">Ver y descargar los contenidos</a></p>'
                % urls["public_url"])
    rows = ""
    for p in photos:
        is_video = (p.kind or "IMAGE").upper() == "VIDEO"
        dl = _external_url_for("public_photo_share_item", token=share.token, photo_id=str(p.id))
        if is_video:
            media = ('<span style="display:inline-block;width:64px;height:64px;border-radius:8px;background:#111;color:#fff;'
                     'text-align:center;line-height:64px;font-size:22px">&#9654;</span>')
        else:
            media = '<img src="%s" style="width:64px;height:64px;object-fit:cover;border-radius:8px;display:block">' % escape(_absolute_media_url(p.file_url or ""))
        rows += ('<tr><td style="padding:6px 10px 6px 0;width:64px">%s</td>'
                 '<td style="padding:6px;font-size:14px;vertical-align:middle"><b>%s</b><div style="font-size:12px;color:#888">%s</div></td>'
                 '<td style="padding:6px;vertical-align:middle"><a href="%s" style="color:#007CA2">&#11015; Descargar</a></td></tr>'
                 ) % (media, escape(p.title or p.file_name or ""), ("Vídeo" if is_video else "Foto"), dl)
    return (
        '<div style="font-family:Arial,sans-serif;color:#111;line-height:1.45;max-width:640px;margin:auto">'
        '<div style="text-align:right;margin-bottom:6px"><img src="%s" alt="" style="max-height:58px;max-width:200px"></div>' % logo
        + intro
        + header_html
        + '<h2 style="text-align:center;margin:6px 0 10px">Envío de materiales</h2>'
        + main_btn
        + '<table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse">' + rows + '</table>'
        + '<p style="margin-top:18px"><a href="%s" style="background:#007CA2;color:#fff;padding:10px 18px;border-radius:10px;text-decoration:none;font-weight:700;display:inline-block">Descargar todo (ZIP)</a></p>' % urls["zip_url"]
        + '<p style="color:#888;font-size:12px;margin-top:14px">Si los botones no funcionan, copia este enlace: %s</p>' % urls["public_url"]
        + '</div>'
    )


@app.post("/fotos/<owner_type>/<owner_id>/share/email/preview", endpoint="fotos_share_email_preview")
@admin_required
def fotos_share_email_preview(owner_type, owner_id):
    """Vista previa del correo de materiales (misma estética que el envío, sin crear nada)."""
    ot = _photo_owner_type_norm(owner_type)
    if not ot:
        return jsonify({"ok": False, "error": "Tipo no válido."}), 400
    payload = request.get_json(silent=True) or {}
    ids = [to_uuid(x) for x in (payload.get("photo_ids") or [])]
    ids = [x for x in ids if x]
    session_db = db()
    try:
        owner, _aid, owner_title = _photo_resolve_owner(session_db, ot, owner_id)
        if not owner:
            return jsonify({"ok": False, "error": "No encontrado."}), 404
        photos = (
            session_db.query(Photo).filter(Photo.id.in_(ids)).order_by(Photo.sort_order.asc()).all()
        ) if ids else []
        share = PhotoShare(
            owner_type=ot, owner_id=owner.id, token="previsualizacion",
            photo_ids=[str(x) for x in ids],
            brand_company_id=to_uuid(payload.get("brand_company_id")) or _photo_owner_group_company_id(session_db, ot, owner),
        )
        html_body = _photo_share_email_html(session_db, share, photos, owner_title, (payload.get("note") or "").strip())
        return jsonify({"ok": True, "html": html_body})
    finally:
        session_db.close()


@app.post("/fotos/<owner_type>/<owner_id>/share/email", endpoint="fotos_share_email")
@admin_required
def fotos_share_email(owner_type, owner_id):
    ot = _photo_owner_type_norm(owner_type)
    if not ot:
        return jsonify({"ok": False, "error": "Tipo no válido."}), 400
    payload = request.get_json(silent=True) or {}
    ids = [to_uuid(x) for x in (payload.get("photo_ids") or []) if to_uuid(x)]
    recipients = payload.get("recipients") or []
    note = (payload.get("note") or "").strip() or None
    brand_company_id = to_uuid(payload.get("brand_company_id"))
    if not ids:
        return jsonify({"ok": False, "error": "Sin fotos."}), 400
    if not recipients:
        return jsonify({"ok": False, "error": "Indica al menos un destinatario."}), 400
    state = _current_user_state()
    session_db = db()
    try:
        owner, _aid, owner_title = _photo_resolve_owner(session_db, ot, owner_id)
        if not owner:
            return jsonify({"ok": False, "error": "No encontrado."}), 404
        photos = session_db.query(Photo).filter(Photo.id.in_(ids)).all()
        share = _create_photo_share(session_db, ot, owner, ids, brand_company_id, owner_title, state)
        session_db.commit()
        subject = (payload.get("subject") or ("Fotografías — " + (owner_title or ""))).strip()
        html = _photo_share_email_html(session_db, share, photos, owner_title, note)
        ok, err = _send_optional_email(recipients, subject, html, reply_to=_current_user_email())
        if not ok:
            return jsonify({"ok": False, "error": err or "No se pudo enviar."}), 500
        return jsonify({"ok": True})
    except Exception as e:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(e)}), 500
    finally:
        session_db.close()


def _photo_share_load(session_db, token):
    share = session_db.query(PhotoShare).filter(PhotoShare.token == token).first()
    if not share:
        return None, []
    ids = [to_uuid(x) for x in (share.photo_ids or []) if to_uuid(x)]
    photos = session_db.query(Photo).filter(Photo.id.in_(ids)).all() if ids else []
    order = {pid: i for i, pid in enumerate(ids)}
    photos.sort(key=lambda p: order.get(p.id, 0))
    return share, photos


@app.get("/fotos-compartir/<token>", endpoint="public_photo_share")
def public_photo_share(token):
    session_db = db()
    try:
        share, photos = _photo_share_load(session_db, token)
        if not share:
            abort(404)
        owner, _aid, owner_title = _photo_resolve_owner(session_db, share.owner_type, share.owner_id)
        company = session_db.get(GroupCompany, share.brand_company_id) if share.brand_company_id else None
        logo = (company.logo_url if company and company.logo_url else url_for("static", filename="img/logo.png"))
        rows = [{
            "id": str(p.id), "title": p.title or p.file_name or "", "file_url": p.file_url,
            "is_video": (p.kind or "IMAGE").upper() == "VIDEO",
            "download_url": url_for("public_photo_share_item", token=token, photo_id=str(p.id)),
        } for p in photos]
        card = _public_share_card(session_db, share.owner_type, owner, _aid)
        _card_bits = [x for x in [card["activity_label"], card["event_name"], card["city"], card["date_label"]] if x]
        og = {
            "title": ("Fotos / Vídeos" + (" · " + (card["artist_name"] or card["event_name"] or owner_title) if (card["artist_name"] or card["event_name"] or owner_title) else "")),
            "description": " · ".join(_card_bits),
            # SIEMPRE absoluta y sin el «?» final de storage3: si no, WhatsApp/SMS no previsualizan.
            "image": _absolute_media_url(card["artist_photo"] or (rows[0]["file_url"] if rows and not rows[0]["is_video"] else "") or (logo or "")),
        }
        return render_template("public_photo_share.html", logo=logo, owner_title=owner_title, photos=rows,
                               zip_url=url_for("public_photo_share_zip", token=token), count_label=_photo_count_label(photos),
                               kind_title="Fotos / Vídeos", card=card, og=og)
    finally:
        session_db.close()


@app.get("/fotos-compartir/<token>/zip", endpoint="public_photo_share_zip")
def public_photo_share_zip(token):
    fmt = (request.args.get("fmt") or "original").strip().lower()
    session_db = db()
    try:
        share, photos = _photo_share_load(session_db, token)
        if not share or not photos:
            abort(404)
        _owner, _aid, owner_title = _photo_resolve_owner(session_db, share.owner_type, share.owner_id)
        data, fname = _photos_zip_bytes(photos, fmt, share.title or owner_title)
        return send_file(BytesIO(data), mimetype="application/zip", as_attachment=True, download_name=fname)
    finally:
        session_db.close()


@app.get("/fotos-compartir/<token>/<photo_id>", endpoint="public_photo_share_item")
def public_photo_share_item(token, photo_id):
    fmt = (request.args.get("fmt") or "original").strip().lower()
    session_db = db()
    try:
        share, photos = _photo_share_load(session_db, token)
        if not share:
            abort(404)
        p = next((x for x in photos if str(x.id) == str(photo_id)), None)
        if not p:
            abort(404)
        data, mimetype, fname = _photo_download_bytes(p, fmt)
        return send_file(BytesIO(data), mimetype=mimetype, as_attachment=True, download_name=fname)
    finally:
        session_db.close()


@app.post('/administracion/gastos/<expense_id>/solicitud-pago/<decision>', endpoint='administration_payment_request_decision')
@admin_required
def administration_payment_request_decision(expense_id, decision):
    session_db = db()
    try:
        expense = session_db.get(BagExpense, to_uuid(expense_id))
        if not expense:
            abort(404)
        decision = (decision or '').strip().upper()
        note = (request.form.get('note') or '').strip()
        if decision == 'ACCEPT':
            expense.immediate_payment_requested = False
            expense.payment_status = 'PENDIENTE'
            expense.admin_review_status = 'PAGO_ACEPTADO'
            expense.admin_review_note = note or None
            expense.admin_reviewed_at = _now_madrid()
            session_db.add(BagPaymentInteraction(expense_id=expense.id, kind='PAGO_ACEPTADO', description=note or 'Solicitud aceptada por administración.', amount=expense.immediate_payment_amount or expense.amount_gross, created_by_nick=_email_to_nick(_current_user_email() or '')))
            flash('Solicitud aceptada y enviada a pendiente de pago.', 'success')
        else:
            expense.immediate_payment_requested = False
            expense.payment_status = 'NO_PAGADO'
            expense.admin_review_status = 'PAGO_RECHAZADO'
            expense.admin_review_note = note or 'Solicitud rechazada por administración.'
            expense.admin_reviewed_at = _now_madrid()
            session_db.add(BagPaymentInteraction(expense_id=expense.id, kind='PAGO_RECHAZADO', description=expense.admin_review_note, amount=Decimal('0'), created_by_nick=_email_to_nick(_current_user_email() or '')))
            flash('Solicitud rechazada y devuelta con nota.', 'warning')
        session_db.commit()
        return redirect(url_for('administracion_view', tab='pendiente', subtab='solicitudes'))
    except Exception as exc:
        session_db.rollback()
        flash(f'Error revisando solicitud: {exc}', 'danger')
        return redirect(url_for('administracion_view', tab='pendiente', subtab='solicitudes'))
    finally:
        session_db.close()


@app.post('/administracion/bolsas/<bag_id>/cierre-liquidacion', endpoint='administration_bag_close_liquidation')
@admin_required
def administration_bag_close_liquidation(bag_id):
    session_db = db()
    try:
        bag = session_db.get(WorkflowBag, to_uuid(bag_id))
        if not bag:
            abort(404)
        mode = (request.form.get('mode') or 'CERRAR').strip().upper()
        note = (request.form.get('note') or '').strip()
        if mode == 'VALIDAR':
            bag.liquidation_status = 'PENDIENTE_CIERRE'
            bag.liquidation_reviewed_at = _now_madrid()
            flash('Liquidación validada y enviada a cierre.', 'success')
        elif mode == 'PAGO':
            bag.liquidation_status = 'PENDIENTE_PAGO'
            flash('Liquidación cerrada y enviada a pagos.', 'success')
        elif mode == 'ARCHIVAR':
            bag.liquidation_status = 'ARCHIVADA'
            bag.is_archived = True
            bag.archived_at = _now_madrid()
            flash('Liquidación archivada.', 'success')
        else:
            bag.liquidation_status = 'CERRADA'
            bag.is_archived = True
            bag.archived_at = _now_madrid()
            flash('Liquidación cerrada.', 'success')
        adjustments = list(getattr(bag, 'liquidation_adjustments', None) or [])
        if note:
            adjustments.append({'at': _now_madrid().isoformat(), 'by': _current_user_email(), 'note': note, 'mode': mode})
        bag.liquidation_adjustments = adjustments
        session_db.commit()
        return redirect(url_for('administracion_view', tab='pendiente', subtab='cierre'))
    except Exception as exc:
        session_db.rollback()
        flash(f'Error cerrando liquidación: {exc}', 'danger')
        return redirect(url_for('administracion_view', tab='pendiente', subtab='cierre'))
    finally:
        session_db.close()


