def _safe_uuid(value):
    try:
        return to_uuid(value)
    except Exception:
        return None


def _safe_int(value, default: int = 0) -> int:
    try:
        return int(str(value or "").strip() or default)
    except Exception:
        return default


def _json_dict(value) -> dict:
    if isinstance(value, dict):
        return dict(value)
    if isinstance(value, str) and value.strip():
        try:
            parsed = json.loads(value)
            return parsed if isinstance(parsed, dict) else {}
        except Exception:
            return {}
    return {}


def _json_list(value) -> list:
    if isinstance(value, list):
        return list(value)
    if isinstance(value, str) and value.strip():
        try:
            parsed = json.loads(value)
            return parsed if isinstance(parsed, list) else []
        except Exception:
            return []
    return []


APP33_ENTITY_LINK_TYPES = {
    "promoter": {"label": "Tercero", "icon": "fa-user-tie"},
    "empresa": {"label": "Empresa", "icon": "fa-building"},
    "institucion": {"label": "Institución", "icon": "fa-landmark"},
    "artist": {"label": "Artista", "icon": "fa-microphone-lines"},
    "media": {"label": "Medio", "icon": "fa-bullhorn"},
    "venue": {"label": "Recinto", "icon": "fa-location-dot"},
    "ticketer": {"label": "Ticketera", "icon": "fa-ticket"},
    "publishing": {"label": "Editorial", "icon": "fa-pen-nib"},
    "personal": {"label": "Alguien de la empresa", "icon": "fa-users"},
    "event": {"label": "Evento", "icon": "fa-masks-theater"},
}
APP33_ENTITY_LINK_ALIASES = {
    "third_party": "promoter", "tercero": "promoter", "promotor": "promoter",
    "company": "empresa", "empresas": "empresa",
    "institution": "institucion", "instituciones": "institucion", "institución": "institucion",
    "artista": "artist",
    "medio": "media", "recinto": "venue", "ticketera": "ticketer", "editorial": "publishing",
    "publishing_company": "publishing",
    "user": "personal", "usuario": "personal", "oficina": "personal", "empleado": "personal", "staff": "personal",
}

def _entity_link_type(raw: str | None) -> str:
    value = (raw or "").strip().lower()
    value = APP33_ENTITY_LINK_ALIASES.get(value, value)
    return value if value in APP33_ENTITY_LINK_TYPES else ""


def _entity_link_label(entity_type: str | None) -> str:
    return APP33_ENTITY_LINK_TYPES.get(_entity_link_type(entity_type), {}).get("label", "Vinculación")


def _entity_placeholder_url() -> str:
    try:
        return url_for("static", filename="img/placeholder_photo.png")
    except Exception:
        return ""


def _entity_link_payload(session_db, entity_type: str | None, entity_id) -> dict | None:
    etype = _entity_link_type(entity_type)
    eid = _safe_uuid(entity_id)
    if not etype or not eid:
        return None
    row = None
    label = ""
    subtitle = ""
    logo_url = ""
    href = ""
    if etype in ("promoter", "empresa", "institucion"):
        row = session_db.get(Promoter, eid)
        if row:
            label = _promoter_display_name(row) or row.nick or _entity_link_label(etype)
            subtitle = " · ".join([x for x in [(row.contact_email or "").strip(), (row.contact_phone or "").strip()] if x])
            logo_url = row.logo_url or ""
            href = url_for("promoter_detail_view", pid=row.id)
    elif etype == "artist":
        row = session_db.get(Artist, eid)
        if row:
            label = row.name or "Artista"
            subtitle = (getattr(row, "genre", "") or "").strip()
            logo_url = getattr(row, "photo_url", "") or ""
            href = url_for("artist_detail_view", artist_id=row.id)
    elif etype == "event":
        row = session_db.get(AppEvent, eid)
        if row:
            label = row.name or "Evento"
            subtitle = ""
            logo_url = getattr(row, "logo_url", "") or ""
            href = url_for("event_detail_view", eid=row.id)
    elif etype == "media":
        row = session_db.get(MediaOutlet, eid)
        if row:
            label = row.name or "Medio"
            subtitle = (row.media_type or "").replace("_", " ").title()
            logo_url = row.logo_url or ""
            href = url_for("media_outlet_detail_view", media_id=row.id)
    elif etype == "venue":
        row = session_db.get(Venue, eid)
        if row:
            label = row.name or "Recinto"
            subtitle = " · ".join([x for x in [(row.municipality or "").strip(), (row.province or "").strip()] if x])
            logo_url = row.photo_url or ""
            href = url_for("venue_detail_view", vid=row.id)
    elif etype == "ticketer":
        row = session_db.get(Ticketer, eid)
        if row:
            label = row.name or "Ticketera"
            subtitle = row.link_url or ""
            logo_url = row.logo_url or ""
            href = url_for("ticketer_detail_view", tid=row.id)
    elif etype == "publishing":
        row = session_db.get(PublishingCompany, eid)
        if row:
            label = row.name or "Editorial"
            subtitle = "Editorial"
            logo_url = row.logo_url or ""
            href = url_for("publishing_company_detail_view", pcid=row.id)
    elif etype == "personal":
        # Persona de la oficina (User + UserProfile; comparten id user_id).
        user = session_db.get(User, eid)
        profile = session_db.get(UserProfile, eid)
        if user:
            row = user
            label = (_profile_full_name(profile) if profile else "") or (getattr(profile, "nick", None) if profile else None) or (user.email or "Personal")
            subtitle = ", ".join(getattr(profile, "departments", None) or []) if profile else (user.email or "")
            logo_url = (getattr(profile, "photo_url", None) or "") if profile else ""
            href = url_for("personnel_detail_view", user_id=user.id)
    if not row:
        return None
    return {
        "type": etype,
        "type_label": _entity_link_label(etype),
        "icon": APP33_ENTITY_LINK_TYPES.get(etype, {}).get("icon", "fa-link"),
        "id": str(eid),
        "label": label,
        "subtitle": subtitle,
        "logo_url": logo_url or _entity_placeholder_url(),
        "href": href,
    }


def _entity_link_self_types(etype: str) -> list[str]:
    """Tipos equivalentes que apuntan a la misma fila física. Empresa/Institución/Tercero
    comparten la tabla de terceros, así una vinculación creada como «empresa» también debe
    aparecer en la ficha del tercero (y viceversa)."""
    if etype in ("promoter", "empresa", "institucion"):
        return ["promoter", "empresa", "institucion"]
    return [etype]


def _entity_link_rows(session_db, entity_type: str | None, entity_id, active_only: bool = True) -> list[dict]:
    etype = _entity_link_type(entity_type)
    eid = _safe_uuid(entity_id)
    if not etype or not eid:
        return []
    self_types = _entity_link_self_types(etype)
    q = session_db.query(ThirdPartyLink).filter(
        or_(
            and_(ThirdPartyLink.source_type.in_(self_types), ThirdPartyLink.source_id == eid),
            and_(ThirdPartyLink.target_type.in_(self_types), ThirdPartyLink.target_id == eid),
        )
    )
    if active_only:
        q = q.filter(ThirdPartyLink.is_active.is_(True))
    rows = q.order_by(ThirdPartyLink.created_at.desc()).all()
    out = []
    for link in rows:
        if link.source_type in self_types and str(link.source_id) == str(eid):
            other = _entity_link_payload(session_db, link.target_type, link.target_id)
            source = _entity_link_payload(session_db, link.source_type, link.source_id)
        else:
            other = _entity_link_payload(session_db, link.source_type, link.source_id)
            source = _entity_link_payload(session_db, link.target_type, link.target_id)
        if not other:
            continue
        out.append({
            "id": str(link.id),
            "relation_title": link.relation_title or "",
            "note": link.note or "",
            "is_active": bool(link.is_active),
            "created_at_label": _invitation_display_datetime(link.created_at) if "_invitation_display_datetime" in globals() else "",
            "source": source,
            "linked": other,
        })
    return out


def _entity_link_dedupe_rows(rows: list[dict]) -> list[dict]:
    """Colapsa, SOLO para los resúmenes mini, vínculos repetidos hacia "lo mismo" (mismo nombre de
    entidad vinculada): si el mismo vínculo existe dos veces —p. ej. una vez hacia una ficha creada
    sin logo y otra hacia la ficha real con logo— se muestra UNA sola vez, prefiriendo la variante
    CON logo. El panel de gestión de la ficha sigue enseñando todas las filas para poder limpiarlas."""
    out: list[dict] = []
    by_label: dict[str, int] = {}
    for r in rows or []:
        linked = r.get("linked") or {}
        key = (linked.get("label") or "").strip().lower()
        if not key:
            out.append(r)
            continue
        prev = by_label.get(key)
        if prev is None:
            by_label[key] = len(out)
            out.append(r)
            continue
        prev_logo = ((out[prev].get("linked") or {}).get("logo_url") or "").strip()
        this_logo = (linked.get("logo_url") or "").strip()
        if not prev_logo and this_logo:
            out[prev] = r
    return out


def _promoter_link_summary(session_db, promoter: Promoter | None, publisher_fallback: bool = True) -> dict:
    if not promoter:
        return {}
    # CACHÉ por request + atajo del índice de vínculos activos. Los listados de invitaciones piden
    # el resumen del MISMO tercero muchas veces (solicitudes, compromisos y los 3 listados) y cada
    # llamada era una consulta; con la BD en otra región eso convertía la página en segundos de
    # espera. Además, si el tercero no tiene ningún vínculo (la mayoría), ni se consulta.
    _ck = (str(promoter.id), bool(publisher_fallback))
    try:
        _cache = getattr(g, "_promoter_link_summary_cache", None)
        if _cache is None:
            _cache = {}
            g._promoter_link_summary_cache = _cache
    except Exception:
        _cache = None
    if _cache is not None and _ck in _cache:
        return _cache[_ck]

    def _remember(res: dict) -> dict:
        if _cache is not None:
            _cache[_ck] = res
        return res

    rows = []
    _active = None
    try:
        _active = _entity_link_active_keys()
    except Exception:
        _active = None
    if _active is None or ("promoter", str(promoter.id)) in _active:
        rows = _entity_link_dedupe_rows(_entity_link_rows(session_db, "promoter", promoter.id, active_only=True))
    if not rows:
        # Fallback a la EDITORIAL del tercero (contextos discográficos). En INVITACIONES va a False:
        # la editorial NO es una vinculación y aparecía como tal sobre el plano/listados.
        pub = getattr(promoter, "publishing_company", None) if publisher_fallback else None
        if pub:
            return _remember({"label": pub.name, "type_label": "Editorial", "type": "publishing", "logo_url": pub.logo_url or _entity_placeholder_url(), "items": []})
        return _remember({})
    first = rows[0].get("linked") or {}
    label = first.get("label") or ""
    type_label = first.get("type_label") or ""
    return _remember({
        "label": label,
        "type_label": type_label,
        "type": first.get("type") or "",
        "relation_title": rows[0].get("relation_title") or "",
        "icon": first.get("icon") or "fa-link",
        "logo_url": first.get("logo_url") or _entity_placeholder_url(),
        "items": [{
            "label": (r.get("linked") or {}).get("label", ""),
            "type_label": (r.get("linked") or {}).get("type_label", ""),
            "relation_title": r.get("relation_title", ""),
            "icon": (r.get("linked") or {}).get("icon", "fa-link"),
            "logo_url": (r.get("linked") or {}).get("logo_url", ""),
        } for r in rows[:3]],
    })


def _promoter_link_summary_text(summary: dict | None) -> str:
    """Texto corto y legible del vínculo principal: primero el NOMBRE de lo vinculado y, a
    continuación, la relación. Ej.: "Radio X - director" o, si no hay relación, solo "Radio X".
    NO se muestra el tipo de la entidad vinculada (institución, medio, …)."""
    if not summary:
        return ""
    parts = [(summary.get("label") or "").strip(), (summary.get("relation_title") or "").strip()]
    return " - ".join([x for x in parts if x])


# --- Mini-ficha de vínculos para pintar BAJO el nombre+foto de CUALQUIER entidad ---------
# Núcleo del requisito «en toda la app»: cuando se muestra una entidad vinculable (tercero,
# artista, medio, recinto, ticketera, editorial) que tiene vinculaciones, debajo del nombre se
# pinta en pequeño el logo/foto de lo vinculado + el cargo/relación. Para que cualquier plantilla
# pueda hacerlo sin tocar su ruta, exponemos el helper global `linked_mini(tipo, id)` (ver
# inject_globals), que resuelve los vínculos de forma perezosa con una sesión de SOLO LECTURA
# cacheada por request y un caché por (tipo, id) para no repetir consultas.
def _entity_link_mini_session():
    sess = getattr(g, "_entity_link_session", None)
    if sess is None:
        sess = db()
        g._entity_link_session = sess
    return sess


@app.teardown_request
def _close_entity_link_session(exc=None):
    sess = getattr(g, "_entity_link_session", None)
    if sess is not None:
        try:
            sess.close()
        except Exception:
            pass
        try:
            g._entity_link_session = None
        except Exception:
            pass
    return None


def _entity_link_active_keys():
    """Conjunto de claves (tipo, id) que aparecen en ALGUNA vinculación activa (como origen o
    destino), precargado UNA vez por request con una sola consulta. Permite que `linked_mini` no
    consulte por cada entidad sin vínculos (el caso habitual en listados). Devuelve None si la
    precarga falla (entonces se cae al comportamiento por-entidad)."""
    if getattr(g, "_entity_link_keys_done", False):
        return getattr(g, "_entity_link_active_keys_set", None)
    keys = set()
    ok = True
    try:
        sess = _entity_link_mini_session()
        for s_type, s_id, t_type, t_id in sess.query(
            ThirdPartyLink.source_type, ThirdPartyLink.source_id,
            ThirdPartyLink.target_type, ThirdPartyLink.target_id,
        ).filter(ThirdPartyLink.is_active.is_(True)).all():
            keys.add((_entity_link_type(s_type), str(s_id)))
            keys.add((_entity_link_type(t_type), str(t_id)))
    except Exception:
        ok = False
    try:
        g._entity_link_keys_done = True
        g._entity_link_active_keys_set = keys if ok else None
    except Exception:
        pass
    return keys if ok else None


def _entity_link_mini_summary(entity_type, entity_id) -> dict | None:
    """Resumen corto (vínculo principal + hasta 3) de cualquier entidad vinculable, cacheado por
    (tipo, id) durante la request. Devuelve None si no tiene vínculos activos."""
    etype = _entity_link_type(entity_type)
    eid = _safe_uuid(entity_id)
    if not etype or not eid:
        return None
    cache = getattr(g, "_entity_link_mini_cache", None)
    if cache is None:
        cache = {}
        try:
            g._entity_link_mini_cache = cache
        except Exception:
            pass
    key = (etype, str(eid))
    if key in cache:
        return cache[key]
    # Atajo: si conocemos el índice de claves con vínculos y esta no está, no hay nada que pintar.
    active = _entity_link_active_keys()
    if active is not None and key not in active:
        cache[key] = None
        return None
    summary = None
    try:
        rows = _entity_link_dedupe_rows(_entity_link_rows(_entity_link_mini_session(), etype, eid, active_only=True))
    except Exception:
        rows = []
    if rows:
        first = rows[0].get("linked") or {}
        summary = {
            "label": first.get("label", ""),
            "type_label": first.get("type_label", ""),
            "type": first.get("type", ""),
            "relation_title": rows[0].get("relation_title", ""),
            "icon": first.get("icon", "fa-link"),
            "logo_url": first.get("logo_url", ""),
            "items": [{
                "label": (r.get("linked") or {}).get("label", ""),
                "type_label": (r.get("linked") or {}).get("type_label", ""),
                "type": (r.get("linked") or {}).get("type", ""),
                "relation_title": r.get("relation_title", ""),
                "icon": (r.get("linked") or {}).get("icon", "fa-link"),
                "logo_url": (r.get("linked") or {}).get("logo_url", ""),
                "href": (r.get("linked") or {}).get("href", ""),
            } for r in rows[:3]],
            "extra": max(0, len(rows) - 3),
        }
    try:
        cache[key] = summary
    except Exception:
        pass
    return summary


def linked_mini(entity_type=None, entity_id=None, summary=None, max_items=2):
    """HTML de la mini-ficha de vínculos para colocar bajo el nombre+foto de una entidad.
    Uso en plantilla: {{ linked_mini('promoter', p.id) }} (o pasando un `summary` ya calculado).
    Devuelve '' si la entidad no tiene vínculos."""
    if summary is None and entity_type is not None and entity_id is not None:
        summary = _entity_link_mini_summary(entity_type, entity_id)
    if not summary:
        return Markup("")
    items = summary.get("items")
    if not items:
        base = {
            "relation_title": summary.get("relation_title", ""),
            "type_label": summary.get("type_label", ""),
            "type": summary.get("type", ""),
            "label": summary.get("label", ""),
            "logo_url": summary.get("logo_url", ""),
        }
        items = [base] if (base["label"] or base["relation_title"]) else []
    if not items:
        return Markup("")
    try:
        limit = max(1, int(max_items))
    except Exception:
        limit = 2
    shown = items[:limit]
    hidden = summary.get("extra", 0) + max(0, len(items) - len(shown))
    chips = []
    for it in shown:
        # Primero el NOMBRE de lo vinculado y, a continuación, la relación (logo + "nombre - relación").
        # Nunca el tipo de la entidad (medio, institución…).
        label = (it.get("label") or "").strip()
        relation = (it.get("relation_title") or "").strip()
        if label and relation:
            inner = Markup('<b>%s</b> - %s') % (label, relation)
        elif label:
            inner = Markup('<b>%s</b>') % label
        else:
            inner = Markup('%s') % relation
        img_cls = "is-photo" if (it.get("type") or "") in ("artist", "venue") else "is-logo"
        chips.append(Markup('<span class="linked-mini-item"><img class="%s" src="%s" alt="" loading="lazy"><span class="linked-mini-text">%s</span></span>') % (
            img_cls, it.get("logo_url") or _entity_placeholder_url(), inner,
        ))
    extra_html = Markup('<span class="linked-mini-more">+%d</span>') % hidden if hidden else Markup("")
    return Markup('<span class="linked-mini">%s%s</span>') % (Markup("").join(chips), extra_html)


def _invitation_token() -> str:
    return _uuid.uuid4().hex + _uuid.uuid4().hex[:8]


def _invitation_display_date(value) -> str:
    if not value:
        return "Sin fecha"
    try:
        return value.strftime("%d/%m/%Y")
    except Exception:
        return str(value)


def _invitation_display_datetime(value) -> str:
    if not value:
        return ""
    try:
        return value.strftime("%d/%m/%Y %H:%M")
    except Exception:
        return str(value)


def _invitation_normalize_search(value: str | None) -> str:
    raw = str(value or "")
    raw = unicodedata.normalize("NFD", raw)
    raw = "".join(ch for ch in raw if unicodedata.category(ch) != "Mn")
    raw = re.sub(r"[^a-zA-Z0-9]+", " ", raw)
    return raw.casefold().strip()


def _concert_artist_ids(concert: Concert | None) -> list[str]:
    ids = []
    if not concert:
        return ids
    raw = getattr(concert, "artist_ids", None)
    if isinstance(raw, list):
        ids.extend([str(x) for x in raw if x])
    if getattr(concert, "artist_id", None):
        ids.append(str(concert.artist_id))
    out = []
    seen = set()
    for item in ids:
        if item and item not in seen:
            seen.add(item)
            out.append(item)
    return out


def _concert_artist_rows(session_db, concert: Concert | None) -> list[Artist]:
    ids = [_safe_uuid(x) for x in _concert_artist_ids(concert)]
    ids = [x for x in ids if x]
    if not ids:
        return []
    rows = session_db.query(Artist).filter(Artist.id.in_(ids)).order_by(Artist.name.asc()).all()
    order = {str(x): i for i, x in enumerate(ids)}
    return sorted(rows, key=lambda a: order.get(str(a.id), 9999))


def _artist_chip_payload(artist: Artist | None) -> dict:
    return {
        "id": str(getattr(artist, "id", "") or ""),
        "name": getattr(artist, "name", None) or "Artista",
        "photo_url": getattr(artist, "photo_url", None) or url_for("static", filename="img/placeholder_photo.png"),
    }


def _invitation_event_type_label(concert: Concert | None) -> str:
    raw = (getattr(concert, "activity_type", None) or getattr(concert, "sale_type", None) or "CONCIERTO").strip().upper()
    labels = {
        "CONCIERTO": "Concierto",
        "FESTIVAL": "Festival",
        "EVENTO_PROMOCIONAL": "Evento promocional",
        "PROGRAMA_TV": "Programa de TV",
        "TV": "Programa de TV",
        "MARCA": "Acción con marca",
        "OTROS": "Otros",
        "CADIZ": "Festival / ciclo",
    }
    return labels.get(raw, raw.replace("_", " ").title())


def _invitation_event_title(concert: Concert | None) -> str:
    if not concert:
        return "Evento"
    # Nombre del evento si lo hay (p. ej. festival / ciclo).
    festival = (getattr(concert, "festival_name", None) or "").strip()
    if festival:
        return festival
    # Si no hay nombre de evento, el título es el MUNICIPIO (no el nombre del recinto;
    # el recinto y la ciudad ya se muestran en la línea de debajo).
    city = _invitation_event_city(concert)
    if city:
        return city
    # Último recurso: la etiqueta del tipo de actividad.
    return _invitation_event_type_label(concert)


def _invitation_event_city(concert: Concert | None) -> str:
    if not concert:
        return ""
    return (getattr(concert, "manual_municipality", None) or (getattr(getattr(concert, "venue", None), "municipality", None) or "")).strip()


def _invitation_event_province(concert: Concert | None) -> str:
    if not concert:
        return ""
    return (getattr(concert, "manual_province", None) or (getattr(getattr(concert, "venue", None), "province", None) or "")).strip()


def _invitation_event_venue_name(concert: Concert | None) -> str:
    if not concert:
        return ""
    return (getattr(getattr(concert, "venue", None), "name", None) or getattr(concert, "manual_venue_name", None) or "").strip()


def _invitation_event_payload(session_db, concert: Concert, include_counts: bool = False) -> dict:
    artists = [_artist_chip_payload(a) for a in _concert_artist_rows(session_db, concert)]
    payload = {
        "id": str(concert.id),
        "type_label": _invitation_event_type_label(concert),
        # Nombre EXPLÍCITO del evento (festival/ciclo) si lo hay; vacío si no. `title` ya hace el
        # fallback a municipio/tipo, pero para componer "nombre · municipio · fecha" necesitamos
        # saber si existe un nombre propio para no duplicar el municipio.
        "name": (getattr(concert, "festival_name", None) or "").strip(),
        "title": _invitation_event_title(concert),
        "date": concert.date.isoformat() if getattr(concert, "date", None) else "",
        "date_label": _invitation_display_date(getattr(concert, "date", None)),
        "city": _invitation_event_city(concert),
        "province": _invitation_event_province(concert),
        "venue": _invitation_event_venue_name(concert),
        "show_time": getattr(concert, "show_time", None) or "",
        "artists": artists,
        "artist_names": ", ".join([a["name"] for a in artists]) or (getattr(getattr(concert, "artist", None), "name", None) or ""),
        "status": getattr(concert, "status", None) or "",
        # Cartel principal del concierto (si hay cartelería subida): se usa en cabeceras en vez del avatar.
        "poster_url": _concert_poster_url(concert),
    }
    if include_counts:
        payload["counts"] = _invitation_event_counts(session_db, concert)
    return payload


def _invitation_category_legacy_rows(concert: Concert | None) -> list[dict]:
    rows: list[dict] = []
    seen = set()
    for raw in list(getattr(concert, "invitations_json", None) or []):
        if not isinstance(raw, dict):
            continue
        name = (raw.get("category") or raw.get("name") or "General").strip() or "General"
        key = name.casefold()
        if key in seen:
            continue
        seen.add(key)
        rows.append({
            "name": name,
            "qty_contract": _safe_int(raw.get("total_qty"), _safe_int(raw.get("artist_qty")) + _safe_int(raw.get("office_qty"))),
            "source": "CONTRATO",
        })
    ticketing = getattr(concert, "ticketing_payload", None) or {}
    if isinstance(ticketing, dict):
        for raw in list(ticketing.get("ticket_types") or []):
            if not isinstance(raw, dict):
                continue
            qty = _safe_int(raw.get("invites_total")) or _safe_int(raw.get("invites_artist"))
            if qty <= 0:
                continue
            name = (raw.get("name") or raw.get("category") or "General").strip() or "General"
            key = name.casefold()
            if key in seen:
                continue
            seen.add(key)
            rows.append({"name": name, "qty_contract": qty, "source": "TICKETING"})
    if not rows:
        rows.append({"name": "General", "qty_contract": 0, "source": "DEFAULT"})
    return rows


def _invitation_get_categories(session_db, concert: Concert, ensure_defaults: bool = False) -> list[InvitationCategory]:
    categories = (
        session_db.query(InvitationCategory)
        .filter(InvitationCategory.concert_id == concert.id)
        .order_by(InvitationCategory.sort_order.asc(), InvitationCategory.created_at.asc())
        .all()
    )
    if categories or not ensure_defaults:
        return categories
    created = []
    for idx, row in enumerate(_invitation_category_legacy_rows(concert)):
        cat = InvitationCategory(
            concert_id=concert.id,
            name=row["name"],
            source=row.get("source") or "DEFAULT",
            qty_contract=_safe_int(row.get("qty_contract")),
            sort_order=idx,
            created_by_user_id=_safe_uuid(session.get("user_id")),
            created_by_nick=_current_user_email(),
        )
        session_db.add(cat)
        created.append(cat)
    try:
        session_db.flush()
    except Exception:
        session_db.rollback()
        return (
            session_db.query(InvitationCategory)
            .filter(InvitationCategory.concert_id == concert.id)
            .order_by(InvitationCategory.sort_order.asc(), InvitationCategory.created_at.asc())
            .all()
        )
    return created


INVITATION_ZONES = [
    ("PISTA", "Pista", "fa-people-group"),
    ("GRADA", "Grada", "fa-chair"),
    ("PALCO", "Palcos", "fa-crown"),
]
INVITATION_ZONE_LABELS = {k: lbl for k, lbl, _ic in INVITATION_ZONES}
INVITATION_ZONE_ICONS = {k: ic for k, _lbl, ic in INVITATION_ZONES}


def _invitation_category_zone(cat) -> str:
    """Zona de la categoría: PISTA / GRADA / PALCO. Si no está fijada, se infiere del nombre
    (front stage / general → pista; tribuna/anfiteatro → grada; palco → palco)."""
    z = (getattr(cat, "zone", None) or "").strip().upper()
    if z in INVITATION_ZONE_LABELS:
        return z
    n = (getattr(cat, "name", None) or "").lower()
    if "palco" in n:
        return "PALCO"
    if any(k in n for k in ["grada", "graderio", "graderío", "tribuna", "anfiteatro"]):
        return "GRADA"
    return "PISTA"


def _invitation_category_name_is_honor(cat) -> bool:
    return "honor" in ((getattr(cat, "name", None) or "").lower())


def _invitation_is_locking_palco(cat) -> bool:
    """True para los palcos que se asignan como UNIDAD: una vez comprometidos a alguien quedan
    bloqueados (no se les arrastran más invitados) y desaparecen del asistente de pedir.
    EXCEPCIÓN: el «Palco de Honor» funciona como una categoría de entrada más (varios compromisos/
    peticiones, no se bloquea al haber compromisos), así que NO es un palco de bloqueo."""
    return _invitation_category_zone(cat) == "PALCO" and not _invitation_category_name_is_honor(cat)


def _invitation_ticket_counts_by_category(session_db, concert) -> dict:
    """{cat_id: {uploaded, assigned}} de las entradas del concierto (assigned = no disponibles,
    incluye enviadas). Compartido por la página y el API de categorías (el API construía el payload
    SIN conteos y el «Disponibles» de los asistentes salía solo con lo configurado)."""
    counts = defaultdict(lambda: {"uploaded": 0, "assigned": 0})
    for cid, status, count in (
        session_db.query(InvitationTicket.category_id, InvitationTicket.status, func.count(InvitationTicket.id))
        .filter(InvitationTicket.concert_id == concert.id)
        .group_by(InvitationTicket.category_id, InvitationTicket.status)
        .all()
    ):
        counts[str(cid)]["uploaded"] += int(count or 0)
        if status != 'AVAILABLE':
            counts[str(cid)]["assigned"] += int(count or 0)
    return counts


def _invitation_category_payload(cat: InvitationCategory, counts: dict | None = None) -> dict:
    qty_contract = _safe_int(getattr(cat, "qty_contract", 0))
    qty_extra = _safe_int(getattr(cat, "qty_extra", 0))
    uploaded = _safe_int((counts or {}).get("uploaded", 0))
    assigned = _safe_int((counts or {}).get("assigned", 0))
    total_configured = qty_contract + qty_extra
    # El disponible efectivo nunca es menor que las entradas subidas: al subir, se actualiza.
    effective_configured = max(total_configured, uploaded)
    return {
        "id": str(cat.id),
        "name": cat.name,
        "ticket_kind": cat.ticket_kind or "PDF_UNNUMBERED",
        "guest_list_mode": cat.guest_list_mode or "",
        "qty_contract": qty_contract,
        "qty_extra": qty_extra,
        "configured": total_configured,
        "uploaded": uploaded,
        "assigned": assigned,
        "available_configured": max(effective_configured - assigned, 0),
        # Disponible REAL para pedir/comprometer: si hay entradas SUBIDAS manda eso (subidas menos
        # asignadas/enviadas); si aún no se subió nada, lo configurado.
        "available_real": max(uploaded - assigned, 0) if uploaded > 0 else max(total_configured, 0),
        "source": cat.source or "MANUAL",
        "is_active": bool(cat.is_active),
        "requests_blocked": bool(getattr(cat, "requests_blocked", False)),
        "requests_over_quota_blocked": bool(getattr(cat, "requests_over_quota_blocked", False)),
        "is_pmr": bool(getattr(cat, "is_pmr", False)),
        "stairs_spec": (getattr(cat, "stairs_spec", None) or ""),
        "zone": _invitation_category_zone(cat),
        "zone_label": INVITATION_ZONE_LABELS.get(_invitation_category_zone(cat), "Pista"),
        "zone_icon": INVITATION_ZONE_ICONS.get(_invitation_category_zone(cat), "fa-people-group"),
    }


def _invitation_ticket_kind_label(value: str | None) -> str:
    key = (value or "PDF_UNNUMBERED").strip().upper()
    return dict(INVITATION_CATEGORY_TYPES).get(key, key.replace("_", " ").title())


def _invitation_ticket_status_label(value: str | None) -> str:
    labels = {
        "AVAILABLE": "Disponible",
        "ASSIGNED": "Asignada",
        "SENT": "Enviada",
        "DELIVERED": "Entregada",
        "PICKED_UP": "Recogida",
        "PRINTED": "Impresa",
        "LOST": "Perdida",
        "BLOCKED": "Bloqueada",
    }
    return labels.get((value or "AVAILABLE").upper(), (value or "AVAILABLE").title())


def _invitation_ticket_status_class(value: str | None) -> str:
    key = (value or "AVAILABLE").strip().upper()
    if key == "AVAILABLE":
        return "available"
    if key == "ASSIGNED":
        return "assigned"
    if key == "PRINTED":
        return "printed"
    if key in {"SENT", "DELIVERED", "PICKED_UP"}:
        return "sent"
    if key == "LOST":
        return "lost"
    if key == "BLOCKED":
        return "blocked"
    return key.lower()


# Estados en los que una entrada ya "salió" y NO se puede reutilizar para asignar a otro invitado:
# enviada por cualquier vía o IMPRESA (la impresión bloquea igual que el envío, distinto color).
INVITATION_TICKET_CONSUMED_STATUSES = {"SENT", "DELIVERED", "PICKED_UP", "PRINTED", "DISPONIBLES_TAQUILLA", "RECOGIDAS_TAQUILLA", "ENTREGADAS_MANO"}


# Paleta para colorear cada invitado en el plano de butacas (borde de la butaca + chip bajo la fila).
INVITATION_ASSIGNEE_COLORS = ["#e83b4b", "#007ca2", "#f59e0b", "#16a34a", "#7c3aed", "#db2777", "#0891b2", "#65a30d", "#ea580c", "#4f46e5"]


def _invitation_ticket_payload(t: InvitationTicket, name_map: dict[str, str] | None = None, request_map: dict | None = None, commitment_map: dict | None = None) -> dict:
    sector = (getattr(t, "sector", None) or "").strip()
    row_label = (getattr(t, "row_label", None) or "").strip()
    seat = (getattr(t, "seat_number", None) or "").strip()
    location = " ".join([x for x in [sector, row_label, seat] if x]) or ("Numerada" if getattr(t, "is_numbered", False) else "Sin numerar")
    status = t.status or "AVAILABLE"
    rid = str(t.assigned_request_id) if getattr(t, "assigned_request_id", None) else ""
    rinfo = (request_map or {}).get(rid) if rid else None
    # Enviada/descargada: la entrada por sí misma (status/sent_at) o, si está asignada a una
    # solicitud, lo que diga la solicitud (la descarga solo se registra a nivel de solicitud).
    sent = status in {"SENT", "DELIVERED", "PICKED_UP"} or bool(getattr(t, "sent_at", None)) or bool(rinfo and rinfo.get("sent"))
    downloaded = bool(rinfo and rinfo.get("downloaded"))
    return {
        "id": str(t.id),
        "category_id": str(t.category_id),
        "category_name": (name_map or {}).get(str(t.category_id), "Categoría"),
        "status": status,
        "status_label": _invitation_ticket_status_label(t.status),
        "status_class": _invitation_ticket_status_class(t.status),
        # AÑADIDA en el último envío (ampliación): etiqueta azul junto a la entrada.
        "added_after_send": bool(getattr(t, "added_after_send", False)),
        "code": t.ticket_code or t.pdf_name or "—",
        "pdf_url": t.pdf_url,
        "pdf_name": t.pdf_name or "",
        "sector": sector or "General",
        "row_label": row_label or "Sin fila",
        "seat_number": seat,
        "is_numbered": bool(getattr(t, "is_numbered", False)),
        "location": location,
        "assigned_label": t.assigned_label or (rinfo.get("guest_name") if rinfo else "") or "",
        "assigned_request_id": rid,
        "assigned_commitment_id": str(t.assigned_commitment_id) if getattr(t, "assigned_commitment_id", None) else "",
        "assignee_promoter_id": (rinfo.get("promoter_id") if rinfo else "") or "",
        "assignee_artist_id": (rinfo.get("artist_id") if rinfo else "") or "",
        "sent": bool(sent),
        "downloaded": bool(downloaded),
        "warning": t.previous_assignment_warning or "",
        # Quién tiene la butaca (para pintarlo sobre el plano): clave estable + nombre/foto/vínculo.
        **_invitation_ticket_assignee_fields(t, rid, rinfo, request_map, commitment_map),
    }


def _invitation_assignee_visual(session_db, row, link_photo_fallback: bool = True) -> dict:
    """Nombre + foto/logo + vínculo del invitado de una solicitud/compromiso, para pintarlo sobre el
    plano. Tercero → logo + vínculo; artista/empleado → foto.
    link_photo_fallback: si la persona NO tiene foto propia, usar el logo de su vinculación como
    imagen. SOLO debe activarse para las BUTACAS asignadas (ver de un vistazo para quién son);
    en listados/tarjetas va a False y quien no tiene foto simplemente no la muestra."""
    name = (getattr(row, "guest_name", None) or "").strip()
    photo = ""
    link = ""
    link_logo = ""
    link_type = ""
    gp = getattr(row, "guest_promoter_id", None)
    ga = getattr(row, "guest_artist_id", None)
    gu = getattr(row, "guest_user_id", None)
    if gp:
        pr = session_db.get(Promoter, gp)
        if pr:
            name = name or _promoter_display_name(pr) or pr.nick
            photo = pr.logo_url or ""
            _ls = _promoter_link_summary(session_db, pr, publisher_fallback=False)
            link = _promoter_link_summary_text(_ls)
            link_logo = (_ls or {}).get("logo_url") or ""
            link_type = (_ls or {}).get("type") or ""
            # Si el tercero no tiene foto/logo pero está vinculado, usa el logo/foto de lo vinculado
            # (solo para las butacas asignadas; en listados no se sustituye).
            if link_photo_fallback and not photo and _ls:
                photo = _ls.get("logo_url") or ""
    elif ga:
        ar = session_db.get(Artist, ga)
        if ar:
            name = name or ar.name
            photo = getattr(ar, "photo_url", "") or ""
    elif gu:
        up = session_db.get(UserProfile, gu)
        if up:
            name = name or _profile_full_name(up) or getattr(up, "nick", "") or ""
            photo = getattr(up, "photo_url", "") or ""
    # Si es PARA EL ARTISTA (destinatario artista) y no hay foto propia, usa la foto del artista del evento.
    if ga and not photo:
        try:
            _concert = getattr(row, "concert", None) or (session_db.get(Concert, row.concert_id) if getattr(row, "concert_id", None) else None)
            _arows = _concert_artist_rows(session_db, _concert) if _concert else []
            if _arows:
                photo = getattr(_arows[0], "photo_url", "") or photo
        except Exception:
            pass
    return {"name": name or "", "photo": photo or "", "link": link or "", "link_logo": link_logo or "", "link_type": link_type or ""}


def _invitation_ticket_assignee_fields(t, rid, rinfo, request_map, commitment_map) -> dict:
    """Datos del invitado (clave, nombre, foto, vínculo) de una butaca asignada, para pintarlo."""
    cidk = str(t.assigned_commitment_id) if getattr(t, "assigned_commitment_id", None) else ""
    info = None
    key = ""
    if rid and rinfo:
        key = f"R:{rid}"
        info = rinfo
        # Solicitud: el nombre es el del invitado.
        name = (t.assigned_label or "") or (info.get("guest_name") or "")
    elif cidk:
        key = f"C:{cidk}"
        info = (commitment_map or {}).get(cidk)
        # Compromiso: el nombre es el del COMPROMISO (no a quién se envía).
        name = (info.get("guest_name") if info else "") or (t.assigned_label or "")
    else:
        name = t.assigned_label or ""
    return {
        "assignee_key": key,
        "assignee_name": name,
        "assignee_photo": (info.get("photo") if info else "") or "",
        "assignee_link": (info.get("link") if info else "") or "",
        "assignee_link_logo": (info.get("link_logo") if info else "") or "",
        "assignee_link_type": (info.get("link_type") if info else "") or "",
        "assignee_total": _safe_int(info.get("total")) if info else 0,
        "assignee_requester": (info.get("requester") if info else "") or "",
    }


def _parse_stairs_spec(spec) -> set[int]:
    """Parsea la especificación de escaleras del configurador (p. ej. '17-19, 27-29') y devuelve el
    conjunto de butacas TRAS las que va la escalera (la menor de cada par: 17, 27). Tolerante a
    formatos ('17 y 19', '17/19', '17'); ignora lo que no sean números."""
    out: set[int] = set()
    for chunk in re.split(r"[,;\n]+", str(spec or "")):
        nums = [int(x) for x in re.findall(r"\d+", chunk)]
        if nums:
            out.add(min(nums))
    return out


def _invitation_stair_afters_for_category(concert, category) -> set[int]:
    """Butacas TRAS las que pintar una «escalera» en el plano de esta categoría.
    Prioridad: lo configurado en la categoría (campo stairs_spec del configurador). Si no hay nada
    configurado, se aplica el valor por defecto del Cádiz Music Stadium (Palco de Honor→17, Grada de
    Invitados→27) como respaldo histórico. Vacío = sin escaleras."""
    parsed = _parse_stairs_spec(getattr(category, "stairs_spec", None) if category is not None else None)
    if parsed:
        return parsed
    nv = _invitation_normalize_search(_concert_venue_name(concert))
    if not ("cadiz" in nv and "stadium" in nv):
        return set()
    nc = _invitation_normalize_search(getattr(category, "name", None) if category is not None else None)
    if "palco" in nc and "honor" in nc:
        return {17}
    if "grada" in nc and "invitados" in nc:
        return {27}
    return set()


def _invitation_layout_json(category) -> dict:
    raw = getattr(category, "layout_json", None) if category is not None else None
    if isinstance(raw, dict):
        return raw
    return _json_loads_safe(raw, {}) or {}


def _invitation_int_set(vals) -> set[int]:
    out: set[int] = set()
    for v in (vals or []):
        s = str(v).strip()
        if s.lstrip("-").isdigit():
            out.add(int(s))
    return out


def _invitation_num_set(vals) -> set:
    """Conjunto de posiciones numéricas: enteras (butacas existentes) o con decimales (elementos
    INSERTADOS entre butacas o fuera de rango, p. ej. 6.5 = entre la 6 y la 8, o -1 = antes del inicio)."""
    out = set()
    for v in (vals or []):
        try:
            f = float(v)
        except (TypeError, ValueError):
            continue
        out.add(int(f) if f == int(f) else round(f, 4))
    return out


_INVITATION_STAGE_EDGES = {"top", "bottom", "left", "right"}


def _invitation_stage_point(raw) -> dict | None:
    """Punto del escenario sobre el MARCO del mapa como {x,y} en % (0-100) + ángulo de la flecha.
    Acepta el nuevo formato {x,y} o el legado por borde ('top'/'bottom'/'left'/'right')."""
    edge_map = {"top": (50.0, 0.0), "bottom": (50.0, 100.0), "left": (0.0, 50.0), "right": (100.0, 50.0)}
    x = y = None
    if isinstance(raw, dict):
        try:
            x = max(0.0, min(100.0, float(raw.get("x"))))
            y = max(0.0, min(100.0, float(raw.get("y"))))
        except (TypeError, ValueError):
            return None
    elif isinstance(raw, str) and raw.strip().lower() in edge_map:
        x, y = edge_map[raw.strip().lower()]
    if x is None or y is None:
        return None
    import math as _math
    angle = _math.degrees(_math.atan2(y - 50.0, x - 50.0))  # 0=derecha, 90=abajo, -90=arriba
    return {"x": round(x, 2), "y": round(y, 2), "angle": round(angle, 1)}


def _invitation_sector_layout(category, sector: str, concert=None, default_stairs=None) -> dict:
    """Configuración del plano de UN sector: por FILA (escaleras/huecos/asientos apagados), sentido de
    numeración y punto del escenario (360° sobre el marco). Compatibilidad con el formato antiguo por
    sector (stairs/gaps/off a nivel de sector se aplican como respaldo a todas las filas)."""
    data = _invitation_layout_json(category)
    sectors = data.get("sectors") if isinstance(data.get("sectors"), dict) else {}
    sec = (sectors or {}).get(sector) or (sectors or {}).get((sector or "").strip()) or {}
    if not isinstance(sec, dict):
        sec = {}
    legacy_stairs = _invitation_int_set(sec.get("stairs"))
    if not legacy_stairs:
        legacy_stairs = set(default_stairs or ()) or _invitation_stair_afters_for_category(concert, category)
    rows_raw = sec.get("rows") if isinstance(sec.get("rows"), dict) else {}
    rows_cfg = {}
    for rl, rc in (rows_raw or {}).items():
        if isinstance(rc, dict):
            rows_cfg[str(rl)] = {
                "stairs": _invitation_int_set(rc.get("stairs")),
                "gaps": _invitation_num_set(rc.get("gaps")),
                "off": _invitation_num_set(rc.get("off")),
            }
    orientation = (sec.get("orientation") or "ltr").strip().lower()
    # Filas-separadoras (PASILLOS entre filas): filas SIN butacas que llevan sus propios
    # elementos (escaleras/huecos/apagados) y se colocan ENTRE dos filas (ancla `after` = la
    # fila tras la que van; vacío = antes de la primera). Se ven igual en configurador/visión/asignación.
    separators = []
    for sp in (sec.get("separators") if isinstance(sec.get("separators"), list) else []):
        if not isinstance(sp, dict):
            continue
        separators.append({
            "after": str(sp.get("after") or ""),
            "stairs": _invitation_int_set(sp.get("stairs")),
            "gaps": _invitation_num_set(sp.get("gaps")),
            "off": _invitation_num_set(sp.get("off")),
        })
    return {
        "rows_cfg": rows_cfg,
        "separators": separators,
        "legacy_stairs": legacy_stairs,
        "legacy_gaps": _invitation_num_set(sec.get("gaps")),
        "legacy_off": _invitation_num_set(sec.get("off")),
        "stage": _invitation_stage_point(sec.get("stage")),
        "orientation": "rtl" if orientation == "rtl" else "ltr",
    }


def _invitation_row_layout(cfg: dict, row_label: str) -> dict:
    """Escaleras/huecos/apagados EFECTIVOS de una fila: los suyos propios o, si no tiene, el respaldo
    de sector (formato antiguo)."""
    rc = (cfg.get("rows_cfg") or {}).get(str(row_label)) or {}
    return {
        "stairs": rc.get("stairs") if rc.get("stairs") else set(cfg.get("legacy_stairs") or ()),
        "gaps": rc.get("gaps") if rc.get("gaps") else set(cfg.get("legacy_gaps") or ()),
        "off": rc.get("off") if rc.get("off") else set(cfg.get("legacy_off") or ()),
    }


# Tope de columnas por fila al alinear un sector: más allá NO se rellena la rejilla (evita un DOM
# gigante si hay numeraciones muy dispersas por datos raros). El plano cae al modo simple.
_INVITATION_GRID_MAX_COLS = 260


def _invitation_natural_key(value):
    """Clave de orden NATURAL para filas/sectores: los números van en orden numérico
    (Fila 1, 2, ... 10, 11) y no alfabético (1, 10, 11, 2). Mezcla texto+números de forma estable."""
    import re as _re
    parts = _re.split(r"(\d+)", str(value or ""))
    key = []
    for p in parts:
        if p == "":
            continue
        if p.isdigit():
            key.append((0, int(p), ""))
        else:
            key.append((1, 0, p.casefold()))
    return key


def _invitation_ticket_groups(ticket_payloads: list[dict], category=None, concert=None, stair_afters: set[int] | None = None) -> list[dict]:
    """Plano por sector→fila. La rejilla de cada sector se DEDUCE de las butacas que hay (rango
    mín→máx por paso) y CADA fila se alinea a esa rejilla, rellenando con «asientos apagados» (gris)
    las posiciones que la fila no tiene: así todo el sector queda alineado y se ve como un plano
    completo. Se aplican por sector los retoques del configurador (escaleras, huecos, apagados y borde
    del escenario) desde layout_json. Devuelve por sector: filas con `visual` (celdas seat/missing/
    gap/stair) y `layout` (bloques por invitado), `step` y `stage` (borde del escenario)."""
    grouped: dict[str, dict[str, list[dict]]] = defaultdict(lambda: defaultdict(list))
    for item in ticket_payloads:
        grouped[item.get("sector") or "General"][item.get("row_label") or "Sin fila"].append(item)
    # Color estable por invitado dentro de la categoría (para pintar butaca + chip del mismo tono).
    color_by_key: dict[str, str] = {}

    def _color_for(key: str) -> str:
        if not key:
            return ""
        if key not in color_by_key:
            color_by_key[key] = INVITATION_ASSIGNEE_COLORS[len(color_by_key) % len(INVITATION_ASSIGNEE_COLORS)]
        return color_by_key[key]

    _assigned_states = {"ASSIGNED", "SENT", "DELIVERED", "PICKED_UP", "PRINTED", "DISPONIBLES_TAQUILLA", "RECOGIDAS_TAQUILLA", "ENTREGADAS_MANO"}
    _sent_set = {"SENT", "DELIVERED", "PICKED_UP", "PRINTED", "DISPONIBLES_TAQUILLA", "RECOGIDAS_TAQUILLA", "ENTREGADAS_MANO"}
    out = []
    for sector in sorted(grouped.keys(), key=_invitation_natural_key):
        cfg = _invitation_sector_layout(category, sector, concert=concert, default_stairs=stair_afters)
        # Butacas numeradas de TODO el sector para deducir la rejilla común (mín→máx por paso).
        all_nums = [int(s.get("seat_number")) for seats in grouped[sector].values()
                    for s in seats if str(s.get("seat_number") or "").isdigit()]
        # COLUMNAS del sector, alineadas para todas las filas: enteros de la rejilla base (mín→máx por
        # paso, butacas reales) + posiciones INSERTADAS (huecos/apagados con decimales o fuera de rango).
        int_positions = set(all_nums)
        insert_positions = set(cfg.get("legacy_gaps") or ()) | set(cfg.get("legacy_off") or ())
        for _rc in (cfg.get("rows_cfg") or {}).values():
            insert_positions |= set(_rc.get("gaps") or ()) | set(_rc.get("off") or ())
        # Las filas-separadoras (pasillos) también aportan columnas para que TODO el sector alinee.
        for _sp in (cfg.get("separators") or []):
            insert_positions |= set(_sp.get("gaps") or ()) | set(_sp.get("off") or ())
        sector_step = 1
        columns = None
        _int_all = list(int_positions) + [int(p) for p in insert_positions if float(p) == int(p)]
        mn = mx = 0
        if _int_all:
            # La rejilla base (mín→máx por paso) se deduce SOLO de las butacas reales: un hueco/
            # apagado insertado FUERA del rango añade su columna pero no debe redefinir la base
            # (cambiaba mn y, con paso 2, la paridad — aparecían butacas grises fantasma).
            if all_nums:
                mn, mx = min(all_nums), max(all_nums)
            else:
                mn, mx = min(_int_all), max(_int_all)
            _parity = list(all_nums) or _int_all
            sector_step = 2 if (len(_parity) >= 2 and len({int(n) % 2 for n in _parity}) == 1 and (mx - mn) >= 2) else 1
            base = list(range(mn, mx + 1, sector_step))
            cols = set(base) | set(insert_positions) | int_positions
            if len(cols) <= _INVITATION_GRID_MAX_COLS:
                columns = sorted(cols)
        rows = []
        for row_label in sorted(grouped[sector].keys(), key=_invitation_natural_key):
            _rl = _invitation_row_layout(cfg, row_label)
            stairs_after = _rl["stairs"]; gaps_cfg = _rl["gaps"]; off_cfg = _rl["off"]
            seats = sorted(grouped[sector][row_label], key=lambda x: _safe_int(x.get("seat_number")) if str(x.get("seat_number") or "").isdigit() else 999999)
            # Color por invitado en cada butaca asignada.
            for seat in seats:
                st = (seat.get("status") or "").upper()
                key = seat.get("assignee_key") if st in _assigned_states else ""
                seat["assignee_color"] = _color_for(key) if key else ""
            by_num: dict[int, dict] = {}
            non_numbered = []
            for s in seats:
                sv = s.get("seat_number")
                if str(sv or "").isdigit():
                    by_num[int(sv)] = s
                else:
                    non_numbered.append(s)
            visual = []
            if columns is not None:
                # Escaleras en el BORDE inicial (antes de la primera columna): el bucle solo las pinta
                # ENTRE columnas y las de los extremos se perdían en el mapa (el configurador sí las ve).
                if stairs_after and columns:
                    for sa in sorted(stairs_after):
                        if sa < columns[0]:
                            visual.append({"type": "stair", "label": "Escalera"})
                prev_pos = None
                for pos in columns:
                    if prev_pos is not None and stairs_after:
                        for sa in sorted(stairs_after):
                            if prev_pos <= sa < pos:
                                visual.append({"type": "stair", "label": "Escalera"})
                    ipos = int(pos) if float(pos) == int(pos) else None
                    if ipos is not None and ipos in by_num:
                        visual.append({"type": "seat", "seat": by_num[ipos]})
                    elif pos in gaps_cfg:
                        visual.append({"type": "gap", "seat": pos})
                    elif pos in off_cfg:
                        visual.append({"type": "missing", "seat": ipos if ipos is not None else "", "off": True})
                    elif ipos is not None and mn <= ipos <= mx and (ipos - mn) % sector_step == 0:
                        # Posición entera de la rejilla base sin butaca → gris (no la tenemos), para alinear.
                        visual.append({"type": "missing", "seat": ipos, "off": False})
                    else:
                        # Columna de inserción de OTRA fila → espaciador vacío (mantiene la alineación).
                        visual.append({"type": "spacer"})
                    prev_pos = pos
                if stairs_after and columns:
                    for sa in sorted(stairs_after):
                        if sa >= columns[-1]:
                            visual.append({"type": "stair", "label": "Escalera"})
            else:
                # Sin rejilla (sin numerar, o demasiadas columnas): butacas seguidas + escaleras entre nº.
                _first_num = next((int(s.get("seat_number")) for s in seats if str(s.get("seat_number") or "").isdigit()), None)
                if stairs_after and _first_num is not None:
                    for sa in sorted(stairs_after):
                        if sa < _first_num:
                            visual.append({"type": "stair", "label": "Escalera"})
                prev_num = None
                for s in seats:
                    sv = s.get("seat_number")
                    cur = int(sv) if str(sv or "").isdigit() else None
                    if cur is not None and prev_num is not None and stairs_after:
                        for sa in sorted(stairs_after):
                            if prev_num <= sa < cur:
                                visual.append({"type": "stair", "label": "Escalera"})
                    visual.append({"type": "seat", "seat": s})
                    if cur is not None:
                        prev_num = cur
                if stairs_after and prev_num is not None:
                    for sa in sorted(stairs_after):
                        if sa >= prev_num:
                            visual.append({"type": "stair", "label": "Escalera"})
                non_numbered = []
            for seat in non_numbered:
                visual.append({"type": "seat", "seat": seat})
            # Sentido de numeración: por defecto 1,2,3… de izquierda a derecha; si el sector está en
            # 'rtl' se invierte visualmente (el 1 queda a la derecha).
            if cfg.get("orientation") == "rtl":
                visual = list(reversed(visual))
            # Layout de la fila: agrupa butacas SEGUIDAS del mismo invitado en un bloque con barra
            # (nombre + foto) ENCIMA que las abarca; las libres/huecos van sueltos. Así se ve sobre
            # el plano de quién es cada butaca, sin leyenda aparte.
            layout = []
            block = None
            for cell in visual:
                if cell.get("type") == "seat":
                    seat = cell["seat"]
                    st = (seat.get("status") or "").upper()
                    key = seat.get("assignee_key") if st in _assigned_states else ""
                    if key and block and block.get("key") == key:
                        block["seats"].append(seat)
                    elif key:
                        block = {"type": "block", "key": key, "name": seat.get("assignee_name") or "",
                                 "photo": seat.get("assignee_photo") or "", "link": seat.get("assignee_link") or "",
                                 "link_logo": seat.get("assignee_link_logo") or "", "link_type": seat.get("assignee_link_type") or "",
                                 "color": seat.get("assignee_color") or "", "sent": st in _sent_set, "seats": [seat]}
                        layout.append(block)
                    else:
                        block = None
                        layout.append({"type": "seat", "seat": seat})
                else:
                    block = None
                    layout.append(cell)
            rows.append({"row_label": row_label, "seats": seats, "visual": visual, "layout": layout, "step": sector_step})
        # Filas-separadoras (pasillos ENTRE filas): filas sin butacas con sus propios elementos
        # (escaleras/huecos/apagados). Se intercalan según su ancla `after` (vacío = arriba del todo;
        # ancla a fila inexistente = al final). Solo con rejilla (sector numerado alineado).
        separators = cfg.get("separators") or []
        if separators and columns is not None:
            def _sep_row(sp):
                st = sp.get("stairs") or set(); gp = sp.get("gaps") or set(); of = sp.get("off") or set()
                vis = []
                if st:
                    for sa in sorted(st):
                        if sa < columns[0]:
                            vis.append({"type": "stair", "label": "Escalera"})
                prev = None
                for pos in columns:
                    if prev is not None and st:
                        for sa in sorted(st):
                            if prev <= sa < pos:
                                vis.append({"type": "stair", "label": "Escalera"})
                    ipos = int(pos) if float(pos) == int(pos) else None
                    if pos in gp:
                        vis.append({"type": "gap", "seat": pos})
                    elif pos in of:
                        vis.append({"type": "missing", "seat": ipos if ipos is not None else "", "off": True})
                    else:
                        vis.append({"type": "spacer"})
                    prev = pos
                if st:
                    for sa in sorted(st):
                        if sa >= columns[-1]:
                            vis.append({"type": "stair", "label": "Escalera"})
                if cfg.get("orientation") == "rtl":
                    vis = list(reversed(vis))
                return {"row_label": "", "separator": True, "seats": [], "visual": vis, "layout": list(vis), "step": sector_step}
            seat_labels = {r["row_label"] for r in rows}
            interleaved = []
            for sp in separators:
                if not sp.get("after"):
                    interleaved.append(_sep_row(sp))
            for r in rows:
                interleaved.append(r)
                for sp in separators:
                    if sp.get("after") and sp.get("after") == r["row_label"]:
                        interleaved.append(_sep_row(sp))
            for sp in separators:
                a = sp.get("after")
                if a and a not in seat_labels:
                    interleaved.append(_sep_row(sp))
            rows = interleaved
        out.append({"sector": sector, "rows": rows, "stage": cfg["stage"]})
    return out


def _invitation_availability_breakdown(ticket_payloads: list[dict]) -> dict:
    """Disponibles de UNA categoría numerada agrupadas por sector y fila, con rangos de butacas
    seguidas (respetando el paso: pares/impares o correlativo)."""
    avail = [t for t in (ticket_payloads or []) if (t.get('status') or '') == 'AVAILABLE']
    by_sector: dict = defaultdict(lambda: defaultdict(list))
    for t in avail:
        by_sector[t.get('sector') or 'General'][t.get('row_label') or 'Sin fila'].append(t)
    sectors = []
    total = 0
    for sector in sorted(by_sector.keys(), key=lambda x: str(x).casefold()):
        rows = []
        sector_count = 0
        for row_label in sorted(by_sector[sector].keys(), key=lambda x: str(x).casefold()):
            seats = by_sector[sector][row_label]
            sector_count += len(seats)
            nums = sorted([_safe_int(t.get('seat_number')) for t in seats if str(t.get('seat_number') or '').isdigit()])
            step = 2 if (len(nums) >= 2 and len({n % 2 for n in nums}) == 1 and (nums[-1] - nums[0]) >= 2) else 1
            runs = []
            i = 0
            while i < len(nums):
                j = i
                while j + 1 < len(nums) and nums[j + 1] - nums[j] == step:
                    j += 1
                runs.append(str(nums[i]) if nums[i] == nums[j] else f'{nums[i]}-{nums[j]}')
                i = j + 1
            rows.append({'row_label': row_label, 'available': len(seats), 'runs': runs})
        sectors.append({'sector': sector, 'available': sector_count, 'rows': rows})
        total += sector_count
    return {'sectors': sectors, 'available_total': total}


def _invitation_split_pdf_pages(data: bytes) -> list[bytes]:
    """Divide un PDF en una lista de PDFs de una sola página (bytes), una entrada por página.

    Si pypdf no está disponible, el PDF tiene una sola página o no se puede leer/dividir, devuelve
    `[data]` (se trata como una única entrada, comportamiento previo)."""
    if not data:
        return []
    if not PYPDF_AVAILABLE or PdfReader is None or PdfWriter is None:
        return [data]
    try:
        reader = PdfReader(BytesIO(data))
        pages = list(reader.pages)
        if len(pages) <= 1:
            return [data]
        blobs = []
        for page in pages:
            writer = PdfWriter()
            writer.add_page(page)
            buf = BytesIO()
            writer.write(buf)
            blobs.append(buf.getvalue())
        return blobs
    except Exception:
        return [data]


def _invitation_extract_pdf_text_from_bytes(data: bytes) -> str:
    if not data or not PYPDF_AVAILABLE or PdfReader is None:
        return ""
    try:
        reader = PdfReader(BytesIO(data))
        parts = []
        for page in list(reader.pages)[:3]:
            try:
                parts.append(page.extract_text() or "")
            except Exception:
                continue
        return "\n".join(parts)
    except Exception:
        return ""


def _invitation_extract_ticket_metadata(data: bytes, filename: str | None = None) -> dict:
    text_value = _invitation_extract_pdf_text_from_bytes(data)
    haystack = "\n".join([filename or "", text_value or ""])
    compact = re.sub(r"[ \t]+", " ", haystack, flags=re.M)

    # Acota la detección de sector/fila/asiento a la zona de DATOS de la entrada (desde la primera
    # etiqueta tipo "Nombre:/Asiento:/Butaca:/Localidad:") para evitar el largo texto legal de
    # condiciones, que contiene palabras como "Lounge" o "filmar" que ensuciaban la detección.
    m_data = re.search(r"\b(?:nombre|asiento|butaca|localidad)\s*:", compact, flags=re.I)
    data_region = compact[m_data.start():] if m_data else compact

    def pick(patterns, text=None):
        src = compact if text is None else text
        for pattern in patterns:
            m = re.search(pattern, src, flags=re.I | re.M)
            if m:
                return (m.group(1) or "").strip(" :-#\t\r\n")
        return ""

    sector = pick([
        # Zonas con nombre propio ("Platea General", "Tribuna Alta"...): habitual cuando la etiqueta
        # y el valor quedan descolocados al extraer el texto. Las palabras extra se limitan a la misma
        # línea para no arrastrar texto contiguo.
        r"\b((?:platea|tribuna|grada|grader[ií]o|anfiteatro|palco|pista|lounge|patio|preferente)(?:[^\S\n]+(?:general|alta|baja|central|lateral|vip|[A-Z0-9][\wÁÉÍÓÚÜÑ]*)){0,2})\b",
        r"(?:sector|secci[oó]n|zona|bloque|block|grada|tribuna|platea|anfiteatro|palco|puerta|acceso|gate)\s*[:#\.\-]?\s*([A-Za-z0-9ÁÉÍÓÚÜÑ][\wÁÉÍÓÚÜÑ./-]{0,18})",
    ], data_region)
    row_label = pick([
        r"(?:\bfila\b|\brow\b|\bfil\.)\s*[:#\.\-]?\s*([A-Za-z0-9ÁÉÍÓÚÜÑ][\wÁÉÍÓÚÜÑ./-]{0,10})",
        # Valor ANTES de la etiqueta ("...20:00 14Fila:" -> 14).
        r"([0-9]{1,3}[A-Za-zÁÉÍÓÚÜÑ]?)\s*Fila\b",
    ], data_region)
    seat = pick([
        r"(?:asiento|butaca|seat)\s*[:#\.\-]?\s*([0-9]{1,5}[A-Za-z]?)",
        r"n[ºo°]?\.?\s*(?:asiento|butaca)\s*[:#\.\-]?\s*([0-9]{1,5}[A-Za-z]?)",
        # Asiento etiquetado solo como "Nº:"/"N°:" (formato ctickets.es: "Fila: 1  Nº: 3"). Se exige el
        # ":" justo tras "Nº" y `\b` al final para NO confundirlo con "Nº de pedido/entrada" ni capturar
        # trozos de un número largo (pedido). Límite de 4 dígitos: los asientos no son tan largos.
        r"\bn[º°]\.?\s*[:#]\s*([0-9]{1,4}[A-Za-z]?)\b",
        r"\bn[úu]m(?:ero)?\.?\s*[:#]\s*([0-9]{1,4}[A-Za-z]?)\b",
        # Número de asiento aislado en su línea antes de "Apertura de puertas" (valor descolocado).
        r"\n[ ]*([0-9]{1,4})[ ]*\n[ ]*Apertura",
    ], data_region)
    # Código de barras numérico (12-20 dígitos): es lo único realmente ÚNICO por entrada/butaca.
    barcode = pick([r"\b(\d{12,20})\b"])
    # "Localizador"/"Código" etiquetado: puede venir COMPARTIDO por todo el pedido (mismo en todas las
    # entradas), así que NO es fiable para deduplicar; solo se usa si no hay código de barras numérico.
    labeled_code = pick([
        r"(?:c[oó]digo(?:\s*de\s*barras)?|c[oó]d\.?|code|barcode|localizador|locator|n[ºo°]?\.?\s*entrada|ticket)\s*[:#\.\-]?\s*([A-Z0-9][A-Z0-9._/-]{4,64})",
    ])
    generic_code = pick([r"\b([A-Z0-9]{10,})\b"])
    code = barcode or labeled_code or generic_code
    code_reliable = bool(barcode)
    # "Tiene código" = se detectó CUALQUIER código real (de barras, localizador/código etiquetado o
    # un alfanumérico largo). Solo se descartan como "no invitación" las páginas SIN ningún código.
    has_code = bool(barcode or labeled_code or generic_code)
    if not code:
        code = (Path(filename or "").stem or hashlib.sha256(data or b"").hexdigest()[:16]).strip()
    return {
        "sector": sector[:80] or None,
        "row_label": row_label[:40] or None,
        "seat_number": seat[:20] or None,
        "ticket_code": code[:120] or None,
        "code_reliable": code_reliable,
        "has_code": has_code,
        "raw_text": text_value[:4000] if text_value else "",
    }


def _invitation_assigned_qty_for_source(session_db, category_id, source_type: str, source_id) -> int:
    q = session_db.query(func.count(InvitationTicket.id)).filter(InvitationTicket.category_id == category_id)
    if source_type == "commitment":
        q = q.filter(InvitationTicket.assigned_commitment_id == source_id)
    else:
        q = q.filter(InvitationTicket.assigned_request_id == source_id)
    return int(q.scalar() or 0)


def _invitation_pending_assignment_payloads(session_db, concert: Concert, categories: list[InvitationCategory]) -> dict[str, list[dict]]:
    name_map = _invitation_category_name_map(categories)
    payload: dict[str, list[dict]] = {str(c.id): [] for c in categories}
    placeholder_photo = url_for("static", filename="img/placeholder_photo.png")
    # UNA sola consulta agrupada con TODOS los conteos de asignación del concierto. Antes se hacían
    # 1-2 COUNT por fuente×categoría (decenas de consultas) y, con la BD en otra región, eso son
    # segundos de espera al abrir/refrescar el asignador.
    assigned_counts: dict[tuple, int] = {}
    unsent_counts: dict[tuple, int] = {}
    for _cid, _rq, _cm, _st, _n in session_db.query(
            InvitationTicket.category_id, InvitationTicket.assigned_request_id,
            InvitationTicket.assigned_commitment_id, InvitationTicket.status,
            func.count(InvitationTicket.id)).filter(
            InvitationTicket.concert_id == concert.id).group_by(
            InvitationTicket.category_id, InvitationTicket.assigned_request_id,
            InvitationTicket.assigned_commitment_id, InvitationTicket.status).all():
        if _rq:
            _key = (str(_cid), "request", str(_rq))
        elif _cm:
            _key = (str(_cid), "commitment", str(_cm))
        else:
            continue
        assigned_counts[_key] = assigned_counts.get(_key, 0) + int(_n or 0)
        if (_st or "").upper() == "ASSIGNED":
            unsent_counts[_key] = unsent_counts.get(_key, 0) + int(_n or 0)
    for commitment in session_db.query(InvitationCommitment).filter(InvitationCommitment.concert_id == concert.id).order_by(InvitationCommitment.created_at.asc()).all():
        quantities = _json_dict(commitment.quantities_json)
        vis = _invitation_assignee_visual(session_db, commitment, link_photo_fallback=False)
        for cid, qty in quantities.items():
            cat = next((c for c in categories if str(c.id) == str(cid)), None)
            if not cat:
                continue
            assigned = assigned_counts.get((str(cat.id), "commitment", str(commitment.id)), 0)
            pending = max(_safe_int(qty) - assigned, 0)
            # Sin pendientes: sigue apareciendo si tiene entradas ASIGNADAS sin enviar (editable).
            if pending <= 0:
                if unsent_counts.get((str(cat.id), "commitment", str(commitment.id)), 0) <= 0:
                    continue
            payload[str(cat.id)].append({
                "source_type": "commitment",
                "source_id": str(commitment.id),
                "name": commitment.name,
                "company": commitment.reason or "Compromiso",
                "photo_url": vis["photo"] or placeholder_photo,
                # Visual del destinatario (foto/logo + vínculo) para la tarjeta del asignador.
                "guest_photo": vis["photo"] or "",
                "guest_link_text": vis["link"] or "",
                "guest_link_logo": vis["link_logo"] or "",
                "guest_link_type": vis["link_type"] or "",
                "requester": commitment.created_by_nick or "",
                "requester_name": commitment.created_by_nick or "",
                "requester_photo": placeholder_photo,
                "note": (commitment.note or "").strip(),
                "date_label": _invitation_display_datetime(commitment.created_at),
                "qty": pending,
                "qty_total": _safe_int(qty),
                "assigned": assigned,
                "category_id": str(cat.id),
                "category_name": name_map.get(str(cat.id), "Categoría"),
            })
    # Peticiones aprobadas/asignadas (asignables), pendientes de aprobar (se muestran para poder
    # aprobarlas y asignarlas directamente desde aquí) y AMPLIADAS tras el envío (enviadas o
    # entregadas a las que se les añadieron invitaciones: lo pendiente vuelve al asignador para
    # que no se olvide).
    _sent_ish = {"ENVIADAS", "ENTREGADAS_MANO", "DISPONIBLES_TAQUILLA", "RECOGIDAS_TAQUILLA"}
    source_statuses = {"APROBADAS", "ASIGNADAS", "SOLICITADAS"} | _sent_ish
    for row in session_db.query(InvitationRequest).filter(InvitationRequest.concert_id == concert.id, InvitationRequest.status.in_(source_statuses)).order_by(InvitationRequest.created_at.asc()).all():
        is_pending_approval = (row.status or "") == "SOLICITADAS"
        row_sent_ish = (row.status or "") in _sent_ish
        quantities = _json_dict(row.quantities_json)
        vis = _invitation_assignee_visual(session_db, row, link_photo_fallback=False)
        guest_name = vis["name"] or row.guest_name
        note = (row.note or getattr(row, "guest_note", None) or "").strip()
        for cid, qty in quantities.items():
            cat = next((c for c in categories if str(c.id) == str(cid)), None)
            if not cat:
                continue
            # Las categorías de LISTADO no asignan PDFs: una lista ya enviada no vuelve como pendiente.
            if row_sent_ish and (cat.ticket_kind or "").upper() == "GUEST_LIST":
                continue
            assigned = assigned_counts.get((str(cat.id), "request", str(row.id)), 0)
            pending = max(_safe_int(qty) - assigned, 0)
            # Sin pendientes: sigue apareciendo mientras tenga entradas ASIGNADAS sin enviar — se
            # pueden mover/desasignar hasta el envío, también las AMPLIACIONES ya asignadas de una
            # solicitud enviada (igual que los compromisos).
            if pending <= 0 and unsent_counts.get((str(cat.id), "request", str(row.id)), 0) <= 0:
                continue
            payload[str(cat.id)].append({
                "source_type": "request",
                "source_id": str(row.id),
                "name": guest_name,
                "company": row.guest_company or ("Pendiente de aprobar" if is_pending_approval else ("Ampliada tras el envío" if row_sent_ish else "Petición aprobada")),
                "photo_url": vis["photo"] or row.requester_photo_url or placeholder_photo,
                # Visual del invitado (foto/logo + vínculo) para la tarjeta del asignador.
                "guest_photo": vis["photo"] or "",
                "guest_link_text": vis["link"] or "",
                "guest_link_logo": vis["link_logo"] or "",
                "guest_link_type": vis["link_type"] or "",
                "requester": row.requester_nick or row.requester_email or "",
                "requester_name": row.requester_nick or row.requester_email or "",
                "requester_photo": row.requester_photo_url or placeholder_photo,
                "note": note,
                "date_label": _invitation_display_datetime(row.created_at),
                "qty": pending,
                "qty_total": _safe_int(qty),
                "assigned": assigned,
                "pending_approval": is_pending_approval,
                "category_id": str(cat.id),
                "category_name": name_map.get(str(cat.id), "Categoría"),
            })
    return payload


def _invitation_assign_context(session_db, concert, categories) -> dict:
    """Todo lo que necesita el ASIGNADOR (modal): entradas, planos por categoría y tarjetas de
    pendientes. Lo comparten la página de invitaciones y el PARCIAL ligero que refresca el modal
    al abrirlo (abrir el asignador ya no paga el render de la página completa)."""
    name_map = _invitation_category_name_map(categories)
    ticket_rows = (
        session_db.query(InvitationTicket)
        .filter(InvitationTicket.concert_id == concert.id)
        .order_by(InvitationTicket.sector.asc().nullslast(), InvitationTicket.row_label.asc().nullslast(), InvitationTicket.seat_number.asc().nullslast(), InvitationTicket.uploaded_at.asc())
        .limit(1000)
        .all()
    )
    # Estado de envío/descarga (y tercero/artista invitado) de las solicitudes a las que están
    # asignadas las entradas, para mostrarlo al pinchar una invitación numerada y decidir si se
    # puede recuperar/desvincular.
    ticket_request_ids = {t.assigned_request_id for t in ticket_rows if getattr(t, 'assigned_request_id', None)}
    ticket_commitment_ids = {t.assigned_commitment_id for t in ticket_rows if getattr(t, 'assigned_commitment_id', None)}
    request_map: dict[str, dict] = {}
    if ticket_request_ids:
        _sent_statuses = {'ENVIADAS', 'ENTREGADAS_MANO', 'DISPONIBLES_TAQUILLA', 'RECOGIDAS_TAQUILLA'}
        for r in session_db.query(InvitationRequest).filter(InvitationRequest.id.in_(list(ticket_request_ids))).all():
            _ai = _invitation_assignee_visual(session_db, r)
            request_map[str(r.id)] = {
                'sent': bool(r.sent_at) or (r.status or '') in _sent_statuses,
                'downloaded': bool(r.downloaded_at) or _safe_int(r.downloaded_count) > 0,
                'guest_name': _ai['name'] or (r.guest_name or ''),
                'promoter_id': str(r.guest_promoter_id) if getattr(r, 'guest_promoter_id', None) else '',
                'artist_id': str(r.guest_artist_id) if getattr(r, 'guest_artist_id', None) else '',
                'photo': _ai['photo'],
                'link': _ai['link'],
                'link_logo': _ai['link_logo'],
                'link_type': _ai['link_type'],
                'total': _invitation_total_qty(_json_dict(r.quantities_json)),
                'requester': (r.requester_nick or r.requester_email or '').strip(),
            }
    commitment_map: dict[str, dict] = {}
    if ticket_commitment_ids:
        for c in session_db.query(InvitationCommitment).filter(InvitationCommitment.id.in_(list(ticket_commitment_ids))).all():
            _ai = _invitation_assignee_visual(session_db, c)
            commitment_map[str(c.id)] = {
                # Nombre = del COMPROMISO (no del destinatario); vínculo/foto del destinatario.
                'guest_name': (c.name or _ai['name'] or ''),
                'photo': _ai['photo'],
                'link': _ai['link'],
                'link_logo': _ai['link_logo'],
                'link_type': _ai['link_type'],
                'total': _invitation_total_qty(_json_dict(c.quantities_json)),
                'requester': (c.created_by_nick or '').strip(),
            }
    tickets = [_invitation_ticket_payload(t, name_map, request_map, commitment_map) for t in ticket_rows]
    # PLANO DEL RECINTO en el asignador: se casa cada entrada numerada con el mapa
    # (sector/fila/asiento → "sec|fila|slot") para colocarla en su butaca REAL del plano
    # completo. Sin mapa o sin casar, el asignador sigue con sus planos por sector de siempre.
    assign_map = None
    try:
        if getattr(concert, 'venue_id', None):
            _sm_asg = _concert_seatmap(session_db, concert)
            _lay_asg = (_sm_asg.layout_json or {}) if _sm_asg is not None else {}
            if _lay_asg.get('sections'):
                _lk_asg = seatmap_calc.seat_lookup(_lay_asg)
                _n_match = 0
                for item in tickets:
                    if not (item.get('seat_number') or '').strip():
                        continue
                    _mk = seatmap_calc.match_ticket(_lk_asg, item.get('sector'), item.get('row_label'), item.get('seat_number'))
                    if _mk:
                        item['map_key'] = _mk
                        _n_match += 1
                if _n_match:
                    assign_map = {'layout': _lay_asg, 'version': int(_sm_asg.version or 0), 'name': _sm_asg.name or ''}
    except Exception:
        assign_map = None
    tickets_by_category = {str(c.id): [] for c in categories}
    for item in tickets:
        tickets_by_category.setdefault(str(item['category_id']), []).append(item)
    uncategorized_tickets = tickets_by_category.get('None', [])
    _cat_by_id = {str(c.id): c for c in categories}
    ticket_groups_by_category = {
        cid: _invitation_ticket_groups(rows, category=_cat_by_id.get(cid), concert=concert)
        for cid, rows in tickets_by_category.items()
    }
    availability_by_category = {
        cid: _invitation_availability_breakdown(rows)
        for cid, rows in tickets_by_category.items()
    }
    pending_assignments = _invitation_pending_assignment_payloads(session_db, concert, categories)
    return {
        'tickets': tickets,
        'tickets_by_category': tickets_by_category,
        'uncategorized_tickets': uncategorized_tickets,
        'ticket_groups_by_category': ticket_groups_by_category,
        'availability_by_category': availability_by_category,
        'pending_assignments': pending_assignments,
        'assign_map': assign_map,
    }


def _invitation_request_uses_only_guest_list(session_db, row: InvitationRequest) -> bool:
    quantities = _json_dict(row.quantities_json)
    if not quantities:
        return False
    categories = _invitation_get_categories(session_db, row.concert or session_db.get(Concert, row.concert_id), ensure_defaults=False) if row.concert_id else []
    cat_map = {str(c.id): c for c in categories}
    matched = False
    for cid, qty in quantities.items():
        if _safe_int(qty) <= 0:
            continue
        cat = cat_map.get(str(cid))
        if not cat or (cat.ticket_kind or "").upper() != "GUEST_LIST":
            return False
        matched = True
    return matched


def _invitation_quantities_from_form(form, categories: list[InvitationCategory] | None = None, prefix: str = "qty") -> dict:
    quantities: dict[str, int] = {}
    cats = categories or []
    # Categorías con peticiones BLOQUEADAS: se ignoran (no se pueden pedir invitaciones para ellas).
    blocked = {str(c.id) for c in cats if getattr(c, "requests_blocked", False)}
    category_ids = [str(c.id) for c in cats]
    if category_ids:
        for cid in category_ids:
            if cid in blocked:
                continue
            val = _safe_int(form.get(f"{prefix}_{cid}"))
            if val > 0:
                quantities[cid] = val
    raw = form.get("quantities_json")
    if raw:
        for k, v in _json_dict(raw).items():
            if str(k) in blocked:
                continue
            val = _safe_int(v)
            if val > 0:
                quantities[str(k)] = val
    total = _safe_int(form.get(f"{prefix}_total") or form.get("qty_total"))
    if not quantities and total > 0:
        quantities["TOTAL"] = total
    return quantities


def _invitation_total_qty(quantities: dict | None) -> int:
    return sum(_safe_int(v) for v in (quantities or {}).values())


def _invitation_category_name_map(categories: list[InvitationCategory]) -> dict[str, str]:
    return {str(c.id): c.name for c in categories}


def _invitation_quantities_label(quantities: dict | None, name_map: dict[str, str] | None = None) -> str:
    q = quantities or {}
    if not q:
        return "0"
    pieces = []
    for cid, qty in q.items():
        qty = _safe_int(qty)
        if qty <= 0:
            continue
        name = (name_map or {}).get(str(cid)) or ("Total" if str(cid) == "TOTAL" else "Categoría")
        pieces.append(f"{name}: {qty}")
    return " · ".join(pieces) or "0"


def _invitation_categories_label(quantities: dict | None, name_map: dict[str, str] | None = None) -> str:
    """Nombres de las categorías solicitadas, SIN cantidades (el total ya se muestra aparte).
    P. ej. 'Palco Super VIP 2 · Palco Super VIP 4'. Ignora la clave TOTAL (peticiones sin categorizar)."""
    q = quantities or {}
    pieces = []
    for cid, qty in q.items():
        if _safe_int(qty) <= 0:
            continue
        if str(cid) == "TOTAL":
            continue
        name = (name_map or {}).get(str(cid))
        if name:
            pieces.append(name)
    return " · ".join(pieces)


def _invitation_status_badge(status: str | None) -> str:
    """Color del estado para QUIEN GESTIONA: solicitadas/comprometidas en GRIS; aprobadas en AZUL;
    asignadas en AMARILLO; enviadas / en taquilla / recogidas en VERDE; denegadas en rojo."""
    s = (status or "SOLICITADAS").upper()
    if s in {"ENVIADAS", "ENTREGADAS_MANO", "DISPONIBLES_TAQUILLA", "RECOGIDAS_TAQUILLA"}:
        return "success"
    if s == "ASIGNADAS":
        return "warning text-dark"
    if s == "PARCIAL":
        return "warning text-dark"  # naranja: hay asignadas/enviadas y quedan por asignar
    if s == "APROBADAS":
        return "info text-dark"
    if s in {"RECHAZADAS", "ANULADAS"}:
        return "danger"
    return "secondary"  # SOLICITADAS / COMPROMETIDAS → gris


def _invitation_requester_status(status: str | None) -> tuple[str, str]:
    """(etiqueta, color) que ve EL PETICIONARIO: solo solicitada / aprobada / enviada / denegada.
    No se le muestran los estados internos de gestión (asignadas, taquilla, recogidas...)."""
    s = (status or "SOLICITADAS").upper()
    if s in {"ENVIADAS", "ENTREGADAS_MANO", "DISPONIBLES_TAQUILLA", "RECOGIDAS_TAQUILLA"}:
        return ("Enviadas", "success")
    if s in {"APROBADAS", "ASIGNADAS", "PARCIAL"}:
        return ("Aprobadas", "info text-dark")
    if s == "RECHAZADAS":
        return ("Rechazadas", "danger")
    if s == "ANULADAS":
        return ("Anuladas", "secondary")
    return ("Solicitadas", "secondary")


def _invitation_commitment_state_from_statuses(statuses) -> tuple[str, str]:
    """(etiqueta, color) del estado de un compromiso EN UNA CATEGORÍA según el estado de sus entradas.
    Los compromisos NO tienen 'aprobadas': asignadas (amarillo) → enviadas / en taquilla (verde) →
    recogidas (verde)."""
    s = set((x or "").upper() for x in (statuses or []))
    if not s:
        return ("Sin asignar", "secondary")
    if "ASSIGNED" in s:
        return ("Asignadas", "warning text-dark")
    if s <= {"RECOGIDAS_TAQUILLA", "PICKED_UP"}:
        return ("Recogidas", "success")
    if s <= {"DISPONIBLES_TAQUILLA", "RECOGIDAS_TAQUILLA", "PICKED_UP"}:
        return ("En taquilla", "success")
    return ("Enviadas", "success")


def _invitation_request_payload(row: InvitationRequest, categories: list[InvitationCategory] | None = None) -> dict:
    name_map = _invitation_category_name_map(categories or [])
    quantities = _json_dict(row.quantities_json)
    # Categorías solicitadas: nombres reales (Palco de Honor, Palco Super VIP, Pista General…) SIN
    # cantidades, porque el total ya se muestra en su propio badge.
    categories_label = _invitation_categories_label(quantities, name_map)
    # Identidad ACTUAL del invitado (nombre, foto, email, teléfono, vínculo) resuelta EN VIVO desde la
    # entidad vinculada, para que TODA la gestión de invitaciones trabaje siempre sobre lo más
    # actualizado, sin importar dónde se cambiaran los datos de la ficha.
    try:
        _sess = row._sa_instance_state.session
    except Exception:
        _sess = None
    if _sess is not None:
        _idn = _invitation_guest_identity(_sess, row)
    else:
        _idn = {"name": row.guest_name, "photo": "", "email": row.guest_email or "", "phone": row.guest_phone or "", "link_summary": {}}
    guest_name = _idn.get("name") or row.guest_name
    guest_photo = _idn.get("photo") or ""
    # Artista sin foto propia → foto del artista del evento (es su foto, no un vínculo).
    if not guest_photo and getattr(row, "guest_artist_id", None) and _sess is not None:
        try:
            _c = getattr(row, "concert", None)
            _ar = _concert_artist_rows(_sess, _c) if _c else []
            if _ar:
                guest_photo = getattr(_ar[0], "photo_url", "") or ""
        except Exception:
            pass
    # Vínculo: en vivo si hay entidad; si no, lo guardado en la solicitud.
    link_summary = _idn.get("link_summary") or _json_dict(getattr(row, "guest_link_summary", None))
    _cur_email = _idn.get("email") or ""
    _cur_phone = _idn.get("phone") or ""
    # Peticionario y registrador EN VIVO (nombre + foto) desde su perfil, para reflejar cambios de
    # nombre del personal de la oficina (antes se quedaba el snapshot: "digital" en vez del nombre real).
    _req_nick = (row.requester_nick or "").strip()
    _req_photo = (row.requester_photo_url or "").strip()
    _cb_nick = (getattr(row, "created_by_nick", None) or "").strip()
    if _sess is not None:
        if getattr(row, "requester_user_id", None):
            _rp = _sess.get(UserProfile, row.requester_user_id)
            if _rp:
                _req_nick = _profile_full_name(_rp) or getattr(_rp, "nick", "") or _req_nick
                _req_photo = getattr(_rp, "photo_url", "") or _req_photo
        if getattr(row, "created_by_user_id", None):
            _cbp = _sess.get(UserProfile, row.created_by_user_id)
            if _cbp:
                _cb_nick = _profile_full_name(_cbp) or getattr(_cbp, "nick", "") or _cb_nick
    # Etiqueta de estado por CUPO:
    #  · cupo completo asignado → Asignadas/Enviadas (según envíos).
    #  · algo asignado/enviado pero faltan → «Sin asignar parcialmente» (PARCIAL, naranja).
    #  · nada asignado → Solicitadas/Aprobadas.
    _display_status = row.status or "SOLICITADAS"
    _needs_assign = False
    _needs_send = False
    _needs_download = False
    _status_split = None
    _downloaded_partial = False
    _reforwarded_partial = False
    if _sess is not None and _display_status not in _INVITATION_MANUAL_REQUEST_STATUSES:
        _qty_total = _invitation_total_qty(quantities)
        _asg_total = _invitation_request_assigned_total(_sess, row)
        _sent_total = _invitation_request_sent_total(_sess, row)
        _pend = max(_qty_total - _asg_total, 0)
        if _qty_total > 0 and 0 < _asg_total < _qty_total:
            _display_status = "PARCIAL"
        elif _display_status == "ASIGNADAS" and _qty_total > 0 and _asg_total < _qty_total:
            _display_status = "APROBADAS"
        # ETIQUETA PARTIDA (ampliaciones): mitad del color de lo logrado + mitad de lo que falta.
        #  · quedan por asignar y ya hay asignadas/enviadas → verde|azul (si hubo envío) o
        #    amarillo|azul, con «X/X pendientes».
        #  · todo asignado pero envío parcial (ampliada ya asignada) → amarillo|verde con
        #    «X/X enviadas»; al enviar de nuevo, todo verde.
        if _qty_total > 0 and _pend > 0 and _asg_total > 0:
            _status_split = {
                "left_badge": ("success" if _sent_total > 0 else "warning text-dark"),
                "left_text": ("%d env." % _sent_total) if _sent_total > 0 else ("%d asig." % _asg_total),
                "right_badge": "info text-dark",
                "right_text": "%d/%d pendientes" % (_pend, _qty_total),
                "title": "Asignadas %d · Enviadas %d · Pendientes de asignar %d (de %d): la ampliación espera en el asignador." % (_asg_total, _sent_total, _pend, _qty_total),
            }
        elif _qty_total > 0 and _pend == 0 and 0 < _sent_total < _asg_total:
            _status_split = {
                "left_badge": "warning text-dark",
                "left_text": "%d sin enviar" % (_asg_total - _sent_total),
                "right_badge": "success",
                "right_text": "%d/%d enviadas" % (_sent_total, _qty_total),
                "title": "Asignadas %d · Enviadas %d: al enviar TODO de nuevo, las nuevas van con la etiqueta azul «Nueva» (si envías solo las nuevas, sin etiqueta)." % (_asg_total, _sent_total),
            }
        # Para los filtros «Sin asignar» / «Sin enviar» / «Sin descargar» del listado de invitados.
        _needs_assign = bool(_qty_total > 0 and _asg_total < _qty_total)
        _needs_send = bool(_asg_total > 0 and _sent_total < _asg_total)
        _needs_download = bool(_sent_total > 0) and not (
            bool(getattr(row, "downloaded_at", None)) or _safe_int(getattr(row, "downloaded_count", 0)) > 0
        )
        # Descarga / reenvío PARCIALES: se hicieron ANTES de asignar entradas nuevas (ampliación)
        # → la marca se muestra a medias (verde|amarillo) hasta que se repitan con todo.
        _last_added = _invitation_request_last_added_at(_sess, row)
        if _last_added is not None:
            if getattr(row, "downloaded_at", None) and row.downloaded_at < _last_added:
                _downloaded_partial = True
            if getattr(row, "reforwarded_at", None) and row.reforwarded_at < _last_added:
                _reforwarded_partial = True
    # Correo EFECTIVO del destinatario (para el botón «Enviar por email»): según el modo de recepción.
    # Para EMPLOYEE (miembro de la oficina) el snapshot del payload puede estar vacío -> se resuelve
    # EN VIVO por el id del usuario (así no falla «no tiene correo» con gente que sí tiene email).
    _rp = _json_dict(row.receiver_payload)
    _rmode = (row.receiver_mode or "GUEST").upper()
    if _rmode in ("GUEST", "BOX_OFFICE", "DOOR"):
        _recipient_email = _cur_email or (_rp.get("email") or "")
    elif _rmode == "ME":
        _recipient_email = (_rp.get("email") or row.requester_email or "")
    elif _rmode == "EMPLOYEE":
        _recipient_email = (_rp.get("email") or "").strip()
        if not _recipient_email and _rp.get("user_id"):
            _euid = _safe_uuid(_rp.get("user_id"))
            if _euid:
                _s2 = db()
                try:
                    _eu = _s2.get(User, _euid)
                    _recipient_email = (getattr(_eu, "email", None) or "").strip()
                finally:
                    _s2.close()
    else:  # OTHER
        _recipient_email = (_rp.get("email") or row.guest_email or "")
    return {
        "id": str(row.id),
        "guest_name": guest_name,
        "guest_promoter_id": str(row.guest_promoter_id) if getattr(row, "guest_promoter_id", None) else "",
        "guest_photo_url": guest_photo or url_for("static", filename="img/placeholder_photo.png"),
        "guest_photo": guest_photo,  # foto/logo PROPIO (vacío si no tiene): la lista solo pinta avatar si hay
        "guest_company": row.guest_company or "",
        "guest_title": getattr(row, "guest_title", None) or row.guest_company or "",
        "guest_email": _cur_email or "",
        "recipient_email": _recipient_email or "",
        "guest_phone": _cur_phone or "",
        "requester_nick": _req_nick or row.requester_email or "—",
        "requester_photo_url": _req_photo or url_for("static", filename="img/placeholder_photo.png"),
        "receiver_mode": row.receiver_mode or "GUEST",
        "receiver_payload": _json_dict(row.receiver_payload),
        "quantities": quantities,
        "qty_total": _invitation_total_qty(quantities),
        "quantities_label": _invitation_quantities_label(quantities, name_map),
        "categories_label": categories_label,
        "status": row.status or "SOLICITADAS",
        "status_label": INVITATION_STATUS_LABELS.get(_display_status, _display_status or "Solicitadas"),
        "status_badge": _invitation_status_badge(_display_status),
        "status_split": _status_split,
        "downloaded_partial": _downloaded_partial,
        "reforwarded_partial": _reforwarded_partial,
        "needs_assign": _needs_assign,
        "needs_send": _needs_send,
        "needs_download": _needs_download,
        "requester_status_label": _invitation_requester_status(_display_status)[0],
        "requester_status_badge": _invitation_requester_status(_display_status)[1],
        "link_summary": link_summary,
        "link_summary_text": _promoter_link_summary_text(link_summary),
        "note": row.note or "",
        "created_at_label": _invitation_display_datetime(row.created_at),
        "sent_at_label": _invitation_display_datetime(getattr(row, 'sent_at', None)),
        "sent_via": (getattr(row, 'sent_via', None) or ''),
        "sent_to": (getattr(row, 'sent_to', None) or ''),
        "downloaded_at_label": _invitation_display_datetime(row.downloaded_at),
        "downloaded_count": _safe_int(row.downloaded_count),
        "reforwarded": bool(getattr(row, "reforwarded_at", None)),
        "reforwarded_at_label": _invitation_display_datetime(getattr(row, "reforwarded_at", None)),
        # ¿Hay entradas enviadas Y otras nuevas sin enviar (ampliación tras envío)? → preguntar al enviar.
        "has_partial_sent": bool(
            _sess is not None
            and _invitation_request_sent_total(_sess, row) > 0
            and _invitation_request_assigned_total(_sess, row) > _invitation_request_sent_total(_sess, row)
        ),
        "can_edit_public": (row.status or "") in {"SOLICITADAS", "APROBADAS"},
        "download_url": url_for("invitation_request_download", token=row.delivery_token) if row.delivery_token else "",
        "download_url_abs": _external_url_for("invitation_request_download", token=row.delivery_token) if row.delivery_token else "",
        "created_by_nick": _cb_nick,
        "registered_by_other": bool(getattr(row, "created_by_user_id", None)) and str(getattr(row, "created_by_user_id", "") or "") != str(getattr(row, "requester_user_id", "") or ""),
    }


def _invitation_ficha_overview(session_db, concert, categories) -> list[dict]:
    """Compromisos y peticiones del evento agrupados por categoría para la ficha del concierto.

    Cada petición/compromiso aparece bajo cada categoría en la que tenga cantidad > 0; los que no
    encajan en ninguna van a un grupo 'Sin categoría'. Incluye foto y vínculo del invitado."""
    cat_objs = list(categories or [])
    cat_order = [str(c.id) for c in cat_objs]
    cat_name = {str(c.id): c.name for c in cat_objs}
    cat_kind = {str(c.id): (c.ticket_kind or 'PDF_UNNUMBERED') for c in cat_objs}
    groups = {cid: {"category_id": cid, "category_name": cat_name[cid], "ticket_kind": cat_kind[cid], "commitments": [], "requests": []} for cid in cat_order}
    sin = {"category_id": "", "category_name": "Sin categoría", "ticket_kind": "", "commitments": [], "requests": []}

    reqs = (
        session_db.query(InvitationRequest)
        .filter(InvitationRequest.concert_id == concert.id)
        .filter(InvitationRequest.status.notin_(['RECHAZADAS', 'ANULADAS']))
        .order_by(InvitationRequest.created_at.asc())
        .all()
    )
    for row in reqs:
        payload = _invitation_request_payload(row, cat_objs)
        quantities = payload.get("quantities") or {}
        placed = False
        for cid in cat_order:
            qty = _safe_int(quantities.get(cid))
            if qty > 0:
                item = dict(payload)
                item["qty"] = qty
                groups[cid]["requests"].append(item)
                placed = True
        if not placed:
            item = dict(payload)
            item["qty"] = payload.get("qty_total") or 0
            sin["requests"].append(item)

    for row in (
        session_db.query(InvitationCommitment)
        .filter(InvitationCommitment.concert_id == concert.id)
        .filter(InvitationCommitment.status != 'ANULADAS')
        .order_by(InvitationCommitment.created_at.asc())
        .all()
    ):
        quantities = _json_dict(row.quantities_json)
        base = {
            "id": str(row.id),
            "name": row.name,
            "reason": row.reason or "",
            "photo_url": (getattr(row.promoter, "logo_url", None) if getattr(row, "promoter", None) else None) or url_for("static", filename="img/placeholder_photo.png"),
        }
        placed = False
        for cid in cat_order:
            qty = _safe_int(quantities.get(cid))
            if qty > 0:
                item = dict(base)
                item["qty"] = qty
                groups[cid]["commitments"].append(item)
                placed = True
        if not placed:
            item = dict(base)
            item["qty"] = _invitation_total_qty(quantities)
            sin["commitments"].append(item)

    out = [groups[cid] for cid in cat_order]
    if sin["requests"] or sin["commitments"]:
        out.append(sin)
    return [g for g in out if g["requests"] or g["commitments"]]


def _invitation_ficha_guests(session_db, concert):
    """Compromisos + peticiones agrupadas del evento con los MISMOS payloads y estética que la
    pestaña «Invitados» de gestión de invitaciones (``invitation_event_detail``), para mostrarlos
    idénticos en la ficha de la actividad (también en las pasadas, donde ya no hay gestión).

    Solo lectura: reutiliza los mismos helpers atómicos que la gestión para que la información y
    los colores/categorías coincidan. Devuelve ``(commitments, grouped_requests)``.
    """
    categories = _invitation_get_categories(session_db, concert, ensure_defaults=False)
    ticket_counts = _invitation_ticket_counts_by_category(session_db, concert)
    cat_payloads = [_invitation_category_payload(c, ticket_counts.get(str(c.id))) for c in categories]
    for _i, _cp in enumerate(cat_payloads):
        _cp['color'] = INVITATION_ASSIGNEE_COLORS[_i % len(INVITATION_ASSIGNEE_COLORS)]
    _cat_meta = {cp['id']: cp for cp in cat_payloads}
    name_map = _invitation_category_name_map(categories)

    _cmt_rows_all = session_db.query(InvitationCommitment).filter(InvitationCommitment.concert_id == concert.id).order_by(InvitationCommitment.created_at.asc()).all()
    _req_rows_all = session_db.query(InvitationRequest).filter(InvitationRequest.concert_id == concert.id).order_by(InvitationRequest.created_at.desc()).all()
    _tk_by_cmt: dict = defaultdict(lambda: defaultdict(list))
    for _st, _cidt, _cmid in (session_db.query(InvitationTicket.status, InvitationTicket.category_id, InvitationTicket.assigned_commitment_id)
                              .filter(InvitationTicket.concert_id == concert.id, InvitationTicket.assigned_commitment_id.isnot(None)).all()):
        _tk_by_cmt[str(_cmid)][str(_cidt)].append(_st)

    commitments = []
    for row in _cmt_rows_all:
        q = _json_dict(row.quantities_json)
        _tk_by_cat = _tk_by_cmt.get(str(row.id)) or {}
        _dl_cats = _json_dict(getattr(row, "downloaded_categories_json", None))
        cat_status = []
        for _cid, _qv in q.items():
            if str(_cid) == 'TOTAL':
                continue
            _qn = _safe_int(_qv)
            if _qn <= 0:
                continue
            _sts = _tk_by_cat.get(str(_cid), [])
            _asg = len(_sts)
            _lbl, _bdg = _invitation_commitment_state_from_statuses(_sts)
            if _asg < _qn:
                _lbl, _bdg = ("Sin asignar parcialmente", "warning text-dark") if _asg > 0 else ("Sin asignar", "secondary")
            if not _sts and (getattr(row, "status", "") or "").upper() == "ENVIADAS":
                _lbl, _bdg = ("Enviadas", "success")
            _meta = _cat_meta.get(str(_cid), {})
            cat_status.append({
                "id": str(_cid), "name": name_map.get(str(_cid), "Categoría"), "qty": _qn,
                "assigned": _asg, "done": _asg >= _qn, "status_label": _lbl, "status_badge": _bdg,
                "downloaded": str(_cid) in _dl_cats, "color": _meta.get("color", "#9ca3af"),
                "zone": _meta.get("zone", "PISTA"), "configured": _safe_int(_meta.get("configured", 0)),
            })
        _idn = _invitation_guest_identity(session_db, row)
        _rcpt_name = _idn.get("name") or row.guest_name or ""
        _rcpt_photo = _idn.get("photo") or ""
        _rcpt_link_summary = _idn.get("link_summary") or {}
        if not _rcpt_photo and row.guest_artist_id:
            _ar = _concert_artist_rows(session_db, concert) if concert else []
            if _ar:
                _rcpt_photo = getattr(_ar[0], "photo_url", "") or ""
        _cb_nick = (row.created_by_nick or "").strip()
        _cb_photo = ""
        if row.created_by_user_id:
            _cbp = session_db.get(UserProfile, row.created_by_user_id)
            if _cbp:
                _cb_nick = _cb_nick or _profile_full_name(_cbp) or getattr(_cbp, 'nick', '') or ""
                _cb_photo = getattr(_cbp, 'photo_url', '') or ""
        commitments.append({
            "id": str(row.id), "name": row.name, "reason": row.reason or "",
            "quantities_label": _invitation_quantities_label(q, name_map),
            "category_status": cat_status, "status": row.status,
            "sent_via": (getattr(row, 'sent_via', None) or ''), "sent_to": (getattr(row, 'sent_to', None) or ''),
            "note": row.note or "", "created_by_nick": _cb_nick, "created_by_photo": _cb_photo,
            "recipient_name": _rcpt_name, "recipient_photo": _rcpt_photo,
            "recipient_link_summary": _rcpt_link_summary,
            "recipient_link_summary_text": _promoter_link_summary_text(_rcpt_link_summary),
            "guest_type": ('THIRD_PARTY' if row.guest_promoter_id else 'ARTIST' if row.guest_artist_id else 'EMPLOYEE' if row.guest_user_id else ''),
        })

    requests = []
    for row in _req_rows_all:
        if (row.status or '') in {'RECHAZADAS', 'ANULADAS'}:
            continue
        item = _invitation_request_payload(row, categories)
        item.update(_invitation_request_kind_flags(session_db, row, categories))
        requests.append(item)
    _invitation_group_requests(requests, categories)
    committed = _invitation_committed_palco_labels(session_db, concert, categories)
    for _cid_full in _invitation_request_excluded_category_ids(session_db, concert, categories):
        committed.setdefault(_cid_full, '')
    grouped_requests = _invitation_grouped(requests, categories, locked_labels=committed)
    return commitments, grouped_requests


def _invitation_event_cutoff_datetime(concert: Concert | None):
    """Devuelve el corte operativo de invitaciones: 05:00 del día posterior al evento.

    Las invitaciones deben seguir disponibles durante la madrugada posterior al concierto
    para permitir gestión en puerta/taquilla, pero no deben aparecer ni poder solicitarse
    cuando ya han pasado 5 horas desde el cierre del día del evento.
    """
    event_date = getattr(concert, "date", None)
    if not event_date:
        return None
    try:
        if isinstance(event_date, datetime):
            event_date = event_date.date()
        return datetime.combine(event_date + timedelta(days=1), datetime.min.time(), tzinfo=TZ_MADRID).replace(hour=5, minute=0, second=0, microsecond=0)
    except Exception:
        return None


def _invitation_event_is_active_for_requests(concert: Concert | None, *, now_value=None) -> bool:
    """Indica si un evento puede aparecer en Pedir/Gestionar invitaciones.

    Regla de negocio: desaparece 5 horas después del día del concierto/evento.
    """
    cutoff = _invitation_event_cutoff_datetime(concert)
    if not cutoff:
        return True
    now_value = now_value or _now_madrid()
    try:
        if getattr(now_value, "tzinfo", None) is None:
            now_value = now_value.replace(tzinfo=TZ_MADRID)
        return now_value < cutoff
    except Exception:
        return True


def _invitation_event_query_start_date() -> date:
    """Fecha mínima SQL amplia para no perder eventos de ayer antes de las 05:00."""
    now_value = _now_madrid()
    return now_value.date() - timedelta(days=1 if now_value.hour < 5 else 0)


def _invitation_concert_visible_for_user(concert: Concert | None) -> bool:
    """Oculta solicitudes personales 5h después del día del concierto/evento."""
    return _invitation_event_is_active_for_requests(concert)


def _user_is_ticketing(state: dict | None = None) -> bool:
    """True si el usuario actual pertenece al departamento de Ticketing."""
    state = state or _current_user_state()
    return any(str(d).strip().lower() == "ticketing" for d in (state.get("departments") or []))


def _concert_is_group_promoted(session_db, concert) -> bool:
    """True si una empresa del grupo participa como promotora (group_company_id) o como
    socio (ConcertCompanyShare) en el concierto/actividad."""
    if not concert:
        return False
    if getattr(concert, "group_company_id", None):
        return True
    cid = getattr(concert, "id", None)
    if not cid:
        return False
    try:
        return session_db.query(ConcertCompanyShare.id).filter(ConcertCompanyShare.concert_id == cid).first() is not None
    except Exception:
        return False


def _filter_manageable_concerts(session_db, concerts, state: dict | None = None) -> list:
    """Devuelve solo los conciertos que el usuario actual puede GESTIONAR en invitaciones.

    Criterio de negocio:
      - Rol 10 (dirección): todos.
      - Requiere acceso a 'invitaciones.gestionar'.
      - Producción (artistas asignados): conciertos de esos artistas cuyo promotor NO sea una
        empresa del grupo (sin group_company_id ni participación del grupo).
      - Ticketing: solo conciertos cuyo promotor SÍ sea una empresa del grupo (group_company_id
        o participación vía ConcertCompanyShare).
      - Además, los añadidos manualmente vía 'Gestionar otros' (opt-in), sin filtrar por grupo.
    """
    concerts = [c for c in (concerts or []) if c is not None]
    if not concerts:
        return []
    state = state or _current_user_state()
    if int(state.get("role") or 0) == 10:
        return list(concerts)
    if not _state_has_access(state, "invitaciones.gestionar", include_descendants=True):
        return []
    uid = _safe_uuid(state.get("user_id"))
    assigned = {str(x) for x in (state.get("assigned_artist_ids") or []) if x}
    is_ticketing = _user_is_ticketing(state)
    concert_ids = [c.id for c in concerts if getattr(c, "id", None)]
    opt_in_ids: set[str] = set()
    group_share_ids: set[str] = set()
    if uid and concert_ids:
        for (cid,) in (
            session_db.query(InvitationManagerOptIn.concert_id)
            .filter(InvitationManagerOptIn.user_id == uid, InvitationManagerOptIn.concert_id.in_(concert_ids))
            .all()
        ):
            opt_in_ids.add(str(cid))
    # Conciertos con participación de una empresa del grupo (socio). Junto con group_company_id
    # define "el promotor es una empresa del grupo". Se carga SIEMPRE: producción los excluye y
    # ticketing los incluye.
    if concert_ids:
        for (cid,) in (
            session_db.query(ConcertCompanyShare.concert_id)
            .filter(ConcertCompanyShare.concert_id.in_(concert_ids))
            .distinct()
            .all()
        ):
            group_share_ids.add(str(cid))
    out = []
    for c in concerts:
        cid = str(getattr(c, "id", "") or "")
        if cid and cid in opt_in_ids:
            out.append(c)
            continue
        is_group = bool(getattr(c, "group_company_id", None)) or (cid in group_share_ids)
        # Producción: conciertos de sus artistas asignados con promotor externo (no del grupo).
        if assigned and not is_group and (assigned & set(_concert_artist_ids(c))):
            out.append(c)
            continue
        # Ticketing: solo conciertos cuyo promotor es una empresa del grupo.
        if is_ticketing and is_group:
            out.append(c)
            continue
    return out


def _user_can_manage_invitations(concert, *, state: dict | None = None, session_db=None) -> bool:
    """Indica si el usuario actual puede gestionar las invitaciones de un concierto concreto."""
    if not concert:
        return False
    own = False
    if session_db is None:
        session_db = db()
        own = True
    try:
        return bool(_filter_manageable_concerts(session_db, [concert], state=state))
    finally:
        if own:
            session_db.close()


def _ensure_can_manage_invitations(session_db, concert):
    """Aborta con 403 si el usuario actual no puede gestionar las invitaciones del concierto.
    Refuerza server-side la restricción que la UI ya aplica (artistas asignados / Ticketing /
    'Gestionar otros' / dirección)."""
    if not concert or not _user_can_manage_invitations(concert, session_db=session_db):
        abort(403)


def _invitation_request_visible_for_user(row: InvitationRequest | None) -> bool:
    if not row or (row.status or "") in {"RECHAZADAS", "ANULADAS"}:
        return False
    return _invitation_concert_visible_for_user(getattr(row, "concert", None))


def _invitation_request_assigned_total(session_db, row) -> int:
    """Total de entradas asignadas a una solicitud, con caché POR CONCIERTO en g: una única consulta
    agrupada por solicitud en vez de un COUNT por fila al pintar listados (con la BD en otra región,
    cada consulta extra son ~30 ms — los listados grandes tardaban segundos)."""
    cid = str(getattr(row, "concert_id", "") or "")
    cache = getattr(g, "_inv_req_assigned_totals", None)
    if cache is None:
        cache = {}
        try:
            g._inv_req_assigned_totals = cache
        except Exception:
            pass
    m = cache.get(cid)
    if m is None:
        m = {}
        try:
            for _rq, _n in session_db.query(InvitationTicket.assigned_request_id, func.count(InvitationTicket.id)).filter(
                    InvitationTicket.concert_id == row.concert_id,
                    InvitationTicket.assigned_request_id.isnot(None)).group_by(InvitationTicket.assigned_request_id).all():
                m[str(_rq)] = int(_n or 0)
        except Exception:
            m = {}
        cache[cid] = m
    return m.get(str(row.id), 0)


_INVITATION_TICKET_SENT_STATUSES = {"SENT", "DELIVERED", "PICKED_UP", "PRINTED", "DISPONIBLES_TAQUILLA"}
# Estados de solicitud "finales/manuales" que NO se recalculan automáticamente desde las entradas.
_INVITATION_MANUAL_REQUEST_STATUSES = {"RECHAZADAS", "ANULADAS", "ENTREGADAS_MANO", "DISPONIBLES_TAQUILLA", "RECOGIDAS_TAQUILLA"}


def _invitation_sync_request_status(session_db, row) -> None:
    """Recalcula el status de una SOLICITUD desde sus entradas (fuente de verdad).

    Evita el desajuste "en el mapa asignadas/enviadas pero la solicitud sigue pendiente":
      - alguna entrada enviada -> ENVIADAS
      - alguna asignada (no enviada) -> ASIGNADAS
      - ninguna -> vuelve a APROBADAS si venía de ASIGNADAS/ENVIADAS
    No toca estados manuales (rechazada/anulada/entregada en mano/taquilla).
    """
    if row is None:
        return
    cur = (row.status or "").upper()
    if cur in _INVITATION_MANUAL_REQUEST_STATUSES:
        return
    qty_total = _invitation_total_qty(_json_dict(getattr(row, "quantities_json", None)))
    tickets = session_db.query(InvitationTicket).filter(InvitationTicket.assigned_request_id == row.id).all()
    assigned = len(tickets)
    sent = sum(1 for t in tickets if (t.status or "").upper() in _INVITATION_TICKET_SENT_STATUSES)
    # OJO ampliaciones: el estado guardado CONSERVA lo logrado (ENVIADAS/ASIGNADAS); lo que falte
    # por asignar se refleja aparte (etiqueta partida X/X pendientes + asignador), no degradando.
    if sent > 0:
        if cur not in INVITATION_SENT_STATUSES:
            row.status = "ENVIADAS"
            if not row.sent_at:
                row.sent_at = _now_madrid()
    elif assigned > 0:
        row.status = "ASIGNADAS"
        if not row.assigned_at:
            row.assigned_at = _now_madrid()
    else:
        if cur in ("ASIGNADAS", "ENVIADAS"):
            row.status = "APROBADAS"


def _invitation_sync_commitment_status(session_db, row) -> None:
    """Igual que la de solicitudes pero para un COMPROMISO."""
    if row is None:
        return
    cur = (row.status or "").upper()
    if cur in {"ANULADAS"}:
        return
    qty_total = _invitation_total_qty(_json_dict(getattr(row, "quantities_json", None)))
    tickets = session_db.query(InvitationTicket).filter(InvitationTicket.assigned_commitment_id == row.id).all()
    assigned = len(tickets)
    sent = sum(1 for t in tickets if (t.status or "").upper() in _INVITATION_TICKET_SENT_STATUSES)
    # Igual que en solicitudes: la ampliación NO degrada el estado guardado; lo pendiente se ve en
    # las etiquetas por categoría y en el asignador (por métricas).
    if sent > 0:
        row.status = "ENVIADAS"
    elif assigned > 0:
        row.status = "ASIGNADAS"
    else:
        if cur in ("ASIGNADAS", "ENVIADAS"):
            row.status = "COMPROMETIDAS"


def _invitation_request_last_added_at(session_db, row):
    """Última entrada ASIGNADA a la solicitud (max assigned_at), con caché por concierto en g.
    Sirve para detectar descargas/reenvíos PARCIALES: el invitado descargó/reenvió y DESPUÉS se le
    asignaron entradas nuevas (ampliación) → la marca queda a medias hasta repetirse."""
    cid = str(getattr(row, "concert_id", "") or "")
    cache = getattr(g, "_inv_req_last_added", None)
    if cache is None:
        cache = {}
        try:
            g._inv_req_last_added = cache
        except Exception:
            pass
    m = cache.get(cid)
    if m is None:
        m = {}
        try:
            for _rq, _mx in session_db.query(InvitationTicket.assigned_request_id, func.max(InvitationTicket.assigned_at)).filter(
                    InvitationTicket.concert_id == row.concert_id,
                    InvitationTicket.assigned_request_id.isnot(None)).group_by(InvitationTicket.assigned_request_id).all():
                m[str(_rq)] = _mx
        except Exception:
            m = {}
        cache[cid] = m
    return m.get(str(row.id))


def _invitation_request_sent_total(session_db, row) -> int:
    """Nº de entradas de la solicitud YA enviadas (status SENT/…), con caché por concierto en g.
    Sirve para detectar «ampliación tras envío»: hay enviadas y también nuevas sin enviar."""
    cid = str(getattr(row, "concert_id", "") or "")
    cache = getattr(g, "_inv_req_sent_totals", None)
    if cache is None:
        cache = {}
        try:
            g._inv_req_sent_totals = cache
        except Exception:
            pass
    m = cache.get(cid)
    if m is None:
        m = {}
        try:
            for _rq, _n in session_db.query(InvitationTicket.assigned_request_id, func.count(InvitationTicket.id)).filter(
                    InvitationTicket.concert_id == row.concert_id,
                    InvitationTicket.assigned_request_id.isnot(None),
                    InvitationTicket.status.in_(list(_INVITATION_TICKET_SENT_STATUSES))).group_by(InvitationTicket.assigned_request_id).all():
                m[str(_rq)] = int(_n or 0)
        except Exception:
            m = {}
        cache[cid] = m
    return m.get(str(row.id), 0)


def _invitation_request_kind_flags(session_db, row: InvitationRequest, categories: list[InvitationCategory]) -> dict:
    quantities = _json_dict(getattr(row, "quantities_json", None))
    cat_map = {str(c.id): c for c in (categories or [])}
    kinds = []
    for cid, qty in quantities.items():
        if _safe_int(qty) <= 0:
            continue
        cat = cat_map.get(str(cid))
        if cat:
            kinds.append((cat.ticket_kind or "PDF_UNNUMBERED").upper())
    uses_guest_list = bool(kinds) and all(k == "GUEST_LIST" for k in kinds)
    requires_numbered_assignment = any(k == "PDF_NUMBERED" for k in kinds)
    status = (getattr(row, "status", None) or "")
    assigned_or_sent = status in {"ASIGNADAS", "ENVIADAS", "ENTREGADAS_MANO", "DISPONIBLES_TAQUILLA", "RECOGIDAS_TAQUILLA"}
    # Solo se puede ENVIAR con el cupo COMPLETO asignado: una solicitud parcialmente asignada
    # no ofrece envío hasta completarla — también las AMPLIADAS tras el envío (primero se asigna
    # lo nuevo en el asignador; al reenviar se manda todo, con «Añadida» en las nuevas).
    fully_assigned = True
    pending_qty = 0
    if assigned_or_sent and not uses_guest_list:
        qty_total = sum(_safe_int(v) for k, v in quantities.items() if str(k) != "TOTAL")
        assigned_total = _invitation_request_assigned_total(session_db, row)
        pending_qty = max(qty_total - assigned_total, 0)
        fully_assigned = qty_total <= 0 or assigned_total >= qty_total
    return {
        "uses_guest_list": uses_guest_list,
        "requires_numbered_assignment": requires_numbered_assignment,
        "fully_assigned": fully_assigned,
        "can_send": uses_guest_list or (assigned_or_sent and fully_assigned),
        "can_download_pdf": assigned_or_sent and not uses_guest_list,
        # «Asignar» disponible también para las AMPLIADAS (enviadas/asignadas con pendientes) y
        # para las NUMERADAS (el auto-asignado coge butacas contiguas; afinar luego es opcional).
        "can_auto_assign": (
            status in {"SOLICITADAS", "APROBADAS"} or (pending_qty > 0 and status not in {"RECHAZADAS", "ANULADAS"})
        ),
    }


def _invitation_parse_ticket_kind_and_guest_mode(raw_kind: str | None, fallback_kind: str | None = None, fallback_guest_mode: str | None = None) -> tuple[str, str | None]:
    value = (raw_kind or fallback_kind or "PDF_UNNUMBERED").strip().upper()
    if value in {"GUEST_LIST_BOX_OFFICE", "GUEST_LIST_TAQUILLA", "LIST_BOX_OFFICE"}:
        return "GUEST_LIST", "BOX_OFFICE"
    if value in {"GUEST_LIST_DOOR", "LIST_DOOR", "GUEST_LIST_ACCESS"}:
        return "GUEST_LIST", "DOOR"
    if value == "GUEST_LIST":
        mode = (fallback_guest_mode or "BOX_OFFICE").strip().upper()
        return "GUEST_LIST", mode if mode in {"BOX_OFFICE", "DOOR"} else "BOX_OFFICE"
    if value not in {"PDF_UNNUMBERED", "PDF_NUMBERED"}:
        value = "PDF_UNNUMBERED"
    return value, None


def _invitation_ficha_header_counts(session_db, concert: Concert) -> dict:
    """Contadores de la pestaña Invitaciones de la ficha: Por contrato (lo pactado en la ficha
    de contratación) · Subidas (entradas subidas al back office) · Solicitadas (comprometidas +
    solicitadas activas) · Total (subidas − solicitadas)."""
    categories = _invitation_get_categories(session_db, concert, ensure_defaults=False)
    if categories:
        contract = sum(_safe_int(c.qty_contract) for c in categories)
    else:
        contract = sum(_safe_int(row.get("qty_contract")) for row in _invitation_category_legacy_rows(concert))
    uploaded = int(
        session_db.query(func.count(InvitationTicket.id))
        .filter(InvitationTicket.concert_id == concert.id)
        .scalar() or 0
    )
    commitments = session_db.query(InvitationCommitment).filter(InvitationCommitment.concert_id == concert.id).filter(InvitationCommitment.status != "ANULADAS").all()
    requests_rows = session_db.query(InvitationRequest).filter(InvitationRequest.concert_id == concert.id).all()
    solicitadas = (
        sum(_invitation_total_qty(_json_dict(x.quantities_json)) for x in commitments)
        + sum(_invitation_total_qty(_json_dict(x.quantities_json)) for x in requests_rows if (x.status or "") in INVITATION_PENDING_COUNT_STATUSES)
    )
    return {
        "contract": contract,
        "uploaded": uploaded,
        "requested": solicitadas,
        "total": uploaded - solicitadas,
    }


def _invitation_event_counts(session_db, concert: Concert) -> dict:
    categories = _invitation_get_categories(session_db, concert, ensure_defaults=False)
    # Invitaciones realmente SUBIDAS por categoría. El nº disponible nunca puede ser menor que las
    # entradas ya subidas al sistema, así que al subir invitaciones el disponible se actualiza.
    uploaded_by_cat = {}
    for cid, count in (
        session_db.query(InvitationTicket.category_id, func.count(InvitationTicket.id))
        .filter(InvitationTicket.concert_id == concert.id)
        .group_by(InvitationTicket.category_id)
        .all()
    ):
        uploaded_by_cat[str(cid)] = int(count or 0)
    total_uploaded = sum(uploaded_by_cat.values())
    if categories:
        known_ids = {str(c.id) for c in categories}
        # DISPONIBLES: si una categoría TIENE subidas, cuentan SOLO las subidas (lo real); si NO tiene
        # nada subido, cuenta lo configurado (contrato + extra). Así al subir manda lo subido.
        category_total = sum(
            (uploaded_by_cat.get(str(c.id), 0) if uploaded_by_cat.get(str(c.id), 0) > 0
             else (_safe_int(c.qty_contract) + _safe_int(c.qty_extra)))
            for c in categories
        )
        # Entradas subidas sin categoría conocida (sin asignar / categorías legacy) también suman.
        category_total += sum(n for k, n in uploaded_by_cat.items() if k not in known_ids)
    else:
        legacy_total = sum(_safe_int(row.get("qty_contract")) for row in _invitation_category_legacy_rows(concert))
        category_total = max(legacy_total, total_uploaded)
    commitments = session_db.query(InvitationCommitment).filter(InvitationCommitment.concert_id == concert.id).filter(InvitationCommitment.status != "ANULADAS").all()
    requests = session_db.query(InvitationRequest).filter(InvitationRequest.concert_id == concert.id).all()
    committed = sum(_invitation_total_qty(_json_dict(x.quantities_json)) for x in commitments)
    requested = sum(_invitation_total_qty(_json_dict(x.quantities_json)) for x in requests if (x.status or "") in INVITATION_PENDING_COUNT_STATUSES)
    assigned = sum(_invitation_total_qty(_json_dict(x.quantities_json)) for x in requests if (x.status or "") in {"ASIGNADAS", "ENVIADAS", "ENTREGADAS_MANO", "DISPONIBLES_TAQUILLA", "RECOGIDAS_TAQUILLA"})
    # Solicitudes "estén o no asignadas": todas las peticiones activas (no rechazadas/anuladas).
    requested_all = sum(_invitation_total_qty(_json_dict(x.quantities_json)) for x in requests if (x.status or "") in INVITATION_ACTIVE_REQUEST_STATUSES)
    return {
        "configured": category_total,
        "committed": committed,
        "requested": requested,
        "requested_all": requested_all,
        "assigned": assigned,
        # RESULTADO = Disponibles − Compromisos − (todas las) Invitaciones solicitadas.
        "result": category_total - committed - requested_all,
    }


def _invitation_manage_status_map(session_db, concerts) -> dict:
    """Estado de gestión de varios eventos a la vez, en consultas agregadas (1 por tabla, sin N+1).
    Devuelve {concert_id(str): {pending, box_office, managed}}:
      - pending: hay solicitudes/compromisos PENDIENTES DE GESTIONAR (solicitadas/aprobadas/asignadas
        sin enviar, o compromisos sin entregar) -> etiqueta roja.
      - box_office: nº de invitaciones dejadas EN TAQUILLA aún sin recoger (DISPONIBLES_TAQUILLA)
        -> etiqueta amarilla.
      - managed: todo enviado/entregado y, si había de taquilla, todas recogidas (nada pendiente ni
        en taquilla, pero existía algo) -> etiqueta verde. Sin nada -> los tres a 0/False."""
    ids = [c.id for c in (concerts or []) if getattr(c, "id", None)]
    out = {str(cid): {"pending": 0, "box_office": 0, "managed": False} for cid in ids}
    if not ids:
        return out
    acc = {str(cid): {"pending": 0, "box_office": 0, "done": 0} for cid in ids}
    pending_statuses = {"SOLICITADAS", "APROBADAS", "ASIGNADAS"}
    done_statuses = {"ENVIADAS", "ENTREGADAS_MANO", "RECOGIDAS_TAQUILLA"}
    for concert_id, status, qjson in (
        session_db.query(InvitationRequest.concert_id, InvitationRequest.status, InvitationRequest.quantities_json)
        .filter(InvitationRequest.concert_id.in_(ids))
        .all()
    ):
        a = acc.get(str(concert_id))
        if a is None:
            continue
        st = (status or "").upper()
        if st in pending_statuses:
            a["pending"] += 1
        elif st == "DISPONIBLES_TAQUILLA":
            a["box_office"] += _invitation_total_qty(_json_dict(qjson))
        elif st in done_statuses:
            a["done"] += 1
    commitments = session_db.query(InvitationCommitment).filter(InvitationCommitment.concert_id.in_(ids)).filter(InvitationCommitment.status != "ANULADAS").all()
    commit_ids = [c.id for c in commitments]
    delivered_by_commit: dict[str, int] = {}
    box_by_commit: dict[str, int] = {}
    if commit_ids:
        delivered_set = {"SENT", "DELIVERED", "PICKED_UP", "RECOGIDAS_TAQUILLA"}
        for ccid, tstatus, cnt in (
            session_db.query(InvitationTicket.assigned_commitment_id, InvitationTicket.status, func.count(InvitationTicket.id))
            .filter(InvitationTicket.assigned_commitment_id.in_(commit_ids))
            .group_by(InvitationTicket.assigned_commitment_id, InvitationTicket.status)
            .all()
        ):
            st = (tstatus or "").upper()
            if st in delivered_set:
                delivered_by_commit[str(ccid)] = delivered_by_commit.get(str(ccid), 0) + int(cnt or 0)
            elif st == "DISPONIBLES_TAQUILLA":
                box_by_commit[str(ccid)] = box_by_commit.get(str(ccid), 0) + int(cnt or 0)
    for c in commitments:
        a = acc.get(str(c.concert_id))
        if a is None:
            continue
        committed_qty = _invitation_total_qty(_json_dict(c.quantities_json))
        if committed_qty <= 0:
            continue
        delivered = delivered_by_commit.get(str(c.id), 0)
        box = box_by_commit.get(str(c.id), 0)
        if delivered >= committed_qty:
            a["done"] += 1
        elif (c.status or "").upper() == "ASIGNADAS" and delivered == 0 and box == 0:
            # Compromiso de listado marcado como asignado/enviado sin PDFs: se considera gestionado.
            a["done"] += 1
        else:
            if box > 0:
                a["box_office"] += box
            if (delivered + box) < committed_qty:
                a["pending"] += 1
    for cid, a in acc.items():
        out[cid] = {
            "pending": a["pending"],
            "box_office": a["box_office"],
            "managed": (a["pending"] == 0 and a["box_office"] == 0 and a["done"] > 0),
        }
    return out


def _invitation_event_pending_to_manage(session_db, concert) -> dict:
    """Estado de gestión de un único evento (envoltorio de _invitation_manage_status_map)."""
    cid = getattr(concert, "id", None)
    default = {"pending": 0, "box_office": 0, "managed": False}
    if not cid:
        return default
    return _invitation_manage_status_map(session_db, [concert]).get(str(cid), default)


def _invitation_configured_concert_query(session_db):
    query_start = _invitation_event_query_start_date()
    return (
        session_db.query(Concert)
        .options(joinedload(Concert.artist), joinedload(Concert.venue))
        .filter(or_(Concert.date == None, Concert.date >= query_start))  # noqa: E711
        .order_by(Concert.date.asc().nullslast(), Concert.created_at.desc())
    )


def _invitation_event_has_config(session_db, concert: Concert) -> bool:
    if session_db.query(InvitationCategory.id).filter(InvitationCategory.concert_id == concert.id).first():
        return True
    if _invitation_category_legacy_rows(concert):
        rows = _invitation_category_legacy_rows(concert)
        return any(_safe_int(r.get("qty_contract")) > 0 for r in rows)
    return False


def _invitation_entity_email(session_db, row) -> str:
    """Correo del invitado tomado directamente de la ENTIDAD vinculada (tercero/artista/empleado),
    sin mirar el snapshot. Devuelve '' si no hay entidad o no tiene correo."""
    gp = getattr(row, "guest_promoter_id", None)
    ga = getattr(row, "guest_artist_id", None)
    gu = getattr(row, "guest_user_id", None)
    if gp:
        pr = session_db.get(Promoter, gp)
        if pr:
            if (pr.contact_email or "").strip():
                return pr.contact_email.strip()
            try:
                pe = session_db.query(PromoterEmail).filter(PromoterEmail.promoter_id == gp).order_by(PromoterEmail.created_at.asc()).first()
                if pe and (pe.email or "").strip():
                    return pe.email.strip()
            except Exception:
                pass
    elif ga:
        ar = session_db.get(Artist, ga)
        if ar and (ar.email or "").strip():
            return ar.email.strip()
    elif gu:
        u = session_db.get(User, gu)
        if u and (u.email or "").strip():
            return u.email.strip()
    return ""


def _invitation_entity_phone(session_db, row) -> str:
    """Teléfono del invitado tomado directamente de la ENTIDAD vinculada (tercero → contact_phone;
    empleado → primer móvil del perfil). El artista no tiene teléfono propio."""
    gp = getattr(row, "guest_promoter_id", None)
    gu = getattr(row, "guest_user_id", None)
    if gp:
        pr = session_db.get(Promoter, gp)
        if pr and (pr.contact_phone or "").strip():
            return pr.contact_phone.strip()
    if gu:
        prof = session_db.get(UserProfile, gu)
        mob = _first_profile_mobile(prof) if prof else ""
        if mob:
            return mob
    return ""


def _invitation_guest_current_email(session_db, row) -> str:
    """Correo del invitado para mostrar/editar/enviar. Si está vinculado a una entidad
    (tercero/artista/empleado) manda SIEMPRE el de su ficha (lo más actualizado); si no hay entidad
    (invitado escrito a mano), el guardado en la propia solicitud/compromiso."""
    return _invitation_entity_email(session_db, row) or (getattr(row, "guest_email", None) or "").strip()


def _invitation_guest_live_phone(session_db, row) -> str:
    """Teléfono del invitado: el de la ficha de la entidad vinculada (lo más actualizado); si no hay
    entidad, el guardado en la solicitud/compromiso. El artista no tiene teléfono propio."""
    return _invitation_entity_phone(session_db, row) or (getattr(row, "guest_phone", None) or "").strip()


def _invitation_guest_identity(session_db, row) -> dict:
    """Identidad ACTUAL del invitado (nombre, foto/logo, email, teléfono y vínculo) resuelta EN VIVO
    desde la entidad vinculada (tercero/artista/empleado), para que TODA la gestión de invitaciones
    trabaje siempre sobre lo más actualizado, sin importar dónde se haya editado la ficha. Para
    invitados escritos a mano (sin entidad) usa lo guardado en la solicitud/compromiso."""
    name = (getattr(row, "guest_name", None) or "").strip()
    photo = ""
    link_summary = {}
    gp = getattr(row, "guest_promoter_id", None)
    ga = getattr(row, "guest_artist_id", None)
    gu = getattr(row, "guest_user_id", None)
    if gp:
        pr = session_db.get(Promoter, gp)
        if pr:
            name = _promoter_display_name(pr) or pr.nick or name
            photo = pr.logo_url or ""
            link_summary = _promoter_link_summary(session_db, pr, publisher_fallback=False)
    elif ga:
        ar = session_db.get(Artist, ga)
        if ar:
            name = ar.name or name
            photo = ar.photo_url or ""
    elif gu:
        prof = session_db.get(UserProfile, gu)
        if prof:
            name = _profile_full_name(prof) or getattr(prof, "nick", "") or name
            photo = getattr(prof, "photo_url", "") or ""
    return {
        "name": name,
        "photo": photo,
        "email": _invitation_guest_current_email(session_db, row),
        "phone": _invitation_guest_live_phone(session_db, row),
        "link_summary": link_summary,
    }


def _invitation_guest_live_emails(session_db, row) -> list[str]:
    """Correo(s) del invitado para el envío: el vigente de la solicitud/compromiso."""
    e = _invitation_guest_current_email(session_db, row)
    return [e] if e else []


def _invitation_sync_contact_for_entity(session_db, *, promoter_id=None, artist_id=None, user_id=None,
                                        email: str | None = None, phone: str | None = None) -> None:
    """Propaga el email/teléfono ACTUALIZADO de una persona (ficha del tercero/artista/empleado) a sus
    invitaciones AÚN NO enviadas (solicitudes y compromisos), para que los próximos envíos usen el
    último dato. No toca las ya enviadas/entregadas ni pisa con un valor vacío."""
    email = (email or "").strip()
    phone = (phone or "").strip()
    if not email and not phone:
        return
    sent = {'ENVIADAS', 'ENTREGADAS_MANO', 'DISPONIBLES_TAQUILLA', 'RECOGIDAS_TAQUILLA', 'RECHAZADAS', 'ANULADAS'}
    try:
        specs = []
        if promoter_id:
            specs.append(('guest_promoter_id', promoter_id))
        if artist_id:
            specs.append(('guest_artist_id', artist_id))
        if user_id:
            specs.append(('guest_user_id', user_id))
        for Model in (InvitationRequest, InvitationCommitment):
            for attr, val in specs:
                for inv in session_db.query(Model).filter(getattr(Model, attr) == val).all():
                    if (getattr(inv, 'status', None) or '') in sent:
                        continue
                    if email:
                        inv.guest_email = email
                    if phone:
                        inv.guest_phone = phone
    except Exception:
        pass


def _invitation_requester_live_emails(session_db, row) -> list[str]:
    """Correo del peticionario (persona de la oficina) resuelto en vivo desde su usuario."""
    values = []
    uid = getattr(row, "requester_user_id", None)
    if uid:
        u = session_db.get(User, uid)
        if u and (u.email or "").strip():
            values.append(u.email.strip())
    if (getattr(row, "requester_email", None) or "").strip():
        values.append(row.requester_email.strip())
    return values


def _first_profile_mobile(profile) -> str:
    """Primer móvil de un UserProfile (mobile_phones es una lista JSON)."""
    try:
        phones = _json_list(getattr(profile, "mobile_phones", None))
    except Exception:
        phones = []
    for p in phones:
        val = (str(p) if not isinstance(p, dict) else (p.get("number") or p.get("phone") or "")).strip()
        if val:
            return val
    return ""


def _invitation_request_reply_to(session_db, row) -> str:
    """Reply-To de una SOLICITUD: la persona de la oficina que hizo la petición (el peticionario),
    NO quien gestiona/envía. Si se pidió en nombre de otra persona de la oficina, el peticionario ya
    es esa otra persona (requester_user_id/requester_email)."""
    for e in _invitation_requester_live_emails(session_db, row):
        if e:
            return e
    return ""


def _invitation_commitment_reply_to(session_db, row) -> str:
    """Reply-To de un COMPROMISO: la persona de la oficina que lo registró (created_by)."""
    uid = getattr(row, "created_by_user_id", None)
    if uid:
        u = session_db.get(User, uid)
        if u and (u.email or "").strip():
            return u.email.strip()
    return ""


def _normalize_phone_intl(raw: str | None, default_cc: str = "34") -> str:
    """Normaliza un teléfono a solo dígitos en formato internacional (sin '+') para wa.me/sms.
    Un número nacional español de 9 dígitos se antepone el prefijo del país."""
    digits = re.sub(r"\D", "", raw or "")
    if not digits:
        return ""
    if digits.startswith("00"):
        digits = digits[2:]
    if len(digits) == 9:  # nacional (móvil/fijo español)
        digits = default_cc + digits
    return digits


def _invitation_share_text(session_db, concert, guest_name: str | None, link: str | None) -> str:
    """Texto para compartir por WhatsApp/SMS: «Hola <nombre>, aquí tienes tus invitaciones para el
    concierto de <datos>. Descárgalas: <enlace>». El enlace descarga las invitaciones en un único PDF
    (directo, sin descomprimir)."""
    ev = _invitation_event_payload(session_db, concert) if concert else {}
    artist = (ev.get("artist_names") or "").strip()
    date_label = (ev.get("date_label") or "").strip()
    venue = (ev.get("venue") or ev.get("city") or "").strip()
    parts = [artist] if artist else []
    if date_label:
        parts.append(f"({date_label})")
    if venue:
        parts.append(f"en {venue}")
    evento = " ".join([p for p in parts if p]).strip() or "el concierto"
    name = (guest_name or "").strip()
    saludo = f"Hola {name}," if name else "Hola,"
    if link:
        return f"{saludo} aquí tienes tus invitaciones para el concierto de {evento}. Descárgalas: {link}"
    return (f"{saludo} tus invitaciones para el concierto de {evento} estarán a tu nombre en el "
            "acceso/taquilla.")


def _invitation_tickets_to_merged_pdf(tickets) -> tuple[bytes | None, int]:
    """Une los PDF de las entradas en UN SOLO PDF (todas sus páginas) para poder abrirlo y usarlo
    directamente sin descomprimir un ZIP. Devuelve (bytes|None, nº de entradas incluidas). Si solo hay
    una entrada o pypdf no está disponible, devuelve ese PDF tal cual."""
    blobs = []
    for t in tickets or []:
        # Entrada principal + (PMR) su acompañante justo detrás: la de acompañante viaja siempre con ella.
        for url in [(getattr(t, "pdf_url", None) or "").strip(), (getattr(t, "companion_pdf_url", None) or "").strip()]:
            if not url:
                continue
            content = None
            for _attempt in range(3):
                try:
                    content, _ct = _download_remote_content(url)
                    break
                except Exception:
                    content = None
            if content is None:
                try:
                    app.logger.warning("Invitación PDF único: no se pudo bajar %s (%s)", getattr(t, "id", "?"), url)
                except Exception:
                    pass
                continue
            blobs.append(content)
    if not blobs:
        return None, 0
    if len(blobs) == 1 or not PYPDF_AVAILABLE or PdfWriter is None or PdfReader is None:
        return blobs[0], len(blobs)
    try:
        writer = PdfWriter()
        merged = 0
        for b in blobs:
            try:
                reader = PdfReader(BytesIO(b))
                for page in reader.pages:
                    writer.add_page(page)
                merged += 1
            except Exception:
                continue
        if merged == 0:
            return blobs[0], len(blobs)
        out = BytesIO()
        writer.write(out)
        return out.getvalue(), len(blobs)
    except Exception:
        return blobs[0], len(blobs)


def _invitation_delivery_recipients(session_db, row: InvitationRequest) -> list[str]:
    payload = _json_dict(row.receiver_payload)
    values = []
    mode = (row.receiver_mode or "GUEST").upper()
    if mode == "GUEST":
        values.extend(_invitation_guest_live_emails(session_db, row))
    elif mode == "ME":
        values.extend(_invitation_requester_live_emails(session_db, row))
    elif mode == "OTHER":
        values.extend([payload.get("email"), row.guest_email])
    elif mode == "EMPLOYEE":
        # Resolver el correo EN VIVO por el id del miembro de la oficina (el snapshot del payload puede
        # estar vacío si se guardó cuando aún no tenía email); se cae al snapshot como respaldo.
        emp_uid = _safe_uuid(payload.get("user_id"))
        if emp_uid:
            emp = session_db.get(User, emp_uid)
            if emp and (emp.email or "").strip():
                values.append(emp.email)
        values.append(payload.get("email"))
    elif mode in {"BOX_OFFICE", "DOOR"}:
        values.extend(_invitation_guest_live_emails(session_db, row))
        values.extend(_invitation_requester_live_emails(session_db, row))
    return _dedupe_valid_email_addresses(values)


def _invitation_receiver_text(row: InvitationRequest) -> str:
    payload = _json_dict(row.receiver_payload)
    mode = (row.receiver_mode or "GUEST").upper()
    labels = {
        "GUEST": "Enviar al invitado",
        "BOX_OFFICE": "Dejar en taquilla",
        "ME": "Enviar a mí",
        "OTHER": "Enviar a otro",
        "EMPLOYEE": "A alguien de la empresa",
        "DOOR": "Acceso por puerta",
    }
    base = labels.get(mode, mode)
    if mode in ("OTHER", "EMPLOYEE"):
        target = " · ".join([x for x in [payload.get("name"), payload.get("email"), payload.get("phone")] if x])
        return f"{base}: {target}" if target else base
    return base


def _invitation_parse_deadline(value: str | None):
    raw = (value or "").strip()
    if not raw:
        return None
    try:
        if "T" in raw:
            return datetime.fromisoformat(raw)
        return datetime.strptime(raw, "%Y-%m-%d %H:%M")
    except Exception:
        try:
            return datetime.strptime(raw, "%Y-%m-%d")
        except Exception:
            return None


def _concert_start_datetime(concert) -> datetime | None:
    """Fecha+hora de comienzo del evento (para el auto-bloqueo del enlace).
    Usa show_time o doors_time; si no hay hora, cae al final del día del evento."""
    d = getattr(concert, "date", None)
    if not d:
        return None
    raw = (getattr(concert, "show_time", None) or getattr(concert, "doors_time", None) or "").strip()
    hh, mm = 23, 59
    m = re.match(r"^(\d{1,2}):(\d{2})", raw)
    if m:
        try:
            hh, mm = int(m.group(1)), int(m.group(2))
        except Exception:
            hh, mm = 23, 59
    try:
        return datetime(d.year, d.month, d.day, hh, mm, tzinfo=TZ_MADRID)
    except Exception:
        return None


def _invitation_link_state(link: InvitationPublicLink) -> tuple[str, str]:
    if (link.status or "").upper() == "CANCELLED":
        return "cancelled", "Este enlace ha sido anulado y ya no está disponible. Por favor contacte con quien se lo ha enviado."
    # Bloqueo manual: congela nuevas peticiones y cambios sin anular el enlace.
    if bool(getattr(link, "locked", False)):
        return "locked", "El enlace está bloqueado temporalmente: no admite nuevas peticiones ni cambios por ahora."
    # Auto-bloqueo a la hora de comienzo del evento.
    try:
        start_dt = _concert_start_datetime(getattr(link, "concert", None))
        if start_dt is not None and start_dt <= _now_madrid():
            return "locked", "El evento ya ha comenzado: el enlace no admite nuevas peticiones ni cambios."
    except Exception:
        pass
    try:
        concert = getattr(link, "concert", None)
        if concert is not None and not _invitation_event_is_active_for_requests(concert):
            return "expired", "Lo sentimos, este concierto o evento ya ha pasado y no admite nuevas peticiones de invitaciones."
    except Exception:
        pass
    if link.deadline_at:
        try:
            deadline = link.deadline_at
            if getattr(deadline, "tzinfo", None) is None:
                deadline = deadline.replace(tzinfo=TZ_MADRID)
            if deadline < _now_madrid():
                return "expired", "Lo sentimos, el plazo para realizar peticiones ya ha finalizado."
        except Exception:
            pass
    return "active", ""


def _invitation_committed_category_ids(session_db, concert) -> set[str]:
    """IDs de categoría con al menos un COMPROMISO activo (status != ANULADAS y cantidad > 0).
    Un palco cuyo id esté aquí ya está "asignado a alguien" (aunque no se le hayan asignado las
    entradas todavía) y no debe ofrecerse al pedir ni admitir que se le arrastren invitados."""
    concert_id = getattr(concert, "id", concert)
    out: set[str] = set()
    for x in (
        session_db.query(InvitationCommitment)
        .filter(InvitationCommitment.concert_id == concert_id)
        .filter(InvitationCommitment.status != "ANULADAS")
        .all()
    ):
        for cid, q in _json_dict(x.quantities_json).items():
            if str(cid).upper() != "TOTAL" and _safe_int(q) > 0:
                out.add(str(cid))
    return out


def _invitation_committed_palco_labels(session_db, concert, categories) -> dict[str, str]:
    """{category_id: "Nombre destinatario"} SOLO para las categorías de zona PALCO que ya están
    comprometidas. Se usa para (a) ocultarlas al pedir y (b) mostrarlas bloqueadas ("Asignado a …")
    en el arrastre de peticiones. Si un mismo palco tuviera varios compromisos, se unen los nombres."""
    palco_ids = {str(c.id) for c in categories if _invitation_is_locking_palco(c)}
    if not palco_ids:
        return {}
    concert_id = getattr(concert, "id", concert)
    out: dict[str, list[str]] = {}
    for x in (
        session_db.query(InvitationCommitment)
        .filter(InvitationCommitment.concert_id == concert_id)
        .filter(InvitationCommitment.status != "ANULADAS")
        .order_by(InvitationCommitment.created_at.asc())
        .all()
    ):
        label = (getattr(x, "name", None) or _invitation_guest_identity(session_db, x).get("name") or "").strip()
        for cid, q in _json_dict(x.quantities_json).items():
            scid = str(cid)
            if scid in palco_ids and _safe_int(q) > 0:
                out.setdefault(scid, [])
                if label and label not in out[scid]:
                    out[scid].append(label)
    return {cid: " · ".join(names) for cid, names in out.items()}


def _invitation_request_excluded_category_ids(session_db, concert, categories) -> set:
    """Categorías que NO se ofrecen al PEDIR invitaciones (asistente interno y enlace público):
    (a) palcos ya COMPROMETIDOS a alguien (se asignan como unidad), y (b) cualquier palco COMPLETO
    — con entradas subidas y ninguna disponible porque ya están todas asignadas o enviadas—.
    Un palco lleno o cuyas invitaciones ya salieron no puede aceptar más peticiones."""
    excluded = set(_invitation_committed_palco_labels(session_db, concert, categories).keys())
    palco_ids = {str(c.id) for c in categories if _invitation_category_zone(c) == "PALCO"}
    if palco_ids:
        counts = _invitation_ticket_counts_by_category(session_db, concert)
        for cid in palco_ids:
            cc = counts.get(cid) or {}
            uploaded = _safe_int(cc.get("uploaded"))
            if uploaded > 0 and _safe_int(cc.get("assigned")) >= uploaded:
                excluded.add(cid)
    return excluded


def _invitation_event_available_by_category(session_db, concert: Concert, categories: list[InvitationCategory]) -> dict:
    """Aforo disponible del EVENTO por categoría (capacidad - comprometidas - solicitadas activas).
    Se usa para las opciones 'solo con aforo' y 'limitar a aforo' del enlace público."""
    uploaded = {}
    for cid, count in (
        session_db.query(InvitationTicket.category_id, func.count(InvitationTicket.id))
        .filter(InvitationTicket.concert_id == concert.id)
        .group_by(InvitationTicket.category_id)
        .all()
    ):
        uploaded[str(cid)] = int(count or 0)
    used = defaultdict(int)
    for x in session_db.query(InvitationCommitment).filter(InvitationCommitment.concert_id == concert.id).filter(InvitationCommitment.status != "ANULADAS").all():
        for cid, q in _json_dict(x.quantities_json).items():
            if str(cid).upper() != "TOTAL":
                used[str(cid)] += _safe_int(q)
    for x in session_db.query(InvitationRequest).filter(InvitationRequest.concert_id == concert.id).all():
        if (x.status or "") not in INVITATION_ACTIVE_REQUEST_STATUSES:
            continue
        for cid, q in _json_dict(x.quantities_json).items():
            if str(cid).upper() != "TOTAL":
                used[str(cid)] += _safe_int(q)
    out = {}
    for c in categories:
        cid = str(c.id)
        cap = max(_safe_int(c.qty_contract) + _safe_int(c.qty_extra), uploaded.get(cid, 0))
        out[cid] = max(cap - used.get(cid, 0), 0)
    return out


def _invitation_public_limits(link: InvitationPublicLink, categories: list[InvitationCategory], requests: list[InvitationRequest] | None = None, event_available_by_cat: dict | None = None, event_available_total: int | None = None, exclude_ids: set | None = None) -> dict:
    category_limits = _json_dict(link.category_limits_json)
    enabled = set(str(x) for x in _json_list(link.categories_enabled_json))
    only_available = bool(getattr(link, "show_only_available", False))
    cap_available = bool(getattr(link, "limit_to_available", False))
    used_total = 0
    used_by_category = defaultdict(int)
    for row in requests or []:
        if (row.status or "") in INVITATION_FINAL_STATUSES:
            continue
        q = _json_dict(row.quantities_json)
        used_total += _invitation_total_qty(q)
        for cid, qty in q.items():
            used_by_category[str(cid)] += _safe_int(qty)
    _exclude = set(str(x) for x in (exclude_ids or set()))
    rows = []
    for i, cat in enumerate(categories):
        cid = str(cat.id)
        # Palco ya comprometido a alguien: no se ofrece al pedir por el enlace público.
        if cid in _exclude:
            continue
        if link.limit_mode == "CATEGORIES" and cid not in category_limits:
            continue
        # Solo ofrecer las categorías que esta persona puede pedir (las habilitadas
        # al generar/editar el enlace), en cualquier modo de límite.
        if enabled and cid not in enabled:
            continue
        limit = _safe_int(category_limits.get(cid), None) if link.limit_mode == "CATEGORIES" else None
        if limit is not None and limit <= 0:
            continue
        available = None if limit is None else max(limit - used_by_category.get(cid, 0), 0)
        event_avail = None
        _cat_over_quota = bool(getattr(cat, "requests_over_quota_blocked", False))
        if event_available_by_cat is not None and cid in event_available_by_cat:
            event_avail = event_available_by_cat.get(cid)
            if cap_available or _cat_over_quota:
                # Limitar lo solicitable al aforo real disponible (opción del enlace o flag
                # «No aceptar por encima del cupo» de la categoría).
                available = event_avail if available is None else min(available, event_avail)
                if limit is None:
                    limit = event_avail
        if only_available and event_avail is not None and event_avail <= 0:
            continue  # Solo mostrar categorías con aforo disponible.
        rows.append({
            "id": cid,
            "name": cat.name,
            "limit": limit,
            "used": used_by_category.get(cid, 0),
            "available": available,
            "event_available": event_avail,
            "blocked": bool(getattr(cat, "requests_blocked", False)),
            "over_quota_blocked": _cat_over_quota,
            "zone": _invitation_category_zone(cat),
            "zone_label": INVITATION_ZONE_LABELS.get(_invitation_category_zone(cat), "Pista"),
            "zone_icon": INVITATION_ZONE_ICONS.get(_invitation_category_zone(cat), "fa-people-group"),
            "color": INVITATION_ASSIGNEE_COLORS[i % len(INVITATION_ASSIGNEE_COLORS)],
            "configured": _safe_int(getattr(cat, "qty_contract", 0)) + _safe_int(getattr(cat, "qty_extra", 0)),
        })
    total_limit = _safe_int(link.total_limit) if link.limit_mode == "TOTAL" else None
    available_total = None if total_limit is None else max(total_limit - used_total, 0)
    if cap_available and event_available_total is not None:
        available_total = event_available_total if available_total is None else min(available_total, event_available_total)
    return {"categories": rows, "total_limit": total_limit, "used_total": used_total, "available_total": available_total}


def _invitation_group_requests(requests: list[dict], categories) -> None:
    """Agrupa payloads de solicitud por categoría 'principal' (la de más entradas), añade
    group_key/name/color/order/total y ordena por grupo + alfabético (muta la lista). Reutilizado
    por la gestión interna de invitados y por la página pública del enlace."""
    _cat_order = {str(c.id): i for i, c in enumerate(categories)}
    _cat_color = {str(c.id): INVITATION_ASSIGNEE_COLORS[i % len(INVITATION_ASSIGNEE_COLORS)] for i, c in enumerate(categories)}
    _cat_name = {str(c.id): c.name for c in categories}

    def _primary(item):
        q = item.get('quantities') or {}
        best, best_qty = '', -1
        for k, v in q.items():
            if str(k).upper() == 'TOTAL' or str(k) not in _cat_name:
                continue
            try:
                iv = int(v or 0)
            except Exception:
                iv = 0
            if iv > best_qty:
                best, best_qty = str(k), iv
        return best

    totals = {}
    for item in requests:
        pk = _primary(item)
        item['group_key'] = pk
        item['group_name'] = _cat_name.get(pk, 'Sin categoría')
        item['group_color'] = _cat_color.get(pk, '#9ca3af')
        item['group_order'] = _cat_order.get(pk, 10000)
        q = item.get('quantities') or {}
        try:
            _n = int(q.get(pk) or 0) if pk else 0
        except Exception:
            _n = 0
        if _n <= 0:
            _n = _safe_int(item.get('qty_total'))
        totals[pk] = totals.get(pk, 0) + max(_n, 0)
    for item in requests:
        item['group_total'] = totals.get(item.get('group_key'), 0)
    requests.sort(key=lambda x: (x.get('group_order', 10000), _invitation_normalize_search(x.get('guest_name') or '')))


def _invitation_grouped(requests: list[dict], categories, allowed_ids=None, locked_labels=None) -> list:
    """Agrupa para pintar ZONAS DE DROP: un grupo por categoría (aunque esté vacía, para poder soltar
    ahí) en su orden, y al final 'Sin categoría' SOLO si hay solicitudes sin categoría. Requiere que
    `requests` ya venga con group_key (via _invitation_group_requests).
    Si `allowed_ids` no es None, solo se pintan las categorías permitidas (las disponibles para pedir
    en el enlace); las que no lo estén se conservan solo si ya tienen peticiones (para no ocultarlas).
    `locked_labels` (dict {cat_id: "Asignado a …"}) marca palcos ya comprometidos: el grupo se pinta
    BLOQUEADO (droppable=False, con la etiqueta del destinatario) para que no se le arrastren invitados."""
    allowed = set(str(x) for x in allowed_ids) if allowed_ids is not None else None
    locked = {str(k): v for k, v in (locked_labels or {}).items()}
    colors = {str(c.id): INVITATION_ASSIGNEE_COLORS[i % len(INVITATION_ASSIGNEE_COLORS)] for i, c in enumerate(categories)}
    by_key = {}
    for r in requests:
        by_key.setdefault(str(r.get('group_key') or ''), []).append(r)
    groups = []
    for c in categories:
        cid = str(c.id)
        rows = by_key.get(cid, [])
        if allowed is not None and cid not in allowed and not rows:
            continue
        zone = _invitation_category_zone(c)
        groups.append({
            "cat_id": cid,
            "name": c.name,
            "color": colors.get(cid, '#9ca3af'),
            "total": sum(_safe_int(r.get('qty_total')) for r in rows),
            "rows": rows,
            "zone": zone,
            "zone_label": INVITATION_ZONE_LABELS.get(zone, "Pista"),
            "zone_icon": INVITATION_ZONE_ICONS.get(zone, "fa-people-group"),
            # Aforo del palco (para mostrarlo entre paréntesis en Invitados) y bloqueo si ya está
            # comprometido a alguien (no se le pueden arrastrar invitados).
            "configured": _safe_int(getattr(c, 'qty_contract', 0)) + _safe_int(getattr(c, 'qty_extra', 0)),
            "droppable": cid not in locked,
            "locked_label": locked.get(cid, ""),
        })
    uncat = by_key.get('', [])
    if uncat:
        groups.append({
            "cat_id": "",
            "name": "Sin categoría",
            "color": "#9ca3af",
            "total": sum(_safe_int(r.get('qty_total')) for r in uncat),
            "rows": uncat,
            "zone": "",
            "zone_label": "Sin categoría",
            "zone_icon": "fa-circle-question",
            "configured": 0,
            "droppable": True,
            "locked_label": "",
        })
    return groups


INVITATION_SENT_STATUSES = {"ENVIADAS", "ENTREGADAS_MANO", "DISPONIBLES_TAQUILLA", "RECOGIDAS_TAQUILLA"}


def _invitation_recategorize(session_db, row: InvitationRequest, category_id: str, confirm: bool) -> dict:
    """Cambia la categoría de una solicitud arrastrándola. category_id vacío = 'Sin categoría'.
    Bloquea si ya está enviada/final. Si está ASIGNADAS pide confirmación y, al confirmar, libera las
    entradas asignadas (vuelven a disponibles) y la solicitud queda pendiente de asignar (APROBADAS)."""
    status = (row.status or "").upper()
    if status in INVITATION_SENT_STATUSES or status in {"RECHAZADAS", "ANULADAS"}:
        return {"ok": False, "error": "Esta solicitud ya no se puede cambiar de categoría (está enviada o cerrada)."}
    cid = (category_id or "").strip()
    if cid:
        cat = session_db.get(InvitationCategory, to_uuid(cid))
        if not cat or str(cat.concert_id) != str(row.concert_id):
            return {"ok": False, "error": "Categoría no válida para este evento."}
        # Un palco ya comprometido a alguien no admite que se le arrastren invitados.
        # (El «Palco de Honor» es la excepción: funciona como una categoría más y admite varios.)
        if _invitation_is_locking_palco(cat) and str(cat.id) in _invitation_committed_category_ids(session_db, row.concert_id):
            return {"ok": False, "error": "Este palco ya está asignado a un compromiso; no se le pueden mover invitados."}
        # Un palco COMPLETO (todas sus entradas ya asignadas o enviadas) tampoco admite más invitados.
        if _invitation_category_zone(cat) == "PALCO":
            _cc = _invitation_ticket_counts_by_category(session_db, row.concert).get(str(cat.id)) or {}
            if _safe_int(_cc.get("uploaded")) > 0 and _safe_int(_cc.get("assigned")) >= _safe_int(_cc.get("uploaded")):
                return {"ok": False, "error": "Este palco ya está completo (invitaciones asignadas o enviadas); no se le pueden mover invitados."}
    if status == "ASIGNADAS" and not confirm:
        return {"ok": False, "needs_confirm": True}
    if status == "ASIGNADAS":
        for t in session_db.query(InvitationTicket).filter(InvitationTicket.assigned_request_id == row.id).all():
            t.previous_assignment_warning = f"Se cambió de categoría; estaba asignada a {row.guest_name}."
            t.assigned_request_id = None
            t.assigned_label = None
            t.status = "AVAILABLE"
        row.status = "APROBADAS"
        row.assigned_at = None
    total = _invitation_total_qty(_json_dict(row.quantities_json)) or _safe_int(request.form.get("qty_total")) or 1
    row.quantities_json = {cid: total} if cid else {"TOTAL": total}
    row.updated_at = _now_madrid()
    return {"ok": True}


def _invitation_upsert_category_rows_from_request(session_db, concert: Concert, form) -> list[InvitationCategory]:
    categories = _invitation_get_categories(session_db, concert, ensure_defaults=True)
    return categories


def _invitation_artist_options(session_db) -> list[dict]:
    rows = session_db.query(Artist).order_by(Artist.name.asc()).all()
    # email para el asistente de invitaciones: decide si pedir un correo manual del invitado.
    return [{**_artist_chip_payload(a), "email": (getattr(a, "email", None) or "")} for a in rows]


def _invitation_event_artist_options(session_db) -> list[dict]:
    """Artistas con al menos un concierto/festival/evento vigente para solicitudes de
    invitaciones (de hoy en adelante, o aún sin fecha asignada).

    Se usa en el paso "Selecciona artista" de Pedir invitaciones (alta interna y enlace),
    para no ofrecer artistas cuyas actividades ya pasaron ni los que no tienen ninguna.
    Mismo criterio de vigencia que el listado de eventos del módulo: actividad sin fecha
    asignada (TBD) o con fecha >= hoy (vía `_invitation_event_query_start_date`), más la
    regla de las 5 h (`_invitation_event_is_active_for_requests`). Solo selecciona las
    columnas necesarias para no cargar los payloads JSONB pesados del concierto.
    """
    query_start = _invitation_event_query_start_date()
    now_value = _now_madrid()
    wanted_ids = set()
    for row in (
        session_db.query(Concert.id, Concert.date, Concert.artist_id, Concert.artist_ids)
        .filter(or_(Concert.date == None, Concert.date >= query_start))  # noqa: E711
        .all()
    ):
        if not _invitation_event_is_active_for_requests(row, now_value=now_value):
            continue
        for aid in _concert_artist_ids(row):
            if aid:
                wanted_ids.add(aid)
    if not wanted_ids:
        return []
    uuids = [u for u in (_safe_uuid(a) for a in wanted_ids) if u]
    if not uuids:
        return []
    rows = session_db.query(Artist).filter(Artist.id.in_(uuids)).order_by(Artist.name.asc()).all()
    return [_artist_chip_payload(a) for a in rows]


def _invitation_personnel_options(session_db) -> list[dict]:
    """Personal ACTUAL (sin eliminados ni bloqueados) para pedir/asignar invitaciones."""
    _inactive = _inactive_user_ids(session_db)
    rows = (
        session_db.query(User, UserProfile)
        .outerjoin(UserProfile, UserProfile.user_id == User.id)
        .order_by(User.email.asc())
        .all()
    )
    out = []
    for user, profile in rows:
        if user.id in _inactive:
            continue
        name = _profile_full_name(profile) if profile else ""
        nick = getattr(profile, "nick", None) if profile else None
        out.append({
            "id": str(user.id),
            "name": name or nick or user.email,
            "email": user.email,
            "photo_url": (getattr(profile, "photo_url", None) if profile else None) or url_for("static", filename="img/placeholder_photo.png"),
        })
    return out


def _invitation_promoter_payload(promoter: Promoter | None) -> dict:
    return {
        "id": str(getattr(promoter, "id", "") or ""),
        "name": _promoter_display_name(promoter) if promoter else "",
        "email": getattr(promoter, "contact_email", None) or "",
        "phone": getattr(promoter, "contact_phone", None) or "",
        "photo_url": getattr(promoter, "logo_url", None) or url_for("static", filename="img/placeholder_photo.png"),
    }


_INV_LINK_COLS_READY = False


def _ensure_invitation_link_columns(session_db) -> None:
    """Auto-repara las columnas del enlace público (locked/show_only_available/limit_to_available)
    si la migración de arranque no se aplicó en este proceso. Evita 500 por 'column does not exist'.
    El ALTER es idempotente y persiste, así que basta con que lo ejecute la primera petición."""
    global _INV_LINK_COLS_READY
    if _INV_LINK_COLS_READY:
        return
    try:
        session_db.execute(text(
            "ALTER TABLE IF EXISTS invitation_public_links "
            "ADD COLUMN IF NOT EXISTS locked boolean NOT NULL DEFAULT false, "
            "ADD COLUMN IF NOT EXISTS show_only_available boolean NOT NULL DEFAULT false, "
            "ADD COLUMN IF NOT EXISTS limit_to_available boolean NOT NULL DEFAULT false"
        ))
        session_db.commit()
        _INV_LINK_COLS_READY = True
    except Exception:
        try:
            session_db.rollback()
        except Exception:
            pass


def _invitation_public_link_url(link: InvitationPublicLink) -> str:
    return _external_url_for("public_invitation_request_link", token=link.token)


def _invitation_request_download_url(row: InvitationRequest) -> str:
    if not row.delivery_token:
        row.delivery_token = _invitation_token()
    return _external_url_for("invitation_request_download", token=row.delivery_token)


def _build_invitation_request_pdf(session_db, row: InvitationRequest) -> bytes:
    concert = row.concert or session_db.get(Concert, row.concert_id)
    categories = _invitation_get_categories(session_db, concert, ensure_defaults=False) if concert else []
    name_map = _invitation_category_name_map(categories)
    buffer = BytesIO()
    if not REPORTLAB_AVAILABLE:
        text_body = f"Invitaciones\n\n{row.guest_name}\n{_invitation_quantities_label(_json_dict(row.quantities_json), name_map)}"
        return text_body.encode("utf-8")
    doc = SimpleDocTemplate(buffer, pagesize=A4, rightMargin=36, leftMargin=36, topMargin=36, bottomMargin=36)
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle("InvitationTitle", parent=styles["Title"], alignment=TA_CENTER, fontSize=20, spaceAfter=14)
    normal = styles["BodyText"]
    story = []
    story.append(Paragraph("Invitaciones", title_style))
    if concert:
        event = _invitation_event_payload(session_db, concert)
        info = [
            ["Evento", html.escape(event["type_label"] + " · " + (event["title"] or ""))],
            ["Artista", html.escape(event["artist_names"] or "—")],
            ["Fecha", html.escape(event["date_label"] or "—")],
            ["Hora", html.escape(event.get("show_time") or "—")],
            ["Recinto", html.escape(event.get("venue") or "—")],
            ["Ciudad", html.escape(" · ".join([x for x in [event.get("city"), event.get("province")] if x]) or "—")],
        ]
        tbl = Table(info, colWidths=[90, 360])
        tbl.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (0, -1), colors.whitesmoke),
            ("BOX", (0, 0), (-1, -1), 0.5, colors.lightgrey),
            ("INNERGRID", (0, 0), (-1, -1), 0.25, colors.lightgrey),
            ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ]))
        story.append(tbl)
        story.append(Spacer(1, 14))
    quantities = _json_dict(row.quantities_json)
    story.append(Paragraph(f"Buenas, te adjunto {row.guest_name and html.escape(row.guest_name) or 'las invitaciones'}.", normal))
    story.append(Spacer(1, 8))
    story.append(Paragraph(f"<b>Invitaciones:</b> {html.escape(_invitation_quantities_label(quantities, name_map))}", normal))
    story.append(Paragraph(f"<b>Estado:</b> {html.escape(INVITATION_STATUS_LABELS.get(row.status or '', row.status or ''))}", normal))
    receiver = _invitation_receiver_text(row)
    if receiver:
        story.append(Paragraph(f"<b>Entrega:</b> {html.escape(receiver)}", normal))
    assigned = (
        session_db.query(InvitationTicket)
        .filter(InvitationTicket.assigned_request_id == row.id)
        .order_by(InvitationTicket.sector.asc().nullslast(), InvitationTicket.row_label.asc().nullslast(), InvitationTicket.seat_number.asc().nullslast())
        .all()
    )
    if assigned:
        story.append(Spacer(1, 12))
        story.append(Paragraph("<b>Entradas asignadas</b>", normal))
        data = [["Categoría", "Localización", "Código"]]
        cat_map = {str(c.id): c.name for c in categories}
        for t in assigned:
            loc = " ".join([x for x in [t.sector, t.row_label, t.seat_number] if x]) or "Sin numerar"
            code = t.ticket_code or t.pdf_name or "—"
            data.append([cat_map.get(str(t.category_id), "Categoría"), loc, code])
        table = Table(data, colWidths=[140, 160, 190])
        table.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), colors.whitesmoke),
            ("GRID", (0, 0), (-1, -1), 0.25, colors.lightgrey),
            ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ]))
        story.append(table)
    story.append(Spacer(1, 18))
    story.append(Paragraph("Importante: todas las invitaciones quedan sujetas a las indicaciones de organización, taquilla o puerta.", normal))
    doc.build(story)
    return buffer.getvalue()


def _hex_tint(hex_color: str | None, factor: float = 0.72) -> str:
    """Versión más CLARA de un color hex (mezcla con blanco al `factor`), para la barra suave."""
    try:
        h = (hex_color or "").lstrip("#")
        if len(h) == 3:
            h = "".join(c * 2 for c in h)
        r, g, b = int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)
        r = int(r + (255 - r) * factor); g = int(g + (255 - g) * factor); b = int(b + (255 - b) * factor)
        return f"#{r:02x}{g:02x}{b:02x}"
    except Exception:
        return "#e5e7eb"


def _invitation_tickets_grouped_html(session_db, concert, tickets, zip_all, *, categories=None) -> str:
    """Lista de entradas para el correo y para la página pública de descarga, con la MISMA estética que
    "configurar invitaciones": agrupada por ZONA → CATEGORÍA (borde de color + topo + barra suave +
    "Descargar todas") → SECTOR (si hay varios), y con la flecha de descarga PEGADA al número de cada
    invitación (alineada en columna). Estilos en línea (compatibles con clientes de correo)."""
    esc = html.escape
    if not tickets:
        return ""
    cats = categories if categories is not None else (_invitation_get_categories(session_db, concert, ensure_defaults=False) if concert else [])
    cat_map = {str(c.id): c for c in cats}
    # Color por categoría según su ORDEN (idéntico al de la pantalla de gestión).
    color_by = {str(c.id): INVITATION_ASSIGNEE_COLORS[i % len(INVITATION_ASSIGNEE_COLORS)] for i, c in enumerate(cats)}
    zone_order = ["PISTA", "GRADA", "PALCO"]
    zone_labels = {"PISTA": "Pista", "GRADA": "Grada", "PALCO": "Palcos"}
    # Icono por zona: el MISMO SVG (rojo de marca) que usa la app; como <img> para que se vea igual en
    # correo/enlace (Font Awesome no renderiza en email).
    def _zone_img(zone):
        # PNG (no SVG) porque muchos clientes de correo (Gmail) no renderizan SVG en <img>.
        fn = {"PISTA": "pista", "GRADA": "grada", "PALCO": "palco"}.get(zone, "pista")
        src = _absolute_media_url(url_for("static", filename="img/zone/" + fn + ".png"))
        return f'<img src="{esc(src)}" width="17" height="17" alt="" style="height:17px;width:auto;vertical-align:-3px;margin-right:7px">'
    grouped: dict = {z: [] for z in zone_order}
    bykey: dict = {}
    for t in tickets:
        cid = str(t.category_id)
        cat = cat_map.get(cid)
        zone = _invitation_category_zone(cat) if cat else "PISTA"
        k = (zone, cid)
        if k not in bykey:
            bykey[k] = []
            grouped.setdefault(zone, []).append((cid, cat, bykey[k]))
        bykey[k].append(t)

    def _dlicon(href, title=""):
        return (f'<a href="{esc(href)}" title="{esc(title or "Descargar entrada")}" '
                'style="color:#e83b4b;text-decoration:none;font-size:16px;line-height:1;display:inline-block;vertical-align:middle">&#11015;</a>')

    def _dlall(cid):
        sep = "&" if "?" in (zip_all or "") else "?"
        href = f"{zip_all}{sep}category={cid}"
        return (f'<a href="{esc(href)}" style="color:#e83b4b;text-decoration:none;font-weight:600;'
                'font-size:12px;white-space:nowrap">&#11015; Descargar todas</a>')

    out = []
    n = 0
    for zone in zone_order:
        zcats = grouped.get(zone) or []
        if not zcats:
            continue
        # Cabecera de zona: icono (mismo SVG que la app, rojo) + nombre en negro y en negrita.
        inner = [f'<div style="font-weight:800;color:#111;font-size:15px;margin:0 0 10px">{_zone_img(zone)}{esc(zone_labels[zone])}</div>']
        for cid, cat, cat_tickets in zcats:
            cat_name = (getattr(cat, "name", None) or "Categoría").strip()
            color = color_by.get(cid, "#9ca3af")
            shade = _hex_tint(color, 0.85)  # sombreado claro SOLO para la barra del título
            is_num = (getattr(cat, "ticket_kind", "") or "") == "PDF_NUMBERED"
            # Barra del TÍTULO con sombreado de lado a lado (como en "configurar invitaciones").
            title_bar = (
                f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;background:{shade}"><tr>'
                f'<td style="padding:7px 12px;vertical-align:middle">'
                f'<span style="display:inline-block;width:11px;height:11px;border-radius:50%;background:{color};margin-right:8px;vertical-align:middle"></span>'
                f'<span style="font-weight:700;color:#111;font-size:14px;vertical-align:middle">{esc(cat_name)}</span>'
                f'<span style="color:#7a828d;font-size:12px">&nbsp;({len(cat_tickets)})</span></td>'
                f'<td align="right" style="padding:7px 12px;vertical-align:middle">{_dlall(cid)}</td>'
                '</tr></table>'
            )
            # Sub-agrupar por SECTOR (en orden de aparición) si hay más de uno.
            sector_order, by_sector = [], {}
            for t in cat_tickets:
                sec = (t.sector or "").strip()
                if sec not in by_sector:
                    by_sector[sec] = []
                    sector_order.append(sec)
                by_sector[sec].append(t)
            multi_sector = len(sector_order) > 1
            parts = []
            for sec in sector_order:
                if multi_sector and sec:
                    parts.append(f'<div style="font-size:12px;font-weight:700;color:#49515d;margin:8px 0 2px">Sector {esc(sec)}</div>')
                trs = []
                for t in by_sector[sec]:
                    n += 1
                    if is_num:
                        bits = []
                        if not multi_sector and (t.sector or "").strip():
                            bits.append((t.sector or "").strip())
                        if (t.row_label or "").strip():
                            bits.append("Fila " + (t.row_label or "").strip())
                        if (t.seat_number or "").strip():
                            bits.append("Asiento " + (t.seat_number or "").strip())
                        detail = ", ".join(bits)
                    else:
                        detail = ""
                    dl = _dlicon(t.pdf_url, f"Descargar invitación {n}") if (t.pdf_url or "").strip() else ""
                    detail_html = f'<span style="color:#667085"> · {esc(detail)}</span>' if detail else ""
                    # NUEVA respecto al último envío (ampliación): etiqueta azul junto a la entrada,
                    # para distinguirla visualmente de las ya enviadas (solo en envíos de TODO).
                    if getattr(t, "added_after_send", False):
                        detail_html += ('<span style="display:inline-block;background:#0dcaf0;color:#062a30;font-size:10px;'
                                        'font-weight:700;border-radius:6px;padding:1px 6px;margin-left:8px;vertical-align:middle">NUEVA</span>')
                    # Numeradas: nº + fila/asiento delante y la flecha JUSTO tras el texto. La tabla se
                    # ajusta al contenido (sin width:100%) → la columna del texto toma el ancho del texto
                    # MÁS LARGO de esa categoría, así todas las flechas quedan en la misma vertical.
                    trs.append(
                        '<tr>'
                        f'<td style="padding:3px 0;font-size:14px;color:#111;vertical-align:middle;white-space:nowrap">Invitación {n}{detail_html}</td>'
                        f'<td style="padding:3px 0 3px 12px;white-space:nowrap;vertical-align:middle">{dl}</td>'
                        '</tr>')
                parts.append('<table role="presentation" cellpadding="0" cellspacing="0" style="border-collapse:collapse">' + "".join(trs) + "</table>")
            # Bloque de categoría: borde de color; el sombreado va SOLO en la barra del título.
            inner.append(f'<div style="border:1px solid {shade};border-left:4px solid {color};border-radius:8px;margin:8px 0;overflow:hidden">'
                         + title_bar + '<div style="padding:6px 12px 8px">' + "".join(parts) + '</div></div>')
        # Toda la zona dentro de un "bocadillo" claro que la diferencia.
        out.append('<div style="border:1px solid #e6e9ee;background:#fafbfc;border-radius:14px;padding:12px 14px;margin:14px 0">' + "".join(inner) + "</div>")
    return "".join(out)


def _invitation_email_compose(session_db, concert, tickets, zip_all, *, custom_text=None, only_guest_list=False, guest_name=None, receiver_mode=None, category_filter_id=None, share_urls=None) -> tuple:
    """Construye (asunto, html, texto) del correo de invitaciones. Compartido por solicitudes y
    compromisos: recibe ya las entradas y la URL base del ZIP. Si se pasa category_filter_id, el
    botón "Descargar todas" de cabecera queda acotado a esa categoría."""
    event = _invitation_event_payload(session_db, concert) if concert else {}
    esc = html.escape
    artist_name = (event.get("artist_names") or "").strip()
    event_name = ((getattr(concert, "festival_name", None) or "") if concert else "").strip()
    city = (event.get("city") or "").strip()
    venue = (event.get("venue") or "").strip()
    date_label = (event.get("date_label") or "").strip()
    show_time = (event.get("show_time") or "").strip()
    # Asunto: Invitaciones "Artista", "Evento", "Ciudad", "Fecha" (solo lo que haya).
    subj_parts = [x for x in [artist_name, event_name, city, date_label] if x]
    subject = ("Invitaciones " + ", ".join(subj_parts)).strip() if subj_parts else "Invitaciones"

    logo = _invitation_event_logo_url(session_db, concert, external=True)  # logo de la empresa del evento
    arts = event.get("artists") or []
    # Si hay cartel de concierto subido, se usa el cartel principal en la cabecera en vez del avatar.
    artist_photo = (event.get("poster_url") or "").strip() or ((arts[0].get("photo_url") or "").strip() if arts else "")

    # Saludo: SOLO el nombre del invitado tras "Hola" (sin vínculos ni foto).
    _gname = (guest_name or "").strip()
    _hola = f"Hola {esc(_gname)}," if _gname else "Hola,"
    # Texto: el personalizado reemplaza al genérico.
    if custom_text and custom_text.strip():
        intro = "".join(f'<p style="margin:0 0 10px;text-align:justify">{esc(p)}</p>' for p in custom_text.strip().split("\n") if p.strip())
    else:
        intro = (f'<p style="margin:0 0 10px;text-align:justify">{_hola} aquí tienes tus invitaciones.</p>'
                 '<p style="margin:0 0 10px;text-align:justify">Esperamos que disfrutes.</p>'
                 '<p style="margin:0 0 10px;text-align:justify">Un saludo</p>')

    logo_html = f'<div style="text-align:right;margin-bottom:6px"><img src="{esc(logo)}" style="max-height:58px;max-width:200px" alt="Logo"></div>'
    meta_rows = [(k, v) for k, v in [("Evento", event_name), ("Ciudad", city), ("Recinto", venue), ("Fecha", date_label), ("Hora", show_time)] if v]
    meta_html = "".join(f'<div style="font-size:13px;color:#444"><b>{esc(k)}:</b> {esc(v)}</div>' for k, v in meta_rows)
    # Foto del artista en círculo junto al nombre en la cabecera.
    photo_cell = (
        f'<td style="vertical-align:middle;padding-right:12px">'
        f'<img src="{esc(artist_photo)}" width="52" height="52" alt="" style="width:52px;height:52px;border-radius:50%;object-fit:cover;display:block;border:1px solid #eceef1"></td>'
    ) if artist_photo else ''
    header_html = (
        '<table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;background:#f6f7f9;border:1px solid #eceef1;border-radius:14px;margin:8px 0 18px">'
        '<tr><td style="padding:14px 16px"><table role="presentation" cellpadding="0" cellspacing="0"><tr>'
        f'{photo_cell}'
        f'<td style="vertical-align:top"><div style="font-size:17px;font-weight:700;color:#111">{esc(artist_name or "Evento")}</div>{meta_html}</td>'
        '</tr></table></td></tr></table>'
    )

    def abtn(href, label, primary=True):
        if primary:
            return f'<a href="{esc(href)}" style="background:#e83b4b;color:#fff;text-decoration:none;padding:9px 16px;border-radius:10px;font-weight:700;display:inline-block;font-size:13px">{esc(label)}</a>'
        return f'<a href="{esc(href)}" style="color:#e83b4b;text-decoration:none;font-weight:600;font-size:13px">{esc(label)}</a>'

    def dlicon(href, title=""):
        # Icono de descarga (enlace) para cada entrada suelta. Usa un glifo unicode para
        # compatibilidad con clientes de correo (Font Awesome no renderiza en email).
        return (f'<a href="{esc(href)}" title="{esc(title or "Descargar entrada")}" '
                'style="color:#e83b4b;text-decoration:none;font-size:16px;line-height:1;'
                'display:inline-block;vertical-align:middle">&#11015;</a>')

    def catzip(base, cid):
        sep = "&" if "?" in (base or "") else "?"
        return f"{base}{sep}category={cid}"

    if only_guest_list:
        mode = "en taquilla" if (receiver_mode or '').upper() == 'BOX_OFFICE' else "en puerta"
        gname = guest_name or "el invitado"
        body = (f'<div style="font-family:Arial,sans-serif;color:#111;line-height:1.45;max-width:720px;margin:0 auto">{logo_html}{intro}{header_html}'
                f'<h2 style="text-align:center;margin:14px 0 6px">Invitaciones</h2>'
                f'<p style="text-align:center;color:#555">Tus invitaciones estarán {mode} a nombre de <b>{esc(gname)}</b>.</p></div>')
        return subject, body, f"Hola, tus invitaciones para {subject} estarán {mode} a nombre de {gname}."

    categories = _invitation_get_categories(session_db, concert, ensure_defaults=False) if concert else []
    # Lista de entradas agrupada (zona → categoría → sector) con la estética del configurador y la
    # flecha de descarga pegada al número. Mismo componente que la página pública de descarga.
    sections = [_invitation_tickets_grouped_html(session_db, concert, tickets, zip_all, categories=categories)]

    top_zip = catzip(zip_all, category_filter_id) if category_filter_id else zip_all
    # Solo ofrecemos el botón "Descargar todas" si REALMENTE hay PDFs que descargar. Si no, el enlace
    # daría error: en su lugar avisamos. (Las listas de invitados/taquilla ya se gestionan arriba.)
    # Botones "Compartir" (WhatsApp / SMS): permiten al invitado REENVIAR sus invitaciones desde el
    # correo, con la misma info y visual que un envío. Van al endpoint de reenvío (registra que se
    # reenvió y redirige a wa.me / sms:). Verde WhatsApp y azul SMS para diferenciarlos del rojo de marca.
    def sbtn(href, label, bg, icon_svg):
        return (f'<a href="{esc(href)}" style="background:{bg};color:#fff;text-decoration:none;padding:9px 14px;'
                f'border-radius:10px;font-weight:700;display:inline-block;font-size:13px;margin-left:8px">{icon_svg}{esc(label)}</a>')
    _wa_ico = '<span style="font-weight:900;margin-right:6px">✆</span>'
    _sms_ico = '<span style="font-weight:900;margin-right:6px">✉</span>'
    share_html = ""
    if tickets and share_urls:
        parts = []
        if share_urls.get("whatsapp"):
            parts.append(sbtn(share_urls["whatsapp"], "Compartir", "#25D366", _wa_ico))
        if share_urls.get("sms"):
            parts.append(sbtn(share_urls["sms"], "Compartir", "#0d6efd", _sms_ico))
        if parts:
            share_html = "".join(parts)
    if tickets:
        download_html = f'<div style="text-align:right;margin:0 0 12px">{abtn(top_zip, "Descargar invitaciones")}{share_html}</div>'
        plain = f"{_hola} aquí tienes tus invitaciones para {subject}. Descárgalas: {top_zip}"
    else:
        download_html = ('<p style="text-align:center;color:#555;margin:0 0 12px">Tus invitaciones se están '
                         'preparando. Si en un rato no puedes descargarlas, contacta con la organización.</p>')
        plain = f"Hola, tus invitaciones para {subject} se están preparando."
    body = (f'<div style="font-family:Arial,sans-serif;color:#111;line-height:1.45;max-width:720px;margin:0 auto">{logo_html}{intro}{header_html}'
            f'<h2 style="text-align:center;margin:14px 0 6px">Invitaciones</h2>'
            f'{download_html}'
            f'{"".join(sections)}</div>')
    return subject, body, plain


def _invitation_email_body(session_db, row: InvitationRequest, download_url: str | None = None, custom_text: str | None = None, only_ticket_ids=None) -> tuple:
    """Correo de una SOLICITUD (wrapper de _invitation_email_compose). Con only_ticket_ids
    («enviar solo las nuevas») el listado se acota a las entradas de ese envío."""
    concert = row.concert or session_db.get(Concert, row.concert_id)
    only_gl = _invitation_request_uses_only_guest_list(session_db, row)
    if not row.delivery_token:
        row.delivery_token = _invitation_token()
    zip_all = _external_url_for("invitation_request_download", token=row.delivery_token)  # PDF único (directo)
    tickets = [] if only_gl else (session_db.query(InvitationTicket)
               .filter(InvitationTicket.assigned_request_id == row.id)
               .order_by(InvitationTicket.sector.asc().nullslast(), InvitationTicket.row_label.asc().nullslast(), InvitationTicket.seat_number.asc().nullslast(), InvitationTicket.uploaded_at.asc())
               .all())
    if only_ticket_ids is not None:
        tickets = [t for t in tickets if t.id in only_ticket_ids]
    share_urls = None
    if not only_gl:
        share_urls = {
            "whatsapp": _external_url_for("public_invitation_reforward", token=row.delivery_token, channel="whatsapp"),
            "sms": _external_url_for("public_invitation_reforward", token=row.delivery_token, channel="sms"),
        }
    return _invitation_email_compose(session_db, concert, tickets, zip_all, custom_text=custom_text, only_guest_list=only_gl, guest_name=row.guest_name, receiver_mode=row.receiver_mode, share_urls=share_urls)


def _invitation_commitment_email_body(session_db, commitment, custom_text: str | None = None, category_id=None) -> tuple:
    """Correo de un COMPROMISO: mismas piezas que la solicitud, con las entradas asignadas al
    compromiso (opcionalmente filtradas a una categoría)."""
    concert = commitment.concert or session_db.get(Concert, commitment.concert_id)
    if not commitment.delivery_token:
        commitment.delivery_token = _invitation_token()
    zip_all = _external_url_for("invitation_commitment_download", token=commitment.delivery_token)  # PDF único (directo)
    q = session_db.query(InvitationTicket).filter(InvitationTicket.assigned_commitment_id == commitment.id)
    if category_id:
        q = q.filter(InvitationTicket.category_id == category_id)
    tickets = q.order_by(InvitationTicket.sector.asc().nullslast(), InvitationTicket.row_label.asc().nullslast(), InvitationTicket.seat_number.asc().nullslast(), InvitationTicket.uploaded_at.asc()).all()
    return _invitation_email_compose(session_db, concert, tickets, zip_all, custom_text=custom_text, guest_name=(commitment.guest_name or commitment.name), category_filter_id=(str(category_id) if category_id else None))



def _invitation_event_logo_url(session_db, concert: Concert | None, external: bool = True) -> str:
    """Logo de la empresa del evento. Con external=True (correos, PDFs, previsualizaciones) la URL
    se devuelve SIEMPRE absoluta y sin el «?» final que dejaba storage3 (si está guardada relativa
    o con ese sufijo, algunos clientes de correo no la cargaban)."""
    logo = ""
    if concert:
        for company in (getattr(concert, "billing_company", None), getattr(concert, "group_company", None)):
            logo = (getattr(company, "logo_url", None) or "").strip()
            if logo:
                break
    if not logo:
        logo = (_treinta_y_tres_logo_url(session_db) if "_treinta_y_tres_logo_url" in globals() else "") \
            or url_for("static", filename="img/logo.png", _external=external)
    return _absolute_media_url(logo) if external else logo.rstrip("?")


@app.get("/invitaciones/reenviar/<token>", endpoint="public_invitation_reforward")
def public_invitation_reforward(token):
    """Reenvío por el propio invitado desde el correo (botón «Compartir» WhatsApp/SMS).

    Registra el reenvío (para mostrar el icono de «reenviada» en gestión) y redirige a
    wa.me / sms: con el enlace público de descarga y el mismo texto que los envíos normales.
    """
    channel = (request.args.get("channel") or "whatsapp").strip().lower()
    session_db = db()
    try:
        row = session_db.query(InvitationRequest).filter(InvitationRequest.delivery_token == token).first()
        if not row:
            abort(404)
        concert = row.concert or session_db.get(Concert, row.concert_id)
        try:
            row.reforwarded_at = _now_madrid()
            row.reforwarded_count = _safe_int(getattr(row, "reforwarded_count", 0)) + 1
            session_db.commit()
        except Exception:
            session_db.rollback()
        link = _external_url_for("public_invitation_delivery", kind="r", token=row.delivery_token)
        msg = _invitation_share_text(session_db, concert, row.guest_name, link)
        phone = _normalize_phone_intl(_invitation_guest_live_phone(session_db, row))
        if channel == "sms":
            url = ("sms:" + ("+" + phone if phone else "") + "?&body=" + quote_plus(msg))
        else:
            url = (("https://wa.me/" + phone + "?text=") if phone else "https://wa.me/?text=") + quote_plus(msg)
        return redirect(url)
    finally:
        session_db.close()


@app.get("/invitaciones/entrega/<kind>/<token>", endpoint="public_invitation_delivery")
def public_invitation_delivery(kind, token):
    """Página del enlace que se envía por WhatsApp/SMS: composición visual (logo de la empresa del
    grupo, «Invitaciones», datos del evento, artista, invitado y nº de invitaciones) + descarga."""
    session_db = db()
    try:
        kind = (kind or "").strip().lower()
        if kind == "c":
            row = session_db.query(InvitationCommitment).filter(InvitationCommitment.delivery_token == token).first()
            if not row:
                abort(404)
            concert = row.concert or session_db.get(Concert, row.concert_id)
            # En COMPROMISOS el título es el NOMBRE DEL COMPROMISO (no la persona que recibe).
            guest_name = (getattr(row, "name", None) or "").strip()
            download_url = url_for("invitation_commitment_download", token=token)
            cat = (request.args.get("category") or "").strip()
            if cat:
                download_url = download_url + ("&" if "?" in download_url else "?") + "category=" + cat
        else:
            row = session_db.query(InvitationRequest).filter(InvitationRequest.delivery_token == token).first()
            if not row:
                abort(404)
            concert = row.concert or session_db.get(Concert, row.concert_id)
            guest_name = (getattr(row, "guest_name", None) or "").strip()
            download_url = url_for("invitation_request_download", token=token)
        # Lista de entradas agrupada (zona → categoría → sector) con descarga individual, igual que en
        # el correo. Reutiliza el mismo componente.
        _catf = None
        if kind == "c":
            _tq = session_db.query(InvitationTicket).filter(InvitationTicket.assigned_commitment_id == row.id)
            _catf = _safe_uuid((request.args.get("category") or "").strip())
            if _catf:
                _tq = _tq.filter(InvitationTicket.category_id == _catf)
        else:
            _tq = session_db.query(InvitationTicket).filter(InvitationTicket.assigned_request_id == row.id)
        _dtickets = _tq.order_by(InvitationTicket.sector.asc().nullslast(), InvitationTicket.row_label.asc().nullslast(), InvitationTicket.seat_number.asc().nullslast(), InvitationTicket.uploaded_at.asc()).all()
        # Nº de invitaciones DE ESTA ENTREGA (no el total del compromiso/solicitud): las entradas que
        # de verdad van con este enlace; si no hay PDF (listas de invitados), lo pedido en la
        # categoría del enlace o, sin filtro, el total.
        _q_all = _json_dict(getattr(row, "quantities_json", None))
        qty = len(_dtickets) or (_safe_int(_q_all.get(str(_catf))) if _catf else _invitation_total_qty(_q_all))
        tickets_html = Markup(_invitation_tickets_grouped_html(session_db, concert, _dtickets, download_url)) if _dtickets else ""
        card = _public_share_card(session_db, "CONCERT", concert, getattr(concert, "artist_id", None))
        poster_url = _concert_poster_url(concert) or ""      # cartel principal (solo si lo hay)
        artist_photo = (getattr(getattr(concert, "artist", None), "photo_url", None) or "").strip()  # foto real del artista
        show_time = "" if getattr(concert, "show_time_tbc", False) else (getattr(concert, "show_time", None) or "").strip()
        venue_name = _invitation_event_venue_name(concert) if concert else ""
        logo = _invitation_event_logo_url(session_db, concert, external=False)
        bits = [x for x in [card["activity_label"], (card["event_name"] or card["city"]), card["date_label"]] if x]
        qty_label = (str(qty) + (" invitación" if qty == 1 else " invitaciones")) if qty else ""
        # Título: «Invitaciones · <artista> · <invitado/compromiso>».
        _title_bits = ["Invitaciones"]
        if card["artist_name"]:
            _title_bits.append(card["artist_name"])
        if guest_name:
            _title_bits.append(guest_name)
        og = {
            "title": " · ".join(_title_bits),
            "description": " · ".join([x for x in [" · ".join(bits), qty_label] if x]),
            # Cartel principal → foto de cualquier artista del evento → logo (siempre absoluta).
            "image": _public_share_og_image(session_db, concert, card=card,
                                            logo=_invitation_event_logo_url(session_db, concert, external=True)),
        }
        return render_template("public_invitation_delivery.html", logo=logo, card=card, guest_name=guest_name,
                               poster_url=poster_url, artist_photo=artist_photo, show_time=show_time, venue_name=venue_name,
                               qty=qty, qty_label=qty_label, download_url=download_url, tickets_html=tickets_html, og=og)
    finally:
        session_db.close()


def _invitation_list_type_label(value: str | None) -> str:
    key = (value or "COMPLETE").strip().upper()
    return {"COMPLETE": "Listado completo", "DOOR": "Listado de puerta", "BOX_OFFICE": "Listado de taquilla"}.get(key, "Listado completo")


def _invitation_request_list_kind(session_db, row: InvitationRequest, categories: list[InvitationCategory]) -> set[str]:
    modes = set()
    quantities = _json_dict(row.quantities_json)
    cat_map = {str(c.id): c for c in categories}
    for cid, qty in quantities.items():
        if _safe_int(qty) <= 0:
            continue
        cat = cat_map.get(str(cid))
        if cat and (cat.ticket_kind or '').upper() == 'GUEST_LIST':
            modes.add((cat.guest_list_mode or 'BOX_OFFICE').upper())
    rm = (row.receiver_mode or '').upper()
    if rm in {'BOX_OFFICE', 'DOOR'}:
        modes.add('DOOR' if rm == 'DOOR' else 'BOX_OFFICE')
    if (row.status or '') in {'DISPONIBLES_TAQUILLA', 'RECOGIDAS_TAQUILLA'}:
        modes.add('BOX_OFFICE')
    if not modes:
        modes.add('COMPLETE')
    return modes


def _invitation_guest_list_rows(session_db, concert: Concert, list_type: str | None = 'COMPLETE') -> list[dict]:
    list_type = (list_type or 'COMPLETE').strip().upper()
    categories = _invitation_get_categories(session_db, concert, ensure_defaults=False)
    rows = []
    valid_statuses = {'APROBADAS', 'ASIGNADAS', 'ENVIADAS', 'ENTREGADAS_MANO', 'DISPONIBLES_TAQUILLA', 'RECOGIDAS_TAQUILLA'}
    query = (session_db.query(InvitationRequest)
             .options(joinedload(InvitationRequest.guest_promoter))
             .filter(InvitationRequest.concert_id == concert.id, InvitationRequest.status.in_(valid_statuses))
             .order_by(InvitationRequest.guest_name.asc().nullslast(), InvitationRequest.created_at.asc()))
    for row in query.all():
        modes = _invitation_request_list_kind(session_db, row, categories)
        if list_type == 'DOOR' and 'DOOR' not in modes:
            continue
        if list_type == 'BOX_OFFICE' and 'BOX_OFFICE' not in modes:
            continue
        payload = _invitation_request_payload(row, categories)
        flags = _invitation_request_kind_flags(session_db, row, categories)
        payload.update(flags)
        payload['list_modes'] = list(modes)
        payload['list_type'] = 'DOOR' if 'DOOR' in modes else ('BOX_OFFICE' if 'BOX_OFFICE' in modes else 'COMPLETE')
        payload['list_type_label'] = _invitation_list_type_label(payload['list_type'])
        payload['show_check'] = list_type in {'DOOR', 'BOX_OFFICE'} or payload['list_type'] in {'DOOR', 'BOX_OFFICE'}
        payload['download_url'] = _invitation_request_download_url(row) if flags.get('can_download_pdf') else payload.get('download_url')
        rows.append(payload)
    rows.sort(key=lambda x: _invitation_normalize_search(x.get('guest_name') or ''))
    return rows


def _build_invitation_guest_list_pdf(session_db, concert: Concert, list_type: str | None = 'COMPLETE') -> bytes:
    rows = _invitation_guest_list_rows(session_db, concert, list_type)
    event = _invitation_event_payload(session_db, concert)
    if not REPORTLAB_AVAILABLE:
        lines = ["Invitados", _invitation_list_type_label(list_type), " · ".join([x for x in [event.get('artist_names'), event.get('date_label'), event.get('venue'), event.get('city')] if x]), ""]
        for r in rows:
            lines.append(f"{r.get('guest_name','')} | {r.get('link_summary_text','')} | {r.get('guest_title','')} | {r.get('quantities_label','')} | {r.get('status_label','')}")
        return "\n".join(lines).encode('utf-8')
    buf = BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, leftMargin=34, rightMargin=34, topMargin=34, bottomMargin=34)
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle('InvGuestTitle', parent=styles['Title'], alignment=TA_CENTER, fontSize=18, leading=22)
    small = ParagraphStyle('InvGuestSmall', parent=styles['Normal'], fontSize=8, leading=10)
    normal = ParagraphStyle('InvGuestNormal', parent=styles['Normal'], fontSize=9, leading=11)
    story = []
    logo_cell = ''
    logo_url = _invitation_event_logo_url(session_db, concert)
    if logo_url:
        try:
            logo_cell = _rl_image_flowable_from_url(logo_url, 3.1, 1.25) or ''
        except Exception:
            logo_cell = ''
    header_text = '<br/>'.join([html.escape(x) for x in [event.get('artist_names'), event.get('type_label'), event.get('date_label'), event.get('venue'), event.get('city')] if x])
    header = Table([[Paragraph(header_text or 'Evento', normal), logo_cell]], colWidths=[360, 120])
    header.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'), ('ALIGN',(1,0),(1,0),'RIGHT')]))
    story.extend([header, Spacer(1, 10), Paragraph('Invitados', title_style), Paragraph(html.escape(_invitation_list_type_label(list_type)), ParagraphStyle('InvGuestSub', parent=small, alignment=TA_CENTER)), Spacer(1, 12)])
    data = [[Paragraph('<b>Invitado</b>', small), Paragraph('<b>Vinculación</b>', small), Paragraph('<b>Título</b>', small), Paragraph('<b>Categoría / nº</b>', small), Paragraph('<b>Estado</b>', small), Paragraph('<b>Check</b>', small)]]
    for r in rows:
        check = '☐' if (list_type or '').upper() in {'DOOR','BOX_OFFICE'} or r.get('show_check') else ''
        status = '' if (r.get('status') == 'APROBADAS') else (r.get('status_label') or '')
        data.append([
            Paragraph(html.escape(r.get('guest_name') or ''), normal),
            Paragraph(html.escape(r.get('link_summary_text') or ''), normal),
            Paragraph(html.escape(r.get('guest_title') or ''), normal),
            Paragraph(html.escape(r.get('quantities_label') or ''), normal),
            Paragraph(html.escape(status), normal),
            Paragraph(check, normal),
        ])
    table = Table(data, colWidths=[105, 90, 85, 105, 70, 30], repeatRows=1)
    table.setStyle(TableStyle([('GRID',(0,0),(-1,-1),0.25,colors.HexColor('#d9dee6')),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#f3f4f6')),('VALIGN',(0,0),(-1,-1),'TOP'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white, colors.HexColor('#fbfcfd')])]))
    story.append(table)
    doc.build(story)
    return buf.getvalue()


# ── PDF de Compromisos / Peticiones (misma cabecera: logo de la empresa del grupo arriba a la
#    derecha, título "Invitaciones" centrado, cabecera del evento; paginado "1/1" abajo). ───────────
def _invitation_pdf_header_drawer(session_db, concert):
    """Devuelve una función onPage(canvas, doc) que pinta en CADA página: logo del grupo (arriba dcha.),
    título "Invitaciones" centrado y la cabecera del evento; y el nº de página "n/N" abajo centrado."""
    from reportlab.lib.utils import ImageReader
    logo_url = _invitation_event_logo_url(session_db, concert)
    logo_reader = None
    try:
        if logo_url:
            src = logo_url
            if isinstance(logo_url, str) and logo_url.startswith(("http://", "https://")):
                with urlopen(logo_url, timeout=6) as resp:
                    src = BytesIO(resp.read())
            logo_reader = ImageReader(src)
    except Exception:
        logo_reader = None
    event = _invitation_event_payload(session_db, concert) if concert else {}
    header_line = ' · '.join([x for x in [event.get('artist_names'), event.get('type_label'), event.get('date_label'), event.get('venue'), event.get('city')] if x])

    def _draw(canvas, doc):
        canvas.saveState()
        W, H = doc.pagesize
        # Logo del grupo arriba a la derecha.
        if logo_reader is not None:
            try:
                iw, ih = logo_reader.getSize()
                max_w, max_h = 130.0, 46.0
                scale = min(max_w / float(iw or 1), max_h / float(ih or 1))
                lw, lh = float(iw) * scale, float(ih) * scale
                canvas.drawImage(logo_reader, W - doc.rightMargin - lw, H - lh - 20, width=lw, height=lh, mask='auto', preserveAspectRatio=True)
            except Exception:
                pass
        # Título centrado.
        canvas.setFillColor(colors.HexColor('#111111'))
        canvas.setFont('Helvetica-Bold', 17)
        canvas.drawCentredString(W / 2.0, H - 40, 'Invitaciones')
        # Cabecera del evento.
        if header_line:
            canvas.setFont('Helvetica', 8.5)
            canvas.setFillColor(colors.HexColor('#444444'))
            canvas.drawCentredString(W / 2.0, H - 56, header_line[:160])
        # El nº de página "n/N" lo pinta el canvas numerado en la segunda pasada (para saber el total).
        canvas.restoreState()
    return _draw


class _InvitationNumberedCanvas(canvas.Canvas if REPORTLAB_AVAILABLE else object):
    """Canvas de dos pasadas para poder escribir el total de páginas en "n/N"."""
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._saved_states = []

    def showPage(self):
        self._saved_states.append(dict(self.__dict__))
        self._startPage()

    def save(self):
        total = len(self._saved_states)
        for state in self._saved_states:
            self.__dict__.update(state)
            self._replace_page_total(total)
            super().showPage()
        super().save()

    def _replace_page_total(self, total):
        # Pinta "n/N" centrado en el pie (segunda pasada, cuando ya se conoce el total).
        try:
            W = self._pagesize[0]
            self.saveState()
            self.setFont('Helvetica', 7.5)
            self.setFillColor(colors.HexColor('#888888'))
            self.drawCentredString(W / 2.0, 18, "%d/%d" % (self.getPageNumber(), total))
            self.restoreState()
        except Exception:
            pass


def _build_invitation_commitments_pdf(session_db, concert: Concert) -> bytes:
    """PDF de "Compromisos de invitaciones" tal como se ven: por compromiso, para quién es, quién lo
    añadió y a quién se manda; y debajo sus categorías (color, aforo del palco, nº, ubicación, estado)."""
    categories = _invitation_get_categories(session_db, concert, ensure_defaults=False)
    _cat_meta = {}
    for i, c in enumerate(categories):
        _cat_meta[str(c.id)] = {
            'color': INVITATION_ASSIGNEE_COLORS[i % len(INVITATION_ASSIGNEE_COLORS)],
            'zone': _invitation_category_zone(c),
            'configured': _safe_int(getattr(c, 'qty_contract', 0)) + _safe_int(getattr(c, 'qty_extra', 0)),
        }
    name_map = _invitation_category_name_map(categories)
    rows = list(session_db.query(InvitationCommitment).filter(InvitationCommitment.concert_id == concert.id).order_by(InvitationCommitment.created_at.asc()).all())
    if not REPORTLAB_AVAILABLE:
        return ("Compromisos de invitaciones\n" + "\n".join(r.name or '' for r in rows)).encode('utf-8')
    buf = BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, leftMargin=28, rightMargin=28, topMargin=76, bottomMargin=30)
    styles = getSampleStyleSheet()
    h = ParagraphStyle('InvCmtH', parent=styles['Normal'], fontSize=10.5, leading=13, spaceBefore=8, spaceAfter=2, textColor=colors.HexColor('#111111'))
    meta = ParagraphStyle('InvCmtMeta', parent=styles['Normal'], fontSize=8, leading=10, textColor=colors.HexColor('#555555'))
    cell = ParagraphStyle('InvCmtCell', parent=styles['Normal'], fontSize=8, leading=10)
    story = [Paragraph('Compromisos de invitaciones', ParagraphStyle('InvCmtTitle', parent=styles['Normal'], fontSize=12, leading=14, spaceAfter=6, textColor=colors.HexColor('#111111')))]
    if not rows:
        story.append(Paragraph('No hay compromisos configurados.', meta))
    for r in rows:
        q = _json_dict(r.quantities_json)
        _tk_by_cat = defaultdict(list)
        for _st, _cidt in session_db.query(InvitationTicket.status, InvitationTicket.category_id).filter(InvitationTicket.assigned_commitment_id == r.id).all():
            _tk_by_cat[str(_cidt)].append(_st)
        _dl_cats = _json_dict(getattr(r, 'downloaded_categories_json', None))
        _idn = _invitation_guest_identity(session_db, r)
        _rcpt = _idn.get('name') or r.guest_name or ''
        _link = _promoter_link_summary_text(_idn.get('link_summary') or {})
        top = '<b>' + html.escape(r.name or '') + '</b>'
        if r.reason:
            top += ' · ' + html.escape(r.reason)
        story.append(Paragraph(top, h))
        sub = []
        if _rcpt:
            sub.append('Enviar a: ' + html.escape(_rcpt) + (' (' + html.escape(_link) + ')' if _link else ''))
        if (r.created_by_nick or '').strip():
            sub.append('Añadido por: ' + html.escape((r.created_by_nick or '').strip()))
        if sub:
            story.append(Paragraph(' · '.join(sub), meta))
        data = [[Paragraph('<b>Nº</b>', cell), Paragraph('<b>Categoría</b>', cell), Paragraph('<b>Ubicación</b>', cell), Paragraph('<b>Descarga</b>', cell), Paragraph('<b>Estado</b>', cell)]]
        for _cid, _qv in q.items():
            if str(_cid) == 'TOTAL':
                continue
            _qn = _safe_int(_qv)
            if _qn <= 0:
                continue
            _sts = _tk_by_cat.get(str(_cid), [])
            _asg = len(_sts)
            _lbl, _bdg = _invitation_commitment_state_from_statuses(_sts)
            if not _sts and (getattr(r, 'status', '') or '').upper() == 'ENVIADAS':
                _lbl = 'Enviadas'
            _m = _cat_meta.get(str(_cid), {})
            _nm = name_map.get(str(_cid), 'Categoría')
            if _m.get('zone') == 'PALCO' and _m.get('configured') and 'honor' not in _nm.lower():
                _nm += ' (Aforo: %d)' % _m['configured']
            data.append([
                Paragraph('%d/%d' % (_asg, _qn), cell),
                Paragraph(html.escape(_nm), cell),
                Paragraph(html.escape(name_map.get(str(_cid), '')), cell),
                Paragraph('Sí' if str(_cid) in _dl_cats else '—', cell),
                Paragraph(html.escape(_lbl or ''), cell),
            ])
        t = Table(data, colWidths=[36, 200, 150, 48, 105], repeatRows=1)
        _ts = [('GRID', (0, 0), (-1, -1), 0.25, colors.HexColor('#d9dee6')), ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#f3f4f6')), ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.HexColor('#fbfcfd')]), ('LEFTPADDING', (0, 0), (-1, -1), 4), ('RIGHTPADDING', (0, 0), (-1, -1), 4), ('TOPPADDING', (0, 0), (-1, -1), 2), ('BOTTOMPADDING', (0, 0), (-1, -1), 2)]
        # Franja de color por categoría en la primera columna (misma estética que en pantalla).
        for _ri, (_cid, _qv) in enumerate([kv for kv in q.items() if str(kv[0]) != 'TOTAL' and _safe_int(kv[1]) > 0], start=1):
            _col = _cat_meta.get(str(_cid), {}).get('color', '#9ca3af')
            _ts.append(('LINEBEFORE', (0, _ri), (0, _ri), 4, colors.HexColor(_col)))
        t.setStyle(TableStyle(_ts))
        story.append(t)
        if (r.note or '').strip():
            story.append(Paragraph('Nota: ' + html.escape(r.note.strip()), meta))
    _drawer = _invitation_pdf_header_drawer(session_db, concert)
    doc.build(story, onFirstPage=_drawer, onLaterPages=_drawer, canvasmaker=_InvitationNumberedCanvas)
    return buf.getvalue()


def _build_invitation_requests_pdf(session_db, concert: Concert) -> bytes:
    """PDF de "Peticiones de invitaciones" agrupadas por categoría (color + aforo del palco), con
    invitado, vínculo, nº de entradas, ubicación/categorías, descarga y estado."""
    categories = _invitation_get_categories(session_db, concert, ensure_defaults=False)
    color_by = {str(c.id): INVITATION_ASSIGNEE_COLORS[i % len(INVITATION_ASSIGNEE_COLORS)] for i, c in enumerate(categories)}
    conf_by = {str(c.id): _safe_int(getattr(c, 'qty_contract', 0)) + _safe_int(getattr(c, 'qty_extra', 0)) for c in categories}
    zone_by = {str(c.id): _invitation_category_zone(c) for c in categories}
    reqs = []
    for row in session_db.query(InvitationRequest).filter(InvitationRequest.concert_id == concert.id).filter(~InvitationRequest.status.in_(['RECHAZADAS', 'ANULADAS'])).order_by(InvitationRequest.created_at.desc()).all():
        reqs.append(_invitation_request_payload(row, categories))
    _invitation_group_requests(reqs, categories)
    groups = _invitation_grouped(reqs, categories)
    groups = [g for g in groups if g.get('rows')]
    if not REPORTLAB_AVAILABLE:
        return ("Peticiones de invitaciones\n" + "\n".join((g.get('name') or '') for g in groups)).encode('utf-8')
    buf = BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, leftMargin=28, rightMargin=28, topMargin=76, bottomMargin=30)
    styles = getSampleStyleSheet()
    cell = ParagraphStyle('InvReqCell', parent=styles['Normal'], fontSize=8, leading=10)
    grp = ParagraphStyle('InvReqGrp', parent=styles['Normal'], fontSize=10, leading=12, spaceBefore=8, spaceAfter=2, textColor=colors.HexColor('#111111'))
    story = [Paragraph('Peticiones de invitaciones', ParagraphStyle('InvReqTitle', parent=styles['Normal'], fontSize=12, leading=14, spaceAfter=6, textColor=colors.HexColor('#111111')))]
    if not groups:
        story.append(Paragraph('No hay peticiones.', cell))
    for g in groups:
        _gname = g.get('name') or 'Sin categoría'
        if g.get('zone') == 'PALCO' and g.get('configured') and 'honor' not in _gname.lower():
            _gname += ' (Aforo: %d)' % _safe_int(g.get('configured'))
        _col = g.get('color', '#9ca3af')
        story.append(Paragraph('<font color="%s">■</font> %s · %d' % (_col, html.escape(_gname), _safe_int(g.get('total'))), grp))
        data = [[Paragraph('<b>Invitado</b>', cell), Paragraph('<b>Vínculo</b>', cell), Paragraph('<b>Nº</b>', cell), Paragraph('<b>Ubicación</b>', cell), Paragraph('<b>Descarga</b>', cell), Paragraph('<b>Estado</b>', cell)]]
        for r in g.get('rows', []):
            data.append([
                Paragraph(html.escape(r.get('guest_name') or '') + (' · ' + html.escape(r.get('guest_title')) if r.get('guest_title') else ''), cell),
                Paragraph(html.escape(r.get('link_summary_text') or ''), cell),
                Paragraph(str(_safe_int(r.get('qty_total'))), cell),
                Paragraph(html.escape(r.get('categories_label') or ''), cell),
                Paragraph('Sí' if r.get('downloaded_at_label') else '—', cell),
                Paragraph(html.escape(r.get('status_label') or ''), cell),
            ])
        t = Table(data, colWidths=[150, 120, 26, 130, 46, 90], repeatRows=1)
        _ts = [('GRID', (0, 0), (-1, -1), 0.25, colors.HexColor('#d9dee6')), ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#f3f4f6')), ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.HexColor('#fbfcfd')]), ('LINEBEFORE', (0, 1), (0, -1), 4, colors.HexColor(_col)), ('LEFTPADDING', (0, 0), (-1, -1), 4), ('RIGHTPADDING', (0, 0), (-1, -1), 4), ('TOPPADDING', (0, 0), (-1, -1), 2), ('BOTTOMPADDING', (0, 0), (-1, -1), 2)]
        t.setStyle(TableStyle(_ts))
        story.append(t)
    _drawer = _invitation_pdf_header_drawer(session_db, concert)
    doc.build(story, onFirstPage=_drawer, onLaterPages=_drawer, canvasmaker=_InvitationNumberedCanvas)
    return buf.getvalue()


def _invitation_rejection_email_body(session_db, row: InvitationRequest, reason: str | None = None) -> tuple[str, str, str]:
    concert = row.concert or session_db.get(Concert, row.concert_id)
    event = _invitation_event_payload(session_db, concert) if concert else {}
    subject = f"Solicitud de invitaciones rechazada · {event.get('artist_names') or event.get('title') or ''}".strip(" ·")
    html_body = f"""
    <div style="font-family:Arial,sans-serif;line-height:1.45;color:#111">
      <h2>Solicitud de invitaciones rechazada</h2>
      <p>La solicitud de invitaciones para <b>{html.escape(row.guest_name or '')}</b> ha sido rechazada.</p>
      <p><b>Evento:</b> {html.escape(' · '.join([x for x in [event.get('type_label'), event.get('artist_names'), event.get('date_label'), event.get('city'), event.get('venue')] if x]))}</p>
      {f'<p><b>Motivo:</b> {html.escape(reason)}</p>' if reason else ''}
    </div>
    """
    text_body = f"La solicitud de invitaciones para {row.guest_name or ''} ha sido rechazada. {reason or ''}"
    return subject, html_body, text_body


@app.get('/invitaciones', endpoint='invitations_view')
@admin_required
def invitations_view():
    tab = (request.args.get('tab') or 'pedir').strip().lower()
    if tab == 'mis':
        tab = 'pedir'
    if tab not in {'pedir', 'gestionar'}:
        tab = 'pedir'
    session_db = db()
    try:
        artists = _invitation_artist_options(session_db)
        event_artists = _invitation_event_artist_options(session_db)
        personnel = _invitation_personnel_options(session_db)
        # Prefill del asistente "Pedir invitaciones" al llegar desde la ficha de un tercero
        # (?for_promoter=<id>): preselecciona a ese tercero como invitado (THIRD_PARTY). El JS de
        # la plantilla abre el asistente y rellena el buscador de terceros con estos datos.
        prefill_guest = None
        for_promoter_id = _safe_uuid(request.args.get('for_promoter'))
        if for_promoter_id:
            _pr = session_db.get(Promoter, for_promoter_id)
            if _pr:
                _ls = _promoter_link_summary(session_db, _pr)
                prefill_guest = {
                    'id': str(_pr.id),
                    'label': _promoter_display_name(_pr) or _pr.nick or 'Tercero',
                    'contact_email': (_pr.contact_email or '').strip(),
                    'contact_phone': (_pr.contact_phone or '').strip(),
                    'logo_url': _pr.logo_url or '',
                    'link_summary': _ls,
                    'link_summary_text': _promoter_link_summary_text(_ls),
                }
        query_start = _invitation_event_query_start_date()
        query = (
            session_db.query(Concert)
            .options(joinedload(Concert.artist), joinedload(Concert.venue))
            .filter(or_(Concert.date == None, Concert.date >= query_start))  # noqa: E711
            .order_by(Concert.date.asc().nullslast(), Concert.created_at.desc())
            .limit(160)
        )
        now_value = _now_madrid()
        candidates = []
        for concert in query.all():
            if not _invitation_event_is_active_for_requests(concert, now_value=now_value):
                continue
            # Se incluyen TODOS los conciertos activos (tengan o no invitaciones configuradas o
            # solicitudes); en "Gestionar" el filtrado por perfil (artistas asignados no-grupo /
            # ticketing con empresa del grupo) lo hace _filter_manageable_concerts más abajo.
            candidates.append(concert)
        # En "Gestionar" cada usuario solo ve lo que le corresponde (artistas asignados; Ticketing ->
        # empresas del grupo; opt-ins de "Gestionar otros"). Dirección (rol 10) ve todo.
        if tab == 'gestionar':
            candidates = _filter_manageable_concerts(session_db, candidates, state=_current_user_state())
        events = [_invitation_event_payload(session_db, c, include_counts=True) for c in candidates]
        if tab == 'gestionar':
            # Estado por evento (pendiente/taquilla/enviadas) en una sola consulta agregada, y orden
            # por urgencia: pendientes primero, luego taquilla, luego enviadas (estable -> respeta el
            # orden cronológico dentro de cada nivel).
            _status_map = _invitation_manage_status_map(session_db, candidates)
            for ev in events:
                ev['manage_status'] = _status_map.get(ev.get('id'), {"pending": 0, "box_office": 0, "managed": False})

            def _manage_urgency(ev):
                ms = ev.get('manage_status') or {}
                if ms.get('pending'):
                    return 0
                if ms.get('box_office'):
                    return 1
                if ms.get('managed'):
                    return 2
                return 3
            events.sort(key=_manage_urgency)
        # Agrupado por artista para la pestaña Gestionar: un grupo por artista, en orden de aparición
        # (el del evento más próximo primero, porque `events` ya viene cronológico) y eventos
        # cronológicos dentro de cada grupo.
        events_by_artist = []
        if tab == 'gestionar':
            _agroups = {}
            for ev in events:
                arts = ev.get('artists') or [{'id': '', 'name': 'Sin artista', 'photo_url': None}]
                for a in arts:
                    akey = str(a.get('id') or a.get('name') or '')
                    grp = _agroups.get(akey)
                    if grp is None:
                        grp = {'artist': a, 'events': []}
                        _agroups[akey] = grp
                        events_by_artist.append(grp)
                    grp['events'].append(ev)
            # Dentro de cada artista, los conciertos SIEMPRE en orden cronológico (del más próximo al
            # más lejano). Los sin fecha van al final. (El orden por urgencia solo ordena los artistas.)
            _date_by_id = {str(c.id): getattr(c, 'date', None) for c in candidates}
            for grp in events_by_artist:
                grp['events'].sort(key=lambda ev: (_date_by_id.get(ev.get('id')) is None, _date_by_id.get(ev.get('id')) or date.max))
        current_user_id = _safe_uuid(session.get('user_id'))
        my_requests = []
        my_denied_count = 0
        office_requests = []
        show_denied = _truthy(request.args.get('show_denied'))
        # "Ver las pedidas para otros de la oficina": al pedir invitaciones "para alguien de la
        # empresa" la solicitud se reasigna a esa persona (requester != yo), por lo que no aparece en
        # MI listado. Quien la registró (yo) puede mostrarlas para saber cómo están.
        show_office = _truthy(request.args.get('show_office'))
        if current_user_id:
            base_q = (
                session_db.query(InvitationRequest)
                .options(joinedload(InvitationRequest.concert))
                .filter(InvitationRequest.requester_user_id == current_user_id)
                .order_by(InvitationRequest.created_at.desc())
                .limit(180)
            )
            for row in base_q.all():
                if not _invitation_concert_visible_for_user(row.concert):
                    continue
                is_denied = (row.status or '') in {'RECHAZADAS', 'ANULADAS'}
                if is_denied:
                    my_denied_count += 1
                    if not show_denied:
                        continue
                concert = row.concert
                cats = _invitation_get_categories(session_db, concert, ensure_defaults=False) if concert else []
                item = _invitation_request_payload(row, cats)
                item.update(_invitation_request_kind_flags(session_db, row, cats))
                item['event'] = _invitation_event_payload(session_db, concert) if concert else {}
                item['is_denied'] = is_denied
                item['for_office'] = False
                my_requests.append(item)
                if len(my_requests) >= 120:
                    break
            # Peticiones que YO registré PARA otra persona de la oficina (requester != yo). Se cargan
            # siempre para saber si hay que ofrecer el botón; solo se intercalan si show_office. Son de
            # solo lectura aquí (no soy el peticionario): la plantilla no muestra acciones sobre ellas.
            office_q = (
                session_db.query(InvitationRequest)
                .options(joinedload(InvitationRequest.concert))
                .filter(InvitationRequest.created_by_user_id == current_user_id)
                .filter(InvitationRequest.requester_user_id != current_user_id)
                .order_by(InvitationRequest.created_at.desc())
                .limit(180)
            )
            for row in office_q.all():
                if not _invitation_concert_visible_for_user(row.concert):
                    continue
                is_denied = (row.status or '') in {'RECHAZADAS', 'ANULADAS'}
                if is_denied and not show_denied:
                    continue
                concert = row.concert
                cats = _invitation_get_categories(session_db, concert, ensure_defaults=False) if concert else []
                item = _invitation_request_payload(row, cats)
                item['event'] = _invitation_event_payload(session_db, concert) if concert else {}
                item['is_denied'] = is_denied
                item['for_office'] = True
                office_requests.append(item)
                if len(office_requests) >= 120:
                    break
        # Agrupadas por actividad (evento), conservando el orden de aparición. Si el usuario activó
        # "ver las pedidas para otros", se intercalan en el grupo del mismo evento (detrás de las suyas).
        grouping_source = list(my_requests)
        if show_office:
            grouping_source.extend(office_requests)
        my_requests_by_event = []
        _mr_index = {}
        for item in grouping_source:
            ev = item.get('event') or {}
            key = ev.get('id') or 'sin-evento'
            grp = _mr_index.get(key)
            if grp is None:
                grp = {'event': ev, 'requests': []}
                _mr_index[key] = grp
                my_requests_by_event.append(grp)
            grp['requests'].append(item)
        return render_template(
            'invitaciones.html',
            tab=tab,
            artists=artists,
            event_artists=event_artists,
            personnel=personnel,
            events=events,
            events_by_artist=events_by_artist,
            my_requests=my_requests,
            my_requests_by_event=my_requests_by_event,
            my_denied_count=my_denied_count,
            office_requests=office_requests,
            show_office=show_office,
            show_denied=show_denied,
            category_types=INVITATION_CATEGORY_TYPES,
            guest_list_modes=INVITATION_GUEST_LIST_MODES,
            status_labels=INVITATION_STATUS_LABELS,
            entity_link_types=APP33_ENTITY_LINK_TYPES,
            prefill_guest=prefill_guest,
        )
    finally:
        session_db.close()


@app.get('/api/invitaciones/gestionar-otros/artistas', endpoint='api_invitation_manage_others_artists')
@admin_required
def api_invitation_manage_others_artists():
    """Artistas con actividades futuras que el usuario NO gestiona todavía ('Gestionar otros')."""
    state = _current_user_state()
    session_db = db()
    try:
        if int(state.get('role') or 0) != 10 and not _state_has_access(state, 'invitaciones.gestionar', include_descendants=True):
            return jsonify({'ok': False, 'artists': []}), 403
        query_start = _invitation_event_query_start_date()
        now_value = _now_madrid()
        concerts = (
            session_db.query(Concert)
            .options(joinedload(Concert.artist))
            .filter(or_(Concert.date == None, Concert.date >= query_start))  # noqa: E711
            .order_by(Concert.date.asc().nullslast(), Concert.created_at.desc())
            .limit(400)
            .all()
        )
        active = [c for c in concerts if _invitation_event_is_active_for_requests(c, now_value=now_value)]
        managed_ids = {str(c.id) for c in _filter_manageable_concerts(session_db, active, state=state)}
        not_managed = [c for c in active if str(c.id) not in managed_ids]
        counts: dict[str, int] = {}
        for c in not_managed:
            for aid in _concert_artist_ids(c):
                if aid:
                    counts[aid] = counts.get(aid, 0) + 1
        if not counts:
            return jsonify({'ok': True, 'artists': []})
        uuids = [u for u in (_safe_uuid(a) for a in counts.keys()) if u]
        rows = session_db.query(Artist).filter(Artist.id.in_(uuids)).all() if uuids else []
        artists = []
        for a in rows:
            payload = _artist_chip_payload(a)
            payload['activity_count'] = counts.get(str(a.id), 0)
            artists.append(payload)
        artists.sort(key=lambda x: (-x['activity_count'], (x.get('name') or '').lower()))
        return jsonify({'ok': True, 'artists': artists})
    finally:
        session_db.close()


@app.get('/api/invitaciones/gestionar-otros/artista/<artist_id>/actividades', endpoint='api_invitation_manage_others_activities')
@admin_required
def api_invitation_manage_others_activities(artist_id):
    """Actividades futuras de un artista que el usuario aún no gestiona."""
    state = _current_user_state()
    aid = _safe_uuid(artist_id)
    session_db = db()
    try:
        if not aid:
            return jsonify({'ok': False, 'events': []}), 400
        query_start = _invitation_event_query_start_date()
        now_value = _now_madrid()
        concerts = (
            session_db.query(Concert)
            .options(joinedload(Concert.artist), joinedload(Concert.venue))
            .filter(or_(Concert.date == None, Concert.date >= query_start))  # noqa: E711
            .order_by(Concert.date.asc().nullslast(), Concert.created_at.desc())
            .limit(400)
            .all()
        )
        active = [c for c in concerts if _invitation_event_is_active_for_requests(c, now_value=now_value)]
        managed_ids = {str(c.id) for c in _filter_manageable_concerts(session_db, active, state=state)}
        target = [c for c in active if str(aid) in set(_concert_artist_ids(c)) and str(c.id) not in managed_ids]
        events = [_invitation_event_payload(session_db, c, include_counts=True) for c in target]
        return jsonify({'ok': True, 'events': events})
    finally:
        session_db.close()


@app.post('/invitaciones/gestionar-otros/anadir', endpoint='invitation_manage_others_add')
@admin_required
def invitation_manage_others_add():
    """Añade una actividad a la lista de gestión del usuario ('Gestionar otros')."""
    state = _current_user_state()
    uid = _safe_uuid(state.get('user_id'))
    data = request.get_json(silent=True) or {}
    concert_id = _safe_uuid(request.form.get('concert_id') or data.get('concert_id'))
    if not uid or not concert_id:
        return jsonify({'ok': False, 'error': 'Datos incompletos'}), 400
    session_db = db()
    try:
        concert = session_db.get(Concert, concert_id)
        if not concert:
            return jsonify({'ok': False, 'error': 'Actividad no encontrada'}), 404
        existing = session_db.query(InvitationManagerOptIn).filter_by(user_id=uid, concert_id=concert_id).first()
        if not existing:
            session_db.add(InvitationManagerOptIn(user_id=uid, concert_id=concert_id))
            session_db.commit()
        return jsonify({'ok': True, 'concert_id': str(concert_id)})
    except Exception as exc:
        session_db.rollback()
        return jsonify({'ok': False, 'error': str(exc)}), 500
    finally:
        session_db.close()


@app.get('/api/invitaciones/eventos', endpoint='api_invitation_events')
@admin_required
def api_invitation_events():
    artist_id = (request.args.get('artist_id') or '').strip()
    include_all = _truthy(request.args.get('all'))
    session_db = db()
    try:
        aid = str(_safe_uuid(artist_id) or '')
        query_start = _invitation_event_query_start_date()
        q = (
            session_db.query(Concert)
            .options(joinedload(Concert.artist), joinedload(Concert.venue))
            .filter(or_(Concert.date == None, Concert.date >= query_start))  # noqa: E711
            .order_by(Concert.date.asc().nullslast(), Concert.created_at.desc())
            .limit(220)
        )
        rows = []
        now_value = _now_madrid()
        for c in q.all():
            if not _invitation_event_is_active_for_requests(c, now_value=now_value):
                continue
            if aid and aid not in _concert_artist_ids(c):
                continue
            if (not include_all) and (not _invitation_event_has_config(session_db, c)):
                continue
            rows.append(_invitation_event_payload(session_db, c, include_counts=True))
        return jsonify({"ok": True, "events": rows})
    finally:
        session_db.close()


@app.get('/api/invitaciones/eventos/<concert_id>/categorias', endpoint='api_invitation_event_categories')
@admin_required
def api_invitation_event_categories(concert_id):
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        if not concert:
            abort(404)
        if not _invitation_event_is_active_for_requests(concert):
            return jsonify({'ok': False, 'message': 'Este concierto o evento ya no admite solicitudes de invitaciones.'}), 410
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=True)
        session_db.commit()
        counts = _invitation_event_counts(session_db, concert)
        # Un palco ya comprometido a alguien (aunque no se le hayan asignado las entradas) o un
        # palco COMPLETO (todas sus entradas asignadas/enviadas) NO se ofrece al pedir: desaparece
        # de la lista de categorías del asistente.
        committed_palco = _invitation_request_excluded_category_ids(session_db, concert, categories)
        # Color por CATEGORÍA (mismo criterio que en el listado de invitados: por orden de la
        # categoría en el evento), para que la franja de color sea idéntica en todas partes.
        _tk_counts = _invitation_ticket_counts_by_category(session_db, concert)
        cat_payloads = []
        for i, c in enumerate(categories):
            if str(c.id) in committed_palco:
                continue
            p = _invitation_category_payload(c, _tk_counts.get(str(c.id)))
            p['color'] = INVITATION_ASSIGNEE_COLORS[i % len(INVITATION_ASSIGNEE_COLORS)]
            cat_payloads.append(p)
        return jsonify({
            'ok': True,
            'event': _invitation_event_payload(session_db, concert, include_counts=True),
            'categories': cat_payloads,
            'counts': counts,
        })
    finally:
        session_db.close()


@app.get('/invitaciones/evento/<concert_id>', endpoint='invitation_event_detail')
@admin_required
def invitation_event_detail(concert_id):
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        if not concert:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)
        _ensure_invitation_link_columns(session_db)
        if not _invitation_event_is_active_for_requests(concert):
            flash('Este concierto o evento ya no aparece en gestión de invitaciones porque han pasado más de 5 horas desde el día del evento.', 'warning')
            return redirect(url_for('invitations_view', tab='gestionar'))
        # Origen para el botón "Volver": si se entra desde la ficha de la actividad (?from=ficha) se
        # recuerda en sesión por concierto, así sobrevive a las acciones internas (subir/asignar/enviar
        # recargan o redirigen aquí sin querystring). Desde la lista/inicio (?from=gestionar) se limpia.
        _back_origin = (request.args.get('from') or '').strip().lower()
        _back_map = session.get('inv_event_origin') or {}
        if _back_origin == 'ficha':
            _back_map[str(concert.id)] = 'ficha'
            session['inv_event_origin'] = _back_map
        elif _back_origin in ('gestionar', 'lista', 'inicio') and str(concert.id) in _back_map:
            _back_map.pop(str(concert.id), None)
            session['inv_event_origin'] = _back_map
        back_to_ficha = (session.get('inv_event_origin') or {}).get(str(concert.id)) == 'ficha'
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=True)
        session_db.commit()
        # Releer tras crear defaults para contar bien.
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=False)
        ticket_counts = _invitation_ticket_counts_by_category(session_db, concert)
        cat_payloads = [_invitation_category_payload(c, ticket_counts.get(str(c.id))) for c in categories]
        # Asignadas SIN enviar por categoría: para el botón «Enviar todas las asignadas» de la
        # cabecera de cada categoría (solo se muestra si hay algo que enviar).
        assigned_pending_by_category = {str(cid): int(n or 0) for cid, n in (
            session_db.query(InvitationTicket.category_id, func.count(InvitationTicket.id))
            .filter(InvitationTicket.concert_id == concert.id, InvitationTicket.status == 'ASSIGNED')
            .group_by(InvitationTicket.category_id).all())}
        for _i, _cp in enumerate(cat_payloads):
            _cp['color'] = INVITATION_ASSIGNEE_COLORS[_i % len(INVITATION_ASSIGNEE_COLORS)]
        # Meta por categoría (color/zona/aforo) para pintar las categorías del compromiso con la MISMA
        # estética de color que las peticiones.
        _cat_meta = {cp['id']: cp for cp in cat_payloads}
        name_map = _invitation_category_name_map(categories)
        # ---- PRECARGA en bloque (rendimiento con BD remota) ----
        # 1) Compromisos y solicitudes de una vez (se reutilizan en sus bucles de abajo).
        _cmt_rows_all = session_db.query(InvitationCommitment).filter(InvitationCommitment.concert_id == concert.id).order_by(InvitationCommitment.created_at.asc()).all()
        _req_rows_all = session_db.query(InvitationRequest).filter(InvitationRequest.concert_id == concert.id).order_by(InvitationRequest.created_at.desc()).all()
        # 2) Entidades invitadas (terceros/artistas/empleados) en 3 consultas IN: puebla el identity
        #    map de la sesión y los session.get() por fila (identidad EN VIVO) dejan de ser un viaje
        #    a la BD cada uno (~30 ms/consulta con la BD en otra región: los listados tardaban segundos).
        _all_guest_rows = _cmt_rows_all + _req_rows_all
        _pids = {x.guest_promoter_id for x in _all_guest_rows if getattr(x, 'guest_promoter_id', None)}
        _aids = {x.guest_artist_id for x in _all_guest_rows if getattr(x, 'guest_artist_id', None)}
        _uids = {x.guest_user_id for x in _all_guest_rows if getattr(x, 'guest_user_id', None)}
        _uids |= {x.created_by_user_id for x in _cmt_rows_all if getattr(x, 'created_by_user_id', None)}
        if _pids:
            session_db.query(Promoter).filter(Promoter.id.in_(list(_pids))).all()
        if _aids:
            session_db.query(Artist).filter(Artist.id.in_(list(_aids))).all()
        if _uids:
            session_db.query(UserProfile).filter(UserProfile.user_id.in_(list(_uids))).all()
        # 3) Estados de las entradas de TODOS los compromisos en UNA consulta agrupable (antes, una
        #    consulta por compromiso dentro del bucle).
        _tk_by_cmt: dict = defaultdict(lambda: defaultdict(list))
        for _st, _cidt, _cmid in (session_db.query(InvitationTicket.status, InvitationTicket.category_id, InvitationTicket.assigned_commitment_id)
                                  .filter(InvitationTicket.concert_id == concert.id, InvitationTicket.assigned_commitment_id.isnot(None)).all()):
            _tk_by_cmt[str(_cmid)][str(_cidt)].append(_st)
        commitments = []
        for row in _cmt_rows_all:
            q = _json_dict(row.quantities_json)
            # Entradas de este compromiso por categoría: nº asignadas + ESTADO (asignadas/enviadas/...).
            _tk_by_cat = _tk_by_cmt.get(str(row.id)) or {}
            _dl_cats = _json_dict(getattr(row, "downloaded_categories_json", None))
            cat_status = []
            for _cid, _qv in q.items():
                if str(_cid) == 'TOTAL':
                    continue
                _qn = _safe_int(_qv)
                if _qn <= 0:
                    continue
                _sts = _tk_by_cat.get(str(_cid), [])
                _asg = len(_sts)
                _lbl, _bdg = _invitation_commitment_state_from_statuses(_sts)
                # Cupo COMPLETO → Asignadas/Enviadas. Parcial con algo hecho (p. ej. ampliado tras
                # asignar/enviar) → etiqueta PARTIDA (verde|azul si hubo envío, amarillo|azul si solo
                # asignadas) con lo pendiente. Nada asignado → «Sin asignar».
                _split = None
                if _asg < _qn:
                    if _asg > 0:
                        _lbl, _bdg = ("Sin asignar parcialmente", "warning text-dark")
                        _sent_n = sum(1 for x in _sts if (x or '').upper() in {'SENT', 'DELIVERED', 'PICKED_UP', 'PRINTED'})
                        _split = {
                            "left_badge": ("success" if _sent_n > 0 else "warning text-dark"),
                            "left_text": ("%d env." % _sent_n) if _sent_n > 0 else ("%d asig." % _asg),
                            "right_badge": "info text-dark",
                            "right_text": "%d/%d pendientes" % (_qn - _asg, _qn),
                            "title": "Asignadas %d · Enviadas %d · Pendientes de asignar %d (de %d)." % (_asg, _sent_n, _qn - _asg, _qn),
                        }
                    else:
                        _lbl, _bdg = ("Sin asignar", "secondary")
                # Compromiso marcado como enviado de forma directa (sin entradas asignadas): la
                # categoría sin entradas se muestra como "Enviadas" en vez de "Sin asignar".
                if not _sts and (getattr(row, "status", "") or "").upper() == "ENVIADAS":
                    _lbl, _bdg = ("Enviadas", "success")
                _meta = _cat_meta.get(str(_cid), {})
                cat_status.append({
                    "id": str(_cid),
                    "name": name_map.get(str(_cid), "Categoría"),
                    "qty": _qn,
                    "assigned": _asg,
                    "done": _asg >= _qn,
                    "status_label": _lbl,
                    "status_badge": _bdg,
                    "split": _split,
                    "downloaded": str(_cid) in _dl_cats,
                    "color": _meta.get("color", "#9ca3af"),
                    "zone": _meta.get("zone", "PISTA"),
                    "configured": _safe_int(_meta.get("configured", 0)),
                })
            # Destinatario (a quién se mandan): nombre + foto/logo para "Enviar a ...".
            # Identidad ACTUAL del destinatario (en vivo desde su ficha) — nombre, foto, email y vínculo.
            _idn = _invitation_guest_identity(session_db, row)
            _rcpt_name = _idn.get("name") or row.guest_name or ""
            _rcpt_photo = _idn.get("photo") or ""
            _rcpt_email = _idn.get("email") or ""
            _rcpt_link_summary = _idn.get("link_summary") or {}
            # Artista sin foto propia → foto del artista del evento.
            if not _rcpt_photo and row.guest_artist_id:
                _ar = _concert_artist_rows(session_db, concert) if concert else []
                if _ar:
                    _rcpt_photo = getattr(_ar[0], "photo_url", "") or ""
            # Quién añadió el compromiso (foto + nombre).
            _cb_nick = (row.created_by_nick or "").strip()
            _cb_photo = ""
            if row.created_by_user_id:
                _cbp = session_db.get(UserProfile, row.created_by_user_id)
                if _cbp:
                    _cb_nick = _cb_nick or _profile_full_name(_cbp) or getattr(_cbp, 'nick', '') or ""
                    _cb_photo = getattr(_cbp, 'photo_url', '') or ""
            _c_needs_assign = any(cs["assigned"] < cs["qty"] for cs in cat_status)
            _c_needs_send = any(cs["assigned"] > 0 and cs["status_label"] not in ("Enviadas", "Recogidas en taquilla", "Disponibles en taquilla", "Entregadas en mano") for cs in cat_status)
            # «Sin descargar»: alguna categoría ya ENVIADA cuyo PDF nadie ha descargado aún.
            _c_needs_download = any(cs["status_label"] == "Enviadas" and not cs.get("downloaded") for cs in cat_status)
            commitments.append({
                "id": str(row.id),
                "name": row.name,
                "reason": row.reason or "",
                "quantities": q,
                "quantities_label": _invitation_quantities_label(q, name_map),
                "category_status": cat_status,
                "needs_assign": _c_needs_assign,
                "needs_send": _c_needs_send,
                "needs_download": _c_needs_download,
                "status": row.status,
                "status_label": INVITATION_STATUS_LABELS.get(row.status or '', row.status or ''),
                "sent_via": (getattr(row, 'sent_via', None) or ''),
                "sent_to": (getattr(row, 'sent_to', None) or ''),
                "downloaded_at_label": _invitation_display_datetime(getattr(row, 'downloaded_at', None)),
                "note": row.note or "",
                "created_by_nick": _cb_nick,
                "created_by_photo": _cb_photo,
                "recipient_name": _rcpt_name,
                "recipient_photo": _rcpt_photo,
                "recipient_email": _rcpt_email,
                "recipient_link_summary": _rcpt_link_summary,
                "recipient_link_summary_text": _promoter_link_summary_text(_rcpt_link_summary),
                "guest_type": ('THIRD_PARTY' if row.guest_promoter_id else 'ARTIST' if row.guest_artist_id else 'EMPLOYEE' if row.guest_user_id else ''),
                "guest_promoter_id": str(row.guest_promoter_id) if row.guest_promoter_id else "",
                "guest_artist_id": str(row.guest_artist_id) if row.guest_artist_id else "",
                "guest_user_id": str(row.guest_user_id) if row.guest_user_id else "",
                "guest_email": row.guest_email or "",
                "guest_phone": row.guest_phone or "",
            })
        requests = []
        denied_count = 0
        show_denied = _truthy(request.args.get('show_denied'))
        for row in _req_rows_all:
            is_denied = (row.status or '') in {'RECHAZADAS', 'ANULADAS'}
            if is_denied:
                denied_count += 1
                if not show_denied:
                    continue
            item = _invitation_request_payload(row, categories)
            item.update(_invitation_request_kind_flags(session_db, row, categories))
            item['is_denied'] = is_denied
            requests.append(item)
        # Agrupación del listado por TIPO de invitación (categoría) con franja de color + orden
        # alfabético (helper reutilizado también por la página pública del enlace).
        _invitation_group_requests(requests, categories)
        # PENDIENTES DE ASIGNAR por categoría (contador rojo de cada tarjeta): nº de peticiones
        # (solicitudes + compromisos vivos, no enviados/cerrados) con entradas aún sin asignar en
        # esa categoría, y total de entradas pendientes (pedido − ya asignado por esa petición).
        _tk_by_req: dict = defaultdict(lambda: defaultdict(int))
        for _rid, _cidt, _n in (session_db.query(InvitationTicket.assigned_request_id, InvitationTicket.category_id, func.count(InvitationTicket.id))
                                .filter(InvitationTicket.concert_id == concert.id, InvitationTicket.assigned_request_id.isnot(None))
                                .group_by(InvitationTicket.assigned_request_id, InvitationTicket.category_id).all()):
            _tk_by_req[str(_rid)][str(_cidt)] = int(_n or 0)
        _sent_set_pend = {'ENVIADAS', 'ENTREGADAS_MANO', 'DISPONIBLES_TAQUILLA', 'RECOGIDAS_TAQUILLA'}
        _cat_kind_pend = {str(c.id): (c.ticket_kind or '').upper() for c in categories}
        _pending_by_cat: dict = defaultdict(lambda: {'requests': 0, 'qty': 0})
        for _r in _req_rows_all:
            _st = (_r.status or '').upper()
            if _st in {'RECHAZADAS', 'ANULADAS'}:
                continue
            for _cid2, _qv in _json_dict(_r.quantities_json).items():
                if str(_cid2).upper() == 'TOTAL':
                    continue
                # Listas ya enviadas no cuentan como pendientes (no asignan PDFs); las AMPLIADAS
                # tras envío sí: su resto por asignar debe verse para que no se olvide.
                if _st in _sent_set_pend and _cat_kind_pend.get(str(_cid2)) == 'GUEST_LIST':
                    continue
                _pend = _safe_int(_qv) - _tk_by_req.get(str(_r.id), {}).get(str(_cid2), 0)
                if _pend > 0:
                    _pending_by_cat[str(_cid2)]['requests'] += 1
                    _pending_by_cat[str(_cid2)]['qty'] += _pend
        for _c in _cmt_rows_all:
            _st = (_c.status or '').upper()
            if _st == 'ANULADAS':
                continue
            _tkc = _tk_by_cmt.get(str(_c.id)) or {}
            for _cid2, _qv in _json_dict(_c.quantities_json).items():
                if str(_cid2).upper() == 'TOTAL':
                    continue
                if _st in _sent_set_pend and _cat_kind_pend.get(str(_cid2)) == 'GUEST_LIST':
                    continue
                _pend = _safe_int(_qv) - len(_tkc.get(str(_cid2)) or [])
                if _pend > 0:
                    _pending_by_cat[str(_cid2)]['requests'] += 1
                    _pending_by_cat[str(_cid2)]['qty'] += _pend
        for _cp in cat_payloads:
            _pd = _pending_by_cat.get(_cp['id']) or {'requests': 0, 'qty': 0}
            _cp['pending_requests'] = _pd['requests']
            _cp['pending_qty'] = _pd['qty']
        # Palcos ya comprometidos a alguien: {cat_id: "Asignado a …"} para bloquear su zona de drop.
        committed_palco_labels = _invitation_committed_palco_labels(session_db, concert, categories)
        # Palcos COMPLETOS (todas sus entradas asignadas/enviadas): también bloqueados en el listado
        # (sin arrastrar peticiones dentro), aunque no tengan compromiso.
        for _cid_full in _invitation_request_excluded_category_ids(session_db, concert, categories):
            committed_palco_labels.setdefault(_cid_full, '')
        guest_list_rows_complete = _invitation_guest_list_rows(session_db, concert, 'COMPLETE')
        guest_list_rows_door = _invitation_guest_list_rows(session_db, concert, 'DOOR')
        guest_list_rows_box_office = _invitation_guest_list_rows(session_db, concert, 'BOX_OFFICE')
        guest_list_links = []
        for glink in session_db.query(InvitationGuestListLink).filter(InvitationGuestListLink.concert_id == concert.id).order_by(InvitationGuestListLink.created_at.desc()).limit(20).all():
            guest_list_links.append({
                'id': str(glink.id),
                'token': glink.token,
                'url': _external_url_for('public_invitation_guest_list', token=glink.token),
                'list_type': glink.list_type or 'COMPLETE',
                'list_type_label': _invitation_list_type_label(glink.list_type),
                'status': glink.status or 'ACTIVE',
                'created_at_label': _invitation_display_datetime(glink.created_at),
                'created_by': glink.created_by_nick or '',
            })
        links = []
        _state_meta = {
            'active': ('Activo', 'success'),
            'locked': ('Bloqueado', 'warning'),
            'expired': ('Vencido', 'secondary'),
            'cancelled': ('Anulado', 'danger'),
        }
        # Colores/nombres de categoría IGUALES que en Invitados (mismo índice de paleta por orden).
        _lk_color = {str(c.id): INVITATION_ASSIGNEE_COLORS[i % len(INVITATION_ASSIGNEE_COLORS)] for i, c in enumerate(categories)}
        _lk_name = {str(c.id): c.name for c in categories}
        _lk_order = {str(c.id): i for i, c in enumerate(categories)}
        for link in session_db.query(InvitationPublicLink).filter(InvitationPublicLink.concert_id == concert.id).order_by(InvitationPublicLink.created_at.desc()).all():
            # Blindaje por enlace: un enlace con datos inesperados no debe tumbar toda la ficha.
            try:
                state, msg = _invitation_link_state(link)
                limits = _invitation_public_limits(link, categories, [])
                url = _invitation_public_link_url(link)
                target_promoter = link.target_promoter
                target_link_summary = _promoter_link_summary(session_db, target_promoter) if target_promoter else {}
                share_msg = f"Solicita tus invitaciones aquí:\n{url}"
                state_label, state_badge = _state_meta.get(state, ('—', 'secondary'))
                # Resumen de peticiones de ESTE enlace: nº de peticiones + invitaciones por categoría
                # (solo categorías con peticiones), con los colores de Invitados.
                _lk_rows = (
                    session_db.query(InvitationRequest)
                    .filter(InvitationRequest.public_link_id == link.id)
                    .filter(InvitationRequest.status.notin_(['ANULADAS', 'RECHAZADAS']))
                    .all()
                )
                _per_cat, _uncat = {}, 0
                for _r in _lk_rows:
                    _q = _json_dict(_r.quantities_json)
                    _real = [k for k in _q if str(k).upper() != 'TOTAL' and str(k) in _lk_name]
                    for k in _real:
                        _per_cat[str(k)] = _per_cat.get(str(k), 0) + _safe_int(_q.get(k))
                    if not _real:
                        _uncat += _invitation_total_qty(_q)
                _req_cats = [
                    {"name": _lk_name.get(cid, ''), "color": _lk_color.get(cid, '#9ca3af'), "qty": qty}
                    for cid, qty in sorted(_per_cat.items(), key=lambda kv: _lk_order.get(kv[0], 9999)) if qty > 0
                ]
                if _uncat > 0:
                    _req_cats.append({"name": "Sin categoría", "color": "#9ca3af", "qty": _uncat})
                links.append({
                    "id": str(link.id),
                    "token": link.token,
                    "url": url,
                    "target_name": link.target_name or (target_promoter.nick if target_promoter else '') or '—',
                    "target_email": link.target_email or '',
                    "target_photo_url": (getattr(target_promoter, 'logo_url', None) or '') if target_promoter else '',
                    "target_promoter_id": str(link.target_promoter_id) if link.target_promoter_id else '',
                    "target_link_summary": target_link_summary,
                    "target_link_summary_text": _promoter_link_summary_text(target_link_summary) if target_link_summary else '',
                    "requested_by": link.requested_by_nick or link.requested_by_email or '—',
                    "requested_by_photo_url": link.requested_by_photo_url or url_for('static', filename='img/placeholder_photo.png'),
                    "deadline_label": _invitation_display_datetime(link.deadline_at),
                    "locked": bool(getattr(link, 'locked', False)),
                    # Config (para prefijar el modal de editar; `link` en plantilla es este dict).
                    "categorize_requests": bool(getattr(link, 'categorize_requests', True)),
                    "show_only_available": bool(getattr(link, 'show_only_available', False)),
                    "limit_to_available": bool(getattr(link, 'limit_to_available', False)),
                    "categories_enabled_json": _json_list(link.categories_enabled_json),
                    "category_limits_json": _json_dict(link.category_limits_json),
                    "state": state,
                    "state_label": state_label,
                    "state_badge": state_badge,
                    "req_count": len(_lk_rows),
                    "req_cats": _req_cats,
                    "whatsapp_url": 'https://wa.me/?text=' + quote_plus(share_msg),
                    "sms_url": 'sms:?&body=' + quote_plus(share_msg),
                    "message": msg,
                    "limits": limits,
                })
            except Exception as _linkexc:
                try:
                    app.logger.exception('invitation link card build failed')
                except Exception:
                    pass
                flash('No se pudo cargar un enlace generado (' + type(_linkexc).__name__ + ': ' + str(_linkexc)[:180] + ').', 'warning')
        _assign_ctx = _invitation_assign_context(session_db, concert, categories)
        tickets = _assign_ctx['tickets']
        tickets_by_category = _assign_ctx['tickets_by_category']
        uncategorized_tickets = _assign_ctx['uncategorized_tickets']
        ticket_groups_by_category = _assign_ctx['ticket_groups_by_category']
        availability_by_category = _assign_ctx['availability_by_category']
        pending_assignments = _assign_ctx['pending_assignments']
        # Mapa del recinto (visor): si el recinto del concierto tiene mapa de butacas, se casan las
        # entradas subidas (sector/fila/asiento) con él y se pinta a cada invitado con su color.
        venue_map_inv = None
        if concert.venue_id:
            try:
                _sm_inv = _concert_seatmap(session_db, concert)
                if _sm_inv is not None:
                    venue_map_inv = _invitation_venue_map_payload(_sm_inv, tickets)
                    if venue_map_inv:
                        venue_map_inv["venue_id"] = str(concert.venue_id)   # enlace de corrección (alias)
            except Exception:
                venue_map_inv = None
        current_state = _current_user_state()
        return render_template(
            'invitaciones.html',
            tab='evento',
            venue_map_inv=venue_map_inv,
            back_to_ficha=back_to_ficha,
            group_promoted=_concert_is_group_promoted(session_db, concert),
            event=_invitation_event_payload(session_db, concert, include_counts=True),
            # Cabecera con los MISMOS contadores que la ficha de la actividad.
            header_counts=_invitation_ficha_header_counts(session_db, concert),
            concert=concert,
            categories=cat_payloads,
            commitments=commitments,
            requests=requests,
            grouped_requests=_invitation_grouped(requests, categories, locked_labels=committed_palco_labels),
            assigned_pending_by_category=assigned_pending_by_category,
            denied_count=denied_count,
            show_denied=show_denied,
            guest_list_rows_complete=guest_list_rows_complete,
            guest_list_rows_door=guest_list_rows_door,
            guest_list_rows_box_office=guest_list_rows_box_office,
            guest_list_links=guest_list_links,
            links=links,
            tickets=tickets,
            tickets_by_category=tickets_by_category,
            uncategorized_tickets=uncategorized_tickets,
            ticket_groups_by_category=ticket_groups_by_category,
            availability_by_category=availability_by_category,
            pending_assignments=pending_assignments,
            current_user_invitation={
                'name': current_state.get('nick') or current_state.get('email') or '',
                'email': current_state.get('email') or '',
                'phone': current_state.get('phone') or '',
                'photo_url': current_state.get('photo_url') or url_for('static', filename='img/placeholder_photo.png'),
            },
            artists=_invitation_artist_options(session_db),
            event_artists=_invitation_event_artist_options(session_db),
            personnel=_invitation_personnel_options(session_db),
            category_types=INVITATION_CATEGORY_TYPES,
            guest_list_modes=INVITATION_GUEST_LIST_MODES,
            status_labels=INVITATION_STATUS_LABELS,
            entity_link_types=APP33_ENTITY_LINK_TYPES,
        )
    finally:
        session_db.close()


def _invitation_limits_summary(link: InvitationPublicLink, categories: list[InvitationCategory]) -> str:
    if (link.limit_mode or 'NONE') == 'TOTAL':
        return f"Límite total: {_safe_int(link.total_limit)}"
    if (link.limit_mode or '') == 'CATEGORIES':
        limits = _json_dict(link.category_limits_json)
        name_map = _invitation_category_name_map(categories)
        pieces = [f"{name_map.get(cid, 'Categoría')}: {_safe_int(qty)}" for cid, qty in limits.items() if _safe_int(qty) > 0]
        return ' · '.join(pieces) or 'Sin límite por categoría'
    if link.categorize_requests:
        enabled = set(str(x) for x in _json_list(link.categories_enabled_json))
        if enabled:
            name_map = _invitation_category_name_map(categories)
            return 'Categorías: ' + ' · '.join([name_map.get(cid, 'Categoría') for cid in enabled])
        return 'Sin límite, con categorías'
    return 'Sin límite y sin categorías'


@app.post('/invitaciones/evento/<concert_id>/categorias', endpoint='invitation_category_save')
@admin_required
def invitation_category_save(concert_id):
    session_db = db()
    next_url = (request.form.get('next') or '').strip()
    if not next_url.startswith('/'):
        next_url = ''
    fallback_url = url_for('invitation_event_detail', concert_id=concert_id) + '#inv-tab-tickets'
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        if not concert:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)

        # Modo tabla: permite configurar de una vez todas las categorías con contrato/adicionales.
        row_names = request.form.getlist('category_name[]')
        if row_names:
            row_ids = request.form.getlist('category_id[]')
            contract_qtys = request.form.getlist('qty_contract[]')
            extra_qtys = request.form.getlist('qty_extra[]')
            kinds = request.form.getlist('ticket_kind[]')
            guest_modes = request.form.getlist('guest_list_mode[]')
            blocked_ids = set(request.form.getlist('block_requests_cat'))  # categorías con peticiones bloqueadas
            over_quota_ids = set(request.form.getlist('block_over_quota_cat'))  # no aceptar por encima de cupo
            pmr_ids = set(request.form.getlist('pmr_cat'))  # categorías PMR (con entrada de acompañante)
            zone_vals = request.form.getlist('zone[]')  # zona (PISTA/GRADA/PALCO) por categoría
            stairs_specs = request.form.getlist('stairs_spec[]')  # escaleras (opcional) por categoría
            for idx, name_raw in enumerate(row_names):
                name = (name_raw or '').strip()
                if not name:
                    continue
                category_id = _safe_uuid(row_ids[idx] if idx < len(row_ids) else None)
                row = session_db.get(InvitationCategory, category_id) if category_id else None
                if row and row.concert_id != concert.id:
                    continue
                if not row:
                    row = InvitationCategory(concert_id=concert.id, created_by_user_id=_safe_uuid(session.get('user_id')), created_by_nick=_current_user_email(), sort_order=idx)
                    session_db.add(row)
                raw_kind = kinds[idx] if idx < len(kinds) else ''
                raw_guest = guest_modes[idx] if idx < len(guest_modes) else ''
                ticket_kind, guest_mode = _invitation_parse_ticket_kind_and_guest_mode(raw_kind, getattr(row, 'ticket_kind', None), raw_guest or getattr(row, 'guest_list_mode', None))
                row.name = name
                row.qty_contract = _safe_int(contract_qtys[idx] if idx < len(contract_qtys) else 0)
                row.qty_extra = _safe_int(extra_qtys[idx] if idx < len(extra_qtys) else 0)
                row.ticket_kind = ticket_kind
                row.guest_list_mode = guest_mode
                row.is_active = True
                row.requests_blocked = bool(category_id and str(category_id) in blocked_ids)
                row.requests_over_quota_blocked = bool(category_id and str(category_id) in over_quota_ids)
                row.is_pmr = bool(category_id and str(category_id) in pmr_ids)
                _zone_raw = (zone_vals[idx] if idx < len(zone_vals) else '').strip().upper()
                row.zone = _zone_raw if _zone_raw in ('PISTA', 'GRADA', 'PALCO') else None
                _stairs_raw = (stairs_specs[idx] if idx < len(stairs_specs) else '').strip()
                row.stairs_spec = _stairs_raw or None
                row.sort_order = idx
                row.updated_at = _now_madrid()
            session_db.commit()
            flash('Invitaciones disponibles actualizadas.', 'success')
            return redirect(next_url or fallback_url)

        category_id = _safe_uuid(request.form.get('category_id'))
        row = session_db.get(InvitationCategory, category_id) if category_id else None
        if row and row.concert_id != concert.id:
            abort(403)
        if not row:
            row = InvitationCategory(concert_id=concert.id, created_by_user_id=_safe_uuid(session.get('user_id')), created_by_nick=_current_user_email())
            session_db.add(row)
        ticket_kind, guest_mode = _invitation_parse_ticket_kind_and_guest_mode(request.form.get('ticket_kind'), getattr(row, 'ticket_kind', None), request.form.get('guest_list_mode') or getattr(row, 'guest_list_mode', None))
        row.name = (request.form.get('name') or 'General').strip() or 'General'
        row.ticket_kind = ticket_kind
        row.guest_list_mode = guest_mode
        row.qty_contract = _safe_int(request.form.get('qty_contract'))
        row.qty_extra = _safe_int(request.form.get('qty_extra'))
        row.is_active = not _truthy(request.form.get('inactive'))
        row.updated_at = _now_madrid()
        session_db.commit()
        flash('Categoría de invitaciones guardada.', 'success')
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo guardar la categoría: {exc}', 'danger')
    finally:
        session_db.close()
    return redirect(next_url or fallback_url)


@app.get('/api/invitaciones/duplicados', endpoint='api_invitation_request_duplicates')
def api_invitation_request_duplicates():
    """Comprueba si el invitado (o alguien con nombre similar) ya tiene solicitudes en el evento.
    Sirve para el aviso previo al crear una solicitud (app y enlace público)."""
    guest_name = (request.args.get('guest_name') or '').strip()
    guest_promoter_id = _safe_uuid(request.args.get('guest_promoter_id'))
    token = (request.args.get('token') or '').strip()
    session_db = db()
    try:
        concert = None
        if token:
            link = session_db.query(InvitationPublicLink).filter(InvitationPublicLink.token == token).first()
            if link:
                concert = link.concert or session_db.get(Concert, link.concert_id)
        else:
            if not session.get('user_id'):
                return jsonify({'ok': False, 'matches': []}), 403
            concert = session_db.get(Concert, _safe_uuid(request.args.get('concert_id')))
        if not concert or (not guest_name and not guest_promoter_id):
            return jsonify({'ok': True, 'matches': []})
        rows = (
            session_db.query(InvitationRequest)
            .filter(InvitationRequest.concert_id == concert.id)
            .filter(~InvitationRequest.status.in_(['RECHAZADAS', 'ANULADAS']))
            .order_by(InvitationRequest.created_at.desc())
            .all()
        )
        matches = []
        for r in rows:
            same_promoter = bool(guest_promoter_id and getattr(r, 'guest_promoter_id', None) and r.guest_promoter_id == guest_promoter_id)
            sim = _similarity_score(guest_name, r.guest_name or '') if guest_name else 0.0
            if not (same_promoter or sim >= 0.72):
                continue
            p = _invitation_request_payload(r, None)
            matches.append({
                'guest_name': p.get('guest_name') or r.guest_name or '',
                'qty_total': p.get('qty_total') or 0,
                'requester_nick': p.get('requester_nick') or '',
                'requester_photo': p.get('requester_photo_url') or '',
                'created_at_label': p.get('created_at_label') or '',
            })
        return jsonify({'ok': True, 'matches': matches})
    finally:
        session_db.close()


def _invitation_safe_next(value: str | None) -> str | None:
    """Valida un `next` para redirigir tras crear una solicitud: solo rutas locales de la ficha de
    evento de invitaciones (evita open-redirect). Devuelve la ruta o None."""
    v = (value or "").strip()
    if not v:
        return None
    # Solo rutas locales (sin esquema/host) y limitadas a la ficha de gestión de invitaciones.
    if v.startswith("//") or "://" in v:
        return None
    if v.startswith("/invitaciones/evento/"):
        return v
    return None


def _invitation_parse_guest_receiver(session_db, form, state, requester_info):
    """Interpreta «para quién son» (guest_*) y «a quién se le mandan» (receiver_*) de una petición.
    ÚNICA fuente de verdad, compartida por CREAR peticiones y por ENVIAR una selección de entradas del
    plano (así cambiar el flujo de peticiones cambia también el envío por selección).
    Devuelve (fields, requester_info, no_guest_contact); las claves de `fields` coinciden con los
    kwargs de InvitationRequest para poder construirlo con **fields."""
    guest_type = (form.get('guest_type') or 'THIRD_PARTY').strip().upper()
    guest_name = (form.get('guest_name') or '').strip()
    guest_email = (form.get('guest_email') or '').strip()
    guest_phone = (form.get('guest_phone') or '').strip()
    guest_company = (form.get('guest_company') or '').strip()
    guest_title = (form.get('guest_title') or guest_company or '').strip()
    guest_link_summary = {}
    guest_promoter_id = _safe_uuid(form.get('guest_promoter_id'))
    guest_artist_id = _safe_uuid(form.get('guest_artist_id'))
    guest_user_id = _safe_uuid(form.get('guest_user_id'))
    if guest_type == 'SELF':
        guest_name = state.get('nick') or state.get('email') or 'Solicitante'
        guest_email = state.get('email') or guest_email
    elif guest_type == 'EMPLOYEE' and guest_user_id:
        user = session_db.get(User, guest_user_id)
        profile = session_db.get(UserProfile, guest_user_id)
        if user:
            guest_name = _profile_full_name(profile) or getattr(profile, 'nick', None) or user.email
            guest_email = user.email
            _emp_phones = list(getattr(profile, 'mobile_phones', None) or [])
            requester_info = {
                'user_id': str(user.id),
                'nick': getattr(profile, 'nick', None) or _profile_full_name(profile) or _email_to_nick(user.email or ''),
                'email': user.email,
                'photo_url': getattr(profile, 'photo_url', None),
                'phone': (_emp_phones[0] if _emp_phones else ''),
            }
    elif guest_type == 'ARTIST' and guest_artist_id:
        artist = session_db.get(Artist, guest_artist_id)
        if artist:
            guest_name = artist.name
            guest_email = artist.email or guest_email
    elif guest_promoter_id:
        promoter = session_db.get(Promoter, guest_promoter_id)
        if promoter:
            guest_name = _promoter_display_name(promoter) or promoter.nick
            guest_email = promoter.contact_email or guest_email
            guest_phone = promoter.contact_phone or guest_phone
            guest_link_summary = _promoter_link_summary(session_db, promoter)
    if not guest_name:
        guest_name = 'Invitado'
    if not guest_email:
        guest_email = (form.get('guest_fallback_email') or '').strip()
    receiver_mode = (form.get('receiver_mode') or 'GUEST').strip().upper()
    receiver_payload = {
        'name': (form.get('receiver_name') or '').strip(),
        'email': (form.get('receiver_email') or '').strip(),
        'phone': (form.get('receiver_phone') or '').strip(),
    }
    no_guest_contact = False
    if receiver_mode == 'GUEST':
        receiver_payload['name'] = receiver_payload.get('name') or guest_name
        receiver_payload['email'] = receiver_payload.get('email') or guest_email
        receiver_payload['phone'] = receiver_payload.get('phone') or guest_phone
        if not receiver_payload.get('email') and not receiver_payload.get('phone'):
            no_guest_contact = True
            receiver_mode = 'ME'
            receiver_payload = {
                'name': requester_info.get('nick') or requester_info.get('email') or 'Solicitante',
                'email': requester_info.get('email') or '',
                'phone': requester_info.get('phone') or '',
                'fallback_from_guest': True,
            }
    elif receiver_mode == 'EMPLOYEE':
        ruid = _safe_uuid(form.get('receiver_user_id'))
        ruser = session_db.get(User, ruid) if ruid else None
        rprof = session_db.get(UserProfile, ruid) if ruid else None
        if not ruser:
            raise ValueError('Selecciona a la persona de la empresa que recibirá las invitaciones.')
        receiver_payload = {
            'user_id': str(ruid),
            'name': (_profile_full_name(rprof) if rprof else None) or getattr(rprof, 'nick', None) or ruser.email,
            'email': ruser.email or '',
            'photo_url': (getattr(rprof, 'photo_url', None) if rprof else None) or '',
        }
    elif receiver_mode == 'ME':
        receiver_payload = {
            'name': requester_info.get('nick') or requester_info.get('email') or 'Solicitante',
            'email': requester_info.get('email') or '',
            'phone': requester_info.get('phone') or '',
        }
    elif receiver_mode == 'OTHER':
        receiver_promoter_id = _safe_uuid(form.get('receiver_promoter_id'))
        if receiver_promoter_id:
            receiver_promoter = session_db.get(Promoter, receiver_promoter_id)
            if receiver_promoter:
                receiver_payload['promoter_id'] = str(receiver_promoter.id)
                receiver_payload['name'] = receiver_payload.get('name') or _promoter_display_name(receiver_promoter) or receiver_promoter.nick
                receiver_payload['email'] = receiver_payload.get('email') or receiver_promoter.contact_email or ''
                receiver_payload['phone'] = receiver_payload.get('phone') or receiver_promoter.contact_phone or ''
        if not receiver_payload.get('name'):
            receiver_payload['name'] = 'Otro receptor'
        if not receiver_payload.get('email') and not receiver_payload.get('phone'):
            raise ValueError('Para enviar a otro receptor selecciona un tercero con email/teléfono o indica al menos email o teléfono.')
    elif receiver_mode == 'BOX_OFFICE':
        receiver_payload = {}
    fields = {
        'guest_type': guest_type, 'guest_promoter_id': guest_promoter_id, 'guest_artist_id': guest_artist_id,
        'guest_user_id': guest_user_id, 'guest_name': guest_name, 'guest_company': guest_company,
        'guest_title': guest_title, 'guest_link_summary': guest_link_summary, 'guest_email': guest_email,
        'guest_phone': guest_phone, 'receiver_mode': receiver_mode, 'receiver_payload': receiver_payload,
    }
    return fields, requester_info, no_guest_contact


@app.post('/invitaciones/solicitudes', endpoint='invitation_request_create')
@admin_required
def invitation_request_create():
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(request.form.get('concert_id')))
        if not concert:
            abort(404)
        if not _invitation_event_is_active_for_requests(concert):
            raise ValueError('Este concierto o evento ya no admite solicitudes de invitaciones.')
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=True)
        quantities = _invitation_quantities_from_form(request.form, categories)
        if _invitation_total_qty(quantities) <= 0:
            raise ValueError('Indica al menos una invitación.')
        # Blindaje server-side: palcos comprometidos o COMPLETOS (asignados/enviados) no admiten
        # peticiones (el asistente ya no los ofrece; esto protege ante pestañas desactualizadas).
        _excluded = _invitation_request_excluded_category_ids(session_db, concert, categories)
        _excluded_names = [c.name for c in categories if str(c.id) in _excluded and _safe_int(quantities.get(str(c.id))) > 0]
        if _excluded_names:
            raise ValueError('No se admiten peticiones en: ' + ', '.join(_excluded_names) + ' (palco ya completo o comprometido).')
        # Refuerzo server-side del bloqueo de categorías: no se admiten peticiones para las que el
        # gestor haya marcado como "No admite peticiones" (la UI ya las deshabilita).
        _blocked_names = [
            c.name for c in categories
            if getattr(c, 'requests_blocked', False) and _safe_int(quantities.get(str(c.id))) > 0
        ]
        if _blocked_names:
            raise ValueError('No se admiten peticiones para: ' + ', '.join(_blocked_names) + '.')
        # «No aceptar peticiones por encima del cupo» (configuración por categoría): única otra
        # razón para frenar una petición — sin el flag, se puede pedir aunque no haya cupo/subidas.
        _oq_cats = [c for c in categories if getattr(c, 'requests_over_quota_blocked', False)]
        if _oq_cats:
            _avail_by_cat = _invitation_event_available_by_category(session_db, concert, categories)
            _over = [f"{c.name} (quedan {max(_safe_int(_avail_by_cat.get(str(c.id), 0)), 0)})"
                     for c in _oq_cats
                     if _safe_int(quantities.get(str(c.id))) > max(_safe_int(_avail_by_cat.get(str(c.id), 0)), 0)]
            if _over:
                raise ValueError('No se aceptan peticiones por encima del cupo en: ' + ', '.join(_over) + '.')
        # Las solicitudes (peticiones) NO se limitan por el cupo del evento: el concierto puede no
        # tener invitaciones configuradas todavía, o tenerlas completas y ampliarse después. El
        # control de cupo se ejerce al ACEPTAR/asignar la solicitud (por eso existe el flujo de
        # aprobación), no al pedirla.
        state = _current_user_state()
        # Por defecto la petición se atribuye a quien la registra. Si se pide para otra persona de la
        # oficina (guest_type EMPLOYEE), más abajo se reasigna a esa persona para que figure como suya.
        requester_info = {
            'user_id': session.get('user_id'),
            'nick': state.get('nick') or _email_to_nick(state.get('email') or ''),
            'email': state.get('email'),
            'photo_url': state.get('photo_url'),
            'phone': state.get('phone') or '',
        }
        _rfields, requester_info, no_guest_contact = _invitation_parse_guest_receiver(session_db, request.form, state, requester_info)
        row = InvitationRequest(
            concert_id=concert.id,
            request_source='INTERNAL',
            requester_type='USER',
            requester_user_id=_safe_uuid(requester_info.get('user_id')),
            requester_nick=requester_info.get('nick'),
            requester_email=requester_info.get('email'),
            requester_photo_url=requester_info.get('photo_url'),
            created_by_user_id=_safe_uuid(session.get('user_id')),
            created_by_nick=state.get('nick') or _email_to_nick(state.get('email') or ''),
            guest_note=(request.form.get('guest_note') or '').strip(),
            quantities_json=quantities,
            status='SOLICITADAS',
            note=(request.form.get('note') or '').strip(),
            delivery_token=_invitation_token(),
            **_rfields,
        )
        session_db.add(row)
        session_db.commit()
        if no_guest_contact:
            flash('El invitado no tenía correo configurado: la solicitud se completó y las invitaciones te llegarán a ti (quien las pide). Puedes añadir un correo a su ficha para enviárselas directamente.', 'warning')
        else:
            flash('Solicitud de invitaciones guardada como solicitada.', 'success')
        # Si la solicitud se pidió DESDE la gestión de un evento (campo `next` con la ruta de la ficha),
        # se vuelve a esa misma ficha para no moverse de sitio (el gestor sí tiene permiso). Si no,
        # volvemos a la vista de invitaciones (pestaña "pedir", con "Mis solicitudes"), que el
        # solicitante siempre puede ver: la ficha del evento exige gestión y daría 403 a quien solo pide.
        return redirect(_invitation_safe_next(request.form.get('next')) or url_for('invitations_view', tab='pedir'))
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo crear la solicitud: {exc}', 'danger')
        return redirect(_invitation_safe_next(request.form.get('next')) or url_for('invitations_view', tab='pedir'))
    finally:
        session_db.close()


@app.post('/invitaciones/enlaces', endpoint='invitation_public_link_create')
@admin_required
def invitation_public_link_create():
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(request.form.get('concert_id')))
        if not concert:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)
        _ensure_invitation_link_columns(session_db)
        if not _invitation_event_is_active_for_requests(concert):
            raise ValueError('Este concierto o evento ya no admite enlaces de peticiones de invitaciones.')
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=True)
        state = _current_user_state()
        target_promoter_id = _safe_uuid(request.form.get('target_promoter_id'))
        target = session_db.get(Promoter, target_promoter_id) if target_promoter_id else None
        limit_mode = (request.form.get('limit_mode') or 'NONE').strip().upper()
        category_limits = {}
        categories_enabled = []
        for cat in categories:
            cid = str(cat.id)
            max_qty = _safe_int(request.form.get(f'link_limit_{cid}'))
            enabled = _truthy(request.form.get(f'link_enabled_{cid}')) or max_qty > 0
            if max_qty > 0:
                category_limits[cid] = max_qty
            if enabled:
                categories_enabled.append(cid)
        if limit_mode == 'CATEGORIES' and not category_limits:
            limit_mode = 'NONE'
        if limit_mode == 'TOTAL' and _safe_int(request.form.get('total_limit')) <= 0:
            limit_mode = 'NONE'
        link = InvitationPublicLink(
            concert_id=concert.id,
            token=_invitation_token(),
            target_promoter_id=target_promoter_id,
            target_name=(request.form.get('target_name') or (target.nick if target else '') or '').strip(),
            target_email=(request.form.get('target_email') or (target.contact_email if target else '') or '').strip(),
            target_phone=(request.form.get('target_phone') or (target.contact_phone if target else '') or '').strip(),
            requested_by_user_id=_safe_uuid(session.get('user_id')),
            requested_by_nick=state.get('nick') or _email_to_nick(state.get('email') or ''),
            requested_by_email=state.get('email'),
            requested_by_photo_url=state.get('photo_url'),
            limit_mode=limit_mode,
            total_limit=_safe_int(request.form.get('total_limit')) if limit_mode == 'TOTAL' else None,
            category_limits_json=category_limits,
            categories_enabled_json=categories_enabled,
            categorize_requests=_truthy(request.form.get('categorize_requests')) if request.form.get('categorize_requests') is not None else True,
            show_only_available=_truthy(request.form.get('show_only_available')),
            limit_to_available=_truthy(request.form.get('limit_to_available')),
            deadline_at=_invitation_parse_deadline(request.form.get('deadline_at')),
            status='ACTIVE',
        )
        session_db.add(link)
        session_db.commit()
        share_url = _invitation_public_link_url(link)
        flash('Enlace de peticiones generado. Copia el enlace desde la pestaña de enlaces generados.', 'success')
        return redirect(url_for('invitation_event_detail', concert_id=concert.id, generated_link=share_url))
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo generar el enlace: {exc}', 'danger')
        return redirect(url_for('invitations_view', tab='pedir'))
    finally:
        session_db.close()


