@app.post('/invitaciones/enlaces/<link_id>/compartir-email', endpoint='invitation_public_link_share_email')
@admin_required
def invitation_public_link_share_email(link_id):
    session_db = db()
    try:
        link = session_db.get(InvitationPublicLink, to_uuid(link_id))
        if not link:
            abort(404)
        _ensure_can_manage_invitations(session_db, link.concert)
        concert = link.concert or session_db.get(Concert, link.concert_id)
        recipients = _dedupe_valid_email_addresses(
            (request.form.getlist('recipients') or [])
            + re.split(r'[;,\s]+', request.form.get('extra_emails') or '')
            + ([link.target_email] if link.target_email else [])
        )
        if not recipients:
            flash('Añade al menos un destinatario (o guarda un email en el destinatario del enlace).', 'warning')
            return redirect(url_for('invitation_event_detail', concert_id=link.concert_id))
        url = _invitation_public_link_url(link)
        event = _invitation_event_payload(session_db, concert)
        title = event.get('artist_names') or event.get('title') or 'el evento'
        subject = f"Solicitud de invitaciones · {title}"
        note = (request.form.get('note') or '').strip()
        greeting = Markup.escape(link.target_name or 'Hola')
        safe_title = Markup.escape(title)
        safe_url = Markup.escape(url)
        html = (
            f"<p>Hola {greeting},</p>"
            f"<p>Puedes solicitar tus invitaciones para <strong>{safe_title}</strong> desde este enlace:</p>"
            f'<p><a href="{safe_url}">{safe_url}</a></p>'
        )
        if note:
            html += f"<p>{Markup.escape(note)}</p>"
        ok, err = _send_optional_email(recipients, subject, html)
        flash('Enlace enviado por email.' if ok else f'No se pudo enviar: {err}', 'success' if ok else 'warning')
        return redirect(url_for('invitation_event_detail', concert_id=link.concert_id))
    finally:
        session_db.close()


@app.post('/invitaciones/evento/<concert_id>/compromisos', endpoint='invitation_commitment_save')
@admin_required
def invitation_commitment_save(concert_id):
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        if not concert:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=True)
        commitment_id = _safe_uuid(request.form.get('commitment_id'))
        row = session_db.get(InvitationCommitment, commitment_id) if commitment_id else None
        if row and row.concert_id != concert.id:
            abort(403)
        # Validación de cupo: si se edita un compromiso ya contado, sus cantidades vuelven al pool.
        old_qty = 0
        if row and (row.status or '') != 'ANULADAS':
            old_qty = _invitation_total_qty(_json_dict(getattr(row, 'quantities_json', None)))
        new_quantities = _invitation_quantities_from_form(request.form, categories)
        new_qty = _invitation_total_qty(new_quantities)
        _inv_available = _invitation_event_counts(session_db, concert)['result'] + old_qty
        # Los compromisos PREVALECEN: se permiten aunque no haya cupo suficiente (incluso sin cupo
        # configurado); el disponible quedará en negativo (se muestra en rojo). No se bloquea: se avisa.
        if not row:
            row = InvitationCommitment(concert_id=concert.id, created_by_user_id=_safe_uuid(session.get('user_id')), created_by_nick=_current_user_email())
            session_db.add(row)
        promoter_id = _safe_uuid(request.form.get('promoter_id'))
        promoter = session_db.get(Promoter, promoter_id) if promoter_id else None
        row.promoter_id = promoter_id
        row.name = (request.form.get('name') or (promoter.nick if promoter else '') or 'Compromiso').strip()
        row.reason = (request.form.get('reason') or '').strip()
        # Destinatario (a quién se mandan): tercero / artista / empleado (igual que en solicitudes).
        g_type = (request.form.get('guest_type') or '').strip().upper()
        g_promoter_id = _safe_uuid(request.form.get('guest_promoter_id'))
        g_artist_id = _safe_uuid(request.form.get('guest_artist_id'))
        g_user_id = _safe_uuid(request.form.get('guest_user_id'))
        g_name = (request.form.get('guest_name') or '').strip()
        g_email = (request.form.get('guest_email') or '').strip()
        g_phone = (request.form.get('guest_phone') or '').strip()
        if g_type == 'EMPLOYEE' and g_user_id:
            _gu = session_db.get(User, g_user_id)
            _gp = session_db.get(UserProfile, g_user_id)
            if _gu:
                g_name = _profile_full_name(_gp) or getattr(_gp, 'nick', None) or _gu.email
                g_email = _gu.email or g_email
            g_promoter_id = None; g_artist_id = None
        elif g_type == 'ARTIST' and g_artist_id:
            _ga = session_db.get(Artist, g_artist_id)
            if _ga:
                g_name = _ga.name
                g_email = _ga.email or g_email
            g_promoter_id = None; g_user_id = None
        elif g_promoter_id:
            _gpr = session_db.get(Promoter, g_promoter_id)
            if _gpr:
                g_name = _promoter_display_name(_gpr) or _gpr.nick
                g_email = _gpr.contact_email or g_email
                g_phone = _gpr.contact_phone or g_phone
            g_artist_id = None; g_user_id = None
        else:
            g_promoter_id = None; g_artist_id = None; g_user_id = None
        row.guest_promoter_id = g_promoter_id
        row.guest_artist_id = g_artist_id
        row.guest_user_id = g_user_id
        row.guest_name = g_name or None
        row.guest_email = g_email or None
        row.guest_phone = g_phone or None
        row.quantities_json = new_quantities
        row.note = (request.form.get('note') or '').strip()
        # Recalcular desde entradas + cupo: si al ampliar quedan por asignar, vuelve a COMPROMETIDAS
        # (aparece en el asignador); las asignadas/enviadas se conservan.
        session_db.flush()
        _invitation_sync_commitment_status(session_db, row)
        row.updated_at = _now_madrid()
        session_db.commit()
        if new_qty > _inv_available:
            flash(f'Compromiso guardado. Supera el cupo configurado: el disponible queda en negativo ({_inv_available - new_qty}).', 'warning')
        else:
            flash('Compromiso guardado.', 'success')
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo guardar el compromiso: {exc}', 'danger')
    finally:
        session_db.close()
    return redirect(url_for('invitation_event_detail', concert_id=concert_id))


@app.post('/invitaciones/compromisos/<commitment_id>/eliminar', endpoint='invitation_commitment_delete')
@admin_required
def invitation_commitment_delete(commitment_id):
    """Elimina un compromiso liberando sus entradas: las asignadas (no enviadas) vuelven SIEMPRE a
    disponibles automáticamente. Si tiene entradas ya enviadas/descargadas/impresas hace falta
    decidir con `mode` (`recover` = vuelven al pool con aviso de duplicidad; `lost` = se descartan);
    sin `mode` responde needs_confirm para que el front muestre la alerta Recuperar/Descartar. Sin
    esta liberación, el FK ON DELETE SET NULL dejaba las entradas en ASSIGNED sin dueño."""
    _ajax = _truthy(request.form.get('ajax'))
    cid = None
    session_db = db()
    try:
        row = session_db.get(InvitationCommitment, to_uuid(commitment_id))
        if not row:
            abort(404)
        _ensure_can_manage_invitations(session_db, row.concert)
        cid = row.concert_id
        tickets = session_db.query(InvitationTicket).filter(InvitationTicket.assigned_commitment_id == row.id).all()
        mode = (request.form.get('mode') or '').strip().lower()
        _dl = _json_dict(getattr(row, 'downloaded_categories_json', None))
        sent_f = any((t.status or '') in {'SENT', 'DELIVERED', 'PICKED_UP', 'DISPONIBLES_TAQUILLA'} for t in tickets)
        printed_f = any((t.status or '') == 'PRINTED' for t in tickets)
        downloaded_f = bool(_dl) or bool(getattr(row, 'downloaded_at', None))
        if tickets and (sent_f or printed_f or downloaded_f) and mode not in {'recover', 'lost'}:
            info = {'ok': False, 'needs_confirm': True, 'sent': sent_f, 'downloaded': bool(downloaded_f),
                    'printed': printed_f, 'ticket_count': len(tickets)}
            if _ajax:
                return jsonify(info)
            flash('Estas invitaciones ya se enviaron, descargaron o imprimieron: confirma en el menú si recuperarlas o descartarlas.', 'warning')
            return redirect(url_for('invitation_event_detail', concert_id=cid))
        recovered, discarded = _invitation_release_apply(tickets, mode=mode, entity_label=f'el compromiso «{row.name}»')
        session_db.delete(row)
        session_db.commit()
        msg = 'Compromiso eliminado.' + ((' ' + _invitation_release_summary(recovered, discarded)) if tickets else '')
        if _ajax:
            return jsonify({'ok': True, 'message': msg})
        flash(msg, 'success')
        return redirect(url_for('invitation_event_detail', concert_id=cid))
    except Exception as exc:
        session_db.rollback()
        if _ajax:
            return jsonify({'ok': False, 'error': str(exc)}), 400
        flash(f'No se pudo eliminar el compromiso: {exc}', 'danger')
        return redirect(url_for('invitation_event_detail', concert_id=cid) if cid else url_for('invitations_view', tab='gestionar'))
    finally:
        session_db.close()


@app.post('/invitaciones/compromisos/<commitment_id>/entregar', endpoint='invitation_commitment_deliver')
@admin_required
def invitation_commitment_deliver(commitment_id):
    """Entrega las entradas ya asignadas a un compromiso: por email (la dirección se pide en el
    momento) o marcándolas para recogida en taquilla. Si no tiene entradas asignadas, avisa."""
    session_db = db()
    try:
        row = session_db.get(InvitationCommitment, to_uuid(commitment_id))
        if not row:
            abort(404)
        _ensure_can_manage_invitations(session_db, row.concert)
        cid = row.concert_id
        channel = (request.form.get('channel') or '').strip().lower()
        mode = (request.form.get('mode') or 'email').strip().lower()
        wants_json = (request.form.get('as_json') == '1') or (request.headers.get('X-Requested-With') == 'XMLHttpRequest')
        _cat_id = _safe_uuid(request.form.get('category_id'))  # opcional: entregar solo una categoría
        _tq = session_db.query(InvitationTicket).filter(InvitationTicket.assigned_commitment_id == row.id)
        if _cat_id:
            _tq = _tq.filter(InvitationTicket.category_id == _cat_id)
        tickets = _tq.all()
        if not tickets:
            msg = 'Este compromiso aún no tiene entradas asignadas. Asígnaselas antes de entregarlas.'
            if wants_json:
                return jsonify({'ok': False, 'error': msg}), 400
            flash(msg, 'warning')
            return redirect(url_for('invitation_event_detail', concert_id=cid))
        # Blindaje servidor: la ENTREGA requiere el cupo COMPLETO asignado — con category_id, esa
        # categoría entera; sin él, TODAS las categorías del compromiso (la UI ya oculta la opción;
        # esto protege ante pestañas desactualizadas o dobles clics).
        _q_all = _json_dict(row.quantities_json)
        _incomplete = False
        for _qcid, _qv in _q_all.items():
            if str(_qcid) == 'TOTAL' or _safe_int(_qv) <= 0:
                continue
            if _cat_id and str(_qcid) != str(_cat_id):
                continue
            if _invitation_assigned_qty_for_source(session_db, _safe_uuid(_qcid), 'commitment', row.id) < _safe_int(_qv):
                _incomplete = True
                break
        if _incomplete:
            msg = ('Faltan invitaciones por asignar en esta categoría: la entrega requiere el cupo completo.'
                   if _cat_id else 'Alguna categoría del compromiso no está completa: entrega categoría a categoría o completa la asignación.')
            if wants_json:
                return jsonify({'ok': False, 'error': msg}), 400
            flash(msg, 'warning')
            return redirect(url_for('invitation_event_detail', concert_id=cid))
        now = _now_madrid()
        row.delivery_token = row.delivery_token or _invitation_token()
        if channel in ('whatsapp', 'sms'):
            # WhatsApp/SMS: enlace a la página de entrega (composición visual + descarga en un PDF).
            if _cat_id:
                link = _external_url_for('public_invitation_delivery', kind='c', token=row.delivery_token, category=str(_cat_id))
            else:
                link = _external_url_for('public_invitation_delivery', kind='c', token=row.delivery_token)
            share = _invitation_share_text(session_db, row.concert or session_db.get(Concert, cid), (row.guest_name or row.name), link)
            phone = _normalize_phone_intl(_invitation_guest_live_phone(session_db, row))
            if channel == 'whatsapp':
                url = ('https://wa.me/' + phone + '?text=' + quote_plus(share)) if phone else ('https://wa.me/?text=' + quote_plus(share))
            else:
                url = ('sms:' + ('+' + phone if phone else '') + '?&body=' + quote_plus(share))
            _invitation_tag_new_tickets(tickets, tickets)   # «Nueva» en las añadidas (mezcla)
            for t in tickets:
                t.status = 'SENT'
                t.sent_at = now
                t.updated_at = now
            row.sent_via = 'WhatsApp' if channel == 'whatsapp' else 'SMS'
            row.sent_to = ('+' + phone) if phone else ''
            if not _cat_id:
                row.status = 'ENVIADAS'
                row.updated_at = now
            session_db.commit()
            if wants_json:
                return jsonify({'ok': True, 'url': url, 'channel': channel})
            return redirect(url)
        if mode in ('box_office', 'taquilla'):
            for t in tickets:
                t.status = 'DISPONIBLES_TAQUILLA'
                t.updated_at = now
            row.sent_via = 'Taquilla'
            row.sent_to = 'Recogida en taquilla'
            session_db.commit()
            flash(f'{len(tickets)} entrada(s) de «{row.name}» quedan para recogida en taquilla.', 'success')
            return redirect(url_for('invitation_event_detail', concert_id=cid))
        recipients = _dedupe_valid_email_addresses(
            request.form.getlist('recipients') + request.form.getlist('extra_emails')
            + [(request.form.get('email') or '')] + _invitation_guest_live_emails(session_db, row))
        if not recipients:
            flash('Indica un email de destino o elige la recogida en taquilla.', 'warning')
            return redirect(url_for('invitation_event_detail', concert_id=cid))
        custom_text = request.form.get('custom_text') or None
        # «Nueva» en las añadidas ANTES de componer (así salen etiquetadas en el listado del correo);
        # si el SMTP falla, el rollback deshace las marcas.
        _invitation_tag_new_tickets(tickets, tickets)
        subject, html_body, text_body = _invitation_commitment_email_body(session_db, row, custom_text=custom_text, category_id=_cat_id)
        reply_to = _invitation_commitment_reply_to(session_db, row) or _current_user_email()
        ok, err = _send_optional_email(recipients, subject, html_body, text_body=text_body, reply_to=reply_to)
        if ok:
            # Solo se marca como enviado cuando el correo se ha enviado de verdad.
            for t in tickets:
                t.status = 'SENT'
                t.sent_at = now
                t.updated_at = now
            row.sent_via = 'Email'
            row.sent_to = ', '.join(recipients or [])
            session_db.commit()
            flash(f'Invitaciones de «{row.name}» enviadas por email a: ' + (', '.join(recipients) if recipients else '—') + '.', 'success')
        else:
            session_db.rollback()
            flash(f'No se pudo enviar el email (no se marca como enviada): {err or "SMTP no configurado"}', 'warning')
        return redirect(url_for('invitation_event_detail', concert_id=cid))
    except Exception as exc:
        session_db.rollback()
        if (request.form.get('as_json') == '1') or (request.headers.get('X-Requested-With') == 'XMLHttpRequest'):
            return jsonify({'ok': False, 'error': str(exc)}), 400
        flash(f'No se pudo entregar: {exc}', 'danger')
        return redirect(url_for('invitations_view', tab='gestionar'))
    finally:
        session_db.close()


@app.post('/invitaciones/compromisos/<commitment_id>/marcar-enviadas', endpoint='invitation_commitment_mark_sent')
@admin_required
def invitation_commitment_mark_sent(commitment_id):
    """Marca un compromiso como ENVIADAS SIN enviar correo (cuando se han entregado por otro medio).
    Funciona de forma DIRECTA aunque no haya entradas asignadas: marca el compromiso como enviado.
    Si tiene entradas asignadas, también las pasa a SENT. Acepta `category_id` opcional para marcar
    solo una categoría (en ese caso solo afecta a sus entradas asignadas)."""
    session_db = db()
    try:
        row = session_db.get(InvitationCommitment, to_uuid(commitment_id))
        if not row:
            abort(404)
        _ensure_can_manage_invitations(session_db, row.concert)
        cid = row.concert_id
        _cat_id = _safe_uuid(request.form.get('category_id'))
        _tq = session_db.query(InvitationTicket).filter(InvitationTicket.assigned_commitment_id == row.id)
        if _cat_id:
            _tq = _tq.filter(InvitationTicket.category_id == _cat_id)
        tickets = _tq.all()
        now = _now_madrid()
        _invitation_tag_new_tickets(tickets, tickets)   # «Nueva» en las añadidas (mezcla)
        for t in tickets:
            t.status = 'SENT'
            t.sent_at = now
            t.updated_at = now
        # Marca el compromiso completo como enviado (sirve también sin entradas asignadas). En el
        # marcado por categoría no se toca el estado global para no afectar a las demás categorías.
        row.sent_via = 'Manual'
        row.sent_to = 'Marcada como enviada'
        if not _cat_id:
            row.status = 'ENVIADAS'
            row.updated_at = now
        session_db.commit()
        if tickets:
            flash(f'{len(tickets)} entrada(s) de «{row.name}» marcadas como enviadas.', 'success')
        else:
            flash(f'Compromiso «{row.name}» marcado como enviado.', 'success')
        return redirect(url_for('invitation_event_detail', concert_id=cid))
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo marcar como enviadas: {exc}', 'danger')
        return redirect(url_for('invitations_view', tab='gestionar'))
    finally:
        session_db.close()


@app.post('/invitaciones/correo/preview', endpoint='invitation_send_preview')
@admin_required
def invitation_send_preview():
    """Devuelve el HTML del correo de invitaciones (solicitud o compromiso) para la vista previa del
    modal de envío. No envía nada ni cambia estado (solo fija el token de descarga si faltaba)."""
