@app.post('/invitaciones/evento/<concert_id>/tickets/upload', endpoint='invitation_tickets_upload')
@admin_required
def invitation_tickets_upload(concert_id):
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        if not concert:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)
        cat_id_raw = (request.form.get('category_id') or '').strip()
        category = session_db.get(InvitationCategory, to_uuid(cat_id_raw)) if cat_id_raw else None
        if cat_id_raw and (not category or category.concert_id != concert.id):
            raise ValueError('Categoría no válida.')
        if category is not None:
            ticket_kind, guest_mode = _invitation_parse_ticket_kind_and_guest_mode(
                request.form.get('ticket_kind'),
                category.ticket_kind or 'PDF_UNNUMBERED',
                request.form.get('guest_list_mode') or category.guest_list_mode or 'BOX_OFFICE',
            )
            category.ticket_kind = ticket_kind
            category.guest_list_mode = guest_mode
            if ticket_kind == 'GUEST_LIST':
                session_db.commit()
                flash('Categoría configurada como listado de invitados.', 'success')
                return redirect(url_for('invitation_event_detail', concert_id=concert_id) + '#inv-tab-tickets')
        else:
            # Subida "sin clasificar": entra sin categoría y luego se mueve a una concreta.
            ticket_kind, _gm = _invitation_parse_ticket_kind_and_guest_mode(request.form.get('ticket_kind'), 'PDF_UNNUMBERED', None)
            if ticket_kind == 'GUEST_LIST':
                ticket_kind = 'PDF_UNNUMBERED'
        is_numbered = ticket_kind == 'PDF_NUMBERED' or _truthy(request.form.get('is_numbered'))
        files = request.files.getlist('tickets[]') or request.files.getlist('files[]')
        if not files:
            raise ValueError('No se han seleccionado PDFs.')
        errors = []
        duplicates = []      # entradas que no se suben por estar ya repetidas
        discarded = []       # páginas SIN código: no son invitaciones (se avisan, no se suben)
        created = 0
        created_rows = []    # butacas creadas (numeradas) para el popup de revisión tras subir
        created_tickets = []  # objetos InvitationTicket creados EN ORDEN
        companions_linked = 0  # PMR: entradas con acompañante adjunto (2ª página del PDF)
        is_pmr_cat = category is not None and bool(getattr(category, 'is_pmr', False))
        seen_codes = set()   # códigos ya usados en este lote (para garantizar unicidad)
        seen_shas = set()    # páginas idénticas ya vistas en este lote
        seen_butacas = set() # butacas (sector+fila+asiento) ya vistas en este lote (numeradas)
        folder = f'invitaciones/{concert.id}/{category.id if category else "sin-categoria"}'

        # Precarga EN BLOQUE de lo ya subido a este concierto: dedupe por código, SHA y butaca en
        # memoria. Antes era una consulta a la BD remota por página (lentísimo con muchos PDFs).
        _existing = session_db.query(
            InvitationTicket.ticket_code, InvitationTicket.pdf_sha256,
            InvitationTicket.sector, InvitationTicket.row_label, InvitationTicket.seat_number,
        ).filter(InvitationTicket.concert_id == concert.id).all()
        existing_codes = {r[0] for r in _existing if r[0]}
        existing_shas = {r[1] for r in _existing if r[1]}
        existing_butacas = {
            (str(r[2] or '').strip().lower(), str(r[3] or '').strip().lower(), str(r[4] or '').strip().lower())
            for r in _existing if r[4]
        }
        pending = []   # páginas aceptadas: se suben en paralelo y se crean en orden

        def _code_taken(value):
            return value in seen_codes or value in existing_codes
        for idx, file in enumerate(files):
            if not file or not getattr(file, 'filename', ''):
                continue
            fname = (file.filename or f'invitacion_{idx+1}.pdf').strip()
            if not fname.lower().endswith('.pdf'):
                errors.append(f'{fname}: solo se admiten PDFs')
                continue
            raw = file.read()
            try:
                file.stream.seek(0)
            except Exception:
                pass
            stem = Path(fname).stem or f'invitacion_{idx+1}'
            # Un PDF puede traer varias entradas: lo dividimos en una entrada por página.
            page_blobs = _invitation_split_pdf_pages(raw)
            # PMR (movilidad reducida): la invitación PUEDE llevar acompañante. Un PDF de 2 páginas =
            # UNA invitación (pág. 1) + la de su ACOMPAÑANTE (pág. 2), que van SIEMPRE unidas y cuentan
            # como UNA sola petición (no se dividen en dos). Una sola página = PMR sin acompañante. Se
            # emparejan de dos en dos por si el PDF trae varias juntas (1ª+2ª, 3ª+4ª…; impar suelta = sin
            # acompañante). Fuera de PMR, una entrada por página como siempre.
            if is_pmr_cat:
                page_pairs = [(page_blobs[i], page_blobs[i + 1] if i + 1 < len(page_blobs) else None)
                              for i in range(0, len(page_blobs), 2)]
            else:
                page_pairs = [(pb, None) for pb in page_blobs]
            multi = len(page_pairs) > 1
            form_code_single = (request.form.get(f'ticket_code_{idx}') or '').strip()
            for pidx, (page_bytes, companion_bytes) in enumerate(page_pairs):
                page_sha = hashlib.sha256(page_bytes).hexdigest()
                page_label = f'{stem} (pág. {pidx + 1})' if multi else stem
                # Duplicado real = misma página (SHA): se salta e informa; el resto del lote sí se sube.
                if page_sha in seen_shas or page_sha in existing_shas:
                    duplicates.append(page_label)
                    continue
                meta = _invitation_extract_ticket_metadata(page_bytes, f'{stem}-p{pidx + 1}.pdf')
                reliable_code = bool(meta.get('code_reliable'))
                manual_code = bool(form_code_single) and not multi
                # Una invitación SIEMPRE tiene código (de barras o localizador/código etiquetado). Si la
                # página no lo trae y no se ha escrito a mano, no es una invitación: se descarta y se avisa.
                if not meta.get('has_code') and not manual_code:
                    discarded.append(page_label)
                    continue
                if not multi and form_code_single:
                    code = form_code_single
                    reliable_code = True
                else:
                    code = (meta.get('ticket_code') or f'{stem}-p{pidx + 1}').strip()
                code = (code or page_sha[:16])[:120]
                # Solo se deduplica por CÓDIGO si es fiable (etiquetado en el PDF o escrito a mano);
                # si no, se garantiza un código único (sufijo) para no perder PDFs distintos.
                if _code_taken(code):
                    if reliable_code:
                        duplicates.append(f'{page_label} · {code}')
                        continue
                    base = code[:110]
                    suffix = 2
                    while _code_taken(code) and suffix < 9999:
                        code = f'{base}-{suffix}'
                        suffix += 1
                meta_sector = meta.get('sector') if is_numbered else None
                meta_row = meta.get('row_label') if is_numbered else None
                meta_seat = meta.get('seat_number') if is_numbered else None
                if multi:
                    sector_val = (request.form.get('sector') or meta_sector or '').strip() or None
                    row_val = (request.form.get('row_label') or meta_row or '').strip() or None
                    seat_val = (meta_seat or '').strip() or None
                else:
                    sector_val = (request.form.get(f'sector_{idx}') or request.form.get('sector') or meta_sector or '').strip() or None
                    row_val = (request.form.get(f'row_{idx}') or request.form.get('row_label') or meta_row or '').strip() or None
                    seat_val = (request.form.get(f'seat_{idx}') or meta_seat or '').strip() or None
                # Si en una subida NUMERADA una entrada no trae sector/fila/asiento (se coló una sin
                # numerar), se separa en un sector propio "Sin numerar" para no mezclarla con las numeradas.
                if is_numbered and not sector_val and not row_val and not seat_val:
                    sector_val = 'Sin numerar'
                # Antiduplicados por BUTACA: no subir dos veces la misma localidad (sector+fila+asiento)
                # en el mismo concierto, aunque el PDF sea distinto (complementa la deduplicación por SHA).
                if is_numbered and seat_val and sector_val and sector_val != 'Sin numerar':
                    _bk = (str(sector_val).strip().lower(), str(row_val or '').strip().lower(), str(seat_val).strip().lower())
                    if _bk in seen_butacas or _bk in existing_butacas:
                        duplicates.append(f'{page_label} · {sector_val} F{row_val or "-"} A{seat_val}')
                        continue
                    seen_butacas.add(_bk)
                # Decisión tomada: reservamos código/SHA en el lote y encolamos la subida (que se hace
                # en paralelo más abajo para que sea muy rápida). Aún no subimos ni creamos nada.
                seen_codes.add(code)
                seen_shas.add(page_sha)
                pending.append({
                    'page_bytes': page_bytes, 'companion_bytes': companion_bytes,
                    'code': code, 'page_label': page_label, 'page_sha': page_sha,
                    'pdf_name': (f'{stem}.pdf' if multi else fname), 'stem': stem,
                    'sector': sector_val, 'row_label': row_val, 'seat_number': seat_val,
                })

        # Subida a Storage EN PARALELO: subir de una en una a la región del bucket era el cuello de
        # botella; con hilos, N páginas se suben a la vez y el proceso es muy rápido.
        if pending:
            def _do_upload(item):
                try:
                    item['url'] = upload_pdf_bytes(item['page_bytes'], folder)
                except Exception as up_exc:
                    item['upload_error'] = str(up_exc)
                    return
                if item.get('companion_bytes') is not None:
                    try:
                        item['companion_url'] = upload_pdf_bytes(item['companion_bytes'], folder)
                    except Exception as _cexc:
                        item['companion_error'] = str(_cexc)
            from concurrent.futures import ThreadPoolExecutor
            with ThreadPoolExecutor(max_workers=min(8, max(1, len(pending)))) as _ex:
                list(_ex.map(_do_upload, pending))

        # Persistencia EN ORDEN (una entrada por página aceptada).
        for item in pending:
            if item.get('upload_error'):
                errors.append(f"{item['page_label']}: no se pudo subir ({item['upload_error']})")
                continue
            ticket = InvitationTicket(
                concert_id=concert.id,
                category_id=(category.id if category else None),
                ticket_code=item['code'],
                pdf_url=item['url'],
                pdf_name=item['pdf_name'],
                pdf_sha256=item['page_sha'],
                is_numbered=is_numbered,
                sector=item['sector'],
                row_label=item['row_label'],
                seat_number=item['seat_number'],
                uploaded_by_user_id=_safe_uuid(session.get('user_id')),
                uploaded_by_nick=_current_user_email(),
            )
            session_db.add(ticket)
            created += 1
            created_tickets.append(ticket)
            # PMR: la 2ª página va adjunta como entrada de ACOMPAÑANTE (viaja siempre con la invitación).
            if item.get('companion_url'):
                ticket.companion_pdf_url = item['companion_url']
                ticket.companion_pdf_name = f"{item['stem']} (acompañante).pdf"
                companions_linked += 1
            elif item.get('companion_error'):
                errors.append(f"{item['page_label']}: no se pudo subir el acompañante ({item['companion_error']})")
            if is_numbered:
                created_rows.append({
                    "sector": item['sector'] or "", "row_label": item['row_label'] or "",
                    "seat_number": item['seat_number'] or "", "pdf_name": ticket.pdf_name or "",
                })
        if category is not None:
            category.updated_at = _now_madrid()
        session_db.commit()
        _is_ajax = _truthy(request.form.get('ajax')) or request.headers.get('X-Requested-With') == 'XMLHttpRequest'
        if _is_ajax:
            # Subida AJAX (numeradas): devuelve el resultado detectado para el popup de revisión.
            return jsonify({
                "ok": True,
                "category_id": str(category.id) if category else "",
                "is_numbered": bool(is_numbered),
                "created": created,
                "duplicates": len(duplicates),
                "discarded": len(discarded),
                "companions": companions_linked,
                "errors": errors[:8],
                "tickets": created_rows,
            })
        if created:
            flash(f'{created} invitaciones subidas.' + (f' {companions_linked} con entrada de acompañante.' if companions_linked else ''), 'success')
        if duplicates:
            extra = f' (+{len(duplicates) - 8} más)' if len(duplicates) > 8 else ''
            flash(f'⚠️ {len(duplicates)} invitación(es) duplicada(s): solo se mantiene una de cada. No subidas: ' + ' · '.join(duplicates[:8]) + extra, 'warning')
        if discarded:
            extra = f' (+{len(discarded) - 8} más)' if len(discarded) > 8 else ''
            flash(f'⚠️ {len(discarded)} página(s) descartada(s) por no tener código (no parecen invitaciones): ' + ' · '.join(discarded[:8]) + extra, 'warning')
        if errors:
            flash('Algunas invitaciones no se pudieron subir: ' + ' · '.join(errors[:8]), 'warning')
    except Exception as exc:
        session_db.rollback()
        if _truthy(request.form.get('ajax')) or request.headers.get('X-Requested-With') == 'XMLHttpRequest':
            return jsonify({"ok": False, "error": str(exc)}), 400
        flash(f'No se pudieron subir las invitaciones: {exc}', 'danger')
    finally:
        session_db.close()
    return redirect(url_for('invitation_event_detail', concert_id=concert_id) + '#inv-tab-tickets')


@app.post('/invitaciones/evento/<concert_id>/tickets/redetectar', endpoint='invitation_tickets_redetect')
@admin_required
def invitation_tickets_redetect(concert_id):
    """Re-lee los PDF de las entradas NUMERADAS ya subidas y actualiza sector/fila/asiento con la
    detección actual (útil cuando se mejora el detector: p. ej. asiento etiquetado como "Nº:"). No
    borra datos: solo rellena/corrige lo que ahora se detecta. Acepta `category_id` opcional."""
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        if not concert:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)
        _cat_id = _safe_uuid(request.form.get('category_id'))
        q = session_db.query(InvitationTicket).filter(
            InvitationTicket.concert_id == concert.id,
            InvitationTicket.is_numbered.is_(True),
        )
        if _cat_id:
            q = q.filter(InvitationTicket.category_id == _cat_id)
        tickets = q.all()
        updated = 0
        failed = 0
        for t in tickets:
            url = (getattr(t, 'pdf_url', None) or '').strip()
            if not url:
                continue
            content = None
            for _attempt in range(3):
                try:
                    content, _ct = _download_remote_content(url)
                    break
                except Exception:
                    content = None
            if content is None:
                failed += 1
                continue
            meta = _invitation_extract_ticket_metadata(content, getattr(t, 'pdf_name', None))
            new_sector = (meta.get('sector') or '').strip() or None
            new_row = (meta.get('row_label') or '').strip() or None
            new_seat = (meta.get('seat_number') or '').strip() or None
            changed = False
            # Solo actualiza cuando ahora se detecta algo (no se borra lo ya guardado si no se detecta).
            if new_seat and new_seat != (t.seat_number or None):
                t.seat_number = new_seat
                changed = True
            if new_row and new_row != (t.row_label or None):
                t.row_label = new_row
                changed = True
            if new_sector and new_sector != (t.sector or None):
                t.sector = new_sector
                changed = True
            if changed:
                t.updated_at = _now_madrid()
                updated += 1
        session_db.commit()
        _is_ajax = _truthy(request.form.get('ajax')) or request.headers.get('X-Requested-With') == 'XMLHttpRequest'
        if _is_ajax:
            rows_out = [{
                "sector": (t.sector or ""), "row_label": (t.row_label or ""),
                "seat_number": (t.seat_number or ""), "pdf_name": (t.pdf_name or ""),
            } for t in tickets]
            return jsonify({"ok": True, "updated": updated, "total": len(tickets), "failed": failed, "tickets": rows_out})
        msg = f'Re-detección de butacas: {updated} entrada(s) actualizada(s) de {len(tickets)} numerada(s).'
        if failed:
            msg += f' {failed} no se pudieron descargar (reintentar más tarde).'
        flash(msg, 'success' if updated else 'info')
        return redirect(url_for('invitation_event_detail', concert_id=concert.id) + '#inv-tab-tickets')
    except Exception as exc:
        session_db.rollback()
        if _truthy(request.form.get('ajax')) or request.headers.get('X-Requested-With') == 'XMLHttpRequest':
            return jsonify({"ok": False, "error": str(exc)}), 400
        flash(f'No se pudo re-detectar las butacas: {exc}', 'danger')
        return redirect(url_for('invitation_event_detail', concert_id=concert_id) + '#inv-tab-tickets')
    finally:
        session_db.close()


@app.post('/invitaciones/tickets/<ticket_id>/liberar', endpoint='invitation_ticket_release')
@admin_required
def invitation_ticket_release(ticket_id):
    """Recupera/desvincula una invitación numerada concreta, gestionando su estado:

    - NO enviada → al desvincular vuelve directamente a estar disponible (sin avisos).
    - Enviada (sin descargar) → requiere confirmación; al recuperar vuelve a disponible.
    - Descargada → confirmación con dos caminos: `recover` (vuelve a disponible) o
      `lost` (se desvincula pero NO vuelve al pool de disponibles).

    Sin un `mode` válido cuando hace falta, responde `needs_confirm` para que el front avise.
    """
    _ajax = _truthy(request.form.get('ajax'))
    session_db = db()
    try:
        ticket = session_db.get(InvitationTicket, to_uuid(ticket_id))
        if not ticket:
            abort(404)
        _ensure_can_manage_invitations(session_db, ticket.concert)
        cid = ticket.concert_id
        req = session_db.get(InvitationRequest, ticket.assigned_request_id) if getattr(ticket, 'assigned_request_id', None) else None
        sent_statuses = {'ENVIADAS', 'ENTREGADAS_MANO', 'DISPONIBLES_TAQUILLA', 'RECOGIDAS_TAQUILLA'}
        # El estado que manda es el de LA ENTRADA (una IMPRESA se recupera igual que una enviada):
        # las AÑADIDAS al ampliar una solicitud ya enviada están solo ASIGNADAS y se desasignan/
        # mueven como cualquier otra, sin confirmación, aunque la solicitud figure como enviada.
        was_sent = (ticket.status or '') in {'SENT', 'DELIVERED', 'PICKED_UP', 'PRINTED'} or bool(getattr(ticket, 'sent_at', None))
        if not was_sent and req is not None and (bool(req.sent_at) or (req.status or '') in sent_statuses):
            # Compat con datos antiguos (solicitud enviada sin marcar sus entradas): solo cuenta como
            # enviada si la entrada ya estaba asignada ANTES del envío de la solicitud.
            if req.sent_at is None or ticket.assigned_at is None or ticket.assigned_at <= req.sent_at:
                was_sent = True
        was_downloaded = was_sent and bool(req is not None and (bool(req.downloaded_at) or _safe_int(req.downloaded_count) > 0))
        who = ticket.assigned_label or (req.guest_name if req else '') or 'el invitado'
        mode = (request.form.get('mode') or '').strip().lower()

        # Una BLOQUEADA no se «recupera»: se desbloquea desde su botón (así el recuperar en bloque
        # de una zona no quita bloqueos sin querer).
        if (ticket.status or '').upper() == 'BLOCKED':
            if _ajax:
                return jsonify({'ok': False, 'error': 'Esta invitación está bloqueada: usa «Desbloquear» para volver a ponerla disponible.'}), 400
            flash('Esta invitación está bloqueada: usa «Desbloquear» para volver a ponerla disponible.', 'warning')
            return redirect(url_for('invitation_event_detail', concert_id=cid) + '#inv-tab-tickets')

        # Enviada sin decisión explícita → no liberar a ciegas: pedir confirmación.
        if was_sent and mode not in {'recover', 'lost'}:
            info = {
                'ok': False, 'needs_confirm': True, 'sent': True,
                'downloaded': bool(was_downloaded), 'assigned_label': ticket.assigned_label or (req.guest_name if req else ''),
            }
            if _ajax:
                return jsonify(info)
            flash('Esta invitación ya fue enviada. Usa el aviso para recuperarla o desvincularla.', 'warning')
            return redirect(url_for('invitation_event_detail', concert_id=cid) + '#inv-tab-tickets')

        if was_sent and mode == 'lost':
            ticket.previous_assignment_warning = (
                f"Enviada y descargada por {who}; desvinculada sin recuperar." if was_downloaded
                else f"Enviada a {who}; desvinculada sin recuperar."
            )
            ticket.status = 'LOST'
            msg = 'Invitación desvinculada (no vuelve a estar disponible).'
        else:
            if was_downloaded:
                ticket.previous_assignment_warning = f"Ya había sido enviada y descargada por {who}."
            elif was_sent:
                ticket.previous_assignment_warning = f"Ya había sido enviada a {who}."
            elif ticket.assigned_label:
                ticket.previous_assignment_warning = f"Ya había sido asignada a {ticket.assigned_label}."
            ticket.status = 'AVAILABLE'
            msg = 'Invitación recuperada y de nuevo disponible.'
        _cmt_rel = session_db.get(InvitationCommitment, ticket.assigned_commitment_id) if getattr(ticket, 'assigned_commitment_id', None) else None
        ticket.assigned_request_id = None
        ticket.assigned_commitment_id = None
        ticket.assigned_label = None
        ticket.sent_at = None
        ticket.added_after_send = False   # al soltarse deja de ser «Nueva» de ninguna ampliación
        ticket.updated_at = _now_madrid()
        # Estado de la solicitud/compromiso desde sus entradas (p. ej. si se recuperan TODAS las
        # enviadas, deja de figurar como enviada y vuelve a pendiente).
        session_db.flush()
        if req is not None:
            _invitation_sync_request_status(session_db, req)
            req.updated_at = _now_madrid()
        if _cmt_rel is not None:
            _invitation_sync_commitment_status(session_db, _cmt_rel)
            _cmt_rel.updated_at = _now_madrid()
        session_db.commit()
        if _ajax:
            return jsonify({'ok': True, 'ticket_id': str(ticket.id), 'message': msg})
        flash(msg, 'success')
        return redirect(url_for('invitation_event_detail', concert_id=cid) + '#inv-tab-tickets')
    except Exception as exc:
        session_db.rollback()
        if _ajax:
            return jsonify({'ok': False, 'error': str(exc)}), 400
        flash(f'No se pudo recuperar la entrada: {exc}', 'danger')
        return redirect(url_for('invitations_view', tab='gestionar'))
    finally:
        session_db.close()


