@admin_required
def invitation_ticket_delete(ticket_id):
    session_db = db()
    try:
        ticket = session_db.get(InvitationTicket, to_uuid(ticket_id))
        if not ticket:
            abort(404)
        _ensure_can_manage_invitations(session_db, ticket.concert)
        cid = ticket.concert_id
        session_db.delete(ticket)
        session_db.commit()
        flash('Entrada eliminada.', 'success')
        return redirect(url_for('invitation_event_detail', concert_id=cid) + '#inv-tab-tickets')
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo eliminar la entrada: {exc}', 'danger')
        return redirect(url_for('invitations_view', tab='gestionar'))
    finally:
        session_db.close()


@app.post('/invitaciones/evento/<concert_id>/tickets/bulk', endpoint='invitation_tickets_bulk')
@admin_required
def invitation_tickets_bulk(concert_id):
    """Acciones en bloque sobre varias entradas: eliminar o mover de categoría a la vez."""
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        if not concert:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)
        action = (request.form.get('action') or '').strip().lower()
        ids = [to_uuid(x) for x in (request.form.get('ticket_ids') or '').split(',') if to_uuid(x)]
        if not ids:
            raise ValueError('No has seleccionado ninguna invitación.')
        tickets = (
            session_db.query(InvitationTicket)
            .filter(InvitationTicket.concert_id == concert.id, InvitationTicket.id.in_(ids))
            .all()
        )
        if action == 'delete':
            n = 0
            for t in tickets:
                session_db.delete(t)
                n += 1
            session_db.commit()
            flash(f'{n} invitación(es) eliminada(s).', 'success')
        elif action == 'move':
            new_cat = session_db.get(InvitationCategory, to_uuid(request.form.get('category_id')))
            if not new_cat or new_cat.concert_id != concert.id:
                raise ValueError('Categoría destino no válida.')
            n = 0
            for t in tickets:
                if t.category_id == new_cat.id:
                    continue
                t.category_id = new_cat.id
                t.is_numbered = (new_cat.ticket_kind or '').upper() == 'PDF_NUMBERED'
                if (t.status or '') != 'AVAILABLE':
                    t.status = 'AVAILABLE'
                    t.assigned_request_id = None
                    t.assigned_commitment_id = None
                    t.assigned_label = None
                    t.sent_at = None
                    t.added_after_send = False
                t.updated_at = _now_madrid()
                n += 1
            session_db.commit()
            flash(f'{n} invitación(es) movida(s) a «{new_cat.name}».', 'success')
        else:
            raise ValueError('Acción no válida.')
        return redirect(url_for('invitation_event_detail', concert_id=concert_id) + '#inv-tab-tickets')
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo completar la acción en bloque: {exc}', 'danger')
        return redirect(url_for('invitation_event_detail', concert_id=concert_id) + '#inv-tab-tickets')
    finally:
        session_db.close()


@app.get('/invitaciones/evento/<concert_id>/plano/<category_id>', endpoint='invitation_sector_plan')
@admin_required
def invitation_sector_plan(concert_id, category_id):
    """Datos del plano de UN sector para el configurador (rueda): rejilla auto (mín→máx por paso),
    qué butacas existen y los retoques guardados (escaleras/huecos/apagados/escenario)."""
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        cat = session_db.get(InvitationCategory, to_uuid(category_id))
        if not concert or not cat or cat.concert_id != concert.id:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)
        sector = (request.args.get('sector') or '').strip() or 'General'
        # Butacas por FILA del sector (para mostrar el plano completo en el configurador).
        by_row: dict = {}
        for t in session_db.query(InvitationTicket).filter(InvitationTicket.category_id == cat.id).all():
            if (getattr(t, 'sector', None) or 'General') != sector:
                continue
            sv = getattr(t, 'seat_number', None)
            if str(sv or '').isdigit():
                by_row.setdefault((getattr(t, 'row_label', None) or 'Sin fila'), set()).add(int(sv))
        all_nums = sorted({n for s in by_row.values() for n in s})
        cfg = _invitation_sector_layout(cat, sector, concert=concert)
        cfg_positions = set(cfg.get('legacy_gaps') or ()) | set(cfg.get('legacy_off') or ())
        for _rc in (cfg.get('rows_cfg') or {}).values():
            cfg_positions |= set(_rc.get('gaps') or ()) | set(_rc.get('off') or ())
        # El rango (mín→máx) lo definen las posiciones ENTERAS; los decimales son inserciones intermedias.
        int_vals = list(all_nums) + [int(p) for p in cfg_positions if float(p) == int(p)]
        step = 2 if (len(all_nums) >= 2 and len({n % 2 for n in all_nums}) == 1 and (all_nums[-1] - all_nums[0]) >= 2) else 1
        mn = min(int_vals) if int_vals else 0
        mx = max(int_vals) if int_vals else 0
        # Orden NATURAL de filas (Fila 1,2,…,10,11), IGUAL que la visión y la asignación
        # (_invitation_ticket_groups): el plano se ve idéntico en el configurador y en el mapa.
        rows = [{'label': rl, 'seats': sorted(by_row[rl])} for rl in sorted(by_row.keys(), key=_invitation_natural_key)]
        rows_cfg = {rl: {'stairs': sorted(rc.get('stairs') or ()), 'gaps': sorted(rc.get('gaps') or ()), 'off': sorted(rc.get('off') or ())}
                    for rl, rc in (cfg.get('rows_cfg') or {}).items()}
        separators = [{'after': sp.get('after') or '', 'stairs': sorted(sp.get('stairs') or ()),
                       'gaps': sorted(sp.get('gaps') or ()), 'off': sorted(sp.get('off') or ())}
                      for sp in (cfg.get('separators') or [])]
        return jsonify({
            'ok': True, 'sector': sector, 'step': step, 'min': mn, 'max': mx,
            'rows': rows,
            'config': {
                'rows': rows_cfg,
                'separators': separators,
                'legacy': {'stairs': sorted(cfg.get('legacy_stairs') or ()), 'gaps': sorted(cfg.get('legacy_gaps') or ()), 'off': sorted(cfg.get('legacy_off') or ())},
                'stage': cfg['stage'], 'orientation': cfg.get('orientation', 'ltr'),
            },
        })
    finally:
        session_db.close()


@app.post('/invitaciones/evento/<concert_id>/plano/<category_id>', endpoint='invitation_sector_layout_save')
@admin_required
def invitation_sector_layout_save(concert_id, category_id):
    """Guarda los retoques del plano de un sector (escaleras/huecos/apagados/escenario) en layout_json."""
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        cat = session_db.get(InvitationCategory, to_uuid(category_id))
        if not concert or not cat or cat.concert_id != concert.id:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)
        data = request.get_json(silent=True) or {}
        sector = (data.get('sector') or request.form.get('sector') or '').strip() or 'General'

        def _as_ints(v):
            out = set()
            for x in (v or []):
                try:
                    f = float(x)
                except (TypeError, ValueError):
                    continue
                if f == int(f):
                    out.add(int(f))
            return sorted(out)

        def _as_nums(v):
            # Enteros (butacas existentes) o decimales (inserciones entre butacas / fuera de rango).
            out = set()
            for x in (v or []):
                try:
                    f = float(x)
                except (TypeError, ValueError):
                    continue
                out.add(int(f) if f == int(f) else round(f, 4))
            return sorted(out)
        orientation = (data.get('orientation') or 'ltr').strip().lower()
        # Config por FILA: {rowLabel: {stairs (enteros), gaps/off (enteros o decimales)}}.
        rows_out = {}
        rows_in = data.get('rows') if isinstance(data.get('rows'), dict) else {}
        for rl, rc in (rows_in or {}).items():
            if not isinstance(rc, dict):
                continue
            st, gp, of = _as_ints(rc.get('stairs')), _as_nums(rc.get('gaps')), _as_nums(rc.get('off'))
            if st or gp or of:
                rows_out[str(rl)] = {'stairs': st, 'gaps': gp, 'off': of}
        # Filas-separadoras (pasillos entre filas): lista de {after, stairs, gaps, off}. `after` = la
        # fila tras la que va (vacío = arriba del todo). Se descartan las vacías.
        seps_out = []
        for sp in (data.get('separators') if isinstance(data.get('separators'), list) else []):
            if not isinstance(sp, dict):
                continue
            st, gp, of = _as_ints(sp.get('stairs')), _as_nums(sp.get('gaps')), _as_nums(sp.get('off'))
            if st or gp or of:
                seps_out.append({'after': str(sp.get('after') or ''), 'stairs': st, 'gaps': gp, 'off': of})
        # Escenario: punto {x,y} en % sobre el marco (o null).
        stage_raw = data.get('stage')
        stage_out = None
        if isinstance(stage_raw, dict):
            try:
                stage_out = {'x': max(0.0, min(100.0, float(stage_raw.get('x')))), 'y': max(0.0, min(100.0, float(stage_raw.get('y'))))}
            except (TypeError, ValueError):
                stage_out = None
        sec_cfg = {
            'rows': rows_out,
            'separators': seps_out,
            'stage': stage_out,
            'orientation': 'rtl' if orientation == 'rtl' else 'ltr',
        }
        layout = dict(_invitation_layout_json(cat))
        sectors = dict(layout.get('sectors') or {})
        sectors[sector] = sec_cfg
        layout['sectors'] = sectors
        cat.layout_json = layout
        cat.updated_at = _now_madrid()
        session_db.commit()
        return jsonify({'ok': True, 'sector': sector, 'config': sec_cfg})
    except Exception as exc:
        session_db.rollback()
        return jsonify({'ok': False, 'error': str(exc)}), 400
    finally:
        session_db.close()


def _invitation_bulk_selected_tickets(session_db, concert):
    ids = [to_uuid(x) for x in (request.form.get('ticket_ids') or '').split(',') if to_uuid(x)]
    if not ids:
        raise ValueError('No has seleccionado ninguna invitación.')
    tickets = (session_db.query(InvitationTicket)
               .filter(InvitationTicket.concert_id == concert.id, InvitationTicket.id.in_(ids))
               .order_by(InvitationTicket.sector.asc().nullslast(), InvitationTicket.row_label.asc().nullslast(), InvitationTicket.seat_number.asc().nullslast())
               .all())
    if not tickets:
        raise ValueError('No se encontraron las invitaciones seleccionadas.')
    return tickets


@app.post('/invitaciones/evento/<concert_id>/tickets/imprimir', endpoint='invitation_tickets_bulk_print')
@admin_required
def invitation_tickets_bulk_print(concert_id):
    """Imprime en bloque las entradas seleccionadas: las une en un PDF y las marca IMPRESAS (naranja).
    Una impresa funciona como enviada (no reutilizable); se recupera igual que una enviada."""
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        if not concert:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)
        tickets = _invitation_bulk_selected_tickets(session_db, concert)
        _blocked = [t for t in tickets if (t.status or '').upper() == 'BLOCKED']
        if _blocked:
            raise ValueError(f'La selección incluye {len(_blocked)} entrada(s) BLOQUEADA(s): desbloquéalas antes de poder imprimirlas.')
        reason = (request.form.get('reason') or '').strip()
        with_pdf = [t for t in tickets if (getattr(t, 'pdf_url', None) or '').strip()]
        if not with_pdf:
            raise ValueError('Las invitaciones seleccionadas no tienen PDF que imprimir.')
        pdf_bytes, _n = _invitation_tickets_to_merged_pdf(with_pdf)
        if not pdf_bytes:
            raise ValueError('No se pudieron preparar los PDF para imprimir.')
        now = _now_madrid()
        for t in tickets:
            t.status = 'PRINTED'
            t.printed_at = now
            t.print_reason = reason or t.print_reason
            t.sent_at = t.sent_at or now
            t.updated_at = now
        session_db.commit()
        resp = Response(pdf_bytes, mimetype='application/pdf')
        resp.headers['Content-Disposition'] = 'inline; filename="invitaciones.pdf"'
        return resp
    except Exception as exc:
        session_db.rollback()
        return jsonify({'ok': False, 'error': str(exc)}), 400
    finally:
        session_db.close()


