@app.post('/invitaciones/listado/<token>/solicitudes/<request_id>/estado', endpoint='public_invitation_guest_list_status')
def public_invitation_guest_list_status(token, request_id):
    session_db = db()
    try:
        link = session_db.query(InvitationGuestListLink).filter(InvitationGuestListLink.token == token, InvitationGuestListLink.status == 'ACTIVE').first()
        row = session_db.get(InvitationRequest, to_uuid(request_id))
        if not link or not row or row.concert_id != link.concert_id:
            abort(404)
        action = (request.form.get('action') or '').strip().upper()
        explicit_status = (request.form.get('status') or '').strip().upper()
        if explicit_status in {'ENTREGADAS_MANO', 'RECOGIDAS_TAQUILLA'} or action in {'ENTERED', 'PICKED_UP', 'DELIVERED'}:
            if explicit_status in {'ENTREGADAS_MANO', 'RECOGIDAS_TAQUILLA'}:
                row.status = explicit_status
            elif (link.list_type or '').upper() == 'DOOR' or action == 'ENTERED':
                row.status = 'ENTREGADAS_MANO'
            else:
                row.status = 'RECOGIDAS_TAQUILLA'
            row.delivered_at = _now_madrid()
            row.updated_at = row.delivered_at
            session_db.commit()
            flash('Estado actualizado.', 'success')
        return redirect(url_for('public_invitation_guest_list', token=token))
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo actualizar el estado: {exc}', 'danger')
        return redirect(url_for('public_invitation_guest_list', token=token))
    finally:
        session_db.close()

@app.get('/invitaciones/p/<token>', endpoint='public_invitation_request_link')
def public_invitation_request_link(token):
    session_db = db()
    try:
        _ensure_invitation_link_columns(session_db)
        link = session_db.query(InvitationPublicLink).filter(InvitationPublicLink.token == token).first()
        if not link:
            abort(404)
        concert = link.concert or session_db.get(Concert, link.concert_id)
        if not concert:
            abort(404)
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=True)
        session_db.commit()
        requests = session_db.query(InvitationRequest).filter(InvitationRequest.public_link_id == link.id).order_by(InvitationRequest.created_at.desc()).all()
        state, state_message = _invitation_link_state(link)
        open_for_changes = (state == 'active')
        event_avail_by_cat = _invitation_event_available_by_category(session_db, concert, categories)
        event_avail_total = _invitation_event_counts(session_db, concert)['result']
        # Palcos ya comprometidos o COMPLETOS (asignados/enviados): no se ofrecen al pedir por el
        # enlace público.
        committed_palco = _invitation_request_excluded_category_ids(session_db, concert, categories)
        limits = _invitation_public_limits(link, categories, requests, event_avail_by_cat, event_avail_total, exclude_ids=committed_palco)
        editable_statuses = {'SOLICITADAS', 'APROBADAS', 'ASIGNADAS'}
        manage_statuses = {'ASIGNADAS', 'ENVIADAS', 'ENTREGADAS_MANO', 'DISPONIBLES_TAQUILLA', 'RECOGIDAS_TAQUILLA'}
        req_payloads = []
        for r in requests:
            rp = _invitation_request_payload(r, categories)
            st = rp['status']
            rp['can_edit'] = open_for_changes and st in editable_statuses
            rp['can_cancel'] = open_for_changes and st not in {'ANULADAS', 'RECHAZADAS'}
            rp['can_manage'] = st in manage_statuses and bool(r.delivery_token)
            rp['delivery_url'] = _external_url_for('public_invitation_delivery', kind='r', token=r.delivery_token) if r.delivery_token else ''
            rp['share_text'] = _invitation_share_text(session_db, concert, rp['guest_name'], rp['delivery_url']) if rp['can_manage'] else ''
            req_payloads.append(rp)
        _invitation_group_requests(req_payloads, categories)
        # Open Graph para previsualización WhatsApp/SMS.
        # Se pasa el artista para que la imagen sea el CARTEL principal y, si no lo hay, la foto del artista.
        try:
            card = _public_share_card(session_db, 'CONCERT', concert, artist_id=getattr(concert, 'artist_id', None))
        except Exception:
            card = {}
        event_payload = _invitation_event_payload(session_db, concert)
        og_title = f"Solicitud de invitaciones · {event_payload.get('artist_names') or event_payload.get('title') or ''}".strip(' ·')
        # El nombre del invitado va en el propio TÍTULO, con «Para:» delante.
        if (link.target_name or '').strip():
            og_title = f"{og_title} · Para: {link.target_name.strip()}"
        og_desc_parts = [x for x in [card.get('activity_label'), card.get('event_name') or card.get('city'), card.get('date_label')] if x]
        og = {
            'title': og_title,
            'description': ' · '.join(og_desc_parts),
            # Cartel principal → foto de cualquier artista del evento → logo (siempre absoluta).
            'image': _public_share_og_image(session_db, concert, event_payload=event_payload, card=card,
                                             logo=_invitation_event_logo_url(session_db, concert, external=True)),
        }
        return render_template(
            'public_invitation_request.html',
            link=link,
            link_state=state,
            open_for_changes=open_for_changes,
            state_message=state_message,
            event=event_payload,
            event_logo=_invitation_event_logo_url(session_db, concert, external=True),
            categories=categories,
            limits=limits,
            requests=req_payloads,
            grouped_requests=_invitation_grouped(req_payloads, categories, allowed_ids=[c['id'] for c in limits['categories']], locked_labels={cid: 'Asignado' for cid in committed_palco}),
            status_labels=INVITATION_STATUS_LABELS,
            og=og,
        )
    finally:
        session_db.close()


@app.post('/invitaciones/p/<token>/solicitar', endpoint='public_invitation_request_submit')
def public_invitation_request_submit(token):
    session_db = db()
    try:
        link = session_db.query(InvitationPublicLink).filter(InvitationPublicLink.token == token).first()
        if not link:
            abort(404)
        state, msg = _invitation_link_state(link)
        if state != 'active':
            flash(msg or 'El enlace no está disponible.', 'warning')
            return redirect(url_for('public_invitation_request_link', token=token))
        concert = link.concert or session_db.get(Concert, link.concert_id)
        if not concert:
            abort(404)
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=True)
        existing = session_db.query(InvitationRequest).filter(InvitationRequest.public_link_id == link.id).all()
        quantities = _invitation_quantities_from_form(request.form, categories)
        if not link.categorize_requests:
            total = _safe_int(request.form.get('qty_total')) or _invitation_total_qty(quantities)
            quantities = {'TOTAL': total}
        if _invitation_total_qty(quantities) <= 0:
            raise ValueError('Indica al menos una invitación.')
        # Cupo: por defecto las peticiones NO se limitan por el aforo del evento (el control real se
        # hace al asignar). Solo se rechaza superar el cupo en las categorías marcadas con
        # «No aceptar peticiones por encima del cupo» en la configuración de invitaciones.
        _inv_available = _invitation_event_counts(session_db, concert)['result']
        _event_avail_by_cat = _invitation_event_available_by_category(session_db, concert, categories)
        _over = [f"{c.name} (quedan {max(_safe_int(_event_avail_by_cat.get(str(c.id), 0)), 0)})"
                 for c in categories
                 if getattr(c, 'requests_over_quota_blocked', False)
                 and _safe_int(quantities.get(str(c.id))) > max(_safe_int(_event_avail_by_cat.get(str(c.id), 0)), 0)]
        if _over:
            raise ValueError('No se aceptan peticiones por encima del cupo en: ' + ', '.join(_over) + '.')
        _committed_palco = _invitation_request_excluded_category_ids(session_db, concert, categories)
        limits = _invitation_public_limits(link, categories, existing, _event_avail_by_cat, _inv_available, exclude_ids=_committed_palco)
        if limits.get('total_limit') is not None and _invitation_total_qty(quantities) > limits.get('available_total', 0):
            raise ValueError('La petición supera el límite disponible del enlace.')
        available_by_cat = {str(x['id']): x.get('available') for x in limits.get('categories') or []}
        allowed_cids = set(available_by_cat.keys())
        for cid, qty in quantities.items():
            if str(cid) != 'TOTAL' and allowed_cids and str(cid) not in allowed_cids:
                raise ValueError('La categoría seleccionada no está habilitada para este enlace.')
            if available_by_cat.get(str(cid)) is not None and _safe_int(qty) > _safe_int(available_by_cat.get(str(cid))):
                raise ValueError('La petición supera el límite disponible por categoría.')
        receiver_mode = (request.form.get('receiver_mode') or 'GUEST').strip().upper()
        receiver_payload = {
            'name': (request.form.get('receiver_name') or '').strip(),
            'email': (request.form.get('receiver_email') or '').strip(),
            'phone': (request.form.get('receiver_phone') or '').strip(),
        }
        row = InvitationRequest(
            concert_id=concert.id,
            public_link_id=link.id,
            request_source='PUBLIC_LINK',
            requester_type='PUBLIC_LINK',
            requester_nick=link.target_name or 'Enlace público',
            requester_email=link.target_email,
            requester_photo_url=url_for('static', filename='img/placeholder_photo.png'),
            guest_type='THIRD_PARTY',
            guest_name=(request.form.get('guest_name') or '').strip() or 'Invitado',
            guest_company=(request.form.get('guest_company') or '').strip(),
            guest_title=(request.form.get('guest_title') or request.form.get('guest_company') or '').strip(),
            guest_email=(request.form.get('guest_email') or '').strip(),
            guest_phone=(request.form.get('guest_phone') or '').strip(),
            guest_note=(request.form.get('guest_note') or '').strip(),
            receiver_mode=receiver_mode,
            receiver_payload=receiver_payload,
            quantities_json=quantities,
            status='SOLICITADAS',
            note=(request.form.get('note') or '').strip(),
            delivery_token=_invitation_token(),
        )
        session_db.add(row)
        session_db.commit()
        flash('Petición añadida. Queda pendiente de aprobación por la organización.', 'success')
        return redirect(url_for('public_invitation_request_link', token=token))
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo guardar la petición: {exc}', 'danger')
        return redirect(url_for('public_invitation_request_link', token=token))
    finally:
        session_db.close()


@app.post('/invitaciones/p/<token>/solicitudes/<request_id>/anular', endpoint='public_invitation_request_cancel')
def public_invitation_request_cancel(token, request_id):
    session_db = db()
    try:
        link = session_db.query(InvitationPublicLink).filter(InvitationPublicLink.token == token).first()
        row = session_db.get(InvitationRequest, to_uuid(request_id))
        if not link or not row or row.public_link_id != link.id:
            abort(404)
        row.status = 'ANULADAS'
        row.cancelled_at = _now_madrid()
        row.cancelled_by_label = link.target_name or 'Enlace público'
        assigned = session_db.query(InvitationTicket).filter(InvitationTicket.assigned_request_id == row.id).all()
        for t in assigned:
            t.previous_assignment_warning = f"Ya había sido asignada/enviada a {row.guest_name}."
            t.assigned_request_id = None
            t.assigned_label = None
            t.status = 'AVAILABLE'
            t.sent_at = None
            t.added_after_send = False
        session_db.commit()
        flash('Petición anulada.', 'success')
        return redirect(url_for('public_invitation_request_link', token=token))
    finally:
        session_db.close()


@app.post('/invitaciones/p/<token>/solicitudes/<request_id>/categoria', endpoint='public_invitation_request_recategorize')
def public_invitation_request_recategorize(token, request_id):
    """Cambia la categoría de una solicitud desde el enlace público (arrastrar). JSON {category_id, confirm}."""
    session_db = db()
    try:
        link = session_db.query(InvitationPublicLink).filter(InvitationPublicLink.token == token).first()
        row = session_db.get(InvitationRequest, to_uuid(request_id))
        if not link or not row or row.public_link_id != link.id:
            abort(404)
        state, msg = _invitation_link_state(link)
        if state != 'active':
            return jsonify({"ok": False, "error": msg or "El enlace no admite cambios."})
        data = request.get_json(silent=True) or request.form
        res = _invitation_recategorize(session_db, row, (data.get('category_id') or '').strip(), _truthy(data.get('confirm')))
        if res.get('ok'):
            session_db.commit()
        else:
            session_db.rollback()
        return jsonify(res)
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        session_db.close()


@app.post('/invitaciones/p/<token>/solicitudes/<request_id>/editar', endpoint='public_invitation_request_update')
def public_invitation_request_update(token, request_id):
    session_db = db()
    try:
        link = session_db.query(InvitationPublicLink).filter(InvitationPublicLink.token == token).first()
        row = session_db.get(InvitationRequest, to_uuid(request_id))
        if not link or not row or row.public_link_id != link.id:
            abort(404)
        state, msg = _invitation_link_state(link)
        if state != 'active':
            flash(msg or 'El enlace no admite cambios.', 'warning')
            return redirect(url_for('public_invitation_request_link', token=token))
        if (row.status or '') not in {'SOLICITADAS', 'APROBADAS', 'ASIGNADAS'}:
            flash('Esta petición ya no se puede modificar (ya está enviada o cerrada).', 'warning')
            return redirect(url_for('public_invitation_request_link', token=token))
        concert = link.concert or session_db.get(Concert, link.concert_id)
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=True)
        quantities = _invitation_quantities_from_form(request.form, categories)
        if not link.categorize_requests:
            total = _safe_int(request.form.get('qty_total')) or _invitation_total_qty(quantities)
            quantities = {'TOTAL': total}
        if _invitation_total_qty(quantities) <= 0:
            raise ValueError('Indica al menos una invitación.')
        # Disponibilidad devolviendo lo que ESTA misma petición ya ocupaba (permite mantener/reducir).
        current = _json_dict(row.quantities_json)
        event_avail_by_cat = _invitation_event_available_by_category(session_db, concert, categories)
        for cid, q in current.items():
            if str(cid).upper() != 'TOTAL':
                event_avail_by_cat[str(cid)] = event_avail_by_cat.get(str(cid), 0) + _safe_int(q)
        event_avail_total = _invitation_event_counts(session_db, concert)['result'] + _invitation_total_qty(current)
        # Solo se rechaza superar el cupo en las categorías con «No aceptar por encima del cupo»
        # (event_avail_by_cat ya acredita lo que esta misma petición ocupaba).
        _over = [f"{c.name} (quedan {max(_safe_int(event_avail_by_cat.get(str(c.id), 0)), 0)})"
                 for c in categories
                 if getattr(c, 'requests_over_quota_blocked', False)
                 and _safe_int(quantities.get(str(c.id))) > max(_safe_int(event_avail_by_cat.get(str(c.id), 0)), 0)]
        if _over:
            raise ValueError('No se aceptan peticiones por encima del cupo en: ' + ', '.join(_over) + '.')
        existing = [x for x in session_db.query(InvitationRequest).filter(InvitationRequest.public_link_id == link.id).all() if x.id != row.id]
        # Palcos comprometidos a otros: no se pueden elegir al reeditar (salvo los que esta misma
        # petición ya ocupaba, para poder mantener/reducir).
        _committed_palco = _invitation_request_excluded_category_ids(session_db, concert, categories) - {str(k) for k in current.keys()}
        limits = _invitation_public_limits(link, categories, existing, event_avail_by_cat, event_avail_total, exclude_ids=_committed_palco)
        if limits.get('total_limit') is not None and _invitation_total_qty(quantities) > limits.get('available_total', 0):
            raise ValueError('La petición supera el límite disponible del enlace.')
        available_by_cat = {str(x['id']): x.get('available') for x in limits.get('categories') or []}
        allowed_cids = set(available_by_cat.keys())
        for cid, qty in quantities.items():
            if str(cid) != 'TOTAL' and allowed_cids and str(cid) not in allowed_cids:
                raise ValueError('La categoría seleccionada no está habilitada para este enlace.')
            if available_by_cat.get(str(cid)) is not None and _safe_int(qty) > _safe_int(available_by_cat.get(str(cid))):
                raise ValueError('La petición supera el límite disponible por categoría.')
        # Si estaba asignada y cambian las cantidades, liberar entradas y volver a SOLICITADAS.
        if (row.status or '') == 'ASIGNADAS' and quantities != current:
            for t in session_db.query(InvitationTicket).filter(InvitationTicket.assigned_request_id == row.id).all():
                t.previous_assignment_warning = f"Reeditada por el invitado; estaba asignada a {row.guest_name}."
                t.assigned_request_id = None
                t.assigned_label = None
                t.status = 'AVAILABLE'
                t.sent_at = None
                t.added_after_send = False
            row.status = 'SOLICITADAS'
            row.assigned_at = None
        row.guest_name = (request.form.get('guest_name') or '').strip() or row.guest_name
        row.guest_company = (request.form.get('guest_company') or '').strip()
        row.guest_title = (request.form.get('guest_title') or request.form.get('guest_company') or '').strip()
        row.guest_email = (request.form.get('guest_email') or '').strip()
        row.receiver_mode = (request.form.get('receiver_mode') or row.receiver_mode or 'GUEST').strip().upper()
        row.quantities_json = quantities
        row.note = (request.form.get('note') or '').strip()
        session_db.commit()
        flash('Petición actualizada.', 'success')
        return redirect(url_for('public_invitation_request_link', token=token))
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo actualizar la petición: {exc}', 'danger')
        return redirect(url_for('public_invitation_request_link', token=token))
    finally:
        session_db.close()


@app.post('/invitaciones/p/<token>/solicitudes/<request_id>/reenviar', endpoint='public_invitation_request_resend')
def public_invitation_request_resend(token, request_id):
    session_db = db()
    try:
        link = session_db.query(InvitationPublicLink).filter(InvitationPublicLink.token == token).first()
        row = session_db.get(InvitationRequest, to_uuid(request_id))
        if not link or not row or row.public_link_id != link.id:
            abort(404)
        if (row.status or '') not in {'ASIGNADAS', 'ENVIADAS', 'ENTREGADAS_MANO', 'DISPONIBLES_TAQUILLA', 'RECOGIDAS_TAQUILLA'}:
            flash('Esta petición todavía no tiene invitaciones asignadas.', 'warning')
            return redirect(url_for('public_invitation_request_link', token=token))
        concert = row.concert or session_db.get(Concert, row.concert_id)
        channel = (request.form.get('channel') or 'email').strip().lower()
        row.delivery_token = row.delivery_token or _invitation_token()

        def _mark_sent():
            # Vale para el primer envío (ASIGNADAS) y para el REENVÍO de una ampliada (ENVIADAS
            # parcial): etiqueta «Nueva» en las añadidas y marca SENT lo pendiente. Los estados
            # manuales (mano/taquilla) no se tocan.
            if (row.status or '') not in {'ASIGNADAS', 'ENVIADAS'}:
                return
            _now_rs = _now_madrid()
            _invitation_mark_sent_tickets(session_db, row, 'all', _now_rs)
            row.status = 'ENVIADAS'
            row.sent_at = _now_rs

        if channel in ('whatsapp', 'sms'):
            link_url = _external_url_for('public_invitation_delivery', kind='r', token=row.delivery_token)
            msg = _invitation_share_text(session_db, concert, row.guest_name, link_url)
            phone = _normalize_phone_intl(_invitation_guest_live_phone(session_db, row))
            if channel == 'whatsapp':
                url = ('https://wa.me/' + phone + '?text=' + quote_plus(msg)) if phone else ('https://wa.me/?text=' + quote_plus(msg))
            else:
                url = ('sms:' + ('+' + phone if phone else '') + '?&body=' + quote_plus(msg))
            _mark_sent()
            session_db.commit()
            return redirect(url)
        # Marcas/etiquetas ANTES de componer: el correo sale con las «Nueva»; si el SMTP falla,
        # el rollback lo deshace todo.
        _mark_sent()
        subject, html_body, text_body = _invitation_email_body(session_db, row, None)
        recipients = _dedupe_valid_email_addresses(re.split(r'[;,\s]+', request.form.get('extra_emails') or '') + _invitation_delivery_recipients(session_db, row))
        if not recipients:
            session_db.rollback()
            flash('No hay ningún email al que reenviar. Añade uno.', 'warning')
            return redirect(url_for('public_invitation_request_link', token=token))
        ok, err = _send_optional_email(recipients, subject, html_body, text_body=text_body, reply_to=_invitation_request_reply_to(session_db, row) or None)
        if ok:
            session_db.commit()
            flash('Invitaciones reenviadas por email.', 'success')
        else:
            session_db.rollback()
            flash(f'No se pudo enviar el email: {err or "SMTP no configurado"}', 'warning')
        return redirect(url_for('public_invitation_request_link', token=token))
    finally:
        session_db.close()


# ---------------------------------------------------------------------------
# AGENDA / CALENDARIO de actividades de artista (Inicio + pestaña "Agenda")
# ---------------------------------------------------------------------------
# Recolecta TODAS las actividades con fecha de un conjunto de artistas dentro de una ventana
# (por defecto las próximas 2 semanas) y las normaliza a un mismo formato para pintarlas en un
# calendario visual. Tipos: conciertos/festivales/eventos (Concert), acciones (CompanyAction),
# promoción en medios (MediaPromotionRecord) y lanzamientos (Album/Song). Los conciertos en
# BORRADOR/HABLADO solo se ven al completo con full_details (Contratación/dirección); para el
# resto aparecen como «Reserva — consultar con Contratación». En Inicio el color va por ARTISTA;
# en la ficha del artista, por TIPO de actividad.

AGENDA_PALETTE = [
    "#E33D48", "#007CA2", "#198754", "#6f42c1", "#fd7e14", "#d63384",
    "#20c997", "#0d6efd", "#b5179e", "#e07a5f", "#457b9d", "#9c6644",
]

AGENDA_KIND_ORDER = ["concierto", "festival", "evento", "lanzamiento", "accion", "promocion", "medios", "cumple", "otro", "bloqueo"]
AGENDA_KIND_META = {
    "concierto":   {"label": "Conciertos",      "icon": "fa-music",           "color": "#E33D48"},
    "festival":    {"label": "Festivales",      "icon": "fa-star",            "color": "#6f42c1"},
    "evento":      {"label": "Eventos / promo", "icon": "fa-bullhorn",        "color": "#fd7e14"},
    "lanzamiento": {"label": "Lanzamientos",    "icon": "fa-compact-disc",    "color": "#d63384"},
    "accion":      {"label": "Acciones",        "icon": "fa-clapperboard",    "color": "#007CA2"},
    "promocion":   {"label": "Promoción",       "icon": "fa-microphone-lines","color": "#8e44ad"},
    "medios":      {"label": "Medios",          "icon": "fa-broadcast-tower", "color": "#20c997"},
    "cumple":      {"label": "Cumpleaños",      "icon": "fa-cake-candles",    "color": "#e83e8c"},
    "otro":        {"label": "Otros",           "icon": "fa-thumbtack",       "color": "#0d6efd"},
    "bloqueo":     {"label": "Bloqueos",        "icon": "fa-ban",             "color": "#6c757d"},
}


def _agenda_status_meta(code: str | None) -> tuple[str, str]:
    """Devuelve (etiqueta, clase css) para el estado de un concierto/acción. Clase reutiliza los
    `status-*` de la ficha de artista (hablado/reservado/confirmado)."""
    code = (code or "").upper()
    table = {
        "CONFIRMADO": ("Confirmado", "confirmado"),
        "RESERVADO": ("Reserva", "reservado"),
        "RESERVA": ("Reserva", "reservado"),
        "HABLADO": ("Hablado", "hablado"),
        "BORRADOR": ("Borrador", "hablado"),
        "CERRADA": ("Cerrada", "confirmado"),
    }
    return table.get(code, ("", ""))


# Estados de actividad PREVIOS a la reserva: sus detalles solo los ven Contratación y dirección;
# el resto de la oficina (y los calendarios externos) ven «Reserva — consultar con Contratación»
# hasta que la actividad pase a RESERVADO o CONFIRMADO.
_CONCERT_PRIVATE_STATUSES = {"BORRADOR", "HABLADO"}


def _user_sees_unconfirmed_activities() -> bool:
    """¿El usuario actual ve al completo las actividades en BORRADOR/HABLADO? Solo CONTRATACIÓN
    (acceso a la sección) y DIRECCIÓN (role 10)."""
    try:
        state = _current_user_state()
        if int(state.get("role") or 0) == 10:
            return True
        return bool(has_access_key("contratacion", include_descendants=True))
    except Exception:
        return False


def _agenda_build(session_db, target_ids, start_date, end_date, today_value, full_details=False) -> dict:
    """Construye los datos del calendario de agenda.

    target_ids: iterable de UUIDs de artista a incluir, o None/vacío = TODOS los artistas.
    Devuelve dict serializable con `activities`, `artists` (con color), `kinds` presentes y fechas.

    full_details: True solo para CONTRATACIÓN y dirección (ver `_user_sees_unconfirmed_activities`):
    las actividades en BORRADOR/HABLADO se muestran al completo. Con False (resto de la oficina,
    calendarios públicos/iCal/CalDAV) esas fechas aparecen como «Reserva — consultar con
    Contratación», sin detalles ni enlace, hasta pasar a RESERVADO/CONFIRMADO.
    """
    target = {str(x) for x in target_ids} if target_ids else None

    def _match(ids):
        if target is None:
            return True
        return any(str(i) in target for i in ids if i)

    raw = []  # (artist_ids[list str], item dict sin colores)
    seen_artist_ids = set()

    # ---- Conciertos / festivales / eventos (Concert) ----
    concerts = (
        session_db.query(Concert)
        .options(joinedload(Concert.artist), joinedload(Concert.venue))
        .filter(Concert.date >= start_date, Concert.date <= end_date)
        .all()
    )
    for c in concerts:
        ids = []
        if c.artist_id:
            ids.append(str(c.artist_id))
        for x in (c.artist_ids or []):
            if x and str(x) not in ids:
                ids.append(str(x))
        if not _match(ids):
            continue
        at = (c.activity_type or "CONCIERTO").upper()
        kind = "concierto" if at in ("CONCIERTO", "") else ("festival" if at == "FESTIVAL" else "evento")
        primary = ids[0] if ids else ""
        seen_artist_ids.update(ids)
        # Actividades AÚN sin reservar/confirmar: solo Contratación/dirección las ven al completo;
        # para el resto la fecha queda bloqueada como «Reserva — consultar con Contratación».
        if (c.status or "").upper() in _CONCERT_PRIVATE_STATUSES and not full_details:
            raw.append((ids, {
                "kind": kind, "date": c.date.isoformat() if c.date else "",
                "title": "Reserva", "subtitle": "Consultar con Contratación",
                "artist_id": primary,
                "status_label": "", "status_class": "",
                "cover_url": "",
                "url": "",
            }))
            continue
        slabel, sclass = _agenda_status_meta(c.status)
        venue = c.venue
        municipality = (venue.municipality if venue else "") or ""
        sub = ""
        if venue:
            sub = (venue.name or "")
            if municipality:
                sub = f"{sub} · {municipality}" if sub else municipality
        # Sin nombre propio (festival_name): mostrar el municipio; si tampoco hay, el nombre del artista.
        title = c.festival_name or municipality or (c.artist.name if c.artist else "Concierto")
        raw.append((ids, {
            "kind": kind, "date": c.date.isoformat() if c.date else "",
            "title": title, "subtitle": sub,
            "artist_id": primary,
            "status_label": slabel, "status_class": sclass,
            "cover_url": "",
            "url": url_for("concert_detail_view", cid=c.id),
        }))

    # ---- Acciones de empresa / marketing (CompanyAction) ----
    actions = (
        session_db.query(CompanyAction)
        .options(joinedload(CompanyAction.venue))
        .filter(CompanyAction.start_date != None)  # noqa: E711
        .filter(CompanyAction.start_date >= start_date, CompanyAction.start_date <= end_date)
        .filter(func.upper(func.coalesce(CompanyAction.status, "")).in_(["RESERVA", "CONFIRMADO", "CERRADA"]))
        .all()
    )
    for a in actions:
        ids = [str(x) for x in (a.artist_ids or []) if x]
        if not _match(ids):
            continue
        slabel, sclass = _agenda_status_meta(a.status)
        a_muni = (a.venue.municipality if a.venue is not None else "") or ""
        sub = ACTION_TYPE_LABELS.get((a.action_type or "").upper(), "")
        if a.venue is not None and getattr(a.venue, "name", None):
            sub = f"{sub} · {a.venue.name}" if sub else a.venue.name
        seen_artist_ids.update(ids)
        raw.append((ids, {
            "kind": "accion", "date": a.start_date.isoformat(),
            "title": a.title or a_muni or "Acción", "subtitle": sub,
            "artist_id": ids[0] if ids else "",
            "status_label": slabel, "status_class": sclass,
            "cover_url": "",
            "icon_override": ACTION_TYPE_ICONS.get((a.action_type or "").upper(), ""),
            "url": url_for("action_detail_view", action_id=a.id),
        }))

    # ---- Promoción en medios (MediaPromotionRecord) ----
    media_rows = (
        session_db.query(MediaPromotionRecord)
        .options(joinedload(MediaPromotionRecord.media), joinedload(MediaPromotionRecord.artist))
        .filter(MediaPromotionRecord.promoted_at >= start_date, MediaPromotionRecord.promoted_at <= end_date)
        .all()
    )
    for m in media_rows:
        ids = [str(m.artist_id)] if m.artist_id else []
        if not _match(ids):
            continue
        media_name = m.media.name if m.media else ""
        title = m.promotion_title or m.program_name or media_name or "Promoción en medios"
        sub_bits = [b for b in [media_name if title != media_name else "", m.program_name if m.program_name and m.program_name != title else ""] if b]
        if m.promotion_id:
            url = url_for("promotion_detail_view", promotion_id=m.promotion_id)
        else:
            url = url_for("media_outlet_detail_view", media_id=m.media_id)
        seen_artist_ids.update(ids)
        raw.append((ids, {
            "kind": "medios", "date": m.promoted_at.isoformat(),
            "title": title, "subtitle": " · ".join(sub_bits),
            "artist_id": ids[0] if ids else "",
            "status_label": "", "status_class": "",
            "cover_url": "",
            "url": url,
        }))

    # ---- Promoción de prensa (entrevistas y planes) ----
    # Un PLAN sale como UNA franja de principio a fin (es una tanda de promoción, no N eventos
    # sueltos); una promoción PUNTUAL sale como su entrevista, en su día.
    # ⚠️ En BORRADOR no sale: una promoción está en borrador mientras es una petición o una idea, y
    # lo que no está hablado/confirmado no puede ocupar un día en el calendario de nadie.
    promo_rows = (
        session_db.query(Promotion)
        .filter(func.upper(func.coalesce(Promotion.kind, 'MARKETING')) == PROMO_KIND)
        .filter(func.upper(func.coalesce(Promotion.status, 'ACTIVE')) == 'ACTIVE')
        .filter(func.upper(func.coalesce(Promotion.promo_status, 'BORRADOR')).notin_(['BORRADOR', 'CANCELADO']))
        .all()
    )
    promo_ids = [p.id for p in promo_rows]
    promo_activities = defaultdict(list)
    if promo_ids:
        for act in (session_db.query(PromotionActivity)
                    .options(joinedload(PromotionActivity.media))
                    .filter(PromotionActivity.promotion_id.in_(promo_ids))
                    .filter(func.upper(func.coalesce(PromotionActivity.activity_kind, '')) == 'PROMOCION')
                    .filter(PromotionActivity.activity_date >= start_date,
                            PromotionActivity.activity_date <= end_date)
                    .all()):
            promo_activities[str(act.promotion_id)].append(act)
    for promo in promo_rows:
        ids = _promotion_normalized_artist_ids(getattr(promo, "artist_ids", None) or [])
        if not _match(ids):
            continue
        acts = promo_activities.get(str(promo.id)) or []
        is_plan = (getattr(promo, "request_kind", None) or "PLAN").strip().upper() == "PLAN"
        slabel, sclass = _agenda_status_meta(getattr(promo, "promo_status", None))
        snap = dict(getattr(promo, "snapshot", None) or {})
        url = url_for("promo_detail_view", promotion_id=promo.id)
        if is_plan:
            starts_on = getattr(promo, "starts_on", None)
            ends_on = getattr(promo, "ends_on", None) or starts_on
            if not starts_on or starts_on > end_date or (ends_on and ends_on < start_date):
                continue
            seen_artist_ids.update(ids)
            raw.append((ids, {
                "kind": "promocion", "date": starts_on.isoformat(),
                "end_date": (ends_on or starts_on).isoformat(),
                "title": _promo_title(promo),
                "subtitle": " · ".join([x for x in [(snap.get("title") or "").strip(),
                                                    (f"{len(acts)} promociones" if acts else "")] if x]),
                "artist_id": ids[0] if ids else "",
                "status_label": slabel, "status_class": sclass,
                "cover_url": (snap.get("cover_url") or ""),
                "url": url,
            }))
            continue
        for act in acts:
            seen_artist_ids.update(ids)
            row = _promo_activity_row(act)
            alabel, aclass = _agenda_status_meta(row["status"])
            raw.append((ids, {
                "kind": "promocion", "date": act.activity_date.isoformat(),
                "title": _promo_activity_title(act) or _promo_title(promo),
                "subtitle": " · ".join([x for x in [row["time_label"] if row["time_label"] != "Sin hora" else "",
                                                    row["modality_label"]] if x]),
                "artist_id": ids[0] if ids else "",
                "status_label": alabel, "status_class": aclass,
                "cover_url": (row["media_logo_url"] or snap.get("cover_url") or ""),
                "url": url,
            }))

    # ---- Lanzamientos: Álbumes ----
    albums = (
        session_db.query(Album)
        .options(joinedload(Album.artist))
        .filter(Album.release_date >= start_date, Album.release_date <= end_date)
        .all()
    )
    for al in albums:
        ids = [str(al.artist_id)] if al.artist_id else []
        if not _match(ids):
            continue
        seen_artist_ids.update(ids)
        raw.append((ids, {
            "kind": "lanzamiento", "date": al.release_date.isoformat(),
            "title": al.title or "Lanzamiento",
            "subtitle": ("EP" if (al.album_type or "").upper() == "EP" else "Álbum"),
            "artist_id": ids[0] if ids else "",
            "status_label": "", "status_class": "",
            "cover_url": al.cover_url or "",
            "url": url_for("discografica_album_detail", album_id=al.id),
        }))

    # ---- Lanzamientos: Canciones ----
    songs = (
        session_db.query(Song)
        .options(joinedload(Song.artists))
        .filter(Song.release_date >= start_date, Song.release_date <= end_date)
        .all()
    )
    for sg in songs:
        ids = [str(a.id) for a in (sg.artists or [])]
        if not _match(ids):
            continue
        seen_artist_ids.update(ids)
        raw.append((ids, {
            "kind": "lanzamiento", "date": sg.release_date.isoformat(),
            "title": sg.title or "Lanzamiento", "subtitle": "Single / canción",
            "artist_id": ids[0] if ids else "",
            "status_label": "", "status_class": "",
            "cover_url": sg.cover_url or "",
            "url": url_for("discografica_song_detail", song_id=sg.id),
        }))

    # ---- Bloqueos y notas libres (ArtistAgendaItem), expandidos por día dentro de la ventana ----
    agenda_q = (
        session_db.query(ArtistAgendaItem)
        .filter(ArtistAgendaItem.start_date <= end_date, ArtistAgendaItem.end_date >= start_date)
    )
    if target is not None:
        agenda_q = agenda_q.filter(ArtistAgendaItem.artist_id.in_([to_uuid(x) for x in target if x]))
    for it in agenda_q.all():
        aid = str(it.artist_id)
        kind = "bloqueo" if (it.kind or "").upper() == "BLOCK" else "otro"
        seen_artist_ids.add(aid)
        # UN solo evento con rango (date..end_date), recortado a la ventana: el front pinta una FRANJA
        # CONTINUA que conecta todos los días (antes se expandía por día y salía un chip por día).
        _end = it.end_date or it.start_date
        d0 = it.start_date if it.start_date > start_date else start_date
        d1 = _end if _end < end_date else end_date
        if d1 < d0:
            d1 = d0
        raw.append(([aid], {
            "kind": kind, "date": d0.isoformat(), "end_date": d1.isoformat(),
            "title": it.title or ("Bloqueado" if kind == "bloqueo" else "Nota"),
            "subtitle": (it.note or "") if kind == "otro" else "",
            "artist_id": aid,
            "status_label": "", "status_class": "",
            "cover_url": "", "item_id": str(it.id), "url": "",
        }))

    # ---- Cumpleaños (artista individual -> Artist.birth_date; grupo -> cada miembro) ----
    def _birthday_occurrences(bdate):
        out = []
        for yr in range(start_date.year, end_date.year + 1):
            try:
                d = date(yr, bdate.month, bdate.day)
            except ValueError:
                d = date(yr, 2, 28)  # 29-feb en años no bisiestos
            if start_date <= d <= end_date:
                out.append(d)
        return out

    bday_q = session_db.query(Artist).options(joinedload(Artist.people))
    if target is not None:
        bday_q = bday_q.filter(Artist.id.in_([to_uuid(x) for x in target if x]))
    for art in bday_q.all():
        aid = str(art.id)
        url_art = url_for("artist_detail_view", artist_id=art.id, tab="agenda")
        people = []
        if getattr(art, "is_group", False):
            for p in (art.people or []):
                if p.birth_date:
                    people.append((f"{p.first_name} {p.last_name}".strip(), p.birth_date, art.name))
        elif getattr(art, "birth_date", None):
            people.append((art.name, art.birth_date, ""))
        for pname, bdate, sub in people:
            for d in _birthday_occurrences(bdate):
                seen_artist_ids.add(aid)
                raw.append(([aid], {
                    "kind": "cumple", "date": d.isoformat(),
                    "title": pname or "Cumpleaños", "subtitle": sub,
                    "artist_id": aid,
                    "status_label": "", "status_class": "",
                    "cover_url": "", "url": url_art,
                }))

    # ---- Mapa de artistas (nombre + foto) para colorear/etiquetar ----
    artist_map = {}
    if seen_artist_ids:
        for a in session_db.query(Artist).filter(Artist.id.in_([to_uuid(x) for x in seen_artist_ids if x])).all():
            artist_map[str(a.id)] = {"id": str(a.id), "name": a.name or "—", "photo_url": a.photo_url or ""}

    # Artistas presentes, ordenados por nombre, con color de paleta
    present = [artist_map[a] for a in seen_artist_ids if a in artist_map]
    present.sort(key=lambda x: (x["name"] or "").lower())
    artist_color = {}
    artists_out = []
    for i, a in enumerate(present):
        color = AGENDA_PALETTE[i % len(AGENDA_PALETTE)]
        artist_color[a["id"]] = color
        artists_out.append({**a, "color": color})

    # Tipos presentes (en orden canónico)
    present_kinds = {it["kind"] for _ids, it in raw}
    kinds_out = [
        {"key": k, "label": AGENDA_KIND_META[k]["label"], "icon": AGENDA_KIND_META[k]["icon"], "color": AGENDA_KIND_META[k]["color"]}
        for k in AGENDA_KIND_ORDER if k in present_kinds
    ]

    # Finaliza actividades con colores y nombre de artista
    activities = []
    for ids, it in raw:
        pid = it.get("artist_id") or ""
        meta = AGENDA_KIND_META.get(it["kind"], {})
        names = [artist_map[i]["name"] for i in ids if i in artist_map]
        # Todos los artistas de la actividad (para pintar varias fotos cuando hay más de uno).
        artist_photos = [
            {
                "id": i,
                "name": artist_map[i]["name"],
                "photo_url": artist_map[i].get("photo_url", ""),
                "color": artist_color.get(i, "#6c757d"),
            }
            for i in ids if i in artist_map
        ]
        activities.append({
            **it,
            "artist_ids": ids,
            "icon": it.pop("icon_override", "") or meta.get("icon", "fa-circle"),
            "artist_name": ", ".join(names) if names else (it.get("title") or ""),
            "artist_photo": artist_map.get(pid, {}).get("photo_url", ""),
            "artist_photos": artist_photos,
            "artist_color": artist_color.get(pid, "#6c757d"),
            "kind_color": meta.get("color", "#6c757d"),
            "kind_label": meta.get("label", ""),
        })
    activities.sort(key=lambda x: (x["date"], x["kind"]))

    return {
        "activities": activities,
        "artists": artists_out,
        "kinds": kinds_out,
        "today": today_value.isoformat(),
        "start": start_date.isoformat(),
        "end": end_date.isoformat(),
    }


def _agenda_window(days_ahead: int = 20):
    """Ventana INICIAL de la agenda de Inicio: 3 semanas alineadas a lunes (la semana actual y las
    dos siguientes). Las flechas del calendario cargan más ventanas bajo demanda (`home_agenda_data`),
    sin límite temporal. Devuelve (today, start, end)."""
    today = today_local()
    start = today - timedelta(days=today.weekday())
    return today, start, start + timedelta(days=days_ahead)


def _home_agenda_target_ids() -> list[str] | None:
    """Artistas cuya agenda ve el usuario en Inicio: sus asignados, o None (= todos) si no tiene
    ninguno o es dirección."""
    state = _current_user_state()
    role = _safe_int(state.get("role"))
    assigned = [str(x) for x in (state.get("assigned_artist_ids") or []) if x]
    return None if (role == 10 or not assigned) else assigned


def _home_agenda() -> dict | None:
    """Datos del calendario de Inicio para el usuario actual: actividades de SUS artistas asignados
    (o de todos si no tiene ninguno asignado o es dirección). Color por artista."""
    session_db = db()
    try:
        today, start, end = _agenda_window()
        return _agenda_build(session_db, _home_agenda_target_ids(), start, end, today,
                             full_details=_user_sees_unconfirmed_activities())
    except Exception:
        return None
    finally:
        session_db.close()


@app.get("/agenda/inicio.json", endpoint="home_agenda_data")
@admin_required
def home_agenda_data():
    """Ventana arbitraria de agenda (navegación con flechas SIN límite temporal): la de Inicio
    (artistas del usuario) o, con ?artist_id, la de la pestaña Agenda de un artista concreto.
    Máx. ~6 semanas por petición; el JS pide ventana a ventana y las cachea. Los colores por
    artista los estabiliza el cliente."""
    try:
        start = parse_date(request.args.get("start") or "")
        end = parse_date(request.args.get("end") or "")
    except Exception:
        return jsonify({"error": "Rango inválido."}), 400
    if end < start or (end - start).days > 42:
        return jsonify({"error": "Rango inválido."}), 400
    session_db = db()
    try:
        target_ids = _home_agenda_target_ids()
        artist_raw = (request.args.get("artist_id") or "").strip()
        if artist_raw:
            artist = session_db.get(Artist, _safe_uuid(artist_raw))
            if not artist:
                return jsonify({"error": "Artista no encontrado."}), 404
            target_ids = [str(artist.id)]
        return jsonify(_agenda_build(session_db, target_ids, start, end, today_local(),
                                     full_details=_user_sees_unconfirmed_activities()))
    finally:
        session_db.close()


def _agenda_active_artist_ids(session_db) -> set:
    """IDs (str) de artistas «activos»: con lanzamiento (álbum/canción) o actividad (concierto/acción)
    próxima o de los últimos 10 días. Para mostrarlos primero en el selector del botón + de la agenda."""
    lo = date.today() - timedelta(days=10)
    ids = set()
    try:
        for a in session_db.query(Album.artist_id).filter(Album.release_date.isnot(None), Album.release_date >= lo).all():
            if a[0]:
                ids.add(str(a[0]))
        for c in session_db.query(Concert.artist_id).filter(Concert.date.isnot(None), Concert.date >= lo).limit(600).all():
            if c[0]:
                ids.add(str(c[0]))
        for a in session_db.query(CompanyAction).filter(CompanyAction.start_date.isnot(None), CompanyAction.start_date >= lo).limit(600).all():
            for x in (a.artist_ids or []):
                if x:
                    ids.add(str(x))
        for row in session_db.query(SongArtist.artist_id).join(Song, Song.id == SongArtist.song_id).filter(Song.release_date.isnot(None), Song.release_date >= lo).limit(1000).all():
            if row[0]:
                ids.add(str(row[0]))
    except Exception:
        pass
    return ids


def _agenda_artist_options() -> list[dict]:
    """Artistas para el selector del botón + en Inicio: los asignados al usuario (o todos si no tiene
    ninguno o es dirección). Cada uno marcado `active` (con lanzamiento/actividad próxima o reciente)
    para mostrarlos primero; el resto quedan tras «Ver más artistas»."""
    state = _current_user_state()
    role = _safe_int(state.get("role"))
    assigned = [str(x) for x in (state.get("assigned_artist_ids") or []) if x]
    session_db = db()
    try:
        q = session_db.query(Artist).order_by(Artist.name.asc())
        if not (role == 10 or not assigned):
            q = q.filter(Artist.id.in_([to_uuid(x) for x in assigned]))
        active_ids = _agenda_active_artist_ids(session_db)
        out = []
        for a in q.all():
            activo = str(a.id) in active_ids
            # Los EVENTOS salen en la agenda igual que un artista (su espejo lleva el nombre y el logo
            # del evento), pero SOLO cuando tienen cosas activas: un evento sin actividades no se
            # ofrece como si fuera un artista más.
            if getattr(a, "event_id", None) and not activo:
                continue
            out.append({"id": str(a.id), "name": a.name or "—", "photo_url": a.photo_url or "",
                        "active": activo, "is_event": bool(getattr(a, "event_id", None)),
                        "event_id": (str(a.event_id) if getattr(a, "event_id", None) else "")})
        return out
    except Exception:
        return []
    finally:
        session_db.close()


def _agenda_redirect_back():
    """Vuelve a donde se pidió el alta (Inicio o la agenda del artista)."""
    ref = request.form.get("next") or request.referrer or ""
    if ref.startswith(request.host_url) or ref.startswith("/"):
        return redirect(ref)
    return redirect(url_for("home"))


