# ----------------------- Suscripción de calendario (iCal) del artista -----------------------

def _artist_calendar_links(session_db, artist_id, only_active: bool = True):
    q = session_db.query(ArtistCalendarLink).filter(ArtistCalendarLink.artist_id == artist_id)
    if only_active:
        q = q.filter(ArtistCalendarLink.status == "ACTIVE")
    return q.order_by(ArtistCalendarLink.created_at.desc()).all()


def _artist_calendar_subscribe_url(token: str) -> str:
    """URL pública del feed .ics (https). Para 'suscribirse' se usa el equivalente webcal://."""
    return _external_url_for("public_artist_calendar_ics", token=token)


def _parse_agenda_kinds(values) -> list[str]:
    """Tipos de actividad válidos de un formulario. Vacío (o todos marcados) = sin filtro."""
    picked = [(v or "").strip().lower() for v in (values or []) if (v or "").strip()]
    picked = [k for k in AGENDA_KIND_ORDER if k in picked]
    return [] if len(picked) == len(AGENDA_KIND_ORDER) else picked


def _agenda_filter_kinds(agenda_data: dict, kinds) -> dict:
    """Deja en la agenda solo los tipos elegidos para ese enlace. Lista vacía = todo."""
    allowed = [k for k in (kinds or []) if k in AGENDA_KIND_ORDER]
    if not allowed:
        return agenda_data
    allowed_set = set(allowed)
    data = dict(agenda_data or {})
    data["activities"] = [it for it in (data.get("activities") or []) if it.get("kind") in allowed_set]
    data["kinds"] = [k for k in (data.get("kinds") or []) if k.get("key") in allowed_set]
    return data


def _agenda_kinds_label(kinds) -> str:
    """«Todas las actividades» o la lista de las elegidas, para enseñarlo junto al enlace."""
    allowed = [k for k in (kinds or []) if k in AGENDA_KIND_ORDER]
    if not allowed:
        return "Todas las actividades"
    return " · ".join(AGENDA_KIND_META[k]["label"] for k in AGENDA_KIND_ORDER if k in allowed)


def _ics_escape(value) -> str:
    s = str(value or "")
    s = s.replace("\\", "\\\\").replace(";", "\\;").replace(",", "\\,")
    s = s.replace("\r\n", "\n").replace("\r", "\n").replace("\n", "\\n")
    return s


def _ics_fold(line: str) -> str:
    """Plegado RFC5545: líneas <= 75 octetos, continuación con CRLF + espacio."""
    if len(line.encode("utf-8")) <= 75:
        return line
    out, chunk = [], b""
    for ch in line:
        b = ch.encode("utf-8")
        if len(chunk) + len(b) > 73:
            out.append(chunk.decode("utf-8"))
            chunk = b
        else:
            chunk += b
    if chunk:
        out.append(chunk.decode("utf-8"))
    return "\r\n ".join(out)


def _ics_now_utc() -> str:
    import time
    return time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())


def _artist_calendar_ics(agenda_data: dict, artist) -> str:
    """Genera el calendario iCal (.ics) del artista a partir de _agenda_build. Eventos de día completo.
    SUMMARY = 'tipo · nombre' (o municipio si no hay nombre); DESCRIPTION = resto de info/notas."""
    dtstamp = _ics_now_utc()
    lines = [
        "BEGIN:VCALENDAR",
        "VERSION:2.0",
        "PRODID:-//33 Producciones//Agenda//ES",
        "CALSCALE:GREGORIAN",
        "METHOD:PUBLISH",
        f"X-WR-CALNAME:{_ics_escape('Agenda · ' + (getattr(artist, 'name', '') or ''))}",
        "X-PUBLISHED-TTL:PT1H",
        "REFRESH-INTERVAL;VALUE=DURATION:PT1H",
    ]
    for idx, it in enumerate((agenda_data or {}).get("activities") or []):
        raw_date = it.get("date") or ""
        d = raw_date.replace("-", "")
        if len(d) != 8:
            continue
        # DTEND desde end_date (rango multi-día de bloqueos/notas); si no hay, un día. Antes se
        # ignoraba end_date y una franja de varios días se colapsaba a su primer día en el .ics.
        try:
            raw_end = it.get("end_date") or raw_date
            dtend = (date.fromisoformat(raw_end) + timedelta(days=1)).isoformat().replace("-", "")
        except (ValueError, TypeError):
            continue
        kind_label = (it.get("kind_label") or it.get("kind") or "Evento").strip()
        title = (it.get("title") or "").strip()
        subtitle = (it.get("subtitle") or "").strip()
        name = title or subtitle  # nombre del evento o, si no hay, municipio
        summary = f"{kind_label} · {name}" if name else kind_label
        desc_parts = []
        if title and subtitle:
            desc_parts.append(subtitle)
        if it.get("status_label"):
            desc_parts.append(it["status_label"])
        if it.get("note"):
            desc_parts.append(str(it["note"]).strip())
        if it.get("artist_name"):
            desc_parts.append(it["artist_name"])
        uid = f"{it.get('kind', 'x')}-{it.get('item_id') or it.get('url') or idx}-{d}@33producciones"
        lines += [
            "BEGIN:VEVENT",
            f"UID:{_ics_escape(uid)}",
            f"DTSTAMP:{dtstamp}",
            f"DTSTART;VALUE=DATE:{d}",
            f"DTEND;VALUE=DATE:{dtend}",
            f"SUMMARY:{_ics_escape(summary)}",
        ]
        if subtitle:
            lines.append(f"LOCATION:{_ics_escape(subtitle)}")
        if desc_parts:
            lines.append(f"DESCRIPTION:{_ics_escape(' · '.join(p for p in desc_parts if p))}")
        lines.append("END:VEVENT")
    lines.append("END:VCALENDAR")
    return "\r\n".join(_ics_fold(ln) for ln in lines) + "\r\n"


@app.get("/calendario-artista/<token>.ics", endpoint="public_artist_calendar_ics")
def public_artist_calendar_ics(token):
    """Feed público iCal de la agenda de un artista (solo lectura). Para suscribir desde iPhone/Android."""
    session_db = db()
    try:
        link = (
            session_db.query(ArtistCalendarLink)
            .filter(ArtistCalendarLink.token == token, ArtistCalendarLink.status == "ACTIVE")
            .first()
        )
        if not link:
            abort(404)
        artist = session_db.get(Artist, link.artist_id)
        if not artist:
            abort(404)
        today = today_local()
        agenda_data = _agenda_build(session_db, [str(artist.id)], today - timedelta(weeks=13), today + timedelta(weeks=78), today)
        # El enlace puede estar limitado a ciertos tipos (p. ej. solo conciertos).
        agenda_data = _agenda_filter_kinds(agenda_data, link.kinds)
        ics = _artist_calendar_ics(agenda_data, artist)
    finally:
        session_db.close()
    resp = Response(ics, mimetype="text/calendar")
    resp.headers["Content-Type"] = "text/calendar; charset=utf-8"
    resp.headers["Content-Disposition"] = f'inline; filename="agenda-{token}.ics"'
    resp.headers["Cache-Control"] = "no-cache, max-age=0"
    return resp


@app.get("/calendario-artista/<token>", endpoint="public_artist_calendar_view")
def public_artist_calendar_view(token):
    """Página pública (la que se comparte) con la guía visual para suscribirse al calendario."""
    session_db = db()
    try:
        link = (
            session_db.query(ArtistCalendarLink)
            .filter(ArtistCalendarLink.token == token, ArtistCalendarLink.status == "ACTIVE")
            .first()
        )
        if not link:
            abort(404)
        artist = session_db.get(Artist, link.artist_id)
        if not artist:
            abort(404)
        ics_url = _external_url_for("public_artist_calendar_ics", token=token)
        webcal_url = re.sub(r'^https?://', 'webcal://', ics_url)
        today = today_local()
        agenda = _agenda_build(session_db, [str(artist.id)], today, today + timedelta(weeks=26), today)
        # La vista previa tiene que enseñar lo mismo que el feed: si el enlace está limitado a
        # ciertos tipos, aquí tampoco se ve el resto.
        agenda = _agenda_filter_kinds(agenda, link.kinds)
        kinds_label = _agenda_kinds_label(link.kinds)
        kinds_all = not [k for k in (link.kinds or []) if k in AGENDA_KIND_ORDER]
        upcoming = sorted((agenda.get("activities") or []), key=lambda x: x.get("date") or "")[:6]
    finally:
        session_db.close()
    return render_template("public_artist_calendar.html", artist=artist, ics_url=ics_url, webcal_url=webcal_url,
                           upcoming=upcoming, kinds_label=kinds_label, kinds_all=kinds_all)


@app.get("/caldav/guia", endpoint="public_caldav_guide")
def public_caldav_guide():
    """Guía visual para que los usuarios de la app añadan su cuenta de calendario (CalDAV)."""
    # El servidor CalDAV vive en un host SIN Cloudflare (ver DEPLOY_CALDAV.md): se indica con
    # CALDAV_PUBLIC_HOST (p. ej. "caldav.33producciones.com"). Sin esa variable se cae al dominio
    # actual, que en Render NO acepta PROPFIND (la guía seguiría mostrando el host equivocado).
    server = (os.getenv("EXTERNAL_BASE_URL") or request.url_root).rstrip("/").split("//")[-1]
    caldav_host = (os.getenv("CALDAV_PUBLIC_HOST") or "").strip().rstrip("/").split("//")[-1] or server
    return render_template("caldav_guide.html", caldav_server=caldav_host)


